window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["国家发展改革委"] = {"biaozhunshigongzhaobiaozigeyushenwenjianhebiaozhun1191cd-2":[{"i":1,"n":"第一条","txt":"为了规范施工招标资格预审文件、招标文件编制活动，提高资格预审文件、招标文件编制质量，促进招标投标活动的公开、公平和公正，国家发展和改革委员会、财政部、建设部、铁道部、交通部、信息产业部、水利部、民用航空总局、广播电影电视总局联合编制了《标准施工招标资格预审文件》和《标准施工招标文件》（以下如无特别说明，统一简称为《标准文件》）。"},{"i":2,"n":"第二条","txt":"本《标准文件》适用于依法必须招标的工程建设项目。"},{"i":3,"n":"第三条","txt":"国务院有关行业主管部门可根据《标准施工招标文件》并结合本行业施工招标特点和管理需要，编制行业标准施工招标文件。行业标准施工招标文件重点对“专用合同条款”、“工程量清单”、“图纸”、“技术标准和要求”作出具体规定。"},{"i":4,"n":"第四条","txt":"招标人应根据《标准文件》和行业标准施工招标文件（如有），结合招标项目具体特点和实际需要，按照公开、公平、公正和诚实信用原则编写施工招标资格预审文件或施工招标文件，并按规定执行政府采购政策。"},{"i":5,"n":"第五条","txt":"行业标准施工招标文件和招标人编制的施工招标资格预审文件、施工招标文件，应不加修改地引用《标准施工招标资格预审文件》中的“申请人须知”（申请人须知前附表除外）、“资格审查办法”（资格审查办法前附表除外），以及《标准施工招标文件》中的“投标人须知”（投标人须知前附表和其他附表除外）、“评标办法”（评标办法前附表除外）、“通用合同条款”。 《标准文件》中的其他内容，供招标人参考。"},{"i":6,"n":"第六条","txt":"行业标准施工招标文件中的“专用合同条款”可对《标准施工招标文件》中的“通用合同条款”进行补充、细化，除“通用合同条款”明确“专用合同条款”可作出不同约定外，补充和细化的内容不得与“通用合同条款”强制性规定相抵触，否则抵触内容无效。"},{"i":7,"n":"第七条","txt":"“申请人须知前附表”和“投标人须知前附表”用于进一步明确“申请人须知”和“投标人须知”正文中的未尽事宜，招标人应结合招标项目具体特点和实际需要编制和填写，但不得与“申请人须知”和“投标人须知”正文内容相抵触，否则抵触内容无效。"},{"i":8,"n":"第八条","txt":"“资格审查办法前附表”和“评标办法前附表”用于明确资格审查和评标的方法、因素、标准和程序。招标人应根据招标项目具体特点和实际需要，详细列明全部审查或评审因素、标准，没有列明的因素和标准不得作为资格审查或评标的依据。"},{"i":9,"n":"第九条","txt":"招标人编制招标文件中的“专用合同条款”可根据招标项目的具体特点和实际需要，对《标准施工招标文件》中的“通用合同条款”进行补充、细化和修改，但不得违反法律、行政法规的强制性规定和平等、自愿、公平和诚实信用原则。"},{"i":10,"n":"第十条","txt":"招标人编制的资格预审文件和招标文件不得违反公开、公平、公正、平等、自愿和诚实信用原则。"},{"i":11,"n":"第十一条","txt":"国务院有关部门和地方人民政府有关部门应加强对招标人使用《标准文件》的指导和监督检查，及时总结经验和发现问题。"},{"i":12,"n":"第十二条","txt":"需要就如何适用《标准文件》中不加修改地引用的内容作出解释的，按照国务院和地方人民政府部门职责分工，分别由有关部门负责。"},{"i":13,"n":"第十三条","txt":"因出现新情况，需要对《标准文件》中不加修改地引用的内容作出解释或调整的，由国家发展和改革委员会会同国务院有关部门作出解释或调整。该解释和调整与《标准文件》具有同等效力。"},{"i":14,"n":"第十四条","txt":"《标准文件》作为本规定的附件，与本规定同时发布施行。"}],"biaozhunshigongzhaobiaozigeyushenwenjianhebiaozhun1191cd":[{"i":1,"n":"第一条","txt":"为了规范施工招标资格预审文件、招标文件编制活动，提高资格预审文件、招标文件编制质量，促进招标投标活动的公开、公平和公正，国家发展和改革委员会、财政部、建设部、铁道部、交通部、信息产业部、水利部、民用航空总局、广播电影电视总局联合编制了《标准施工招标资格预审文件》和《标准施工招标文件》(以下如无特别说明，统一简称为《标准文件》)。"},{"i":2,"n":"第二条","txt":"本《标准文件》适用于依法必须招标的工程建设项目。"},{"i":3,"n":"第三条","txt":"国务院有关行业主管部门可根据《标准施工招标文件》并结合本行业施工招标特点和管理需要，编制行业标准施工招标文件。行业标准施工招标文件重点对“专用合同条款”、“工程量清单”、“图纸”、“技术标准和要求”作出具体规定。"},{"i":4,"n":"第四条","txt":"招标人应根据《标准文件》和行业标准施工招标文件(如有)，结合招标项目具体特点和实际需要，按照公开、公平、公正和诚实信用原则编写施工招标资格预审文件或施工招标文件，并按规定执行政府采购政策。"},{"i":5,"n":"第五条","txt":"行业标准施工招标文件和招标人编制的施工招标资格预审文件、施工招标文件，应不加修改地引用《标准施工招标资格预审文件》中的“申请人须知”(申请人须知前附表除外)、“资格审查办法”(资格审查办法前附表除外)，以及《标准施工招标文件》中的“投标人须知”(投标人须知前附表和其他附表除外)、“评标办法”(评标办法前附表除外)、“通用合同条款”。 《标准文件》中的其他内容，供招标人参考。"},{"i":6,"n":"第六条","txt":"行业标准施工招标文件中的“专用合同条款”可对《标准施工招标文件》中的“通用合同条款”进行补充、细化，除“通用合同条款”明确“专用合同条款”可作出不同约定外，补充和细化的内容不得与“通用合同条款”强制性规定相抵触，否则抵触内容无效。"},{"i":7,"n":"第七条","txt":"“申请人须知前附表”和“投标人须知前附表”用于进一步明确“申请人须知”和“投标人须知”正文中的未尽事宜，招标人应结合招标项目具体特点和实际需要编制和填写，但不得与“申请人须知”和“投标人须知”正文内容相抵触，否则抵触内容无效。"},{"i":8,"n":"第八条","txt":"“资格审查办法前附表”和“评标办法前附表”用于明确资格审查和评标的方法、因素、标准和程序。招标人应根据招标项目具体特点和实际需要，详细列明全部审查或评审因素、标准，没有列明的因素和标准不得作为资格审查或评标的依据。"},{"i":9,"n":"第九条","txt":"招标人编制招标文件中的“专用合同条款”可根据招标项目的具体特点和实际需要，对《标准施工招标文件》中的“通用合同条款”进行补充、细化和修改，但不得违反法律、行政法规的强制性规定和平等、自愿、公平和诚实信用原则。"},{"i":10,"n":"第十条","txt":"招标人编制的资格预审文件和招标文件不得违反公开、公平、公正、平等、自愿和诚实信用原则。"},{"i":11,"n":"第十一条","txt":"国务院有关部门和地方人民政府有关部门应加强对招标人使用《标准文件》的指导和监督检查，及时总结经验和发现问题。"},{"i":12,"n":"第十二条","txt":"需要就如何适用《标准文件》中不加修改地引用的内容作出解释的，按照国务院和地方人民政府部门职责分工，分别由有关部门负责。"},{"i":13,"n":"第十三条","txt":"因出现新情况，需要对《标准文件》中不加修改地引用的内容作出解释或调整的，由国家发展和改革委员会会同国务院有关部门作出解释或调整。该解释和调整与《标准文件》具有同等效力。"},{"i":14,"n":"第十四条","txt":"《标准文件》作为本规定的附件，与本规定同时发布施行。"}],"zhongyangchubeimianguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强中央储备棉管理，确保中央储备棉数量真实、质量良好和储存安全，有效发挥中央储备棉在国家宏观调控中的作用，制定本办法。"},{"i":2,"n":"第二条","txt":"中央储备棉的管理、监督检查等适用本办法。"},{"i":3,"n":"第三条","txt":"中央储备棉的轮换、收储、动用（含销售，下同）应当服从服务于棉花市场调控、应急保供、库存更新等需要。"},{"i":4,"n":"第四条","txt":"国家发展改革委负责研究拟订中央储备棉规划和总量计划，会同相关部门提出中央储备棉轮换、收储、动用等调控措施意见，报国务院批准后组织实施。"},{"i":5,"n":"第五条","txt":"国家粮食和储备局负责中央储备棉行政管理，会同相关部门下达中央储备棉轮换、收储、动用计划，对中央储备棉数量、储存安全及计划执行情况进行监督检查。"},{"i":6,"n":"第六条","txt":"财政部负责研究制定中央储备棉财政补贴财务政策，安排中央储备棉财政补贴资金。"},{"i":7,"n":"第七条","txt":"中国储备粮管理集团有限公司（以下简称中储粮集团）负责具体实施中央储备棉轮换、收储、动用计划，执行国家相关部门指令并接受监督指导，加强中央储备棉出入库和在库管理，对中央储备棉的数量、质量和储存安全负责。"},{"i":8,"n":"第八条","txt":"中国农业发展银行负责按照国家有关规定和中央储备棉轮换、收储、动用计划，及时发放中央储备棉贷款，并实施信贷监管。"},{"i":9,"n":"第九条","txt":"中央储备棉的轮换、收储、动用实行计划管理，任何单位和个人未经批准不得擅自动用，不得侵占、破坏、挪用。"},{"i":10,"n":"第十条","txt":"在库时间达到5年左右的中央储备棉原则上需要安排轮换。中央储备棉年度轮换数量可根据供需形势和市场调控需要等进行适当调整。"},{"i":11,"n":"第十一条","txt":"中储粮集团根据中央储备棉入库年限、保管质量、储存安全等情况，提出中央储备棉年度轮换计划建议，报送国家发展改革委、国家粮食和储备局、财政部。"},{"i":12,"n":"第十二条","txt":"出现下列情形之一的，可以启动中央储备棉收储： （一）国内棉花持续显著供大于需，或棉花价格大幅快速下跌； （二）中央储备棉库存明显低于储备规模； （三）国务院认为需要收储的其他情形。"},{"i":13,"n":"第十三条","txt":"出现下列情形之一的，可以动用中央储备棉： （一）国内棉花持续显著供不足需，或棉花价格大幅快速上涨； （二）应对重大自然灾害或者其他突发事件、国防动员等需要动用中央储备棉； （三）国务院认为需要动用中央储备棉的其他情形。"},{"i":14,"n":"第十四条","txt":"国家发展改革委会同国家粮食和储备局、财政部确定中央储备棉轮换、收储、动用的原则、方式、数量和时机等。国家粮食和储备局、财政部会同国家发展改革委等向中储粮集团下达轮换、收储、动用计划。"},{"i":15,"n":"第十五条","txt":"中储粮集团应当按月将中央储备棉轮换、收储、动用计划执行情况报国家发展改革委、国家粮食和储备局、财政部。因不可抗力等不能按时完成计划的，中储粮集团应当及时报告国家粮食和储备局，由国家粮食和储备局、财政部会同相关部门批准。"},{"i":16,"n":"第十六条","txt":"中央储备棉的轮换、收储、动用通过公开竞价交易和进口询价采购方式进行，必要时经国家发展改革委会同相关部门同意，可采取邀标竞价等方式进行。"},{"i":17,"n":"第十七条","txt":"中央储备棉以中储粮集团直属企业自储为主，并逐步提高自储比例。确有需要的，可由中储粮集团租仓储存或委托具备条件的其他企业代储。中储粮集团应当按月将直属企业、租仓库点和代储企业（以下统称承储企业）的名单和储存数量报告国家粮食和储备局，并抄送中国农业发展银行。"},{"i":18,"n":"第十八条","txt":"中储粮集团和承储企业不得擅自变更中央储备棉储存库点，不得虚报、瞒报中央储备棉数量，不得擅自串换中央储备棉品种，不得在中央储备棉中掺杂掺假、以次充好，不得故意拖延中央储备棉出入库。 任何单位、企业、个人不得以中央储备棉对外进行抵押、质押等担保或者清偿债务。"},{"i":19,"n":"第十九条","txt":"中储粮集团和承储企业应当严格执行中央储备棉管理相关规章制度、标准，健全完善内部管理制度和工作机制，严格仓储管理，加强安全管理；对中央储备棉储存管理状况进行经常性检查，及时排查风险隐患，妥善处理保管过程中的数量、质量和储存安全等问题。发现数量和储存安全方面的重大风险隐患，中储粮集团应及时报告国家粮食和储备局。"},{"i":20,"n":"第二十条","txt":"承储企业应当在专门库房内储存中央储备棉，并实行专人保管、专账记载，保证中央储备棉账账相符、账实相符、储存安全。"},{"i":21,"n":"第二十一条","txt":"承储企业应当对中央储备棉进行棉权公示，在储存中央储备棉的库房涂刷或悬挂标识标牌。"},{"i":22,"n":"第二十二条","txt":"因不可抗力等因素需要安排中央储备棉移库的，中储粮集团应当及时提出移库计划建议，经国家粮食和储备局、财政部会同相关部门同意后具体实施。"},{"i":23,"n":"第二十三条","txt":"中储粮集团要加强中央储备棉直属库建设，安排资金用于新建仓容和更新改造，提高自储能力和管理水平；推动智慧棉库建设，建立自主可控的信息化监管系统，严格保障数据安全，实现在线监管，提升穿透监管能力。中央预算内投资对中央储备棉直属库建设予以适当支持。"},{"i":24,"n":"第二十四条","txt":"中央储备棉收储、轮入等所需资金通过中储粮集团直属中国储备棉管理有限公司（以下简称中储棉公司）向中国农业发展银行申请贷款解决，中央财政对中储棉公司按规定利率予以贷款贴息。"},{"i":25,"n":"第二十五条","txt":"中央储备棉入储成本由财政部核定，出库盈利上交中央财政，出库亏损经财政部批准后由中央财政负担。中央财政安排亏损补贴前继续占用中国农业发展银行贷款发生的占贷利息，由中央财政负担。"},{"i":26,"n":"第二十六条","txt":"中央储备棉在库保管费实行定额包干，与保管费相关的税费由中央财政据实负担。保管费标准由财政部结合中央储备棉业务实际情况等确定和调整。"},{"i":27,"n":"第二十七条","txt":"中央储备棉财政补贴资金支付按照国库集中支付制度有关规定执行。中储棉公司应当按照部门预算管理要求对中央储备棉财政补贴资金开展全过程绩效管理，加强中央储备棉资金使用管理。"},{"i":28,"n":"第二十八条","txt":"中央储备棉质量执行公证检验制度，具体按照国家有关规定执行。根据市场调控、应急保供等紧急需要，经相关部门同意，可适当调整公证检验程序和方式。"},{"i":29,"n":"第二十九条","txt":"中储粮集团应当保证入库的中央储备棉达到中央储备棉轮换、收储计划规定的质量等级，并符合国家有关质量要求。"},{"i":30,"n":"第三十条","txt":"国家粮食和储备局、财政部按照各自职责，对中储粮集团和承储企业管理中央储备棉情况进行监督检查。在监督检查过程中，可以行使下列职权： （一）进入承储企业检查中央储备棉的数量和储存安全； （二）向有关单位和人员了解中央储备棉轮换、收储、动用等计划执行和资金使用情况； （三）调阅中央储备棉有关资料、凭证； （四）对违法行为，依法予以处理。"},{"i":31,"n":"第三十一条","txt":"国家粮食和储备局对中央储备棉轮换、收储、动用计划执行情况进行监督检查，督促中储粮集团和承储企业落实计划，并按规定查处有关案件。"},{"i":32,"n":"第三十二条","txt":"中储粮集团和承储企业应当配合国家相关部门的监督检查。"},{"i":33,"n":"第三十三条","txt":"中储粮集团应当加强对承储企业管理中央储备棉情况的内部管控，及时发现并解决问题。"},{"i":34,"n":"第三十四条","txt":"中国农业发展银行按照信贷政策和规定，加强对中央储备棉贷款的信贷监管。中储粮集团和承储企业应当及时提供有关资料和情况。"},{"i":35,"n":"第三十五条","txt":"国家机关工作人员有下列行为之一的，依照《中华人民共和国公务员法》等有关规定，给予相应处分： （一）发现承储企业存在不适于储存中央储备棉等情况不责令限期整改的； （二）接到举报、发现违法违规行为不及时查处的； （三）有其他违反本办法行为的。"},{"i":36,"n":"第三十六条","txt":"中储粮集团有下列行为之一的，由国家相关部门责令改正；情节严重的，对直接责任人和其他相关人员提出处理意见，按权限由相关部门或单位给予相应处分： （一）拒不组织实施或者擅自改变中央储备棉轮换、收储、动用计划的； （二）选择不符合储存保管要求的企业承储中央储备棉的； （三）发现中央储备棉数量、质量和储存安全等方面问题不及时采取措施处理并按照规定报告，造成重大损失的； （四）有其他违反本办法行为的。"},{"i":37,"n":"第三十七条","txt":"承储企业有下列行为之一的，除按照国家有关规定予以行政处罚外，由国家相关部门责成中储粮集团对其限期整改，给予警告，需退回财政补贴的由中储棉公司及时收回并退回财政部，有违法所得的由中储棉公司及时收回并上缴财政部，造成财产损失的依法承担民事赔偿责任；对于中央储备棉代储企业，情节严重的，还应当及时解除承储合同： （一）拒不执行或者擅自改变中央储备棉轮换、收储、动用计划的； （二）擅自动用中央储备棉的； （三）以中央储备棉对外进行担保或者清偿债务的； （四）虚报、瞒报中央储备棉数量的； （五）在中央储备棉中掺杂掺假、以次充好的； （六）擅自串换中央储备棉品种、变更中央储备棉储存库点的； （七）未在专门库房内储存中央储备棉或未实行专人保管、专账记载，中央储备棉账账不符、账实不符的； （八）因管理不善等人为因素造成中央储备棉数量、质量和储存安全等方面出现问题，造成重大损失的； （九）有其他违反本办法"},{"i":38,"n":"第三十八条","txt":"中央储备棉的财务管理、轮换管理、仓储管理具体事项按照《国家储备棉财务管理办法》《中央储备棉轮换管理暂行办法》《中央储备棉仓储管理办法》执行。"},{"i":39,"n":"第三十九条","txt":"本办法由国家发展改革委、财政部负责解释。"},{"i":40,"n":"第四十条","txt":"本办法自2024年4月1日起施行。"}],"zhongyangchubeitangguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强中央储备糖规范管理，确保数量真实、质量合格、储存安全、节约高效，确保管得好、拿得出、调得快、用得上，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称中央储备糖，是指中央政府为实施市场调控、稳定市场预期、应对突发事件引发的市场异常波动而储备的食糖，包括原糖和白砂糖。 中央储备糖实行严格的计划管理，任何单位和个人不得侵占、破坏、挪用。"},{"i":3,"n":"第三条","txt":"从事中央储备糖管理、监督检查等活动，适用本办法。"},{"i":4,"n":"第四条","txt":"国家发展改革委负责中央储备糖市场调控管理，会同国家粮食和物资储备局、财政部研究提出中央储备糖规划、总量计划和年度调控意见，报国务院批准后协调落实。"},{"i":5,"n":"第五条","txt":"国家粮食和物资储备局负责中央储备糖行政管理，负责中央储备糖利息费用补贴的预算编制、申请及使用管理，对中央储备糖数量、质量、储存安全及计划执行情况实施监督检查。"},{"i":6,"n":"第六条","txt":"财政部负责中央储备糖财政财务管理，安排和管理中央储备糖财政补贴资金，组织指导财政部各地监管局开展财务秩序和财政资金监管，定期清算并根据需要开展绩效评估评价。"},{"i":7,"n":"第七条","txt":"中国农业发展银行等负责按照国家有关信贷政策和中央储备糖计划，及时发放和收回中央储备糖贷款，对发放的中央储备糖贷款实施信贷监管，确保资金安全。"},{"i":8,"n":"第八条","txt":"国家发展改革委、国家粮食和物资储备局会同财政部指定储备运营机构。储备运营机构负责中央储备糖的日常管理，储备运营业务与商业经营实行人员、实物、财务、账务管理严格分开，严格执行国家有关部门行政指令，具体实施中央储备糖收储、销售、轮换、动用计划，按月报告计划落实情况、储备管理情况和有关统计报表，对中央储备糖数量、质量和储存安全负责。"},{"i":9,"n":"第九条","txt":"中央储备糖的总量规模、品种结构、区域布局，由国家发展改革委会同国家粮食和物资储备局、财政部，根据国家宏观调控需要和财政承受能力等，结合绩效评估评价结果提出建议，报国务院批准。国家发展改革委会同国家粮食和物资储备局、财政部确定收储、销售的原则、方式、数量和时机等，国家粮食和物资储备局会同国家发展改革委、财政部下达收储、销售计划。"},{"i":10,"n":"第十条","txt":"中央储备糖原则上实行均衡轮换。原糖年度轮换数量按15-20%比例掌握，根据市场调控需要可适当增减，原则上不超过库存总量的30%；白砂糖原则上每年轮换一次。"},{"i":11,"n":"第十一条","txt":"中央储备糖的轮换，由储备运营机构统筹中央储备糖储存品质、年限、承储企业的管理情况等因素，于每年11月底前研究提出下一年度轮换计划建议，报送国家粮食和物资储备局、财政部和国家发展改革委。国家发展改革委会同国家粮食和物资储备局、财政部确定轮换原则、方式、数量和时机等，国家粮食和物资储备局、财政部会同国家发展改革委下达轮换计划。"},{"i":12,"n":"第十二条","txt":"中央储备糖收储、销售、轮换相关费用构成、标准以及盈亏处理等，由财政部会同国家粮食和物资储备局等有关部门按规定确定。"},{"i":13,"n":"第十三条","txt":"中央储备糖的动用，由国家发展改革委会同国家有关部门提出建议，经国务院批准后，由国家粮食和物资储备局会同有关部门下达动用计划。"},{"i":14,"n":"第十四条","txt":"发生下列情形之一的，可以动用中央储备糖： （一）全国或部分地区食糖明显供不应求或市场价格异常波动的； （二）发生重大自然灾害或其他突发事件需要动用中央储备糖的； （三）国务院认为需要动用中央储备糖的其他情形。"},{"i":15,"n":"第十五条","txt":"储备运营机构具体实施中央储备糖的收储、销售、轮换、动用计划，并接受国家有关部门监督指导。因不可抗力等因素不能按时完成的，要及时报国家粮食和物资储备局、财政部和国家发展改革委批复。"},{"i":16,"n":"第十六条","txt":"中央储备糖的收储、销售、轮换主要通过规范的交易平台以公开竞价交易方式进行。根据国家有关规定和要求，也可采取邀标竞价、委托包干、单一来源采购等方式进行。"},{"i":17,"n":"第十七条","txt":"储备运营机构按照中央储备糖区域布局等要求，根据国家有关部门制定的中央储备糖储存库资质条件等相关标准，选择其直属企业储存，也可采取公开、公平、公正的方式选择具备条件的其他企业代储。储备运营机构要将直属企业和代储企业（统称承储企业）名单、具体储存库点和储存数量、质量及时报告国家粮食和物资储备局。"},{"i":18,"n":"第十八条","txt":"储备运营机构和承储企业不得擅自变更中央储备糖储存库点，不得擅自串换中央储备糖品种，不得虚报中央储备糖数量，不得故意拖延中央储备糖出入库。"},{"i":19,"n":"第十九条","txt":"储备运营机构和承储企业要严格执行国家关于中央储备糖管理的规章制度、标准，健全完善内部管理制度和工作机制，严格仓储管理，加强质量安全管理。要加强中央储备糖经常性检查，及时排查风险隐患，妥善处理数量、质量和储存安全等方面问题，并由储备运营机构及时报告国家粮食和物资储备局。 中央储备糖出现数量、质量和储存安全问题造成的损失，由储备运营机构先行赔偿，再向相关责任单位追偿。"},{"i":20,"n":"第二十条","txt":"承储企业要对中央储备糖实行专仓储存、专人保管、专账记载和挂牌明示，不同年份、不同品种应分垛码放，保证账账相符、账实相符、质量合格和储存安全。"},{"i":21,"n":"第二十一条","txt":"承储企业应当对中央储备糖进行糖权公示，在储存中央储备糖的仓房仓门、外墙涂刷明显标识，悬挂统一标牌。"},{"i":22,"n":"第二十二条","txt":"因不可抗力等因素需安排中央储备糖移库的，由储备运营机构提出移库计划建议，经国家粮食和物资储备局、财政部和国家发展改革委同意后具体实施。"},{"i":23,"n":"第二十三条","txt":"在库中央储备糖应当统一办理财产保险，由储备运营机构在财政部北京监管局监督下通过招标方式进行。"},{"i":24,"n":"第二十四条","txt":"中央储备糖应当符合国家有关质量要求，其中储备白砂糖应当符合国标一级及以上。中央储备原糖出库加工的白砂糖投放食品市场应当符合食品安全标准要求。"},{"i":25,"n":"第二十五条","txt":"中央储备糖出入库质量检验，由储备运营机构委托经国家粮食和物资储备局认可的第三方检验机构进行。储备运营机构将检验结果及时汇总报国家粮食和物资储备局，并向承储企业提供出入库质量检验结果。承储企业如对质量检验结果有异议，应在收到检验报告7个工作日内向国家粮食和物资储备局提出书面复检申请，国家粮食和物资储备局按有关规定进行处理。"},{"i":26,"n":"第二十六条","txt":"中央储备糖在库质量安全管理执行定期质量监测制度，由国家粮食和物资储备局组织实施，每年对储备原糖开展一次监测，监测批次比例不低于10%；每年对储备白砂糖开展一次逐批次全覆盖监测。"},{"i":27,"n":"第二十七条","txt":"国家粮食和物资储备局、财政部按照各自职责，依法对储备运营机构和承储企业中央储备糖管理情况进行监督检查和核查。在监督检查和核查过程中，可以行使下列职权: （一）进入承储企业检查中央储备糖数量、质量和储存安全; （二）向有关单位和人员了解中央储备糖收储、销售、轮换、动用等计划执行情况; （三）调阅中央储备糖管理有关资料、凭证； （四）对违法违规行为，依法依规予以处理。"},{"i":28,"n":"第二十八条","txt":"中国农业发展银行按照信贷政策和规定，加强对中央储备糖贷款的信贷监管。储备运营机构应及时提供有关资料和情况。"},{"i":29,"n":"第二十九条","txt":"国家粮食和物资储备局垂直管理局负责辖区内中央储备糖日常监管和计划执行情况的监督检查，督促承储企业严格落实中央储备糖计划，按规定对有关库存案件进行查处，提出处理和追责建议。 国家粮食和物资储备局垂直管理局检查发现承储企业未执行中央储备糖有关管理规定，存在管理不规范、质量把关不严格、制度执行不力等问题，应及时向承储企业指出，责令其予以改正；发现承储企业存在严重违纪违规、不适于储存中央储备糖等情况，应及时向国家粮食和物资储备局报告。"},{"i":30,"n":"第三十条","txt":"储备运营机构及承储企业对国家有关部门单位的监督检查和核查，应当予以配合。任何单位和个人不得拒绝、阻挠、干涉国家有关部门单位的监督检查和核查。"},{"i":31,"n":"第三十一条","txt":"储备运营机构应加强对承储企业中央储备糖管理情况的内部管控，及时发现并解决问题。重大问题报请国家粮食和物资储备局、财政部处理。"},{"i":32,"n":"第三十二条","txt":"国家工作人员违反本办法规定，有下列行为之一的，依照《中华人民共和国公务员法》等有关规定，给予相应处分；构成犯罪的，依法追究刑事责任： （一）不及时下达中央储备糖收储、销售、轮换、动用计划的； （二）发现承储企业存在不适于储存中央储备糖的情况不责成其限期整改的； （三）接到举报、发现违规问题不及时查处的； （四）有其他违反本办法行为的。"},{"i":33,"n":"第三十三条","txt":"储备运营机构违反本办法规定，有下列行为之一的，由国家粮食和物资储备局、财政部按照各自职责，责成储备运营机构限期整改；情节严重的，扣拨管理费补贴，对直接负责的主管人员和其他直接责任人员提出处理建议，按权限由有关部门或单位给予相应处分；构成犯罪的，依法追究刑事责任： （一）拒不实施或擅自改变中央储备糖收储、销售、轮换、动用计划的； （二）选择不符合有关资质条件的企业承储中央储备糖的； （三）发现中央储备糖数量、质量和储存安全等方面问题不及时采取措施处理并按照规定报告的； （四）有其他违反本办法行为的。"},{"i":34,"n":"第三十四条","txt":"承储企业违反本办法规定，有下列行为之一的，由国家粮食和物资储备局、财政部、国家粮食和物资储备局垂直管理局按照各自职责，责成其限期整改；情节严重的，调出其承储的中央储备糖，责令退回财政补贴；有违法所得的，由财政部按有关规定收缴；构成犯罪的，依法追究刑事责任： （一）拒不执行或擅自改变中央储备糖收储、销售、轮换、动用计划的； （二）擅自动用中央储备糖的； （三）以中央储备糖对外担保或清偿债务的； （四）虚报、瞒报中央储备糖数量的； （五）在中央储备糖中掺杂掺假，以次充好的； （六）擅自串换中央储备糖品种，变更中央储备糖储存库点的； （七）未对中央储备糖实行专仓储存、专人保管、专账记载，中央储备糖账账不符、账实不符的； （八）因管理不善等人为因素造成中央储备糖数量、质量和储存安全等方面出现问题的； （九）有其他违反本办法行为的。"},{"i":35,"n":"第三十五条","txt":"本办法由国家发展改革委会同财政部、国家粮食和物资储备局负责解释。"},{"i":36,"n":"第三十六条","txt":"本办法自2021年4月10日起施行，2008年1月24日发布的《中央储备糖管理办法》（商务部 国家发展改革委 财政部令2008年第1号）同时废止。"}],"zhongyangdingjiamulu":[],"zhongyangyusuanneitouzibuzhuhetiexixiangmuguanlibaee8e14":[{"i":1,"n":"第一条","txt":"为规范中央预算内投资补助和贴息项目的管理，提高中央预算内投资补助和贴息资金的使用效益，着力推动投资高质量发展，依据《中共中央 国务院关于深化投融资体制改革的意见》《国务院关于投资体制改革的决定》《政府投资条例》《企业投资项目核准和备案管理条例》等，制定本办法。"},{"i":2,"n":"第二条","txt":"以投资补助和贴息方式安排中央预算内投资的项目管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称投资补助，是指国家发展改革委安排中央预算内投资，对符合条件的经营性投资项目给予的投资资金补助。 本办法所称贴息，是指国家发展改革委安排中央预算内投资，对符合条件、使用了贷款等有息资金的经营性投资项目给予的利息补贴。 本办法所称经营性投资项目包括企业投资项目和地方以资本金注入方式投资的政府投资项目等。 投资补助和贴息资金按项目安排，均为无偿投入。"},{"i":4,"n":"第四条","txt":"投资补助和贴息资金应当投向市场不能有效配置资源的社会公益服务、公共基础设施、农业农村、生态环境保护、重大科技进步、社会管理、国家安全等需要政府支持的公共领域项目。 国家发展改革委应当建立健全投资补助和贴息资金支持范围的评估调整机制，不断优化支持方向和结构等。"},{"i":5,"n":"第五条","txt":"安排投资补助和贴息资金应当贯彻落实国家重大战略、规划和有关重大方针政策，统筹兼顾国民经济社会发展各相关政策目标，保障和提高经济、社会、生态等综合效益，充分发挥对社会投资的引导和带动作用。"},{"i":6,"n":"第六条","txt":"国家发展改革委应当按照国家宏观调控的要求和重点，遵循科学决策、规范管理、注重绩效、公开透明的原则，统筹安排投资补助和贴息资金，平等对待各类投资主体，不得设置歧视性条件。对欠发达地区和革命老区、民族地区、边疆地区的投资项目应当适当倾斜。"},{"i":7,"n":"第七条","txt":"以投资补助和贴息方式安排中央预算内投资，应当分专项制定管理办法或工作方案，明确目标任务、实施期限、投资补助和贴息资金的支持范围、资金安排方式、工作程序、监督管理等主要内容，并针对不同行业、不同地区、不同性质投资项目的具体情况，确定相应的投资补助、贴息标准，作为各专项投资补助和贴息项目管理的具体依据。 管理办法和工作方案应当符合国家有关法律法规、规划和宏观调控政策的要求，按照政府信息公开有关规定向社会公开。"},{"i":8,"n":"第八条","txt":"投资补助和贴息资金应当用于计划新开工或续建项目，除对未足额安排的项目安排剩余资金、用于应急除险项目等特殊情况外，不得用于已完工项目。 项目的投资补助和贴息金额原则上应当一次性核定，对于已经足额安排的项目，不得重复申请。同一项目原则上不得重复申请不同专项资金。"},{"i":9,"n":"第九条","txt":"除涉密项目外，申请投资补助资金的项目，应当通过投资项目在线审批监管平台（以下简称投资在线平台）申请项目代码，按规定完成审批、核准或备案程序（地方政府投资项目应完成项目可行性研究报告审批或者投资概算核定），并按规定的内容和要求提交资金申请报告。 对于建设内容、建设标准、投资补助标准清晰，或者按照打捆、切块方式申请投资补助资金的领域，资金申请报告可以与年度投资计划申请合并报送。"},{"i":10,"n":"第十条","txt":"资金申请报告主要包括项目单位和项目的基本情况、申请中央预算内投资的主要理由和政策依据、前期手续和建设条件落实情况、总投资构成和资金筹措方案等。 项目单位应对所提交的资金申请报告内容的真实性负责。"},{"i":11,"n":"第十一条","txt":"对于申请投资补助资金的项目，资金申请报告应当由需要申请投资补助资金的项目单位提出，按程序报项目汇总申报单位。项目汇总申报单位应当对资金申请报告提出审核意见，并汇总报国家发展改革委。 各省、自治区、直辖市和计划单列市、新疆生产建设兵团发展改革委（以下简称省级发展改革委）和中央管理企业等为项目汇总申报单位。 对于申请贴息资金的项目，资金申请可以参照上述程序进行。"},{"i":12,"n":"第十二条","txt":"项目汇总申报单位应当对投资补助和贴息资金申请文件的下列事项进行审核，对审核结果和申报材料的完整性、合规性负责，并对符合条件的守信项目单位提供便利和支持： （一）符合本办法规定的资金投向和申请程序； （二）符合有关专项管理办法或工作方案的要求； （三）项目已按规定完成审批、核准或备案，且主要建设条件已经落实或基本落实； （四）项目单位未被列入严重失信主体名单，不存在政务失信记录； （五）符合国家发展改革委规定的其他条件。"},{"i":13,"n":"第十三条","txt":"国家发展改革委受理投资补助和贴息资金申请后，对相关事项进行审查，并可依据国家发展改革委委托投资咨询评估相关管理规定，委托相关单位进行评估。 对经审查后不符合规定要求的申报文件，应当予以退回或要求补充报送材料。"},{"i":14,"n":"第十四条","txt":"对于同意安排投资补助资金的项目，国家发展改革委应当批复资金申请报告，核定给予项目的投资补助金额。 对于资金申请报告与年度投资计划申请文件合并报送的项目，资金申请报告可以在下达投资计划时合并批复。"},{"i":15,"n":"第十五条","txt":"资金申请报告批复后，国家发展改革委可根据项目实施和资金安排情况，一次或者分次下达投资计划。对于跨年度实施的项目，原则上应分年度下达投资计划。"},{"i":16,"n":"第十六条","txt":"采用贴息方式的，贴息资金总额根据项目符合贴息条件的贷款等有息资金总额、贴息率和贴息年限计算确定。"},{"i":17,"n":"第十七条","txt":"国家发展改革委按打捆或切块方式安排中央预算内投资的，由省级发展改革委根据国家发展改革委下达年度投资计划明确的支持方向、支持项目应当具备的条件，以及有关工作要求等，将投资计划分解落实至具体项目。 省级发展改革委应当对上述投资计划分解安排的合规性负责，并根据专项管理办法等有关规定，通过投资在线平台（国家重大建设项目库）将投资计划分解落实的具体项目信息报国家发展改革委备案。"},{"i":18,"n":"第十八条","txt":"中央预算内年度投资计划编制、执行、监督管理等应当按照《中央预算内投资计划管理办法》有关规定执行。"},{"i":19,"n":"第十九条","txt":"使用投资补助和贴息资金的项目，应当严格执行投资建设法律法规，不得擅自改变建设规模、建设内容和建设标准。严格执行安全生产和工程质量法律法规，确保项目建设质量和安全。严格规范使用投资补助和贴息资金，严禁转移、侵占或者挪用。在项目建成后及时按规定办理竣工验收手续，推动项目尽快投用发挥效益。"},{"i":20,"n":"第二十条","txt":"项目单位应当根据国家发展改革委的有关要求，通过投资在线平台（国家重大建设项目库），及时如实报送投资补助和贴息项目的下列实施情况，并附具必要的佐证材料： （一）项目实际开竣工时间； （二）项目资金到位、支付和投资完成情况； （三）项目工程形象进度； （四）存在的问题。 暂不具备条件的涉密项目，使用国家重大建设项目库离线软件或其他适当方式填报，并通过涉密介质进行数据交换。"},{"i":21,"n":"第二十一条","txt":"项目汇总申报单位应当定期组织调度投资补助和贴息项目的实施情况，督促项目单位加快推进项目建设并规范报送项目实施情况，积极协调解决项目建设中存在的困难和问题，推动项目顺利建设实施。"},{"i":22,"n":"第二十二条","txt":"对项目不能按时开工建设或者项目建设规模、内容、标准以及项目总投资发生较大变化等情况，项目单位和项目汇总申报单位应当及时报告情况和原因，国家发展改革委应当根据具体情况进行相应调整，并可以视情况追究有关方面责任。打捆和切块下达年度投资计划的项目按照规定的权限办理投资计划调整。"},{"i":23,"n":"第二十三条","txt":"国家发展改革委必要时可以对投资补助和贴息支持领域、政策和项目等开展中期评估和后评价工作，并根据评估评价情况及时对有关管理办法和工作方案、政策等进行调整。"},{"i":24,"n":"第二十四条","txt":"投资补助和贴息项目的财务管理，按照财政部门的有关财务管理规定执行。"},{"i":25,"n":"第二十五条","txt":"各级发展改革部门、有关行业主管部门和其他有关部门应当落实项目全过程管理要求，建立健全对投资补助和贴息项目的监督管理机制，强化项目信息共享，加强对投资计划执行、投资补助和贴息项目建设实施的监督检查。"},{"i":26,"n":"第二十六条","txt":"各级发展改革部门应当会同有关部门，依据职责分工，依托投资在线平台（国家重大建设项目库），对使用投资补助和贴息资金的项目加强在线监测、动态监管，并采取抽查等方式开展项目现场监督检查，保证政府投资资金的合理使用和项目顺利建设实施。 对未履行、不当履行或违法履行监管职责的，要依法依规严肃处理；涉嫌犯罪的，要移送有关机关依法处理。对严格依据抽查事项清单和相关工作要求开展监管，项目出现问题的，应结合监督检查人员工作态度、工作程序方法、客观条件等进行综合分析，该免责的要依法依规免予追究相关责任。"},{"i":27,"n":"第二十七条","txt":"项目单位应当自觉接受审计、财政等部门依据职能分工进行的监督检查。"},{"i":28,"n":"第二十八条","txt":"项目单位应当按照国家有关规定加强投资补助和贴息项目的档案管理，将项目审批、资金申请和实施过程中的有关文件、资料等存档备查。"},{"i":29,"n":"第二十九条","txt":"国家发展改革委工作人员有下列行为之一的，责令其限期整改，根据实际情况依纪依法追究有关责任人的党纪责任、行政责任；构成犯罪的，由司法机关依法追究刑事责任： （一）违反规定批复资金申请报告的； （二）违反规定的程序和要求安排投资补助和贴息资金的； （三）违反有关法律法规或者国家规定，存在玩忽职守、滥用职权、徇私舞弊等情形的； （四）其他违反本办法的行为。"},{"i":30,"n":"第三十条","txt":"项目汇总申报单位和市（地）、县（市）级发展改革部门有下列行为之一的，国家发展改革委可根据情节，在一定时期和范围内不再受理其报送的投资补助和贴息资金申请，或者调减其中央预算内投资安排规模，并视情况对其予以通报： （一）指令或授意项目单位提供虚假情况、骗取投资补助和贴息资金的； （二）审核项目不严，造成中央预算内投资资金损失的； （三）对于打捆和切块下达的年度投资计划分解和安排出现严重失误的； （四）投资计划转发、分解或执行慢，或者指导推动投资项目建设实施不力，造成资金沉淀的； （五）所在地区或所属企业的项目存在较多问题或造成恶劣影响的； （六）对监管机构已指出的项目存在问题督促整改不到位的； （七）其他违反本办法的行为。"},{"i":31,"n":"第三十一条","txt":"项目单位有下列行为之一的，国家发展改革委（打捆和切块下达投资计划的项目由省级发展改革委）责令其限期整改；情节严重的，予以通报，视情况停止拨付、收回已拨付的投资补助和贴息资金，并可自处理之日起1—3年内暂停受理该项目单位的中央预算内投资申请，将相关信息纳入全国信用信息共享平台和在“信用中国”网站公示，依法依规提请或者移交有关机关依法追究有关责任人的行政或法律责任： （一）提供虚假情况，骗取投资补助和贴息资金的； （二）转移、侵占或者挪用投资补助和贴息资金的； （三）擅自改变主要建设规模、建设内容、建设标准的； （四）项目建设规模、建设内容、建设标准、总投资等发生较大变化而不及时如实报告的； （五）无正当理由未及时建设实施，造成资金沉淀的； （六）拒不接受依法进行的监督检查的； （七）未按要求通过投资在线平台（国家重大建设项目库）报告相关项目信息，或者不如实报告相关项目信息的； （八）其他"},{"i":32,"n":"第三十二条","txt":"对地方政府投资项目申请中央预算内投资支持的，应当在申请时明确该项目是直接投资项目还是资本金注入项目，其申请程序、项目实施管理和监督检查等，按照本办法执行。 对于地方政府直接投资项目，其申请的中央预算内投资应当采取直接投资方式安排到项目。对于地方政府资本金注入项目，其申请的中央预算内投资应当主要采取资本金注入方式安排到项目，也可适当采取投资补助和贴息等方式。"},{"i":33,"n":"第三十三条","txt":"涉密项目的申报、审核、批复，以及年度投资计划下达等，应严格落实保密相关法律法规要求。"},{"i":34,"n":"第三十四条","txt":"为了应对自然灾害、事故灾难、公共卫生事件、社会安全事件等突发事件，需要紧急下达中央预算内投资的项目，可以适当简化相关管理程序。"},{"i":35,"n":"第三十五条","txt":"本办法由国家发展改革委负责解释。"},{"i":36,"n":"第三十六条","txt":"本办法自2026年3月1日起施行。《中央预算内投资补助和贴息项目管理办法》（国家发展和改革委员会令2016年第45号）同时废止。"}],"zhongyangyusuanneitouzizibenjinzhuruxiangmuguanlib382eeb":[{"i":1,"n":"第一条","txt":"为加强和规范中央预算内投资资本金注入项目管理，更好发挥中央预算内投资的引导和撬动作用，提高投资效益，激发全社会投资活力，根据《政府投资条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中央预算内投资资本金注入项目的决策、建设实施和监督管理等活动，适用本办法。 本办法所称中央预算内投资资本金注入项目，是指安排中央预算内投资作为项目资本金的经营性固定资产投资项目。 前款规定的经营性固定资产投资项目，应由企业作为项目法人，实行独立核算、自负盈亏。"},{"i":3,"n":"第三条","txt":"采取资本金注入方式安排的中央预算内投资，应按照集中力量办大事、难事、急事的原则要求，主要投向《政府投资条例》第三条第一款规定领域的经营性项目，并积极引导和带动社会投资。"},{"i":4,"n":"第四条","txt":"对符合本办法第三条规定范围的政府和社会资本合作项目，可以采取资本金注入方式安排中央预算内投资。"},{"i":5,"n":"第五条","txt":"国家发展改革委根据国民经济和社会发展规划、国家宏观调控政策、国家级重点专项规划、国家级区域规划及实施方案，坚持科学决策、规范管理、注重绩效、公开透明的原则，平等对待各类投资主体，统筹安排中央预算内投资资本金注入项目，并依法履行有关监督管理职责。"},{"i":6,"n":"第六条","txt":"采取资本金注入安排中央预算内投资的专项，应当在工作方案或管理办法中明确资本金注入项目条件、资金安排标准、监督管理等主要内容，作为各专项资本金注入项目管理的具体依据。"},{"i":7,"n":"第七条","txt":"中央预算内投资所形成的资本金属于国家资本金，由政府出资人代表行使所有者权益。政府出资人代表原则上应为国有资产管理部门、事业单位，国有或国有控股企业。"},{"i":8,"n":"第八条","txt":"政府出资人代表对项目建成后中央预算内投资形成的国有产权，根据《中华人民共和国公司法》、国有资产有关法律法规及项目法人章程规定，行使有关权利并履行相应义务。"},{"i":9,"n":"第九条","txt":"国家建立健全政策措施，鼓励政府出资人代表对中央预算内投资资本金注入项目所持有的权益不分取或少分取红利，以引导社会资本投资。"},{"i":10,"n":"第十条","txt":"中央预算内投资资本金注入项目审批结果等信息，按照《政府信息公开条例》有关规定公开。"},{"i":11,"n":"第十一条","txt":"中央预算内投资资本金注入项目(以下简称资本金注入项目)原则上审批项目建议书、可行性研究报告和初步设计，并核定投资概算。 国家对简化投资项目审批另有规定的，从其规定。"},{"i":12,"n":"第十二条","txt":"国家发展改革委负责审批以下资本金注入项目： (一)国家发展改革委直接安排投资的中央单位项目; (二)需要跨地区、跨部门、跨领域统筹的项目; (三)党中央、国务院要求或法律、行政法规规定由国家发展改革委审批的项目; (四)国家有关规定中明确由国家发展改革委审批的其他项目。 对于特别重大的项目，由国家发展改革委根据有关规定核报国务院批准。 对于地方按照国家有关规定采取资本金注入方式安排中央预算内投资的项目，由地方人民政府发展改革部门或其他有关部门根据本地区规定权限负责审批。"},{"i":13,"n":"第十三条","txt":"申请以资本金注入方式安排中央预算内投资的单位(以下简称项目单位)，应当按照本办法第十二条规定的审批权限，报国家发展改革委、县级以上地方人民政府发展改革部门或其他有关部门(以下简称审批部门)审批。"},{"i":14,"n":"第十四条","txt":"除涉及国家秘密的项目外，审批部门应当通过全国投资项目在线审批监管平台(以下简称在线平台)生成的项目代码，办理资本金注入项目审批手续。 审批部门应当通过在线平台列明有关规划、产业政策等，公开项目审批的办理流程、办理时限和批准情况等，为项目单位提供相关咨询服务。"},{"i":15,"n":"第十五条","txt":"中央管理企业申请投资建设应当由国家发展改革委审批的资本金注入项目，在报送项目建议书、可行性研究报告时，应联合项目所在地省级政府或省级发展改革部门申报，或附具省级发展改革部门的意见。 国家有关部门申请投资建设应当由国家发展改革委审批的资本金注入项目，由该部门负责申报。 地方申请应当由国家发展改革委审批的资本金注入项目，由项目所在地省级发展改革部门初审后报送国家发展改革委审批。"},{"i":16,"n":"第十六条","txt":"资本金注入项目的项目建议书、可行性研究报告可以委托具备相应能力的工程咨询单位编制。初步设计应当按照国家有关规定委托具备相应能力的工程设计单位编制。"},{"i":17,"n":"第十七条","txt":"项目建议书内容和深度应当达到规定要求，并阐述申请以资本金注入方式使用中央预算内投资的理由和依据，提出政府出资人代表和项目法人的初步建议。拟新组建项目法人的，应当提出项目法人的初步组建方案。"},{"i":18,"n":"第十八条","txt":"审批部门对符合有关规定、确有必要建设的资本金注入项目，批准项目建议书。"},{"i":19,"n":"第十九条","txt":"项目单位应当依据项目建议书批复文件或国家有关规定，组织编制资本金注入项目的可行性研究报告。可行性研究报告内容和深度应当达到规定要求，并应当包含以下内容： (一)既有项目法人情况或新项目法人的组建方案; (二)项目资本金比例，出资方及其出资数额、出资比例、出资方式，以及拟申请以资本金注入方式使用中央预算内投资的额度; (三)政府出资人代表及其权利、义务; (四)政府出资人代表同意接受中央预算内投资转为其拟持有国有股份的意见; (五)项目建议书批复中要求说明的其他问题。"},{"i":20,"n":"第二十条","txt":"项目单位在可行性研究报告中申请中央预算内投资资本金的比例，依托现有项目法人建设的，应当根据资产评估情况及有关规定，测算国家资本金所占比例;由新组建的项目法人负责建设的，按国家资本金在项目资本金总量中所占份额，计算出资比例。国家资本金折算股份的价格，不得低于项目其他股东出资的折算价格。"},{"i":21,"n":"第二十一条","txt":"政府和社会资本合作(PPP)项目拟申请以资本金注入方式安排中央预算内投资的，应当根据国家有关规定开展可行性论证，并将论证情况纳入可行性研究报告。"},{"i":22,"n":"第二十二条","txt":"审批部门对符合国家有关规定、具备建设条件并确需以资本金注入方式予以支持的项目，批准可行性研究报告。 可行性研究报告批复文件应当明确项目法人、以资本金注入方式安排中央预算内投资的数额及出资比例、出资人代表或确定出资人代表的方式等。对于在批复可行性研究报告时明确予以中央预算内投资支持，但因特殊情况确实难以确定投资数额、出资比例的，按照年度中央预算内投资计划统筹予以明确。"},{"i":23,"n":"第二十三条","txt":"经批准的可行性研究报告是确定建设项目的依据。 可行性研究报告批准后，由项目法人负责资本金注入项目的具体建设实施工作。"},{"i":24,"n":"第二十四条","txt":"初步设计及其提出的概算应当符合可行性研究报告批复文件，以及国家或有关行业标准和规范的要求。"},{"i":25,"n":"第二十五条","txt":"审批部门对符合可行性研究报告，以及国家或有关行业标准和规范要求的初步设计及其提出的投资概算予以批准。经核定的投资概算是控制资本金注入项目总投资的依据。 根据政府投资项目审批权限有关规定，由国家发展改革委负责审批初步设计的项目，国家发展改革委可以委托有关单位审批初步设计、核定投资概算，或委托有关单位审批初步设计，由国家发展改革委核定投资概算。"},{"i":26,"n":"第二十六条","txt":"审批资本金注入项目时，原则上应委托工程咨询单位对项目建议书、可行性研究报告进行评估。审批初步设计、核定投资概算时，原则上应当按照《政府投资条例》及有关规定经过专业评审。"},{"i":27,"n":"第二十七条","txt":"已完成审批、核准或备案的项目，又申请以资本金注入方式使用中央预算内投资的，应当按照本办法规定重新履行审批程序。其中，对完成审批手续的项目，审批部门应当对可行性研究报告批复文件的项目法人、资金来源及筹措方式等进行相应调整;对完成核准手续的项目，建设地点未变更且建设规模、建设内容等未有较大变更的，审批部门可以参照核准批复文件简化审查内容;对完成备案手续的项目，应当按政府投资项目重新进行审批。"},{"i":28,"n":"第二十八条","txt":"资本金注入项目完成可行性研究报告审批后，又拟采取政府和社会资本合作方式投资建设的，按以下情况分别处理： (一)仍安排中央预算内投资作为项目资本金的，应当重新编制、报批可行性研究报告。 (二)中央预算内投资全部退出项目资本金的，按照项目性质，办理相应的审批、核准或备案手续。其中，建设地点未变更且建设规模、建设内容等未有较大变更的，审批或核准机关应当参照已批复的可行性研究报告简化审查内容。"},{"i":29,"n":"第二十九条","txt":"资本金注入项目拟采取政府和社会资本合作方式投资建设的，原则上应当采用公开招标方式选择社会资本方。社会资本方遴选方案应当在可行性研究报告中作出说明。"},{"i":30,"n":"第三十条","txt":"政府出资人代表和项目法人为不同单位的，项目法人应当及时与政府出资人代表签订股权确认协议，在中央预算内投资到位后为政府出资人代表办理股权登记等手续。 政府出资人代表和项目法人为同一单位的，在资金到位后，按照国家有关规定办理国有资产登记手续。 审批初步设计核定投资概算时，中央预算内投资在项目资本金总量中所占比例发生变化的，应结合可行性研究报告批复中的内容，重新确定国家资本金的出资比例。"},{"i":31,"n":"第三十一条","txt":"发展改革部门根据政府投资管理有关规定，并结合资本金注入项目进展情况，一次或分次向政府出资人代表下达中央预算内投资计划。"},{"i":32,"n":"第三十二条","txt":"资本金注入项目中国家资本金的会计处理，按照国家有关规定办理。"},{"i":33,"n":"第三十三条","txt":"任何单位和个人不得截留、挪用中央预算内投资，不得无故拖延拨付中央预算内投资，不得改变中央预算内投资的使用方式。"},{"i":34,"n":"第三十四条","txt":"项目法人应当根据项目实际情况，依法办理资本金注入项目的规划许可、建设用地、环境影响评价、施工许可等手续，依法履行招标采购程序。"},{"i":35,"n":"第三十五条","txt":"资本金注入项目经批准的政府出资人代表发生变化的，应当报原政府出资人代表确定部门批准，并告知项目审批部门。 资本金注入项目建设投资原则上不得超过经核定的投资概算。因国家政策调整、价格上涨、地质条件发生重大变化等原因确需增加投资概算的，项目法人提出调整方案及资金来源，按照规定的程序报原初步设计审批部门或者投资概算核定部门核定。其中，因增加投资概算拟变更运营补贴、政府付费、使用者付费等其他支持事项、合作条件的，应当征得相关主管部门同意。"},{"i":36,"n":"第三十六条","txt":"资本金注入项目建成并在国家规定的单项验收合格后，应当按照国家有关规定进行竣工验收，并在竣工验收合格后及时办理竣工财务决算。"},{"i":37,"n":"第三十七条","txt":"资本金注入项目的项目法人应当通过在线平台(国家重大建设项目库)如实报送项目的开工建设、建设进度、竣工等基本信息。涉密项目应当按照审批部门的要求报送项目建设情况。 项目开工前，项目法人应当登录在线平台(国家重大建设项目库)报备资本金注入项目开工基本信息。项目开工后，项目法人应当及时在线报备项目建设动态进度基本信息。项目竣工后，项目法人应当及时在线报备项目竣工基本信息。"},{"i":38,"n":"第三十八条","txt":"审批部门应当采取在线监测、现场核查、后评价等方式，加强对资本金注入项目实施情况的监督检查。其他有关部门按照规定职责分工，负责对资本金注入项目监督管理。"},{"i":39,"n":"第三十九条","txt":"县级以上地方人民政府有关监管部门对资本金注入项目监督检查中发现的违法违规行为，应当依法及时处理，通过在线平台登记、共享相关违法违规信息、监管结果信息，并将有关信息记入相关市场主体信用记录，纳入全国信用信息共享平台并向社会公开公示。"},{"i":40,"n":"第四十条","txt":"项目法人应当按照国家有关规定加强资本金注入项目的档案管理，将项目审批和实施过程中的有关文件、资料存档备查。"},{"i":41,"n":"第四十一条","txt":"资本金注入项目的审批部门有下列情形之一的，由上级行政机关责令改正，对负有责任的领导人员和直接责任人员依法给予处分： (一)超越权限审批项目; (二)对不符合规定的项目予以批准; (三)未按规定核定或者调整项目的投资概算; (四)不依法履行监管职责，造成严重后果; (五)其他玩忽职守、滥用职权、徇私舞弊的情形。"},{"i":42,"n":"第四十二条","txt":"资本金注入项目的其他管理部门有下列情形之一的，依照预算管理等有关法律、行政法规和国家有关规定追究法律责任： (一)未按照投资计划和有关规定及时、足额办理中央预算内投资拨付; (二)转移、侵占、挪用中央预算内投资; (三)其他违反法律、行政法规的行为。"},{"i":43,"n":"第四十三条","txt":"资本金注入项目的项目单位有下列情形之一的，由审批部门责令改正，根据具体情况，暂停、停止拨付资金或者收回已拨付的资金，暂停或者停止建设活动，对负有责任的领导人员和直接责任人员依法给予处分： (一)项目未经批准或者不符合规定的建设条件而擅自开工建设; (二)拒绝协助政府出资人代表办理股权变更登记手续，或者阻碍、拒绝政府出资人代表行使法定权利; (三)擅自改变中央预算内投资使用方式; (四)擅自将资本金注入项目变更为政府和社会资本合作项目; (五)其他违反法律、行政法规的行为。"},{"i":44,"n":"第四十四条","txt":"工程咨询单位在项目建议书、可行性研究报告编制和评估，设计单位在初步设计编制，评审机构在初步设计及概算评审中，咨询、评估、评审等存在严重质量问题的，依照有关法律法规和国家有关规定进行处罚，并按照规定降低或者取消该单位资质或评价等级。"},{"i":45,"n":"第四十五条","txt":"资本金注入项目的政府出资人代表、其他有关单位或个人有下列情形之一的，由审批部门责令限期整改，或取消政府出资人代表资格、责令缴回中央预算内投资、另行确定政府出资人代表，由有关机关对负有责任的领导人员和直接责任人员依法给予处分： (一)截留、挪用中央预算内投资或擅自改变中央预算内投资使用方式; (二)无故拖延拨付中央预算内投资、侵犯项目法人合法权益，影响项目建设进度; (三)其他违反法律、行政法规的行为。"},{"i":46,"n":"第四十六条","txt":"违反本办法规定，构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"省级发展改革部门可以参照本办法的规定，制定本地区资本金注入项目管理办法。 对本办法规定的资本金注入项目，法律、行政法规和国家有专门规定的，按照有关规定执行。"},{"i":48,"n":"第四十八条","txt":"本办法由国家发展改革委负责解释。"},{"i":49,"n":"第四十九条","txt":"本办法自2021年8月1日起施行。"}],"zhongyangyusuanneitouzixiangmujianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对中央预算内投资项目的监督管理，规范项目实施和资金使用，保障和提高中央预算内投资综合效益，根据《政府投资条例》等有关法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家发展改革委安排中央预算内投资支持的固定资产投资项目的监督管理活动，适用本办法。 本办法所称监督管理，是指各有关主体对中央预算内投资项目的建设实施，以及相应的中央预算内投资年度计划（以下简称投资计划）的下达、分解、资金安排和使用等开展的日常管理、监测调度、监督检查和后评价等。"},{"i":3,"n":"第三条","txt":"中央预算内投资项目（以下简称投资项目）监督管理应当贯彻投资项目全生命周期管理要求，坚持依法依规、权责一致、公开透明、务实高效的原则。"},{"i":4,"n":"第四条","txt":"国家发展改革委负责指导和协调投资项目的监督管理工作，推动建立健全分工明确、各司其责、纵横联动、协同高效的监督管理体制机制，督促有关地方和部门、单位落实监督管理责任，推动投资项目有效实施、投资计划规范执行，促进中央预算内投资更好发挥综合效益。"},{"i":5,"n":"第五条","txt":"作为投资项目批复或资金申请报告批复、相应的投资计划下达对象，或者投资计划联合发文单位、会签单位的国务院有关行业主管部门，对本行业或领域投资项目履行行业监督管理职责。"},{"i":6,"n":"第六条","txt":"地方各级发展改革部门、有关行业主管部门根据职责分工，对投资项目履行属地监督管理责任，建立健全有关监督管理工作机制，组织实施对本地区投资项目的日常调度、在线监测和监督检查等。"},{"i":7,"n":"第七条","txt":"作为投资计划直接下达对象的中央单位，对本单位及其所属单位、直属机构或各级分支机构承担的投资项目负有主要监督管理责任，并重点对有关项目是否规范使用中央预算内投资、符合建设实施有关规定等承担相应监督管理责任。 本办法所称中央单位是指中央部门及其派出机构、垂直管理单位、所属事业单位，计划单列企业集团和中央管理企业等。"},{"i":8,"n":"第八条","txt":"国家发展改革委应当指导各有关监督管理部门、单位通过全国投资项目在线审批监管平台（国家重大建设项目库）对投资项目进行全生命周期监督管理，并建立监督执法信息共享机制，加强监督检查等工作的统筹协调，避免重复检查，减轻基层负担。 属于涉密投资项目的，应当依托国家重大建设项目库（政务内网系统）加强监督管理。暂不具备条件的，使用国家重大建设项目库离线软件填报，或在落实保密要求的基础上采取适当方式加强日常监督管理。"},{"i":9,"n":"第九条","txt":"国家发展改革委应当强化对投资项目监督管理的结果应用，建立健全中央预算内投资奖惩激励机制。对于上一年度投资项目建设实施以及相应的投资计划执行问题较多，或者审计提出问题较多，且有关问题严重的地方，应当视情况扣减中央预算内投资支持规模。对于上一年度投资项目建设管理及相应投资计划执行良好的地方，应当通过督查激励、通报表扬、加大中央预算内投资支持等方式予以激励。"},{"i":10,"n":"第十条","txt":"国家发展改革委在项目审批或资金申请报告批复时，应当确定安排的中央预算内投资金额，并根据项目实施和资金安排情况，一次或者分次下达投资计划。 投资计划按下达方式分类，包括直接安排到具体项目的投资计划和打捆切块下达的投资计划。投资计划原则上应当按项目下达。"},{"i":11,"n":"第十一条","txt":"对于直接安排到具体项目的投资计划，国家发展改革委在下达时应当明确每一个项目的项目单位（法人）、日常监管责任单位，并对省级发展改革部门、有关行业主管部门、中央单位等监督管理工作提出明确要求。省级发展改革部门应当在收文后10个工作日内转发下达投资计划。"},{"i":12,"n":"第十二条","txt":"对于打捆切块下达的投资计划，国家发展改革委应当督促省级发展改革部门或有关部门在收文后20个工作日内通过全国投资项目在线审批监管平台（国家重大建设项目库）将投资计划分解落实到具体项目，并落实项目单位（法人）主体责任，压实行业部门和地方各级发展改革部门监管责任，推动投资项目规范有序实施。"},{"i":13,"n":"第十三条","txt":"国家发展改革委应当通过全国投资项目在线审批监管平台（国家重大建设项目库）加强对投资项目的督促检查，并动态跟踪相应的投资计划转发、分解和执行，推动项目规范有序建设，按期建成发挥效益。"},{"i":14,"n":"第十四条","txt":"项目单位（法人）应当严格落实投资项目及其相应的投资计划执行的日常管理主体责任，具体内容包括： （一）项目单位应当如实申报项目建设进度，并按照规定的建设内容、规模、标准和工期等组织项目建设； （二）对于投资项目概算或总投资出现大幅度缩减的，应当按程序及时报告，由国家发展改革委或省级发展改革部门根据有关规定，视情形对投资计划有关内容进行调整，并同步研究对相应的项目或资金申请报告批复进行调整；其中，涉及对项目建设内容、建设规模等作较大变更的，应当依法履行项目变更手续； （三）按照有关要求规范合理使用中央预算内投资，做到单独核算、专款专用； （四）按照有关规定通过全国投资项目在线审批监管平台（国家重大建设项目库）及时、准确、完整地报送项目信息和进度数据； （五）自觉接受有关监管部门（单位）的监督检查和评估督导，对监管部门提出的问题认真按要求进行整改，并按照规定报送整改情况； （六）法律、行政法"},{"i":15,"n":"第十五条","txt":"项目日常监管责任单位原则上为投资项目的直接管理单位，即对项目单位（法人）的财务或人事行使管理职责的上一级单位。没有项目直接管理单位的，由项目单位（法人）上级行业主管部门履行日常监管职责。 日常监管责任单位一经确定，原则上不予调整。确需调整的，应当报经项目汇总申报单位（省级发展改革部门或者中央单位）同意后履行调整手续，同时通过全国投资项目在线审批监管平台（国家重大建设项目库）更新相关信息。"},{"i":16,"n":"第十六条","txt":"项目日常监管责任单位应当履行投资项目建设实施日常监管及其相应的投资计划执行的直接责任，具体内容包括： （一）制定日常监管工作方案，明确具体监管方式和要求，并建立动态管理监管台账； （二）督促项目单位（法人）通过全国投资项目在线审批监管平台（国家重大建设项目库）及时上报项目信息和进度数据，并对其真实性和完整性进行审核确认； （三）围绕项目建设实施主要环节，对项目单位（法人）开展定期或不定期的现场核查和监督检查； （四）对日常监管中发现的问题提出整改意见，并督促项目单位（法人）逐一整改落实；对发现的重大问题，及时向有关监管部门报告。 项目日常监管责任单位开展现场核查和监督检查，原则上应当做到“三到现场”，即开工到现场、建设到现场、竣工验收到现场。"},{"i":17,"n":"第十七条","txt":"项目日常监管责任单位应当对项目单位（法人）以下有关投资项目情况开展现场核查和监督检查： （一）项目建设手续是否齐全规范； （二）项目建设进度是否符合投资计划要求； （三）项目建设资金是否按规定期限到位，资金使用是否符合规定要求； （四）项目建设地点、内容、规模、标准、资金来源等事项是否与批复内容相一致，根据实际需要确需调整变更的，是否已按规定办理变更手续； （五）项目总投资是否存在大幅度缩减问题，或者是否超出经核定的投资概算； （六）项目信息和进度数据上报是否及时、准确、完整； （七）法律、行政法规和国家规定的其他内容。"},{"i":18,"n":"第十八条","txt":"国家发展改革委应当通过全国投资项目在线审批监管平台（国家重大建设项目库）定期对投资项目建设实施情况、相应投资计划执行情况等开展监测调度与分析，对未按时开工、建设进度滞后、资金支付率低、缩减投资规模、超期未完工等问题项目进行预警，督促有关项目汇总申报单位、项目日常监管责任单位和项目单位（法人）核查有关问题或情况，并推动整改落实。"},{"i":19,"n":"第十九条","txt":"地方各级发展改革部门依托全国投资项目在线审批监管平台（国家重大建设项目库）定期对本地区投资项目建设实施情况和投资计划执行情况开展监测调度与分析，对有关问题项目及时组织现场核查，并督促整改。"},{"i":20,"n":"第二十条","txt":"中央单位应当依托全国投资项目在线审批监管平台（国家重大建设项目库）对本单位负责监督管理的投资项目及投资计划开展监测调度与分析，发现问题及时推动整改，重大问题及整改情况按规定报送国家发展改革委。"},{"i":21,"n":"第二十一条","txt":"除涉密敏感项目外，根据本办法第十八条至第二十条开展监测调度的各有关部门、单位，对于安排中央预算内投资3000万元以上，具备实际条件且确有必要的单体项目，结合实际要求项目单位（法人）在控制性工点现场配备或者利用现有项目远程可视化监控设备，探索通过全国投资项目在线审批监管平台（国家重大建设项目库）进行实时监控。对于有条件的地方，可探索采取无人机航拍、卫星遥感等方式，定期核查项目建设进度。 开展监测调度的各有关部门、单位，可根据需要要求项目单位（法人）、项目日常监管责任单位、项目汇总申报单位等提供项目现场照片或视频等。 前款规定的各有关监测调度部门、单位应当探索运用互联网、大数据、云计算等现代信息技术手段，加强对投资项目各类信息的分析研判，与监测调度数据进行交叉验证，提高监测调度以及发现问题线索的能力。"},{"i":22,"n":"第二十二条","txt":"各级发展改革部门在开展监督检查工作过程中，应当综合考量项目性质、项目数量、区域分布、自查情况、监测调度情况、大数据分析情况、有关问题线索等因素，科学合理选取被监督检查项目。"},{"i":23,"n":"第二十三条","txt":"国家发展改革委每年应当制定监督检查计划，选取若干中央预算内投资专项的投资项目及相应的投资计划，通过现场核查、视频监测等方式开展监督检查。对于通过监测调度、大数据排查等方式发现问题比较突出的中央预算内投资专项，应加大监督检查的频次和力度。 国家发展改革委对地方发展改革委应重点检查其是否按照规定履行有关监督管理职责，以及是否按照规定的支持领域、方向、标准等及时分解下达或转发投资计划等。"},{"i":24,"n":"第二十四条","txt":"地方各级发展改革部门根据阶段性重点工作需要，结合本地实际，有重点地开展本地区投资项目的监督检查。 县级发展改革部门每年应当对本县区当年安排的投资项目至少进行一次现场核查和督促指导，推动项目单位（法人）规范有序加快建设、项目如期建成发挥效益，并将现场核查情况在全国投资项目在线审批监管平台（国家重大建设项目库）上予以填报。"},{"i":25,"n":"第二十五条","txt":"各级发展改革部门对投资项目的真实性、合规性等开展监督检查，主要检查以下内容： （一）项目申请材料是否与项目实际情况一致，有关材料和填报的信息是否真实、准确、完整，项目是否符合支持方向； （二）项目是否按要求开工建设，项目建设进度是否符合规定要求； （三）是否通过全国投资项目在线审批监管平台（国家重大建设项目库）按照规定及时、准确、完整填报项目信息； （四）中央预算内投资是否足额及时到位，是否存在闲置、转移、侵占、挪用等情况； （五）项目总投资是否存在大幅度缩减问题，或者是否超出经核定的投资概算； （六）是否规范履行竣工验收程序； （七）法律、行政法规和国家规定的其他内容。 各级发展改革部门对项目日常监管责任单位应重点检查其是否按照规定履行“三到现场”等日常监管职责。"},{"i":26,"n":"第二十六条","txt":"各级发展改革部门开展监督检查可以采取以下方式： （一）听取项目单位（法人）、项目汇总申报单位、项目日常监管单位、项目参建单位（包括项目前期咨询、招标代理、项目管理、勘察、设计、施工、监理、竣工验收等单位）关于项目情况的汇报，与相关人员访谈等； （二）查阅项目建议书、可行性研究报告、初步设计报告、项目申请书，以及项目审批、核准或备案文件，项目报建相关文件及批复手续，招投标、施工、监理、会计凭证等过程管理文件，竣工验收、决算相关文件等档案资料； （三）赴项目实地核查，或者通过视频方式查看项目现场； （四）向项目建成后的服务对象、涉及对象等访谈了解项目有关情况等； （五）法律、行政法规和国家规定的其他方式。"},{"i":27,"n":"第二十七条","txt":"除配合各级发展改革部门开展监督检查外，中央单位应当从行业或企业内控等角度开展监督检查，并重点对项目建设及中央预算内投资使用的合规性等进行监督检查，并将监督检查情况在全国投资项目在线审批监管平台（国家重大建设项目库）上予以填报。"},{"i":28,"n":"第二十八条","txt":"各级有关行业主管部门应当按照规定的职责分工，对本行业或领域的投资项目建设实施和投入运营是否符合有关建设目标、建设任务、进度要求、行业法规政策、技术标准等进行监督检查，并通过全国投资项目在线审批监管平台（国家重大建设项目库）实现监督检查结果信息共享。"},{"i":29,"n":"第二十九条","txt":"对于打捆切块下达投资计划的，省级发展改革部门或有关部门应当对分解后的具体项目，逐一落实项目单位（法人）、项目日常监管责任单位，明确相应监督管理要求，经项目日常监管责任单位确认后，向国家发展改革委报备。"},{"i":30,"n":"第三十条","txt":"作为打捆切块下达投资计划联合发文单位、会签单位的地方各级有关行业主管部门对有关投资项目履行以下监督管理职责： （一）督促指导项目单位（法人）做好建设手续办理、要素保障、征地拆迁等工作，落实项目建设条件，推进项目尽早开工并规范有序实施； （二）督促项目单位（法人）及时、准确填报项目建设进度等信息并同步上传佐证材料，做好项目调度信息与项目资料的比对审核； （三）项目建成后，应当督促项目单位（法人）切实做好项目运营管理，充分发挥投资效益； （四）法律、行政法规和国家规定的其他要求。"},{"i":31,"n":"第三十一条","txt":"对于打捆切块下达投资计划的投资项目，国家发展改革委应当按照“省负总责、市县抓落实”的总体要求，明确监督重点并加强对地方的指导，必要时采取“四不两直”等方式，对投资项目开展灵活机动检查。县级发展改革部门每年对本县区当年安排中央预算内投资的项目至少开展一次现场核查；省、市发展改革部门每年组织对本地区当年安排中央预算内投资的项目进行抽查，抽查比例原则上不得低于10%。 有关现场核查和抽查情况应当在全国投资项目在线审批监管平台（国家重大建设项目库）上予以填报。"},{"i":32,"n":"第三十二条","txt":"国家发展改革委应当重点加强对打捆切块下达投资计划有关专项的绩效目标审核和绩效跟踪监控，通过重点绩效评价等方式强化绩效管理机制，将绩效评价结果作为该专项及年度资金安排和调整的重要依据。对于经绩效评价不适宜采取打捆切块下达投资计划的专项，应当按照有关规定调整为采取直接安排到具体项目的方式下达投资计划。"},{"i":33,"n":"第三十三条","txt":"国家发展改革委每年初研究确定需要开展后评价的投资项目，制定项目后评价年度计划，印送有关方面并组织实施。 中央单位和地方各级发展改革部门根据实际需要开展投资项目后评价工作。 本办法所称项目后评价是指各级发展改革部门定期选取部分有代表性的投资项目，在项目建设完成并投入使用或运营一定时间后组织开展项目后评价，将项目建成后所达到的实际效果与项目的可行性研究报告、初步设计（含概算）文件及其审批文件的主要内容进行对比分析，找出差距及原因，总结经验教训，提出评估评价意见和对策建议。"},{"i":34,"n":"第三十四条","txt":"各级发展改革部门开展项目后评价可以委托具备相应能力的工程咨询机构承担，但不得委托参加过同一项目前期工作和建设实施工作的工程咨询机构承担该项目的后评价任务。 国家发展改革委委托有关工程咨询机构开展项目后评价工作的，应当按照《国家发展改革委投资咨询评估管理办法》等有关规定执行。"},{"i":35,"n":"第三十五条","txt":"各级发展改革部门在开展投资项目后评价的过程中，应重视公众参与，广泛听取各方面意见，并在后评价报告中予以客观反映。"},{"i":36,"n":"第三十六条","txt":"各级发展改革部门应当强化后评价成果运用，将后评价成果作为规划制定、投资决策、项目管理的重要依据或参考，不断提高投资决策科学化、法治化水平，促进提升中央预算内投资综合效益。"},{"i":37,"n":"第三十七条","txt":"项目单位（法人）有下列情形之一的，各级发展改革部门应当责令整改，明确整改期限，督促整改落实；情节严重的，予以通报，视情况停止拨付并收回已拨付的中央预算内投资，并可自处理之日起1—3年内暂停受理该项目单位（法人）中央预算内投资申请；涉嫌违纪违法的问题线索，按照规定移交纪检监察部门、司法机关，依法依纪追究其行政或法律责任。 （一）弄虚作假骗取中央预算内投资的； （二）转移、侵占、挪用中央预算内投资或擅自改变中央预算内投资使用方式的； （三）无正当理由不按照投资项目管理及投资计划要求推进资金支付，影响项目建设实施或造成资金沉淀、闲置等不利影响的； （四）虚报项目投资概算或者总投资申请中央预算内投资，或者无正当理由出现投资项目概算或者总投资大幅缩减情形且不如实报告的； （五）所报送材料或者通过全国投资项目在线审批监管平台（国家重大建设项目库）填报信息故意弄虚作假的； （六）监督检查过程中擅自转"},{"i":38,"n":"第三十八条","txt":"项目日常监管责任单位有下列情形之一的，由国家发展改革委或项目汇总申报单位，采取通报、约谈的方式对项目日常监管责任单位予以提醒；涉嫌违纪违法的问题线索，按照规定移交纪检监察部门、司法机关，依法依纪追究其行政或法律责任。 （一）其负责监管的投资项目出现第三十七条规定情形的； （二）监管失职失责，对其负责监管的投资项目出现第三十七条情形制止不力，甚至包庇纵容的； （三）对项目单位（法人）录入信息不及时、不准确、不完整等未尽到监管责任，影响对投资项目有关调度监测等监督管理工作的； （四）对监管机构已经指出项目存在问题，督促整改不到位，导致问题长期未整改的； （五）其他违反法律、行政法规和国家发展改革委规定的行为。"},{"i":39,"n":"第三十九条","txt":"项目汇总申报单位有下列情形之一的，国家发展改革委应当责令整改，明确整改期限，督促整改落实；情节严重的，约谈项目汇总申报单位负责人，视情况予以通报，情节恶劣的抄送项目汇总申报单位同级党委（党组）、政府，并可视情况暂停有关地方（部门）出现问题专项的中央预算内投资申请；涉嫌违纪违法的问题线索，按照规定移交纪检监察部门、司法机关，依法依纪追究其行政或法律责任。 （一）一年内被监督检查或审计查出第三十七条所指投资项目问题较多的； （二）不按照规定时限要求转发或分解下达投资计划，严重影响项目建设实施，或者造成资金大量沉淀、闲置等严重不利影响的； （三）对切块下达的投资计划进行分解时，安排给不符合专项管理办法（或工作方案）规定投资项目的； （四）其他违反法律、行政法规和国家发展改革委规定的行为。"},{"i":40,"n":"第四十条","txt":"对于项目单位（法人）、项目日常监管责任单位、项目汇总申报单位等违反本办法有关规定，但能够积极配合调查、认真整改纠正、主动消除或者减轻危害后果的，可以酌情减轻处理或处罚。"},{"i":41,"n":"第四十一条","txt":"各级发展改革部门和其他有关部门应当加强投资项目执法信息共享，通过全国投资项目在线审批监管平台（国家重大建设项目库）登记、共享相关违法违规信息、监管结果信息，并将有关信息记入相关主体信用记录，纳入全国信用信息共享平台并向社会公开公示，实施联合惩戒。"},{"i":42,"n":"第四十二条","txt":"各有关监督管理部门、单位的工作人员在开展监督管理过程中滥用职权、渎职失职、徇私舞弊、索贿受贿的，依法追究行政或者法律责任，构成犯罪的，依法追究其刑事责任。"},{"i":43,"n":"第四十三条","txt":"由国家发展改革委直接审批的中央预算内投资项目的监督管理活动，除遵守本办法有关规定外，还应当执行《中央预算内直接投资项目管理办法》和《中央预算内资本金注入项目管理办法》有关规定。"},{"i":44,"n":"第四十四条","txt":"省级发展改革部门可以依据本办法，制定本地区中央预算内投资项目监督管理的具体办法或细则。 对中央预算内投资项目的监督管理，法律、行政法规和国家有专门规定的，按照有关规定执行。"},{"i":45,"n":"第四十五条","txt":"本办法由国家发展改革委负责解释。"},{"i":46,"n":"第四十六条","txt":"本办法自2024年2月1日起实施。"}],"zhongyangyusuanneizhijietouzixiangmuguanlibanfa":[{"i":1,"n":"第一条","txt":"为切实加强和进一步规范中央预算内直接投资项目管理，健全科学、民主的投资决策机制，提高投资效益，着力推动投资高质量发展，依据《中共中央、国务院关于深化投融资体制改革的意见》《国务院关于投资体制改革的决定》《政府投资条例》等，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称中央预算内直接投资项目（以下简称直接投资项目或者项目），是指国家发展改革委安排中央预算内投资建设的中央本级（包括中央部门及其派出机构、垂直管理单位、所属事业单位）非经营性固定资产投资项目。 党政机关办公楼建设项目按照党中央、国务院规定严格管理。"},{"i":3,"n":"第三条","txt":"中央预算内直接投资应当遵循科学决策、规范管理、注重绩效、公开透明的原则，统筹兼顾国民经济社会发展各相关政策目标，争取获得经济和社会发展综合效益。 中央预算内直接投资应贯彻落实国家重大战略、重大规划和重大方针政策，并与经济社会发展水平和财政收支状况相适应。"},{"i":4,"n":"第四条","txt":"直接投资项目实行审批制，包括审批项目建议书、可行性研究报告、初步设计。情况特殊、影响重大的项目，需要审批开工报告。 国务院、国家发展改革委批准的专项规划中已经明确、前期工作深度达到项目建议书要求、建设内容简单、投资规模较小的项目，可以直接编报可行性研究报告，或者合并编报项目建议书。"},{"i":5,"n":"第五条","txt":"申请安排中央预算内投资3000万元及以上的项目，以及需要跨地区、跨部门、跨领域统筹的项目，由国家发展改革委审批或者由国家发展改革委委托中央有关部门审批，其中特别重大项目由国家发展改革委核报国务院批准；其余项目按照隶属关系，由中央有关部门审批后抄送国家发展改革委。 按照规定权限和程序批准的项目，国家发展改革委在编制年度计划时统筹安排中央预算内投资。"},{"i":6,"n":"第六条","txt":"审批直接投资项目时，一般应当委托具备相应能力的工程咨询机构对项目建议书、可行性研究报告进行评估。特别重大的项目实行专家评议制度。"},{"i":7,"n":"第七条","txt":"直接投资项目在可行性研究报告、初步设计及投资概算的编制、审批以及建设过程中，应当符合国家有关建设标准和规范。"},{"i":8,"n":"第八条","txt":"发展改革委与财政、自然资源、生态环境、金融监管、行业管理等部门建立联动机制，实现信息共享。 凡不涉及国家安全和国家秘密、法律法规未禁止公开的直接投资项目，审批部门应当按照政府信息公开的有关规定，将项目审批情况向社会公开。"},{"i":9,"n":"第九条","txt":"适宜编制规划的领域，国家发展改革委和中央有关部门应当编制专项规划。按照规定权限和程序批准的专项规划，是项目决策的重要依据。"},{"i":10,"n":"第十条","txt":"国家发展改革委会同有关部门建立项目储备库，作为项目决策和年度计划安排的重要依据。"},{"i":11,"n":"第十一条","txt":"项目建议书要对项目建设的必要性、主要建设内容、拟建地点、拟建规模、投资匡算、资金筹措以及社会效益和经济效益等进行初步分析，并附相关文件资料。项目建议书的编制格式、内容和深度应当达到规定要求。 由国家发展改革委负责审批的项目，其项目建议书应当由具备相应资信的甲级工程咨询机构编制。"},{"i":12,"n":"第十二条","txt":"项目建议书编制完成后，由项目单位按照规定程 序报送项目审批部门审批。项目审批部门对符合有关规定、确有必要建设的项目，批准项目建议书，并将批复文件抄送自然资源、生态环境等部门。 项目审批部门可以在项目建议书批复文件中规定批复文件的有效期。"},{"i":13,"n":"第十三条","txt":"项目单位依据项目建议书批复文件，组织开展可行性研究，并按照规定向自然资源、生态环境等部门申请办理用地（用海）预审与选址意见书、环境影响评价等审批手续。"},{"i":14,"n":"第十四条","txt":"项目审批部门在批准项目建议书之后，应当按照有关规定进行公示。公示期间征集到的主要意见和建议，作为编制和审批项目可行性研究报告的重要参考。"},{"i":15,"n":"第十五条","txt":"项目建议书批准后，项目单位应当委托工程咨询机构编制可行性研究报告，对项目在技术和经济上的可行性以及社会效益、节能、资源综合利用、生态环境影响、社会稳定风险等进行全面分析论证，落实各项建设和运行保障条件，并按照有关规定取得相关许可、审查意见。可行性研究报告的编制格式、内容和深度应当达到规定要求。 由国家发展改革委负责审批的项目，其可行性研究报告应当由具备相应资信的甲级工程咨询机构编制。"},{"i":16,"n":"第十六条","txt":"项目可行性研究报告应当包含以下招标内容: （一）项目的勘察、设计、施工、监理以及重要设备、材料等采购活动的具体招标范围（全部或者部分招标）； （二）项目的勘察、设计、施工、监理以及重要设备、材料等采购活动拟采用的招标组织形式（委托招标或者自行招标）。按照有关规定拟自行招标的，应当按照国家有关规定提交书面材料； （三）项目的勘察、设计、施工、监理以及重要设备、材料等采购活动拟采用的招标方式（公开招标或者邀请招标）。按照有关规定拟邀请招标的，应当按照国家有关规定提交书面材料。"},{"i":17,"n":"第十七条","txt":"可行性研究报告编制完成后，由项目单位按照规定程序报送项目审批部门审批，并应当按规定附送用地（用海）预审与选址意见书、节能审查意见以及其它应当提交的文件。"},{"i":18,"n":"第十八条","txt":"项目审批部门对符合有关规定、具备建设条件的项目，批准可行性研究报告，并将批复文件抄送自然资源、生态环境等部门。 项目审批部门可以在可行性研究报告批复文件中规定批复文件的有效期。 对于情况特殊、影响重大的项目，需要审批开工报告的，应当在可行性研究报告批复文件中予以明确。"},{"i":19,"n":"第十九条","txt":"经批准的可行性研究报告是确定建设项目的依据。项目单位可以依据可行性研究报告批复文件，按照规定向自然资源等部门申请办理规划许可、正式用地等手续，并委托具有相应资质的设计单位进行初步设计。"},{"i":20,"n":"第二十条","txt":"初步设计应当符合国家有关规定和可行性研究报告批复文件的有关要求，明确各单项工程或者单位工程的建设内容、建设规模、建设标准、用地规模、主要材料、设备规格和技术参数等设计方案，并据此编制投资概算。投资概算应当包括国家规定的项目建设所需的全部费用。 由国家发展改革委负责审批的项目，其初步设计应当由具备相应资质的甲级设计单位编制。"},{"i":21,"n":"第二十一条","txt":"投资概算超过可行性研究报告批准的投资估算百分之十的，或者项目单位、建设性质、建设地点、建设规模、技术方案等发生重大变更的，项目单位应当报告项目审批部门。项目审批部门可以要求项目单位重新组织编制和报批可行性研究报告。"},{"i":22,"n":"第二十二条","txt":"初步设计编制完成后，由项目单位按照规定程序报送项目审批部门审批。法律法规对直接投资项目的初步设计审批权限另有规定的，从其规定。 对于由国家发展改革委审批项目建议书、可行性研究报告的项目，其初步设计经中央有关部门审核后，由国家发展改革委审批或者经国家发展改革委核定投资概算后由中央有关部门审批。 经批准的初步设计及投资概算应当作为项目建设实施和控制投资的依据。"},{"i":23,"n":"第二十三条","txt":"直接投资项目应当符合规划、产业政策、环境保护、土地使用、节约能源、资源利用等方面的有关规定。"},{"i":24,"n":"第二十四条","txt":"对于项目单位缺乏相关专业技术人员和建设管理经验的直接投资项目，项目审批部门应当在批复可行性研究报告时要求实行代理建设制度（“代建制”），通过招标等方式选择具备工程项目管理资质的工程咨询机构，作为项目管理单位负责组织项目的建设实施。项目管理单位按照与项目单位签订的合同，承担项目建设实施的相关权利义务，严格执行项目的投资概算、质量标准和建设工期等要求，在项目竣工验收后将项目交付项目单位。"},{"i":25,"n":"第二十五条","txt":"直接投资项目应当依法办理相关手续，在具备国家规定的各项开工条件后，方可开工建设。 对于按照可行性研究报告批复文件的规定需要审批开工报告的项目，应当在开工报告批准后方可开工建设。"},{"i":26,"n":"第二十六条","txt":"直接投资项目的招标采购，按照《招标投标法》等有关法律法规规定办理。从事直接投资项目招标代理业务的招标代理机构，应当具备中央投资项目招标代理资格。"},{"i":27,"n":"第二十七条","txt":"建立项目建设情况报告制度。项目单位应当按照规定向项目审批部门定期报告项目建设进展情况。"},{"i":28,"n":"第二十八条","txt":"项目由于政策调整、价格上涨、地质条件发生重大变化等原因确需调整投资概算的，由项目单位提出调整方案，按照规定程序报原概算核定部门核定。概算调增幅度超过原批复概算百分之十的，概算核定部门应按照规定委托评审机构进行专业评审，并依据结论进行概算调整。"},{"i":29,"n":"第二十九条","txt":"建立健全直接投资项目的工程保险和工程担保制度，加强直接投资项目的风险管理。"},{"i":30,"n":"第三十条","txt":"直接投资项目应当遵守国家档案管理的有关规定，做好项目档案管理工作。项目档案验收不合格的，应当限期整改，经复查合格后，方可进行竣工验收。"},{"i":31,"n":"第三十一条","txt":"直接投资项目竣工后，应当按照规定编制竣工决算。项目竣工决算具体审查和审批办法，按照国家有关规定执行。"},{"i":32,"n":"第三十二条","txt":"直接投资项目建成后，项目单位应当按照国家有关规定报请项目可行性研究报告审批部门组织竣工验收。对于委托中央有关部门或者项目单位进行竣工验收的，中央有关部门或者项目单位应当在竣工验收完成后，将项目竣工验收报告报项目可行性研究报告审批部门。"},{"i":33,"n":"第三十三条","txt":"直接投资项目建成运行后，项目审批部门可以依据有关规定，组织具备相应资质的工程咨询机构，对照项目可行性研究报告批复文件及批准的可行性研究报告的主要内容开展项目后评价，必要时应当参照初步设计文件的相关内容进行对比分析，进一步加强和改进项目管理，不断提高决策水平和投资效益。"},{"i":34,"n":"第三十四条","txt":"发展改革、财政、审计、监察和其它有关部门，依据职能分工，对直接投资项目进行监督检查。 发展改革部门要严格落实属地监管责任，采取抽查等方式开展项目监管，并依托投资项目在线审批监管平台（国家重大项目库）加强对中央预算内直接投资项目的在线动态监管。 对未履行、不当履行或违法履行监管职责的，要依法依规严肃处理；涉嫌犯罪的，要移送有关机关依法处理。对严格依据抽查事项清单和相关工作要求开展监管，项目出现问题的，应结合执法检查人员工作态度、工作程序方法、客观条件等进行综合分析，该免责的依法依规免予追究相关责任。"},{"i":35,"n":"第三十五条","txt":"国家发展改革委和有关部门应当依法接受单位、个人对直接投资项目在审批、建设过程中违法违规行为的投诉和举报，并按照有关规定进行查处。"},{"i":36,"n":"第三十六条","txt":"项目审批部门和其它有关部门有下列行为之一的，责令限期改正，并对直接负责的主管人员和其它直接责任人员依法给予处分。 （一）违反本办法规定批准项目建议书、可行性研究报告、初步设计及核定投资概算的； （二）强令或者授意项目单位违反本办法规定的； （三）因故意或者重大过失造成重大损失或者严重损害公民、法人和其它组织合法权益的； （四）其它违反本办法规定的行为。"},{"i":37,"n":"第三十七条","txt":"国家机关及有关单位的工作人员在项目建设过程中滥用职权、玩忽职守、徇私舞弊、索贿受贿的，依法追究行政或者法律责任。"},{"i":38,"n":"第三十八条","txt":"项目单位和项目管理单位有下列行为之一的，国家发展改革委和有关部门将其纳入不良信用记录，责令其限期整改、暂停项目建设或者暂停投资安排；对直接负责的主管人员和其它直接责任人员，依法追究行政或者法律责任。 （一）提供虚假情况骗取项目审批和中央预算内投资的； （二）违反国家有关规定擅自开工建设的； （三）未经批准擅自调整建设标准或者投资规模、改变建设地点或者建设内容的； （四）转移、侵占或者挪用建设资金的； （五）未及时办理竣工验收手续、未经竣工验收或者验收不合格即交付使用的； （六）已经批准的项目，无正当理由未及时实施或者完成的； （七）不按国家规定履行招标程序的； （八）其它违反本办法规定的行为。"},{"i":39,"n":"第三十九条","txt":"有关工程咨询机构或者设计单位在编制项目建议书、可行性研究报告、初步设计及投资概算以及开展咨询评估或者项目后评价时，弄虚作假或者咨询评估意见严重失实的，国家发展改革委和有关部门将其纳入不良信用记录，根据其情节轻重，依法给予警告、停业整顿、降低资质等级或者撤销资质等处罚；造成损失的，依法承担赔偿责任。相关责任人员涉嫌犯罪的，依法移送司法机关处理。"},{"i":40,"n":"第四十条","txt":"直接投资项目发生重大质量安全事故的，按照国家有关规定，由有关部门依法追究项目单位、项目管理单位和勘察设计、施工、监理、招标代理等单位以及相关人员的法律责任。"},{"i":41,"n":"第四十一条","txt":"中央有关部门可以根据本办法的规定及职能分工，制订本部门的具体管理办法。省级发展改革部门可以参照本办法制订本地区的管理办法。"},{"i":42,"n":"第四十二条","txt":"本办法由国家发展改革委负责解释。"},{"i":43,"n":"第四十三条","txt":"本办法自2014年3月1日起施行。"}],"chanyejiegoutiaozhengzhidaomulu":[],"renminfangkongfanghushebeiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范人民防空防护设备管理，提高人民防空防护设备产品质量，根据《中华人民共和国人民防空法》《中华人民共和国产品质量法》《中华人民共和国行政许可法》《中华人民共和国标准化法》《中华人民共和国建筑法》《中华人民共和国认证认可条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"人民防空防护设备的生产、安装及监督管理活动，适用本办法。 本办法所称人民防空防护设备包括防护门类和防化类，是指专门用于人民防空工程中的防护门、阀门、防化监测报警与控制设备、滤毒与净化设备以及其他保障掩蔽人员生命、生活的产品设备。 国家对人民防空防护设备实行目录管理制度。《人民防空防护设备产品目录》由国家人民防空主管部门发布并动态管理。"},{"i":3,"n":"第三条","txt":"国家支持人民防空科学研究和技术创新，鼓励新技术、新材料、新工艺、新方法在人民防空领域推广应用。"},{"i":4,"n":"第四条","txt":"人民防空防护设备生产、安装应当符合国家的相关标准和技术规范。 人民防空防护设备相关标准和技术规范统一由国家人民防空主管部门组织制定。"},{"i":5,"n":"第五条","txt":"人民防空主管部门会同有关部门按职责分工负责对人民防空防护设备产品质量实施监督管理。鼓励人民防空行业协会发挥好政策宣传、行业自律作用。"},{"i":6,"n":"第六条","txt":"国家实行防护设备生产资质认定制度。生产人民防空防护设备的企业应当取得《人民防空防护设备生产资质证书》。 省级人民防空主管部门接受国家人民防空主管部门委托，负责本行政区域内人民防空防护设备生产资质的认定工作，并将认定结果上报国家人民防空主管部门。"},{"i":7,"n":"第七条","txt":"国家加强人民防空防护设备管理信息化水平。人民防空领域行政许可的申请、变更、查询等相关业务线上办理；行政检查、行政处罚以及产品溯源等相关信息线上发布。"},{"i":8,"n":"第八条","txt":"人民防空防护设备生产企业应当具备以下条件： （一）经营证照齐全，注册资金不低于1000万元； （二）生产防护门等防护设备的企业技术负责人应当具有人力资源和社会保障主管部门颁发的建筑工程或机械工程类专业高级技术职称证书。防化监测报警与控制、滤毒与净化等防护设备的企业技术负责人应当具有人力资源和社会保障主管部门颁发的化工或电子类专业高级技术职称证书； （三）拥有中级以上专业职称技术人员不少于3人、国家认可相应资格的技术工人不少于10人。企业应当与前述人员签订1年以上劳动合同并缴纳社会保险，并为前述人员社会保险缴纳唯一单位； （四）生产场地应具备防护设备生产能力，符合国家有关消防和环保等要求，并落实“三同时”制度； （五）安全生产、产品质量等管理体系完备； （六）无因违法行为被撤销《人民防空防护设备生产资质证书》的记录，或者被撤销《人民防空防护设备生产资质证书》已满2年； （七）其他应当具备"},{"i":9,"n":"第九条","txt":"申请从事人民防空防护设备生产的企业应当向省级人民防空主管部门提交申请材料。省级人民防空主管部门应当自受理之日起20个工作日内作出决定。对符合条件的，核发《人民防空防护设备生产资质证书》；对不符合条件的，不予核发证书，并书面向申请人说明理由。 省级人民防空主管部门在办理申请期间应当组织对企业生产条件进行现场检验。省级人民防空主管部门可以委托检验检测机构对试制产品进行检测。检验检测所需时间不计算在前款规定的期限内。"},{"i":10,"n":"第十条","txt":"取得《人民防空防护设备生产资质证书》的企业可以在全国不同地方生产防护设备，无需重复申请《人民防空防护设备生产资质证书》，但应当在新生产地点生产的产品出厂后30个工作日内，将新生产地点具体地址和第三方检验检测机构对新生产地点试制防护设备出具的检验检测报告电子文本提交至资质证书核发机关和新生产地点所在地省级人民防空主管部门。 新生产地点生产条件应当满足本办法第八条第二项至第七项规定。新生产地点出现产品质量等问题，由取证企业承担责任。"},{"i":11,"n":"第十一条","txt":"《人民防空防护设备生产资质证书》应当载明企业名称、法定代表人、注册地址、证书有效期、发证机关、发证时间等。 《人民防空防护设备生产资质证书》载明内容发生变更的，企业应当提出变更申请。其中，企业的名称、法定代表人、注册地址等发生变更的，省级人民防空主管部门办理变更申请时，可以不进行现场核查。"},{"i":12,"n":"第十二条","txt":"《人民防空防护设备生产资质证书》有效期5年。需要延续有效期的，企业应当在距有效期届满前的3至6个月内申请延期。逾期提出申请的，省级人民防空主管部门可以不予受理，原《人民防空防护设备生产资质证书》到期自动失效。 企业按时提出延期申请的，省级人民防空主管部门应当经现场检验后作出决定。相关企业在证书有效期内合规经营且无不良行为记录、未受到行政处罚的，可简化程序，不再进行现场检验。"},{"i":13,"n":"第十三条","txt":"企业提出防护设备生产资质认定申请的，应当提交以下信息电子文本： （一）防护设备生产企业资质认定申请； （二）企业营业执照正、副本； （三）法定代表人签字并加盖单位公章的材料真实性承诺书； （四）法定代表人身份证、技术负责人和专业技术人员职称证书、技术工人资格证书，以及前述所有人员的社保缴纳证明； （五）第三方检验检测机构对试制防护设备产品出具的检验检测报告； （六）政府有关部门出具的生产场地消防、环保合格材料； （七）安全生产、产品质量等方面管理制度。"},{"i":14,"n":"第十四条","txt":"企业提出变更其企业名称、法定代表人、注册地址申请的，应当提交以下信息电子文本： （一）防护设备生产企业资质变更申请； （二）变更后的企业营业执照正、副本； （三）法定代表人签字并加盖单位公章的材料真实性承诺书。 企业在领取相关信息变更后的新证书时，应当交还原证书。"},{"i":15,"n":"第十五条","txt":"企业提出延续《人民防空防护设备生产资质证书》有效期申请的，应当提交以下信息电子文本： （一）防护设备生产企业资质延续申请； （二）企业营业执照正、副本； （三）法定代表人签字并加盖单位公章的材料真实性承诺书； （四）法定代表人身份证、技术负责人和专业技术人员职称证书、技术工人资格证书，以及前述所有人员的社保缴纳证明； （五）政府有关部门出具的生产场地消防、环保合格材料； （六）安全生产、产品质量等方面管理制度。"},{"i":16,"n":"第十六条","txt":"人民防空防护设备生产企业可以在全国范围内从事设备生产、销售活动，各地不得设置或者变相设置准入条件。"},{"i":17,"n":"第十七条","txt":"人民防空防护设备生产企业应当对其生产的人民防空防护设备产品质量负责，并接受发证机关以及生产地点所在地县级以上地方人民防空主管部门的监督检查。"},{"i":18,"n":"第十八条","txt":"人民防空防护设备生产企业应当建立有效的质量管理体系，保证产品质量、标志、标识符合相关法律法规和标准规范要求。不得生产、销售未纳入《人民防空防护设备产品目录》的人民防空防护设备。"},{"i":19,"n":"第十九条","txt":"人民防空防护设备出厂前，生产企业应当自行或者委托具有检验检测资质的机构对产品质量进行检验检测，检验检测合格的方可印制产品合格证。出厂的人民防空防护设备应当附有产品合格证和使用维护说明书。 人民防空防护设备生产企业应当建立产品售后服务体系和维护保修制度。"},{"i":20,"n":"第二十条","txt":"人民防空防护设备出厂前，生产企业应当按照国家人民防空主管部门制定的人民防空防护设备编码规则，统一编码。 人民防空防护设备应当在产品显著位置设置铭牌，标出企业名称、生产地址、产品型号、生产时间、联系方式、设备编码和能够显示前述内容的二维码等。"},{"i":21,"n":"第二十一条","txt":"负责安装人民防空防护设备的单位和监理单位应当按照工程设计要求、施工技术标准、合同约定和有关技术标准，对进场的人民防空防护设备进行现场检查、登记，如实记录进货来源、名称、批次、规格、型号等内容；现场检查不合格的，不得安装。现场检查记录应当存档备查。"},{"i":22,"n":"第二十二条","txt":"工程竣工验收前，建设单位应当委托具有相应资质的检验检测机构，按照国家相关标准规范，对人民防空防护设备产品及安装质量组织检验检测。检验检测合格报告应当作为工程竣工验收要件。"},{"i":23,"n":"第二十三条","txt":"从事人民防空防护设备检验检测的机构应当通过国家或者省级市场监督管理部门组织开展的人民防空防护设备检验检测能力认定。"},{"i":24,"n":"第二十四条","txt":"县级以上人民防空主管部门按照属地管理原则，组织对人民防空防护设备产品质量、维护管理等开展检查。 人民防空主管部门开展人民防空防护设备监督检查时，有关组织和个人应当予以配合，如实提供相关情况和资料。"},{"i":25,"n":"第二十五条","txt":"有下列行为之一的，由县级以上人民防空主管部门责令限期改正并给予警告、通报批评；逾期不改正的，根据违法情节处以5万元以下罚款，并可以根据违法情形撤销《人民防空防护设备生产资质证书》；构成犯罪的，依法追究刑事责任。 （一）不具备本办法规定的生产条件从事生产活动的； （二）未取得《人民防空防护设备生产资质证书》生产防护设备的； （三）生产、销售的人民防空防护设备未纳入《人民防空防护设备产品目录》的； （四）在申请《人民防空防护设备生产资质证书》过程中弄虚作假的； （五）未对人民防空防护设备产品质量进行检验检测即出厂销售的； （六）人民防空防护设备出现质量问题或者未履行产品维修责任的； （七）不配合人民防空主管部门监督检查的； （八）其他违反本办法规定，造成严重后果的。"},{"i":26,"n":"第二十六条","txt":"有下列行为之一的，由县级以上人民防空主管部门给予批评教育并责令限期改正；情节严重的，给予警告或者通报批评。 （一）未能按要求将新生产地点和第三方检验检测机构对新生产地点试制防护设备产品出具的检验检测报告提交资质证书核发机关和新生产地点所在地省级人民防空主管部门的； （二）出厂的人民防空防护设备未附产品合格证、使用维护说明书、铭牌或者铭牌内容不完整的； （三）未落实产品质量等管理制度的； （四）其他违反本办法规定，尚未造成严重后果的。"},{"i":27,"n":"第二十七条","txt":"人民防空主管部门工作人员有下列行为之一的，责令其限期改正，并依法追究有关责任人的行政责任；构成犯罪的，依法追究刑事责任。 （一）违规办理《人民防空防护设备生产资质证书》的； （二）有其他滥用职权、玩忽职守、徇私舞弊、索贿受贿等违法行为的。"},{"i":28,"n":"第二十八条","txt":"本办法由国家人民防空主管部门负责解释。其他文件规定与本办法不一致的，按本办法执行。"},{"i":29,"n":"第二十九条","txt":"各省、自治区、直辖市人民防空主管部门可按照本办法制定具体实施办法。"},{"i":30,"n":"第三十条","txt":"本办法自2025年1月1日起施行。《人民防空专用设备生产安装管理暂行办法》（国人防〔2014〕438号）同时废止。 本办法施行前已取得《人民防空防护设备生产资质证书》的企业可继续从事相关生产活动，但应当在申请延续资质证书有效期时，满足本办法相关规定。"}],"jiagejianceguiding":[{"i":1,"n":"第一条","txt":"为科学、有效地组织价格监测工作，保障价格监测数据的真实性、准确性和及时性，发挥价格监测在宏观经济调控和价格管理中的重要作用，正确引导生产、流通和消费，保持市场价格总水平的基本稳定，根据《中华人民共和国价格法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称价格监测指政府价格主管部门对重要商品和服务价格的变动情况进行跟踪、采集、分析、预测、公布的活动。 价格监测的基本任务是调查和分析重要商品、服务价格，以及相关成本与市场供求的变动情况;跟踪反馈国家重要经济政策在价格领域的反映;实施价格预测、预警，并及时提出政策建议。"},{"i":3,"n":"第三条","txt":"国务院价格主管部门负责组织和协调全国价格监测工作，县级以上各级人民政府价格主管部门负责组织和协调本地区的价格监测工作。 价格监测的具体工作，由各级人民政府价格主管部门的价格监测机构及相关业务机构负责实施。"},{"i":4,"n":"第四条","txt":"县级以上各级人民政府价格主管部门要建立健全价格监测机构，明确价格监测工作职责，配备相应的价格监测工作人员，组织开展价格监测工作。"},{"i":5,"n":"第五条","txt":"国务院价格主管部门制定全国统一的价格监测报告制度，规定价格调查和价格信息采集、汇总、计算、传输、报告、分析、公布的具体办法，以及相应的价格监测项目、指标、代码、表式的统一标准，适时调整监测项目、标准及监测周期。"},{"i":6,"n":"第六条","txt":"省、自治区、直辖市人民政府价格主管部门可根据本行政区域内经济活动的实际情况和价格工作的需要，制定或授权下级人民政府价格主管部门制定补充的价格监测项目和标准，但不得与国家制定的价格监测报告制度相抵触。补充的价格监测项目和标准，应报国务院价格主管部门备案。"},{"i":7,"n":"第七条","txt":"建立、完善价格监测网络系统，逐步形成全国统一的价格监测网络。要加强价格监测信息采集、处理、传输的设备和网络技术建设，不断完善价格监测手段。"},{"i":8,"n":"第八条","txt":"价格监测以定点监测和周期性价格监测报表为基础，并开展专项调查、临时性调查、非定点监测等，加强对重要商品、服务价格的动态监测和变化趋势分析，提高价格监测的时效性和准确性。"},{"i":9,"n":"第九条","txt":"政府价格主管部门应根据价格监测报告制度的规定指定有关国家行政机关、企事业单位以及其他组织作为价格监测定点单位，并发给证书或标志牌。 价格监测定点单位要求对所承担的提供价格监测资料的工作给予指导和帮助的，政府价格主管部门应予以指导和帮助。 价格监测定点单位需要了解其所提供商品、服务价格的本地区价格平均水平的，政府价格主管部门应予以提供。"},{"i":10,"n":"第十条","txt":"价格监测有关单位和个人有义务接受政府价格主管部门的价格监测调查。 价格定点监测指定单位，应按照监测报告制度规定的内容和时间提供真实可靠的价格监测资料，提供的价格监测资料必须经本单位负责人审核。 非定点监测的单位及个人，有义务配合价格调查工作。"},{"i":11,"n":"第十一条","txt":"价格监测定点单位应建立价格监测的内部管理制度，对本单位的价格监测资料整理、报送实行监督，以保证价格资料的真实性、时效性;任何人不得虚报、瞒报、拒报、迟报，不得伪造、篡改价格监测资料。"},{"i":12,"n":"第十二条","txt":"价格监测工作人员收集价格资料时，应按照价格监测报告制度规定的内容、标准、方法、时间和程序进行。 实行价格监测调查证制度，价格监测工作人员须持证进行监测、调查活动。"},{"i":13,"n":"第十三条","txt":"价格监测工作人员要认真履行工作职责，具备从事价格监测工作所需的专业知识。各级人民政府价格主管部门应当加强对价格监测人员的专业培训和考核工作。"},{"i":14,"n":"第十四条","txt":"县级以上各级人民政府价格主管部门要向同级人民政府和上级价格主管部门及时上报价格监测报告和价格形势分析报告，反映重要商品和服务的价格变动以及价格政策执行情况，提出政策建议。"},{"i":15,"n":"第十五条","txt":"政府价格主管部门应向社会公布重要商品和服务价格监测、预测信息，或由政府价格主管部门的监测机构按有关制度规定向社会发布价格监测、预测信息。 属于国家机密、商业秘密的价格监测资料，不得对外公布，也不得用于政府宏观调控和价格工作以外的任何其他目的。"},{"i":16,"n":"第十六条","txt":"价格监测的工作经费，可申请列入同级财政预算。"},{"i":17,"n":"第十七条","txt":"价格监测定点单位因生产、经营品种调整，以及其他原因，不能及时、准确提供价格监测资料的，负责指定工作的价格主管部门应及时进行调整，另行指定价格监测定点单位。 对不再承担价格定点监测工作的单位，负责指定工作的价格主管部门应及时收回其价格监测定点单位证书或标志牌。"},{"i":18,"n":"第十八条","txt":"价格监测机构不按价格监测报告制度规定组织实施价格调查、监测工作，造成不能及时、准确上报有关价格监测数据，严重影响全国或地区数据汇总的，由本级或上级价格主管部门责令改正，予以通报批评。必要时，上级价格主管部门可责令其对有关的价格监测项目停报整顿。"},{"i":19,"n":"第十九条","txt":"价格监测定点单位有下列行为之一的，由下达监测任务的县级以上人民政府价格主管部门责令改正，予以通报批评;情节严重的，可建议任免机关或监察机关对负有直接责任的主管人员和其他责任人员予以行政处分。 (一)虚报、瞒报价格监测资料的; (二)伪造、篡改价格监测资料的; (三)拒报或屡次迟报价格监测资料的。"},{"i":20,"n":"第二十条","txt":"对违反价格监测规定的价格监测定点单位，地方性法规或规章规定有行政处罚的，也可依其规定予以行政处罚。"},{"i":21,"n":"第二十一条","txt":"县级以上各级人民政府价格主管部门的价格监测工作人员凡有下列行为之一的，由本级人民政府价格主管部门给予批评教育;情节严重的，由上级人民政府价格主管部门给予通报批评，并可提请任免机关或监察机关依法予以行政处分。 (一)不执行价格监测制度，影响价格监测工作的; (二)上报价格数据错误较多，严重影响数据准确性和代表性的; (三)玩忽职守、弄虚作假、瞒报、虚报或篡改价格数据资料，造成全国或地区汇总数据严重失实的。"},{"i":22,"n":"第二十二条","txt":"县级以上地方各级价格主管部门和有关国家行政机关、企事业单位以及其他组织的主管人员对履行职责的价格监测工作人员进行打击报复的，由上级人民政府价格主管部门或下达监测任务的人民政府价格主管部门提请任免机关或监察机关予以行政处分;构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"价格监测工作人员及价格监测相关人员违反有关保密规定的，依照有关法律法规处罚。"},{"i":24,"n":"第二十四条","txt":"政府价格主管部门对本级价格监测工作成绩突出的单位和个人可给予表彰和适当的奖励。"},{"i":25,"n":"第二十五条","txt":"本规定由国家发展和改革委员会负责解释。"},{"i":26,"n":"第二十六条","txt":"本规定自2003年6月1日起实施。"}],"jiageweifaxingweixingzhengchufashishibanfa":[{"i":1,"n":"第一条","txt":"为有效实施价格行政处罚，及时平抑市场价格异常波动，维护公共利益和社会稳定，根据《价格法》、《行政处罚法》、《价格违法行为行政处罚规定》等，制定本办法。"},{"i":2,"n":"第二条","txt":"经营者违反《价格法》第十四条规定哄抬价格，有下列情形之一的，政府价格主管部门依据《价格违法行为行政处罚规定》第五条的规定予以行政处罚： （一）捏造、散布涨价信息，大幅度提高价格的； （二）生产成本或进货成本没有发生明显变化，以牟取暴利为目的，大幅度提高价格的； （三）在一些地区或行业率先大幅度提高价格的； （四）囤积居奇，导致商品供不应求而出现价格大幅度上涨的。 构成哄抬价格行为的具体提价或涨价幅度，由省级价格主管部门根据当地具体情况提出，并报请省级人民政府批准确定。"},{"i":3,"n":"第三条","txt":"经营者违反《价格法》第十四条规定变相提高价格，采用下列手段之一的，政府价格主管部门依据《价格违法行为行政处罚规定》第六条的规定予以行政处罚： （一）抬高等级销售商品或者收取费用的； （二）以假充真，以次充好，降低质量的； （三）偷工减料，短尺少称，减少数量的； （四）变相提高价格的其他行为。"},{"i":4,"n":"第四条","txt":"地方政府及政府部门违反《价格法》规定，超越定价权限和范围擅自制定、调整价格或不执行法定的价格干预措施、紧急措施的，由上级政府或者政府价格主管部门责令改正，并可以通报批评；对直接负责的主管人员和其他直接责任人员，由上级政府价格主管部门提请有权机关依法给予行政处分。"},{"i":5,"n":"第五条","txt":"行业组织应当接受政府价格主管部门的指导，有价格违法行为且情节严重的，价格主管部门可以提请登记管理机关撤销登记。"},{"i":6,"n":"第六条","txt":"当国务院依法采取价格干预措施或者紧急措施，省、自治区、直辖市人民政府依法采取价格干预措施时，政府价格主管部门进行监督检查，适用本办法第七条、第八条、第九条和第十条。"},{"i":7,"n":"第七条","txt":"对纳入价格干预措施或紧急措施范围的商品和服务，以及可能波及的相关商品和服务的价格违法行为，应当依据《价格违法行为行政处罚规定》第十五条的规定予以从重处罚，在法定罚款幅度内应当从高适用，行政处罚种类在两个以上的应当从重适用，可以并处的应当并处处罚。"},{"i":8,"n":"第八条","txt":"价格行政执法人员可以适用以下程序，从快制止价格违法行为： （一）执法人员进行调查或者检查前，可以不向当事人送达《检查通知书》但要出示执法证件； （二）在调查或者检查中发现应当给予行政处罚的行为的，可以当场决定立案，立案、询问或检查应当制作笔录； （三）作出行政处罚决定前，可以不向当事人送达《行政处罚事先告知书》、《行政处罚听证告知书》，而以口头告知的方式履行行政处罚事先告知程序、听证告知程序； （四）调查终结，价格主管部门负责人应当立即对调查结果进行审查，及时作出行政处罚决定；对情节复杂或者重大违法行为给予较重的行政处罚，可以不召开案件审理委员会会议，而由价格主管部门负责人集体讨论决定。 （五）对依法可以当场作出行政处罚决定的，不当场收缴事后难以执行的，可以当场收缴罚款。"},{"i":9,"n":"第九条","txt":"经营者有下列情形之一的，可以按没有违法所得论处： （一）无合法销售或收费票据的； （二）隐匿、销毁销售或收费票据的； （三）隐瞒销售或收费票据数量、帐簿与票据金额不符导致计算违法所得金额无依据的； （四）多收价款全部退还的； （五）应当按没有违法所得论处的其他情形。"},{"i":10,"n":"第十条","txt":"因价格违法行为致使消费者或者其他经营者多付价款的，责令限期退还；期限届满后逾期不退或者难以退还的价款，以违法所得论处。"},{"i":11,"n":"第十一条","txt":"价格行政执法人员对应当予以及时制止和从重处罚的价格违法行为不予及时制上、从重处罚；因处罚失当，致使公民、法人或者其他组织的合法权益、公共利益和社会秩序遭受损害的，应当依法追究直接负责的主管人员和其他直接责任人员的责任。"},{"i":12,"n":"第十二条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":13,"n":"第十三条","txt":"本办法自2004年9月1日起施行。"}],"qiyejingwaitouziguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强境外投资宏观指导，优化境外投资综合服务，完善境外投资全程监管，促进境外投资持续健康发展，维护我国国家利益和国家安全，根据《中华人民共和国行政许可法》《国务院关于投资体制改革的决定》《国务院对确需保留的行政审批项目设定行政许可的决定》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称境外投资，是指中华人民共和国境内企业(以下称“投资主体”)直接或通过其控制的境外企业，以投入资产、权益或提供融资、担保等方式，获得境外所有权、控制权、经营管理权及其他相关权益的投资活动。 前款所称投资活动，主要包括但不限于下列情形： (一)获得境外土地所有权、使用权等权益; (二)获得境外自然资源勘探、开发特许权等权益; (三)获得境外基础设施所有权、经营管理权等权益; (四)获得境外企业或资产所有权、经营管理权等权益; (五)新建或改扩建境外固定资产; (六)新建境外企业或向既有境外企业增加投资; (七)新设或参股境外股权投资基金; (八)通过协议、信托等方式控制境外企业或资产。 本办法所称企业，包括各种类型的非金融企业和金融企业。 本办法所称控制，是指直接或间接拥有企业半数以上表决权，或虽不拥有半数以上表决权，但能够支配企业的经营、财务、人事、技术等重要事项。"},{"i":3,"n":"第三条","txt":"投资主体依法享有境外投资自主权，自主决策、自担风险。"},{"i":4,"n":"第四条","txt":"投资主体开展境外投资，应当履行境外投资项目(以下称“项目”)核准、备案等手续，报告有关信息，配合监督检查。"},{"i":5,"n":"第五条","txt":"投资主体开展境外投资，不得违反我国法律法规，不得威胁或损害我国国家利益和国家安全。"},{"i":6,"n":"第六条","txt":"国家发展和改革委员会(以下称“国家发展改革委”)在国务院规定的职责范围内，履行境外投资主管部门职责，根据维护我国国家利益和国家安全的需要，对境外投资进行宏观指导、综合服务和全程监管。"},{"i":7,"n":"第七条","txt":"国家发展改革委建立境外投资管理和服务网络系统(以下称“网络系统”)。投资主体可以通过网络系统履行核准和备案手续、报告有关信息;涉及国家秘密或不适宜使用网络系统的事项，投资主体可以另行使用纸质材料提交。网络系统操作指南由国家发展改革委发布。"},{"i":8,"n":"第八条","txt":"投资主体可以就境外投资向国家发展改革委咨询政策和信息、反映情况和问题、提出意见和建议。"},{"i":9,"n":"第九条","txt":"国家发展改革委在国务院规定的职责范围内，会同有关部门根据国民经济和社会发展需要制定完善相关领域专项规划及产业政策，为投资主体开展境外投资提供宏观指导。"},{"i":10,"n":"第十条","txt":"国家发展改革委在国务院规定的职责范围内，会同有关部门加强国际投资形势分析，发布境外投资有关数据、情况等信息，为投资主体提供信息服务。"},{"i":11,"n":"第十一条","txt":"国家发展改革委在国务院规定的职责范围内，会同有关部门参与国际投资规则制定，建立健全投资合作机制，加强政策交流和协调，推动有关国家和地区为我国企业开展投资提供公平环境。"},{"i":12,"n":"第十二条","txt":"国家发展改革委在国务院规定的职责范围内，推动海外利益安全保护体系和能力建设，指导投资主体防范和应对重大风险，维护我国企业合法权益。"},{"i":13,"n":"第十三条","txt":"实行核准管理的范围是投资主体直接或通过其控制的境外企业开展的敏感类项目。核准机关是国家发展改革委。 本办法所称敏感类项目包括： (一)涉及敏感国家和地区的项目; (二)涉及敏感行业的项目。 本办法所称敏感国家和地区包括： (一)与我国未建交的国家和地区; (二)发生战争、内乱的国家和地区; (三)根据我国缔结或参加的国际条约、协定等，需要限制企业对其投资的国家和地区; (四)其他敏感国家和地区。 本办法所称敏感行业包括： (一)武器装备的研制生产维修; (二)跨境水资源开发利用; (三)新闻传媒; (四)根据我国法律法规和有关调控政策，需要限制企业境外投资的行业。 敏感行业目录由国家发展改革委发布。"},{"i":14,"n":"第十四条","txt":"实行备案管理的范围是投资主体直接开展的非敏感类项目，也即涉及投资主体直接投入资产、权益或提供融资、担保的非敏感类项目。 实行备案管理的项目中，投资主体是中央管理企业(含中央管理金融企业、国务院或国务院所属机构直接管理的企业，下同)的，备案机关是国家发展改革委;投资主体是地方企业，且中方投资额3亿美元及以上的，备案机关是国家发展改革委;投资主体是地方企业，且中方投资额3亿美元以下的，备案机关是投资主体注册地的省级政府发展改革部门。 本办法所称非敏感类项目，是指不涉及敏感国家和地区且不涉及敏感行业的项目。 本办法所称中方投资额，是指投资主体直接以及通过其控制的境外企业为项目投入的货币、证券、实物、技术、知识产权、股权、债权等资产、权益以及提供融资、担保的总额。 本办法所称省级政府发展改革部门，包括各省、自治区、直辖市及计划单列市人民政府发展改革部门和新疆生产建设兵团发展改革部门。"},{"i":15,"n":"第十五条","txt":"投资主体可以向核准、备案机关咨询拟开展的项目是否属于核准、备案范围，核准、备案机关应当及时予以告知。"},{"i":16,"n":"第十六条","txt":"两个以上投资主体共同开展的项目，应当由投资额较大一方在征求其他投资方书面同意后提出核准、备案申请。如各方投资额相等，应当协商一致后由其中一方提出核准、备案申请。"},{"i":17,"n":"第十七条","txt":"对项目所需前期费用(包括履约保证金、保函手续费、中介服务费、资源勘探费等)规模较大的，投资主体可以参照本办法第十三条、第十四条规定对项目前期费用提出核准、备案申请。经核准或备案的项目前期费用计入项目中方投资额。"},{"i":18,"n":"第十八条","txt":"实行核准管理的项目，投资主体应当通过网络系统向核准机关提交项目申请报告并附具有关文件。其中，投资主体是中央管理企业的，由其集团公司或总公司向核准机关提交;投资主体是地方企业的，由其直接向核准机关提交。"},{"i":19,"n":"第十九条","txt":"项目申请报告应当包括以下内容： (一)投资主体情况; (二)项目情况，包括项目名称、投资目的地、主要内容和规模、中方投资额等; (三)项目对我国国家利益和国家安全的影响分析; (四)投资主体关于项目真实性的声明。 项目申请报告的通用文本以及应当附具的文件(以下称“附件”)清单由国家发展改革委发布。"},{"i":20,"n":"第二十条","txt":"项目申请报告可以由投资主体自行编写，也可以由投资主体自主委托具有相关经验和能力的中介服务机构编写。"},{"i":21,"n":"第二十一条","txt":"项目申请报告和附件齐全、符合法定形式的，核准机关应当予以受理。 项目申请报告或附件不齐全、不符合法定形式的，核准机关应当在收到项目申请报告之日起5个工作日内一次性告知投资主体需要补正的内容。逾期不告知的，自收到项目申请报告之日起即为受理。 核准机关受理或不予受理项目申请报告，都应当通过网络系统告知投资主体。投资主体需要受理或不予受理凭证的，可以通过网络系统自行打印或要求核准机关出具。"},{"i":22,"n":"第二十二条","txt":"项目涉及有关部门职责的，核准机关应当商请有关部门在7个工作日内出具书面审查意见。有关部门逾期没有反馈书面审查意见的，视为同意。"},{"i":23,"n":"第二十三条","txt":"核准机关在受理项目申请报告后，如确有必要，应当在4个工作日内委托咨询机构进行评估。除项目情况复杂的，评估时限不得超过30个工作日。项目情况复杂的，经核准机关同意，可以延长评估时限，但延长的时限不得超过60个工作日。 核准机关应当将咨询机构进行评估所需的时间告知投资主体。 接受委托的咨询机构应当在规定时限内提出评估报告，并对评估结论承担责任。 评估费用由核准机关承担，咨询机构及其工作人员不得收取投资主体任何费用。"},{"i":24,"n":"第二十四条","txt":"核准机关可以结合有关单位意见、评估意见等，建议投资主体对项目申请报告有关内容进行调整，或要求投资主体对有关情况或材料作进一步澄清、补充。"},{"i":25,"n":"第二十五条","txt":"核准机关应当在受理项目申请报告后20个工作日内作出是否予以核准的决定。项目情况复杂或需要征求有关单位意见的，经核准机关负责人批准，可以延长核准时限，但延长的核准时限不得超过10个工作日，并应当将延长时限的理由告知投资主体。 前款规定的核准时限，包括征求有关单位意见的时间，不包括咨询机构评估的时间。"},{"i":26,"n":"第二十六条","txt":"核准机关对项目予以核准的条件为： (一)不违反我国法律法规; (二)不违反我国有关发展规划、宏观调控政策、产业政策和对外开放政策; (三)不违反我国缔结或参加的国际条约、协定; (四)不威胁、不损害我国国家利益和国家安全。"},{"i":27,"n":"第二十七条","txt":"对符合核准条件的项目，核准机关应当予以核准，并向投资主体出具书面核准文件。 对不符合核准条件的项目，核准机关应当出具不予核准书面通知，并说明不予核准的理由。"},{"i":28,"n":"第二十八条","txt":"项目违反有关法律法规、违反有关规划或政策、违反有关国际条约或协定、威胁或损害我国国家利益和国家安全的，核准机关可以不经过征求意见、委托评估等程序，直接作出不予核准的决定。"},{"i":29,"n":"第二十九条","txt":"实行备案管理的项目，投资主体应当通过网络系统向备案机关提交项目备案表并附具有关文件。其中，投资主体是中央管理企业的，由其集团公司或总公司向备案机关提交;投资主体是地方企业的，由其直接向备案机关提交。 项目备案表格式文本及附件清单由国家发展改革委发布。"},{"i":30,"n":"第三十条","txt":"项目备案表和附件齐全、符合法定形式的，备案机关应当予以受理。 项目备案表或附件不齐全、项目备案表或附件不符合法定形式、项目不属于备案管理范围、项目不属于备案机关管理权限的，备案机关应当在收到项目备案表之日起5个工作日内一次性告知投资主体。逾期不告知的，自收到项目备案表之日起即为受理。 备案机关受理或不予受理项目备案表，都应当通过网络系统告知投资主体。投资主体需要受理或不予受理凭证的，可以通过网络系统自行打印或要求备案机关出具。"},{"i":31,"n":"第三十一条","txt":"备案机关在受理项目备案表之日起7个工作日内向投资主体出具备案通知书。 备案机关发现项目违反有关法律法规、违反有关规划或政策、违反有关国际条约或协定、威胁或损害我国国家利益和国家安全的，应当在受理项目备案表之日起7个工作日内向投资主体出具不予备案书面通知，并说明不予备案的理由。"},{"i":32,"n":"第三十二条","txt":"属于核准、备案管理范围的项目，投资主体应当在项目实施前取得项目核准文件或备案通知书。 本办法所称项目实施前，是指投资主体或其控制的境外企业为项目投入资产、权益(已按照本办法第十七条办理核准、备案的项目前期费用除外)或提供融资、担保之前。"},{"i":33,"n":"第三十三条","txt":"属于核准、备案管理范围的项目，投资主体未取得有效核准文件或备案通知书的，外汇管理、海关等有关部门依法不予办理相关手续，金融企业依法不予办理相关资金结算和融资业务。"},{"i":34,"n":"第三十四条","txt":"已核准、备案的项目，发生下列情形之一的，投资主体应当在有关情形发生前向出具该项目核准文件或备案通知书的机关提出变更申请： (一)投资主体增加或减少; (二)投资地点发生重大变化; (三)主要内容和规模发生重大变化; (四)中方投资额变化幅度达到或超过原核准、备案金额的20%，或中方投资额变化1亿美元及以上; (五)需要对项目核准文件或备案通知书有关内容进行重大调整的其他情形。 核准机关应当在受理变更申请之日起20个工作日内作出是否同意变更核准的书面决定。备案机关应当在受理变更申请之日起7个工作日内作出是否同意变更备案的书面决定。"},{"i":35,"n":"第三十五条","txt":"核准文件、备案通知书有效期2年。确需延长有效期的，投资主体应当在有效期届满的30个工作日前向出具该项目核准文件或备案通知书的机关提出延长有效期的申请。 核准机关应当在受理延期申请之日起20个工作日内作出是否同意延长核准文件有效期的书面决定。备案机关应当在受理延期申请之日起7个工作日内作出是否同意延长备案通知书有效期的书面决定。"},{"i":36,"n":"第三十六条","txt":"核准、备案机关应当依法履行职责，严格按照规定权限、程序、时限等要求实施核准、备案行为，提高行政效能，提供优质服务。"},{"i":37,"n":"第三十七条","txt":"对核准、备案机关实施的核准、备案行为，相关利害关系人有权依法申请行政复议或提起行政诉讼。"},{"i":38,"n":"第三十八条","txt":"对不符合本办法规定条件的项目予以核准、备案，或违反本办法规定权限和程序予以核准、备案的，应当依法予以撤销。"},{"i":39,"n":"第三十九条","txt":"核准、备案机关应当按照《政府信息公开条例》规定将核准、备案有关信息予以公开。"},{"i":40,"n":"第四十条","txt":"国家发展改革委和省级政府发展改革部门根据境外投资有关法律法规和政策，按照本办法第十三条、第十四条规定的分工，联合同级政府有关部门建立协同监管机制，通过在线监测、约谈函询、抽查核实等方式对境外投资进行监督检查，对违法违规行为予以处理。"},{"i":41,"n":"第四十一条","txt":"倡导投资主体创新境外投资方式、坚持诚信经营原则、避免不当竞争行为、保障员工合法权益、尊重当地公序良俗、履行必要社会责任、注重生态环境保护、树立中国投资者良好形象。"},{"i":42,"n":"第四十二条","txt":"投资主体通过其控制的境外企业开展大额非敏感类项目的，投资主体应当在项目实施前通过网络系统提交大额非敏感类项目情况报告表，将有关信息告知国家发展改革委。 投资主体提交的大额非敏感类项目情况报告表内容不完整的，国家发展改革委应当在收到之日起5个工作日内一次性告知投资主体需要补正的内容。逾期不告知的，视作内容完整。大额非敏感类项目情况报告表格式文本由国家发展改革委发布。 本办法所称大额非敏感类项目，是指中方投资额3亿美元及以上的非敏感类项目。"},{"i":43,"n":"第四十三条","txt":"境外投资过程中发生外派人员重大伤亡、境外资产重大损失、损害我国与有关国家外交关系等重大不利情况的，投资主体应当在有关情况发生之日起5个工作日内通过网络系统提交重大不利情况报告表。重大不利情况报告表格式文本由国家发展改革委发布。"},{"i":44,"n":"第四十四条","txt":"属于核准、备案管理范围的项目，投资主体应当在项目完成之日起20个工作日内通过网络系统提交项目完成情况报告表。项目完成情况报告表格式文本由国家发展改革委发布。 前款所称项目完成，是指项目所属的建设工程竣工、投资标的股权或资产交割、中方投资额支出完毕等情形。"},{"i":45,"n":"第四十五条","txt":"国家发展改革委、省级政府发展改革部门可以就境外投资过程中的重大事项向投资主体发出重大事项问询函。投资主体应当按照重大事项问询函载明的问询事项和时限要求提交书面报告。 国家发展改革委、省级政府发展改革部门认为确有必要的，可以公示重大事项问询函及投资主体提交的书面报告。"},{"i":46,"n":"第四十六条","txt":"投资主体按照本办法第四十二条、第四十三条、第四十四条、第四十五条规定提交有关报告表或书面报告后，需要凭证的，可以通过网络系统自行打印提交完成凭证。"},{"i":47,"n":"第四十七条","txt":"国家发展改革委、省级政府发展改革部门可以根据其掌握的国际国内经济社会运行情况和风险状况，向投资主体或利益相关方发出风险提示，供投资主体或利益相关方参考。"},{"i":48,"n":"第四十八条","txt":"投资主体应当对自身通过网络系统和线下提交的各类材料的真实性、合法性、完整性负责，不得有虚假、误导性陈述和重大遗漏。"},{"i":49,"n":"第四十九条","txt":"有关部门和单位、驻外使领馆等发现企业违反本办法规定的，可以告知核准、备案机关。公民、法人或其他组织发现企业违反本办法规定的，可以据实向核准、备案机关举报。 国家发展改革委建立境外投资违法违规行为记录，公布并更新企业违反本办法规定的行为及相应的处罚措施，将有关信息纳入全国信用信息共享平台、国家企业信用信息公示系统、“信用中国”网站等进行公示，会同有关部门和单位实施联合惩戒。"},{"i":50,"n":"第五十条","txt":"国家发展改革委工作人员有下列行为之一的，责令其限期改正，并依法追究有关责任人的行政责任;构成犯罪的，依法追究刑事责任： (一)滥用职权、玩忽职守、徇私舞弊、索贿受贿的; (二)违反本办法规定程序和条件办理项目核准、备案的; (三)其他违反本办法规定的行为。"},{"i":51,"n":"第五十一条","txt":"投资主体通过恶意分拆项目、隐瞒有关情况或提供虚假材料等手段申请核准、备案的，核准、备案机关不予受理或不予核准、备案，对投资主体及主要责任人处以警告。"},{"i":52,"n":"第五十二条","txt":"投资主体通过欺骗、贿赂等不正当手段取得项目核准文件或备案通知书的，核准、备案机关应当撤销该核准文件或备案通知书，对投资主体及主要责任人处以警告;构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"属于核准、备案管理范围的项目，投资主体有下列行为之一的，由核准、备案机关责令投资主体中止或停止实施该项目并限期改正，对投资主体及有关责任人处以警告;构成犯罪的，依法追究刑事责任： (一)未取得核准文件或备案通知书而擅自实施的; (二)应当履行核准、备案变更手续，但未经核准、备案机关同意而擅自实施变更的。"},{"i":54,"n":"第五十四条","txt":"投资主体有下列行为之一的，由国家发展改革委或投资主体注册地的省级政府发展改革部门责令投资主体限期改正;情节严重或逾期不改正的，对投资主体及有关责任人处以警告： (一)未按本办法第四十二条、第四十三条、第四十四条、第四十五条规定报告有关信息的; (二)违反本办法第四十八条规定的。"},{"i":55,"n":"第五十五条","txt":"投资主体在境外投资过程中实施不正当竞争行为、扰乱境外投资市场秩序的，由国家发展改革委或投资主体注册地的省级政府发展改革部门责令投资主体中止或停止开展该项目并限期改正，对投资主体及主要责任人处以警告。"},{"i":56,"n":"第五十六条","txt":"境外投资威胁我国国家利益和国家安全的，由国家发展改革委或投资主体注册地的省级政府发展改革部门责令投资主体中止实施项目并限期改正。 境外投资损害我国国家利益和国家安全的，由国家发展改革委或投资主体注册地的省级政府发展改革部门责令投资主体停止实施项目、限期改正并采取补救措施，对投资主体及有关责任人处以警告;构成犯罪的，依法追究刑事责任。 投资主体按照本办法第四十三条规定及时提交重大不利情况报告表并主动改正的，可以减轻或免除本条规定的行政处罚。"},{"i":57,"n":"第五十七条","txt":"金融企业为属于核准、备案管理范围但未取得核准文件或备案通知书的项目提供融资、担保的，由国家发展改革委通报该违规行为并商请有关金融监管部门依法依规处罚该金融企业及有关责任人。"},{"i":58,"n":"第五十八条","txt":"各省级政府发展改革部门要加强对本地企业境外投资的指导、服务和监管，可以按照本办法的规定制定具体实施办法。"},{"i":59,"n":"第五十九条","txt":"国家发展改革委对省级政府发展改革部门的境外投资管理工作进行指导和监督，对发现的问题及时予以纠正。"},{"i":60,"n":"第六十条","txt":"核准、备案机关及其工作人员，以及被核准机关征求意见、受核准机关委托进行评估的单位及其工作人员，依法对投资主体根据本办法提交的材料负有保守商业秘密的义务。"},{"i":61,"n":"第六十一条","txt":"事业单位、社会团体等非企业组织对境外开展投资参照本办法执行。"},{"i":62,"n":"第六十二条","txt":"投资主体直接或通过其控制的企业对香港、澳门、台湾地区开展投资的，参照本办法执行。 投资主体通过其控制的香港、澳门、台湾地区企业对境外开展投资的，参照本办法执行。"},{"i":63,"n":"第六十三条","txt":"境内自然人通过其控制的境外企业或香港、澳门、台湾地区企业对境外开展投资的，参照本办法执行。 境内自然人直接对境外开展投资不适用本办法。境内自然人直接对香港、澳门、台湾地区开展投资不适用本办法。"},{"i":64,"n":"第六十四条","txt":"法律、行政法规对境外投资管理有专门规定的，从其规定。"},{"i":65,"n":"第六十五条","txt":"本办法由国家发展改革委负责解释。"},{"i":66,"n":"第六十六条","txt":"本办法自2018年3月1日起施行。《境外投资项目核准和备案管理办法》(国家发展和改革委员会令第9号)同时废止。"}],"qiyetouzixiangmushizhongshihoujianguanbanfa":[{"i":1,"n":"第一条","txt":"为加强对企业投资项目的事中事后监管，规范企业投资行为，维护公共利益和企业合法权益，依据《行政许可法》《行政处罚法》《企业投资项目核准和备案管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"各级发展改革部门根据核准和备案职责，对企业在境内投资建设的固定资产项目(以下简称项目)核准和备案的事中事后监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"项目事中事后监管是指各级发展改革部门对项目开工前是否依法取得核准批复文件或者办理备案手续，并在开工后是否按照核准批复文件或者备案内容进行建设的监督管理。 各级发展改革部门开展项目事中事后监管，应当与规划、环保、国土、建设、安全生产等主管部门的事中事后监管工作各司其职、各负其责，并加强协调配合。"},{"i":4,"n":"第四条","txt":"各级发展改革部门对项目实施分级分类监督管理。对已经取得核准批复文件的项目，由核准机关实施监督管理;对已经备案的项目，由备案机关实施监督管理。对项目是否依法取得核准批复文件或者办理备案手续，由项目所在地县级以上地方发展改革部门实施监督管理。"},{"i":5,"n":"第五条","txt":"各级发展改革部门应当建立健全行政监督和监管执法程序，加强监管执法队伍建设，保障监管执法经费，依法行使监督管理职权。 对政府投资项目以及企业投资项目使用政府投资的稽察工作，按照有关规定执行。"},{"i":6,"n":"第六条","txt":"核准机关对本机关已核准的项目，应当对以下方面进行监督管理： (一)是否通过全国投资项目在线审批监管平台(以下简称在线平台)，如实、及时报送项目开工建设、建设进度、竣工等建设实施基本信息; (二)需要变更已核准建设地点或者对已核准建设规模、建设内容等作较大变更的，是否按规定办理变更手续; (三)需要延期开工建设的，是否按规定办理延期开工建设手续; (四)是否按照核准的建设地点、建设规模、建设内容等进行建设。"},{"i":7,"n":"第七条","txt":"核准机关应当根据行业特点、监管需要和简易、可操作的原则，制定、上线核准项目报送建设实施基本信息的格式文本，并对报送的建设实施基本信息进行在线监测。"},{"i":8,"n":"第八条","txt":"核准机关对其核准的项目，应当在项目开工后至少开展一次现场核查。"},{"i":9,"n":"第九条","txt":"已开工核准项目未如实、及时报送建设实施基本信息的，核准机关应当责令项目单位予以纠正;拒不纠正的，给予警告。"},{"i":10,"n":"第十条","txt":"项目未按规定办理核准批复文件、项目变更批复文件或者批复文件失效后开工建设的，核准机关应当依法责令停止建设或者责令停产，并依法处以罚款。"},{"i":11,"n":"第十一条","txt":"项目未按照核准的建设地点、建设规模、建设内容等进行建设的，核准机关应当依法责令停止建设或者责令停产，并依法处以罚款。 对于有关部门依法认定项目建设内容属于产业政策禁止投资建设的，核准机关应当依法责令停止建设或者责令停产并恢复原状，并依法处以罚款。"},{"i":12,"n":"第十二条","txt":"县级以上地方发展改革部门发现本行政区域内的项目列入《政府核准的投资项目目录》，但未依法办理核准批复文件、项目变更批复文件或者批复文件失效后开工建设的，应当报告对该项目有核准权限的机关，由核准机关依法责令停止建设或者责令停产，并依法处以罚款。"},{"i":13,"n":"第十三条","txt":"备案机关对本机关已备案的项目，应当对以下方面进行监督管理： (一)是否通过在线平台如实、及时报送项目开工建设、建设进度、竣工等建设实施基本信息; (二)是否属于实行核准管理的项目; (三)是否按照备案的建设地点、建设规模、建设内容进行建设; (四)是否属于产业政策禁止投资建设的项目。"},{"i":14,"n":"第十四条","txt":"备案机关应当根据行业特点、监管需要和简易、可操作的原则，制定、上线备案项目报送建设实施基本信息的格式文本，并对报送的建设实施基本信息进行在线监测。"},{"i":15,"n":"第十五条","txt":"项目自备案后2年内未开工建设或者未办理任何其他手续的，项目单位如果决定继续实施该项目，应当通过在线平台作出说明;如果不再继续实施，应当撤回已备案信息。 前款项目既未作出说明，也未撤回备案信息的，备案机关应当予以提醒。经提醒后仍未作出相应处理的，备案机关应当移除已向社会公示的备案信息，项目单位获取的备案证明文件自动失效。对其中属于故意报备不真实项目、影响投资信息准确性的，备案机关可以将项目列入异常名录，并向社会公开。"},{"i":16,"n":"第十六条","txt":"备案机关对其备案的项目，应当根据“双随机一公开”的原则，结合投资调控实际需要，定期制定现场核查计划。对列入现场核查计划的项目，应当在项目开工后至少开展一次现场核查。列入现场核查计划的项目数量比例，由备案机关根据实际确定。"},{"i":17,"n":"第十七条","txt":"已开工备案项目未如实、及时报送建设实施基本信息的，备案机关应当责令项目单位予以纠正;拒不纠正的，给予警告。"},{"i":18,"n":"第十八条","txt":"项目建设与备案信息不符的，备案机关应当责令限期改正;逾期不改正的，依法处以罚款并列入失信企业名单，向社会公开。 对于有关部门依法认定项目建设内容属于产业政策禁止投资建设的，备案机关应当依法责令停止建设或者责令停产并恢复原状，并依法处以罚款。"},{"i":19,"n":"第十九条","txt":"县级以上地方发展改革部门发现本行政区域内的已开工项目应备案但未依法备案的，应当报告对该项目有备案权限的机关，由备案机关责令其限期改正;逾期不改正的，依法处以罚款并列入失信企业名单，向社会公开。"},{"i":20,"n":"第二十条","txt":"对本行政区域内的已开工项目，经有关部门依法认定属于产业政策禁止投资建设的，县级以上发展改革部门应当依法责令停止建设或者责令停产并恢复原状，并依法处以罚款。"},{"i":21,"n":"第二十一条","txt":"各级发展改革部门对项目的现场核查，可以自行开展，也可以发挥工程咨询单位等机构的专业优势，以委托第三方机构的方式开展。 委托第三方机构开展现场核查的，应当建立核查机构名录，制订核查工作规范，加强对核查工作的指导和监督。委托第三方机构开展现场核查的经费由委托方承担。"},{"i":22,"n":"第二十二条","txt":"各级发展改革部门应当依托在线平台，运用大数据、互联网、移动计算等信息技术手段，加强对各类信息的分析研判，提高发现问题线索的能力。"},{"i":23,"n":"第二十三条","txt":"各级发展改革部门应当畅通投诉举报渠道，对投诉举报反映的问题线索及时予以处理。"},{"i":24,"n":"第二十四条","txt":"各级发展改革部门对发现的涉嫌违法问题，应当按照法定权限和程序立案查处，并作出处理决定。 对发现的涉及其他部门职权的违法违纪线索，应当及时移送。涉嫌犯罪的，应当移送司法机关追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"各级发展改革部门对项目的行政处罚信息，应当通过在线平台进行归集，并通过在线平台和“信用中国”网站向社会公开。 对在项目事中事后监管中形成的项目异常名录和失信企业名单，应当通过在线平台与全国信用信息平台共享，通过“信用中国”网站向社会公开，并实施联合惩戒。"},{"i":26,"n":"第二十六条","txt":"各级发展改革部门应当与规划、环保、国土、建设、安全生产等主管部门建立健全协同监管和联合执法机制，参加本级人民政府开展的综合执法工作，提高监管执法效率。"},{"i":27,"n":"第二十七条","txt":"各级发展改革部门应当建立健全项目事中事后监管责任制和责任追究制，通过约谈、挂牌督办、上收核准权限等措施，督促下级发展改革部门落实工作责任。"},{"i":28,"n":"第二十八条","txt":"本办法第九条、第十七条所称的警告，均指《行政处罚法》规定的行政处罚罚种，各级发展改革部门应当依照法定程序和要求实施。"},{"i":29,"n":"第二十九条","txt":"核准机关对未按规定办理核准手续的项目，未按照核准的建设地点、建设规模、建设内容等进行建设的项目，处以罚款的情形和幅度依照《企业投资项目核准和备案管理条例》第十八条执行。"},{"i":30,"n":"第三十条","txt":"备案机关对未依法备案的项目，建设与备案信息不符的项目，处以罚款的情形和幅度依照《企业投资项目核准和备案管理条例》第十九条执行。"},{"i":31,"n":"第三十一条","txt":"对属于产业政策禁止投资建设的项目，处以罚款的情形和幅度依照《企业投资项目核准和备案管理条例》第二十条执行。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定，但能够积极配合调查、认真整改纠正、主动消除或者减轻危害后果的，可以在法定幅度内减轻处罚。"},{"i":33,"n":"第三十三条","txt":"外商投资项目事中事后监督管理另有规定的，从其规定。"},{"i":34,"n":"第三十四条","txt":"事业单位、社会团体等非企业组织在境内投资建设的项目事中事后监督管理适用本办法，但通过预算安排的项目除外。"},{"i":35,"n":"第三十五条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":36,"n":"第三十六条","txt":"本办法自2018年2月4日起实施。"}],"qiyetouzixiangmuhezhunhebeianguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为落实企业投资自主权，规范政府对企业投资项目的核准和备案行为，实现便利、高效服务和有效管理，依法保护企业合法权益，依据《行政许可法》、《企业投资项目核准和备案管理条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称企业投资项目(以下简称项目)，是指企业在中国境内投资建设的固定资产投资项目，包括企业使用自己筹措资金的项目，以及使用自己筹措的资金并申请使用政府投资补助或贷款贴息等的项目。 项目申请使用政府投资补助、贷款贴息的，应在履行核准或备案手续后，提出资金申请报告。"},{"i":3,"n":"第三条","txt":"县级以上人民政府投资主管部门对投资项目履行综合管理职责。 县级以上人民政府其他部门依照法律、法规规定，按照本级政府规定职责分工，对投资项目履行相应管理职责。"},{"i":4,"n":"第四条","txt":"根据项目不同情况，分别实行核准管理或备案管理。 对关系国家安全、涉及全国重大生产力布局、战略性资源开发和重大公共利益等项目，实行核准管理。其他项目实行备案管理。"},{"i":5,"n":"第五条","txt":"实行核准管理的具体项目范围以及核准机关、核准权限，由国务院颁布的《政府核准的投资项目目录》(以下简称《核准目录》)确定。法律、行政法规和国务院对项目核准的范围、权限有专门规定的，从其规定。 《核准目录》由国务院投资主管部门会同有关部门研究提出，报国务院批准后实施，并根据情况适时调整。 未经国务院批准，各部门、各地区不得擅自调整《核准目录》确定的核准范围和权限。"},{"i":6,"n":"第六条","txt":"除国务院另有规定外，实行备案管理的项目按照属地原则备案。 各省级政府负责制定本行政区域内的项目备案管理办法，明确备案机关及其权限。"},{"i":7,"n":"第七条","txt":"依据本办法第五条第一款规定具有项目核准权限的行政机关统称项目核准机关。《核准目录》所称国务院投资主管部门是指国家发展和改革委员会;《核准目录》规定由省级政府、地方政府核准的项目，其具体项目核准机关由省级政府确定。 项目核准机关对项目进行的核准是行政许可事项，实施行政许可所需经费应当由本级财政予以保障。 依据国务院专门规定和省级政府规定具有项目备案权限的行政机关统称项目备案机关。"},{"i":8,"n":"第八条","txt":"项目的市场前景、经济效益、资金来源和产品技术方案等，应当依法由企业自主决策、自担风险，项目核准、备案机关及其他行政机关不得非法干预企业的投资自主权。"},{"i":9,"n":"第九条","txt":"项目核准、备案机关及其工作人员应当依法对项目进行核准或者备案，不得擅自增减审查条件，不得超出办理时限。"},{"i":10,"n":"第十条","txt":"项目核准、备案机关应当遵循便民、高效原则，提高办事效率，提供优质服务。 项目核准、备案机关应当制定并公开服务指南，列明项目核准的申报材料及所需附件、受理方式、审查条件、办理流程、办理时限等;列明项目备案所需信息内容、办理流程等，提高工作透明度，为企业提供指导和服务。"},{"i":11,"n":"第十一条","txt":"县级以上地方人民政府有关部门应当依照相关法律法规和本级政府有关规定，建立健全对项目核准、备案机关的监督制度，加强对项目核准、备案行为的监督检查。 各级政府及其有关部门应当依照相关法律法规及规定对企业从事固定资产投资活动实施监督管理。 任何单位和个人都有权对项目核准、备案、建设实施过程中的违法违规行为向有关部门检举。有关部门应当及时核实、处理。"},{"i":12,"n":"第十二条","txt":"除涉及国家秘密的项目外，项目核准、备案通过全国投资项目在线审批监管平台(以下简称在线平台)实行网上受理、办理、监管和服务，实现核准、备案过程和结果的可查询、可监督。"},{"i":13,"n":"第十三条","txt":"项目核准、备案机关以及其他有关部门统一使用在线平台生成的项目代码办理相关手续。 项目通过在线平台申报时，生成作为该项目整个建设周期身份标识的唯一项目代码。项目的审批信息、监管(处罚)信息，以及工程实施过程中的重要信息，统一汇集至项目代码，并与社会信用体系对接，作为后续监管的基础条件。"},{"i":14,"n":"第十四条","txt":"项目核准、备案机关及有关部门应当通过在线平台公开与项目有关的发展规划、产业政策和准入标准，公开项目核准、备案等事项的办理条件、办理流程、办理时限等。项目核准、备案机关应根据《政府信息公开条例》有关规定将核准、备案结果予以公开，不得违法违规公开重大工程的关键信息。"},{"i":15,"n":"第十五条","txt":"企业投资建设固定资产投资项目，应当遵守国家法律法规，符合国民经济和社会发展总体规划、专项规划、区域规划、产业政策、市场准入标准、资源开发、能耗与环境管理等要求，依法履行项目核准或者备案及其他相关手续，并依法办理城乡规划、土地(海域)使用、环境保护、能源资源利用、安全生产等相关手续，如实提供相关材料，报告相关信息。"},{"i":16,"n":"第十六条","txt":"对项目核准、备案机关实施的项目核准、备案行为，相关利害关系人有权依法申请行政复议或者提起行政诉讼。"},{"i":17,"n":"第十七条","txt":"企业办理项目核准手续，应当按照国家有关要求编制项目申请报告，取得第二十二条规定依法应当附具的有关文件后，按照本办法第二十三条规定报送。"},{"i":18,"n":"第十八条","txt":"组织编制和报送项目申请报告的项目单位，应当对项目申请报告以及依法应当附具文件的真实性、合法性和完整性负责。"},{"i":19,"n":"第十九条","txt":"项目申请报告应当主要包括以下内容： (一)项目单位情况; (二)拟建项目情况，包括项目名称、建设地点、建设规模、建设内容等; (三)项目资源利用情况分析以及对生态环境的影响分析; (四)项目对经济和社会的影响分析。"},{"i":20,"n":"第二十条","txt":"项目申请报告通用文本由国务院投资主管部门会同有关部门制定,主要行业的项目申请报告示范文本由相应的项目核准机关参照项目申请报告通用文本制定，明确编制内容、深度要求等。"},{"i":21,"n":"第二十一条","txt":"项目申请报告可以由项目单位自行编写，也可以由项目单位自主委托具有相关经验和能力的工程咨询单位编写。任何单位和个人不得强制项目单位委托中介服务机构编制项目申请报告。 项目单位或者其委托的工程咨询单位应当按照项目申请报告通用文本和行业示范文本的要求编写项目申请报告。 工程咨询单位接受委托编制有关文件，应当做到依法、独立、客观、公正，对其编制的文件负责。"},{"i":22,"n":"第二十二条","txt":"项目单位在报送项目申请报告时，应当根据国家法律法规的规定附具以下文件： (一)城乡规划行政主管部门出具的选址意见书(仅指以划拨方式提供国有土地使用权的项目); (二)国土资源(海洋)行政主管部门出具的用地(用海)预审意见(国土资源主管部门明确可以不进行用地预审的情形除外); (三)法律、行政法规规定需要办理的其他相关手续。"},{"i":23,"n":"第二十三条","txt":"地方企业投资建设应当分别由国务院投资主管部门、国务院行业管理部门核准的项目，可以分别通过项目所在地省级政府投资主管部门、行业管理部门向国务院投资主管部门、国务院行业管理部门转送项目申请报告。属于国务院投资主管部门核准权限的项目，项目所在地省级政府规定由省级政府行业管理部门转送的，可以由省级政府投资主管部门与其联合报送。 国务院有关部门所属单位、计划单列企业集团、中央管理企业投资建设应当由国务院有关部门核准的项目，直接向相应的项目核准机关报送项目申请报告，并附行业管理部门的意见。 企业投资建设应当由国务院核准的项目，按照本条第一、二款规定向国务院投资主管部门报送项目申请报告，由国务院投资主管部门审核后报国务院核准。新建运输机场项目由相关省级政府直接向国务院、中央军委报送项目申请报告。"},{"i":24,"n":"第二十四条","txt":"企业投资建设应当由地方政府核准的项目，应当按照地方政府的有关规定，向相应的项目核准机关报送项目申请报告。"},{"i":25,"n":"第二十五条","txt":"项目申报材料齐全、符合法定形式的，项目核准机关应当予以受理。 申报材料不齐全或者不符合法定形式的，项目核准机关应当在收到项目申报材料之日起5个工作日内一次告知项目单位补充相关文件，或对相关内容进行调整。逾期不告知的，自收到项目申报材料之日起即为受理。 项目核准机关受理或者不予受理申报材料，都应当出具加盖本机关专用印章并注明日期的书面凭证。对于受理的申报材料，书面凭证应注明项目代码，项目单位可以根据项目代码在线查询、监督核准过程和结果。"},{"i":26,"n":"第二十六条","txt":"项目核准机关在正式受理项目申请报告后，需要评估的，应在4个工作日内按照有关规定委托具有相应资质的工程咨询机构进行评估。项目核准机关在委托评估时，应当根据项目具体情况，提出评估重点，明确评估时限。 工程咨询机构与编制项目申请报告的工程咨询机构为同一单位、存在控股、管理关系或者负责人为同一人的，该工程咨询机构不得承担该项目的评估工作。工程咨询机构与项目单位存在控股、管理关系或者负责人为同一人的，该工程咨询机构不得承担该项目单位的项目评估工作。 除项目情况复杂的，评估时限不得超过30个工作日。接受委托的工程咨询机构应当在项目核准机关规定的时间内提出评估报告，并对评估结论承担责任。项目情况复杂的，履行批准程序后，可以延长评估时限，但延长的期限不得超过60个工作日。 项目核准机关应当将项目评估报告与核准文件一并存档备查。 评估费用由委托评估的项目核准机关承担，评估机构及其工作人员不得收取项目单位"},{"i":27,"n":"第二十七条","txt":"项目涉及有关行业管理部门或者项目所在地地方政府职责的，项目核准机关应当商请有关行业管理部门或地方人民政府在7个工作日内出具书面审查意见。有关行业管理部门或地方人民政府逾期没有反馈书面审查意见的，视为同意。"},{"i":28,"n":"第二十八条","txt":"项目建设可能对公众利益构成重大影响的，项目核准机关在作出核准决定前，应当采取适当方式征求公众意见。 相关部门对直接涉及群众切身利益的用地(用海)、环境影响、移民安置、社会稳定风险等事项已经进行实质性审查并出具了相关审批文件的，项目核准机关可不再就相关内容重复征求公众意见。 对于特别重大的项目，可以实行专家评议制度。除项目情况特别复杂外，专家评议时限原则上不得超过30个工作日。"},{"i":29,"n":"第二十九条","txt":"项目核准机关可以根据评估意见、部门意见和公众意见等，要求项目单位对相关内容进行调整，或者对有关情况和文件做进一步澄清、补充。"},{"i":30,"n":"第三十条","txt":"项目违反相关法律法规，或者不符合发展规划、产业政策和市场准入标准要求的，项目核准机关可以不经过委托评估、征求意见等程序，直接作出不予核准的决定。"},{"i":31,"n":"第三十一条","txt":"项目核准机关应当在正式受理申报材料后20个工作日内作出是否予以核准的决定，或向上级项目核准机关提出审核意见。项目情况复杂或者需要征求有关单位意见的，经本行政机关主要负责人批准，可以延长核准时限，但延长的时限不得超过40个工作日，并应当将延长期限的理由告知项目单位。 项目核准机关需要委托评估或进行专家评议的，所需时间不计算在前款规定的期限内。项目核准机关应当将咨询评估或专家评议所需时间书面告知项目单位。"},{"i":32,"n":"第三十二条","txt":"项目符合核准条件的，项目核准机关应当对项目予以核准并向项目单位出具项目核准文件。项目不符合核准条件的，项目核准机关应当出具不予核准的书面通知，并说明不予核准的理由。 属于国务院核准权限的项目，由国务院投资主管部门根据国务院的决定向项目单位出具项目核准文件或者不予核准的书面通知。 项目核准机关出具项目核准文件或者不予核准的书面通知应当抄送同级行业管理、城乡规划、国土资源、水行政管理、环境保护、节能审查等相关部门和下级机关。"},{"i":33,"n":"第三十三条","txt":"项目核准文件和不予核准书面通知的格式文本，由国务院投资主管部门制定。"},{"i":34,"n":"第三十四条","txt":"项目核准机关应制定内部工作规则，不断优化工作流程,提高核准工作效率。"},{"i":35,"n":"第三十五条","txt":"项目核准机关应当从以下方面对项目进行审查： (一)是否危害经济安全、社会安全、生态安全等国家安全; (二)是否符合相关发展建设规划、产业政策和技术标准; (三)是否合理开发并有效利用资源; (四)是否对重大公共利益产生不利影响。 项目核准机关应当制定审查工作细则，明确审查具体内容、审查标准、审查要点、注意事项及不当行为需要承担的后果等。"},{"i":36,"n":"第三十六条","txt":"除本办法第二十二条要求提供的项目申请报告附送文件之外，项目单位还应在开工前依法办理其他相关手续。"},{"i":37,"n":"第三十七条","txt":"取得项目核准文件的项目，有下列情形之一的，项目单位应当及时以书面形式向原项目核准机关提出变更申请。原项目核准机关应当自受理申请之日起20个工作日内作出是否同意变更的书面决定： (一)建设地点发生变更的; (二)投资规模、建设规模、建设内容发生较大变化的; (三)项目变更可能对经济、社会、环境等产生重大不利影响的; (四)需要对项目核准文件所规定的内容进行调整的其他重大情形。"},{"i":38,"n":"第三十八条","txt":"项目自核准机关出具项目核准文件或同意项目变更决定2年内未开工建设，需要延期开工建设的，项目单位应当在2年期限届满的30个工作日前，向项目核准机关申请延期开工建设。项目核准机关应当自受理申请之日起20个工作日内，作出是否同意延期开工建设的决定，并出具相应文件。开工建设只能延期一次，期限最长不得超过1年。国家对项目延期开工建设另有规定的，依照其规定。 在2年期限内未开工建设也未按照规定向项目核准机关申请延期的，项目核准文件或同意项目变更决定自动失效。"},{"i":39,"n":"第三十九条","txt":"实行备案管理的项目，项目单位应当在开工建设前通过在线平台将相关信息告知项目备案机关，依法履行投资项目信息告知义务，并遵循诚信和规范原则。"},{"i":40,"n":"第四十条","txt":"项目备案机关应当制定项目备案基本信息格式文本，具体包括以下内容： (一)项目单位基本情况; (二)项目名称、建设地点、建设规模、建设内容; (三)项目总投资额; (四)项目符合产业政策声明。 项目单位应当对备案项目信息的真实性、合法性和完整性负责。"},{"i":41,"n":"第四十一条","txt":"项目备案机关收到本办法第四十条规定的全部信息即为备案。项目备案信息不完整的，备案机关应当及时以适当方式提醒和指导项目单位补正。 项目备案机关发现项目属产业政策禁止投资建设或者依法应实行核准管理，以及不属于固定资产投资项目、依法应实施审批管理、不属于本备案机关权限等情形的，应当通过在线平台及时告知企业予以纠正或者依法申请办理相关手续。"},{"i":42,"n":"第四十二条","txt":"项目备案相关信息通过在线平台在相关部门之间实现互通共享。 项目单位需要备案证明的，可以通过在线平台自行打印或者要求备案机关出具。"},{"i":43,"n":"第四十三条","txt":"项目备案后，项目法人发生变化，项目建设地点、规模、内容发生重大变更，或者放弃项目建设的，项目单位应当通过在线平台及时告知项目备案机关，并修改相关信息。"},{"i":44,"n":"第四十四条","txt":"实行备案管理的项目，项目单位在开工建设前还应当根据相关法律法规规定办理其他相关手续。"},{"i":45,"n":"第四十五条","txt":"上级项目核准、备案机关应当加强对下级项目核准、备案机关的指导和监督，及时纠正项目管理中存在的违法违规行为。"},{"i":46,"n":"第四十六条","txt":"项目核准和备案机关、行业管理、城乡规划(建设)、国家安全、国土(海洋)资源、环境保护、节能审查、金融监管、安全生产监管、审计等部门，应当按照谁审批谁监管、谁主管谁监管的原则，采取在线监测、现场核查等方式，依法加强对项目的事中事后监管。 项目核准、备案机关应当根据法律法规和发展规划、产业政策、总量控制目标、技术政策、准入标准及相关环保要求等，对项目进行监管。 城乡规划、国土(海洋)资源、环境保护、节能审查、安全监管、建设、行业管理等部门，应当履行法律法规赋予的监管职责，在各自职责范围内对项目进行监管。 金融监管部门应当加强指导和监督，引导金融机构按照商业原则，依法独立审贷。 审计部门应当依法加强对国有企业投资项目、申请使用政府投资资金的项目以及其他公共工程项目的审计监督。"},{"i":47,"n":"第四十七条","txt":"各级地方政府有关部门应按照相关法律法规及职责分工，加强对本行政区域内项目的监督检查，发现违法违规行为的，应当依法予以处理，并通过在线平台登记相关违法违规信息。"},{"i":48,"n":"第四十八条","txt":"对不符合法定条件的项目予以核准，或者超越法定职权予以核准的，应依法予以撤销。"},{"i":49,"n":"第四十九条","txt":"各级项目核准、备案机关的项目核准或备案信息，以及国土(海洋)资源、城乡规划、水行政管理、环境保护、节能审查、安全监管、建设、工商等部门的相关手续办理信息、审批结果信息、监管(处罚)信息，应当通过在线平台实现互通共享。"},{"i":50,"n":"第五十条","txt":"项目单位应当通过在线平台如实报送项目开工建设、建设进度、竣工的基本信息。 项目开工前，项目单位应当登录在线平台报备项目开工基本信息。项目开工后，项目单位应当按年度在线报备项目建设动态进度基本信息。项目竣工验收后，项目单位应当在线报备项目竣工基本信息。"},{"i":51,"n":"第五十一条","txt":"项目单位有下列行为之一的，相关信息列入项目异常信用记录，并纳入全国信用信息共享平台： (一)应申请办理项目核准但未依法取得核准文件的; (二)提供虚假项目核准或备案信息，或者未依法将项目信息告知备案机关，或者已备案项目信息变更未告知备案机关的; (三)违反法律法规擅自开工建设的; (四)不按照批准内容组织实施的; (五)项目单位未按本办法第五十条规定报送项目开工建设、建设进度、竣工等基本信息，或者报送虚假信息的; (六)其他违法违规行为。"},{"i":52,"n":"第五十二条","txt":"项目核准、备案机关有下列情形之一的，由其上级行政机关责令改正，对负有责任的领导人员和直接责任人员由有关单位和部门依纪依法给予处分： (一)超越法定职权予以核准或备案的; (二)对不符合法定条件的项目予以核准的; (三)对符合法定条件的项目不予核准的; (四)擅自增减核准审查条件的，或者以备案名义变相审批、核准的; (五)不在法定期限内作出核准决定的; (六)不依法履行监管职责或者监督不力，造成严重后果的。"},{"i":53,"n":"第五十三条","txt":"项目核准、备案机关及其工作人员，以及其他相关部门及其工作人员，在项目核准、备案以及相关审批手续办理过程中玩忽职守、滥用职权、徇私舞弊、索贿受贿的，对负有责任的领导人员和直接责任人员依法给予处分;构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"项目核准、备案机关，以及国土(海洋)资源、城乡规划、水行政管理、环境保护、节能审查、安全监管、建设等部门违反相关法律法规规定，未依法履行监管职责的，对直接负责的主管人员和其他直接责任人员，依法给予处分;构成犯罪的，依法追究刑事责任。 项目所在地的地方政府有关部门不履行企业投资监管职责的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":55,"n":"第五十五条","txt":"企业以分拆项目、隐瞒有关情况或者提供虚假申报材料等不正当手段申请核准、备案的，项目核准机关不予受理或者不予核准、备案，并给予警告。"},{"i":56,"n":"第五十六条","txt":"实行核准管理的项目，企业未依法办理核准手续开工建设或者未按照核准的建设地点、建设规模、建设内容等进行建设的，由核准机关责令停止建设或者责令停产，对企业处项目总投资额1‰以上5‰以下的罚款;对直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款，属于国家工作人员的，依法给予处分。项目应视情况予以拆除或者补办相关手续。 以欺骗、贿赂等不正当手段取得项目核准文件，尚未开工建设的，由核准机关撤销核准文件，处项目总投资额1‰以上5‰以下的罚款;已经开工建设的，依照前款规定予以处罚;构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"实行备案管理的项目，企业未依法将项目信息或者已备案项目信息变更情况告知备案机关，或者向备案机关提供虚假信息的，由备案机关责令限期改正;逾期不改正的，处2万元以上5万元以下的罚款。"},{"i":58,"n":"第五十八条","txt":"企业投资建设产业政策禁止投资建设项目的，由县级以上人民政府投资主管部门责令停止建设或者责令停产并恢复原状，对企业处项目总投资额5‰以上10‰以下的罚款;对直接负责的主管人员和其他直接责任人员处5万元以上10万元以下的罚款，属于国家工作人员的，依法给予处分。法律、行政法规另有规定的，依照其规定。"},{"i":59,"n":"第五十九条","txt":"项目单位在项目建设过程中不遵守国土(海洋)资源、城乡规划、环境保护、节能、安全监管、建设等方面法律法规和有关审批文件要求的，相关部门应依法予以处理。"},{"i":60,"n":"第六十条","txt":"承担项目申请报告编写、评估任务的工程咨询评估机构及其人员、参与专家评议的专家，在编制项目申请报告、受项目核准机关委托开展评估或者参与专家评议过程中，违反从业规定，造成重大损失和恶劣影响的，依法降低或撤销工程咨询单位资格，取消主要责任人员的相关职业资格。"},{"i":61,"n":"第六十一条","txt":"本办法所称省级政府包括各省、自治区、直辖市及计划单列市人民政府和新疆生产建设兵团。"},{"i":62,"n":"第六十二条","txt":"外商投资项目和境外投资项目的核准和备案管理办法另行制定。"},{"i":63,"n":"第六十三条","txt":"省级政府和国务院行业管理部门，可以按照《企业投资项目核准和备案管理条例》和本办法的规定，制订具体实施办法。"},{"i":64,"n":"第六十四条","txt":"事业单位、社会团体等非企业组织在中国境内利用自有资金、不申请政府投资建设的固定资产投资项目，按照企业投资项目进行管理。 个人投资建设项目参照本办法的相关规定执行。"},{"i":65,"n":"第六十五条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":66,"n":"第六十六条","txt":"本办法自2017年4月8日起施行。《政府核准投资项目管理办法》(国家发展改革委令第11号)同时废止。"}],"qiyetouzixiangmuhezhunhebeianguanlibanfa":[{"i":1,"n":"第一条","txt":"为落实企业投资自主权，规范政府对企业投资项目的核准和备案行为，实现便利、高效服务和有效管理，依法保护企业合法权益，依据《行政许可法》、《企业投资项目核准和备案管理条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称企业投资项目（以下简称项目），是指企业在中国境内投资建设的固定资产投资项目，包括企业使用自己筹措资金的项目，以及使用自己筹措的资金并申请使用政府投资补助或贷款贴息等的项目。 项目申请使用政府投资补助、贷款贴息的，应在履行核准或备案手续后，提出资金申请报告。"},{"i":3,"n":"第三条","txt":"县级以上人民政府投资主管部门对投资项目履行综合管理职责。 县级以上人民政府其他部门依照法律、法规规定，按照本级政府规定职责分工，对投资项目履行相应管理职责。"},{"i":4,"n":"第四条","txt":"根据项目不同情况，分别实行核准管理或备案管理。 对关系国家安全、涉及全国重大生产力布局、战略性资源开发和重大公共利益等项目，实行核准管理。其他项目实行备案管理。"},{"i":5,"n":"第五条","txt":"实行核准管理的具体项目范围以及核准机关、核准权限，由国务院颁布的《政府核准的投资项目目录》（以下简称《核准目录》）确定。法律、行政法规和国务院对项目核准的范围、权限有专门规定的，从其规定。 《核准目录》由国务院投资主管部门会同有关部门研究提出，报国务院批准后实施，并根据情况适时调整。 未经国务院批准，各部门、各地区不得擅自调整《核准目录》确定的核准范围和权限。"},{"i":6,"n":"第六条","txt":"除国务院另有规定外，实行备案管理的项目按照属地原则备案。 各省级政府负责制定本行政区域内的项目备案管理办法，明确备案机关及其权限。"},{"i":7,"n":"第七条","txt":"依据本办法第五条第一款规定具有项目核准权限的行政机关统称项目核准机关。《核准目录》所称国务院投资主管部门是指国家发展和改革委员会；《核准目录》规定由省级政府、地方政府核准的项目，其具体项目核准机关由省级政府确定。 项目核准机关对项目进行的核准是行政许可事项，实施行政许可所需经费应当由本级财政予以保障。 依据国务院专门规定和省级政府规定具有项目备案权限的行政机关统称项目备案机关。"},{"i":8,"n":"第八条","txt":"项目的市场前景、经济效益、资金来源和产品技术方案等，应当依法由企业自主决策、自担风险，项目核准、备案机关及其他行政机关不得非法干预企业的投资自主权。"},{"i":9,"n":"第九条","txt":"项目核准、备案机关及其工作人员应当依法对项目进行核准或者备案，不得擅自增减审查条件，不得超出办理时限。"},{"i":10,"n":"第十条","txt":"项目核准、备案机关应当遵循便民、高效原则，提高办事效率，提供优质服务。 项目核准、备案机关应当制定并公开服务指南，列明项目核准的申报材料及所需附件、受理方式、审查条件、办理流程、办理时限等;列明项目备案所需信息内容、办理流程等，提高工作透明度，为企业提供指导和服务。"},{"i":11,"n":"第十一条","txt":"县级以上地方人民政府有关部门应当依照相关法律法规和本级政府有关规定，建立健全对项目核准、备案机关的监督制度，加强对项目核准、备案行为的监督检查。 各级政府及其有关部门应当依照相关法律法规及规定对企业从事固定资产投资活动实施监督管理。 任何单位和个人都有权对项目核准、备案、建设实施过程中的违法违规行为向有关部门检举。有关部门应当及时核实、处理。"},{"i":12,"n":"第十二条","txt":"除涉及国家秘密的项目外，项目核准、备案通过全国投资项目在线审批监管平台（以下简称在线平台）实行网上受理、办理、监管和服务，实现核准、备案过程和结果的可查询、可监督。"},{"i":13,"n":"第十三条","txt":"项目核准、备案机关以及其他有关部门统一使用在线平台生成的项目代码办理相关手续。 项目通过在线平台申报时，生成作为该项目整个建设周期身份标识的唯一项目代码。项目的审批信息、监管(处罚)信息，以及工程实施过程中的重要信息，统一汇集至项目代码，并与社会信用体系对接，作为后续监管的基础条件。"},{"i":14,"n":"第十四条","txt":"项目核准、备案机关及有关部门应当通过在线平台公开与项目有关的发展规划、产业政策和准入标准，公开项目核准、备案等事项的办理条件、办理流程、办理时限等。 项目核准、备案机关应根据《政府信息公开条例》有关规定将核准、备案结果予以公开，不得违法违规公开重大工程的关键信息。"},{"i":15,"n":"第十五条","txt":"企业投资建设固定资产投资项目，应当遵守国家法律法规，符合国民经济和社会发展总体规划、专项规划、区域规划、产业政策、市场准入标准、资源开发、能耗与环境管理等要求，依法履行项目核准或者备案及其他相关手续，并依法办理城乡规划、土地（海域）使用、环境保护、能源资源利用、安全生产等相关手续，如实提供相关材料，报告相关信息。"},{"i":16,"n":"第十六条","txt":"对项目核准、备案机关实施的项目核准、备案行为，相关利害关系人有权依法申请行政复议或者提起行政诉讼。"},{"i":17,"n":"第十七条","txt":"企业办理项目核准手续，应当按照国家有关要求编制项目申请报告，取得第二十二条规定依法应当附具的有关文件后，按照本办法第二十三条规定报送。"},{"i":18,"n":"第十八条","txt":"组织编制和报送项目申请报告的项目单位，应当对项目申请报告以及依法应当附具文件的真实性、合法性和完整性负责。"},{"i":19,"n":"第十九条","txt":"项目申请报告应当主要包括以下内容： （一）项目单位情况； （二）拟建项目情况，包括项目名称、建设地点、建设规模、建设内容等； （三）项目资源利用情况分析以及对生态环境的影响分析； （四）项目对经济和社会的影响分析。"},{"i":20,"n":"第二十条","txt":"项目申请报告通用文本由国务院投资主管部门会同有关部门制定,主要行业的项目申请报告示范文本由相应的项目核准机关参照项目申请报告通用文本制定，明确编制内容、深度要求等。"},{"i":21,"n":"第二十一条","txt":"项目申请报告可以由项目单位自行编写，也可以由项目单位自主委托具有相关经验和能力的工程咨询单位编写。任何单位和个人不得强制项目单位委托中介服务机构编制项目申请报告。 项目单位或者其委托的工程咨询单位应当按照项目申请报告通用文本和行业示范文本的要求编写项目申请报告。 工程咨询单位接受委托编制有关文件，应当做到依法、独立、客观、公正，对其编制的文件负责。"},{"i":22,"n":"第二十二条","txt":"项目单位在报送项目申请报告时，应当根据国家法律法规的规定附具以下文件： （一）自然资源主管部门出具的用地（用海）预审与选址意见书； （二）法律、行政法规规定需要办理的其他相关手续。"},{"i":23,"n":"第二十三条","txt":"地方企业投资建设应当分别由国务院投资主管部门、国务院行业管理部门核准的项目，可以分别通过项目所在地省级政府投资主管部门、行业管理部门向国务院投资主管部门、国务院行业管理部门转送项目申请报告。属于国务院投资主管部门核准权限的项目，项目所在地省级政府规定由省级政府行业管理部门转送的，可以由省级政府投资主管部门与其联合报送。 国务院有关部门所属单位、计划单列企业集团、中央管理企业投资建设应当由国务院有关部门核准的项目，直接向相应的项目核准机关报送项目申请报告，并附行业管理部门的意见。 企业投资建设应当由国务院核准的项目，按照本条第一、二款规定向国务院投资主管部门报送项目申请报告，由国务院投资主管部门审核后报国务院核准。新建运输机场项目由相关省级政府直接向国务院、中央军委报送项目申请报告。"},{"i":24,"n":"第二十四条","txt":"企业投资建设应当由地方政府核准的项目，应当按照地方政府的有关规定，向相应的项目核准机关报送项目申请报告。"},{"i":25,"n":"第二十五条","txt":"项目申报材料齐全、符合法定形式的，项目核准机关应当予以受理。 申报材料不齐全或者不符合法定形式的，项目核准机关应当在收到项目申报材料之日起５个工作日内一次告知项目单位补充相关文件，或对相关内容进行调整。逾期不告知的，自收到项目申报材料之日起即为受理。 项目核准机关受理或者不予受理申报材料，都应当出具加盖本机关专用印章并注明日期的书面凭证。对于受理的申报材料，书面凭证应注明项目代码，项目单位可以根据项目代码在线查询、监督核准过程和结果。"},{"i":26,"n":"第二十六条","txt":"项目核准机关在正式受理项目申请报告后，需要评估的，应在４个工作日内按照有关规定委托具有相应资质的工程咨询机构进行评估。项目核准机关在委托评估时，应当根据项目具体情况，提出评估重点，明确评估时限。 工程咨询机构与编制项目申请报告的工程咨询机构为同一单位、存在控股、管理关系或者负责人为同一人的，该工程咨询机构不得承担该项目的评估工作。工程咨询机构与项目单位存在控股、管理关系或者负责人为同一人的，该工程咨询机构不得承担该项目单位的项目评估工作。 除项目情况复杂的，评估时限不得超过30个工作日。接受委托的工程咨询机构应当在项目核准机关规定的时间内提出评估报告，并对评估结论承担责任。项目情况复杂的，履行批准程序后，可以延长评估时限，但延长的期限不得超过60个工作日。 项目核准机关应当将项目评估报告与核准文件一并存档备查。 评估费用由委托评估的项目核准机关承担，评估机构及其工作人员不得收取项目单位"},{"i":27,"n":"第二十七条","txt":"项目涉及有关行业管理部门或者项目所在地地方政府职责的，项目核准机关应当商请有关行业管理部门或地方人民政府在７个工作日内出具书面审查意见。有关行业管理部门或地方人民政府逾期没有反馈书面审查意见的，视为同意。"},{"i":28,"n":"第二十八条","txt":"项目建设可能对公众利益构成重大影响的，项目核准机关在作出核准决定前，应当采取适当方式征求公众意见。 相关部门对直接涉及群众切身利益的用地（用海）、环境影响、移民安置、社会稳定风险等事项已经进行实质性审查并出具了相关审批文件的，项目核准机关可不再就相关内容重复征求公众意见。 对于特别重大的项目，可以实行专家评议制度。除项目情况特别复杂外，专家评议时限原则上不得超过30个工作日。"},{"i":29,"n":"第二十九条","txt":"项目核准机关可以根据评估意见、部门意见和公众意见等，要求项目单位对相关内容进行调整，或者对有关情况和文件做进一步澄清、补充。"},{"i":30,"n":"第三十条","txt":"项目违反相关法律法规，或者不符合发展规划、产业政策和市场准入标准要求的，项目核准机关可以不经过委托评估、征求意见等程序，直接作出不予核准的决定。"},{"i":31,"n":"第三十一条","txt":"项目核准机关应当在正式受理申报材料后２０个工作日内作出是否予以核准的决定，或向上级项目核准机关提出审核意见。项目情况复杂或者需要征求有关单位意见的，经本行政机关主要负责人批准，可以延长核准时限，但延长的时限不得超过40个工作日，并应当将延长期限的理由告知项目单位。 项目核准机关需要委托评估或进行专家评议的，所需时间不计算在前款规定的期限内。项目核准机关应当将咨询评估或专家评议所需时间书面告知项目单位。"},{"i":32,"n":"第三十二条","txt":"项目符合核准条件的，项目核准机关应当对项目予以核准并向项目单位出具项目核准文件。项目不符合核准条件的，项目核准机关应当出具不予核准的书面通知，并说明不予核准的理由。 属于国务院核准权限的项目，由国务院投资主管部门根据国务院的决定向项目单位出具项目核准文件或者不予核准的书面通知。 项目核准机关出具项目核准文件或者不予核准的书面通知应当抄送同级行业管理、城乡规划、国土资源、水行政管理、环境保护、节能审查等相关部门和下级机关。"},{"i":33,"n":"第三十三条","txt":"项目核准文件和不予核准书面通知的格式文本，由国务院投资主管部门制定。"},{"i":34,"n":"第三十四条","txt":"项目核准机关应制定内部工作规则，不断优化工作流程,提高核准工作效率。"},{"i":35,"n":"第三十五条","txt":"项目核准机关应当从以下方面对项目进行审查： （一）是否危害经济安全、社会安全、生态安全等国家安全； （二）是否符合相关发展建设规划、产业政策和技术标准； （三）是否合理开发并有效利用资源； （四）是否对重大公共利益产生不利影响。 项目核准机关应当制定审查工作细则，明确审查具体内容、审查标准、审查要点、注意事项及不当行为需要承担的后果等。"},{"i":36,"n":"第三十六条","txt":"除本办法第二十二条要求提供的项目申请报告附送文件之外，项目单位还应在开工前依法办理其他相关手续。"},{"i":37,"n":"第三十七条","txt":"取得项目核准文件的项目，有下列情形之一的，项目单位应当及时以书面形式向原项目核准机关提出变更申请。原项目核准机关应当自受理申请之日起20个工作日内作出是否同意变更的书面决定： （一）建设地点发生变更的； （二）投资规模、建设规模、建设内容发生较大变化的； （三）项目变更可能对经济、社会、环境等产生重大不利影响的； （四）需要对项目核准文件所规定的内容进行调整的其他重大情形。"},{"i":38,"n":"第三十八条","txt":"项目自核准机关出具项目核准文件或同意项目变更决定２年内未开工建设，需要延期开工建设的，项目单位应当在2年期限届满的30个工作日前，向项目核准机关申请延期开工建设。项目核准机关应当自受理申请之日起20个工作日内，作出是否同意延期开工建设的决定，并出具相应文件。开工建设只能延期一次，期限最长不得超过1年。国家对项目延期开工建设另有规定的，依照其规定。 在2年期限内未开工建设也未按照规定向项目核准机关申请延期的，项目核准文件或同意项目变更决定自动失效。"},{"i":39,"n":"第三十九条","txt":"实行备案管理的项目，项目单位应当在开工建设前通过在线平台将相关信息告知项目备案机关，依法履行投资项目信息告知义务，并遵循诚信和规范原则。"},{"i":40,"n":"第四十条","txt":"项目备案机关应当制定项目备案基本信息格式文本，具体包括以下内容： （一）项目单位基本情况； （二）项目名称、建设地点、建设规模、建设内容； （三）项目总投资额； （四）项目符合产业政策声明。 项目单位应当对备案项目信息的真实性、合法性和完整性负责。"},{"i":41,"n":"第四十一条","txt":"项目备案机关收到本办法第四十条规定的全部信息即为备案。项目备案信息不完整的，备案机关应当及时以适当方式提醒和指导项目单位补正。 项目备案机关发现项目属产业政策禁止投资建设或者依法应实行核准管理，以及不属于固定资产投资项目、依法应实施审批管理、不属于本备案机关权限等情形的，应当通过在线平台及时告知企业予以纠正或者依法申请办理相关手续。"},{"i":42,"n":"第四十二条","txt":"项目备案相关信息通过在线平台在相关部门之间实现互通共享。 项目单位需要备案证明的，可以通过在线平台自行打印或者要求备案机关出具。"},{"i":43,"n":"第四十三条","txt":"项目备案后，项目法人发生变化，项目建设地点、规模、内容发生重大变更，或者放弃项目建设的，项目单位应当通过在线平台及时告知项目备案机关，并修改相关信息。"},{"i":44,"n":"第四十四条","txt":"实行备案管理的项目，项目单位在开工建设前还应当根据相关法律法规规定办理其他相关手续。"},{"i":45,"n":"第四十五条","txt":"上级项目核准、备案机关应当加强对下级项目核准、备案机关的指导和监督，及时纠正项目管理中存在的违法违规行为。"},{"i":46,"n":"第四十六条","txt":"项目核准和备案机关、行业管理、城乡规划（建设）、国家安全、国土（海洋）资源、环境保护、节能审查、金融监管、安全生产监管、审计等部门，应当按照谁审批谁监管、谁主管谁监管的原则，采取在线监测、现场核查等方式，依法加强对项目的事中事后监管。 项目核准、备案机关应当根据法律法规和发展规划、产业政策、总量控制目标、技术政策、准入标准及相关环保要求等，对项目进行监管。 城乡规划、国土（海洋）资源、环境保护、节能审查、安全监管、建设、行业管理等部门，应当履行法律法规赋予的监管职责，在各自职责范围内对项目进行监管。 金融监管部门应当加强指导和监督，引导金融机构按照商业原则，依法独立审贷。 审计部门应当依法加强对国有企业投资项目、申请使用政府投资资金的项目以及其他公共工程项目的审计监督。"},{"i":47,"n":"第四十七条","txt":"各级地方政府有关部门应按照相关法律法规及职责分工，加强对本行政区域内项目的监督检查，发现违法违规行为的，应当依法予以处理，并通过在线平台登记相关违法违规信息。"},{"i":48,"n":"第四十八条","txt":"对不符合法定条件的项目予以核准，或者超越法定职权予以核准的，应依法予以撤销。"},{"i":49,"n":"第四十九条","txt":"各级项目核准、备案机关的项目核准或备案信息，以及国土（海洋）资源、城乡规划、水行政管理、环境保护、节能审查、安全监管、建设、工商等部门的相关手续办理信息、审批结果信息、监管（处罚）信息，应当通过在线平台实现互通共享。"},{"i":50,"n":"第五十条","txt":"项目单位应当通过在线平台如实报送项目开工建设、建设进度、竣工的基本信息。 项目开工前，项目单位应当登录在线平台报备项目开工基本信息。项目开工后，项目单位应当按年度在线报备项目建设动态进度基本信息。项目竣工验收后，项目单位应当在线报备项目竣工基本信息。"},{"i":51,"n":"第五十一条","txt":"项目单位有下列行为之一的，相关信息列入项目异常信用记录，并纳入全国信用信息共享平台： （一）应申请办理项目核准但未依法取得核准文件的； （二）提供虚假项目核准或备案信息，或者未依法将项目信息告知备案机关，或者已备案项目信息变更未告知备案机关的； （三）违反法律法规擅自开工建设的； （四）不按照批准内容组织实施的； （五）项目单位未按本办法第五十条规定报送项目开工建设、建设进度、竣工等基本信息，或者报送虚假信息的； （六）其他违法违规行为。"},{"i":52,"n":"第五十二条","txt":"项目核准、备案机关有下列情形之一的，由其上级行政机关责令改正，对负有责任的领导人员和直接责任人员由有关单位和部门依纪依法给予处分： （一）超越法定职权予以核准或备案的； （二）对不符合法定条件的项目予以核准的； （三）对符合法定条件的项目不予核准的； （四）擅自增减核准审查条件的，或者以备案名义变相审批、核准的； （五）不在法定期限内作出核准决定的； （六）不依法履行监管职责或者监督不力，造成严重后果的。"},{"i":53,"n":"第五十三条","txt":"项目核准、备案机关及其工作人员，以及其他相关部门及其工作人员，在项目核准、备案以及相关审批手续办理过程中玩忽职守、滥用职权、徇私舞弊、索贿受贿的，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"项目核准、备案机关，以及国土（海洋）资源、城乡规划、水行政管理、环境保护、节能审查、安全监管、建设等部门违反相关法律法规规定，未依法履行监管职责的，对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。 项目所在地的地方政府有关部门不履行企业投资监管职责的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":55,"n":"第五十五条","txt":"企业以分拆项目、隐瞒有关情况或者提供虚假申报材料等不正当手段申请核准、备案的，项目核准机关不予受理或者不予核准、备案，并给予警告。"},{"i":56,"n":"第五十六条","txt":"实行核准管理的项目，企业未依法办理核准手续开工建设或者未按照核准的建设地点、建设规模、建设内容等进行建设的，由核准机关责令停止建设或者责令停产，对企业处项目总投资额1‰以上5‰以下的罚款；对直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款，属于国家工作人员的，依法给予处分。项目应视情况予以拆除或者补办相关手续。 以欺骗、贿赂等不正当手段取得项目核准文件，尚未开工建设的，由核准机关撤销核准文件，处项目总投资额1‰以上5‰以下的罚款；已经开工建设的，依照前款规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"实行备案管理的项目，企业未依法将项目信息或者已备案项目信息变更情况告知备案机关，或者向备案机关提供虚假信息的，由备案机关责令限期改正；逾期不改正的，处2万元以上5万元以下的罚款。"},{"i":58,"n":"第五十八条","txt":"企业投资建设产业政策禁止投资建设项目的，由县级以上人民政府投资主管部门责令停止建设或者责令停产并恢复原状，对企业处项目总投资额5‰以上10‰以下的罚款；对直接负责的主管人员和其他直接责任人员处5万元以上10万元以下的罚款，属于国家工作人员的，依法给予处分。法律、行政法规另有规定的，依照其规定。"},{"i":59,"n":"第五十九条","txt":"项目单位在项目建设过程中不遵守国土（海洋）资源、城乡规划、环境保护、节能、安全监管、建设等方面法律法规和有关审批文件要求的，相关部门应依法予以处理。"},{"i":60,"n":"第六十条","txt":"承担项目申请报告编写、评估任务的工程咨询评估机构及其人员、参与专家评议的专家，在编制项目申请报告、受项目核准机关委托开展评估或者参与专家评议过程中，违反从业规定，造成重大损失和恶劣影响的，依法降低或撤销工程咨询单位资格，取消主要责任人员的相关职业资格。"},{"i":61,"n":"第六十一条","txt":"本办法所称省级政府包括各省、自治区、直辖市及计划单列市人民政府和新疆生产建设兵团。"},{"i":62,"n":"第六十二条","txt":"外商投资项目和境外投资项目的核准和备案管理办法另行制定。"},{"i":63,"n":"第六十三条","txt":"省级政府和国务院行业管理部门，可以按照《企业投资项目核准和备案管理条例》和本办法的规定，制订具体实施办法。"},{"i":64,"n":"第六十四条","txt":"事业单位、社会团体等非企业组织在中国境内利用自有资金、不申请政府投资建设的固定资产投资项目，按照企业投资项目进行管理。 个人投资建设项目参照本办法的相关规定执行。"},{"i":65,"n":"第六十五条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":66,"n":"第六十六条","txt":"本办法自2017年4月8日起施行。《政府核准投资项目管理办法》（国家发展改革委令第11号）同时废止。"}],"gongyongdianjianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强电力供应与使用的监督管理，根据《电力供应与使用条例》第三十六条规定，制定本办法。"},{"i":2,"n":"第二条","txt":"从事供用电监督管理的机构和人员，在执行监督检查任务时，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"供用电监督管理必须以事实为依据，以电力法律和行政法规以及电力技术标准为准则，遵循本办法的规定进行。"},{"i":4,"n":"第四条","txt":"县以上电力管理部门负责本行政区域内供电、用电的监督工作。但上级电力管理部门认为工作必需，可指派供用电监督人员直接进行监督检查。"},{"i":5,"n":"第五条","txt":"供用电监督管理的职责是： 1.宣传、普及电力法律和行政法规知识； 2.监督电力法律、行政法规和电力技术标准的执行； 3.监督国家有关电力供应与使用政策、方针的执行； 4.协调处理供用电纠纷，依法保护电力投资者、供应者与使用者的合法权益； 5.协助司法机关查处电力供应与使用中发生的治安、刑事案件； 6.依法查处电力违法行为，并作出行政处罚。"},{"i":6,"n":"第六条","txt":"供用电监督人员在依法执行监督检查公务时，不得少于两人，应出示行政执法证。被检查的单位应接受检查，并根据监督人员依法提出的要求，提供有关情况、回答有关询问、协助提取证据、出示工作证件等。"},{"i":7,"n":"第七条","txt":"供用电监督人员依法执行监督公务时，应遵守被检查单位的保卫保密规定；现场勘查不得直接或替代他人从事电工作业，也不得非法干预被检查单位正常的生产调度工作。"},{"i":8,"n":"第八条","txt":"各级电力管理部门应依法配备供用电监督管理人员。担任供用电监督管理工作的人员应具备相应的专业技术能力和行政执法资格。"},{"i":9,"n":"第九条","txt":"省级电力管理部门负责本行政区域内供用电监督管理人员的资格审查和专门知识及技能的培训工作。县级以上电力管理部门可依法委托供用电监督协助人员。"},{"i":10,"n":"第十条","txt":"各级电力管理部门负责本行政区域内发生的电力违法行为查处工作。上级电力管理部门认为必要时，可直接查处下级电力管理部门管辖的电力违法行为，也可将自己查处的电力违法事件交由下级电力管理部门查处。对电力违法行为情节复杂，需由上一级电力管理部门查处更为适宜时，下级电力管理部门可报请上一级电力管理部门查处。"},{"i":11,"n":"第十一条","txt":"电力管理部门对下列方式要求处理的电力违法事件，应当受理： 1.用户或群众举报的； 2.供电企业提请处理的； 3.上级电力管理部门交办的； 4.其他部门移送的。 电力管理部门对受理的电力违法事件，可视电力违法事件性质和危及电网安全运行的紧迫程度，可依法在现场查处，也可立案处理。"},{"i":12,"n":"第十二条","txt":"电力违法行为，可用书面和口头方式举报。口头方式举报的事件，受理人应详细记录并经核对无误后，由举报人签章。举报人举报的事件如不愿使用真实姓名的，电力管理部门应尊重举报人的意愿。"},{"i":13,"n":"第十三条","txt":"电力管理部门发现受理的举报事件不属于本部门查处的，应及时向举报人说明，同时将举报信函或笔录移送有权处理的部门。对明显的治安违法行为或刑事违法行为，电力管理部门应主动协助公安、司法机关查处。"},{"i":14,"n":"第十四条","txt":"电力管理部门对危及电网运行安全或人身安全的违法行为，当供电企业在现场制止无效时，应当即指派供用电监督人员赶赴现场处理，制止违法行为，以确保电网和人身安全。"},{"i":15,"n":"第十五条","txt":"对涉嫌电力违法行为的查处应符合行政处罚法及有关规定。当事人对行政处罚决定不服的，有权依法申请行政复议或提起行政诉讼。当事人逾期不履行行政处罚决定的，作出行政处罚决定的电力管理部门可以依法向人民法院申请强制执行。"},{"i":16,"n":"第十六条","txt":"违反《电力法》和国家有关规定，未取得相应类别电力业务许可证而从事电力供应业务者，电力管理部门应以书面形式责令其停止营业，没收其违法所得，并处以违法所得五倍以下的罚款。"},{"i":17,"n":"第十七条","txt":"违反《电力法》和国家有关规定，擅自伸入或跨越其他供电企业供电营业区供电者，电力管理部门应以书面形式责令其拆除伸入或跨越的供电设施，没收其违法所得，并处以违法所得四倍以下的罚款。"},{"i":18,"n":"第十八条","txt":"违反《电力法》和国家有关规定，擅自向外转供电者，电力管理部门应以书面形式责令其拆除转供电设施，没收其违法所得，并处以违法所得三倍以下的罚款。"},{"i":19,"n":"第十九条","txt":"电力管理部门对危害供电、用电安全，扰乱正常供电、用电秩序的行为，除协助供电企业追缴电费外，应分别给予下列处罚： 1.擅自改变用电类别的，应责令其改正，给予警告；再次发生的，可下达中止供电命令。 2.擅自超过合同约定的容量用电的，应责令其改正，给予警告；拒绝改正的，可下达中止供电命令。 3.擅自使用已经在供电企业办理暂停使用手续的电力设备，或者擅自启用已经被供电企业查封的电力设备的，应责令其改正，给予警告；启用电力设备危及电网安全的，可下达中止供电命令。 4.擅自迁移、更动或者擅自操作供电企业的用电计量装置、电力负荷控制装置、供电设施以及约定由供电企业调度的用户受电设备，且不构成窃电和超指标用电的，应责令其改正，给予警告；造成他人损害的，还应责令其赔偿，危及电网安全的，可下达中止供电命令。 5. 未经供电企业许可，擅自引入、供出电力或者将自备电源擅自并网的，应责令其改正，给予警告；拒绝改"},{"i":20,"n":"第二十条","txt":"电力管理部门对盗窃电能的行为，应责令其停止违法行为，并处以应交电费五倍以下的罚款；构成违反治安管理行为的，由公安机关依照治安管理处罚法的有关规定予以处罚；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"本办法自一九九六年九月一日起施行。"}],"gongdianjianguanbanfa":[{"i":1,"n":"第一条","txt":"为了加强供电监管，规范供电行为，维护供电市场秩序，保护电力使用者的合法权益和社会公共利益，根据《电力监管条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家能源局依照本办法和国家有关规定，履行全国供电监管和行政执法职能。 国家能源局派出机构（以下简称派出机构）负责辖区内供电监管和行政执法工作。"},{"i":3,"n":"第三条","txt":"供电监管应当依法进行，并遵循公开、公正和效率的原则。"},{"i":4,"n":"第四条","txt":"供电企业应当依法从事供电业务，并接受国家能源局及其派出机构（以下简称电力监管机构）的监管。供电企业依法经营，其合法权益受法律保护。 本办法所称供电企业是指依法取得电力业务许可证、从事供电业务的企业。"},{"i":5,"n":"第五条","txt":"任何单位和个人对供电企业违反本办法和国家有关供电监管规定的行为，有权向电力监管机构投诉和举报，电力监管机构应当依法处理。"},{"i":6,"n":"第六条","txt":"电力监管机构对供电企业的供电能力实施监管。 供电企业应当加强供电设施建设，具有能够满足其供电区域内用电需求的供电能力，保障供电设施的正常运行。"},{"i":7,"n":"第七条","txt":"电力监管机构对供电企业的供电质量实施监管。 在电力系统正常的情况下，供电企业的供电质量应当符合下列规定： (一)向用户提供的电能质量符合国家标准或者电力行业标准; (二)城市地区年供电可靠率不低于99%，城市居民用户受电端电压合格率不低于95%，10千伏以上供电用户受电端电压合格率不低于98%; (三)农村地区年供电可靠率和农村居民用户受电端电压合格率符合派出机构的规定。派出机构有关农村地区年供电可靠率和农村居民用户受电端电压合格率的规定，应当报国家能源局备案。 供电企业应当审核用电设施产生谐波、冲击负荷的情况，按照国家有关规定拒绝不符合规定的用电设施接入电网。用电设施产生谐波、冲击负荷影响供电质量或者干扰电力系统安全运行的，供电企业应当及时告知用户采取有效措施予以消除;用户不采取措施或者采取措施不力，产生的谐波、冲击负荷仍超过国家标准的，供电企业可以按照国家有关规定拒绝其接入电网或者"},{"i":8,"n":"第八条","txt":"电力监管机构对供电企业设置电压监测点的情况实施监管。 供电企业应当按照下列规定选择电压监测点： (一)35千伏专线供电用户和110千伏以上供电用户应当设置电压监测点; (二)35千伏非专线供电用户或者66千伏供电用户、10(6、20)千伏供电用户，每10000千瓦负荷选择具有代表性的用户设置1个以上电压监测点，所选用户应当包括对供电质量有较高要求的重要电力用户和变电站10(6、20)千伏母线所带具有代表性线路的末端用户; (三)低压供电用户，每百台配电变压器选择具有代表性的用户设置1个以上电压监测点，所选用户应当是重要电力用户和低压配电网的首末两端用户。 供电企业应当按照国家有关规定选择、安装、校验电压监测装置，监测和统计用户电压情况。监测数据和统计数据应当及时、真实、完整，并按照要求及时报送电力监管机构。"},{"i":9,"n":"第九条","txt":"电力监管机构对供电企业保障供电安全的情况实施监管。 供电企业应当坚持安全第一、预防为主、综合治理的方针，遵守有关供电安全的法律、法规和规章，加强供电安全管理，建立、健全供电安全责任制度，完善安全供电条件，维护电力系统安全稳定运行，依法处置供电突发事件，保障电力稳定、可靠供应。 供电企业应当按照国家有关规定加强重要电力用户安全供电管理，指导重要电力用户配置和使用自备应急电源，建立自备应急电源基础档案数据库。 供电企业发现用电设施存在安全隐患，应当及时告知用户采取有效措施进行治理。用户应当按照国家有关规定消除用电设施安全隐患。用电设施存在严重威胁电力系统安全运行和人身安全的隐患，用户拒不治理的，供电企业可以按照国家有关规定对该用户中止供电。"},{"i":10,"n":"第十条","txt":"电力监管机构对供电企业履行电力社会普遍服务义务的情况实施监管。 供电企业应当按照国家规定履行电力社会普遍服务义务，依法保障任何人能够按照国家规定的价格获得最基本的供电服务。"},{"i":11,"n":"第十一条","txt":"电力监管机构对供电企业办理用电业务的情况实施监管。 供电企业应当按照国家规定的流程、时限等要求为用户提供便捷高效的用电报装服务。"},{"i":12,"n":"第十二条","txt":"电力监管机构对供电企业向用户受电工程提供服务的情况实施监管。 供电企业应当对用户受电工程建设提供必要的业务咨询和技术标准咨询;对用户受电工程进行中间检查和竣工检验，应当执行国家有关标准;发现用户受电设施存在故障隐患时，应当及时一次性书面告知用户并指导其予以消除;发现用户受电设施存在严重威胁电力系统安全运行和人身安全的隐患时，应当指导其立即消除，在隐患消除前不得送电。"},{"i":13,"n":"第十三条","txt":"电力监管机构对供电企业实施停电、限电或者中止供电的情况进行监管。 在电力系统正常的情况下，供电企业应当连续向用户供电。需要停电或者限电的，应当符合下列规定： (一)因供电设施计划检修需要停电的，供电企业应当提前7日公告停电区域、停电线路、停电时间; (二)因供电设施临时检修需要停电的，供电企业应当提前24小时公告停电区域、停电线路、停电时间; (三)因电网发生故障或者电力供需紧张等原因需要停电、限电的，供电企业应当按照所在地人民政府批准的有序用电方案或者事故应急处置方案执行。 引起停电或者限电的原因消除后，供电企业应当尽快恢复正常供电。 供电企业对用户中止供电应当按照国家有关规定执行。 供电企业对重要电力用户实施停电、限电、中止供电或者恢复供电，应当按照国家有关规定执行。"},{"i":14,"n":"第十四条","txt":"电力监管机构对供电企业处理供电故障的情况实施监管。 供电企业应当建立完善的报修服务制度，公开报修电话，保持电话畅通，24小时受理供电故障报修。 供电企业应当迅速组织人员处理供电故障，尽快恢复正常供电。供电企业工作人员到达现场抢修的时限，自接到报修之时起，城区范围不超过60分钟，农村地区不超过120分钟，边远、交通不便地区不超过240分钟。因天气、交通等特殊原因无法在规定时限内到达现场的，应当向用户做出解释。"},{"i":15,"n":"第十五条","txt":"电力监管机构对供电企业履行紧急供电义务的情况实施监管。 因抢险救灾、突发事件需要紧急供电时，供电企业应当及时提供电力供应。"},{"i":16,"n":"第十六条","txt":"电力监管机构对供电企业处理用电投诉的情况实施监管。 供电企业应当建立用电投诉处理制度，公开投诉电话。对用户的投诉，供电企业应当自接到投诉之日起10个工作日内提出处理意见并答复用户。 供电企业应当在供电营业场所设置公布电力服务热线电话和电力监管投诉举报电话的标识，该标识应当固定在供电营业场所的显著位置。"},{"i":17,"n":"第十七条","txt":"电力监管机构对供电企业执行国家有关电力行政许可规定的情况实施监管。 供电企业应当遵守国家有关供电营业区、供电业务许可和承装（修、试）电力设施许可等规定。"},{"i":18,"n":"第十八条","txt":"电力监管机构对供电企业公平、无歧视开放供电市场的情况实施监管。 供电企业不得从事下列行为： (一)无正当理由拒绝用户用电申请; (二)对趸购转售电企业符合国家规定条件的输配电设施，拒绝或者拖延接入系统; (三)违反市场竞争规则，以不正当手段损害竞争对手的商业信誉或者排挤竞争对手; (四)对用户受电工程指定设计单位、施工单位和设备材料供应单位; (五)其他违反国家有关公平竞争规定的行为。"},{"i":19,"n":"第十九条","txt":"电力监管机构对供电企业执行国家规定的电价政策和收费标准的情况实施监管。 供电企业应当严格执行国家电价政策，按照国家核准电价或者市场交易价，依据计量检定机构依法认可的用电计量装置的记录，向用户计收电费。 供电企业不得自定电价，不得擅自变更电价，不得擅自在电费中加收或者代收国家政策规定以外的其他费用。 供电企业不得自立项目或者自定标准收费;对国家已经明令取缔的收费项目，不得向用户收取费用。 供电企业应用户要求对产权属于用户的电气设备提供有偿服务时，应当执行政府定价或者政府指导价。没有政府定价和政府指导价的，参照市场价格协商确定。"},{"i":20,"n":"第二十条","txt":"电力监管机构对供电企业签订供用电合同的情况实施监管。 供电企业应当按照国家有关规定，遵循平等自愿、协商一致、诚实信用的原则，与用户、趸购转售电单位签订供用电合同，并按照合同约定供电。"},{"i":21,"n":"第二十一条","txt":"电力监管机构对供电企业执行国家规定的成本规则的情况实施监管。 供电企业应当按照国家有关成本的规定核算成本。"},{"i":22,"n":"第二十二条","txt":"电力监管机构对供电企业信息公开的情况实施监管。 供电企业应当按照国家有关规定，采取便于用户获取的方式，公开供电服务信息。供电企业公开信息应当真实、及时、完整。 供电企业应当方便用户查询下列信息： (一)用电报装信息和办理进度; (二)用电投诉处理情况; (三)其他用电信息。"},{"i":23,"n":"第二十三条","txt":"电力监管机构对供电企业报送信息的情况实施监管。 供电企业应当按照《电力企业信息报送规定》向电力监管机构报送信息。供电企业报送信息应当真实、及时、完整。"},{"i":24,"n":"第二十四条","txt":"电力监管机构对供电企业执行国家有关节能减排和环境保护政策的情况实施监管。 供电企业应当减少电能输送和供应环节的损失和浪费。 供电企业应当严格执行政府有关部门依法作出的对淘汰企业、关停企业或者环境违法企业采取停限电措施的决定。未收到政府有关部门决定恢复送电的通知，供电企业不得擅自对政府有关部门责令限期整改的用户恢复送电。"},{"i":25,"n":"第二十五条","txt":"电力监管机构对供电企业实施电力需求侧管理的情况实施监管。 供电企业应当按照国家有关电力需求侧管理规定，采取有效措施，指导用户科学、合理和节约用电，提高电能使用效率。"},{"i":26,"n":"第二十六条","txt":"电力监管机构根据履行监管职责的需要，可以要求供电企业报送与监管事项相关的文件、资料，并责令供电企业按照国家规定如实公开有关信息。 电力监管机构应当对供电企业报送信息和公开信息的情况进行监督检查，发现违法行为及时处理。"},{"i":27,"n":"第二十七条","txt":"供电企业应当按照电力监管机构的规定将与监管相关的信息系统接入电力监管信息系统。"},{"i":28,"n":"第二十八条","txt":"电力监管机构依法履行职责，可以采取下列措施，进行现场检查： (一)进入供电企业进行检查; (二)询问供电企业的工作人员，要求其对有关检查事项作出说明; (三)查阅、复制与检查事项有关的文件、资料，对可能被转移、隐匿、损毁的文件、资料予以封存; (四)对检查中发现的违法行为，可以当场予以纠正或者要求限期改正。"},{"i":29,"n":"第二十九条","txt":"电力监管机构可以在用户中依法开展供电满意度调查等供电情况调查，并向社会公布调查结果。"},{"i":30,"n":"第三十条","txt":"供电企业违反国家有关供电监管规定的，电力监管机构应当依法查处并予以记录;造成重大损失或者重大影响的，电力监管机构可以对供电企业的主管人员和其他直接责任人员依法提出处理意见和建议。"},{"i":31,"n":"第三十一条","txt":"电力监管机构对供电企业违反国家有关供电监管规定，损害用户合法权益和社会公共利益的行为及其处理情况，可以向社会公布。"},{"i":32,"n":"第三十二条","txt":"电力监管机构从事监管工作的人员违反电力监管有关规定，损害供电企业、用户的合法权益以及社会公共利益的，依照国家有关规定追究其责任;应当承担纪律责任的，依法给予处分;构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"供电企业违反本办法第六条规定，没有能力对其供电区域内的用户提供供电服务并造成严重后果的，电力监管机构可以吊销电力业务许可证，指定其他供电企业供电。"},{"i":34,"n":"第三十四条","txt":"供电企业违反本办法第七条、第八条、第九条、第十条、第十一条、第十二条、第十三条、第十四条、第十五条、第十六条、第二十一条、第二十四条规定的，由电力监管机构责令改正，给予警告;情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":35,"n":"第三十五条","txt":"供电企业违反本办法第十八条规定，由电力监管机构责令改正，拒不改正的，处10万元以上100万元以下罚款;对直接负责的主管人员和其他直接责任人员，依法给予处分;情节严重的，可以吊销电力业务许可证。"},{"i":36,"n":"第三十六条","txt":"供电企业违反本办法第十九条规定的，电力监管机构可以责令改正并向有关部门提出行政处罚建议。"},{"i":37,"n":"第三十七条","txt":"供电企业有下列情形之一的，由电力监管机构责令改正;拒不改正的，处5万元以上50万元以下罚款，对直接负责的主管人员和其他直接责任人员，依法给予处分;构成犯罪的，依法追究刑事责任： (一)拒绝或者阻碍电力监管机构及其从事监管工作的人员依法履行监管职责的; (二)提供虚假或者隐瞒重要事实的文件、资料的; (三)未按照国家有关电力监管规章、规则的规定公开有关信息的。"},{"i":38,"n":"第三十八条","txt":"对于违反本办法并造成严重后果的供电企业主管人员或者直接责任人员，电力监管机构可以建议将其调离现任岗位，3年内不得担任供电企业同类职务。"},{"i":39,"n":"第三十九条","txt":"本办法所称以上、以下、不低于、不超过，包括本数。"},{"i":40,"n":"第四十条","txt":"本办法自2010年1月1日起施行。2005年6月21日电监会发布的《供电服务监管办法(试行)》同时废止。"}],"gongdianyingyequhuafenjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为划分和管理供电营业区，依法保障电力供应的专营权，保障用户供电安全，保护用户合法权益，根据《中华人民共和国行政许可法》《中华人民共和国电力法》《电力供应与使用条例》《电力监管条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"供电营业区是指向用户供应电力的地域。经国家审查批准的供电营业区是供电企业依法专营电力的地域。"},{"i":3,"n":"第三条","txt":"国家对供电营业区的设立、变更实行许可证管理制度。供电企业应按规定申请供电营业区划分，并取得电力业务许可证。 电力业务许可证由国家能源局统一印制。"},{"i":4,"n":"第四条","txt":"根据电力生产供应特点，为确保电网安全经济运行和供电服务质量，在一个供电营业区内，只准设一个供电营业机构。供电营业区划分及供电营业分支机构设置应当根据国家电力安全保供的需要和相关政策要求进行动态调整。"},{"i":5,"n":"第五条","txt":"供电营业区原则上以省、地（市）、县行政区划为基础，根据电网结构、供电能力、供电质量、供电经济合理性等因素划分确定。 在《中华人民共和国电力法》实施前，同一个行政区域内已形成多个供电企业供电的，应按上述原则协商核定其供电营业区。"},{"i":6,"n":"第六条","txt":"供电营业区（不含增量配电区域）分为下列三类： （一）省（自治区、直辖市）内跨地（市）行政区划的供电营业区（简称省级营业区）； （二）地（自治州、省辖市）内跨县行政区划的供电营业区（简称地级营业区）； （三）县（市）内跨乡镇行政区划的供电营业区（简称县级营业区）。"},{"i":7,"n":"第七条","txt":"为便于分级管理，根据电网结构和行政区划不同，一般可将省级营业区分划为地、县两级营业区；地级营业区分划为若干个县级营业区，并根据实际需求在每级营业区内设立相应的供电营业分支机构。 对公用电网未覆盖的地区，其供电营业区划分另行规定。"},{"i":8,"n":"第八条","txt":"供电营业区的设立、变更，由国家能源局派出机构依据职责和管理权限，会同省级电力管理部门审查批准后，发给电力业务许可证。"},{"i":9,"n":"第九条","txt":"申请供电营业区者，须具备下列条件： （一）具有独立企业法人资格（不具有法人资格的，按照隶属关系由其法人企业提出申请）； （二）具有保障该地区用电需求的供电能力； （三）具有与经营业务相适应的资金、场所、设施和技术手段； （四）具有与经营业务相适应的专门技术与业务人员、管理制度、技术标准； （五）具有与该地区社会与经济发展相适应的电网改造和发展规划； （六）法律法规规定的其他条件。"},{"i":10,"n":"第十条","txt":"申请供电营业区者，应向国家能源局派出机构提供下列资料： （一）能反映营业区边界的供电区域地理平面图； （二）设立的供电营业分支机构及相应的供电营业区域； （三）电源容量及分布、供电网络及负荷分布图； （四）经政府主管部门批准的电网改造与发展规划； （五）企业性质、组织机构、人员构成及数量、主要技术业务人员资格； （六）保证安全生产必需的基础设施、工机具、计量、试验、调度、通讯及交通运输装备； （七）技术业务的规章制度； （八）供电营业区双边达成的划分协议； （九）《电力业务许可证管理规定》规定的其他资料。"},{"i":11,"n":"第十一条","txt":"供电企业在申请供电营业区前，应就供电营业区的划分，与相邻供电企业进行协商，达成协议。 有关双方对营业区划分未取得一致意见的，由国家能源局派出机构会同省级电力管理部门协调解决。"},{"i":12,"n":"第十二条","txt":"由于历史原因，多个电网已形成交叉供电的营业区域，有关各方应从确保供用电安全出发，本着互利互惠原则，协商确定供电营业区。协商不成的，由国家能源局派出机构会同省级电力管理部门协调划定。"},{"i":13,"n":"第十三条","txt":"国家能源局派出机构应当会同省级电力管理部门对申请人提交的材料进行审查，按照《电力业务许可证管理规定》相关要求作出许可决定。"},{"i":14,"n":"第十四条","txt":"供电企业对电力业务许可证明确的供电营业区有异议的，应在自知道或者应当知道之日起30日内向国家能源局提出复核请求。国家能源局应在接到复核请求之日后60日内作出复核决定。"},{"i":15,"n":"第十五条","txt":"取得电力业务许可证的供电企业，应当按照国家规定承担本营业区内的供电义务，依法保障供区电力用户能够按照国家规定的价格获得最基本的供电服务。"},{"i":16,"n":"第十六条","txt":"除经国家能源局派出机构、省级电力管理部门同意向其他供电企业供电营业区内用户实施的供电情形外，供电企业不得超越电力业务许可证明确的供电营业区供电。"},{"i":17,"n":"第十七条","txt":"由于政治、军事、安全等原因，对供电质量有特殊要求或者用电对供电质量产生严重影响的用户，可由国家能源局派出机构、省级电力管理部门指定的供电企业供电。"},{"i":18,"n":"第十八条","txt":"取得电力业务许可证的供电企业，因自身原因没有能力对其供电营业区内的用户提供符合国家规定的供电服务，且限期整改后仍不符合要求并造成严重后果的，国家能源局派出机构会同省级电力管理部门协商后，可缩减其供电营业区。"},{"i":19,"n":"第十九条","txt":"供电营业区的扩展或者合并、缩小、分立等变更，应向国家能源局派出机构提供下列资料： （一）变更理由及有关证明文件； （二）与相邻供电企业就供电营业区变更达成的协议； （三）供电营业区变动的地理平面图； （四）《电力业务许可证管理规定》规定的其他资料。"},{"i":20,"n":"第二十条","txt":"供电企业因破产或者其他原因需要停业时，必须在停业前一个月同时向国家能源局派出机构和省级电力管理部门报告，经批准并确定接续的供电企业后，方可停业，并办理电力业务许可证注销手续。"},{"i":21,"n":"第二十一条","txt":"用户燃煤自备电厂应自发自供其所在厂区内的用电，剩余电量如需上网，应按照交易规则参与市场化交易。 分布式、源网荷储等其他项目剩余电量上网按国家有关规定执行。"},{"i":22,"n":"第二十二条","txt":"未经许可从事电力供应业务，或者擅自变更供电营业区的，按照《中华人民共和国行政许可法》《中华人民共和国电力法》有关规定处理。"},{"i":23,"n":"第二十三条","txt":"有关增量配电业务配电区域划分办法另行制定。"},{"i":24,"n":"第二十四条","txt":"国家能源局对本办法实施情况进行定期评估，并适时调整完善。"},{"i":25,"n":"第二十五条","txt":"本办法自2024年7月1日起施行。原电力工业部于1996年5月19日发布的《供电营业区划分及管理办法》（电力工业部令第5号）同时废止。"}],"gongdianyingyeguize":[{"i":1,"n":"第一条","txt":"为加强供电营业管理，建立正常的供电营业秩序，保障供用双方的合法权益，依照《电力供应与使用条例》和国家有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"供电企业和用户在进行电力供应与使用活动中，应当遵守本规则的规定。"},{"i":3,"n":"第三条","txt":"供电企业和用户应当遵守国家有关规定，服从电网统一调度。"},{"i":4,"n":"第四条","txt":"供电企业应当无歧视地向用户提供供电服务并按照电力体制改革的要求和电力市场交易规则履行相应的服务责任。"},{"i":5,"n":"第五条","txt":"供电企业应当按照国家信息公开有关规定，主动公开与供用电相关的政策制度、服务标准、投诉或监督渠道等信息。 本规则应当通过供电企业的供电营业场所及各类线上服务渠道公开，供用户查阅。"},{"i":6,"n":"第六条","txt":"供电企业供电的额定频率为交流50赫兹。"},{"i":7,"n":"第七条","txt":"供电企业供电的额定电压： （一）低压供电：单相为220伏，三相三线为380伏，三相四线为380/220伏； （二）高压供电：为10（6、20）、35、110（66）、220（330）千伏。 用户需要的电压等级不在上列范围时，应当自行采取变压措施解决。 用户需要的电压等级在110千伏以上时，其受电装置应当作为终端变电站设计。"},{"i":8,"n":"第八条","txt":"供电企业对申请用电的用户提供的供电方式，应当从供用电的安全、经济、合理和便于运维管理出发，依据国家有关政策规定、电网规划、用电需求以及当地供电条件等因素，进行技术经济比较，与用户协商确定。由地方政府投资建设供电设施的，供电企业应当就供电方式与地方政府协商确定。"},{"i":9,"n":"第九条","txt":"用户单相用电设备总容量12千瓦以下的可以采用低压220伏供电，但有单台设备容量超过1千瓦的单相电焊机、换流设备时，用户应当采取有效的技术措施以消除对电能质量的影响，否则应当改为其他方式供电。"},{"i":10,"n":"第十条","txt":"用户用电设备总容量160千瓦以下的，可以采用低压三相制供电，特殊情况也可以采用高压供电。"},{"i":11,"n":"第十一条","txt":"符合国家政策要求的，对距离发电厂较近的用户可以采用发电厂直配供电方式，但不得以发电厂的厂用电源或变电站（所）的站用电源对用户供电。"},{"i":12,"n":"第十二条","txt":"供电企业应当根据用户重要等级和负荷性质，按照国家及行业标准提供供电电源。 用户应当按照国家及行业标准配置自备应急电源，采取非电性质应急安全保护措施。"},{"i":13,"n":"第十三条","txt":"新建居住区供电方式应当符合国家相关政策要求及技术标准。 新建居住区居民住宅供电设施应当按照一户一表标准进行建设。 新建居住区的固定车位应当按照规定建设充电基础设施或预留安装条件，满足直接装表接电要求。居民自用充电桩用电按照国家相关政策要求及技术标准配置。"},{"i":14,"n":"第十四条","txt":"对基建工地、农田水利、市政建设等非永久性用电，可以供给临时电源。临时用电期限一般不得超过三年，如需办理延期的，应当在到期前向供电企业提出申请；逾期不办理延期或永久性正式用电手续的，供电企业应当终止供电。 使用临时电源的用户不得向外转供电，不得私自改变用电类别，供电企业不受理除更名、过户、销户、变更交费方式及联系人信息以外的变更业务。临时用电不得作为正式用电使用，如需改为正式用电，应当按照新装用电办理。 因突发事件需要紧急供电时，供电企业应当迅速组织力量，架设临时电源供电。架设临时电源所需的工程费用和应付的电费，由地方人民政府有关部门负责拨付。"},{"i":15,"n":"第十五条","txt":"供电企业一般不采用趸售方式供电。特殊情况需开放趸售供电时，应当由省级电力管理部门批准。 趸购转售电单位应当服从电网的统一调度，按照规定的电价向用户售电，不得再层层趸售。 电网经营企业与趸购转售电单位应当就趸购转售事宜签订供用电合同，明确双方的权利和义务。 趸购转售电单位需新装或增加趸购容量时，应当按照本规则的规定办理新装增容手续。"},{"i":16,"n":"第十六条","txt":"用户不得自行转供电。在公用供电设施尚未到达的地区，供电企业征得该地区有供电能力的直供用户同意，可以采用委托方式向其附近的用户转供电力，但不得委托重要的国防军工用户转供电。 委托转供电应当遵守下列规定： （一）供电企业与委托转供户（简称转供户）应当就转供范围、转供容量、转供期限、转供费用、计量方式、电费计算、转供电设施建设、产权划分、运行维护、调度通信、违约责任等事项签订协议； （二）转供区域内的用户（简称被转供户），视同供电企业的直供户，与直供户享有同样的用电权利，其一切用电事宜按照直供户的规定办理；   （三）向被转供户供电的公用线路与变压器的损耗电量应当由供电企业负担，不得摊入被转供户用电量中； （四）在计算转供户用电量、最大需量及功率因数调整电费时，应当扣除被转供户、公用线路与变压器消耗的有功、无功电量。最大需量按照下列规定折算： 1.照明及一班制：每月用电量180千瓦时，折合为"},{"i":17,"n":"第十七条","txt":"非电网供电主体对具备表计条件的终端用户，应当按照政府规定的电价政策执行，不得在终端用户的电费中加收物业公共部位、共用设施和配套设施的运行维护费等费用。 本条所指非电网供电，是指在公用供电设施已到达的地区，非电网供电主体将用电地址内配用电设施向供电企业申请整体报装并建立供用电关系，再由其通过内部配电设施向内部终端用户供电的情形。"},{"i":18,"n":"第十八条","txt":"用户应当将重要负荷与非重要负荷、生产用电与生活区用电分开配电。 新装或增加用电的用户应当按照上述规定确定内部的配电方式，对目前尚未达到上述要求的用户应当逐步改造。"},{"i":19,"n":"第十九条","txt":"任何单位或个人需新装用电或增加用电容量（简称增容）、变更用电都应当按照本规则规定，通过供电企业供电营业场所或线上服务渠道提出申请，办理手续。 供电企业应当在供电营业场所及各类线上服务渠道公开办理各项用电业务的程序、制度和收费标准。"},{"i":20,"n":"第二十条","txt":"供电企业的供电营业机构统一归口办理用户的新装、增容用电，包括业务受理、供电方案答复、设计审查、中间检查、竣工检验、装表接电等环节。"},{"i":21,"n":"第二十一条","txt":"用户申请新装或增容时，应当向供电企业提供以下申请资料： （一）低压用户需提供用电人有效身份证件、用电地址物权证件，居民自用充电桩需按照国家有关规定提供相关材料； （二）高压用户需提供用电人有效身份证件、用电地址物权证件、用电工程项目批准文件、用电设备清单，国家政策另有规定的，按照相关规定执行。    供电企业采用转移负荷或分流改造等方式后仍然存在供电能力不足或政府规定限制的用电项目，供电企业可以通知用户暂缓办理。"},{"i":22,"n":"第二十二条","txt":"供电企业对已受理的用电申请，应当尽快确定供电方案，在下列期限内正式书面通知用户： 低压用户不超过三个工作日，高压单电源用户不超过十个工作日，高压双电源用户不超过二十个工作日。若不能如期确定供电方案时，供电企业应当向用户说明原因。用户对供电企业答复的供电方案有不同意见时，应当在一个月内提出意见，双方可以再行协商确定。用户应当根据确定的供电方案进行受电工程设计。"},{"i":23,"n":"第二十三条","txt":"高压供电方案的有效期为一年，低压供电方案的有效期为三个月。用户应当在有效期内依据供电方案开工建设受电工程，逾期不开工的，供电方案失效。 用户遇有特殊情况，需延长供电方案有效期的，应当在有效期到期前十日向供电企业提出申请，供电企业应当视情况予以办理延长手续，但延长时间不得超过前款规定期限。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，为变更用电： （一）停止部分或全部受电设施用电容量的（简称减容）； （二）临时更换其他容量变压器的（简称暂换）； （三）迁移受电设施用电地址的（简称迁址）； （四）移动电能计量装置安装位置的（简称移表）； （五）暂时停止全部用电并拆表的（简称暂拆）； （六）用电地址物权变化引起用电人变更的（简称过户）； （七）变更用户名称的（简称更名）； （八）一户分立为两户以上用户的（简称分户）； （九）两户以上用户合并为一户的（简称并户）； （十）终止供用电关系的（简称销户）； （十一）改变供电电压等级的（简称改压）； （十二）改变电价类别、用电类别等计价计费信息的（简称改类）； （十三）改变行业分类、交费方式、银行账号、增值税信息、联系人信息等基础档案信息的（简称其它变更）。 用户需办理变更用电业务时，应当到供电企业供电营业场所或通过线上服务渠道办理申请手续，必要时应当办理变更"},{"i":25,"n":"第二十五条","txt":"用户减容分为永久性减容和非永久性减容，须向供电企业提出申请。供电企业应当按照下列规定办理：    （一）高低压用户均可以办理减容业务，自减容之日起，按照减容后的容量执行相应电价政策；高压供电的用户，减容应当是整台或整组变压器（含不通过受电变压器的高压电动机）的停止或更换小容量变压器用电，根据用户申请的减容日期，对非永久性减容的用户设备进行加封，对永久性减容的用户受电设备拆除电气连接； （二）申请非永久性减容的，减容次数不受限制，每次减容时长不得少于十五日，最长不得超过两年；两年内恢复的按照减容恢复办理，超过两年的应当按照新装或增容办理； （三）用户申请恢复用电时，容（需）量电费从减容恢复之日起按照恢复后的容（需）量计收；实际减容时长少于十五日的，停用期间容（需）量电费正常收取；非永久性减容期满后用户未申请恢复的，供电企业可以延长减容期限，但距用户申请非永久性减容时间最多不超过两年，超过"},{"i":26,"n":"第二十六条","txt":"用户暂换（因受电变压器故障而无相同容量变压器替代，需要临时更换其他容量变压器），应当在更换前向供电企业提出申请。供电企业应当按照下列规定办理： （一）应当在原受电地点内整台暂换受电变压器； （二）暂换变压器的使用时间，10（6、20）千伏以下的不得超过两个月，35千伏以上的不得超过三个月，逾期不办理手续的，供电企业可以中止供电； （三）暂换和暂换恢复的变压器经检验合格后才能投入运行； （四）两部制电价用户须在暂换之日起，按照替换后的变压器容量计收容（需）量电费。"},{"i":27,"n":"第二十七条","txt":"用户迁址，应当向供电企业提出申请。供电企业应当按照下列规定办理： （一）原址按照终止用电办理，供电企业予以销户。新址用电优先受理； （二）迁移后的新址不在原供电点供电的，新址用电按照新装用电办理； （三）迁移后的新址仍在原供电点，但新址用电容量超过原址用电容量的，超过部分按照增容办理；新址用电引起的用户产权范围内工程费用由用户负担； （四）私自迁移用电地址用电的，除按照本规则第一百零一条第四项处理外，自迁新址不论是否引起供电点变动，一律按照新装用电办理。"},{"i":28,"n":"第二十八条","txt":"用户移表（因修缮房屋或其他原因需要移动电能计量装置安装位置），应当向供电企业提出申请。供电企业应当按照下列规定办理： （一）在用电地址、用电容量、用电类别、供电点等不变情况下，可以办理移表手续； （二）移表所需的用户产权范围内工程费用由用户负担； （三）用户不论何种原因，不得自行移动表位，否则，可以按照本规则第一百零一条第四项处理。"},{"i":29,"n":"第二十九条","txt":"用户暂拆（因修缮房屋等原因需要暂时停止用电并拆表），应当向供电企业提出申请。供电企业应当按照下列规定办理： （一）用户暂拆应当停止全部用电容量的使用并与供电企业结清电费； （二）用户办理暂拆手续后，供电企业应当在五个工作日内执行暂拆； （三）暂拆时间最长不得超过一年；暂拆期间，供电企业保留该用户原容量的使用权； （四）暂拆原因消除，用户要求复装接电时，须向供电企业办理复装接电手续；上述手续完成后，供电企业应当在五个工作日内为该用户复装接电； （五）超过暂拆规定时间要求复装接电的，按照新装办理。"},{"i":30,"n":"第三十条","txt":"用户过户，应当持有关证明向供电企业提出申请。供电企业应当按照下列规定办理： （一）在用电地址、用电容量不变条件下，可以办理过户； （二）原用户应当与供电企业结清债务，才能解除原供用电关系； （三）不申请办理过户手续而私自过户的，新用户应当承担原用户所负债务；供电企业发现用户私自过户时，供电企业应当通知该户补办手续，必要时可以中止供电。"},{"i":31,"n":"第三十一条","txt":"用户更名，应当向供电企业提出申请。在用户用电主体、用电地址、用电容量、用电类别不变条件下，供电企业应当办理更名。"},{"i":32,"n":"第三十二条","txt":"用户分户，应当持有关证明向供电企业提出申请。供电企业应当按照下列规定办理： （一）在用电地址、供电点、用电容量不变，且其受电装置具备分装的条件时，可以办理分户； （二）分立后的用户按照地址均应当具有独立的不动产权属； （三）在原用户与供电企业结清债务的情况下，再办理分户手续； （四）分立后的新用户应当与供电企业重新建立供用电关系； （五）原用户的用电容量由分户者自行协商分割，需要增容的，分户后另行向供电企业办理增容手续； （六）分户引起的用户产权范围内工程费用由分户者负担； （七）分户后受电装置应当经供电企业检验合格，由供电企业分别装表计费。"},{"i":33,"n":"第三十三条","txt":"用户并户，应当持有关证明向供电企业提出申请。供电企业应当按照下列规定办理： （一）在同一供电点、同一用电地址的相邻两个以上用户允许办理并户； （二）原用户应当在并户前与供电企业结清债务； （三）新用户用电容量不得超过并户前各户容量之和； （四）并户引起的用户产权范围内工程费用由并户者负担； （五）并户受电装置应当经供电企业检验合格，由供电企业重新装表计费。"},{"i":34,"n":"第三十四条","txt":"用户销户，应当向供电企业提出申请。供电企业应当按照下列规定办理： （一）销户应当停止全部用电容量的使用； （二）供用电双方结清电费； （三）查验电能计量装置完好性后，拆除接户线和电能计量装置。 办完上述事宜，即完成销户，解除供用电关系。"},{"i":35,"n":"第三十五条","txt":"用户连续六个月不用电，且经现场确认不具备继续用电条件或存在安全用电隐患的，供电企业应当向用户进行告知，或公告一个月后予以销户。用户需再用电时，按照新装用电办理。"},{"i":36,"n":"第三十六条","txt":"用户改压（因用户原因需要在原址改变供电电压等级），应当向供电企业提出申请。供电企业应当按照下列规定办理： （一）改变电压等级供电，超过原容量者，超过部分按照增容办理； （二）改压引起的用户产权范围内工程费用由用户负担。 由于供电企业的原因引起用户供电电压等级变化的，改压引起的用户产权范围外工程费用由供电企业负担。"},{"i":37,"n":"第三十七条","txt":"用户改类，应当向供电企业提出申请。供电企业应当按照下列规定办理： （一）在同一受电设施内，因电力用途发生变化而引起电价类别、用电类别变化的，应当办理改类手续； （二）用户根据国家电价政策的规定，申请两部制电价、分时电价、阶梯电价等电价变更的，应当办理改类手续； （三）擅自改变用电类别的，按照本规则第一百零一条第一项处理。"},{"i":38,"n":"第三十八条","txt":"用户改变行业分类、交费方式、银行账号、增值税信息、用电地名（地理位置不变）、联系人信息等基础档案信息的，须向供电企业提出办理其它变更申请。供电企业发现用户档案信息与实际不符须进行变更的，用户应当配合。 因行业分类变化导致用电类别变化的，按照改类办理。"},{"i":39,"n":"第三十九条","txt":"用户依法破产后，供电企业应当按照下列规定办理： 用户进行工商注销的，供电企业应当予以销户； （二）终止供电仍需在破产用户原址上用电的，按照新装用电办理。"},{"i":40,"n":"第四十条","txt":"用户受电设施的建设与改造应当符合城乡电网建设与改造规划。对规划中安排的线路走廊和变电站建设用地，应当优先满足公用供电设施建设的需要，确保土地和空间资源得到有效利用。"},{"i":41,"n":"第四十一条","txt":"用户新装、增装或改装受电工程的设计安装、试验与运行应当符合国家有关标准；国家尚未制定标准的，应当符合电力行业标准；国家和电力行业尚未制定标准的，应当符合省（自治区、直辖市）电力管理部门的规定和规程。"},{"i":42,"n":"第四十二条","txt":"新建居民住宅小区供电设施应当按照国家相关政策要求及技术标准进行建设。其中： （一）高层小区一级负荷应当采用双重电源供电；特级负荷除双重电源供电外，还应增设应急电源供电，并严禁将其它负荷接入应急供电系统；二级负荷宜采用双回线路供电； （二）新建居民住宅小区应当合理规划确定配用电设施位置，满足防洪防涝相关要求，设置应急移动电源接口。"},{"i":43,"n":"第四十三条","txt":"高压供电的用户应当提供设计单位资质证明材料、受电工程设计及说明书，一式两份送交供电企业。其中受电工程设计及说明书应当包括： （一）用电负荷分布图； （二）负荷组成、性质及保安负荷； （三）主要电气设备一览表； （四）影响电能质量的用电设备清单； （五）节能篇及主要生产设备、生产工艺耗电以及允许中断供电时间； （六）高压受电设施一、二次接线图与平面布置图； （七）用电功率因数计算及无功补偿方式； （八）继电保护、过电压保护及电能计量装置的方式； （九）隐蔽工程设计资料； （十）配电网络布置图； （十一）自备应急电源及接线方式。 低压供电的用户无需提供设计相关资料。"},{"i":44,"n":"第四十四条","txt":"供电企业对重要电力用户、居民住宅小区送审的受电工程设计文件和有关资料，应当根据本规则的有关规定进行审核，单次审核时间不超过三个工作日，审核意见应当以书面形式连同审核过的一份受电工程设计文件和有关资料一并退还用户，以便用户据以施工。用户若更改审核后的设计文件，应当将变更后的设计再送供电企业复核。 重要电力用户、居民住宅小区受电工程的设计文件，未经供电企业审核同意，用户不得据以施工，否则，供电企业可以不予检验和接电。 不实行设计审查的高压用户，在竣工检验时提交设计单位资质证明材料、受电工程设计及说明书。"},{"i":45,"n":"第四十五条","txt":"无功电力应当就地平衡。用户应当在提高用电自然功率因数的基础上，按照有关标准设计和安装无功补偿设备，并做到随其负荷和电压变动及时投入或切除，防止无功电力倒送。除电网有特殊要求的用户外，用户在当地供电企业规定的电网高峰负荷时的功率因数，应当达到下列规定： （一）100千伏安以上高压供电的用户功率因数为0.90以上； （二）其他用户和大、中型电力排灌站、趸购转售电企业，功率因数为0.85以上； （三）农业用电，功率因数为0.80。 凡功率因数不能达到上述规定的新用户，供电企业可以拒绝接电。对已送电的用户，供电企业应当督促和帮助用户采取措施，提高功率因数。对在规定期限内仍未采取措施达到上述要求的用户，供电企业可以中止或限制供电。功率因数调整电费办法按照国家规定执行。"},{"i":46,"n":"第四十六条","txt":"重要电力用户、居民住宅小区受电工程施工期间，供电企业应当根据审核同意的设计和有关施工标准，对用户受电工程中的隐蔽工程进行中间检查。如有不符合规定的，一次性向用户提出书面意见。用户应当按照设计和施工标准予以改正。单次检查时间不超过两个工作日。不实行隐蔽工程中间检查的用户，在竣工检验时提交隐蔽工程施工、试验单位资质证明材料，施工及试验记录。"},{"i":47,"n":"第四十七条","txt":"用户受电工程施工、试验完工后，应当向供电企业提出竣工检验申请，并提供工程竣工报告。报告应当包括： （一）施工、试验单位资质证明材料； （二）工程竣工图及说明； （三）电气试验及保护整定调试记录； （四）安全用具的试验报告； （五）隐蔽工程的施工及试验记录； （六）运行管理的有关规定和制度； （七）值班人员名单及资格； （八）供电企业认为必要的其他资料或记录。 供电企业接到用户的受电装置竣工报告及检验申请后，应当及时组织审核竣工资料，对投运后可能影响公共电网安全运行的涉网设备进行检验。对检验不合格的，供电企业应当一次性向用户提出书面意见。用户应当按照书面意见予以整改，直至合格。单次检验时间不超过三个工作日。检验合格后，供电企业应当与用户协商确定装表接电时间，装表接电时间不超过三个工作日。"},{"i":48,"n":"第四十八条","txt":"公用路灯、交通信号灯是公用设施，应当由当地人民政府及有关管理部门投资建设，并负责维护管理和交纳电费等事项。供电企业可以接受地方有关部门的委托，代为设计、施工与维护管理公用路灯，并照章收取费用，具体事项由双方协商确定。"},{"i":49,"n":"第四十九条","txt":"用户独资、合资或集资建设的供电设施建成后，其运行维护管理按照以下规定确定： （一）属于公用性质或占用公用线路规划走廊的，由供电企业统一管理；供电企业应当在交接前，与用户协商，就供电设施运行维护管理达成协议；对统一运行维护管理的公用供电设施，供电企业应当保留原所有者在上述协议中确认的容量； （二）属于用户专用性质，但不在公用变电站内的供电设施，由用户运行维护管理；如用户运行维护管理确有困难，可以委托具有相应资质的企业代为运维管理，并签订协议；  （三）属于用户共用性质的供电设施，由拥有产权的用户共同运行维护管理；如用户共同运行维护管理确有困难，可以委托具有相应资质的企业代为运维管理，并签订协议；  （四）在公用变电站内由用户投资建设的供电设备，如变压器、通信设备、开关、刀闸等，由供电企业统一运维管理；建成投运前，双方应当就运行维护、检修、备品备件等项事宜签订交接协议；  （五）属于临时用"},{"i":50,"n":"第五十条","txt":"供电设施的运行维护管理范围，按照产权归属确定。产权归属不明确的，责任分界点按照下列各项确定： （一）公用低压线路供电的，以电能表前的供电接户线用户端最后支持物为分界点，支持物属供电企业； （二）10（6、20）千伏以下公用高压线路供电的，以用户厂界外或配电室前的第一断路器或第一支持物为分界点，第一断路器或第一支持物属供电企业；  （三）35千伏以上公用高压线路供电的，以用户厂界外或用户变电站外第一基电杆为分界点，第一基电杆属供电企业；  （四）采用电缆供电的，本着便于维护管理的原则，分界点由供电企业与用户协商确定；  （五）产权属于用户且由用户运行维护的线路，以公用线路分支杆或专用线路接引的公用变电站外第一基电杆为分界点，专用线路第一基电杆属用户。 在电气上的具体分界点，由供用双方协商确定。"},{"i":51,"n":"第五十一条","txt":"供电企业和用户分工维护管理的供电和受电设备，除另有约定者外，未经管辖单位同意，对方不得操作或更动；如因紧急事故必须操作或更动者，事后应当迅速通知管辖单位。"},{"i":52,"n":"第五十二条","txt":"由于工程施工或线路维护的需要，供电企业须在用户处凿墙、挖沟、掘坑、巡线等作业时，应当征得用户同意，用户应当给予方便，供电企业应当遵守用户的有关安全保卫制度。用户到供电企业维护的电力设施保护范围和保护区作业时，须经县级以上地方政府电力管理部门批准，并按照要求采取安全措施后，在供电企业人员监护下工作。作业完工后，双方均应当及时予以修复。"},{"i":53,"n":"第五十三条","txt":"因建设引起建筑物、构筑物与供电设施相互妨碍，需要迁移供电设施或采取防护措施时，应当按照建设先后的原则，确定其担负的责任。如供电设施建设在先，建筑物、构筑物建设在后，由后续建设单位负担供电设施迁移、防护所需的费用；如建筑物、构筑物建设在先，供电设施建设在后，由供电设施建设单位负担建筑物、构筑物迁移所需的费用；不能确定建设先后的，由双方协商解决。 供电企业需要迁移用户或其他供电企业的设施时，参照上述原则办理。 城乡建设与改造需迁移供电设施时，供电企业和用户都应当积极配合，迁移所需的材料和费用，应当在城乡建设与改造投资中解决。"},{"i":54,"n":"第五十四条","txt":"供电设施产权所有者对在供电设施上发生的事故承担法律责任，但法律法规另有规定的除外。"},{"i":55,"n":"第五十五条","txt":"供电企业和用户都应当加强供电和用电的运行管理，切实执行国家和电力行业制定的有关安全供用电的规程制度。用户执行其上级主管机关颁发的电气规程制度，除特殊专用的设备外，如与电力行业标准或规定有矛盾时，应当以国家和电力行业标准或规定为准。供电企业和用户在必要时应当制定本单位的现场规程。"},{"i":56,"n":"第五十六条","txt":"在电力系统正常状况下，供电频率的允许偏差为： （一）电网装机容量在300万千瓦以上的，为±0.2赫兹； （二）电网装机容量不足300万千瓦的，为±0.5赫兹。 在电力系统非正常状况下，供电频率允许偏差不应超过±1.0赫兹。"},{"i":57,"n":"第五十七条","txt":"在电力系统正常状况下，供电企业供到用户受电端的供电电压允许偏差为： （一）35千伏以上电压供电的，电压正、负偏差的绝对值之和不超过额定值的10%； （二）10（6、20）千伏以下三相供电的，为额定值的±7%； （三）220伏单相供电的，为额定值的+7%、－10%。 在电力系统非正常状况下，用户受电端的电压最大允许偏差不应超过额定值的±10%。用户用电功率因数达不到本规则第四十五条规定的，其受电端的电压偏差不受此限制。"},{"i":58,"n":"第五十八条","txt":"电网公共连接点电压正弦波畸变率和用户注入电网的谐波电流不得超过国家标准的规定。用户的非线性阻抗特性的用电设备接入电网运行所注入电网的谐波电流和引起公共连接点电压正弦波畸变率超过标准时，用户应当采取措施予以消除。否则，供电企业可以中止对其供电。"},{"i":59,"n":"第五十九条","txt":"用户的冲击负荷、波动负荷、非对称负荷对供电质量产生影响或对安全运行构成干扰和妨碍时，用户应当采取措施予以消除。如不采取措施或采取措施不力，达不到国家标准规定的要求时，供电企业可以中止对其供电。"},{"i":60,"n":"第六十条","txt":"供电企业应当不断改善供电可靠性，减少设备检修和电力系统事故对用户的停电次数及每次停电持续时间。供用电设备计划检修应当做到统一安排。供电设备计划检修时，对35千伏以上电压供电的用户的停电次数，每年不应超过一次；对10（6、20）千伏供电的用户，每年不应超过三次。"},{"i":61,"n":"第六十一条","txt":"供电企业和用户应当共同加强电能质量管理。对电能质量有异议的可以由具有相应资质的技术检测机构进行技术判断。"},{"i":62,"n":"第六十二条","txt":"供电企业和用户的供用电设备计划检修应当相互配合，尽量做到统一检修。用电负荷较大，开停对电网有影响的设备，其停开时间，用户应当提前与供电企业联系。 遇有紧急检修需停电时，供电企业应当按照规定提前通知重要用户，用户应当予以配合；事故断电，应当尽快修复。"},{"i":63,"n":"第六十三条","txt":"供电企业应当根据电力系统情况和电力负荷的重要性，编制事故限电序位方案，并按照有关规定程序报批后执行。"},{"i":64,"n":"第六十四条","txt":"用户应当定期进行电气设备和保护装置的检查、检修和试验，消除设备隐患，预防电气设备事故和误动作发生。 用户电气设备危及人身和运行安全时，应当立即检修。 多路电源供电的用户应当加装连锁装置，或按照供用双方签订的协议进行调度操作。"},{"i":65,"n":"第六十五条","txt":"用户发生用电事故，应当按照法律法规规定向地方政府有关部门报告，供电企业应当协助有关部门开展调查。发生下列事故的，还应当同时告知供电企业： （一）人身触电死亡； （二）导致电力系统停电； （三）专线掉闸或全厂停电； （四）电气火灾； （五）重要或大型电气设备损坏； （六）停电期间向电力系统倒送电。"},{"i":66,"n":"第六十六条","txt":"用户受电侧的继电保护装置、安全自动装置应当与电力系统的继电保护方式相互配合，并按照国家及行业有关标准或规程进行整定和检验。由供电企业整定、加封的继电保护装置及其二次回路和供电企业规定的继电保护整定值，用户不得擅自变动。"},{"i":67,"n":"第六十七条","txt":"承装、承修、承试受电工程的单位，应当取得《承装（修、试）电力设施许可证》。"},{"i":68,"n":"第六十八条","txt":"供电企业和用户应当经常开展安全供用电宣传教育，普及安全用电常识。"},{"i":69,"n":"第六十九条","txt":"在发供电系统正常情况下，供电企业应当连续向用户供应电力。 有下列情形之一的，可以按照规定的程序中止供电： （一）危害供用电安全，扰乱供用电秩序的； （二）逾期未交付电费超过三十日，经催交在合理期限内仍未交付的； （三）受电装置经检验不合格，在指定期间未改善的； （四）用户注入电网的谐波电流超过标准，以及冲击负荷、非对称负荷等对电能质量产生干扰与妨碍，在规定限期内不采取措施的； （五）拒不在限期内拆除私增用电容量的； （六）拒不在限期内交付违约用电引起的费用的； （七）违反安全用电、有序用电有关规定，拒不改正的； （八）私自向外转供电力的。 有下列情形之一的，可立即中止供电： （一）发生不可抗力和紧急避险的； （二）发现确有窃电行为并已告知将中止供电的。"},{"i":70,"n":"第七十条","txt":"除因故需要中止供电和可以立即中止供电的情形外，供电企业需对用户停止供电时，应当按照下列程序办理： （一）在停电前三至七日内，将停电通知书送达用户，对重要用户的停电，应当将停电通知书报送同级电力管理部门； （二）在停电前三十分钟，将停电时间再通知用户一次，方可在通知规定时间实施停电。"},{"i":71,"n":"第七十一条","txt":"因故需要中止供电时，供电企业应当按照下列要求事先通知用户或公告： （一）因供电设施计划检修需要停电时，应当提前七日通知用户或公告； （二）因供电设施临时检修需要停止供电时，应当提前二十四小时通知重要用户或公告； （三）发供电系统发生故障需要停电、限电或者计划限、停电时，供电企业应当按照批准的有序用电方案或限电序位执行，有序用电方案或限电序位应当事前公告用户。"},{"i":72,"n":"第七十二条","txt":"引起停电或限电的原因消除后，供电企业应当在二十四小时内恢复供电。不能在二十四小时内恢复供电的，供电企业应当向用户说明原因。"},{"i":73,"n":"第七十三条","txt":"供电企业应当在用户每一个受电点内按照不同电价类别，分别安装电能计量装置，每个受电点作为用户的一个计费单位。用户为满足内部核算的需要，可以自行在其内部装设考核能耗用的电能表，但该表所示读数不得作为供电企业计费依据。"},{"i":74,"n":"第七十四条","txt":"在用户受电点内难以按照电价类别分别装设电能计量装置时，可以装设总的电能计量装置，然后按其不同电价类别的用电设备容量的比例或实际可能的用电量，确定不同电价类别用电量的比例或定量进行分算，分别计价。供电企业每年至少对上述比例或定量核定一次，用户不得拒绝。"},{"i":75,"n":"第七十五条","txt":"电能计量装置包括计费电能表（有功、无功电能表及最大需量表）和电压、电流互感器及二次连接导线。计费电能表及附件的购置、安装、移动、更换、检验、拆除、加封及表计接线等，均由供电企业负责办理，用户应当提供工作上的方便。 供电企业不得违反国家有关规定向用户收取电能计量装置费用。高压用户的成套设备中装有自备互感器时，经供电企业检验合格并加封，可以作为计费互感器。 供电企业在新装、换装及现场校验后应当对电能计量装置加封，并请用户在工作凭证上签章。"},{"i":76,"n":"第七十六条","txt":"对10（6、20）千伏以下电压供电的用户，应当配置专用的电能计量柜（箱）；对35千伏以上电压供电的用户，应当有专用的电流互感器二次线圈和专用的电压互感器二次连接线，并不得与保护、测量回路共用。电压互感器专用回路的电压降不得超过允许值。超过允许值时，应当予以改造或采取必要的技术措施予以更正。"},{"i":77,"n":"第七十七条","txt":"电能计量装置原则上应当装在供电设施的产权分界处。如产权分界处不适宜装表的，对专线供电的高压用户，可以在供电变压器出口装表计量；对公用线路供电的高压用户，可以在用户受电装置的低压侧计量。当电能计量装置不安装在产权分界处时，线路与变压器损耗的有功与无功电量均须由产权所有者负担。在计算用户容（需）量电费（按照最大需量计收时）、电度电费及功率因数调整电费时，应当将上述损耗电量计算在内。"},{"i":78,"n":"第七十八条","txt":"城镇居民用电一般应当实行一户一表。因特殊原因不能实行一户一表计费时，供电企业可以根据其容量按照公安门牌或楼门单元、楼层安装共用的计费电能表，居民用户不得拒绝合用。共用计费电能表内的各用户，可以自行装设分户电能表，自行分算电费，供电企业在技术上予以指导。"},{"i":79,"n":"第七十九条","txt":"临时用电的用户，应当安装电能计量装置。对不具备安装条件的，可以按照其用电容量、使用时间、规定的电价计收电费。"},{"i":80,"n":"第八十条","txt":"安装在用户处的电能计量装置、电能信息采集装置，用户应当妥为保护，不得存在妨碍抄表、运行维护或者影响计量准确、安全和数据传输的行为。如发生计费电能表丢失、损坏或过负荷烧坏等情况，用户应当及时告知供电企业，以便供电企业采取措施。如因用户原因引起的，用户应当负担赔偿费或修理费；其他原因引起的，供电企业应当负责换表，不收费用。"},{"i":81,"n":"第八十一条","txt":"供电企业应当按照规定的周期校验、轮换计费电能表，并对计费电能表进行不定期检查。发现计量失常时，应当查明原因。电能表运行出现问题的，应当更换。 用户认为供电企业装设的计费电能表不准时，有权向供电企业提出校验申请，供电企业受理申请后，应当在五个工作日内检验，并将检验结果通知用户。如计费电能表的误差超出允许范围时，供电企业应当按照本规则第八十二条规定退补电费。用户对检验结果有异议时，可以向有资质的计量检定机构申请检定。用户在申请验表期间，其电费仍应当按期交纳，验表结果确认后，再行退补电费。"},{"i":82,"n":"第八十二条","txt":"由于计费计量互感器、电能表的误差及其连接线电压降超出允许范围或者其他非人为原因致使计量记录不准时，供电企业应当按照下列规定退补相应电量的电费： （一）互感器或者电能表误差超出允许范围时，以“0”误差为基准，按照验证后的误差值退补电量；退补时间以误差发生之日起至误差更正之日止计算；时间无法确定的，从上次校验或者换装后投入之日起至误差更正之日止的二分之一时间计算； （二）连接线的电压降超出允许范围时，以允许电压降为基准，按照验证后实际值与允许值之差退补电量；退补时间从连接线投入或负荷增加之日起至电压降更正之日止；  （三）其他非人为原因致使计量记录不准时，以考核能耗用的计量装置或者其它电能量测量装置记录为基准计算；无上述装置的，以用户正常月份用电量为基准计算；退补时间按照电能计量装置运行数据确定。 退补期间，用户先按照抄见电量如期交纳电费，误差确定后，再行退补。"},{"i":83,"n":"第八十三条","txt":"电能计量装置接线错误、互感器故障、倍率不符等原因，使电能计量或者计算出现差错时，供电企业应当退补从差错发生之日起至差错更正之日止相应电量的电费，并按照下列规定执行： （一）计算电量的倍率或铭牌倍率与实际不符的，以实际倍率为基准，按照正确与错误倍率的差值退补电量；退补时间无法确定的，以抄表记录为准确定； （二）因计费电能计量装置接线错误、互感器故障的，以考核能耗用的电能计量装置或者其它电能量测量装置记录为基准计算，无上述装置的，可以按照以下方法计算： 1.计费电能计量装置接线错误的，以其实际记录的电量为基数，按照正确与错误接线的差额率退补电量；退补时间无法确定的，从上次校验或换装投入之日起至接线错误更正之日止； 2.互感器故障的，按照电工理论计算方法确定的差额率计算退补电量；无法计算的，以用户正常月份用电量为基准，按照正常月与故障月的差额计算退补电量。 退补电量未正式确定前，用户先按照正"},{"i":84,"n":"第八十四条","txt":"供电企业应当依据电能计量装置的记录计算电费，按期向用户收取或通知用户按期交纳电费。供电企业可以与用户协商确定收取电费的方式。 用户应当按照双方约定的期限和交费方式交清电费，不得拖延或拒交电费。"},{"i":85,"n":"第八十五条","txt":"供电企业应当在规定的日期抄录计费电能表读数，可以运用数字信息手段远程自动采集。 由于用户原因或远程采集异常，且无法如期抄录计费电能表读数的，可以通知用户待期补抄或暂按照前次用电量计收电费，待下次抄表时一并结清。 电力市场交易规则对电能计量有规定的，按照相关规定执行。"},{"i":86,"n":"第八十六条","txt":"容（需）量电费以月计算，但新装、增容、变更与终止用电当月的容（需）量电费，应当按照实用天数计算，每日按照全月容（需）量电费除以当月日历天数收取，日用电不足二十四小时的，按照一天计算。事故停电、检修停电、有序用电不扣减容（需）量电费。"},{"i":87,"n":"第八十七条","txt":"容（需）量电费按照变压器容量或最大需量计收，同一计费周期内用户可以选择其中一种。 以变压器容量计算容（需）量电费的用户，其备用的变压器（含不通过变压器的高压电动机），属冷备用状态并经供电企业加封的，不收容（需）量电费；属热备用状态的或未经加封的，不论使用与否都计收容（需）量电费。用户专门为调整用电功率因数的设备，如电容器、调相机等，不计收容（需）量电费。 在受电设施一次侧装有连锁装置互为备用的变压器（含不通过变压器的高压电动机），按照可能同时使用的变压器（含不通过变压器的高压电动机）容量之和的最大值计算其容（需）量电费。 以最大需量方式计收需量电费的用户，计收方式按照相关电价政策规定执行。"},{"i":88,"n":"第八十八条","txt":"对月用电量较大的用户，供电企业可以按照用户月电费确定每月分若干次收费，并于抄表后结清当月电费。收费次数由供电企业与用户协商确定，一般每月不少于三次。对于银行划拨电费的，供电企业、用户、银行三方应当签订电费划拨和结清的协议书。 供用双方改变开户银行或账号时，应当及时通知对方。"},{"i":89,"n":"第八十九条","txt":"临时用电用户未装电能计量装置的，供电企业应当根据其用电容量，按照双方约定的每日使用时数和使用期限预收全部电费。用电终止时，供电企业按照实际用电天数对预收电费进行清算。到约定期限时，应当终止供电。"},{"i":90,"n":"第九十条","txt":"供电企业依法对用户终止供电时，双方应当结清全部电费和与供电业务相关的其他债务。否则，供电企业有权依法追缴。"},{"i":91,"n":"第九十一条","txt":"在供电营业区内建设的各类发电厂，未经许可，不得从事电力供应业务。 并网运行的发电厂，应当在发电厂建设项目立项前，与并网的电网经营企业联系，就并网容量、发电时间、上网电价、上网电量等达成电力输送或电量购销意向性协议。"},{"i":92,"n":"第九十二条","txt":"电网经营企业与并网发电厂应当根据国家法律、行政法规和有关规定，签订并网调度协议，并在并网发电前签订购售电合同或相关交易合同。"},{"i":93,"n":"第九十三条","txt":"用户自备电厂应当自发自供厂区内的用电，自发自用有余的电量可以与供电企业签订购售电合同。 用户自备电厂应当公平承担发电企业社会责任、政府规定的基金和费用，在成为合格市场主体情况下，可以按照交易规则参与市场化交易。"},{"i":94,"n":"第九十四条","txt":"供电企业和用户应当在供电前，根据用户用电需求和供电企业的供电能力以及办理用电申请时双方已认可或协商一致的下列文件，签订供用电合同： （一）用户的用电申请报告或用电申请书； （二）供电企业答复的供电方案； （三）用户受电装置施工竣工检验报告； （四）其他双方事先约定的有关文件。   在签订供用电合同时，可以单独签订电费结算协议和电力调度协议等。"},{"i":95,"n":"第九十五条","txt":"供用电合同应当采用纸质或电子合同签订，经双方协商同意的有关修改合同的文书、电报、电传和图表等也是合同的组成部分。   供用电合同书面形式可以分为标准格式和非标准格式两类。标准格式合同适用于供电方式简单、一般性用电需求的用户；非标准格式合同适用于供用电方式特殊的用户。 供电企业可以根据用电类别、用电容量、电压等级的不同，分类制定出适应不同类型用户需要的标准格式供用电合同。"},{"i":96,"n":"第九十六条","txt":"供用电合同的变更或者解除，应当依法进行。 因国家法律法规或政策变化，影响供用电合同主要内容时，应当根据调整后的国家法律法规或政策执行。"},{"i":97,"n":"第九十七条","txt":"供用电双方在合同中订有电力运行事故责任条款的，按照下列规定办理，双方另有约定的除外： （一）由于供电企业电力运行事故造成用户停电时，供电企业应当按照用户在停电时间内可能用电量乘以当期同类用户平均电量电价的四倍（两部制电价为五倍）给予赔偿；用户在停电时间内可能用电量，按照停电前用户正常用电月份或正常用电一定天数内的每小时平均用电量乘以停电小时计算； （二）由于用户责任造成供电企业对外停电时，用户应当按照供电企业对外停电时间少供电量，乘以上月供电企业平均售电单价给予赔偿； 因用户过错造成其他用户损害的，受害用户要求赔偿时，该用户应当依法承担赔偿责任； 虽因用户过错，但由于供电企业责任而使事故扩大造成其他用户损害的，该用户不承担事故扩大部分的赔偿责任； （三）对停电责任的分析和停电时间及少供电量的计算，均按照供电企业的事故记录及有关规定办理；停电时间不足一小时按照一小时计算，超过一小时按照实"},{"i":98,"n":"第九十八条","txt":"供用电双方在合同中订有电压质量责任条款的，按照下列规定办理，双方另有约定的除外： （一）用户用电功率因数达到规定标准，而供电电压超出本规则规定的允许偏差，给用户造成损失的，供电企业应当按照用户每月在电压不合格的累计时间内所用的电量，乘以用户当月用电的平均电价的百分之二十给予赔偿； （二）用户用电功率因数未达到规定标准或其他用户原因引起电压质量不合格的，供电企业不承担赔偿责任； （三）电压偏差超出允许偏差的时间，以用户自备并经供电企业认可的电压自动记录仪表的记录为准，如用户未装此项仪表，则以供电企业的电压记录为准。"},{"i":99,"n":"第九十九条","txt":"供用电双方在合同中订有频率质量责任条款的，按照下列规定办理，双方另有约定的除外： （一）供电频率超出允许偏差，给用户造成损失的，供电企业应当按照用户每月在频率不合格的累计时间内所用的电量，乘以用户当月用电的平均电价的百分之二十给予赔偿； （二）频率变动超出允许偏差的时间，以用户自备并经供电企业认可的频率自动记录仪表的记录为准，如用户未装此项仪表，则以供电企业的频率记录为准。"},{"i":100,"n":"第一百条","txt":"用户在供电企业规定的期限内未交清电费时，应当承担电费滞纳的违约责任。电费违约金从逾期之日起计算至交纳日止。每日电费违约金按照下列规定计算，双方另有约定的除外： （一）居民用户每日按照欠费总额的千分之一计算； （二）其他用户： 1.当年欠费部分，每日按照欠费总额的千分之二计算； 2.跨日历年欠费部分，每日按照欠费总额的千分之三计算。 电费违约金收取总额按日累加计收。"},{"i":101,"n":"第一百零一条","txt":"供电企业对用户危害供用电安全、扰乱正常供用电秩序等行为应当及时予以制止。用户有下列行为的，应当承担相应的责任，双方另有约定的除外： （一）在电价低的供电线路上，擅自接用电价高的用电设备或私自改变用电类别的，应当按照实际使用日期补交其差额电费，并承担不高于二倍差额电费的违约使用电费，使用起讫日期难以确定的，实际使用时间按照三个月计算； （二）私增或更换电力设备导致超过合同约定的容量用电的，除应当拆除私增容设备或恢复原用电设备外，属于两部制电价的用户，应当补交私增设备容量使用天数的容（需）量电费，并承担不高于三倍私增容量容（需）量电费的违约使用电费；其他用户应当承担私增容量每千瓦（千伏安视同千瓦）五十元的违约使用电费，如用户要求继续使用者，按照新装增容办理； （三）擅自使用已在供电企业办理减容、暂拆手续的电力设备或启用供电企业封存的电力设备的，应当停用违约使用的设备；属于两部制电价的用户，"},{"i":102,"n":"第一百零二条","txt":"供电企业与用户签订的供用电合同相关违约责任条款，不得超出本规则规定的违约责任限度，不得擅自增加用户义务，减损用户权利。"},{"i":103,"n":"第一百零三条","txt":"禁止窃电行为。窃电行为包括： （一）在供电企业的供电设施上，擅自接线用电； （二）绕越供电企业电能计量装置用电； （三）伪造或者开启供电企业加封的电能计量装置封印用电； （四）故意损坏供电企业电能计量装置； （五）故意使供电企业电能计量装置不准或者失效； （六）采用其他方法窃电。"},{"i":104,"n":"第一百零四条","txt":"供电企业对查获的窃电者，应当予以制止并按照本规则规定程序中止供电。窃电用户应当按照所窃电量补交电费，并按照供用电合同的约定承担不高于应补交电费三倍的违约使用电费。拒绝承担窃电责任的，供电企业应当报请电力管理部门依法处理。窃电数额较大或情节严重的，供电企业应当提请司法机关依法追究刑事责任。"},{"i":105,"n":"第一百零五条","txt":"能够查实用户窃电量的，按已查实的数额确定窃电量。窃电量不能查实的，按照下列方法确定： （一）在供电企业的供电设施上，擅自接线用电或者绕越供电企业电能计量装置用电的，所窃电量按照私接设备额定容量（千伏安视同千瓦）乘以实际使用时间计算确定； （二）以其他行为窃电的，所窃电量按照计费电能表标定电流值（对装有限流器的，按照限流器整定电流值）所指的容量（千伏安视同千瓦）乘以实际窃用的时间计算确定。 窃电时间无法查明时，窃电日数以一百八十天计算。每日窃电时长，电力用户按照十二小时计算、照明用户按照六小时计算。"},{"i":106,"n":"第一百零六条","txt":"因违约用电或窃电造成供电企业的供电设施损坏的，责任者应当承担供电设施的修复费用或进行赔偿。 因违约用电或窃电导致他人财产、人身安全受到侵害的，受害人有权要求违约用电或窃电者停止侵害，赔偿损失。供电企业应予协助。"},{"i":107,"n":"第一百零七条","txt":"供电企业电企业对检举、查获窃电或违约用电的有关人员应当给予奖励。"},{"i":108,"n":"第一百零八条","txt":"电力行业协会推动制定供用电活动的国家标准和行业标准，推广供用电先进技术，促进技术进步和节能减排。"},{"i":109,"n":"第一百零九条","txt":"本规则所称的“以上”“以下”“内”“以内”“提前”“至少”“不超过”“不高于”，包括本数；所称的“不足”“超出”“超过”“少于”，不包括本数。"},{"i":110,"n":"第一百一十条","txt":"本规则自2024年6月1日起施行。1996年10月8日原电力工业部发布的《供电营业规则》同时废止。"}],"quanguotouzixiangmuzaixianshenpijianguanpingtaiyunf4818a-2":[{"i":1,"n":"第一条","txt":"为加强全国投资项目在线审批监管平台(以下简称“在线平台”)建设、应用和管理，确保在线平台逐步完善、稳定运行并发挥作用，根据有关法律法规和改革要求，结合工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"在线平台是指依托互联网和国家电子政务外网(以下简称“政务外网”)建设的固定资产投资项目(以下简称“项目”)综合管理服务平台。 各级政府及其部门应当通过在线平台实现项目网上申报、并联审批、信息公开、协同监管，不断优化办事流程，提高服务水平，并加强事中事后监管，主动接受社会监督。"},{"i":3,"n":"第三条","txt":"在线平台适用于各类项目建设实施全过程的审批、监管和服务，包括行政许可、政府内部审批、备案、评估评审、技术审查，项目实施情况监测，以及政策法规、规划咨询服务等。涉密项目及信息不得通过在线平台办理和传递。"},{"i":4,"n":"第四条","txt":"各级在线平台由互联网门户网站和政务外网审批监管系统构成。互联网门户网站是项目单位和社会公众网上申报、查询办理情况的统一窗口，提供办事指南、中介服务、政策信息等服务指引;审批监管系统是联接各级政府部门相关信息系统开展并联审批、电子监察、项目监管、数据分析的工作平台。 利用大数据分析加强监测预测、风险预警，按照精细化管理要求，加强事中事后监管。充分利用平台痕迹管理功能，增强透明度，对各个环节做到可检查、可考核。"},{"i":5,"n":"第五条","txt":"在线平台由中央平台和地方平台组成。中央平台负责管理由国务院及其相关部门审批、核准和备案的项目(以下简称“中央项目”)。地方平台负责管理地方各级政府及其相关部门审批、核准和备案的项目(以下简称“地方项目”)。"},{"i":6,"n":"第六条","txt":"在线平台工作体系由综合管理部门、应用管理部门、建设运维部门共同组成。"},{"i":7,"n":"第七条","txt":"综合管理部门是指统筹协调推进在线平台建设、应用、规范运行的部门。负责研究制定相关管理制度、业务规则和标准规范并督促落实，开展绩效管理。 中央平台综合管理部门为国家发展改革委。履行地方平台综合管理职责的相关单位由地方政府指定。"},{"i":8,"n":"第八条","txt":"应用管理部门是指履行各类项目审批和监管职能，并通过在线平台办理和归集信息的部门。负责制定相关内部工作规则，编制完善、及时公开办事指南，包括审批依据、审批内容、受理条件、办理流程、办理时限、收费标准、监管要求、联系方式等;及时共享相关事项办理信息;为企业提供相关咨询服务;建设完善本部门与审批监管相关的业务系统，指导协调本系统在线平台建设和运行工作;督促项目单位通过在线平台及时报送项目开工建设、建设进度、竣工等基本信息，支撑协同监管。 应用管理部门按照法律法规规定，负责办理本办法第三条所列事项。"},{"i":9,"n":"第九条","txt":"建设运维部门是指在线平台建设、运行维护和数据管理的部门。负责建设与完善在线平台功能，满足业务需要;制定运行维护细则、安全保障方案和安全防护策略，确保在线平台安全稳定运行。 中央平台建设运维部门为国家信息中心。地方平台由地方政府指定相关单位负责。"},{"i":10,"n":"第十条","txt":"各类项目实行统一代码制度。项目代码是项目整个建设周期的唯一身份标识，一项一码。项目代码由在线平台生成，项目办理信息、监管(处罚)信息，以及工程实施过程中的重要信息，统一汇集至项目代码。"},{"i":11,"n":"第十一条","txt":"编码规则由中央平台综合管理部门统一制定。项目应按照本办法第五条规定的隶属关系，分别由中央平台和地方平台赋码。"},{"i":12,"n":"第十二条","txt":"项目已有非在线平台编码的，要按照在线平台统一规则赋予项目代码，并与原编码进行对应。 项目延期或调整的，项目代码保持不变;项目发生重大变化，需要重新审批、核准、备案的，应当重新赋码。"},{"i":13,"n":"第十三条","txt":"应用管理部门要推行项目代码应用，审批文件、项目招标投标、信息公开等涉及使用项目名称时，应当同时标注项目代码。应用管理部门办理项目相关审批事项、下达资金等，要首先核验项目代码。"},{"i":14,"n":"第十四条","txt":"项目单位在线申报，获取项目代码;各应用管理部门依责办理，优化服务。各级在线平台要强化技术手段，支持有关业务实现全程网上办理。项目单位在审批事项办结后，要按要求及时报送项目实施情况。 (一)项目申报。项目单位根据本办法第五条的规定，通过相应的在线平台填报项目信息，获取项目代码。填报项目信息时，项目单位应当根据在线平台所公开的办事指南真实完整准确填报。在线平台应当根据办事指南和项目申报信息等，向项目单位告知应办事项，强化事前服务。项目单位凭项目代码根据平台所示的办事指南提交所需的申报材料。项目变更、中止，项目单位应当通过在线平台申请。 (二)项目受理。应用管理部门应当依据有关法律法规受理审批事项申请，接收申报材料应当核验项目代码，对未通过项目代码核验的，不得受理并告知项目单位。应用管理部门受理后，在线平台开始计时。 (三)项目办理。应用管理部门应当依据有关法律法规办理审批事项，通过在线平台"},{"i":15,"n":"第十五条","txt":"在线平台根据应用管理部门相关事项办理时限要求，进行计时，并根据实际进度进行自动提示。不纳入审批事项办理时限的相关环节，在线平台根据应用管理部门提供的信息调整计时节点。"},{"i":16,"n":"第十六条","txt":"应用管理部门在审批过程中需委托中介服务的，中介服务事项及其委托办理过程要纳入在线平台运行，接受监督。"},{"i":17,"n":"第十七条","txt":"在线平台支持各级各部门纵横协同办理项目审批事项。涉及中央和地方需要交换的项目及审批事项信息，应当及时在中央平台和省级地方平台之间交换。"},{"i":18,"n":"第十八条","txt":"项目审批信息、监管信息、处罚结果等要及时通过在线平台向社会公开。项目单位可凭项目代码查询项目办理过程及审批结果。"},{"i":19,"n":"第十九条","txt":"全国信用信息共享平台、全国公共资源交易平台和招标投标公共服务平台、公共政务信息共享平台以及各级政府有关部门相关信息系统应当依据法律法规并按照权限与在线平台开展数据共享与交换。与统计部门的数据共享和交换，应当符合政府统计法律制度。"},{"i":20,"n":"第二十条","txt":"建设运维部门要建立健全配套的运行维护管理制度，设置专职岗位和人员安排在线平台升级改造及运维所需经费，并列入本级建设运维单位的部门财政预算，保障在线平台安全稳定运行。"},{"i":21,"n":"第二十一条","txt":"各级在线平台要满足国家信息安全等级保护第三级的有关要求。建设运维部门要实时监控在线平台运行情况，严格实行安全防护策略，完善数据备份、恢复和容灾机制。"},{"i":22,"n":"第二十二条","txt":"各级在线平台要按照在线平台统一制定的数据接口规范和数据交换频率进行对接和数据交换，当数据规范调整时，各级在线平台要按要求及时进行适应性调整。建设运维部门会同应用管理部门保证数据质量。"},{"i":23,"n":"第二十三条","txt":"本办法由国家发展改革委会同有关部门负责解释。"},{"i":24,"n":"第二十四条","txt":"各部门、各地方应根据本办法制订完善本部门、本地区的具体运行管理办法及配套管理规则，共同加强管理，保证平稳运行。"},{"i":25,"n":"第二十五条","txt":"本办法自2017年6月25日起施行。"}],"quanguotouzixiangmuzaixianshenpijianguanpingtaiyunf4818a":[{"i":1,"n":"第一条","txt":"为加强全国投资项目在线审批监管平台（以下简称“在线平台”）建设、应用和管理，确保在线平台逐步完善、稳定运行并发挥作用，根据《中共中央、国务院关于深化投融资体制改革的意见》、《政府投资条例》、《企业投资项目核准和备案管理条例》等法律法规和改革要求，结合工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"在线平台是指依托互联网和国家电子政务外网（以下简称“政务外网”）建设的固定资产投资项目（以下简称“项目”）综合管理服务平台。 各级政府及其部门应当通过在线平台实现项目网上申报、并联审批、信息公开、协同监管，不断优化办事流程，提高服务水平，并加强事中事后监管，主动接受社会监督。"},{"i":3,"n":"第三条","txt":"在线平台适用于各类项目建设实施全过程的审批、监管和服务，包括行政许可、政府内部审批、备案、评估评审、技术审查，项目实施情况监测，以及政策法规、规划咨询服务等。涉密项目及信息不得通过在线平台办理和传递。"},{"i":4,"n":"第四条","txt":"各级在线平台由互联网门户网站和政务外网审批监管系统构成。互联网门户网站是项目单位和社会公众网上申报、查询办理情况的统一窗口，提供办事指南、中介服务、政策信息等服务指引；审批监管系统是联接各级政府部门相关信息系统开展并联审批、电子监察、项目监管、数据分析的工作平台。 利用大数据分析加强监测预测、风险预警，按照精细化管理要求，加强事中事后监管。充分利用平台痕迹管理功能，增强透明度，对各个环节做到可检查、可考核。"},{"i":5,"n":"第五条","txt":"在线平台由中央平台和地方平台组成。中央平台负责管理由国务院及其相关部门审批、核准和备案的项目（以下简称“中央项目”）。地方平台负责管理地方各级政府及其相关部门审批、核准和备案的项目（以下简称“地方项目”）。"},{"i":6,"n":"第六条","txt":"在线平台工作体系由综合管理部门、应用管理部门、建设运维部门共同组成。"},{"i":7,"n":"第七条","txt":"综合管理部门是指统筹协调推进在线平台建设、应用、规范运行的部门。负责研究制定相关管理制度、业务规则和标准规范并督促落实，开展绩效管理。 中央平台综合管理部门为国家发展改革委。履行地方平台综合管理职责的相关单位由地方政府指定。"},{"i":8,"n":"第八条","txt":"应用管理部门是指履行各类项目审批和监管职能，并通过在线平台办理和归集信息的部门。负责制定相关内部工作规则，编制完善、及时公开办事指南，包括审批依据、审批内容、受理条件、办理流程、办理时限、收费标准、监管要求、联系方式等；及时共享相关事项办理信息；为企业提供相关咨询服务；建设完善本部门与审批监管相关的业务系统，指导协调本系统在线平台建设和运行工作；督促项目单位通过在线平台及时报送项目开工建设、建设进度、竣工等基本信息，支撑协同监管。应用管理部门按照法律法规规定，负责办理本办法第三条所列事项。"},{"i":9,"n":"第九条","txt":"建设运维部门是指在线平台建设、运行维护和数据管理的部门。负责建设与完善在线平台功能，满足业务需要；制定运行维护细则、安全保障方案和安全防护策略，确保在线平台安全稳定运行。 中央平台建设运维部门为国家信息中心。地方平台由地方政府指定相关单位负责。"},{"i":10,"n":"第十条","txt":"各类项目实行统一代码制度。项目代码是项目整个建设周期的唯一身份标识，一项一码。项目代码由在线平台生成，项目办理信息、监管（处罚）信息，以及工程实施过程中的重要信息，统一汇集至项目代码。"},{"i":11,"n":"第十一条","txt":"编码规则由中央平台综合管理部门统一制定。项目应按照本办法第五条规定的隶属关系，分别由中央平台和地方平台赋码。"},{"i":12,"n":"第十二条","txt":"项目已有非在线平台编码的，要按照在线平台统一规则赋予项目代码，并与原编码进行对应。 项目延期或调整的，项目代码保持不变；项目发生重大变化，需要重新审批、核准、备案的，应当重新赋码。"},{"i":13,"n":"第十三条","txt":"应用管理部门要推行项目代码应用，审批文件、项目招标投标、信息公开等涉及使用项目名称时，应当同时标注项目代码。应用管理部门办理项目相关审批事项、下达资金等，要首先核验项目代码。"},{"i":14,"n":"第十四条","txt":"项目单位在线申报，获取项目代码；各应用管理部门依责办理，优化服务。各级在线平台要强化技术手段，支持有关业务实现全程网上办理。项目单位在审批事项办结后，要按要求及时报送项目实施情况。 （一）项目申报。项目单位根据本办法第五条的规定，通过相应的在线平台填报项目信息，获取项目代码。填报项目信息时，项目单位应当根据在线平台所公开的办事指南真实完整准确填报。在线平台应当根据办事指南和项目申报信息等，向项目单位告知应办事项，强化事前服务。项目单位凭项目代码根据平台所示的办事指南提交所需的申报材料。项目变更、中止，项目单位应当通过在线平台申请。 （二）项目受理。应用管理部门应当依据有关法律法规受理审批事项申请，接收申报材料应当核验项目代码，对未通过项目代码核验的，不得受理并告知项目单位。应用管理部门受理后，在线平台开始计时。 （三）项目办理。应用管理部门应当依据有关法律法规办理审批事项，通过在线平台"},{"i":15,"n":"第十五条","txt":"在线平台根据应用管理部门相关事项办理时限要求，进行计时，并根据实际进度进行自动提示。不纳入审批事项办理时限的相关环节，在线平台根据应用管理部门提供的信息调整计时节点。"},{"i":16,"n":"第十六条","txt":"应用管理部门在审批过程中需委托中介服务的，中介服务事项及其委托办理过程要纳入在线平台运行，接受监督。"},{"i":17,"n":"第十七条","txt":"在线平台支持各级各部门纵横协同办理项目审批事项。涉及中央和地方需要交换的项目及审批事项信息，应当及时在中央平台和省级地方平台之间交换。"},{"i":18,"n":"第十八条","txt":"项目审批信息、监管信息、处罚结果等要及时通过在线平台向社会公开。项目单位可凭项目代码查询项目办理过程及审批结果。"},{"i":19,"n":"第十九条","txt":"全国信用信息共享平台、全国公共资源交易平台和招标投标公共服务平台、公共政务信息共享平台以及各级政府有关部门相关信息系统应当依据法律法规并按照权限与在线平台开展数据共享与交换。与统计部门的数据共享和交换，应当符合政府统计法律制度。"},{"i":20,"n":"第二十条","txt":"建设运维部门要建立健全配套的运行维护管理制度，设置专职岗位和人员安排在线平台升级改造及运维所需经费，并列入本级建设运维单位的部门财政预算，保障在线平台安全稳定运行。"},{"i":21,"n":"第二十一条","txt":"各级在线平台要满足国家信息安全等级保护第三级的有关要求。建设运维部门要实时监控在线平台运行情况，严格实行安全防护策略，完善数据备份、恢复和容灾机制。"},{"i":22,"n":"第二十二条","txt":"各级在线平台要按照在线平台统一制定的数据接口规范和数据交换频率进行对接和数据交换，当数据规范调整时，各级在线平台要按要求及时进行适应性调整。建设运维部门会同应用管理部门保证数据质量。"},{"i":23,"n":"第二十三条","txt":"本办法由国家发展改革委会同有关部门负责解释。"},{"i":24,"n":"第二十四条","txt":"各部门、各地方应根据本办法制订完善本部门、本地区的具体运行管理办法及配套管理规则，共同加强管理，保证平稳运行。"}],"gonggongjigounengyuanshenjiguanlizanxingbanfa-2":[{"i":1,"n":"第一条","txt":"为加强公共机构节能管理，规范公共机构能源审计工作，提高公共机构能源利用效率，节约财政支出，根据《中华人民共和国节约能源法》、《党政机关厉行节约反对浪费条例》和《公共机构节能条例》等法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"公共机构能源审计是指依据有关法律、法规和标准，对公共机构的用能系统、设备的运行、管理及能源资源利用状况进行检验、核查和技术、经济分析评价，提出改进用能方式或提高用能效率建议和意见的行为。公共机构能源审计可由公共机构自行或委托能源审计服务机构，或由管理机关事务工作的机构委托能源审计服务机构实施。"},{"i":3,"n":"第三条","txt":"公共机构能源审计应当坚持“全面客观、突出重点、量化细化、安全保密”原则。"},{"i":4,"n":"第四条","txt":"国务院管理节能工作的部门会同国务院管理机关事务工作的机构，推进全国公共机构能源审计工作。县级以上管理节能工作的部门会同同级地方人民政府管理机关事务工作的机构，推进本地区公共机构能源审计工作。教育、科技、文化、卫生、体育等系统各级主管部门在同级管理机关事务工作的机构指导下，推进本级系统内公共机构能源审计工作。"},{"i":5,"n":"第五条","txt":"县级以上各级人民政府管理机关事务工作的机构应当将能源审计工作内容纳入公共机构节能规划和工作计划，并与节能改造、合同能源管理、用能标准制定等工作相衔接。"},{"i":6,"n":"第六条","txt":"年能源消费量达500吨标准煤以上或年电力消耗200万千瓦时以上或建筑面积1万平方米以上的公共机构或集中办公区每 5年应开展一次能源审计，并纳入政府购买服务范围。 对存在下列情况之一的本级公共机构或集中办公区，县级以上各级人民政府管理机关事务工作的机构应结合工作实际，委托能源审计服务机构，组织开展能源审计： （一）年能源消费总量占本级公共机构能源消费比重排前 10%的； （二）与上一年度相比年度能源消费量增长超过 20%的； （三）未完成年度节能目标任务的； （四）其他有必要实施能源审计情况的。"},{"i":7,"n":"第七条","txt":"县级以上各级人民政府管理机关事务工作的机构组织开展能源审计应符合以下要求： （一）在实施能源审计10个工作日前，应书面通知被审计公共机构准备好相关资料； （二）能源审计工作周期不超过1年，累计工作日不超过45天。"},{"i":8,"n":"第八条","txt":"能源审计服务机构须具有独立法人资格，具备履行能源审计工作所必须的检验、测试等专业技术能力，具备相关领域认证资质或实验室认可资质。鼓励具备采用合同能源管理方式提供节能服务经验的企业承担能源审计服务工作。"},{"i":9,"n":"第九条","txt":"能源审计服务机构开展能源审计，应符合《公共机构能源审计技术导则》及相关规范性文件的要求。提供节能服务经验的企业承担能源审计服务工作。"},{"i":10,"n":"第十条","txt":"能源审计服务机构形成的能源审计报告应当书面征求被审计公共机构意见，被审计公共机构应当自接到能源审计报告之日起 10个工作日内，提出书面意见。能源审计服务机构要进一步核实情况，对审计报告做相应修改，送达被审计公共机构；10个工作日内被审计公共机构未提出书面意见的，视同无异议。"},{"i":11,"n":"第十一条","txt":"公共机构应当根据能源审计报告提出的建议和意见，采取提高能源利用效率的措施，2月内制定整改方案。公共机构应对所属公共机构能源审计工作情况进行监督检查，督促其及时整改。 县级以上人民政府管理机关事务工作的机构应对法定职责范围内公共机构能源审计工作情况进行监督检查，督促其及时整改。 公共机构能源审计开展情况应作为节能目标责任评价考核的重要内容。"},{"i":12,"n":"第十二条","txt":"公共机构应及时将本级及所属公共机构的能源审计报告、整改方案报送同级管理机关事务工作的机构。 县级以上人民政府管理机关事务工作的机构应于每年3月底前将上一年度法定职责范围内公共机构能源审计情况报送上级人民政府管理机关事务工作的机构，并抄送同级节能主管部门和有关行业主管部门。"},{"i":13,"n":"第十三条","txt":"能源审计服务机构及工作人员须为被审计公共机构保守秘密，不得泄露国家秘密、商业秘密和技术秘密。"},{"i":14,"n":"第十四条","txt":"能源审计服务机构有下列行为之一的，县级以上人民政府管理机关事务工作的机构应立即中止其能源审计工作，并会同管理节能工作的部门在官方网站按照有关规定向社会公示，并纳入信用体系记录，并依法追究其责任： （一）在能源审计过程中违纪违规的； （二）未履行能源审计合同的； （三）能源审计结果与事实严重不符，有重大偏差的； （四）未履行保密责任的。"},{"i":15,"n":"第十五条","txt":"公共机构有下列行为之一的，由本级人民政府管理机关事务工作的机构会同管理节能工作的部门责令限期整改；逾期不改正的，予以通报： （一）未按本办法规定组织实施能源审计的； （二）拒绝、阻碍能源审计的； （三）拒绝、拖延提供与能源审计有关资料，或者提供的资料不真实、不完整的； （四）未按照能源审计结果进行整改的。"},{"i":16,"n":"第十六条","txt":"县级以上各级人民政府管理机关事务工作的机构组织开展能源审计的工作经费，应按照国家有关规定列入部门预算，并按照规定程序向同级财政部门申请。"},{"i":17,"n":"第十七条","txt":"本办法由国家发展改革委会同国家机关事务管理局负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自2016年3月1日起施行。"}],"gonggongjigounengyuanshenjiguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为加强公共机构节能管理，规范公共机构能源审计工作，提高公共机构能源利用效率，节约财政支出，根据《中华人民共和国节约能源法》、《党政机关厉行节约反对浪费条例》和《公共机构节能条例》等法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"公共机构能源审计是指依据有关法律、法规和标准，对公共机构的用能系统、设备的运行、管理及能源资源利用状况进行检验、核查和技术、经济分析评价，提出改进用能方式或提高用能效率建议和意见的行为。公共机构能源审计可由公共机构自行或委托能源审计服务机构，或由管理机关事务工作的机构委托能源审计服务机构实施。"},{"i":3,"n":"第三条","txt":"公共机构能源审计应当坚持“全面客观、突出重点、量化细化、安全保密”原则。"},{"i":4,"n":"第四条","txt":"国务院管理节能工作的部门会同国务院管理机关事务工作的机构，推进全国公共机构能源审计工作。 县级以上管理节能工作的部门会同同级地方人民政府管理机关事务工作的机构，推进本地区公共机构能源审计工作。 教育、科技、文化、卫生、体育等系统各级主管部门在同级管理机关事务工作的机构指导下，推进本级系统内公共机构能源审计工作。"},{"i":5,"n":"第五条","txt":"县级以上各级人民政府管理机关事务工作的机构应当将能源审计工作内容纳入公共机构节能规划和工作计划，并与节能改造、合同能源管理、用能标准制定等工作相衔接。"},{"i":6,"n":"第六条","txt":"年能源消费量达500吨标准煤以上或年电力消耗200万千瓦时以上或建筑面积1万平方米以上的公共机构或集中办公区每5年应开展一次能源审计，并纳入政府购买服务范围。 对存在下列情况之一的本级公共机构或集中办公区，县级以上各级人民政府管理机关事务工作的机构应结合工作实际，委托能源审计服务机构，组织开展能源审计： (一)年能源消费总量占本级公共机构能源消费比重排前10%的; (二)与上一年度相比年度能源消费量增长超过20%的; (三)未完成年度节能目标任务的; (四)其他有必要实施能源审计情况的。"},{"i":7,"n":"第七条","txt":"县级以上各级人民政府管理机关事务工作的机构组织开展能源审计应符合以下要求： (一)在实施能源审计10个工作日前，应书面通知被审计公共机构准备好相关资料; (二)能源审计工作周期不超过1年，累计工作日不超过45天。"},{"i":8,"n":"第八条","txt":"能源审计服务机构须具有独立法人资格，具备履行能源审计工作所必须的检验、测试等专业技术能力，具备相关领域认证资质或实验室认可资质。鼓励具备采用合同能源管理方式提供节能服务经验的企业承担能源审计服务工作。"},{"i":9,"n":"第九条","txt":"能源审计服务机构开展能源审计，应符合《公共机构能源审计技术导则》及相关规范性文件的要求。"},{"i":10,"n":"第十条","txt":"能源审计服务机构形成的能源审计报告应当书面征求被审计公共机构意见，被审计公共机构应当自接到能源审计报告之日起10个工作日内，提出书面意见。能源审计服务机构要进一步核实情况，对审计报告做相应修改，送达被审计公共机构;10个工作日内被审计公共机构未提出书面意见的，视同无异议。"},{"i":11,"n":"第十一条","txt":"公共机构应当根据能源审计报告提出的建议和意见，采取提高能源利用效率的措施，2月内制定整改方案。 公共机构应对所属公共机构能源审计工作情况进行监督检查，督促其及时整改。 县级以上人民政府管理机关事务工作的机构应对法定职责范围内公共机构能源审计工作情况进行监督检查，督促其及时整改。 公共机构能源审计开展情况应作为节能目标责任评价考核的重要内容。"},{"i":12,"n":"第十二条","txt":"公共机构应及时将本级及所属公共机构的能源审计报告、整改方案报送同级管理机关事务工作的机构。 县级以上人民政府管理机关事务工作的机构应于每年3月底前将上一年度法定职责范围内公共机构能源审计情况报送上级人民政府管理机关事务工作的机构，并抄送同级节能主管部门和有关行业主管部门。"},{"i":13,"n":"第十三条","txt":"能源审计服务机构及工作人员须为被审计公共机构保守秘密，不得泄露国家秘密、商业秘密和技术秘密。"},{"i":14,"n":"第十四条","txt":"能源审计服务机构有下列行为之一的，县级以上人民政府管理机关事务工作的机构应立即中止其能源审计工作，并会同管理节能工作的部门在官方网站按照有关规定向社会公示，并纳入信用体系记录，并依法追究其责任： (一)在能源审计过程中违纪违规的; (二)未履行能源审计合同的; (三)能源审计结果与事实严重不符，有重大偏差的; (四)未履行保密责任的。"},{"i":15,"n":"第十五条","txt":"公共机构有下列行为之一的，由本级人民政府管理机关事务工作的机构会同管理节能工作的部门责令限期整改;逾期不改正的，予以通报： (一)未按本办法规定组织实施能源审计的; (二)拒绝、阻碍能源审计的; (三)拒绝、拖延提供与能源审计有关资料，或者提供的资料不真实、不完整的; (四)未按照能源审计结果进行整改的。"},{"i":16,"n":"第十六条","txt":"县级以上各级人民政府管理机关事务工作的机构组织开展能源审计的工作经费，应按照国家有关规定列入部门预算，并按照规定程序向同级财政部门申请。"},{"i":17,"n":"第十七条","txt":"本办法由国家发展改革委会同国家机关事务管理局负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自2016年3月1日起施行。"}],"gonggongziyuanjiaoyipingtaiguanlizanxingbanfa-2":[{"i":1,"n":"第一条","txt":"为规范公共资源交易平台运行，提高公共资源配置效率和效益，加强对权力运行的监督制约，维护国家利益、社会公共利益和交易当事人的合法权益，根据有关法律法规和《国务院办公厅关于印发整合建立统一的公共资源交易平台工作方案的通知》（国办发〔2015〕63号），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于公共资源交易平台的运行、服务和监督管理。"},{"i":3,"n":"第三条","txt":"本办法所称公共资源交易平台是指实施统一的制度和标准、具备开放共享的公共资源交易电子服务系统和规范透明的运行机制，为市场主体、社会公众、行政监督管理部门等提供公共资源交易综合服务的体系。 公共资源交易是指涉及公共利益、公众安全的具有公有性、公益性的资源交易活动。"},{"i":4,"n":"第四条","txt":"公共资源交易平台应当立足公共服务职能定位，坚持电子化平台的发展方向，遵循开放透明、资源共享、高效便民、守法诚信的运行服务原则。"},{"i":5,"n":"第五条","txt":"公共资源交易平台要利用信息网络推进交易电子化,实现全流程透明化管理。"},{"i":6,"n":"第六条","txt":"国务院发展改革部门会同国务院有关部门统筹指导和协调全国公共资源交易平台相关工作。 设区的市级以上地方人民政府发展改革部门或政府指定的部门会同有关部门负责本行政区域的公共资源交易平台指导和协调等相关工作。 各级招标投标、财政、国土资源、国有资产等行政监督管理部门按照规定的职责分工，负责公共资源交易活动的监督管理。"},{"i":7,"n":"第七条","txt":"公共资源交易平台的运行应当遵循相关法律法规和国务院有关部门制定的各领域统一的交易规则，以及省级人民政府颁布的平台服务管理细则。"},{"i":8,"n":"第八条","txt":"依法必须招标的工程建设项目招标投标、国有土地使用权和矿业权出让、国有产权交易、政府采购等应当纳入公共资源交易平台。 国务院有关部门和地方人民政府结合实际，推进其他各类公共资源交易纳入统一平台。纳入平台交易的公共资源项目，应当公开听取意见，并向社会公布。"},{"i":9,"n":"第九条","txt":"公共资源交易平台应当按照国家统一的技术标准和数据规范，建立公共资源交易电子服务系统，开放对接各类主体依法建设的公共资源电子交易系统和政府有关部门的电子监管系统。"},{"i":10,"n":"第十条","txt":"公共资源交易项目的实施主体根据交易标的专业特性，选择使用依法建设和运行的电子交易系统。"},{"i":11,"n":"第十一条","txt":"公共资源交易项目依法需要评标、评审的，应当按照全国统一的专家专业分类标准，从依法建立的综合评标、政府采购评审等专家库中随机抽取专家，法律法规另有规定的除外。 有关行政监督管理部门按照规定的职责分工，对专家实施监督管理。 鼓励有条件的地方跨区域选择使用专家资源。"},{"i":12,"n":"第十二条","txt":"公共资源交易平台应当按照省级人民政府规定的场所设施标准，充分利用已有的各类场所资源，为公共资源交易活动提供必要的现场服务设施。 市场主体依法建设的交易场所符合省级人民政府规定标准的，可以在现有场所办理业务。"},{"i":13,"n":"第十三条","txt":"公共资源交易平台应当建立健全网络信息安全制度，落实安全保护技术措施，保障平台平稳运行。"},{"i":14,"n":"第十四条","txt":"公共资源交易平台的服务内容、服务流程、工作规范、收费标准和监督渠道应当按照法定要求确定，并通过公共资源交易电子服务系统向社会公布。"},{"i":15,"n":"第十五条","txt":"公共资源交易平台应当推行网上预约和服务事项办理。确需在现场办理的，实行窗口集中，简化流程，限时办结。"},{"i":16,"n":"第十六条","txt":"公共资源交易平台应当将公共资源交易公告、资格审查结果、交易过程信息、成交信息、履约信息等，通过公共资源交易电子服务系统依法及时向社会公开。涉及国家秘密、商业秘密、个人隐私以及其他依法应当保密的信息除外。 公共资源交易平台应当无偿提供依法必须公开的信息。"},{"i":17,"n":"第十七条","txt":"交易服务过程中产生的电子文档、纸质资料以及音视频等，应当按照规定的期限归档保存。"},{"i":18,"n":"第十八条","txt":"公共资源交易平台运行服务机构及其工作人员不得从事以下活动： （一）行使任何审批、备案、监管、处罚等行政监督管理职能； （二）违法从事或强制指定招标、拍卖、政府采购代理、工程造价等中介服务； （三）强制非公共资源交易项目进入平台交易； （四）干涉市场主体选择依法建设和运行的公共资源电子交易系统； （五）非法扣押企业和人员的相关证照资料； （六）通过设置注册登记、设立分支机构、资质验证、投标（竞买）许可、强制担保等限制性条件阻碍或者排斥其他地区市场主体进入本地区公共资源交易市场； （七）违法要求企业法定代表人到场办理相关手续; （八）其他违反法律法规规定的情形。"},{"i":19,"n":"第十九条","txt":"公共资源交易平台运行服务机构提供公共服务确需收费的，不得以营利为目的。根据平台运行服务机构的性质，其收费分别纳入行政事业性收费和经营服务性收费管理，具体收费项目和收费标准按照有关规定执行。属于行政事业性收费的，按照本级政府非税收入管理的有关规定执行。"},{"i":20,"n":"第二十条","txt":"公共资源交易平台运行服务机构发现公共资源交易活动中有违法违规行为的，应当保留相关证据并及时向有关行政监督管理部门报告。"},{"i":21,"n":"第二十一条","txt":"各级行政监督管理部门应当将公共资源交易活动当事人资质资格、信用奖惩、项目审批和违法违规处罚等信息，自作出行政决定之日起7个工作日内上网公开，并通过相关电子监管系统交换至公共资源交易电子服务系统。"},{"i":22,"n":"第二十二条","txt":"各级公共资源交易平台应当依托统一的社会信用代码，记录公共资源交易过程中产生的市场主体和专家信用信息，并通过国家公共资源交易电子服务系统实现信用信息交换共享和动态更新。"},{"i":23,"n":"第二十三条","txt":"国务院发展改革部门牵头建立国家公共资源交易电子服务系统，与省级公共资源交易电子服务系统和有关部门建立的电子系统互联互通，实现市场主体信息、交易信息、行政监管信息的集中交换和同步共享。"},{"i":24,"n":"第二十四条","txt":"省级人民政府应当搭建全行政区域统一、终端覆盖市县的公共资源交易电子服务系统，对接国家公共资源交易电子服务系统和有关部门建立的电子系统，按照有关规定交换共享信息。有关电子招标投标、政府采购等系统应当分别与国家电子招标投标公共服务系统、政府采购管理交易系统对接和交换信息。"},{"i":25,"n":"第二十五条","txt":"公共资源交易电子服务系统应当分别与投资项目在线审批监管系统、信用信息共享系统对接，交换共享公共资源交易相关信息、项目审批核准信息和信用信息。"},{"i":26,"n":"第二十六条","txt":"市场主体已经在公共资源电子交易系统登记注册，并通过公共资源交易电子服务系统实现信息共享的，有关行政监督管理部门和公共资源交易平台运行服务机构不得强制要求其重复登记、备案和验证。"},{"i":27,"n":"第二十七条","txt":"公共资源交易电子服务系统应当支持不同电子认证数字证书的兼容互认。"},{"i":28,"n":"第二十八条","txt":"公共资源交易平台和有关行政监督管理部门在公共资源交易数据采集、汇总、传输、存储、公开、使用过程中，应加强数据安全管理。涉密数据的管理，按照有关法律规定执行。"},{"i":29,"n":"第二十九条","txt":"各级行政监督管理部门按照规定的职责分工，加强对公共资源交易活动的事中事后监管，依法查处违法违规行为。 对利用职权违规干预和插手公共资源交易活动的国家机关或国有企事业单位工作人员，依纪依法予以处理。 各级审计部门应当对公共资源交易平台运行依法开展审计监督。"},{"i":30,"n":"第三十条","txt":"设区的市级以上地方人民政府应当推动建立公共资源交易电子监管系统，实现对项目登记，公告发布，开标评标或评审、竞价，成交公示，交易结果确认，投诉举报，交易履约等交易全过程监控。 公共资源交易电子服务系统和其对接的公共资源电子交易系统应当实时向监管系统推送数据。"},{"i":31,"n":"第三十一条","txt":"建立市场主体公共资源交易活动事前信用承诺制度，要求市场主体以规范格式向社会作出公开承诺，并纳入交易主体信用记录，接受社会监督。"},{"i":32,"n":"第三十二条","txt":"各级行政监督管理部门应当将公共资源交易主体信用信息作为市场准入、项目审批、资质资格审核的重要依据。 建立行政监督管理部门、司法机关等部门联合惩戒机制，对在公共资源交易活动中有不良行为记录的市场主体，依法限制或禁止其参加招标投标、国有土地使用权出让和矿业权出让、国有产权交易、政府采购等公共资源交易活动。 建立公共资源交易相关信息与同级税务机关共享机制，推进税收协作。"},{"i":33,"n":"第三十三条","txt":"各级行政监督管理部门应当运用大数据技术，建立公共资源交易数据关联比对分析机制，开展监测预警，定期进行效果评估，及时调整监管重点。"},{"i":34,"n":"第三十四条","txt":"各级行政监督管理部门应当建立联合抽查机制，对有效投诉举报多或有违法违规记录情况的市场主体，加大随机抽查力度。 行政监督管理部门履行监督管理职责过程中，有权查阅、复制公共资源交易活动有关文件、资料和数据。公共资源交易平台运行服务机构应当如实提供相关情况。"},{"i":35,"n":"第三十五条","txt":"建立由市场主体以及第三方参与的社会评价机制，对所辖行政区域公共资源交易平台运行服务机构提供公共服务情况进行评价。"},{"i":36,"n":"第三十六条","txt":"市场主体或社会公众认为公共资源交易平台运行服务机构及其工作人员存在违法违规行为的，可以依法向政府有关部门投诉、举报。"},{"i":37,"n":"第三十七条","txt":"公共资源交易领域的行业协会应当发挥行业组织作用，加强自律管理和服务。"},{"i":38,"n":"第三十八条","txt":"公共资源交易平台运行服务机构未公开服务内容、服务流程、工作规范、收费标准和监督渠道，由政府有关部门责令限期改正。拒不改正的，予以通报批评。"},{"i":39,"n":"第三十九条","txt":"公共资源交易平台运行服务机构及其工作人员违反本办法第十八条禁止性规定的，由政府有关部门责令限期改正，并予以通报批评。情节严重的，依法追究直接责任人和有关领导的责任。构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"公共资源交易平台运行服务机构违反本办法第十九条规定收取费用的，由同级价格主管部门会同有关部门责令限期改正。拒不改正的，依照《中华人民共和国价格法》、《价格违法行为行政处罚规定》等给予处罚，并予以公示。"},{"i":41,"n":"第四十一条","txt":"公共资源交易平台运行服务机构未按照本办法规定在公共资源交易电子服务系统公开、交换、共享信息的，由政府有关部门责令限期改正。拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分，并予以通报。"},{"i":42,"n":"第四十二条","txt":"公共资源交易平台运行服务机构限制市场主体建设的公共资源电子交易系统对接公共资源交易电子服务系统的，由政府有关部门责令限期改正。拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分，并予以通报。"},{"i":43,"n":"第四十三条","txt":"公共资源交易平台运行服务机构及其工作人员向他人透露依法应当保密的公共资源交易信息的，由政府有关部门责令限期改正，并予以通报批评。情节严重的，依法追究直接责任人和有关领导的责任。构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"有关行政监督管理部门、公共资源交易平台运行服务机构及其工作人员徇私舞弊、滥用职权、弄虚作假、玩忽职守，未依法履行职责的，依法给予处分;构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"公共资源电子交易系统是根据工程建设项目招标投标、土地使用权和矿业权出让、国有产权交易、政府采购等各类交易特点，按照有关规定建设、对接和运行，以数据电文形式完成公共资源交易活动的信息系统。 公共资源交易电子监管系统是指政府有关部门在线监督公共资源交易活动的信息系统。 公共资源交易电子服务系统是指联通公共资源电子交易系统、监管系统和其他电子系统，实现公共资源交易信息数据交换共享，并提供公共服务的枢纽。"},{"i":46,"n":"第四十六条","txt":"公共资源交易平台运行服务机构是指由政府推动设立或政府通过购买服务等方式确定的，通过资源整合共享方式，为公共资源交易相关市场主体、社会公众、行政监督管理部门等提供公共服务的单位。"},{"i":47,"n":"第四十七条","txt":"本办法由国务院发展改革部门会同国务院有关部门负责解释。"},{"i":48,"n":"第四十八条","txt":"本办法自2016年8月1日起实施。"}],"gonggongziyuanjiaoyipingtaiguanlizanxingbanfa-3":[{"i":1,"n":"第一条","txt":"为规范公共资源交易平台运行，提高公共资源配置效率和效益，加强对权力运行的监督制约，维护国家利益、社会公共利益和交易当事人的合法权益，根据有关法律法规和《国务院办公厅关于印发整合建立统一的公共资源交易平台工作方案的通知》（国办发[2015]63号），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于公共资源交易平台的运行、服务和监督管理。"},{"i":3,"n":"第三条","txt":"本办法所称公共资源交易平台是指实施统一的制度和标准、具备开放共享的公共资源交易电子服务系统和规范透明的运行机制，为市场主体、社会公众、行政监督管理部门等提供公共资源交易综合服务的体系。 公共资源交易是指涉及公共利益、公众安全的具有公有性、公益性的资源交易活动。"},{"i":4,"n":"第四条","txt":"公共资源交易平台应当立足公共服务职能定位，坚持电子化平台的发展方向，遵循开放透明、资源共享、高效便民、守法诚信的运行服务原则。"},{"i":5,"n":"第五条","txt":"公共资源交易平台要利用信息网络推进交易电子化，实现全流程透明化管理。"},{"i":6,"n":"第六条","txt":"国务院发展改革部门会同国务院有关部门统筹指导和协调全国公共资源交易平台相关工作。 设区的市级以上地方人民政府发展改革部门或政府指定的部门会同有关部门负责本行政区域的公共资源交易平台指导和协调等相关工作。 各级招标投标、财政、国土资源、国有资产等行政监督管理部门按照规定的职责分工，负责公共资源交易活动的监督管理。"},{"i":7,"n":"第七条","txt":"公共资源交易平台的运行应当遵循相关法律法规和国务院有关部门制定的各领域统一的交易规则，以及省级人民政府颁布的平台服务管理细则。"},{"i":8,"n":"第八条","txt":"依法必须招标的工程建设项目招标投标、国有土地使用权和矿业权出让、国有产权交易、政府采购等应当纳入公共资源交易平台。 国务院有关部门和地方人民政府结合实际，推进其他各类公共资源交易纳入统一平台。纳入平台交易的公共资源项目，应当公开听取意见，并向社会公布。"},{"i":9,"n":"第九条","txt":"公共资源交易平台应当按照国家统一的技术标准和数据规范，建立公共资源交易电子服务系统，开放对接各类主体依法建设的公共资源电子交易系统和政府有关部门的电子监管系统。"},{"i":10,"n":"第十条","txt":"公共资源交易项目的实施主体根据交易标的专业特性，选择使用依法建设和运行的电子交易系统。"},{"i":11,"n":"第十一条","txt":"公共资源交易项目依法需要评标、评审的，应当按照全国统一的专家专业分类标准，从依法建立的综合评标、政府采购评审等专家库中随机抽取专家，法律法规另有规定的除外。 有关行政监督管理部门按照规定的职责分工，对专家实施监督管理。 鼓励有条件的地方跨区域选择使用专家资源。"},{"i":12,"n":"第十二条","txt":"公共资源交易平台应当按照省级人民政府规定的场所设施标准，充分利用已有的各类场所资源，为公共资源交易活动提供必要的现场服务设施。 市场主体依法建设的交易场所符合省级人民政府规定标准的，可以在现有场所办理业务。"},{"i":13,"n":"第十三条","txt":"公共资源交易平台应当建立健全网络信息安全制度，落实安全保护技术措施，保障平台平稳运行。"},{"i":14,"n":"第十四条","txt":"公共资源交易平台的服务内容、服务流程、工作规范、收费标准和监督渠道应当按照法定要求确定，并通过公共资源交易电子服务系统向社会公布。"},{"i":15,"n":"第十五条","txt":"公共资源交易平台应当推行网上预约和服务事项办理。确需在现场办理的，实行窗口集中，简化流程，限时办结。"},{"i":16,"n":"第十六条","txt":"公共资源交易平台应当将公共资源交易公告、资格审查结果、交易过程信息、成交信息、履约信息等，通过公共资源交易电子服务系统依法及时向社会公开。涉及国家秘密、商业秘密、个人隐私以及其他依法应当保密的信息除外。 公共资源交易平台应当无偿提供依法必须公开的信息。"},{"i":17,"n":"第十七条","txt":"交易服务过程中产生的电子文档、纸质资料以及音视频等，应当按照规定的期限归档保存。"},{"i":18,"n":"第十八条","txt":"公共资源交易平台运行服务机构及其工作人员不得从事以下活动： （一）行使任何审批、备案、监管、处罚等行政监督管理职能； （二）违法从事或强制指定招标、拍卖、政府采购代理、工程造价等中介服务； （三）强制非公共资源交易项目进入平台交易； （四）干涉市场主体选择依法建设和运行的公共资源电子交易系统； （五）非法扣押企业和人员的相关证照资料； （六）通过设置注册登记、设立分支机构、资质验证、投标（竞买）许可、强制担保等限制性条件阻碍或者排斥其他地区市场主体进入本地区公共资源交易市场； （七）违法要求企业法定代表人到场办理相关手续； （八）其他违反法律法规规定的情形。"},{"i":19,"n":"第十九条","txt":"公共资源交易平台运行服务机构提供公共服务确需收费的，不得以营利为目的。根据平台运行服务机构的性质，其收费分别纳入行政事业性收费和经营服务性收费管理，具体收费项目和收费标准按照有关规定执行。属于行政事业性收费的，按照本级政府非税收入管理的有关规定执行。"},{"i":20,"n":"第二十条","txt":"公共资源交易平台运行服务机构发现公共资源交易活动中有违法违规行为的，应当保留相关证据并及时向有关行政监督管理部门报告。"},{"i":21,"n":"第二十一条","txt":"各级行政监督管理部门应当将公共资源交易活动当事人资质资格、信用奖惩、项目审批和违法违规处罚等信息，自作出行政决定之日起7个工作日内上网公开，并通过相关电子监管系统交换至公共资源交易电子服务系统。"},{"i":22,"n":"第二十二条","txt":"各级公共资源交易平台应当依托统一的社会信用代码，记录公共资源交易过程中产生的市场主体和专家信用信息，并通过国家公共资源交易电子服务系统实现信用信息交换共享和动态更新。"},{"i":23,"n":"第二十三条","txt":"国务院发展改革部门牵头建立国家公共资源交易电子服务系统，与省级公共资源交易电子服务系统和有关部门建立的电子系统互联互通，实现市场主体信息、交易信息、行政监管信息的集中交换和同步共享。"},{"i":24,"n":"第二十四条","txt":"省级人民政府应当搭建全行政区域统一、终端覆盖市县的公共资源交易电子服务系统，对接国家公共资源交易电子服务系统和有关部门建立的电子系统，按照有关规定交换共享信息。有关电子招标投标、政府采购等系统应当分别与国家电子招标投标公共服务系统、政府采购管理交易系统对接和交换信息。"},{"i":25,"n":"第二十五条","txt":"公共资源交易电子服务系统应当分别与投资项目在线审批监管系统、信用信息共享系统对接，交换共享公共资源交易相关信息、项目审批核准信息和信用信息。"},{"i":26,"n":"第二十六条","txt":"市场主体已经在公共资源电子交易系统登记注册，并通过公共资源交易电子服务系统实现信息共享的，有关行政监督管理部门和公共资源交易平台运行服务机构不得强制要求其重复登记、备案和验证。"},{"i":27,"n":"第二十七条","txt":"公共资源交易电子服务系统应当支持不同电子认证数字证书的兼容互认。"},{"i":28,"n":"第二十八条","txt":"公共资源交易平台和有关行政监督管理部门在公共资源交易数据采集、汇总、传输、存储、公开、使用过程中，应加强数据安全管理。涉密数据的管理，按照有关法律规定执行。"},{"i":29,"n":"第二十九条","txt":"各级行政监督管理部门按照规定的职责分工，加强对公共资源交易活动的事中事后监管，依法查处违法违规行为。 对利用职权违规干预和插手公共资源交易活动的国家机关或国有企事业单位工作人员，依纪依法予以处理。 各级审计部门应当对公共资源交易平台运行依法开展审计监督。"},{"i":30,"n":"第三十条","txt":"设区的市级以上地方人民政府应当推动建立公共资源交易电子监管系统，实现对项目登记，公告发布，开标评标或评审、竞价，成交公示，交易结果确认，投诉举报，交易履约等交易全过程监控。 公共资源交易电子服务系统和其对接的公共资源电子交易系统应当实时向监管系统推送数据。"},{"i":31,"n":"第三十一条","txt":"建立市场主体公共资源交易活动事前信用承诺制度，要求市场主体以规范格式向社会作出公开承诺，并纳入交易主体信用记录，接受社会监督。"},{"i":32,"n":"第三十二条","txt":"各级行政监督管理部门应当将公共资源交易主体信用信息作为市场准入、项目审批、资质资格审核的重要依据。 建立行政监督管理部门、司法机关等部门联合惩戒机制，对在公共资源交易活动中有不良行为记录的市场主体，依法限制或禁止其参加招标投标、国有土地使用权出让和矿业权出让、国有产权交易、政府采购等公共资源交易活动。建立公共资源交易相关信息与同级税务机关共享机制，推进税收协作。"},{"i":33,"n":"第三十三条","txt":"各级行政监督管理部门应当运用大数据技术，建立公共资源交易数据关联比对分析机制，开展监测预警，定期进行效果评估，及时调整监管重点。"},{"i":34,"n":"第三十四条","txt":"各级行政监督管理部门应当建立联合抽查机制，对有效投诉举报多或有违法违规记录情况的市场主体，加大随机抽查力度。 行政监督管理部门履行监督管理职责过程中，有权查阅、复制公共资源交易活动有关文件、资料和数据。公共资源交易平台运行服务机构应当如实提供相关情况。"},{"i":35,"n":"第三十五条","txt":"建立由市场主体以及第三方参与的社会评价机制，对所辖行政区域公共资源交易平台运行服务机构提供公共服务情况进行评价。"},{"i":36,"n":"第三十六条","txt":"市场主体或社会公众认为公共资源交易 平台运行服务机构及其工作人员存在违法违规行为的，可以依法向政府有关部门投诉、举报。"},{"i":37,"n":"第三十七条","txt":"公共资源交易领域的行业协会应当发挥行业组织作用，加强自律管理和服务。"},{"i":38,"n":"第三十八条","txt":"公共资源交易平台运行服务机构未公开服务内容、服务流程、工作规范、收费标准和监督渠道，由政府有关部门责令限期改正。拒不改正的，予以通报批评。"},{"i":39,"n":"第三十九条","txt":"公共资源交易平台运行服务机构及其工作人员违反本办法第十八条禁止性规定的，由政府有关部门责令限期改正，并予以通报批评。情节严重的，依法追究直接责任人和有关领导的责任。构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"公共资源交易平台运行服务机构违反本办法第十九条规定收取费用的，由同级价格主管部门会同有关部门责令限期改正。拒不改正的，依照《中华人民共和国价格法》、《价格违法行为行政处罚规定》等给予处罚，并予以公示。"},{"i":41,"n":"第四十一条","txt":"公共资源交易平台运行服务机构未按照本办法规定在公共资源交易电子服务系统公开、交换、共享信息的，由政府有关部门责令限期改正。拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分，并予以通报。"},{"i":42,"n":"第四十二条","txt":"公共资源交易平台运行服务机构限制市场主体建设的公共资源电子交易系统对接公共资源交易电子服务系统的，由政府有关部门责令限期改正。拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分，并予以通报。"},{"i":43,"n":"第四十三条","txt":"公共资源交易平台运行服务机构及其工作人员向他人透露依法应当保密的公共资源交易信息的，由政府有关部门责令限期改正，并予以通报批评。情节严重的，依法追究直接责任人和有关领导的责任。构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"有关行政监督管理部门、公共资源交易平台运行服务机构及其工作人员徇私舞弊、滥用职权、弄虚作假、玩忽职守，未依法履行职责的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"公共资源电子交易系统是根据工程建设项目招标投标、土地使用权和矿业权出让、国有产权交易、政府采购等各类交易特点，按照有关规定建设、对接和运行，以数据电文形式完成公共资源交易活动的信息系统。 公共资源交易电子监管系统是指政府有关部门在线监督公共资源交易活动的信息系统。 公共资源交易电子服务系统是指联通公共资源电子交易系统、监管系统和其他电子系统，实现公共资源交易信息数据交换共享，并提供公共服务的枢纽。"},{"i":46,"n":"第四十六条","txt":"公共资源交易平台运行服务机构是指由政府推动设立或政府通过购买服务等方式确定的，通过资源整合共享方式，为公共资源交易相关市场主体、社会公众、行政监督管理部门等提供公共服务的单位。"},{"i":47,"n":"第四十七条","txt":"本办法由国务院发展改革部门会同国务院有关部门负责解释。"},{"i":48,"n":"第四十八条","txt":"本办法自2016年8月1日起实施。"}],"guanyuzhizhidijiaqingxiaoxingweideguiding-2":[{"i":1,"n":"第一条","txt":"为制止低价倾销行为，支持和促进公开、公平、合法的市场价格竞争，维护国家利益，保护消费者和经营者的合法权益，根据《中华人民共和国价格法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称低价倾销行为是指经营者在依法降价处理商品之外，为排挤竞争对手或独占市场，以低于成本的价格倾销商品，扰乱正常生产经营秩序，损害国家利益或者其他经营者合法权益的行为。"},{"i":3,"n":"第三条","txt":"本规定适用于实行市场调节价的商品。"},{"i":4,"n":"第四条","txt":"本规定第二条所称成本是指生产成本、经营成本。 生产成本包括制造成本和由管理费用、财务费用、销售费用构成的期间费用。 经营成本包括购进商品进货成本和由经营费用、管理费用、财务费用构成的流通费用。"},{"i":5,"n":"第五条","txt":"本规定所称低于成本，是指经营者低于其所经营商品的合理的个别成本。 在个别成本无法确认时，由政府价格主管部门按该商品行业平均成本及其下浮幅度认定。"},{"i":6,"n":"第六条","txt":"本规定第二条所称依法降价处理的商品是指： (一)积压商品; (二)过季或者临近换季的商品; (三)临近保质期限、有效期限的商品; (四)临近保质期限的鲜活商品; (五)因依法清偿债务、破产、转产、歇业等原因需要以低于成本的价格销售的商品。"},{"i":7,"n":"第七条","txt":"本规定第二条所称以低于成本的价格倾销商品的行为是指： (一)生产企业销售商品的出厂价格低于其生产成本的，或经销企业的销售价格低于其进货成本的; (二)采用高规格、高等级充抵低规格、低等级等手段，变相降低价格，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的; (三)通过采取折扣、补贴等价格优惠手段，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的; (四)进行非对等物资串换，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的; (五)通过以物抵债，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的; (六)采取多发货少开票或不开票方法，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的; (七)通过多给数量、批量优惠等方式，变相降低价格，使生产企业实际出厂价格低于"},{"i":8,"n":"第八条","txt":"经营者应当依据生产经营成本和市场供求状况合理定价，并通过改进生产经营管理，降低生产经营成本，在市场竞争中获取合法利润。"},{"i":9,"n":"第九条","txt":"经营者应当根据自身的经营条件建立、健全内部价格管理制度，建立并保留价格变动台帐。严格按照国家财经法规进行成本核算、费用分摊，准确记录与核定商品和服务成本，不得弄虚作假。"},{"i":10,"n":"第十条","txt":"在个别成本无法确认时，行业组织应当协助政府价格主管部门测定行业平均成本及合理的下浮幅度，制止低价倾销行为。"},{"i":11,"n":"第十一条","txt":"违反《价格法》和本规定，属于跨省区的低价倾销行为，由国务院价格主管部门认定;属于省及省以下区域性的低价倾销行为，由省、自治区、直辖市人民政府价格主管部门认定。"},{"i":12,"n":"第十二条","txt":"经营者以低于成本的价格销售本规定第六条所列商品时，除正常标注应当标明的商品价格内容外，还应当清晰、准确地标明原价、降低后的价格或者折扣、赠送的商品或者服务内容。"},{"i":13,"n":"第十三条","txt":"为认定低价倾销行为，必要时，政府价格主管部门可以会同行业主管部门或者委托有资质的中介事务机构对个别成本予以认定。"},{"i":14,"n":"第十四条","txt":"行业组织受政府价格主管部门和行业主管部门的委托，对个别成本无法确认的商品进行行业平均成本测定及其信息发布。商品的行业平均成本及其下浮幅度由政府价格主管部门会同行业主管部门确定和公布。消费者和经营者在举报低价倾销行为时，可将其作为主要依据。政府价格主管部门在调查认定低价倾销行为时，可将其作为参考依据。"},{"i":15,"n":"第十五条","txt":"任何单位和个人均有权向政府价格主管部门举报低价倾销行为。政府价格主管部门应当对举报人员给予鼓励，并负责为举报者保密。 省级以下政府价格主管部门受理举报，或者认为存在以及可能存在低价倾销行为时，应当及时报请省级政府价格主管部门认定。 对于省及省以下区域性的低价倾销行为，省级政府价格主管部门可以根据需要委托当地政府价格主管部门进行调查。 对跨省区的低价倾销行为，国务院价格主管部门可以根据需要委托省级政府价格主管部门进行调查。"},{"i":16,"n":"第十六条","txt":"政府价格主管部门开展低价倾销调查时，应当听取行业组织、相关经营者、消费者和消费者协会的意见。"},{"i":17,"n":"第十七条","txt":"政府价格主管部门开展低价倾销调查时，经营者应当如实提供调查所必需的账簿、单据、凭证、文件以及其它资料。"},{"i":18,"n":"第十八条","txt":"省级以上人民政府价格主管部门依法对低价倾销行为实施行政处罚。 政府价格主管部门对低价倾销行为作出行政处罚决定之前，应当告知当事人有要求举行听证的权利;当事人要求听证的，政府价格主管部门应当组织听证。听证程序依照《中华人民共和国行政处罚法》第四十二条执行。 违反本规定第十二条的，按《中华人民共和国价格法》第四十二条规定处罚。 违反本规定第十七条，不如实提供调查所必需的账簿、单据、凭证、文件以及其它资料的，按《中华人民共和国价格法》第四十四条的规定处罚。"},{"i":19,"n":"第十九条","txt":"本规定由国家发展计划委员会负责解释并组织实施。省、自治区、直辖市人民政府可根据本地情况制定本规定实施细则。"},{"i":20,"n":"第二十条","txt":"本规定自发布之日起施行。"}],"guanyuzhizhidijiaqingxiaoxingweideguiding":[{"i":1,"n":"第一条","txt":"为制止低价倾销行为，支持和促进公开、公平、合法的市场价格竞争，维护国家利益，保护消费者和经营者的合法权益，根据《中华人民共和国价格法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称低价倾销行为是指经营者在依法降价处理商品之外，为排挤竞争对手或独占市场，以低于成本的价格倾销商品，扰乱正常生产经营秩序，损害国家利益或者其他经营者合法权益的行为。"},{"i":3,"n":"第三条","txt":"本规定适用于实行市场调节价的商品。"},{"i":4,"n":"第四条","txt":"本规定第二条所称成本是指生产成本、经营成本。 生产成本包括制造成本和由管理费用、财务费用、销售费用构成的期间费用。 经营成本包括购进商品进货成本和由经营费用、管理费用、财务费用构成的流通费用。"},{"i":5,"n":"第五条","txt":"本规定所称低于成本，是指经营者低于其所经营商品的合理的个别成本。 在个别成本无法确认时，由政府价格主管部门按该商品行业平均成本及其下浮幅度认定。"},{"i":6,"n":"第六条","txt":"本规定第二条所称依法降价处理的商品是指： （一）积压商品； （二）过季或者临近换季的商品； （三）临近保质期限、有效期限的商品； （四）临近保质期限的鲜活商品； （五）因依法清偿债务、破产、转产、歇业等原因需要以低于成本的价格销售的商品。"},{"i":7,"n":"第七条","txt":"本规定第二条所称以低于成本的价格倾销商品的行为是指： （一）生产企业销售商品的出厂价格低于其生产成本的，或经销企业的销售价格低于其进货成本的； （二）采用高规格、高等级充抵低规格、低等级等手段，变相降低价格，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的； （三）通过采取折扣、补贴等价格优惠手段，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的； （四）进行非对等物资串换，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的； （五）通过以物抵债，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的； （六）采取多发货少开票或不开票方法，使生产企业实际出厂价格低于其生产成本，经销企业实际销售价格低于其进货成本的； （七）通过多给数量、批量优惠等方式，变相降低价格，使生产企业实际出厂价格低于"},{"i":8,"n":"第八条","txt":"经营者应当依据生产经营成本和市场供求状况合理定价，并通过改进生产经营管理，降低生产经营成本，在市场竞争中获取合法利润。"},{"i":9,"n":"第九条","txt":"经营者应当根据自身的经营条件建立、健全内部价格管理制度，建立并保留价格变动台帐。严格按照国家财经法规进行成本核算、费用分摊，准确记录与核定商品和服务成本，不得弄虚作假。"},{"i":10,"n":"第十条","txt":"在个别成本无法确认时，行业组织应当协助政府价格主管部门测定行业平均成本及合理的下浮幅度，制止低价倾销行为。"},{"i":11,"n":"第十一条","txt":"违反《价格法》和本规定，属于跨省区的低价倾销行为，由国务院价格主管部门认定；属于省及省以下区域性的低价倾销行为，由省、自治区、直辖市人民政府价格主管部门认定。"},{"i":12,"n":"第十二条","txt":"经营者以低于成本的价格销售本规定第六条所列商品时，除正常标注应当标明的商品价格内容外，还应当清晰、准确地标明原价、降低后的价格或者折扣、赠送的商品或者服务内容。"},{"i":13,"n":"第十三条","txt":"为认定低价倾销行为，必要时，政府价格主管部门可以会同行业主管部门或者委托有资质的中介事务机构对个别成本予以认定。"},{"i":14,"n":"第十四条","txt":"行业组织受政府价格主管部门和行业主管部门的委托，对个别成本无法确认的商品进行行业平均成本测定及其信息发布。商品的行业平均成本及其下浮幅度由政府价格主管部门会同行业主管部门确定和公布。消费者和经营者在举报低价倾销行为时，可将其作为主要依据。政府价格主管部门在调查认定低价倾销行为时，可将其作为参考依据。"},{"i":15,"n":"第十五条","txt":"任何单位和个人均有权向政府价格主管部门举报低价倾销行为。政府价格主管部门应当对举报人员给予鼓励，并负责为举报者保密。 省级以下政府价格主管部门受理举报，或者认为存在以及可能存在低价倾销行为时，应当及时报请省级政府价格主管部门认定。 对于省及省以下区域性的低价倾销行为，省级政府价格主管部门可以根据需要委托当地政府价格主管部门进行调查。 对跨省区的低价倾销行为，国务院价格主管部门可以根据需要委托省级政府价格主管部门进行调查。"},{"i":16,"n":"第十六条","txt":"政府价格主管部门开展低价倾销调查时，应当听取行业组织、相关经营者、消费者和消费者协会的意见。"},{"i":17,"n":"第十七条","txt":"政府价格主管部门开展低价倾销调查时，经营者应当如实提供调查所必需的账簿、单据、凭证、文件以及其它资料。"},{"i":18,"n":"第十八条","txt":"省级以上人民政府价格主管部门依法对低价倾销行为实施行政处罚。 政府价格主管部门对低价倾销行为作出行政处罚决定之前，应当告知当事人有要求举行听证的权利；当事人要求听证的，政府价格主管部门应当组织听证。听证程序依照《中华人民共和国行政处罚法》第四十二条执行。 违反本规定第十二条的，按《中华人民共和国价格法》第四十二条规定处罚。 违反本规定第十七条，不如实提供调查所必需的账簿、单据、凭证、文件以及其它资料的，按《中华人民共和国价格法》第四十四条的规定处罚。"},{"i":19,"n":"第十九条","txt":"本规定由国家发展计划委员会负责解释并组织实施。省、自治区、直辖市人民政府可根据本地情况制定本规定实施细则。"},{"i":20,"n":"第二十条","txt":"本规定自发布之日起施行。"}],"chuangyetouziqiyeguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为促进创业投资企业发展，规范其投资运作，鼓励其投资中小企业特别是中小高新技术企业，依据《中华人民共和国公司法》、《中华人民共和国中小企业促进法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称创业投资企业，系指在中华人民共和国境内注册设立的主要从事创业投资的企业组织。 前款所称创业投资，系指向创业企业进行股权投资，以期所投资创业企业发育成熟或相对成熟后主要通过股权转让获得资本增值收益的投资方式。 前款所称创业企业，系指在中华人民共和国境内注册设立的处于创建或重建过程中的成长性企业，但不含已经在公开市场上市的企业。"},{"i":3,"n":"第三条","txt":"国家对创业投资企业实行备案管理。凡遵照本办法规定完成备案程序的创业投资企业，应当接受创业投资企业管理部门的监管，投资运作符合有关规定的可享受政策扶持。未遵照本办法规定完成备案程序的创业投资企业，不受创业投资企业管理部门的监管，不享受政策扶持。"},{"i":4,"n":"第四条","txt":"创业投资企业的备案管理部门分国务院管理部门和省级(含副省级城市)管理部门两级。国务院管理部门为国家发展和改革委员会;省级(含副省级城市)管理部门由同级人民政府确定，报国务院管理部门备案后履行相应的备案管理职责，并在创业投资企业备案管理业务上接受国务院管理部门的指导。"},{"i":5,"n":"第五条","txt":"外商投资创业投资企业适用《外商投资创业投资企业管理规定》。依法设立的外商投资创业投资企业，投资运作符合相关条件，可以享受本办法给予创业投资企业的相关政策扶持。"},{"i":6,"n":"第六条","txt":"创业投资企业可以以有限责任公司、股份有限公司或法律规定的其他企业组织形式设立。 以公司形式设立的创业投资企业，可以委托其他创业投资企业、创业投资管理顾问企业作为管理顾问机构，负责其投资管理业务。委托人和代理人的法律关系适用《中华人民共和国民法通则》、《中华人民共和国合同法》等有关法律法规。"},{"i":7,"n":"第七条","txt":"申请设立创业投资企业和创业投资管理顾问企业，依法直接到工商行政管理部门注册登记。"},{"i":8,"n":"第八条","txt":"在国家工商行政管理部门注册登记的创业投资企业，向国务院管理部门申请备案。 在省级及省级以下工商行政管理部门注册登记的创业投资企业，向所在地省级(含副省级城市)管理部门申请备案。"},{"i":9,"n":"第九条","txt":"创业投资企业向管理部门备案应当具备下列条件： (一)已在工商行政管理部门办理注册登记。 (二)经营范围符合本办法第十二条规定。 (三)实收资本不低于3000万元人民币，或者首期实收资本不低于1000万元人民币且全体投资者承诺在注册后的5年内补足不低于3000万元人民币实收资本。 (四)投资者不得超过200人。其中，以有限责任公司形式设立创业投资企业的，投资者人数不得超过50人。单个投资者对创业投资企业的投资不得低于100万元人民币。所有投资者应当以货币形式出资。 (五)有至少3名具备2年以上创业投资或相关业务经验的高级管理人员承担投资管理责任。委托其他创业投资企业、创业投资管理顾问企业作为管理顾问机构负责其投资管理业务的，管理顾问机构必须有至少3名具备2年以上创业投资或相关业务经验的高级管理人员对其承担投资管理责任。 前款所称“高级管理人员”，系指担任副经理及以上职务或相当职务的管理人"},{"i":10,"n":"第十条","txt":"创业投资企业向管理部门备案时，应当提交下列文件： (一)公司章程等规范创业投资企业组织程序和行为的法律文件。 (二)工商登记文件与营业执照的复印件。 (三)投资者名单、承诺出资额和已缴出资额的证明。 (四)高级管理人员名单、简历。 由管理顾问机构受托其投资管理业务的，还应提交下列文件： (一)管理顾问机构的公司章程等规范其组织程序和行为的法律文件。 (二)管理顾问机构的工商登记文件与营业执照的复印件。 (三)管理顾问机构的高级管理人员名单、简历。 (四)委托管理协议。"},{"i":11,"n":"第十一条","txt":"管理部门在收到创业投资企业的备案申请后，应当在5个工作日内，审查备案申请文件是否齐全，并决定是否受理其备案申请。在受理创业投资企业的备案申请后，应当在20个工作日内，审查申请人是否符合备案条件，并向其发出“已予备案”或“不予备案”的书面通知。对“不予备案”的，应当在书面通知中说明理由。"},{"i":12,"n":"第十二条","txt":"创业投资企业的经营范围限于： (一)创业投资业务。 (二)代理其他创业投资企业等机构或个人的创业投资业务。 (三)创业投资咨询业务。 (四)为创业企业提供创业管理服务业务。 (五)参与设立创业投资企业与创业投资管理顾问机构。"},{"i":13,"n":"第十三条","txt":"创业投资企业不得从事担保业务和房地产业务，但是购买自用房地产除外。"},{"i":14,"n":"第十四条","txt":"创业投资企业可以以全额资产对外投资。其中，对企业的投资，仅限于未上市企业。但是所投资的未上市企业上市后，创业投资企业所持股份的未转让部分及其配售部分不在此限。其他资金只能存放银行、购买国债或其他固定收益类的证券。"},{"i":15,"n":"第十五条","txt":"经与被投资企业签订投资协议，创业投资企业可以以股权和优先股、可转换优先股等准股权方式对未上市企业进行投资。"},{"i":16,"n":"第十六条","txt":"创业投资企业对单个企业的投资不得超过创业投资企业总资产的20%。"},{"i":17,"n":"第十七条","txt":"创业投资企业应当在章程、委托管理协议等法律文件中，明确管理运营费用或管理顾问机构的管理顾问费用的计提方式，建立管理成本约束机制。"},{"i":18,"n":"第十八条","txt":"创业投资企业可以从已实现投资收益中提取一定比例作为对管理人员或管理顾问机构的业绩报酬，建立业绩激励机制。"},{"i":19,"n":"第十九条","txt":"创业投资企业可以事先确定有限的存续期限，但是最短不得短于7年。"},{"i":20,"n":"第二十条","txt":"创业投资企业可以在法律规定的范围内通过债权融资方式增强投资能力。"},{"i":21,"n":"第二十一条","txt":"创业投资企业应当按照国家有关企业财务会计制度的规定，建立健全内部财务管理制度和会计核算办法。"},{"i":22,"n":"第二十二条","txt":"国家与地方政府可以设立创业投资引导基金，通过参股和提供融资担保等方式扶持创业投资企业的设立与发展。具体管理办法另行制定。"},{"i":23,"n":"第二十三条","txt":"国家运用税收优惠政策扶持创业投资企业发展并引导其增加对中小企业特别是中小高新技术企业的投资。具体办法由国务院财税部门会同有关部门另行制定。"},{"i":24,"n":"第二十四条","txt":"创业投资企业可以通过股权上市转让、股权协议转让、被投资企业回购等途径，实现投资退出。国家有关部门应当积极推进多层次资本市场体系建设，完善创业投资企业的投资退出机制。"},{"i":25,"n":"第二十五条","txt":"管理部门已予备案的创业投资企业及其管理顾问机构，应当遵循本办法第二、第三章各条款的规定进行投资运作，并接受管理部门的监管。"},{"i":26,"n":"第二十六条","txt":"管理部门已予备案的创业投资企业及其管理顾问机构，应当在每个会计年度结束后的4个月内向管理部门提交经注册会计师审计的年度财务报告与业务报告，并及时报告投资运作过程中的重大事件。 前款所称重大事件，系指： (一)修改公司章程等重要法律文件。 (二)增减资本。 (三)分立与合并。 (四)高级管理人员或管理顾问机构变更。 (五)清算与结业。"},{"i":27,"n":"第二十七条","txt":"管理部门应当在每个会计年度结束后的5个月内，对创业投资企业及其管理顾问机构是否遵守第二、第三章各条款规定，进行年度检查。在必要时，可在第二、第三章相关条款规定的范围内，对其投资运作进行不定期检查。 对未遵守第二、三章各条款规定进行投资运作的，管理部门应当责令其在30个工作日内改正;未改正的，应当取消备案，并在自取消备案之日起的3年内不予受理其重新备案申请。"},{"i":28,"n":"第二十八条","txt":"省级(含副省级城市)管理部门应当及时向国务院管理部门报告所辖地区创业投资企业的备案情况，并于每个会计年度结束后的6个月内报告已纳入备案管理范围的创业投资企业的投资运作情况。"},{"i":29,"n":"第二十九条","txt":"国务院管理部门应当加强对省级(含副省级城市)管理部门的指导。对未履行管理职责或管理不善的，应当建议其改正;造成不良后果的，应当建议其追究相关管理人员的失职责任。"},{"i":30,"n":"第三十条","txt":"创业投资行业协会依据本办法和相关法律、法规及规章，对创业投资企业进行自律管理，并维护本行业的自身权益。"},{"i":31,"n":"第三十一条","txt":"本办法由国家发展和改革委员会会同有关部门解释。"},{"i":32,"n":"第三十二条","txt":"本办法自2006年3月1日起施行。"}],"kezaishengnengyuanxiaofeizuidibizhongmubiaohekezai2bc72e":[{"i":1,"n":"第一条","txt":"为引导全社会优先使用和主动消费可再生能源，推动可再生能源高质量发展，助力实现碳达峰碳中和，建立可再生能源消费最低比重目标制度，完善可再生能源电力消纳保障机制，根据《中华人民共和国能源法》《中华人民共和国可再生能源法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于能源用户可再生能源消费最低比重目标和省级行政区域可再生能源电力消纳责任权重的制定、监测和考核。"},{"i":3,"n":"第三条","txt":"国务院能源主管部门会同国务院工业和信息化、住房城乡建设、交通运输等有关部门制定可再生能源消费最低比重目标和可再生能源电力消纳责任权重并组织实施。省级能源主管部门在省级党委、政府领导下，会同有关部门组织落实。"},{"i":4,"n":"第四条","txt":"可再生能源消费最低比重是指国家规定能源用户消费的可再生能源在其总能源消费中应达到的最低比重。可再生能源消费最低比重目标分为可再生能源电力消费最低比重目标和非电消费最低比重目标两类，其中电力消费最低比重目标包括全部可再生能源发电种类；非电消费最低比重目标包括可再生能源供热（制冷）、可再生能源制氢氨醇等综合利用、生物燃料等可再生能源非电利用种类。"},{"i":5,"n":"第五条","txt":"国务院能源主管部门会同有关部门确定重点用能行业，对其明确可再生能源电力消费最低比重目标和过渡期限，并进行监测、评价和考核，相关行业范围结合所属领域节能降碳相关要求和工作进展，按年明确。 国务院能源主管部门会同有关部门统筹可再生能源非电利用行业发展和统计核算体系建设情况，适时明确重点用能行业可再生能源非电消费最低比重目标和过渡期限，并进行监测、评价和考核，非电利用种类和相关行业范围结合所属领域节能降碳相关要求和工作进展，按年明确。 国家支持重点用能行业相关企业在明确的可再生能源消费最低比重目标之上，进一步提升可再生能源消费比例；鼓励具备条件的地区对政府部门、事业单位、国有企业提出可再生能源消费最低比重目标。"},{"i":6,"n":"第六条","txt":"国务院能源主管部门按年下达重点用能行业可再生能源电力消费最低比重目标和非电消费最低比重目标。省级能源主管部门在省级党委、政府领导下会同相关行业主管部门组织落实。"},{"i":7,"n":"第七条","txt":"重点用能行业可再生能源电力消费最低比重目标可通过可再生能源电力自发自用、绿电直连、绿证绿电交易（划转）等方式完成；可再生能源非电消费最低比重目标可通过可再生能源供暖（制冷）、可再生能源制氢氨醇等综合利用、生物质能非电利用等方式完成。 重点用能行业应当落实国家相关行业规划和政策要求，坚持因地制宜、规范有序，选择合适方式提升可再生能源消费水平。"},{"i":8,"n":"第八条","txt":"可再生能源电力消费最低比重目标完成情况使用考核年生产电量对应的可再生能源绿色电力证书作为基本凭证进行核算，具体按国家非化石能源电力消费核算有关规定执行。省级能源主管部门会同相关行业主管部门，组织有关机构做好本区域重点用能行业可再生能源非电消费最低比重目标完成情况统计核算，核算方法见附件1。"},{"i":9,"n":"第九条","txt":"国务院能源主管部门负责可再生能源绿色电力证书交易和核销等统计。"},{"i":10,"n":"第十条","txt":"可再生能源电力消纳责任权重是指国家规定各省级行政区域消纳的可再生能源电量占本区域全社会用电量应达到的比重目标，分为可再生能源电力总量消纳责任权重和非水电消纳责任权重两类。总量消纳责任权重包括全部可再生能源发电种类；非水电消纳责任权重包括除水电以外的其他可再生能源发电种类。"},{"i":11,"n":"第十一条","txt":"国务院能源主管部门组织对各省级行政区域可再生能源电力消纳责任权重进行统一测算，建立分区域权重增长机制，强化中长期消纳责任权重引导，与各省份新能源利用率做好衔接，区分不同地区对各省份设置权重增长指标，并按年下达。"},{"i":12,"n":"第十二条","txt":"各省级能源主管部门在省级党委、政府领导下牵头承担消纳落实责任，会同经济运行管理部门、所在地国家能源局派出机构组织制定本省级行政区域可再生能源电力消纳实施方案，保障新能源高质量消纳。省级可再生能源电力消纳实施方案报省级人民政府批准后实施。"},{"i":13,"n":"第十三条","txt":"电网企业应密切配合省级能源主管部门有效落实消纳责任，加大电网投资建设，依据可再生能源电力消纳实施方案，组织经营区内各承担消纳责任的主体完成可再生能源电量消纳。"},{"i":14,"n":"第十四条","txt":"供电企业、售电企业、相关电力用户和使用自备电厂供电的企业等承担可再生能源电力消纳责任，配合做好可再生能源电量消纳，提升可再生能源消纳能力。"},{"i":15,"n":"第十五条","txt":"各电力交易机构负责组织开展可再生能源电力相关交易。北京、广州、内蒙古电力交易中心按职责定期向国务院能源主管部门报送跨省跨区可再生能源电力交易、绿证绿电交易等数据信息；各省级电力交易中心定期向所在地省级能源主管部门和国家能源局派出机构报送省内绿证绿电交易等信息。电力交易机构应及时向承担消纳责任的主体披露可再生能源电力交易及绿证绿电交易等相关信息。"},{"i":16,"n":"第十六条","txt":"各省级行政区域可再生能源电力消纳责任权重完成情况使用实际消纳的可再生能源电量进行核算，核算方法见附件2。 各省级能源主管部门要推动电网企业和承担可再生能源电力消纳责任的主体通过实际消纳电量完成可再生能源电力消纳责任权重，确实无法完成的通过购买考核年生产电量对应的绿证补充完成。"},{"i":17,"n":"第十七条","txt":"电网企业、电力交易机构负责各省级行政区域可再生能源电力消纳量（包括跨省跨区可再生能源交易电量）的统计监测。"},{"i":18,"n":"第十八条","txt":"对于由自然原因（包括可再生能源资源极端异常）或重大事故导致可再生能源发电量显著减少或送出受限，国务院能源主管部门在组织第三方评估后，对有关省级行政区域可再生能源电力消纳责任权重进行考核时相应核减。"},{"i":19,"n":"第十九条","txt":"国务院能源主管部门会同有关部门，委托第三方机构对重点用能行业可再生能源消费最低比重目标和省级行政区域可再生能源电力消纳责任权重的实施情况按季度开展监测，并予以公布。"},{"i":20,"n":"第二十条","txt":"国务院能源主管部门按年度组织开展重点用能行业可再生能源消费最低比重目标和省级行政区域可再生能源电力消纳责任权重完成情况评估，并予以公布。 省级能源主管部门会同相关行业主管部门每年定期向国务院能源主管部门报送上年度本省级行政区域的重点用能行业可再生能源消费最低比重目标和可再生能源电力消纳责任权重完成情况，并抄送所在地国家能源局派出机构。各省不得限制新能源参与跨省区电力市场交易或跨省区绿证交易。"},{"i":21,"n":"第二十一条","txt":"国家能源局派出机构受国务院能源主管部门委托开展相关监管工作，加强可再生能源消费最低比重目标和可再生能源电力消纳责任权重完成情况监管，对监管过程中发现的重大问题及时报告。"},{"i":22,"n":"第二十二条","txt":"未完成可再生能源消费最低比重目标的重点用能行业相关企业，由所在地省级能源主管部门会同相关行业主管部门及国家能源局派出机构，督促其在指标公布三个月内通过绿证交易或其他市场化交易方式补充完成，并及时上报国务院能源主管部门；逾期仍未完成的，由所在地省级能源主管部门会同相关行业主管部门及国家能源局派出机构予以约谈、通报，并依法依规纳入信用记录，加强重点监管。 未完成可再生能源电力消纳责任权重指标的省（自治区、直辖市），可在指标公布三个月内通过绿证交易补充完成，同时进一步提出系统调节能力建设、电网建设、市场价格机制等促进可再生能源消纳的举措，并与新能源可持续发展价格结算机制做好衔接，相关情况及时上报国务院能源主管部门；逾期仍未完成的，视情由国家发展改革委、国家能源局约谈该地区省级能源主管部门并进行通报，同时转移至下一年度，五年规划期最后一年权重指标不可转移。 对于可再生能源消费最低比重目标完成情"},{"i":23,"n":"第二十三条","txt":"可再生能源消费最低比重目标和可再生能源电力消纳责任权重制度完成情况按国家有关规定纳入相关评价考核指标。"},{"i":24,"n":"第二十四条","txt":"本办法由国家发展改革委、工业和信息化部、住房城乡建设部、交通运输部负责解释。"},{"i":25,"n":"第二十五条","txt":"本办法自2026年8月1日起施行。 附件：1.可再生能源非电消费最低比重目标完成情况核算方法       2.可再生能源电力消纳责任权重确定和核算方法 附件1 可再生能源非电消费最低比重目标完成情况核算方法 本方法随《可再生能源消费最低比重目标和可再生能源电力消纳责任权重制度实施办法》发布，作为可再生能源非电消费最低比重目标完成情况核算的基本方法。 一、可再生能源非电消费比重核算方法 重点用能行业相关企业可再生能源非电消费比重完成情况按以下公式核算： 企业可再生能源非电消费比重=（企业生产且消耗的可再生能源非电利用能量+企业购入且消耗的可再生能源非电利用能量）÷企业总非电利用能量 上式中可再生能源非电利用种类包含可再生能源供热（制冷）、可再生能源制氢氨醇等综合利用、生物质能非电利用等。 非电利用中燃料燃烧热量采用燃料低位热值进行统计核算。 二、可再生能源供热（制冷）核算 企业生产且消耗"}],"shangpinmeizhiliangguanlizanxingbanfa-2":[{"i":1,"n":"第一条","txt":"为贯彻落实国务院《大气污染防治行动计划》，强化商品煤全过程质量管理，提高终端用煤质量，推进煤炭高效清洁利用，改善空气质量，根据《中华人民共和国煤炭法》、《中华人民共和国产品质量法》、《中华人民共和国环境保护法》、《中华人民共和国大气污染防治法》、《中华人民共和国对外贸易法》、《中华人民共和国进出口商品检验法》等相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事商品煤的生产、加工、储运、销售、进口、使用等活动，适用本办法。"},{"i":3,"n":"第三条","txt":"商品煤是指作为商品出售的煤炭产品。不包括坑口自用煤以及煤泥、矸石等副产品。企业远距离运输的自用煤，同样适用本办法。"},{"i":4,"n":"第四条","txt":"煤炭管理及有关部门在各自职责范围内负责建立煤炭质量管理制度并组织实施。"},{"i":5,"n":"第五条","txt":"煤炭生产、加工、储运、销售、进口、使用企业是商品煤质量的责任主体，分别对各环节商品煤质量负责。"},{"i":6,"n":"第六条","txt":"商品煤应当满足下列基本要求： （一）灰分（Ad） 褐煤≤30%，其它煤种≤40%。 （二）硫分（St,d） 褐煤≤1.5%，其它煤种≤3%。 （三）其它指标 汞（Hgd）≤0.6µg/g，砷（Asd）≤80µg/g，磷（Pd）≤0.15%，氯（Cld）≤0.3%，氟（Fd）≤200µg/g。"},{"i":7,"n":"第七条","txt":"在中国境内远距离运输（运距超过600公里）的商品煤除在满足第六条要求外，还应当同时满足下列要求： （一）褐煤 发热量（Qnet,ar）≥16.5MJ/kg，灰分（Ad）≤20%，硫分（St,d）≤1%。 （二）其它煤种 发热量（Qnet,ar）≥18MJ/kg，灰分（Ad）≤30%，硫分（St,d）≤2%。 本条中运距是指（国产商品煤）从产地到消费地距离或（境外商品煤）从货物进境口岸到消费地距离。"},{"i":8,"n":"第八条","txt":"对于供应给具备高效脱硫、废弃物处理、硫资源回收等设施的化工、电力及炼焦等用户的商品煤，可适当放宽其商品煤供应和使用的含硫标准，具体办法由国家煤炭管理部门商有关部门制定。"},{"i":9,"n":"第九条","txt":"京津冀及周边地区、长三角、珠三角限制销售和使用灰分（Ad）≥16%、硫分（St,d）≥1%的散煤。"},{"i":10,"n":"第十条","txt":"生产、销售和进口的煤炭应按照《商品煤标识》（GB/T25209-2010）进行标识，标识内容应与实际煤质相符。"},{"i":11,"n":"第十一条","txt":"不符合本办法要求的商品煤，不得进口、销售和远距离运输。煤炭进口检验及其监管，按《进出口商品检验法》等有关法律法规执行。"},{"i":12,"n":"第十二条","txt":"承运企业对不同质量的商品煤应当“分质装车、分质堆存”。在储运过程中，不得降低煤炭的质量。"},{"i":13,"n":"第十三条","txt":"煤炭生产、加工、储运、销售、进口、使用企业均应制定必要的煤炭质量保证制度，建立商品煤质量档案。"},{"i":14,"n":"第十四条","txt":"煤炭管理部门及有关部门在各自职责范围内依法对煤炭质量实施监管。煤炭生产、加工、储运、销售、进口、使用企业应当接受监管。"},{"i":15,"n":"第十五条","txt":"煤炭管理部门及有关部门依法对辖区内的商品煤质量进行抽检，并将抽检结果通报国家发展改革委（国家能源局）等相关部门。"},{"i":16,"n":"第十六条","txt":"煤炭管理部门及有关部门对煤炭生产、加工、储运、销售、使用企业实行分类管理。"},{"i":17,"n":"第十七条","txt":"口岸检验检疫机构对本口岸进口商品煤的质量进行监督管理。每半年进行一次进口商品煤质量分析，上报国家质量监督检验检疫部门，抄送国家发展改革委（国家能源局）、商务部等相关管理部门。"},{"i":18,"n":"第十八条","txt":"任何企业和个人对违反本办法的行为，均可向有关部门举报。有关部门应当及时调查处理，并为举报人保密。"},{"i":19,"n":"第十九条","txt":"商品煤质量达不到本办法要求的，责令限期整改，并予以通报;构成有关法律法规规定的违法行为的，依据有关法律法规予以处罚。"},{"i":20,"n":"第二十条","txt":"采取掺杂使假、以次充好等违法手段进行经营的，依据相关法律法规予以处罚;构成犯罪的，由司法机关依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"对拒绝、阻碍有关部门监督检查、取证的，依法予以处罚;构成犯罪的，由司法机关依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"有关工作人员滥用职权、玩忽职守或者徇私舞弊的，依法予以行政处分;构成犯罪的，由司法机关依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"本办法由国家发展改革委（国家能源局）会同有关部门负责解释。各地区及相关企业可根据本办法制定更严格的标准和实施细则。"},{"i":24,"n":"第二十四条","txt":"本办法自2015年1月1日起施行。"}],"shangpinmeizhiliangguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为贯彻落实国务院《大气污染防治行动计划》，强化商品煤全过程质量管理，提高终端用煤质量，推进煤炭高效清洁利用，改善空气质量，根据《中华人民共和国煤炭法》、《中华人民共和国产品质量法》、《中华人民共和国环境保护法》、《中华人民共和国大气污染防治法》、《中华人民共和国对外贸易法》、《中华人民共和国进出口商品检验法》等相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事商品煤的生产、加工、储运、销售、进口、使用等活动，适用本办法。"},{"i":3,"n":"第三条","txt":"商品煤是指作为商品出售的煤炭产品。不包括坑口自用煤以及煤泥、矸石等副产品。企业远距离运输的自用煤，同样适用本办法。"},{"i":4,"n":"第四条","txt":"煤炭管理及有关部门在各自职责范围内负责建立煤炭质量管理制度并组织实施。"},{"i":5,"n":"第五条","txt":"煤炭生产、加工、储运、销售、进口、使用企业是商品煤质量的责任主体，分别对各环节商品煤质量负责。"},{"i":6,"n":"第六条","txt":"商品煤应当满足下列基本要求： （一）灰分（A） 褐煤≤30%，其它煤种≤40%。 （二）硫分（St,d） 褐煤≤1.5%，其它煤种≤3%。 （三）其它指标 汞（Hgd）≤0.6µg/g，砷（Asd）≤80µg/g，磷（Pd）≤0.15%，氯（Cld）≤0.3%，氟（Fd）≤200µg/g。"},{"i":7,"n":"第七条","txt":"在中国境内远距离运输（运距超过600公里）的商品煤除在满足第六条要求外，还应当同时满足下列要求： （一）褐煤 发热量（Qnet,ar）≥16.5MJ/kg，灰分（Ad）≤20%，硫分（St,d）≤1%。 （二）其它煤种 发热量（Qnet,ar）≥18MJ/kg，灰分（Ad）≤30%，硫分（St,d）≤2%。 本条中运距是指（国产商品煤）从产地到消费地距离或（境外商品煤）从货物进境口岸到消费地距离。"},{"i":8,"n":"第八条","txt":"对于供应给具备高效脱硫、废弃物处理、硫资源回收等设施的化工、电力及炼焦等用户的商品煤，可适当放宽其商品煤供应和使用的含硫标准，具体办法由国家煤炭管理部门商有关部门制定。"},{"i":9,"n":"第九条","txt":"京津冀及周边地区、长三角、珠三角限制销售和使用灰分（Ad）≥16%、硫分（St,d）≥1%的散煤。"},{"i":10,"n":"第十条","txt":"生产、销售和进口的煤炭应按照《商品煤标识》（GB/T25209-2010）进行标识，标识内容应与实际煤质相符。"},{"i":11,"n":"第十一条","txt":"不符合本办法要求的商品煤，不得进口、销售和远距离运输。煤炭进口检验及其监管，按《进出口商品检验法》等有关法律法规执行。"},{"i":12,"n":"第十二条","txt":"承运企业对不同质量的商品煤应当“分质装车、分质堆存”。在储运过程中，不得降低煤炭的质量。"},{"i":13,"n":"第十三条","txt":"煤炭生产、加工、储运、销售、进口、使用企业均应制定必要的煤炭质量保证制度，建立商品煤质量档案。"},{"i":14,"n":"第十四条","txt":"煤炭管理部门及有关部门在各自职责范围内依法对煤炭质量实施监管。煤炭生产、加工、储运、销售、进口、使用企业应当接受监管。"},{"i":15,"n":"第十五条","txt":"煤炭管理部门及有关部门依法对辖区内的商品煤质量进行抽检，并将抽检结果通报国家发展改革委（国家能源局）等相关部门。"},{"i":16,"n":"第十六条","txt":"煤炭管理部门及有关部门对煤炭生产、加工、储运、销售、使用企业实行分类管理。"},{"i":17,"n":"第十七条","txt":"口岸检验检疫机构对本口岸进口商品煤的质量进行监督管理。每半年进行一次进口商品煤质量分析，上报国家质量监督检验检疫部门，抄送国家发展改革委（国家能源局）、商务部等相关管理部门。"},{"i":18,"n":"第十八条","txt":"任何企业和个人对违反本办法的行为，均可向有关部门举报。有关部门应当及时调查处理，并为举报人保密。"},{"i":19,"n":"第十九条","txt":"商品煤质量达不到本办法要求的，责令限期整改，并予以通报；构成有关法律法规规定的违法行为的，依据有关法律法规予以处罚。"},{"i":20,"n":"第二十条","txt":"采取掺杂使假、以次充好等违法手段进行经营的，依据相关法律法规予以处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"对拒绝、阻碍有关部门监督检查、取证的，依法予以处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"有关工作人员滥用职权、玩忽职守或者徇私舞弊的，依法予以行政处分；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"本办法由国家发展改革委（国家能源局）会同有关部门负责解释。各地区及相关企业可根据本办法制定更严格的标准和实施细则。"},{"i":24,"n":"第二十四条","txt":"本办法自2015年1月1日起施行。"}],"gudingzichantouzixiangmujienengshenchabanfa-2":[{"i":1,"n":"第一条","txt":"为促进固定资产投资项目科学合理利用能源,从源头上杜绝能源浪费，提高能源利用效率，加强能源消费总量管理，根据《中华人民共和国节约能源法》、《中华人民共和国行政许可法》、《公共机构节能条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于各级人民政府投资主管部门管理的在我国境内建设的固定资产投资项目。本办法所称节能审查，是指根据节能法律法规、政策标准等，对项目节能情况进行审查并形成审查意见的行为。"},{"i":3,"n":"第三条","txt":"固定资产投资项目节能审查意见是项目开工建设、竣工验收和运营管理的重要依据。政府投资项目，建设单位在报送项目可行性研究报告前，需取得节能审查机关出具的节能审查意见。企业投资项目，建设单位需在开工建设前取得节能审查机关出具的节能审查意见。未按本办法规定进行节能审查，或节能审查未通过的项目，建设单位不得开工建设，已经建成的不得投入生产、使用。"},{"i":4,"n":"第四条","txt":"国家发展改革委负责制定节能审查的相关管理办法，组织编制技术标准、规范和指南，开展业务培训，依据各地能源消耗总量和强度目标完成情况，对各地新上重大高耗能项目的节能审查工作进行督导。"},{"i":5,"n":"第五条","txt":"固定资产投资项目节能审查由地方节能审查机关负责。 国家发展改革委核报国务院审批以及国家发展改革委审批的政府投资项目，建设单位在报送项目可行性研究报告前，需取得省级节能审查机关出具的节能审查意见。国家发展改革委核报国务院核准以及国家发展改革委核准的企业投资项目，建设单位需在开工建设前取得省级节能审查机关出具的节能审查意见。 年综合能源消费量5000吨标准煤以上(改扩建项目按照建成投产后年综合能源消费增量计算，电力折算系数按当量值，下同)的固定资产投资项目，其节能审查由省级节能审查机关负责。其他固定资产投资项目，其节能审查管理权限由省级节能审查机关依据实际情况自行决定。"},{"i":6,"n":"第六条","txt":"年综合能源消费量不满1000吨标准煤，且年电力消费量不满500万千瓦时的固定资产投资项目，以及用能工艺简单、节能潜力小的行业(具体行业目录由国家发展改革委制定并公布)的固定资产投资项目应按照相关节能标准、规范建设，不再单独进行节能审查。"},{"i":7,"n":"第七条","txt":"建设单位应编制固定资产投资项目节能报告。项目节能报告应包括下列内容：分析评价依据;项目建设方案的节能分析和比选，包括总平面布置、生产工艺、用能工艺、用能设备和能源计量器具等方面;选取节能效果好、技术经济可行的节能技术和管理措施;项目能源消费量、能源消费结构、能源效率等方面的分析;对所在地完成能源消耗总量和强度目标、煤炭消费减量替代目标的影响等方面的分析评价。"},{"i":8,"n":"第八条","txt":"节能审查机关受理节能报告后，应委托有关机构进行评审，形成评审意见，作为节能审查的重要依据。节能审查应依据项目是否符合节能有关法律法规、标准规范、政策;项目用能分析是否客观准确，方法是否科学，结论是否准确;节能措施是否合理可行;项目的能源消费量和能效水平是否满足本地区能源消耗总量和强度“双控”管理要求等对项目节能报告进行审查。"},{"i":9,"n":"第九条","txt":"节能审查机关应在法律规定的时限内出具节能审查意见。节能审查意见自印发之日起2年内有效。 通过节能审查的固定资产投资项目，建设内容、能效水平等发生重大变动的，建设单位应向节能审查机关提出变更申请。"},{"i":10,"n":"第十条","txt":"固定资产投资项目投入生产、使用前，应对其节能审查意见落实情况进行验收。"},{"i":11,"n":"第十一条","txt":"固定资产投资项目节能审查应纳入投资项目在线审批监管平台统一管理，实行网上受理、办理、监管和服务，实现审查过程和结果的可查询、可监督。"},{"i":12,"n":"第十二条","txt":"节能审查机关应加强节能审查信息的统计分析，强化事中事后监管，对节能审查意见落实情况进行监督检查。省级节能审查机关应按季度向国家发展改革委报送本地区节能审查实施情况。 国家发展改革委实施全国节能审查信息动态监管，对各地节能审查实施情况进行定期巡查，对重大项目节能审查意见落实情况进行不定期抽查，对违法违规问题进行公开，并依法给予行政处罚。"},{"i":13,"n":"第十三条","txt":"对未按本办法规定进行节能审查，或节能审查未获通过，擅自开工建设或擅自投入生产、使用的固定资产投资项目，由节能审查机关责令停止建设或停止生产、使用，限期改造;不能改造或逾期不改造的生产性项目，由节能审查机关报请本级人民政府按照国务院规定的权限责令关闭;并依法追究有关责任人的责任。 以拆分项目、提供虚假材料等不正当手段通过节能审查的固定资产投资项目，由节能审查机关撤销项目的节能审查意见。 未落实节能审查意见要求的固定资产投资项目，节能审查机关责令建设单位限期整改。不能改正或逾期不改正的，节能审查机关按照法律法规的有关规定进行处罚。 负责审批政府投资项目的工作人员，对未进行节能审查或节能审查未获通过的项目，违反本办法规定予以批准的，依法给予处分。"},{"i":14,"n":"第十四条","txt":"节能审查机关对建设单位、中介机构等的违法违规信息进行记录，将违法违规信息纳入全国信用信息共享平台和投资项目审批监管平台，在“信用中国”网站向社会公开。"},{"i":15,"n":"第十五条","txt":"固定资产投资项目节能评审、业务培训、监督检查，以及标准指南编制等工作经费，按照国家有关规定纳入部门预算，并按照规定程序向同级财政部门申请。"},{"i":16,"n":"第十六条","txt":"省级节能审查机关可根据《中华人民共和国节约能源法》和本办法，制定具体实施办法。"},{"i":17,"n":"第十七条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自2017年1月1日起施行。原《固定资产投资项目节能评估和审查暂行办法》(国家发展和改革委员会令第6号)同时废止。"}],"gudingzichantouzixiangmujienengshenchabanfa":[{"i":1,"n":"第一条","txt":"为完善能源消耗总量和强度调控，促进固定资产投资项目科学合理利用能源，加强用能管理，推进能源节约，防止能源浪费，提高能源利用效率，推动实现碳达峰碳中和，根据《中华人民共和国节约能源法》《中华人民共和国行政许可法》《民用建筑节能条例》《公共机构节能条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于各级人民政府投资主管部门管理的在我国境内建设的固定资产投资项目。本办法所称节能审查，是指根据节能法律法规、政策标准等，对项目能源消费、能效水平及节能措施等情况进行审查并形成审查意见的行为。"},{"i":3,"n":"第三条","txt":"固定资产投资项目节能审查意见是项目开工建设、竣工验收和运营管理的重要依据。政府投资项目，建设单位在报送项目可行性研究报告前，需取得节能审查机关出具的节能审查意见。企业投资项目，建设单位需在开工建设前取得节能审查机关出具的节能审查意见。未按本办法规定进行节能审查，或节能审查未通过的项目，建设单位不得开工建设，已经建成的不得投入生产、使用。"},{"i":4,"n":"第四条","txt":"固定资产投资项目节能审查相关工作经费，按照国家有关规定纳入部门预算，并按照规定程序向同级财政部门申请。对项目进行节能审查不得收取任何费用。"},{"i":5,"n":"第五条","txt":"国家发展改革委负责制定节能审查的相关管理办法，组织编制技术标准、规范和指南，开展业务培训，依据各地能源消费形势、落实能源消耗总量和强度调控、控制化石能源消费、完成节能目标任务、推进碳达峰碳中和进展等情况，对各地新上重大高耗能项目的节能审查工作进行督导。"},{"i":6,"n":"第六条","txt":"县级以上地方各级人民政府管理节能工作的部门应根据本地节能工作实际，对节能审查工作加强总体指导和统筹协调，落实能源消耗总量和强度调控，强化能耗强度降低约束性指标管理，有效增强能源消费总量管理弹性，控制化石能源消费，坚决遏制高耗能、高排放、低水平项目盲目发展。"},{"i":7,"n":"第七条","txt":"固定资产投资项目节能审查由地方节能审查机关负责。节能审查机关应当制定并公开服务指南，列明节能审查的申报材料、受理方式、审查条件、办理流程、办理时限等，为建设单位提供指导和服务，提高工作效能和透明度。上级节能审查机关应加强对下级节能审查机关的工作指导。"},{"i":8,"n":"第八条","txt":"节能审查机关与管理节能工作的部门为不同部门的，节能审查机关应与同级管理节能工作的部门加强工作衔接，重大高耗能项目节能审查应征求同级管理节能工作的部门意见，并及时将本部门节能审查实施情况抄送同级管理节能工作的部门。"},{"i":9,"n":"第九条","txt":"国家发展改革委核报国务院审批以及国家发展改革委审批的政府投资项目，建设单位在报送项目可行性研究报告前，需取得省级节能审查机关出具的节能审查意见。国家发展改革委核报国务院核准以及国家发展改革委核准的企业投资项目，建设单位需在开工建设前取得省级节能审查机关出具的节能审查意见。 年综合能源消费量（建设地点、主要生产工艺和设备未改变的改建项目按照建成投产后年综合能源消费增量计算，其他项目按照建成投产后年综合能源消费量计算，电力折算系数按当量值，下同）10000吨标准煤及以上的固定资产投资项目，其节能审查由省级节能审查机关负责。其他固定资产投资项目，其节能审查管理权限由省级节能审查机关依据实际情况自行决定。 年综合能源消费量不满1000吨标准煤且年电力消费量不满500万千瓦时的固定资产投资项目，涉及国家秘密的固定资产投资项目以及用能工艺简单、节能潜力小的行业（具体行业目录由国家发展改革委制定公布"},{"i":10,"n":"第十条","txt":"地方可结合本地实际，在各类开发区、新区和其他有条件的区域实施区域节能审查，明确区域节能目标、节能措施、能效准入、化石能源消费控制等要求。对已经实施区域节能审查范围内的项目，除应由省级节能审查机关审查的，节能审查实行告知承诺制。 区域节能审查具体实施办法由省级管理节能工作的部门依据实际情况制定。"},{"i":11,"n":"第十一条","txt":"需进行节能审查的固定资产投资项目，建设单位应编制节能报告。项目节能报告应包括下列内容： （一）项目概况； （二）分析评价依据； （三）项目建设及运营方案节能分析和比选，包括总平面布置、生产工艺、用能工艺、用能设备和能源计量器具等方面； （四）节能措施及其技术、经济论证； （五）项目能效水平、能源消费情况，包括单位产品能耗、单位产品化石能源消耗、单位增加值（产值）能耗、单位增加值（产值）化石能源消耗、能源消费量、能源消费结构、化石能源消费量、可再生能源消费量和供给保障情况、原料用能消费量；有关数据与国家、地方、行业标准及国际、国内行业水平的全面比较； （六）项目实施对所在地完成节能目标任务的影响分析。 具备碳排放统计核算条件的项目，应在节能报告中核算碳排放量、碳排放强度指标，提出降碳措施，分析项目碳排放情况对所在地完成降碳目标任务的影响。 建设单位应出具书面承诺，对节能报告的真实性、合法"},{"i":12,"n":"第十二条","txt":"节能报告内容齐全、符合法定形式的，节能审查机关应当予以受理。内容不齐全或不符合法定形式的，节能审查机关应当当场或者5日内一次告知建设单位需要补正的全部内容，逾期不告知的，自收到报告之日起即为受理。"},{"i":13,"n":"第十三条","txt":"节能审查机关受理节能报告后，应委托具备技术能力的机构进行评审，形成评审意见，作为节能审查的重要依据。"},{"i":14,"n":"第十四条","txt":"节能审查机关应当从以下方面对项目节能报告进行审查： （一）项目是否符合节能有关法律法规、标准规范、政策要求； （二）项目用能分析是否客观准确，方法是否科学，结论是否准确； （三）项目节能措施是否合理可行； （四）项目的能效水平、能源消费等相关数据核算是否准确，是否满足本地区节能工作管理要求。"},{"i":15,"n":"第十五条","txt":"节能审查机关应在法律规定的时限内出具节能审查意见或明确节能审查不予通过。节能审查意见自印发之日起2年内有效，逾期未开工建设或建成时间超过节能报告中预计建成时间2年以上的项目应重新进行节能审查。"},{"i":16,"n":"第十六条","txt":"通过节能审查的固定资产投资项目，建设地点、建设内容、建设规模、能效水平等发生重大变动的，或年实际综合能源消费量超过节能审查批复水平10%及以上的，建设单位应向原节能审查机关提交变更申请。原节能审查机关依据实际情况，提出同意变更的意见或重新进行节能审查；项目节能审查权限发生变化的，应及时移交有权审查机关办理。"},{"i":17,"n":"第十七条","txt":"固定资产投资项目投入生产、使用前，应对项目节能报告中的生产工艺、用能设备、节能技术采用情况以及节能审查意见落实情况进行验收，并编制节能验收报告。实行告知承诺管理的项目，应对项目承诺内容以及区域节能审查意见落实情况进行验收。分期建设、投入生产使用的项目，应分期进行节能验收。未经节能验收或验收不合格的项目，不得投入生产、使用。 节能验收主体由省级节能审查机关依据实际情况确定。 节能验收报告应在节能审查机关存档备查。"},{"i":18,"n":"第十八条","txt":"固定资产投资项目节能审查应纳入投资项目在线审批监管平台统一管理，实行网上受理、办理、监管和服务，实现审查过程和结果的可查询、可监督。不单独进行节能审查的固定资产投资项目应通过投资项目在线审批监管平台报送项目能源消费等情况。"},{"i":19,"n":"第十九条","txt":"节能审查机关应会同相关行业主管部门强化节能审查事中事后监管，组织对项目节能审查意见落实、节能验收等情况进行监督检查。日常监督检查工作应按照“双随机一公开”原则开展。"},{"i":20,"n":"第二十条","txt":"管理节能工作的部门要依法依规履行节能监督管理职责，将节能审查实施情况作为节能监察的重点内容。各级管理节能工作的部门应加强节能审查信息的统计分析，定期调度已投产项目能源消费、能效水平等情况，作为研判节能形势、开展节能工作的重要参考。"},{"i":21,"n":"第二十一条","txt":"省级管理节能工作的部门应定期向国家发展改革委报告本地区节能审查实施情况，按要求报送项目节能审查信息和已投产项目调度数据。"},{"i":22,"n":"第二十二条","txt":"国家发展改革委实施全国节能审查动态监管，对各地节能审查实施情况进行监督检查，对重大项目节能审查意见落实情况进行不定期抽查。检查抽查结果作为节能目标责任评价考核的重要内容。"},{"i":23,"n":"第二十三条","txt":"对未按本办法规定进行节能审查，或节能审查未获通过，擅自开工建设或擅自投入生产、使用的固定资产投资项目，由节能审查机关责令停止建设或停止生产、使用，限期整改，并对建设单位进行通报批评，视情节处10万元以下罚款。经节能审查机关认定完成整改的项目，节能审查机关可依据实际情况出具整改完成证明。不能整改或逾期不整改的生产性项目，由节能审查机关报请本级人民政府按照国务院规定的权限责令关闭，并依法追究有关责任人的责任。"},{"i":24,"n":"第二十四条","txt":"以拆分项目、提供虚假材料等不正当手段通过节能审查的固定资产投资项目，由节能审查机关撤销项目的节能审查意见；以不正当手段逃避节能审查的固定资产投资项目，由节能审查机关按程序进行节能审查。项目已开工建设或投入生产、使用的，按本办法第二十三条有关规定进行处罚。"},{"i":25,"n":"第二十五条","txt":"未落实节能审查意见要求的固定资产投资项目，由节能审查机关责令建设单位限期整改。不能整改或逾期不整改的，由节能审查机关按照法律法规的有关规定进行处罚。"},{"i":26,"n":"第二十六条","txt":"未按本办法规定进行节能验收或验收不合格，擅自投入生产、使用的固定资产投资项目，以及以提供虚假材料等不正当手段通过节能验收的固定资产投资项目，由节能审查机关责令建设单位限期整改，并处3万元以上5万元以下罚款。"},{"i":27,"n":"第二十七条","txt":"从事节能咨询、评审等节能服务的机构提供节能审查虚假信息的，由管理节能工作的部门责令改正，没收违法所得，并处5万元以上10万元以下罚款。"},{"i":28,"n":"第二十八条","txt":"节能审查机关对建设单位、中介机构等的违法违规信息进行记录，将违法违规行为及其处理信息纳入全国信用信息共享平台和投资项目在线审批监管平台，在“信用中国”网站向社会公开。对列入严重失信主体名单的，依法依规实施联合惩戒措施。"},{"i":29,"n":"第二十九条","txt":"负责审批政府投资项目的工作人员，对未进行节能审查或节能审查未获通过的项目，违反本办法规定予以批准的，依法给予处分。"},{"i":30,"n":"第三十条","txt":"节能审查机关、节能评审机构工作人员以及其他参与评审的有关人员在节能评审中存在违纪违法行为，依法给予处分，构成犯罪的依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"省级管理节能工作的部门可根据《中华人民共和国节约能源法》等有关法律法规和本办法，制定具体实施办法。"},{"i":32,"n":"第三十二条","txt":"本办法由国家发展改革委负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2023年6月1日起施行。原《固定资产投资项目节能审查办法》（国家发展和改革委员会令2016年第44号）同时废止。"}],"guojiayigongdaizhenguanlibanfa":[{"i":1,"n":"第一条","txt":"为充分发挥以工代赈政策作用，进一步规范和加强新形势下以工代赈管理，确保“赈”出实效，根据《中共中央 国务院关于实现巩固拓展脱贫攻坚成果同乡村振兴有效衔接的意见》《国务院办公厅转发国家发展改革委关于在重点工程项目中大力实施以工代赈促进当地群众就业增收工作方案的通知》《关于在农业农村基础设施建设领域积极推广以工代赈方式的意见》等文件精神和《政府投资条例》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称以工代赈是指政府投资建设基础设施工程，受赈济者参加工程建设获得劳务报酬，以此取代直接赈济的一项扶持政策。现阶段，以工代赈主要包括使用以工代赈专项资金实施以工代赈项目、在农业农村基础设施建设领域中推广以工代赈方式、在政府投资的重点工程项目中实施以工代赈等，主要目的是向参与工程建设的群众发放劳务报酬、开展技能培训，促进其就地就近就业增收。"},{"i":3,"n":"第三条","txt":"实施以工代赈应坚守“赈”的初心，坚持扶志扶智、多劳多得、勤劳致富，鼓励引导群众通过诚实劳动实现增收致富、提高素质技能，加强困难群体就业兜底帮扶，努力增加低收入者收入，促进共同富裕，坚决防止出现“重建设、轻赈济”现象，严禁滥用以工代赈政策侵犯劳动者合法权益。"},{"i":4,"n":"第四条","txt":"各级发展改革（以工代赈，下同）部门是以工代赈的行政主管部门，承担以工代赈工作的综合协调和具体管理职责，会同相关部门在农业农村基础设施建设和政府投资的重点工程项目中组织实施以工代赈。 以工代赈工作纳入国家和地方国民经济社会发展年度计划，按照“中央统筹、省负总责、市县乡抓落实”的管理体制，层层压实工作责任。"},{"i":5,"n":"第五条","txt":"各级发展改革部门应加强对以工代赈工作的组织领导，强化以工代赈工作人员队伍建设，会同相关部门建立沟通协调机制，加强部门协同配合。"},{"i":6,"n":"第六条","txt":"各级发展改革部门应会同相关部门建立健全以工代赈激励机制，加强典型宣传推介。对以工代赈工作积极主动、成效明显的地方和单位给予激励表扬，并在以工代赈专项投资安排中予以倾斜支持。"},{"i":7,"n":"第七条","txt":"地方发展改革部门应根据国家及地方国民经济和社会发展五年规划，结合本地实际，同步编制实施以工代赈领域五年规划或相关工作方案。"},{"i":8,"n":"第八条","txt":"以工代赈计划是指使用国家以工代赈专项资金组织实施的专门计划，包括以工代赈中央预算内投资计划、中央财政衔接推进乡村振兴补助资金以工代赈任务计划，可分年度或分专项安排。 以工代赈计划的基本内容包括投资规模及构成、建设内容、工作任务和政策要求等。"},{"i":9,"n":"第九条","txt":"国家发展改革委负责研究提出以工代赈计划工作总体要求，组织有关省级发展改革部门编制建议计划草案。 省级发展改革部门负责审核下级发展改革部门编报的年度以工代赈建议计划，汇总编制本省年度以工代赈建议计划草案，及时报送国家发展改革委汇总。 建议计划草案应明确项目类别、项目名称、建设内容及规模、建设工期、项目总投资及资金来源、绩效目标等。"},{"i":10,"n":"第十条","txt":"国家发展改革委按照党中央、国务院部署要求，根据地方经济社会发展、自然条件和受灾、相关人口规模和收入、计划安排和执行、劳务报酬发放等情况和工作成效评价及其他政策因素等，结合年度工作重点和地方建议计划草案，编制下达国家以工代赈计划，以切块或打捆方式下达分省规模。"},{"i":11,"n":"第十一条","txt":"省级发展改革部门应自收到国家年度以工代赈计划之日起20个工作日内，将本省年度以工代赈计划分解下达到项目。 分解下达以工代赈计划应按项目明确资金安排方式。政府投资资金安排的非经营性项目，应采取直接投资方式。 以工代赈计划下达后，严禁未经批准擅自变更建设内容和建设规模。确需调整的，应由项目审批部门按程序审批，并按规定履行备案程序。"},{"i":12,"n":"第十二条","txt":"地方各级发展改革部门应建立健全以工代赈计划执行监测机制，实行定期调度、动态监测。省级发展改革部门应跟踪掌握本省以工代赈计划执行情况，及时上报国家发展改革委。"},{"i":13,"n":"第十三条","txt":"国家以工代赈专项资金包括以工代赈中央预算内投资、中央财政衔接推进乡村振兴补助资金以工代赈任务方向（以下简称“中央财政以工代赈任务资金”）。 各地结合当地实际，积极将以工代赈投入纳入本级财政预算，安排本级以工代赈专项资金。"},{"i":14,"n":"第十四条","txt":"以工代赈中央预算内投资按照《中央预算内直接投资项目管理办法》（国家发展改革委2014年第7号令）、《中央预算内投资补助和贴息项目管理办法》（国家发展改革委2016年第45号令）等有关规定管理。 中央财政以工代赈任务资金按照《中央财政衔接推进乡村振兴补助资金管理办法》（财农〔2021〕19号）等有关规定管理。 地方各级发展改革部门应会同财政、乡村振兴等部门和单位，结合本地实际建立健全专项资金管理制度。"},{"i":15,"n":"第十五条","txt":"以工代赈专项资金主要投向欠发达地区，并向原深度贫困地区、国家乡村振兴重点帮扶县、革命老区、易地扶贫搬迁后续扶持任务较重地区以及受自然灾害影响较大地区倾斜。对其他有关地区的以工代赈专项资金投入，按照国家有关政策要求安排。"},{"i":16,"n":"第十六条","txt":"以工代赈专项资金重点支持公益性基础设施和产业发展配套基础设施建设，以及根据国家要求安排的其他工程建设。 公益性基础设施主要包括农村生活、交通、水利等基础设施、林业草原和城乡易地扶贫搬迁安置点配套公益性基础设施等。 产业发展配套基础设施主要包括农牧产业、乡村文化旅游产业、林业草原产业等基础设施和城乡易地扶贫搬迁安置点后续产业基础设施等。"},{"i":17,"n":"第十七条","txt":"以工代赈中央预算内投资主要用于实施一批中小型基础设施建设项目，推广“公益性基础设施建设+劳务报酬发放+就业技能培训+公益性管护岗位开发”和“产业发展配套基础设施建设+劳务报酬发放+就业技能培训+资产折股量化分红”等综合赈济模式，进一步提高劳务报酬发放比例，形成示范带动效应。 中央财政以工代赈任务资金主要用于统筹支持巩固拓展脱贫攻坚成果、全面推进乡村振兴，实施一批小型基础设施建设项目并发放劳务报酬，与财政衔接推进乡村振兴补助资金其他任务形成合力。"},{"i":18,"n":"第十八条","txt":"国家以工代赈专项资金应当用于新开工或续建项目，不得用于已完工项目。下达以工代赈专项资金时应与其他有关专项资金做好衔接，严禁重复安排。 以工代赈项目的具体补助标准可参照国家相关支持标准，由各省根据不同类型项目自行确定。"},{"i":19,"n":"第十九条","txt":"国家以工代赈专项资金在满足项目建设需求的过程中，应重点用于发放参与项目建设劳动者的劳务报酬。不得用于下列支出： （一）单位基本支出； （二）交通工具及通讯设备； （三）发放奖金津贴和福利补助； （四）偿还债务和垫资； （五）购买大中型机械设备等资产； （六）购买花草树木、种苗仔畜、饲料、化肥等生产性物资； （七）其他与以工代赈项目无关的支出事项。 以工代赈项目实施中的就业技能培训、公益性管护岗位开发等工作任务，由地方政府统筹相关财政资金及社会帮扶资金、企业投资等予以支持。"},{"i":20,"n":"第二十条","txt":"县级发展改革部门应指导项目业主单位，充分评估论证财政承受能力和资金筹措方案，防范地方政府债务风险。各地可统筹符合规定的其它渠道资金、引导社会资金用于以工代赈项目建设，对于带动其他渠道资金较多的以工代赈项目予以优先支持。"},{"i":21,"n":"第二十一条","txt":"各级发展改革部门应协调和配合相关专项资金管理部门按照以工代赈计划拨付资金，加强全过程绩效管理，严格资金拨付程序，确保资金安全、及时、准确、规范使用。"},{"i":22,"n":"第二十二条","txt":"以工代赈项目是指使用以工代赈专项资金实施的基础设施建设工程。地方发展改革部门应深刻把握“项目建设是平台载体、就业增收是根本目标”的政策内涵，始终把解决群众就业增收问题作为以工代赈工作的出发点和落脚点，依据以工代赈规划计划建立项目库，将能够充分发挥“赈”的作用的建设工程纳入项目库，加强项目滚动储备和前期工作审查。"},{"i":23,"n":"第二十三条","txt":"以工代赈项目按照基本建设程序管理。国家有特殊要求的项目由省级发展改革部门报国家发展改革委审批，其他项目由地方各级审批部门依据审批权限履行项目审批手续。各级审批部门按照“谁审批、谁负责”原则，对项目的审批管理和合规性负责。"},{"i":24,"n":"第二十四条","txt":"地方各级发展改革部门应会同有关部门建立以工代赈储备项目的前期工作审查机制，按照“省负总责，省、市、县分级把关”的原则，可选择集中审查、委托第三方评估等方式，严格审查储备申报项目的前期要件和项目用工需求、劳务报酬发放可行性、资金投向合规情况等。 列入以工代赈建议计划的项目，原则上应在以工代赈项目库中选择，并优先支持发放劳务报酬比例高、带动当地群众特别是脱贫群众务工人数多、当地政府组织群众务工能力强、综合赈济效果好的项目。"},{"i":25,"n":"第二十五条","txt":"以工代赈项目业主单位一般为乡镇人民政府和村民委员会、农村集体经济组织等。 村民委员会、农村集体经济组织作为项目业主单位的，应尽可能采取村民自建方式实施，切实保障村民知情权、参与权、监督权。鼓励和支持村集体经济组织通过组建村民理事会、劳务合作社、施工队等方式，自主开展以工代赈项目建设和管理。"},{"i":26,"n":"第二十六条","txt":"按照招标投标法和村庄建设项目施行简易审批的有关规定要求，以工代赈项目可以不进行招标，任何单位和个人不得强制要求招标，不得另行制定必须招标的范围和规模标准。 符合村庄建设项目施行简易审批相关要求的，各地应优化可行性研究报告等审批，简化用地、环评、乡村规划许可、施工许可等审批手续。"},{"i":27,"n":"第二十七条","txt":"以工代赈项目应按照相关工程标准进行设计、施工，明确工程责任单位和责任人，确保施工安全和工程质量符合相关要求。"},{"i":28,"n":"第二十八条","txt":"县级发展改革部门应指导以工代赈项目业主单位、施工单位，按照“能用人工尽量不用机械，能组织当地群众务工尽量不用专业施工队伍”的要求，组织项目所在县域内农村劳动力、城镇低收入人口和就业困难群体等参加工程建设，并优先吸纳脱贫人口、防止返贫监测对象、因灾需救助人口、易地扶贫搬迁群众和受自然灾害等不可抗力影响无法外出务工劳动力等群体。"},{"i":29,"n":"第二十九条","txt":"县级发展改革部门应督促指导项目业主单位，结合编制项目可行性研究报告或实施方案，明确务工组织领导、管理、监督等工作任务，细化实化以工代赈务工岗位、数量及务工时间、劳务报酬、岗前技能培训等内容。 业主单位应与项目所在乡镇人民政府、村民委员会和施工单位建立劳务沟通协调机制，督促施工单位与务工群众签订劳务合同（协议）。"},{"i":30,"n":"第三十条","txt":"县级发展改革部门应指导以工代赈项目业主单位、施工单位，严格按照专项计划文件明确的劳务报酬占中央资金比例要求，结合当地群众务工收入水平确定劳务报酬发放标准和规模，做好劳务报酬发放工作，尽最大可能提高以工代赈项目劳务报酬占财政资金的比例。劳务报酬一般通过银行卡发放。 项目业主单位应公开、足额、及时发放劳务报酬，严禁拖欠、克扣，不得将租赁当地群众机械设备等费用计入劳务报酬。 县级发展改革部门在项目前期工作环节应指导以工代赈项目业主单位、施工单位，对能否足额发放劳务报酬进行论证，明确劳务报酬发放金额和标准。"},{"i":31,"n":"第三十一条","txt":"以工代赈项目推行信息公示公告制度，主动接受社会监督。项目开工前，业主单位应对项目名称、资金来源及金额、建设地点、建设内容及规模、建设周期等信息予以公示。项目施工期间，业主单位应在施工现场对群众务工信息、劳务报酬发放标准、监督举报电话等内容进行公示。项目建成后，业主单位应在项目点设置永久性公示牌，公示项目建设相关信息和当地群众参与务工、获取劳务报酬等受益情况。"},{"i":32,"n":"第三十二条","txt":"以工代赈项目建成后，县级发展改革部门应会同有关部门组成验收工作组，重点对项目建设质量、群众务工组织、劳务报酬发放、就业技能培训等落实情况开展验收，并对项目发挥“赈”的作用效果进行评价。 县级发展改革部门和相关乡镇人民政府应加强项目档案资料管理。省、市发展改革部门应对项目验收、档案资料管理情况进行抽查检查。"},{"i":33,"n":"第三十三条","txt":"推广以工代赈方式的农业农村基础设施建设领域，主要包括投资规模较小、技术方案相对简单、用工技能要求不高的农村生产生活基础设施，农村小型交通、水利、文化旅游和林业草原等基础设施建设。"},{"i":34,"n":"第三十四条","txt":"适宜在农业农村基础设施建设领域推广以工代赈方式的省份，省级发展改革部门应会同相关部门建立健全省级推广以工代赈方式项目储备库（或清单，下同），按年度滚动管理。对于农业农村基础设施项目，在不影响项目建设进度和施工质量等前提下，应尽可能纳入项目储备库，采取以工代赈方式实施。"},{"i":35,"n":"第三十五条","txt":"县级发展改革部门应牵头统筹协调县域范围内农业农村基础设施建设领域推广以工代赈方式工作，结合实际制定工作流程、管理细则和考核办法，建立县级推广以工代赈方式项目储备库，规范项目组织实施和管理工作。"},{"i":36,"n":"第三十六条","txt":"县级发展改革部门会同相关部门负责农业农村基础设施建设领域推广以工代赈方式项目的认定工作，提请县级人民政府审定后，纳入县级推广以工代赈方式项目储备库管理，符合条件的项目可通过安排以工代赈专项资金予以支持。 按照招标投标法和村庄建设项目施行简易审批的有关规定要求，农业农村基础设施建设领域推广以工代赈方式项目可以不进行招标。"},{"i":37,"n":"第三十七条","txt":"经认定为推广以工代赈方式的项目，应严格落实组织群众务工、开展就业技能培训等以工代赈政策要求，及时足额向当地农村群众发放劳务报酬，尽量提高项目资金中劳务报酬发放比例。"},{"i":38,"n":"第三十八条","txt":"适用以工代赈的重点工程项目建设领域，包括政府投资的交通、水利、能源、农业农村、城镇建设、生态环境、灾后恢复重建等。"},{"i":39,"n":"第三十九条","txt":"各地在谋划实施政府投资的重点工程项目时，应在确保工程质量安全和符合进度要求等前提下，按照“应用尽用、能用尽用”的原则，结合当地群众务工需求，挖掘主体工程建设及附属临建、工地服务保障、建后管护等方面用工潜力，尽可能通过实施以工代赈帮助当地群众就近务工实现就业增收。 鼓励非政府投资的重点工程项目采取以工代赈方式扩大就业容量。引导民营企业、社会组织等各类社会力量采取以工代赈方式组织实施公益性帮扶项目。"},{"i":40,"n":"第四十条","txt":"国家发展改革委会同相关部门，结合各相关领域重点工程项目中能够实施以工代赈的建设任务和用工环节指导目录，分年度明确国家层面适用以工代赈的重点工程项目清单。 地方各级发展改革部门按照“分级负责、分领域推进”的原则，会同相关部门分年度明确本级适用以工代赈的重点工程项目清单。 县级发展改革部门应牵头协调县域范围内重点工程项目实施以工代赈工作，规范以工代赈务工人员组织、劳动技能培训和安全生产培训、劳务报酬发放监管等具体工作管理。"},{"i":41,"n":"第四十一条","txt":"实施以工代赈的重点工程项目可行性研究报告或资金申请报告、初步设计报告或施工图设计文件、批复文件等，应明确适用以工代赈的建设内容和用工环节等政策要求。项目相关招标投标、签订劳务合同过程中应明确当地群众用工和劳务报酬发放要求等。"},{"i":42,"n":"第四十二条","txt":"实施以工代赈的重点工程项目所在地应建立劳务沟通协调机制，以县域为主组织动员当地农村劳动力、城镇低收入人口和就业困难群体等参与务工，抓好以工代赈务工人员组织、劳动技能和安全生产培训、劳务报酬发放监管等具体工作。"},{"i":43,"n":"第四十三条","txt":"实施以工代赈的重点工程项目所在地应统筹各类符合条件的培训资金和资源，充分利用项目施工场地、机械设备等，采取“培训+上岗”等方式，联合施工单位开展劳动技能培训和安全生产培训。"},{"i":44,"n":"第四十四条","txt":"鼓励实施以工代赈的重点工程项目业主单位、施工单位尽量扩充以工代赈就业岗位，及时向项目所在地县级人民政府相关部门告知用工需求和用工计划，合理确定以工代赈劳务报酬标准，尽可能增加劳务报酬规模，按程序及时足额发放到位。"},{"i":45,"n":"第四十五条","txt":"东部省份在广泛组织动员当地群众参与重点工程项目建设的同时，可结合本地区经济发展水平、当地群众务工需求等情况，大力吸纳中西部省份外出务工人员参与工程建设。"},{"i":46,"n":"第四十六条","txt":"国家发展改革委会同相关部门建立健全以工代赈工作监督检查和成效综合评价机制，对以工代赈专项资金和项目管理、在农业农村基础设施建设领域推广以工代赈方式和重点工程项目中实施以工代赈工作情况开展监督检查和成效评价，及时发现并推动解决以工代赈政策执行中的问题和偏差。"},{"i":47,"n":"第四十七条","txt":"省级发展改革部门应对市县以工代赈工作开展常态化跟踪督促和年度成效综合评价，配合审计、财政等部门做好以工代赈专项资金和项目督促检查和审计工作。 对发现问题突出或评价结果较差的市县，省级发展改革部门应及时予以通报或约谈，提出整改要求，酌情调减或暂停其以工代赈专项资金安排。"},{"i":48,"n":"第四十八条","txt":"对由于各省在以工代赈项目资金申请前期审核不严而造成较大损失的，国家发展改革委可视情节在一定时期和范围内不再受理其报送的以工代赈计划草案。对地方擅自变更建设内容、建设规模的，劳务报酬弄虚作假，以及在投资计划执行和项目实施中出现重大问题的，国家发展改革委可酌情减少或暂停其以工代赈专项资金安排。"},{"i":49,"n":"第四十九条","txt":"在编报下达以工代赈计划工作中，有滥用职权、玩忽职守、徇私舞弊、索贿受贿以及违反规定原则、程序下达投资计划或安排项目等行为的，责令限期改正，并视具体情况追究有关责任人的行政责任；构成犯罪的，由司法机关追究刑事责任。"},{"i":50,"n":"第五十条","txt":"在以工代赈专项资金和项目管理过程中，出现重大问题或达不到预期效益的，对相关责任部门予以通报批评，并酌情调减当地下一年度以工代赈投资规模。 凡拖欠、截留、挪用、挤占、骗取、贪污以工代赈投入的，以及存在群众务工组织弄虚作假、劳务报酬虚报冒领等行为的，责令限期归还、如数追缴，并转请有关部门依法依规依纪从严处置；构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"本办法由国家发展改革委负责解释。省级发展改革部门可根据工作需要制定或修订本省以工代赈管理实施细则，并报国家发展改革委备案。"},{"i":52,"n":"第五十二条","txt":"本办法自2023年3月1日起施行。国家发展改革委2014年12月29日印发的《国家以工代赈管理办法》同时废止。"}],"guojiaqiyejishuzhongxinrendingguanlibanfa":[{"i":1,"n":"第一条","txt":"为深入实施创新驱动发展战略，贯彻落实《中共中央国务院关于深化科技体制改革加快国家创新体系建设的意见》，进一步强化企业技术创新主体地位，引导和支持企业增强技术创新能力，健全技术创新市场导向机制，规范国家企业技术中心管理，依据《中华人民共和国科学技术进步法》，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称企业技术中心，是指企业根据市场竞争需要设立的技术研发与创新机构，负责制定企业技术创新规划、开展产业技术研发、创造运用知识产权、建立技术标准体系、凝聚培养创新人才、构建协同创新网络、推进技术创新全过程实施。"},{"i":3,"n":"第三条","txt":"国家鼓励和支持企业建立技术中心，发挥企业在技术创新中的主体作用，建立健全企业主导产业技术研发创新的体制机制。国家根据创新驱动发展要求和经济结构调整需要，对创新能力强、创新机制好、引领示范作用大、符合条件的企业技术中心予以认定，并给予政策支持，鼓励引导行业骨干企业带动产业技术进步和创新能力提高。"},{"i":4,"n":"第四条","txt":"国家发展改革委、科技部、财政部、海关总署、税务总局负责指导协调国家企业技术中心相关工作。国家发展改革委牵头开展国家企业技术中心的认定与运行评价。 各省、自治区、直辖市、计划单列市及新疆生产建设兵团发展改革部门或地方人民政府指定的部门会同同级管理部门，负责国家企业技术中心的申报、管理等事项。"},{"i":5,"n":"第五条","txt":"国家企业技术中心的认定，原则上每年进行一次。地方政府主管部门根据国家发展改革委通知要求报送申请材料，受理截止日期为当年5月31日。"},{"i":6,"n":"第六条","txt":"国家企业技术中心应当具备以下基本条件： (一)企业在行业中具有显著的发展优势和竞争优势，具有行业领先的技术创新能力和水平; (二)企业具有较好的技术创新机制，企业技术中心组织体系健全，创新效率和效益显著; (三)有较高的研究开发投入，年度研究与试验发展经费支出额不低于1500万元;拥有技术水平高、实践经验丰富的技术带头人，专职研究与试验发展人员数不少于150人; (四)具有比较完善的研究、开发、试验条件，技术开发仪器设备原值不低于2000万元;有较好的技术积累，重视前沿技术开发，具有开展高水平技术创新活动的能力; (五)具有省级企业技术中心资格两年以上。 企业在申请受理截止日期前三年内，不得存在下列情况： (一)因违反海关法及有关法律、行政法规，构成走私行为，受到刑事、行政处罚，或因严重违反海关监管规定受到行政处罚; (二)因违反税收征管法及有关法律、行政法规，构成偷税、骗取出口退税等"},{"i":7,"n":"第七条","txt":"地方政府主管部门会同同级管理部门，根据本办法及当年国家发展改革委发布的通知，推荐符合条件的企业技术中心，并将推荐企业技术中心名单及其申请材料(一式二份)报送国家发展改革委。 申请材料主要包括企业技术中心申请报告、评价表及必要的证明材料。"},{"i":8,"n":"第八条","txt":"母公司技术中心已是国家企业技术中心的，地方政府主管部门不得再推荐其下属子公司申请国家企业技术中心。但从事业务领域与母公司不同的子公司，可推荐其申请母公司国家企业技术中心分中心。 子公司技术中心已是国家企业技术中心的，地方政府主管部门在推荐其母公司申请国家企业技术中心时，应在推荐意见中明确提出将其子公司国家企业技术中心调整为分中心或撤销的意见。 国家企业技术中心分中心的申请程序和要求与国家企业技术中心相同。"},{"i":9,"n":"第九条","txt":"国家发展改革委委托第三方机构，依据评价指标体系对地方政府主管部门推荐的企业技术中心申请材料进行初评，并根据初评结果委托第三方机构组织专家评审。 国家发展改革委会同科技部、财政部、海关总署、税务总局，根据专家评审意见以及国家产业政策、国家进口税收税式支出的总体原则及年度方案等综合评估，确认认定结果，并通过国家发展改革委官方网站予以公示。"},{"i":10,"n":"第十条","txt":"国家发展改革委会同科技部、财政部、海关总署、税务总局，在受理地方政府主管部门申报材料之日起90个工作日之内联合发文，向地方政府主管部门及同级管理部门通报认定结果。"},{"i":11,"n":"第十一条","txt":"国家发展改革委会同科技部、财政部、海关总署、税务总局，原则上每两年组织一次国家企业技术中心运行评价。国家发展改革委于评价年度下发评价通知。 地方政府主管部门对国家企业技术中心评价材料真实性出具意见，并于评价年度的5月31日前将评价材料报送国家发展改革委。 评价材料主要包括国家企业技术中心工作总结、评价表及必要的证明材料。"},{"i":12,"n":"第十二条","txt":"国家发展改革委委托第三方机构，依据评价指标体系，对地方政府主管部门报送的评价材料进行评价，并形成评价结果和评价报告。"},{"i":13,"n":"第十三条","txt":"评价结果分为优秀、良好、基本合格和不合格： (一)评价得分90分及以上为优秀; (二)评价得分65分至90分(不含90分)为良好; (三)评价得分60分至65分(不含65分)为基本合格; (四)评价得分低于60分为不合格。"},{"i":14,"n":"第十四条","txt":"国家发展改革委会同科技部、财政部、海关总署、税务总局对评价结果进行确认。国家发展改革委在受理评价材料之日起70个工作日内，向地方政府主管部门通报评价结果。"},{"i":15,"n":"第十五条","txt":"国家企业技术中心和国家企业技术中心分中心进口科技开发用品按照国家相关税收政策执行。 经海关确认后，国家企业技术中心可按有关规定，将免税进口的科技开发用品放置在其异地非独立法人分支机构使用。"},{"i":16,"n":"第十六条","txt":"国家发展改革委结合企业技术中心创新能力建设、高技术产业化、战略性新兴产业发展等工作，对国家企业技术中心予以支持。"},{"i":17,"n":"第十七条","txt":"国家支持国家企业技术中心承担中央财政科技计划(专项、基金等)的研发任务。"},{"i":18,"n":"第十八条","txt":"地方政府主管部门应于每年8月30日前，将国家企业技术中心所在企业发生更名、重组等变更情况报送国家发展改革委，同时抄送地方同级管理部门。"},{"i":19,"n":"第十九条","txt":"国家发展改革委会同科技部、财政部、海关总署、税务总局，每年对地方政府主管部门报送的企业变更情况进行确认。其中，对经确认取消国家企业技术中心资格的，自该国家企业技术中心所在企业发生更名、重组等变更之日起，停止享受科技开发用品免征进口税收政策。"},{"i":20,"n":"第二十条","txt":"自国家企业技术中心所在企业发生更名、重组等变更之日起，该企业所属国家企业技术中心进口的有关科技开发用品，经海关审核符合有关规定，可办理凭税款担保放行手续。待国家企业技术中心所在企业更名情况确认后，根据确认结果办理已凭税款担保放行的有关进口科技开发用品的税款征免手续。"},{"i":21,"n":"第二十一条","txt":"母公司技术中心已认定为国家企业技术中心的，其子公司原有国家企业技术中心的资格应予调整。其中，从事业务领域与母公司不同的，可调整为其母公司国家企业技术中心分中心;业务领域与母公司一致的，取消其国家企业技术中心资格。 地方政府主管部门推荐母公司申请国家企业技术中心时，没有提出对其子公司国家企业技术中心调整意见的，视同母公司与子公司业务领域相同。"},{"i":22,"n":"第二十二条","txt":"地方政府主管部门报送的企业材料和数据应当真实可靠。企业提供虚假材料和数据的行为，经核实，将纳入国家统一的信用信息平台。"},{"i":23,"n":"第二十三条","txt":"有下列情况之一的，撤销国家企业技术中心资格： (一)运行评价不合格; (二)逾期未报送评价材料; (三)提供虚假材料和数据; (四)主要由于技术原因发生重大质量、安全事故; (五)因违反海关法及有关法律、行政法规，构成走私行为，受到刑事、行政处罚，或因严重违反海关监管规定受到行政处罚; (六)因违反税收征管法及有关法律、行政法规，构成偷税、骗取出口退税等严重税收违法行为; (七)司法、行政机关认定的其他严重违法失信行为; (八)企业被依法终止。"},{"i":24,"n":"第二十四条","txt":"因本办法第二十三条第(一)、(二)项所列原因被撤销国家企业技术中心资格的，自撤销之日起，地方政府主管部门两年内不得再次推荐该企业。 因本办法第二十三条第(三)～(七)项所列原因被撤销国家企业技术中心资格的，自撤销之日起，地方政府主管部门三年内不得再次推荐该企业。 地方政府主管部门负责指导和督促评价基本合格的国家企业技术中心改进工作。"},{"i":25,"n":"第二十五条","txt":"各直属海关对推荐申请国家企业技术中心的企业和国家企业技术中心所在企业是否存在本办法第六条第二款第(一)项、第二十三条第(五)项所列情况进行核查，具体核查要求由海关总署另行确定。 税务机关对推荐申请国家企业技术中心的企业和国家企业技术中心所在企业是否存在本办法第六条第二款第(二)项、第二十三条第(六)项情况进行核查，具体核查要求由税务总局另行确定。"},{"i":26,"n":"第二十六条","txt":"国家发展改革委会同科技部、财政部、海关总署、税务总局联合发文，向地方政府主管部门及同级管理部门通报国家企业技术中心调整、撤销和更名结果。"},{"i":27,"n":"第二十七条","txt":"各地方政府主管部门可参考本办法，结合本地实际，在职责范围内依法制定相应政策，支持企业技术中心建设。"},{"i":28,"n":"第二十八条","txt":"本办法涉及的申请材料、评价材料和评价指标体系的内容和要求，由国家发展改革委商科技部、财政部、海关总署、税务总局后另行发布并适时调整。"},{"i":29,"n":"第二十九条","txt":"依据《中华人民共和国政府信息公开条例》，国家企业技术中心认定的相关信息向社会公开。国家企业技术中心的认定、运行评价等，逐步实现网上办理。"},{"i":30,"n":"第三十条","txt":"本办法自2016年4月1日起施行。《鼓励和支持大型企业和企业集团建立技术中心暂行办法》(国经贸〔1993〕261号)和《国家认定企业技术中心管理办法》(第53号令)同时废止。"},{"i":31,"n":"第三十一条","txt":"本办法由国家发展改革委会同科技部、财政部、海关总署、税务总局负责解释。"}],"guojiafazhanhegaigeweiyuanhuixingzhengfuyishishibae92a1a":[{"i":1,"n":"第一条","txt":"为防止和纠正违法的或者不当的行政行为，保护公民、法人和其他组织的合法权益，监督和保障国家发展改革委依法行使职权，发挥行政复议化解行政争议的主渠道作用，推进法治机关建设，根据《行政复议法》《行政复议法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"国家发展改革委受理行政复议申请、办理行政复议案件，适用本办法。"},{"i":3,"n":"第三条","txt":"国家发展改革委法治工作机构是国家发展改革委行政复议机构（以下简称行政复议机构），具体办理国家发展改革委行政复议事项，履行下列职责： （一）受理行政复议申请； （二）组织开展行政复议调解； （三）向有关组织和人员调查取证，查阅文件和资料； （四）组织行政复议听证； （五）依据法律、行政法规和部门规章审查被申请行政复议的行政行为是否合法与适当，拟定行政复议决定； （六）处理或者转送对有关规范性文件或者行政行为依据的附带审查事项； （七）对被申请人违反有关法律、行政法规、部门规章的行为依照规定的权限和程序提出处理建议； （八）办理国家发展改革委有关行政应诉事项； （九）法律、行政法规和部门规章规定的其他职责。"},{"i":4,"n":"第四条","txt":"国家发展改革委对办理的行政复议案件进行调解时，应当遵循合法、自愿的原则，不得损害国家利益、社会公共利益和他人合法权益，不得违反法律、法规的强制性规定。 行政复议机构应当记录调解情况，将调解工作记录、调解协议书等材料立卷归档。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织可以依照《行政复议法》第十一条规定的行政复议范围，向国家发展改革委申请行政复议。 下列事项不属于行政复议范围： （一）国防、外交等国家行为； （二）行政法规、部门规章或者具有普遍约束力的决定、命令等规范性文件； （三）国家发展改革委实施的行政指导行为； （四）国家发展改革委为作出行政行为而实施的论证、委托评估、请示、报告、咨询等过程性行为； （五）国家发展改革委对本机关工作人员的奖惩、任免等决定； （六）国家发展改革委对民事纠纷作出的调解； （七）对国家发展改革委及其管理的法律、行政法规、部门规章授权的组织的工作人员个人违法违纪行为进行举报、控告或者对工作人员的态度作风提出异议； （八）对国家发展改革委及其管理的法律、行政法规、部门规章授权的组织的业务政策、内部工作制度或者工作程序提出异议的； （九）对有关法律、法规、规章或者政策文件制定、实施情况进行咨询的。 信"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织认为国家发展改革委的行政行为依据的下列规范性文件不合法，在对行政行为申请行政复议时，可以一并向国家发展改革委提出对该规范性文件的附带审查申请： （一）国家发展改革委制定、发布的规范性文件； （二）国家发展改革委管理的法律、行政法规、部门规章授权的组织发布的规范性文件。 前款所列规范性文件不含规章。规章的审查依照法律、行政法规办理。"},{"i":7,"n":"第七条","txt":"国家发展改革委管辖下列行政复议案件： （一）对国家发展改革委作出的行政行为不服的； （二）对国家发展改革委管理的法律、行政法规、部门规章授权的组织作出的行政行为不服的。 公民、法人或者其他组织对国家发展改革委和其他国务院部门以共同名义作出的同一行政行为不服的，可以向国家发展改革委或者其他共同作出行政行为的国务院部门提出行政复议申请，由国家发展改革委和作出行政行为的国务院部门共同作出行政复议决定。 国家发展改革委管理的国家局以自己名义作出的行政行为，被申请行政复议的，由该国家局自行管辖。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织对国家发展改革委作出的行政行为不服申请行政复议的，国家发展改革委是被申请人；对国家发展改革委管理的法律、行政法规、部门规章授权的组织作出的行政行为不服的，该组织是被申请人。 国家发展改革委委托的组织作出行政行为的，国家发展改革委是被申请人。 对国家发展改革委与其他国务院部门以共同名义作出同一行政行为的，国家发展改革委与共同作出行政行为的国务院部门是被申请人。"},{"i":9,"n":"第九条","txt":"公民、法人或者其他组织认为有关行政行为侵犯其合法权益，符合行政复议法律法规和本办法规定的管辖和受理情形的，可以自知道或者应当知道该行政行为之日起60日内向国家发展改革委提出行政复议申请。法律规定的申请期限超过60日的除外。 因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。 有关行政行为作出时，未告知公民、法人或者其他组织申请行政复议的权利、行政复议机关和申请期限的，申请期限自公民、法人或者其他组织知道或者应当知道申请行政复议的权利、行政复议机关和申请期限之日起计算，但是自知道或者应当知道行政行为内容之日起最长不得超过一年。"},{"i":10,"n":"第十条","txt":"因不动产提出的行政复议申请自行政行为作出之日起超过二十年，其他行政复议申请自行政行为作出之日起超过五年的，国家发展改革委不予受理。"},{"i":11,"n":"第十一条","txt":"申请人申请行政复议，可以通过邮寄或者行政行为决定书上告知的互联网渠道等方式，提交行政复议申请书；也可以当面提交行政复议申请书。书面申请有困难的，也可以口头申请，由两名以上国家发展改革委行政复议人员当场记录申请人的基本情况、行政复议请求、申请行政复议的主要事实、理由和时间，并由申请人当场签名确认。 申请人对两个以上行政行为不服的，应当分别申请行政复议。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，申请人应当先向国家发展改革委申请行政复议，对行政复议决定不服的，可以再依法向人民法院提起行政诉讼： （一）对国家发展改革委当场作出的行政处罚决定不服； （二）对国家发展改革委作出的侵犯其已经依法取得的自然资源的所有权或者使用权的决定不服； （三）申请履行相应法定职责，认为国家发展改革委存在行政复议法第十一条第三项、第十一项、第十二项、第十四项规定的在法定期限内未受理、受理后不予答复或者不履行相应法定职责的情形； （四）申请政府信息公开，国家发展改革委认为申请公开的信息属于《中华人民共和国政府信息公开条例》第十四条、第十五条、第十六条规定的情形，决定全部或者部分不予公开； （五）法律、行政法规规定应当先申请行政复议的其他情形。"},{"i":13,"n":"第十三条","txt":"对国家发展改革委作出的行政复议决定不服的，可以向人民法院提起行政诉讼；对国家发展改革委依据本办法第七条第一项规定作出的行政复议决定不服的，也可以向国务院申请裁决。"},{"i":14,"n":"第十四条","txt":"行政复议申请书应当载明下列内容： （一）申请人的基本情况，包括：公民的姓名、身份证明、联系方式；法人或者其他组织的名称、住所、联系方式、法定代表人姓名等； （二）被申请人的名称、地址、联系方式； （三）行政复议请求； （四）申请行政复议的主要事实和理由，以及必要的证据； （五）申请人的签名或者盖章； （六）提出行政复议申请的日期。 申请人为自然人的，应当提交居民身份证或其他有效证件的复印件；申请人为法人或其他组织的，应当提交营业执照或其他有效证件的复印件、法定代表人身份证明等。由申请人法定代理人或者授权委托人代为申请的，应当在行政复议申请书写明法定代理人或者委托代理人的基本情况，并提交法定代理人或者委托代理人的身份证明和代理权限证明等材料。"},{"i":15,"n":"第十五条","txt":"同一行政复议案件申请人超过10人的，推选2至5名代表人参加行政复议。申请人推选代表人，应当向行政复议机关提交由全体申请人签名、盖章或者按指印的推选书，载明代表人基本情况和权限。 代表人参加行政复议的行为对其所代表的申请人发生效力，但是代表人变更行政复议请求、撤回行政复议申请、承认第三人请求的，应当经被代表的申请人书面签字同意。"},{"i":16,"n":"第十六条","txt":"申请人以外的同申请行政复议的行政行为或者行政复议案件处理结果有利害关系的其他公民、法人或者其他组织以书面形式提出申请，可以作为第三人参加行政复议。 申请人提出申请或行政复议机构认为必要时，也可以由行政复议机构通知同申请行政复议的行政行为或者行政复议案件处理结果有利害关系的其他公民、法人或者其他组织作为第三人参加行政复议。 第三人不参加行政复议，不影响行政复议案件的审理。"},{"i":17,"n":"第十七条","txt":"申请人、第三人可以委托一至二名律师、基层法律服务工作者或者其他代理人代为参加行政复议。 申请人、第三人委托代理人的，应当向行政复议机构提交授权委托书、委托人及被委托人的身份证明文件。授权委托书应当载明委托事项、权限和期限，申请人、第三人在授权委托书上签名或盖章。申请人、第三人变更或者解除代理人权限的，应当书面告知行政复议机构。"},{"i":18,"n":"第十八条","txt":"国家发展改革委已经依法受理公民、法人或者其他组织申请行政复议的，在行政复议期间公民、法人或者其他组织不得向人民法院提起行政诉讼。 公民、法人或者其他组织向人民法院提起行政诉讼，人民法院已经依法受理的，不得申请行政复议。"},{"i":19,"n":"第十九条","txt":"国家发展改革委收到行政复议申请后，应当在5日内进行审查。对符合下列规定的，国家发展改革委应当予以受理： （一）有明确的申请人和符合本办法规定的被申请人； （二）申请人与被申请行政复议的行政行为有利害关系； （三）有具体的行政复议请求和理由； （四）在法定申请期限内提出； （五）属于法定的行政复议范围； （六）属于国家发展改革委的管辖范围； （七）国家发展改革委未受理过该申请人就同一行政行为提出的行政复议申请，并且人民法院未受理过该申请人就同一行政行为提起的行政诉讼。 对不符合前款规定的行政复议申请，国家发展改革委应当在审查期限内决定不予受理并说明理由；不属于国家发展改革委管辖的，还应当在不予受理决定中告知申请人有管辖权的行政复议机关。 申请人以项目建设影响其土地或房屋权益为由，对国家发展改革委审批、核准投资项目的行为申请行政复议的，因其与项目审批、核准行为不具有利害关系，不具有申请行政"},{"i":20,"n":"第二十条","txt":"行政复议申请材料不齐全或者表述不清楚，无法判断行政复议申请是否符合本办法第十九条第一款规定的，国家发展改革委应当自收到申请之日起5日内，一次性载明需要补正的事项书面通知申请人补正。 申请人应当自收到补正通知之日起10日内提交补正材料。有正当理由不能按期补正的，申请人应书面告知理由，国家发展改革委可以延长合理的补正期限。无正当理由逾期不补正的，视为申请人放弃行政复议申请，并记录在案。 国家发展改革委收到补正材料后，依照本办法第十九条规定处理。"},{"i":21,"n":"第二十一条","txt":"国家发展改革委受理行政复议申请后，发现该行政复议申请不符合本办法第十九条第一款规定的，应当决定驳回申请并说明理由。 申请人没有新的事实和理由，就同一事项再次申请行政复议的，告知申请人不再处理，并记录在案。"},{"i":22,"n":"第二十二条","txt":"法律、行政法规规定应当先申请行政复议、对行政复议决定不服再向人民法院提起行政诉讼的，国家发展改革委决定不予受理、驳回申请或者受理后超过行政复议期限不作答复的，公民、法人或者其他组织可以自收到决定书之日起或者行政复议期限届满之日起15日内，依法向人民法院提起行政诉讼。"},{"i":23,"n":"第二十三条","txt":"国家发展改革委受理行政复议申请后，指定行政复议人员适用普通程序或者简易程序进行审理。 行政复议人员对办理行政复议案件过程中知悉的国家秘密、商业秘密和个人隐私，应当予以保密。"},{"i":24,"n":"第二十四条","txt":"因同一行政行为或者同类行政行为发生的行政复议案件，属于国家发展改革委管辖范围，有下列情形之一的，国家发展改革委可以决定合并审理： （一）就同一事实对多个公民、法人或者其他组织分别作出行政行为，公民、法人或者其他组织不服，分别向国家发展改革委申请行政复议； （二）同一被申请人在行政复议期间对申请人作出新的行政行为，申请人不服，向国家发展改革委申请行政复议； （三）国家发展改革委认为合并审理可以提高案件办理质效或减轻申请人负担等其他情形。 决定合并审理的案件，国家发展改革委可以合并作出行政复议决定；合并作出行政复议决定的期限，以最先收到的行政复议申请日期作为起算日期。"},{"i":25,"n":"第二十五条","txt":"行政复议期间有下列情形之一的，行政复议中止，行政复议机构应当及时向有关当事人发送《行政复议中止通知书》： （一）作为申请人的公民死亡，其近亲属尚未确定是否参加行政复议； （二）作为申请人的公民丧失参加行政复议的行为能力，尚未确定法定代理人参加行政复议； （三）作为申请人的公民下落不明； （四）作为申请人的法人或者其他组织终止，尚未确定权利义务承受人； （五）申请人、被申请人因不可抗力或者其他正当理由，不能参加行政复议； （六）依照规定进行调解、和解，申请人和被申请人同意中止； （七）行政复议案件涉及的法律适用问题需要有权机关作出解释或者确认； （八）行政复议案件审理需要以其他案件的审理结果为依据，而其他案件尚未审结； （九）申请人提出对有关规范性文件的附带审查申请； （十）国家发展改革委在对被复议的行政行为进行审查时，认为其依据不合法，需要依法处理； （十一）需要中止行政复议的其他情形"},{"i":26,"n":"第二十六条","txt":"行政复议期间有下列情形之一的，国家发展改革委应当终止复议，行政复议机构应当及时向有关当事人发送《行政复议终止通知书》： （一）申请人撤回行政复议申请，行政复议机构准予撤回； （二）作为申请人的公民死亡，没有近亲属或者其近亲属放弃行政复议权利； （三）作为申请人的法人或者其他组织终止，没有权利义务承受人或者其权利义务承受人放弃行政复议权利； （四）依照本办法第二十五条第一款第一项、第二项、第四项的规定中止行政复议满60日，行政复议中止的原因仍未消除。 依照前款规定终止复议的行政复议申请，应当立卷存档。"},{"i":27,"n":"第二十七条","txt":"行政复议期间行政行为不停止执行；但是，有下列情形之一的，应当停止执行： （一）被申请人认为需要停止执行； （二）国家发展改革委认为需要停止执行的； （三）申请人、第三人申请停止执行，国家发展改革委认为其要求合理，决定停止执行； （四）法律、行政法规、部门规章规定停止执行的其他情形。 决定停止执行的，行政复议机构应当及时书面通知当事人。"},{"i":28,"n":"第二十八条","txt":"被申请人对其作出的行政行为的合法性、适当性负有举证责任。 有下列情形之一的，申请人应当提供证据： （一）认为被申请人不履行法定职责的，提供曾经要求被申请人履行法定职责的证据，但是被申请人应当依职权主动履行法定职责或者申请人因正当理由不能提供的除外； （二）提出行政赔偿请求的，提供受行政行为侵害而造成损害的证据，但是因被申请人原因导致申请人无法举证的，由被申请人承担举证责任； （三）法律、行政法规规定需要申请人提供证据的其他情形。"},{"i":29,"n":"第二十九条","txt":"国家发展改革委审理行政复议案件，有权指派行政复议人员依法向有关单位和个人调查取证，查阅、复制、调取有关文件和资料，向有关人员进行询问。被调查取证的单位和个人应当积极配合行政复议人员的工作，不得拒绝或者阻挠。"},{"i":30,"n":"第三十条","txt":"行政复议期间，被申请人不得自行向申请人和其他有关单位或者个人收集证据；自行收集的证据不作为认定行政行为合法性、适当性的依据。 行政复议期间，申请人或者第三人提出被申请行政复议的行政行为作出时没有提出的理由或者证据的，经行政复议机构同意，被申请人可以补充证据。"},{"i":31,"n":"第三十一条","txt":"行政复议期间，申请人、第三人及其委托代理人可以向国家发展改革委行政复议机构申请查阅、复制被申请人提出的书面答复、作出行政行为的证据、依据和其他有关材料，并按照以下规定办理： （一）向国家发展改革委行政复议机构提出查阅、复制有关材料的书面申请； （二）国家发展改革委行政复议机构经过审查认为不涉及国家秘密、商业秘密、个人隐私或者可能危及国家安全、公共安全、社会稳定的情形的，应当同意申请人、第三人及其委托代理人查阅、复制； （三）申请人、第三人查阅、复制时，应当出示有效身份证件，委托代理人查阅、复制，还应出示有效委托代理授权文件； （四）查阅、复制有关材料应当有复议机构工作人员在场； （五）申请人、第三人及其委托代理人不得涂改、毁损、拆换、取走、增添查阅的上述材料。"},{"i":32,"n":"第三十二条","txt":"适用普通程序审理的行政复议案件，行政复议机构自行政复议申请受理之日起7日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到申请书副本或者申请笔录复印件之日起10日内提出书面答复，并提交作出行政行为的证据、依据和其他有关材料。 被申请人的书面答复应当载明以下内容： （一）被申请人的基本情况； （二）进行答辩的事由，作出行政行为的基本过程和情况； （三）作出行政行为的事实依据和有关证据材料； （四）作出行政行为所依据的法律、行政法规、部门规章和规范性文件的文号、具体条款和内容； （五）作出答复的时间。 书面答复应当加盖被申请人的单位公章；被申请人为国家发展改革委的，加盖作出具体行政行为的机构印章。"},{"i":33,"n":"第三十三条","txt":"适用普通程序审理的行政复议案件，行政复议机构应当当面或者通过互联网、电话等方式听取当事人的意见，并将听取的意见记录在案。因当事人原因不能听取意见的，可以书面审理。"},{"i":34,"n":"第三十四条","txt":"审理重大、疑难、复杂的行政复议案件，行政复议机构应当组织听证。 行政复议机构认为有必要听证，或者申请人请求听证的，行政复议机构可以组织听证。 听证由一名行政复议人员任主持人，两名以上行政复议人员任听证员，一名记录员制作听证笔录。"},{"i":35,"n":"第三十五条","txt":"行政复议机构组织听证的，应当于举行听证的5日前将听证的时间、地点和拟听证事项书面通知当事人。 申请人无正当理由拒不参加听证的，视为放弃听证权利。"},{"i":36,"n":"第三十六条","txt":"国家发展改革委审理下列行政复议案件，认为事实清楚、权利义务关系明确、争议不大的，可以适用简易程序： （一）被申请行政复议的行政行为是当场作出； （二）被申请行政复议的行政行为是警告或者通报批评； （三）案件涉及款额三千元以下； （四）属于政府信息公开案件。 除前款规定以外的行政复议案件，当事人各方同意适用简易程序的，可以适用简易程序。征求当事人意见情况应当立卷存档。"},{"i":37,"n":"第三十七条","txt":"适用简易程序审理的行政复议案件，行政复议机构应当自受理行政复议申请之日起3日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到行政复议申请书副本或者行政复议申请笔录复印件之日起5日内，提出书面答复，并提交作出行政行为的证据、依据和其他有关材料。 适用简易程序审理的行政复议案件，可以书面审理。"},{"i":38,"n":"第三十八条","txt":"适用简易程序审理的行政复议案件，行政复议机构认为不宜适用简易程序的，经行政复议机构的负责人批准，可以转为普通程序审理。"},{"i":39,"n":"第三十九条","txt":"被申请人不按照本办法第三十二条和第三十七条规定提出书面答复、提交作出行政行为的证据、依据和其他有关材料的，视为该行政行为没有证据、依据。"},{"i":40,"n":"第四十条","txt":"申请人依照本办法第六条提出对有关规范性文件的附带审查申请，国家发展改革委有权处理的，应当在30日内依法处理；无权处理的，应当在7日内转送有权处理的行政机关依法处理。"},{"i":41,"n":"第四十一条","txt":"国家发展改革委在对被申请人作出的行政行为进行审查时，认为其依据不合法，有权处理的，应当在30日内依法处理；无权处理的，应当在7日内转送有权处理的国家机关依法处理。"},{"i":42,"n":"第四十二条","txt":"国家发展改革委有权处理有关规范性文件或者依据的，中止行政复议案件的审理。行政复议机构自行政复议中止之日起3日内，书面通知规范性文件或者依据的制定机构就相关条款的合法性提出书面答复。制定机构应当自收到书面通知之日起10日内提交书面答复及相关材料，并根据行政复议机构要求当面说明理由。 国家发展改革委认为相关条款合法的，在行政复议决定书中一并告知；认为相关条款超越权限或者违反上位法的，决定停止该条款的执行，并责令纠正。"},{"i":43,"n":"第四十三条","txt":"国家发展改革委审理行政复议案件，由行政复议机构对被申请人作出的行政行为进行审查，按照《行政复议法》第六十三条至七十二条有关规定提出审理意见，经国家发展改革委负责人同意，依法作出行政复议决定。 经过听证的行政复议案件，国家发展改革委应当根据听证笔录、审查认定的事实和证据，依法作出行政复议决定。"},{"i":44,"n":"第四十四条","txt":"适用普通程序审理的行政复议案件，国家发展改革委应当自受理申请之日起60日内作出行政复议决定；但是法律规定的行政复议期限少于60日的除外。情况复杂，不能在规定期限内作出行政复议决定的，经行政复议机构的负责人批准，可以适当延长，并书面告知申请人和被申请人，延长期限最多不超过30日。 适用简易程序审理的行政复议案件，国家发展改革委应当自受理申请之日起30日内作出行政复议决定。"},{"i":45,"n":"第四十五条","txt":"当事人经调解达成协议的，国家发展改革委应当制作行政复议调解书，经各方当事人签字或者签章，并加盖国家发展改革委行政复议专用章，即具有法律效力。 调解未达成协议或者调解书生效前一方反悔的，国家发展改革委应当依法审查或者及时作出行政复议决定。"},{"i":46,"n":"第四十六条","txt":"当事人在行政复议决定作出前可以自愿达成和解，和解内容不得损害国家利益、社会公共利益和他人合法权益，不得违反法律、法规的强制性规定。当事人达成和解后，由申请人向行政复议机构撤回行政复议申请。 行政复议机构准予撤回行政复议申请、决定终止行政复议的，申请人不得再以同一事实和理由提出行政复议申请。但是，申请人能够证明撤回行政复议申请违背其真实意愿的除外。"},{"i":47,"n":"第四十七条","txt":"国家发展改革委作出行政复议决定，应当制作行政复议决定书，并加盖行政复议专用章。 行政复议决定书一经送达，即发生法律效力。"},{"i":48,"n":"第四十八条","txt":"国家发展改革委在办理行政复议案件过程中，发现被申请人或者其他下级行政机关的有关行政行为违法或者不当的，可以向其制发行政复议意见书。有关机关应当自收到行政复议意见书之日起60日内，将纠正相关违法或者不当行政行为的情况报送国家发展改革委。 行政复议期间行政复议机构发现法律、法规、规章、规范性文件实施中带有普遍性的问题，可以制作行政复议建议书，向有关机关提出完善制度和改进行政执法的建议。"},{"i":49,"n":"第四十九条","txt":"被申请人应当履行行政复议决定书、调解书、意见书。 被申请人不履行或者无正当理由拖延履行行政复议决定书、调解书、意见书的，国家发展改革委应当责令其限期履行，并可以约谈被申请人的有关负责人或者予以通报批评。"},{"i":50,"n":"第五十条","txt":"申请人、第三人逾期不起诉又不履行行政复议决定书、调解书的，或者不履行最终裁决的行政复议决定的，按照下列规定分别处理： （一）维持行政行为的行政复议决定书，由作出行政行为的行政机关依法强制执行，或者申请人民法院强制执行； （二）变更行政行为的行政复议决定书，由国家发展改革委依法强制执行，或者申请人民法院强制执行； （三）行政复议调解书，由国家发展改革委依法强制执行，或者申请人民法院强制执行。"},{"i":51,"n":"第五十一条","txt":"国家发展改革委作出行政复议决定后，申请人以外的公民、法人或者其他组织就同一行政行为或者同样行政行为申请行政复议且符合受理条件的，国家发展改革委在受理后根据发生法律效力的行政复议决定的内容，直接作出行政复议决定。"},{"i":52,"n":"第五十二条","txt":"行政复议机关不依照本法规定履行行政复议职责，对有关责任人员依法给予政务处分。行政复议机关工作人员在行政复议活动中，徇私舞弊或者有其他渎职、失职行为的，依法给予政务处分，构成犯罪的，依法追究刑事责任。 被申请人违反行政复议法律法规规定，不提出书面答复或者不提交作出行政行为的证据、依据和其他有关材料，或者阻挠、变相阻挠公民、法人或者其他组织依法申请行政复议，进行报复陷害的，或者不履行或者无正当理由拖延履行行政复议决定书、调解书、意见书的，对有关责任人员依法给予政务处分，构成犯罪的，依法追究刑事责任。 拒绝、阻挠行政复议人员调查取证，故意扰乱行政复议工作秩序的，依法给予处分、治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"行政复议期间的计算和行政复议文书的送达，《行政复议法》没有规定的，依照民事诉讼法关于期间、送达的规定执行。 本办法关于行政复议期间有关“3日”、“5日”、“7日”、“10日”的规定是指工作日，不含法定休假日和当日。"},{"i":54,"n":"第五十四条","txt":"外国人、无国籍人、外国组织在中华人民共和国境内向国家发展改革委申请行政复议，适用本办法。"},{"i":55,"n":"第五十五条","txt":"本办法由国家发展改革委负责解释，自2024年2月1日起施行，原《国家发展和改革委员会行政复议实施办法》（国家发展改革委第46号令）同步废止。"}],"guojiafazhangaigeweiqiyejishuzhongxinrendingguanli689532":[{"i":1,"n":"第一条","txt":"为深入实施创新驱动发展战略，引导和支持企业增强技术创新能力，进一步强化企业科技创新主体地位，推进科技创新和产业创新深度融合，培育发展新质生产力，规范国家发展改革委企业技术中心（以下简称“企业技术中心”）管理，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称企业技术中心，是指企业根据市场竞争需要设立的技术研发与创新机构，负责制定企业科技创新规划、开展科学研究和产业技术研发、创造运用知识产权、建立技术标准体系、凝聚培养创新人才、构建协同创新网络、推进科技创新全过程实施。"},{"i":3,"n":"第三条","txt":"国家鼓励和支持企业建立技术中心，发挥企业在科技创新中的主体作用，建立健全企业主导产业技术创新的体制机制。要坚持党的领导，坚持担国家责、做国家事，根据创新驱动发展要求和高质量发展需要，对创新能力强、体制机制好、示范作用强、符合条件的企业技术中心予以认定，给予政策支持，鼓励开展重大产业技术攻关，带动行业高质量发展。"},{"i":4,"n":"第四条","txt":"国家发展改革委商财政部、海关总署、税务总局指导协调企业技术中心相关工作。国家发展改革委牵头开展企业技术中心的认定与运行评价。 各省、自治区、直辖市及计划单列市、新疆生产建设兵团发展改革部门或地方人民政府指定的部门商同级管理部门，负责企业技术中心的申报、管理等事项。"},{"i":5,"n":"第五条","txt":"企业技术中心的认定，坚持总量控制、优中选优，原则上每两年进行一次。地方政府主管部门根据国家发展改革委通知要求，报送申请材料。"},{"i":6,"n":"第六条","txt":"企业技术中心应当具备以下基本条件： （一）企业在行业中具有显著的发展优势和竞争优势，具有行业领先的科技创新能力和水平； （二）企业具有较好的科技创新机制，企业技术中心组织体系健全，具有较为完备的科技成果转化机制、产学研用协同机制，创新效率和效益显著； （三）企业具有开展重大创新活动的组织机构和人员队伍，有较高的研究开发投入，拥有技术水平高、实践经验丰富的技术带头人，具有比较完善的研究、开发、试验条件，必须全部满足以下基本条件：（1）年度研究与试验发展经费支出额不低于3000万元；（2）专职研究与试验发展人员数不少于150人；（3）技术开发仪器设备原值不低于3000万元； （四）具有较好的技术积累，重视前沿技术开发。 企业在申请受理截止日期前三年内，不得存在下列情况： （一）因违反海关法及有关法律、行政法规，构成走私行为，受到刑事、行政处罚，或因严重违反海关监管规定受到行政处罚； （二）"},{"i":7,"n":"第七条","txt":"地方政府主管部门会同同级管理部门，根据本办法及当年国家发展改革委发布的通知，推荐符合条件的企业技术中心，并将推荐企业技术中心名单及其申请材料（一式两份）报送国家发展改革委。 申请材料主要包括企业技术中心申请报告、评价表及必要的证明材料，以及地方政府主管部门关于所推荐企业技术中心是否存在司法、行政机关认定严重违法失信行为的说明。"},{"i":8,"n":"第八条","txt":"母公司技术中心已是企业技术中心的，地方政府主管部门不得再推荐其下属子公司申请企业技术中心。但从事业务领域与母公司不同的子公司，可推荐其申请母公司企业技术中心分中心。 子公司已是企业技术中心的，地方政府主管部门在推荐其母公司申请企业技术中心时，应在推荐意见中明确提出将其子公司企业技术中心调整为分中心或撤销的意见。企业技术中心分中心的申请程序和要求与企业技术中心相同。"},{"i":9,"n":"第九条","txt":"国家发展改革委依据企业技术中心认定评价工作指南，委托第三方机构组织专家对地方政府主管部门推荐的企业技术中心申请材料进行评估论证。 国家发展改革委商财政部、海关总署、税务总局，根据专家评审意见以及国家产业政策等综合评估，确定认定复核结果。"},{"i":10,"n":"第十条","txt":"国家发展改革委商财政部、海关总署、税务总局，在受理地方政府主管部门申报材料后及时完成认定工作，向地方政府主管部门及同级管理部门通报认定结果。"},{"i":11,"n":"第十一条","txt":"国家发展改革委商财政部、海关总署、税务总局，原则上每两年组织一次企业技术中心运行评价，并于评价年度下发评价通知。 地方政府主管部门对企业技术中心评价材料真实性出具意见，并按照通知要求将评价材料报送国家发展改革委。 评价材料主要包括企业技术中心工作总结、评价表及必要的证明材料，以及地方政府主管部门关于企业技术中心是否存在司法、行政机关认定严重违法失信行为的说明。"},{"i":12,"n":"第十二条","txt":"国家发展改革委委托第三方机构，依据评价指标体系，对地方政府主管部门报送的评价材料进行评价，并形成评价结果和评价报告。"},{"i":13,"n":"第十三条","txt":"评价结果分为优秀、良好、基本合格和不合格： （一）评价得分90分及以上为优秀； （二）评价得分65分至90分（不含90分）为良好； （三）评价得分60分至65分（不含65分）为基本合格； （四）评价得分低于60分为不合格。"},{"i":14,"n":"第十四条","txt":"国家发展改革委商财政部、海关总署、税务总局对评价结果进行确认。国家发展改革委在受理评价材料之后及时完成评价工作，向地方政府主管部门通报评价结果。"},{"i":15,"n":"第十五条","txt":"国家发展改革委鼓励企业技术中心聚焦国家战略需求和产业创新发展需要开展技术研发，结合国家产业技术攻关、示范应用项目实施，对企业技术中心予以支持。"},{"i":16,"n":"第十六条","txt":"国家发展改革委积极支持企业技术中心的科技成果转化，通过国家创业投资引导基金等政府投资基金加强资金保障。"},{"i":17,"n":"第十七条","txt":"国家发展改革委结合国家产业技术工程化中心、国家新兴产业创新中心等国家级科技创新平台基地组建，对评价为优秀的企业技术中心予以支持。"},{"i":18,"n":"第十八条","txt":"国家发展改革委支持符合条件的企业技术中心合理申请新增外债用于发展业务，直接向国家发展改革委提出申请，无需地方出具支持性意见。"},{"i":19,"n":"第十九条","txt":"国家发展改革委支持企业技术中心强化人才队伍建设，鼓励支持申报各类人才专项。"},{"i":20,"n":"第二十条","txt":"鼓励地方结合企业技术中心建设运行需求，在资金、土地、科研、人才等方面给予必要支持。"},{"i":21,"n":"第二十一条","txt":"地方政府主管部门应随当年企业技术中心认定或评价工作，将企业技术中心所在企业发生更名、重组等变更情况报送国家发展改革委，同时抄送地方同级管理部门。"},{"i":22,"n":"第二十二条","txt":"国家发展改革委商财政部、海关总署、税务总局，对地方政府主管部门报送的企业变更情况进行确认。"},{"i":23,"n":"第二十三条","txt":"母公司技术中心已认定为企业技术中心的，其子公司原有企业技术中心的资格应予调整。其中，从事业务领域与母公司不同的，可调整为其母公司企业技术中心分中心；业务领域与母公司一致的，取消其企业技术中心资格。 地方政府主管部门推荐母公司申请企业技术中心时，没有提出对其子公司企业技术中心调整意见的，视同母公司与子公司业务领域相同。"},{"i":24,"n":"第二十四条","txt":"地方政府主管部门报送的企业材料和数据应当真实可靠。企业提供虚假材料和数据的行为，经核实，将纳入全国信用信息共享平台。"},{"i":25,"n":"第二十五条","txt":"有下列情况之一的，撤销企业技术中心资格： （一）运行评价不合格； （二）逾期未报送评价材料； （三）提供虚假材料和数据； （四）主要由于技术原因发生重大质量、安全事故； （五）因违反海关法及有关法律、行政法规，构成走私行为，受到刑事、行政处罚，或因严重违反海关监管规定受到行政处罚； （六）因违反税收征管法及有关法律、行政法规，被确定为重大税收违法失信主体； （七）司法、行政机关认定的其他严重违法失信行为； （八）企业被依法终止。"},{"i":26,"n":"第二十六条","txt":"因本办法第二十五条第（一）、（二）项所列原因被撤销企业技术中心资格的，自撤销之日起，地方政府主管部门两年内不得再次推荐该企业。 因本办法第二十五条第（三）～（七）项所列原因被撤销企业技术中心资格的，自撤销之日起，地方政府主管部门三年内不得再次推荐该企业。 地方政府主管部门负责指导和督促评价基本合格的企业技术中心改进工作。"},{"i":27,"n":"第二十七条","txt":"各直属海关对推荐申请企业技术中心的企业和企业技术中心所在企业是否存在本办法第六条第二款第（一）项、第二十五条第（五）项所列情况进行确认，具体要求由海关总署另行确定。 税务机关对推荐申请企业技术中心的企业和企业技术中心所在企业是否存在本办法第六条第二款第（二）项、第二十五条第（六）项情况进行确认，具体要求由税务总局另行确定。"},{"i":28,"n":"第二十八条","txt":"国家发展改革委商财政部、海关总署、税务总局，向地方政府主管部门通报企业技术中心撤销结果。"},{"i":29,"n":"第二十九条","txt":"地方政府主管部门组织企业技术中心定期向国家发展改革委报送科技创新和关键指标进展（每年4月底前报送上一年度，9月底前报送当年上半年），企业技术中心有重大科技创新成果时，应及时报送。"},{"i":30,"n":"第三十条","txt":"各地方政府主管部门可参考本办法，结合本地实际，在职责范围内依法制定相应政策，支持企业技术中心建设。"},{"i":31,"n":"第三十一条","txt":"依据《中华人民共和国政府信息公开条例》，企业技术中心名单等信息向社会公开。企业技术中心的认定、运行评价等，逐步实现网上办理。"},{"i":32,"n":"第三十二条","txt":"本办法自2026年2月1日起施行，《国家企业技术中心认定管理办法》（国家发展改革委、科技部、财政部、海关总署、国家税务总局2016年第34号令）同时废止。本办法涉及的申请材料、评价材料和评价指标体系等内容和要求，由国家发展改革委商财政部、海关总署、税务总局另行发布并适时调整。"},{"i":33,"n":"第三十三条","txt":"本办法由国家发展改革委负责解释。"}],"guojiagongchengyanjiuzhongxinguanlibanfa":[{"i":1,"n":"第一条","txt":"为深入贯彻落实《中共中央国务院关于深化体制机制改革加快实施创新驱动发展战略的若干意见》（中发〔2015〕8号）《关于深化中央财政科技计划（专项、基金等）管理改革的方案》（国发〔2014〕64号）等决策部署，规范和加强国家工程研究中心建设及运行管理，加快提高创新能力，根据《科学技术进步法》《促进科技成果转化法》等有关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于对国家工程研究中心（以下简称“工程中心”）的申报、组建、评价等管理行为。 本办法所称工程中心，是指国家发展改革委根据建设现代化经济体系的重大战略需求，以服务国家重大战略任务和重点工程实施为目标，组织具有较强研究开发和综合实力的企业、科研单位、高等院校等建设的研究开发实体。 工程中心是国家创新体系的重要组成部分。"},{"i":3,"n":"第三条","txt":"建设工程中心旨在坚定实施创新驱动发展战略，服务经济社会发展，支撑关键核心技术研发，围绕产业链部署创新链，围绕创新链布局产业链，提升产业链供应链稳定性和竞争力，推动经济高质量发展。工程中心以国家和行业需求为出发点，通过建立工程化研究、验证设施和有利于技术创新、成果转化的机制，培育、提高创新能力，搭建产业发展与科技创新之间的桥梁，推动产业关键共性技术、前沿引领技术、现代工程技术、颠覆性技术创新，加快科研成果向现实生产力转化，促进重大科研成果转化应用以及产业基础高级化和产业链现代化。工程中心建设的主要目的是： （一）坚持目标导向，着眼加快重大科技成果工程化、产业化，布局建设开放服务的创新平台，为各类创新主体开展实验室技术熟化、工程化放大和可靠性验证等活动提供基础条件，促进提高科技成果转化能力和转化效率; （二）坚持问题导向，瞄准国家战略任务和重点工程实施中的重大技术难题，以及保产业链供应链稳"},{"i":4,"n":"第四条","txt":"工程中心的主要任务包括： （一）面向国家重大战略任务和重点工程建设需求，开展关键技术攻关和实验研究; （二）以市场为导向，研判产业发展态势及需求，开展具有重要应用价值的重大科技成果的工程化和系统集成，研制重大装备样机及其关键部件; （三）推动技术转移和扩散，持续不断地为规模化生产提供成熟的先进技术、工艺及其技术产品和装备; （四）积极开展国际交流合作，为企业应用国际先进技术、制定采用国际标准、推动国际技术转移扩散等提供支撑服务; （五）提供工程技术验证和咨询服务，研究产业技术标准; （六）为行业培养工程技术研究与管理的高层次人才。"},{"i":5,"n":"第五条","txt":"工程中心的责任与义务主要包括： （一）根据组建方案及相关要求，实现设定的研究开发和成果转化目标，持续推动产业技术进步和创新能力提升; （二）主动组织或参与产业关键核心技术、共性技术开发，并为行业提供高水平技术开发、科技成果工程化试验验证环境; （三）承担国家和行业下达的科技开发及工程化研究任务，并依据合同按时完成任务; （四）通过市场机制向行业转移和扩散承担国家和行业任务所形成的技术成果，起到产业发展与科技创新之间的桥梁作用。"},{"i":6,"n":"第六条","txt":"国家发展改革委负责指导协调工程中心建设及运行管理相关工作，主要负责： （一）会同国务院有关部门制定支持工程中心建设的有关政策，指导工程中心的建设和发展; （二）组织论证工程中心组建方案，对符合条件的支持启动建设;对完成筹建任务的工程中心，予以核定并进行监督管理; （三）批复工程中心创新能力建设项目，下达中央预算内投资计划; （四）组织工程中心运行评价，会同国务院有关部门落实工程中心建设后补助资金和相关进口税收优惠政策。"},{"i":7,"n":"第七条","txt":"国务院有关部门，各省、自治区、直辖市、计划单列市及新疆生产建设兵团发展改革部门，计划单列中央企业（集团）是工程中心建设的主管部门，主要负责： （一）组织所属工程中心创新能力建设项目的申报和管理，督促、协调落实建设条件; （二）组织工程中心组建任务、创新能力建设项目验收，以及工程中心运行的监督管理; （三）根据国家有关规定建立相应的监督管理制度，配合有关部门做好审计、监察和检查等各项工作; （四）按规定给予工程中心资金和政策支持。"},{"i":8,"n":"第八条","txt":"工程中心实施主体单位主要负责： （一）根据组建方案及有关文件要求，推进工程中心组建; （二）落实工程中心建设与运行条件，筹措工程中心建设和运行经费，保障工程中心顺利建设和正常运行; （三）承担国家有关部门委托的研发任务，保证工程中心的开放运行和共用共享，为国家相关重大战略任务、重点工程提供研发和试验条件; （四）按照有关要求向主管部门报送建设项目实施情况和工程中心运行情况。"},{"i":9,"n":"第九条","txt":"国家发展改革委根据有关重大战略部署、重大规划实施、重大工程建设、重点区域创新发展等需要，遵循“少而精”的原则，择优择需部署建设工程中心。国家发展改革委会同有关方面研究提出工程中心建设领域布局，并采取适当形式发布通知。"},{"i":10,"n":"第十条","txt":"拟申请工程中心组建的实施主体单位（以下简称“申报单位”）应具备以下条件： （一）符合国家发展改革委发布的建设领域及相关要求; （二）具有一批有待工程化开发、拥有自主知识产权和良好市场前景、处于国内领先水平的重大科技成果，具有国内一流水平的研究开发和技术集成能力及相应的人才队伍; （三）具有以市场为导向，将重大科技成果向规模生产转化的工程化研究验证环境和能力; （四）具有通过市场机制实现技术转移和扩散，促进科技成果产业化，形成良性循环的自我发展能力; （五）具有对科技成果产业化能力，条件允许的还应具有工程设计、评估及建设的咨询与服务能力; （六）具有完善的人才激励、成果转化激励和知识产权管理等管理制度; （七）未因严重违法失信行为被司法、行政机关依法列入联合惩戒对象名单; （八）符合国家其他相关规定。"},{"i":11,"n":"第十一条","txt":"工程中心一般应采用法人形式组建和运行。对于采取非法人形式组建的工程中心，需要与依托单位在人、财、物的管理上保持清晰边界，评价指标数据能够独立核算、有据可查。"},{"i":12,"n":"第十二条","txt":"鼓励相关领域的优势企业、科研单位、高等院校、社会投资机构组建创新联合体，共同申请组建工程中心。鼓励地方和部门层面的工程中心优先申报。"},{"i":13,"n":"第十三条","txt":"申报单位按照国家发展改革委通知要求，结合自身优势和具体情况，编制组建方案并向主管部门提出申请。"},{"i":14,"n":"第十四条","txt":"主管部门采取适当形式对工程中心组建方案进行评估论证，将符合条件的组建方案推荐给国家发展改革委。"},{"i":15,"n":"第十五条","txt":"国家发展改革委根据主管部门推荐，委托第三方机构或组织专家对工程中心组建方案进行论证，重点包括组建工程中心的必要性和紧迫性、申报单位的条件、发展目标及实现可能性等。"},{"i":16,"n":"第十六条","txt":"国家发展改革委会同相关部门，根据论证意见，综合研究后，择优确定拟启动组建的工程中心，并通知相关主管部门。"},{"i":17,"n":"第十七条","txt":"国家发展改革委同意启动组建工作后，工程中心进入筹建期，可暂以“××国家工程研究中心（筹）”的名义开展工作，实施组建方案中确定的各项任务。"},{"i":18,"n":"第十八条","txt":"主管部门根据国家有关规定建立相应监督管理制度，对处于筹建期的工程中心加强监督管理，配合有关部门做好审计、监察和检查等各项工作。"},{"i":19,"n":"第十九条","txt":"工程中心的筹建期一般不超过三年。达到组建方案明确的筹建期发展目标后，申报单位应编制筹建期总结报告、填写工程中心评价表并附相应证明材料，向主管部门提出正式确认为工程中心的申请。"},{"i":20,"n":"第二十条","txt":"主管部门对申请确认的工程中心应按照工程中心评价指标体系进行评价;对于评价结果中等及以上的工程中心，可向国家发展改革委提出确认申请。"},{"i":21,"n":"第二十一条","txt":"对不能按期达到组建目标、完成组建任务的工程中心，在筹建期结束前，可由主管部门向国家发展改革委提交延长筹建期的书面申请，说明原因、拟采取的措施和计划完成日期。原则上，延长筹建期的时限不能超过一年且只能申请一次。 筹建期或延长期满未完成组建任务的，取消确认为国家工程中心的资格，且不得再以“××国家工程研究中心（筹）”的名义开展工作，由主管部门依照本办法相关规定对后续事宜作出处理。"},{"i":22,"n":"第二十二条","txt":"国家发展改革委会同财政部、海关总署、税务总局对主管部门申请确认的工程中心及总结报告、评价结果及证明材料等进行复核，对符合条件的正式确认为“国家工程研究中心”，国家发展改革委函告海关总署、税务总局并抄送财政部;对以非法人形式运行的工程中心，将其依托单位同时函告海关总署、税务总局并抄报财政部，纳入国家科技创新基地序列进行管理。"},{"i":23,"n":"第二十三条","txt":"工程中心实行优胜劣汰、动态调整的运行评价制度。国家发展改革委牵头，原则上每三年对经正式确认的工程中心进行一次集中评价。在评价年度完成确认的工程中心，可不参加当年的集中评价。"},{"i":24,"n":"第二十四条","txt":"国家发展改革委制定发布《国家工程研究中心评价工作指南》，明确评价指标体系、数据采集规范、材料报送要求等事项。"},{"i":25,"n":"第二十五条","txt":"运行评价程序为： （一）数据采集。工程中心应于评价年度5月1日前将评价材料报主管部门。评价材料包括：工程中心年度工作报告、工程中心评价数据表及其相关附件和证明材料。 （二）数据初审。主管部门对工程中心报送的评价材料进行核实，并对材料完整性、真实性出具意见，于评价年度的5月31日前将评价材料报送国家发展改革委。 （三）数据核实。国家发展改革委委托第三方机构对工程中心报送的评价材料及相关情况进行核实，按照评价工作指南的规定进行计算、分析，形成评价结果。 （四）国家发展改革委会同财政部、海关总署、税务总局对评价结果进行确认，并向主管部门通报评价结果。"},{"i":26,"n":"第二十六条","txt":"工程中心评价结果分为优秀、良好、中等、基本合格和不合格。"},{"i":27,"n":"第二十七条","txt":"工程中心应当定期填报免税进口科技开发用品统计表，于每年4月1日前报送省级财政、税务部门，由各省级财政、税务部门汇总后于每年4月15日前报送财政部、税务总局。"},{"i":28,"n":"第二十八条","txt":"进入筹建期的工程中心，根据建设需要，可提出创新能力建设项目。国家发展改革委按照《中央预算内投资补助和贴息项目管理办法》（国家发展改革委令第45号）、《国家发展改革委关于规范中央预算内投资资金安排方式及项目管理的通知》（发改投资规〔2020〕518号）及《高技术产业发展项目中央预算内投资（补助）暂行管理办法》（发改高技规〔2016〕2514号）等国家高技术产业发展项目管理规定予以研究支持。"},{"i":29,"n":"第二十九条","txt":"国家发展改革委依据运行评价结果，根据《中央财政科技计划（专项、基金等）后补助管理办法》（财教〔2019〕226号）规定，组织工程中心申请国家后补助资金支持。"},{"i":30,"n":"第三十条","txt":"通过正式确认的工程中心，自确认文件印发之日起，进口科技开发用品按照国家相关进口税收政策执行。"},{"i":31,"n":"第三十一条","txt":"国家鼓励和支持工程中心及其分支机构在海关综合保税区建设发展，并享受相关政策支持。"},{"i":32,"n":"第三十二条","txt":"工程中心需要对组建方案中明确的目标任务作重大调整的，应及时向主管部门报告： （一）对于不影响实现工程中心功能和任务的调整，由主管部门负责审核，报国家发展改革委备案; （二）对于发生重大变化，影响工程中心功能实现的，由主管部门提出调整建议，报国家发展改革委审核。"},{"i":33,"n":"第三十三条","txt":"主管部门应将工程中心建设单位或依托单位发生更名、重组等变更情况及时报送国家发展改革委。国家发展改革委对主管部门报送的工程中心建设单位或依托单位变更情况进行确认并函告海关总署。其中，对经确认取消工程中心资格的，自变更之日起，停止享受国家支持科技创新进口税收政策。"},{"i":34,"n":"第三十四条","txt":"主管部门应对工程中心报送的材料和数据承担核实责任，确保真实可靠。工程中心提供虚假材料和数据的行为，一经核实，记入其实施主体单位的信用记录，并纳入全国信用信息共享平台。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一的，国家发展改革委会同财政部、海关总署、税务总局，撤销其工程中心称号： （一）运行评价结果不合格的; （二）连续两次运行评价结果均为基本合格的; （三）逾期未报送评价材料的; （四）提供虚假材料和数据的; （五）主要由于技术原因发生重大质量、安全事故的; （六）因违反《海关法》及有关法律、行政法规，构成走私行为，受到刑事、行政处罚，或因严重违反海关监管规定受到行政处罚的; （七）因违反《税收征收管理法》及有关法律、行政法规，构成偷税、骗取出口退税等严重税收违法行为的; （八）因严重违法失信行为被司法、行政机关依法列入联合惩戒对象名单的; （九）工程中心被依法终止的。"},{"i":36,"n":"第三十六条","txt":"国家发展改革委商有关部门后向主管部门通报工程中心撤销情况，并函送海关总署、税务总局并抄送财政部。被撤销的工程中心，自通报文件印发之日起停止享受国家相关进口税收政策。"},{"i":37,"n":"第三十七条","txt":"国家工程研究中心统一命名为：“××国家工程研究中心”，英文名称为：“National Engineering Research Center of ××”。"},{"i":38,"n":"第三十八条","txt":"有关地方和国务院有关部门可参考本办法制定本地区、本部门工程研究中心管理办法。 国家地方联合工程研究中心和工程实验室参照本办法进行管理，不享受本办法规定的支持政策。"},{"i":39,"n":"第三十九条","txt":"本办法由国家发展改革委负责解释，自2020年9月1日起施行，有效期至2025年9月1日。《国家工程研究中心管理办法》（国家发展改革委令第52号）和《国家工程实验室管理办法（试行）》（国家发展改革委令第54号）同时废止。"}],"guojiawuzichubeicangkuanquanbaoweibanfa":[{"i":1,"n":"第一条","txt":"为加强和规范国家物资储备仓库的安全保卫工作，保障国家储备物资、储备仓库和职工群众的生命及财产安全，依据国家有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于国家物资储备系统所属国家物资储备仓库(以下简称储备仓库)。"},{"i":3,"n":"第三条","txt":"储备仓库及其附属设施属安全保卫重点单位和重要部位，任何组织和个人不得以任何方式侵害其安全。"},{"i":4,"n":"第四条","txt":"储备仓库内部安全保卫工作贯彻“预防为主、单位负责、突出重点、保障安全”的方针。 储备仓库内部安全保卫工作应当坚持以人为本，保护职工人身安全。各级单位不得以任何理由忽视职工人身安全。"},{"i":5,"n":"第五条","txt":"储备仓库安全保卫工作的任务是：以防火灾、防抢劫、防盗窃、防爆炸、防破坏、防恐怖活动和突发事件、防治安灾害事故为重点，加强重要部位的守卫和控制，建立健全安全保卫工作制度，落实治安防范措施，严防发生违法犯罪和其他治安问题，确保国家储备物资和储备仓库的安全。"},{"i":6,"n":"第六条","txt":"储备仓库安全保卫工作实行地方政府和上级主管部门双重领导、以地方政府领导为主的体制，接受当地公安机关的指导、监督。国家发展和改革委员会国家物资储备局(以下简称国家局)对系统的安全保卫工作进行指导、监督。储备物资管理局、办事处(以下简称管理局)对所辖储备仓库安全保卫工作进行管理和监督。"},{"i":7,"n":"第七条","txt":"储备仓库安全保卫工作实行法定代表人负责制。法定代表人是安全保卫工作的第一责任人，通过建立安全保卫责任制，将安全保卫责任落实到各个部门、岗位和人员。"},{"i":8,"n":"第八条","txt":"安全保卫工作第一责任人履行以下职责： (一)贯彻执行国家有关安全保卫工作的法律、法规和规章; (二)组织制定和落实安全保卫工作的制度和计划; (三)组建保卫机构，配备保卫人员; (四)落实安全保卫工作所需经费和设备; (五)布置、检查、考核安全保卫工作; (六)向地方政府和上级主管部门汇报安全保卫工作情况，提出工作建议; (七)处理内部安全保卫工作的重大问题。 安全保卫工作第一责任人可以指定其他负责人分管安全保卫工作。"},{"i":9,"n":"第九条","txt":"储备仓库应当在地方政府的统一组织下，积极会同政府有关部门与周边村镇、街道、企业、事业单位成立保卫工作联防组织。"},{"i":10,"n":"第十条","txt":"储备仓库应当严格执行国家有关易燃、易爆、危险化学品管理及治安、消防等法律法规和技术标准。 储备仓库应当开展法制和安全防范宣传教育，增强全体人员的法制观念和防范意识。"},{"i":11,"n":"第十一条","txt":"储备仓库应当及时消除不安全隐患;化解不安定因素;在当地公安机关指导下制定保卫工作方案和可能发生的恐怖破坏活动及重大突发事件的处置预案，并定期演练;重要部位应当设置安全技术防范设施。 储备仓库新建、扩建、改建项目的安全防护、安全技术防范和消防设施应当与主体工程同时规划、设计、施工，同时验收交付使用。"},{"i":12,"n":"第十二条","txt":"管理局和储备仓库应当设立值班室，24小时值班。对发生的刑事案件、治安案件、治安灾害事故、恐怖破坏活动、突发事件以及存在的重大不安定因素、重大治安隐患，应当及时报告地方政府、公安机关和上级主管部门，并采取相应的救援、控制和处置措施。地方政府、公安机关和上级主管部门接到报告后应当及时予以处理。"},{"i":13,"n":"第十三条","txt":"储备仓库应当严格落实安全检查和隐患整改制度，及时排除隐患。"},{"i":14,"n":"第十四条","txt":"储备仓库应当设置专职保卫机构，配备专职保卫人员，建立治安保卫委员会。"},{"i":15,"n":"第十五条","txt":"保卫人员应当符合国家规定的条件。保卫人员上岗前应当接受有关法律知识和安全保卫业务、技能以及相关专业知识的培训、考核，在岗期间还应当定期接受安全保卫业务培训。 保卫机构的设置和保卫人员的配备、变更情况应当报当地公安机关备案。 保卫机构负责人的任免应当征求上级主管部门和当地公安机关的意见。"},{"i":16,"n":"第十六条","txt":"保卫机构和保卫人员应当遵守法纪、办事公正、讲究文明，严格履行安全保卫职责，积极配合公安机关开展工作。 任何单位和个人不得妨碍保卫机构和保卫人员依法履行职责。保卫机构和保卫人员有权拒绝违反法律规定的指令。"},{"i":17,"n":"第十七条","txt":"储备仓库应当为保卫机构配备安全防护器材、交通和通信工具，按规定为保卫人员发放各类津贴，办理有关保险。 保卫人员因履行职责负伤的，单位应当负责医疗费用;致残或死亡的，依照国家有关工伤保险、评定伤残、评定英烈的规定给予相应的待遇。"},{"i":18,"n":"第十八条","txt":"储备仓库应当组织专职守卫力量开展守卫工作。符合武警部队内卫执勤任务范围规定条件的火炸药储备仓库、油料储备仓库和存有稀贵金属的综合物资储备仓库应当按照国家有关规定申请派驻武警部队进行守卫。"},{"i":19,"n":"第十九条","txt":"储备仓库应当制定守卫方案，指导、监督守卫力量落实守卫勤务制度，对重要部位采取门卫值班与警戒巡逻相结合的方式进行守卫。由武警部队守卫的储备仓库的守卫方案经武警支队和储备仓库批准后，报武警总队和管理局备案;其他储备仓库的守卫方案报管理局备案。 守卫方案应当根据目标内外情况、执勤部署和兵力等变化及时修订，并按前款权限报批。 储备仓库应当按照国家有关规定，在目标警戒控制区域内设置警戒标志，根据情况为守卫力量配备执勤设施、通信设备和交通工具。"},{"i":20,"n":"第二十条","txt":"守卫人员应当严格履行执勤人员职责，遵守执勤纪律，熟悉有关要求，保障目标安全。主要任务是： (一)负责库区、转运站、作业区的警戒控制，对出入的人员、车辆和所携物品进行检查、验证和登记; (二)维护警戒区秩序，发现异常情况及时报告并予以处置; (三)防范、打击敌特和不法分子的破坏和恐怖活动，预防和处置灾害事故; (四)完成储备仓库的其他安全保卫任务。"},{"i":21,"n":"第二十一条","txt":"储备仓库应当加强对守卫工作的组织、监督和指导，对守卫人员明确特别要求和可能发生情况的处置办法，根据情况及时提出守卫方案的修订意见。"},{"i":22,"n":"第二十二条","txt":"储备仓库应当按照国家有关规定划定风险等级，设置安全技术防范设施。"},{"i":23,"n":"第二十三条","txt":"储备仓库的安全技术防范工程建设应当符合国家有关规定。 储备仓库应当加强对安全技术防范设施的检查、维护和保养，搞好值班操作人员的技术培训，确保设备设施正常运行。"},{"i":24,"n":"第二十四条","txt":"安全技术防范工程的报警中心控制室应当设专人24小时值班，并与当地公安机关建立通信联络。图像与报警信息应当与保卫部门或者守卫分队的值班室联通。 发生报警时值班人员应当认真复核，遇有情况应当及时汇报和通知有关部门进行处置，并做好情况记录。"},{"i":25,"n":"第二十五条","txt":"储备仓库的消防工作应当遵守国家有关规定，落实消防安全制度。"},{"i":26,"n":"第二十六条","txt":"储备仓库应当成立消防安全领导小组，建立专职或者义务消防队伍，履行消防安全职责。 专职消防队的建设应当参照国家规定的城市消防站建设标准，在当地公安消防机构的指导下进行。专职消防队员可由本单位职工或者合同制工人担任，应当符合国家规定的条件，并通过有关部门组织的专业培训。 储备仓库应当根据国家规定，为专职消防队员发放补助费。"},{"i":27,"n":"第二十七条","txt":"储备仓库消防设施的设计、施工应当符合国家工程技术标准，消防车辆、器材和消防安全标志应当符合规范要求，并按规定进行检查和维护保养，保证性能完好。 新建、改建、扩建项目的消防设计，应当按照国家工程建设消防技术标准进行，并报公安消防机构审核。未经审核或者审核不合格的，建设单位不得施工。项目竣工时须经公安消防机构进行消防验收，未经验收或者验收不合格的不得投入使用。"},{"i":28,"n":"第二十八条","txt":"储备仓库应当通过多种形式开展经常性的消防安全宣传教育，每年对全体人员至少进行一次消防安全培训，对新上岗和进入新岗位的人员应当进行上岗前消防安全培训。 管理局应当组织或者协助有关部门对下列人员进行消防安全专门培训：单位的消防安全责任人;消防安全管理人员;消防控制室的值班、操作人员。"},{"i":29,"n":"第二十九条","txt":"储备仓库的库区、转运站、作业区及其他重要部位属消防安全重点部位，应当严格执行有关规定和技术标准。 (一)消防安全重点部位应当设置明显的防火标志牌，配备灭火器材; (二)消防安全重点部位的电气、照明、通信、防雷、消防设施及作业工具，应当符合国家有关规定的要求; (三)库区、转运站、作业区及其周界外50米范围内严禁烟火和燃放烟花爆竹。火炸药储备仓库的地下库的洞口及覆土库周围应当按照设计规范的要求设置防火隔离带。油料储备仓库的洞库、覆土库的计量孔、呼吸阀(透气孔)周围及地面罐的防护堤内应当符合隔火要求; 地处防火重点地区的储备仓库，应当按照地方政府的有关规定设置周界防火隔离带; (四)库区、作业区、转运站及其他存有易燃易爆危险品的场所严禁使用明火和一切可能产生明火的操作; 因施工作业确需动火时，动火单位和人员应当按照单位的用火管理制度办理审批手续，并在落实现场监护人，确认无火灾、无爆炸危险后"},{"i":30,"n":"第三十条","txt":"储备仓库的库区、转运站、作业区为安全保卫重要部位。"},{"i":31,"n":"第三十一条","txt":"重要部位及其外部安全距离内，严禁烧荒、爆破、打猎、射击及其他影响安全的活动。 重要部位及其附属设施的外部安全距离按照国家规定和有关标准执行。"},{"i":32,"n":"第三十二条","txt":"重要部位的工作人员应当经过严格审查，符合规定的条件。凡不宜在重要部位工作的人员不得安排在重要部位。"},{"i":33,"n":"第三十三条","txt":"重要部位应当严格执行国家有关的管理规定和行业标准，未经允许任何人员不得擅自进入。 重要部位应当设置醒目的警示标志，配备必要的防护设施。防护设施应当具备防火、防盗、防爆炸、防破坏功能。 进入重要部位的人员、车辆应当接受门卫值班人员的检查，不得携带火种及易燃易爆危险品。进入易燃易爆场所和运输易燃易爆危险品的车辆，应当符合国家规定的技术要求。 凡携带物品离开重要部位的人员、车辆，应当出具有效证明，交门卫值班人员查验。 重要部位不得进行与工作无关的摄影、摄像、测绘等活动，确因工作需要的应当经管理局批准。 重要部位施工作业时，应当严格执行国家局关于仓库改造期间安全管理的有关要求。"},{"i":34,"n":"第三十四条","txt":"储备仓库的库房(罐室)应当按规定设置门锁，严格执行门锁钥匙管理规定。 存有稀贵金属和易燃易爆危险品的库房(罐室)应当实行双人管理，进入人员应当按规定登记、着装和使用工具设备。任何人员不得单独进入和滞留，无关人员严禁入内。"},{"i":35,"n":"第三十五条","txt":"储备仓库枪支管理使用工作应当严格遵守国家有关规定，并自觉接受公安机关的监督、检查。"},{"i":36,"n":"第三十六条","txt":"储备仓库为专职守护押运人员申请持枪证件，应当凭管理局的批准文件和对专职守护押运人员的审查意见等材料，报公安机关主管部门办理。 储备仓库购置枪支、子弹，应当向县级公安机关申报。"},{"i":37,"n":"第三十七条","txt":"配备公务用枪的专职守护押运人员应当符合并严格遵守国家有关枪支使用管理的规定。专职守护押运人员因工作需要携带使用枪支的，应当报经管理局审查批准，并携带持枪证件。 执行守护任务的人员不得携带枪弹离开警戒区域，执行押运任务的人员完成任务后应当及时交还所携枪支。"},{"i":38,"n":"第三十八条","txt":"县级公安机关应当对储备仓库执行枪支管理制度的情况进行监督和定期检查。县级公安机关每半年应当向上一级公安机关报告储备仓库枪支管理情况，地(市)以及省级公安机关每年年初要向上一级公安机关报告储备仓库上年枪支管理情况。"},{"i":39,"n":"第三十九条","txt":"储备仓库应当按照安全管理目标责任制的要求，每半年对安全保卫工作目标执行情况进行考评，年终进行考核与总评。对安全保卫工作成绩突出的单位和个人应当给予表彰和奖励;对因违反规定造成事故和隐患的单位和个人给予处罚;构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"储备仓库的负责人及其有关人员因违反本规定造成事故及人员伤害和财产损失的，视情节给予处罚;构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本办法由国家发展和改革委员会和公安部负责解释。 国家物资储备局，各储备物资管理局应当依照本办法制定实施细则。"},{"i":42,"n":"第四十二条","txt":"本办法自2004年10月1日起施行。"}],"guojiawuzichubeiguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范国家物资储备活动，保障国家物资储备有序发展并及时有效地发挥作用，制定本规定。"},{"i":2,"n":"第二条","txt":"国家建立物资储备制度，适应国家安全和发展战略需要，服务国防建设，应对突发事件，参与宏观调控。"},{"i":3,"n":"第三条","txt":"本规定适用于国家物资储备的管理和监督活动。 本规定所称国家储备物资，是指由中央政府储备和掌握的，国家安全和发展战略所需的关键性矿产品、原材料、成品油以及具有特殊用途的其他物资。国家另有规定的除外。 国家储备物资是国家财政资金的实物形态，所有权属于国家，任何组织和个人不得以任何方式侵占、破坏和挪用。"},{"i":4,"n":"第四条","txt":"国家储备物资实行目录管理，明确品种和规模，定期评估，动态调整。"},{"i":5,"n":"第五条","txt":"确定国家储备物资的品种和规模，应当综合考虑下列因素： (一)国家发展战略需要; (二)国内外资源状况; (三)供应风险和经济风险情况; (四)需要考虑的其他因素。"},{"i":6,"n":"第六条","txt":"国家发展改革委负责国家物资储备工作。国家发展改革委国家物资储备局(以下简称储备局)及其所属储备物资管理局、办事处具体履行国家物资储备管理和监督职责。 财政部负责国家物资储备财政管理及相关行政事业单位国有资产管理，配合国家发展改革委开展国家物资储备有关工作。"},{"i":7,"n":"第七条","txt":"国家发展改革委会同财政部等部门拟订国家物资储备发展规划，报国务院审批。"},{"i":8,"n":"第八条","txt":"储备局建立监测预警制度，为国家储备物资收储、动用等提供决策支撑。"},{"i":9,"n":"第九条","txt":"国家发展改革委依据国家物资储备发展规划等，会同财政部等部门拟订年度国家储备物资收储计划，报国务院审批。 储备局依据国务院批准的年度国家储备物资收储计划组织实施。"},{"i":10,"n":"第十条","txt":"发生下列情形，储备局向国家发展改革委、财政部提出动用建议，报国务院审批： (一)应对特别重大、重大突发事件确需的; (二)宏观调控确需的; (三)法律、行政法规规定或者国务院决定动用的其他情形。 储备局拟订国家储备物资动用预案，做好动用国家储备物资的准备。"},{"i":11,"n":"第十一条","txt":"国家发展改革委会同财政部建立国家储备物资轮换机制，明确轮换条件、程序等。 储备局按照轮换机制，根据国家物资储备发展规划确定的品种、规模调整方案以及储存时间、品质状况等拟订年度及中长期国家储备物资轮换计划，经批准后组织实施。"},{"i":12,"n":"第十二条","txt":"国家储备物资的收储、动用、轮换，一般应当通过市场化方式进行。国家规定或经国务院批准必须实行定向收储、定向动用、定向轮换的除外。"},{"i":13,"n":"第十三条","txt":"国家储备物资入库一般实行送货到库制，出库一般实行到库提货制。"},{"i":14,"n":"第十四条","txt":"交通运输部门组织有关港航、铁路、公路运输企业优先安排国家储备物资的装卸和运输。"},{"i":15,"n":"第十五条","txt":"国家储备物资的收储、轮换计划应当与部门预算相衔接。经财政部依法核定后，国家储备物资轮换和动用发生的盈余上缴中央财政，亏损由中央财政补贴。"},{"i":16,"n":"第十六条","txt":"储备局应当按照布局合理、经济便捷、安全适用的原则，选择承储单位储存国家储备物资。承储单位在保管期内对国家储备物资数量、质量和储存安全负责。 国家储备物资一般由国家物资储备仓库负责储存保管。经国家发展改革委、财政部批准，储备局可以委托其他机构储存保管国家储备物资。"},{"i":17,"n":"第十七条","txt":"储备局应当依照有关法律、行政法规、部门规章、规范性文件、国家标准和技术规范制定和健全各项管理制度，对国家储备物资实行有效的监督管理，做到账实相符。"},{"i":18,"n":"第十八条","txt":"承储单位应当严格执行国家有关法律法规、规章、规范性文件、标准规范以及储备局制定的相关制度，严格执行国家储备物资入库、出库指令，接受有关部门和单位监督，保证国家储备物资数量准确、质量合格、储存安全。"},{"i":19,"n":"第十九条","txt":"国家储备物资日常管理及轮换费用和国家物资储备仓库设施设备维护费用，经财政部依法审定后列入中央财政预算。 属于中央基建投资安排范围的国家物资储备基础设施建设和改造所需资金，列入中央基建投资计划。"},{"i":20,"n":"第二十条","txt":"探索建立以政府购买服务方式储存管理国家储备物资的新机制。"},{"i":21,"n":"第二十一条","txt":"国家储备物资或者资金不得用于担保或者清偿债务。 国家物资储备建设用地、储备仓库等国有资产，未经批准不得用于投资、出租、出借以及合作经营等。"},{"i":22,"n":"第二十二条","txt":"国家物资储备的安全保障工作遵循安全第一、预防为主、综合治理的方针。 储备局应当建立健全安全责任、重大事项报告等安全保障工作制度，并负责对国家储备物资、储备仓库等的安全进行监督检查。"},{"i":23,"n":"第二十三条","txt":"国家物资储备仓库安全保卫和安全生产工作实行地方政府和上级主管部门双重领导，以地方政府为主的体制，接受当地公安、安全生产监督管理等部门的指导、监督。"},{"i":24,"n":"第二十四条","txt":"国家物资储备仓库应当在地方政府的统一组织下，积极会同政府有关部门与周边村镇、街道、企业、事业单位成立保卫工作联防组织。 国家物资储备仓库应当组织专职守卫力量开展守卫工作。符合武警部队内卫执勤任务范围规定的国家物资储备仓库，应当按照国家有关规定申请派驻武警部队进行守卫。 储备局应当按照国家有关规定，为驻库武警部队提供相关保障。"},{"i":25,"n":"第二十五条","txt":"国家储备物资的运输应严格执行国家有关规定，确保运输安全。"},{"i":26,"n":"第二十六条","txt":"储备局根据安全保障工作需要和国家有关规定，设定国家物资储备仓库重点保护区域和范围。 储存危险品的国家物资储备仓库周边安全距离，按照国家有关规定确定，并报地方政府备案，设立标志。"},{"i":27,"n":"第二十七条","txt":"国家物资储备仓库及其工作人员应当按照安全保障工作制度和规范的要求认真履行职责，保证国家储备物资和仓库的安全。"},{"i":28,"n":"第二十八条","txt":"任何组织和个人不得从事下列妨害国家物资储备安全的行为： (一)非法侵占国家物资储备仓库用地; (二)盗窃、破坏、哄抢国家储备物资; (三)破坏国家物资储备仓库及其防护、消防、电力等设施设备; (四)破坏、封堵国家物资储备仓库道路、铁路、输油管线、水源; (五)未经批准并采取必要防护措施，在国家物资储备仓库安全距离内施工、使用明火、爆破、采矿、堆放易燃易爆等危险物品; (六)非法进入国家物资储备仓库重点保护区域; (七)妨害国家物资储备安全的其他行为。"},{"i":29,"n":"第二十九条","txt":"储备局应当建立突发事件预警机制，健全突发事件应急预案体系和应对体系。储备仓库应当制定相应的突发事件应急预案，落实应急保障措施，并定期演练。"},{"i":30,"n":"第三十条","txt":"涉及国家物资储备的组织和个人，应当按照国家有关规定，保守国家秘密。 未经批准，禁止对国家物资储备仓库库区及重要设施设备摄影、摄像、勘察、测量、描绘、记述并使用相关资料。"},{"i":31,"n":"第三十一条","txt":"国家发展改革委、财政部或其委托的机构，对国家物资储备进行监督检查。 储备局建立国家物资储备统计报告制度、内部监督检查制度，定期将有关情况报告国家发展改革委、财政部。"},{"i":32,"n":"第三十二条","txt":"检查内容主要包括：国家储备物资的数量、质量和储存安全，计划落实及指令执行、财政资金使用情况等。"},{"i":33,"n":"第三十三条","txt":"承储单位应当对国家发展改革委、财政部或其委托机构的监督检查予以配合。 任何组织和个人不得拒绝、阻挠、干涉监督检查人员依法开展监督检查工作。"},{"i":34,"n":"第三十四条","txt":"违反本规定第二十八条规定行为之一的，依照《中华人民共和国治安管理处罚法》等有关法律法规的规定追究相应责任;涉嫌犯罪的，依法移送司法机关处理。"},{"i":35,"n":"第三十五条","txt":"承储单位违反本规定，有下列行为之一的，依照《中华人民共和国行政处罚法》等有关法律法规的规定，由国家发展改革委、财政部对其进行警告、罚款，并责令其改正： (一)拒不执行国家储备物资入库、出库指令和有关管理规定的; (二)未经批准，擅自动用国家储备物资或变更储存地点的; (三)虚报、瞒报国家储备物资数量的; (四)因管理不善造成国家储备物资缺失、质量明显下降的; (五)拒绝、阻挠、干涉监督检查人员依法履行职责，造成严重后果的。"},{"i":36,"n":"第三十六条","txt":"任何单位和个人在国家物资储备管理和监督活动中，骗取、截留、挤占、挪用国家财政资金的，根据《财政违法行为处罚处分条例》等规定查处。"},{"i":37,"n":"第三十七条","txt":"有关行政管理部门工作人员在国家物资储备管理和监督活动中，玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分;涉嫌犯罪的，依法移送司法机关处理。"},{"i":38,"n":"第三十八条","txt":"本规定由国家发展改革委、财政部负责解释。"},{"i":39,"n":"第三十九条","txt":"本规定自2015年6月1日起施行。"}],"guojiajiweisifabuguanyuyinfaxiangzhenfalvfuwushouf43bbf3":[{"i":1,"n":"第一条","txt":"为适应建立社会主义市场经济体制的要求，保障乡镇法律服务所和委托乡镇法律服务所办理法律事务的法人和自然人(以下简称委托人)的合法权益，规范乡镇法律服务所收费行为，根据国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于乡镇法律服务所和委托人。"},{"i":3,"n":"第三条","txt":"乡镇法律服务所提供下列法律服务，应按规定的收费标准向委托人收取法律服务费： (一)解答法律询问; (二)代写法律事务文书; (三)代理参加民事、行政诉讼活动; (四)代理非诉讼法律事务; (五)应聘担任法律顾问; (六)主持调解纠纷; (七)办理见证事项。"},{"i":4,"n":"第四条","txt":"制定和调整乡镇法律服务费标准，由省、自治区、直辖市人民政府司法行政部门提出方案，报同级价格部门审批，并报国务院价格管理部门备案。"},{"i":5,"n":"第五条","txt":"制定乡镇法律服务费标准应当考虑下列因素： (一)提供法律服务所需人员数; (二)提供法律服务所需工作时间; (三)提供法律服务的复杂程度; (四)提供法律服务可能承担的风险和责任。 (五)委托人的承受能力。"},{"i":6,"n":"第六条","txt":"乡镇法律服务费的计价形式为：计件收费、计时收费、按标的比例收费。 解答法律询问、代写法律事务文书，代理不涉及财产关系的民事、行政诉讼和非诉讼法律事务，不涉及财产关系的调解、见证，实行计件收费。 担任法律顾问实行计时(月、季度、年)收费。 代理民事、行政诉讼和非诉讼法律事务，调解纠纷、办理见证，凡涉及财产关系的，按标的比例收费。按标的比例收费的，除制定具体的收费比例外，还应规定收费的最高限额。"},{"i":7,"n":"第七条","txt":"乡镇法律服务所在为委托人提供法律服务过程中发生的下列费用由委托人另行支付： (一)鉴定费; (二)异地(省外)调查所需差旅费; (三)乡镇法律服务所为委托人支付的其他费用。"},{"i":8,"n":"第八条","txt":"乡镇法律服务所协助司法助理员(司法所)开展法制宣传教育和其他有关业务工作，不得收费。"},{"i":9,"n":"第九条","txt":"乡镇法律服务所解答比较简易的法律询问不收费。解答比较复杂的、涉及财产关系的法律询问，按规定标准收费。"},{"i":10,"n":"第十条","txt":"乡镇法律工作者担任法律顾问期间，为聘请方办理简易法律事务时，不再收费;受托代理诉讼和比较复杂的非诉讼法律事务，按规定收费标准减半收费。"},{"i":11,"n":"第十一条","txt":"乡镇法律服务所接受公证处委托协助办理公证事项或者接受当事人委托代理申请办理公证，根据工作量大小，从公证费中提取一定比例的服务费。"},{"i":12,"n":"第十二条","txt":"经乡镇法律服务所见证的民事和经济合同发生纠纷，当事人请求调解或者委托代理诉讼的，乡镇法律服务所应当减免收费。"},{"i":13,"n":"第十三条","txt":"乡镇法律服务所主持调解纠纷，调解达成协议的，调解费由有过错的一方支付;双方均有过错的，由乡镇法律服务所根据责任大小决定双方应负担的数额。调解未达成协议或者当事人中途撤回调解申请的，可根据付出工作量大小，酌情退还部分或者全部调解费。调解协议开始执行，当事人一方或者双方反悔要求重新调解的，乡镇法律服务所应当免费进行调解。"},{"i":14,"n":"第十四条","txt":"乡镇法律工作者为委托人提供法律服务，由乡镇法律服务所按照规定的收费标准向委托人收取法律服务费，并向委托人出具收费票据。乡镇法律工作者不得私自收费。"},{"i":15,"n":"第十五条","txt":"乡镇法律服务所向委托人收取法律服务费的数额和方式，除简易法律事务外，应根据国家制定的收费管理办法和收费标准在与委托人签订的《委托代理协议》或者《法律顾问聘应协议》等文书中明确约定，也可以签订专门的收费协议，并根据委托人的要求提供或者说明收费细目及计算办法。 乡镇法律服务所向委托人收取法律服务费，可以在确定委托关系后预收全部费用;也可以与委托人协商约定在承办法律事务期间分期收取;还可以采取事前由乡镇法律服务所垫支全部费用，事后向委托人结算等办法。"},{"i":16,"n":"第十六条","txt":"乡镇法律服务所与委托人终止委托关系，对预收的法律服务费，按下列办法处理： (一)因乡镇法律工作者的过错而要求终止委托关系的，乡镇法律服务所应全部退还。 (二)因委托人的过错，或者委托的要求超出规定范围而终止委托关系的，扣除承办业务已支出的费用后，将余额退还委托人。 (三)乡镇法律服务所无正当理由终止委托关系的，应将已收取的全部费用退还委托人。"},{"i":17,"n":"第十七条","txt":"对本办法第十六条所指过错有异议的，委托人或者乡镇法律服务所可以向乡镇法律服务所所在地的司法行政部门申请调处，也可依法直接提起诉讼。"},{"i":18,"n":"第十八条","txt":"乡镇法律服务所提供下列法律服务或者遇有下列情形，应当按照法律援助的有关规定，减免法律服务费： (一)因公受伤请求赔偿的; (二)请求赡养、抚养、扶养费而生活确有困难的; (三)请求抚恤金(或者劳工赔偿金)、救济金、劳动保险金的; (四)委托人经所在工作单位或者村民委员会证明确实经济困难无力负担的; (五)其他特殊情况需要减免的。"},{"i":19,"n":"第十九条","txt":"乡镇法律服务所应当严格执行国家规定的服务收费标准，明码标价，接受社会监督。"},{"i":20,"n":"第二十条","txt":"乡镇法律服务所有下列价格违法行为之一的，由价格部门的价格监督检查机构依法查处： (一)擅自提高收费标准的; (二)扩大收费范围的; (三)自立名目乱收费的; (四)不按规定明码标价的; (五)不如实提供检查所需资料的; (六)违反本办法的其他价格违法行为。"},{"i":21,"n":"第二十一条","txt":"对城市街道的法律服务所开展法律服务的收费，按本办法进行管理。"},{"i":22,"n":"第二十二条","txt":"本办法由国务院价格部门负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自1997年3月1日起施行。"}],"guojiajiweisifabuguanyuyinfagongzhengfuwushoufeigu7f9765":[{"i":1,"n":"第一条","txt":"为适应建立社会主义市场经济体制的要求，保障公证处和申请办理公证事项的公民、法人以及其他组织(以下简称申请人)的合法权益，规范公证处收费行为，根据有关公证和价格的法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于公证处和申请人。"},{"i":3,"n":"第三条","txt":"公证处对下列法律行为、有法律意义的事实和文书的真实性、合法性，向申请人提供证明以及办理其他公证服务，应按规定的收费标准向申请人收取公证服务费： (一)证明经济合同，办理继承、赠与、遗赠和提存公证; (二)赋予债权文书具有强制执行效力; (三)证明民事协议; (四)证明出生、生存、学历、经历、婚姻状况、亲属关系、收养关系、死亡、不可抗力事件、组织资格和资信等有法律意义的事实; (五)办理证据保全、制作票据拒绝证书，证明有法律意义的文书，证明知识产权的享有、转让和使用许可; (六)办理遗嘱公证和保管遗嘱，清点保管遗产，确认遗嘱的效力; (七)证明对财产的清点、清算、评估和估损; (八)其他民事法律行为的设立、变更、终止; (九)保管文书，办理法律规定的抵押登记，代办与公证事项相关的登记、认证事务，代拟和修改与公证事项相关的法律文书，解答法律咨询; (十)依法办理的其他法律服务事务。"},{"i":4,"n":"第四条","txt":"制定和调整本办法第三条第(一)、(二)、(三)、(四)、(五)项的服务费标准，由国务院司法行政部门提出方案报国务院价格部门审批。制定和调整本办法第三条第(六)、(七)、(八)、(九)、(十)项的服务费标准，由省、自治区、直辖市人民政府司法行政部门提出方案，报同级价格部门审批，并报国务院价格部门备案。 省、自治区、直辖市人民政府价格部门制定服务费标准不当的，由国务院价格部门责令其纠正或直接予以纠正。"},{"i":5,"n":"第五条","txt":"制定和调整公证服务费标准以公证处提供公证服务的社会平均成本为基础，根据办理公证事项所需人数、时间以及公证服务的复杂程度，并考虑申请人的承受能力确定。"},{"i":6,"n":"第六条","txt":"公证服务实行计件收费和按标的比例收费。 本办法第三条第(一)、(二)项按标的比例收费;第三条第(三)、(四)、(五)、(六)、(七)、(八)、(九)、(十)项计件收费。"},{"i":7,"n":"第七条","txt":"公证处为申请人提供公证服务过程中发生的下列费用，由申请人另行支付： (一)鉴定费、评估费; (二)公证书副本费; (三)公证处到异地(省外)办理公证所需的差旅费; (四)当事人因举证有困难，委托公证处进行调查的有关费用等。"},{"i":8,"n":"第八条","txt":"公证处为申请人提供公证服务，依照规定的收费标准向申请人收取公证服务费，并向申请人出具收费票据。公证员个人不得私自收费。"},{"i":9,"n":"第九条","txt":"公证处向申请人收取公证服务费，可在受理公证事项时预收，也可以与申请人约定在承办公证事项期间分期收取。"},{"i":10,"n":"第十条","txt":"已受理的公证事项，申请人要求撤回的，按规定收取手续费。因公证处的责任不能出具公证书或撤销公证书的，预收或已收的公证服务费应全部退还申请人;因公证处和申请人双方责任而撤销公证书的，应按照责任的大小退还部分费用。因申请人提供伪证及举证不实而不能出具公证书的，预收的公证服务费不予退还。"},{"i":11,"n":"第十一条","txt":"对本办法第十条所指责任有异议的，由县级以上司法行政部门认定。"},{"i":12,"n":"第十二条","txt":"有下列情况之一的，公证处应当按照法律援助的有关规定，减收或者免收公证服务费： (一)办理与领取抚恤金(或劳工赔偿金)、救济金、劳动保险金等有关的公证事项; (二)办理赡养、抚养、扶养协议的证明; (三)办理与公益活动有关的公证事项; (四)列入国家“八七”扶贫攻坚计划贫困县的申请人申办的公证事项; (五)申请人确因经济困难而无力负担的; (六)其他特殊情况需要减免的。"},{"i":13,"n":"第十三条","txt":"公证处应当严格执行国家规定的公证服务收费标准，明码标价，接受社会监督。"},{"i":14,"n":"第十四条","txt":"公证处有下列价格违法行为之一的，由价格部门的价格监督检查机构依法查处： (一)擅自提高收费标准的; (二)扩大收费范围的; (三)自立名目滥收费的; (四)不按规定明码标价的; (五)不如实提供价格检查所需资料的; (六)违反本办法的其他价格违法行为。"},{"i":15,"n":"第十五条","txt":"本办法由国务院价格部门负责解释。"},{"i":16,"n":"第十六条","txt":"本办法自1997年3月1日起施行。1991年国家物价局、财政部颁布的《公证收费规定》(〔1991〕价费字549号文附件一)同时废止。"}],"guojiajiweijiageguizhangjiqitaguifanxingwenjianqin6b59ad":[],"guojiagaojishuchanyefazhanxiangmuguanlizanxingbanf760f1a":[{"i":1,"n":"第一条","txt":"为规范管理国家高技术产业发展项目，促进高技术产业健康发展，提高产业核心竞争力，根据《中华人民共和国科学技术进步法》和《中华人民共和国促进科技成果转化法》、《国务院关于投资体制改革的决定》等法律法规，依照《中央预算内投资补助和贴息资金管理暂行办法》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于以增强自主创新能力和促进高技术产业发展为主要任务，经国家发展和改革委员会(以下简称“国家发展改革委”)批准列入国家高技术产业发展项目计划，并给予中央预算内投资补助或贷款贴息，由项目主管部门组织管理，由项目单位具体实施的国家高技术产业发展项目(以下简称“国家高技术项目”)。 对于中央预算内资金采取直接投资和资本金方式注入的国家高技术项目参照国家有关规定进行管理。"},{"i":3,"n":"第三条","txt":"本办法所称国家高技术项目包括： (一)国家高技术产业化项目(以下简称“产业化项目”)，是指以关键技术的工程化集成、示范为主要内容，或以规模化应用为目标的科技自主创新成果转化项目。 (二)国家重大技术装备研制和重大产业技术开发项目(以下简称“研制开发项目”)，是指国家重点建设工程需要的重大技术装备研制项目和重点产业结构优化升级所急需的产业共性、关键技术研发项目。 (三)国家产业技术创新能力建设项目，是指以突破产业发展的技术瓶颈、提高重大科技成果工程化、产业化研发及验证能力为目标的国家工程实验室建设项目(以下简称“工程实验室项目”)和国家工程研究中心建设项目(以下简称“工程中心项目”)，以及以提高企业技术创新能力为目标的国家认定企业技术中心建设项目(以下简称“技术中心项目”)。 (四)国家高技术产业技术升级和结构调整项目，是指以先进的技术、工艺和设备改造落后的生产条件为主要内容，以推进信息"},{"i":4,"n":"第四条","txt":"本办法所称投资补助是指国家发展改革委对符合条件的企业投资项目(含事业单位投资项目，下同)和地方政府投资项目给予的投资资金补助。本办法所称贷款贴息是指国家发展改革委对符合条件、使用了中长期银行贷款的投资项目给予的贷款利息补贴。投资补助和贷款贴息资金(以下简称“国家补贴资金”)均为无偿投入。"},{"i":5,"n":"第五条","txt":"国家发展改革委是国家高技术项目的组织部门，主要履行以下职责： (一)研究提出国家高技术产业发展规划和有关专项规划，研究提出相关产业的发展政策; (二)研究确定国家高技术项目的重点领域和重点任务; (三)组织评审国家高技术项目，批复国家高技术项目的资金申请报告; (四)编制和下达年度国家高技术产业发展项目计划和投资计划; (五)协调国家高技术项目的实施工作，组织或委托项目评估工作。"},{"i":6,"n":"第六条","txt":"本办法所称项目主管部门是指国务院有关部门，省、自治区、直辖市、计划单列市及新疆生产建设兵团发展和改革委员会或经济(贸易)委员会。 计划单列企业集团和中央管理企业可直接向国家发展改革委报送资金申请报告，并对项目承担主管责任。具体要求由国家高技术项目公告或通知规定。 对跨地区、跨部门组织的国家高技术项目，可由相关地区或部门协商确定项目主管部门，或由组织部门指定项目主管部门。 项目主管部门应履行以下主要职责： (一)根据国家发展改革委的国家高技术项目公告或通知，组织本部门、本地区和本企业(集团)的高技术项目申请国家补贴资金的相关工作，对项目的建设条件、招标内容等进行初审，审查通过后向国家发展改革委报送项目资金申请报告，并对初审结果和申报材料负责; (二)负责国家高技术项目的管理工作和项目实施中重大问题的协调、处理，确保项目按期完成并组织项目验收工作; (三)配合国家有关部门进行监督、审计和检"},{"i":7,"n":"第七条","txt":"本办法所称项目单位是指依照我国法律登记、注册，申请高技术项目国家补贴资金的企业或事业法人。项目单位应具有较好的经营管理水平，具备承担国家高技术项目所需的技术开发能力和资金筹措、工程建设组织管理能力。 项目单位应履行下列主要职责： (一)按照本办法和项目公告的要求，编制并向项目主管部门报送高技术项目国家补贴资金申请报告,并对申报材料的真实性承担责任; (二)按照项目组织部门、主管部门批复的项目资金申请报告确定的内容和要求实施项目; (三)按要求向项目主管部门报告项目实施情况和经费落实情况,及时报告项目执行中出现的重大事项; (四)对国家补贴资金要实行专账管理; (五)接受国家发展改革委及各级财政、审计部门，项目主管部门或上述部门委托的机构所进行的评估、监督、审计和检查; (六)项目总体目标达到后，及时按要求进行项目验收。"},{"i":8,"n":"第八条","txt":"国家发展改革委根据《国家高技术产业发展规划》、《当前优先发展的高技术产业化重点领域指南》、《产业结构调整指导目录》、《国家产业技术政策》及其他相关专项规划和相关产业政策，发布国家高技术项目公告或通知，明确国家支持的重点领域、重点任务、实施时间，以及安排国家补贴资金的方式和标准。"},{"i":9,"n":"第九条","txt":"按有关规定应由地方政府核准或备案的企业投资项目，应在核准或备案后提出资金申请报告。 按有关规定应由地方政府审批的地方政府投资项目，应在可行性研究报告经有权审批单位批准后提出资金申请报告。 按照有关规定应报国务院或国家发展改革委审批、核准的项目，可在报送可行性研究报告或项目申请报告时一并提出资金申请，不再单独报送资金申请报告;也可在项目经审批或核准同意后，根据国家有关投资补助、贴息的政策要求，另行报送资金申请报告。"},{"i":10,"n":"第十条","txt":"申请国家高技术项目应具备以下基本条件： (一)符合国家发展改革委项目公告或通知的要求; (二)符合国家产业政策和节能、降耗、环保、安全等要求，项目方案合理可行，具有较好的社会经济效益; (三)应具有我国自主知识产权，知识产权归属明晰; (四)项目单位必须具有较强的技术开发、资金筹措、项目实施能力，以及较好的资信等级，资产负债率在合理范围内，项目已基本具备实施条件，项目所需资金已落实; (五)建设项目应按本办法第九条完成审批、核准或备案，已基本具备开工建设条件，或已经开工建设但审批、核准或备案未超过两年，已通过项目用地预审或用地已经依法批准，具有环保以及其他许可文件。"},{"i":11,"n":"第十一条","txt":"申请国家高技术项目还应具备以下条件： (一)产业化项目采用的科技成果(包括自主知识产权、消化吸收创新、国内外联合开发的技术等)应具有先进性和良好的推广应用价值、有关成果鉴定、权威机构出具的认证或技术检测报告等证明材料、必要的验证和生产许可;项目单位具有较强的工程建设组织管理能力，具有开展相关产业化项目的生产、经营资格。 (二)研制开发项目的研制开发方案先进、可行，目标明确;项目单位应具有较强的技术创新和装备研制能力，具有前期相关领域的研发基础和研发队伍;重大技术装备研制项目应结合依托工程。 (三)工程实验室项目和工程中心项目的项目单位须为已经国家发展改革委批准组建，并完成相关组建工作的国家工程实验室的依托单位或国家工程研究中心;项目建设内容符合该工程实验室或工程研究中心的发展方向和任务，建设方案合理。 (四)技术中心项目的项目单位须为国家认定企业技术中心所在企业，且该国家认定企业技术中"},{"i":12,"n":"第十二条","txt":"项目单位应根据第十条和第十一条的相关规定，编制项目资金申请报告。 项目资金申请报告的具体要求由项目公告或通知具体规定，应包括以下主要内容： (一)项目单位的基本情况和财务状况; (二)项目的基本情况，包括项目背景、项目建设(研发)内容、总投资及资金来源、技术工艺、各项建设(研发)条件落实情况等; (三)申请国家补贴资金的主要理由和政策依据; (四)项目招标内容(适用于申请国家补贴资金500万元及以上的投资项目); (五)国家发展改革委项目公告或通知要求提供的其他内容。 项目资金申请报告可根据具体情况附以下相关文件： (一)政府投资项目的可行性研究报告批准文件或企业投资项目的核准或备案的批准文件; (二)技术来源及技术先进性的有关证明文件; (三)城市规划部门出具的城市规划选址意见(适用于城市规划区域内的投资项目); (四)国土资源部门出具的项目用地预审意见; (五)环保部门出具的环境影"},{"i":13,"n":"第十三条","txt":"项目主管部门应根据第十条至第十二条的相关规定审查项目单位提出的项目资金申请报告，对审查合格的项目资金申请报告报送国家发展改革委。其中，对于工作职能属于省级经济(贸易)委员会的项目，由省级经济(贸易)委员会作为项目主管部门，并由省级经济(贸易)委员会商省级发展和改革委员会后，由省级发展和改革委员会会同省级经济(贸易)委员会联合报送国家发展改革委。 对申报材料不完备的资金申请报告，国家发展改革委及时通知项目主管部门在要求的时限内补充相关材料。"},{"i":14,"n":"第十四条","txt":"对项目主管部门报送的项目资金申请报告，国家发展改革委组织专家组进行专家评审或委托咨询机构进行评估，必要时可征求国务院有关部门或地方政府的意见。 专家组应由专业性、权威性、代表性、中立性，且与项目无重大相关利益的专家组成。专家组应科学、客观、公正地评审项目。 专家评审或咨询机构评估应主要从以下方面对项目进行评审评估： (一)项目技术的先进性和适用性; (二)项目对相关产业的优化升级具有的带动作用; (三)项目单位的经营能力和技术开发能力; (四)项目的市场前景和经济效益; (五)项目实施方案的可行性; (六)国家发展改革委项目公告或通知的其他要求。"},{"i":15,"n":"第十五条","txt":"国家发展改革委按照科学、公平、择优的原则，根据专家评审意见或咨询机构的评估意见，综合考虑国务院有关部门和地方政府的意见，审查批复项目资金申请报告，并将项目的评审评估意见和审批结果以适当的方式告知项目主管部门。项目资金申请报告的批复文件是下达国家补贴资金的依据，应包括项目实施的总体目标、国家补贴资金额度和资金使用方向。批复文件可单独办理，也可集中办理。 国家发展改革委主要从以下方面对项目资金申请报告进行审查： (一)符合中央预算内资金的使用方向; (二)符合项目公告或通知的有关要求; (三)符合国家补贴资金的安排原则; (四)提交的相关文件齐备、有效; (五)项目的主要建设(研发)条件基本落实; (六)符合国家发展改革委要求的其他条件。"},{"i":16,"n":"第十六条","txt":"国家发展改革委安排给单个国家高技术项目的资金最高限额原则上不超过2亿元。 国家发展改革委安排给单个地方政府投资的国家高技术项目的资金在3000万元及以下的，一律按投资补助或贴息方式管理，只审批资金申请报告。国家发展改革委安排给单个企业投资的国家高技术项目的资金在3000万元及以下的，可按投资补助或贷款贴息方式管理，国家发展改革委审批资金申请报告;也可按直接投资或资本金注入方式管理，国家发展改革委审批可行性研究报告。 国家发展改革委安排给单个国家高技术项目的资金在3000万元-2亿元之间且占项目总投资的比例不超过50%的，对于地方政府投资项目可按投资补助或贷款贴息的方式管理，国家发展改革委审批资金申请报告;对于企业投资项目可按投资补助或贷款贴息的方式管理，国家发展改革委审批资金申请报告，也可按直接投资或资本金注入方式管理，国家发展改革委审批可行性研究报告。 国家发展改革委安排给单个国家高"},{"i":17,"n":"第十七条","txt":"单个国家高技术项目的国家补贴资金超过3000万元的，国家发展改革委可要求项目单位报送初步设计概算，并委托咨询机构进行评审，根据评审结果决定国家安排资金的具体数额。"},{"i":18,"n":"第十八条","txt":"单个国家高技术项目的国家补贴资金原则上均为一次性安排。对于已经安排国家补贴资金的国家高技术项目，国家发展改革委不再重复受理其资金申请报告。"},{"i":19,"n":"第十九条","txt":"国家高技术项目的资金来源包括项目单位的自有资金、国家补贴资金、国务院有关部门或地方政府配套资金、银行贷款，以及项目单位筹集的其它资金。项目资金原则上以项目单位自筹为主，国家采用资金补贴的方式予以支持。"},{"i":20,"n":"第二十条","txt":"项目单位筹集的项目资本金或研发项目的自有资金不得低于项目新增投资的30%。项目资本金来源包括项目单位可用于项目的现金、发行股票筹集的资金、新老股东增资扩股资金、资产变现的资金等。"},{"i":21,"n":"第二十一条","txt":"国家补贴资金分为投资补助和贷款贴息补助两类。 国家投资补助应根据项目的重要性、风险程度以及产业发展、区域布局等要求，分档给予补助支持。 贷款贴息补助的贴息率不超过当期银行中长期贷款利率。贴息资金总额根据项目符合贴息条件的银行贷款总额、当年贴息率和贴息年限计算确定，原则上按项目的实施进度和贷款的实际发生额分期安排贴息资金。"},{"i":22,"n":"第二十二条","txt":"国家补贴资金主要用于项目的研究开发、购置研究开发及工程化所需的仪器设备、改善工艺设备和测试条件、建设产业化或工程化验证成套装置和试验装置、建设必要的配套基础设施、购置必要的技术、软件等。"},{"i":23,"n":"第二十三条","txt":"经国家发展改革委批复的国家高技术项目列入国家高技术产业发展项目计划和投资计划。 国家发展改革委根据项目资金申请报告的批复文件、项目建设进度和项目建设资金到位情况，以及项目主管部门提出的项目国家补贴资金的下达申请，可一次或分次下达国家补贴资金投资计划。项目主管部门收到国家补贴资金投资计划后，要按有关规定尽快将国家补贴资金投资计划下达到项目单位，并做好有关协调工作。 对于由省级经济(贸易)委员会作为项目主管部门的项目，国家发展改革委将国家补贴资金投资计划同时下达省级发展和改革委员会及经济(贸易)委员会，由省级发展和改革委员会、省级经济(贸易)委员会联合下达到项目单位。"},{"i":24,"n":"第二十四条","txt":"项目单位对国家补贴资金要专款专用、专账管理;任何部门和单位不得截留、挤占和挪用国家补贴资金;项目主管部门要对国家补贴资金加强监管，督促项目单位按照国家补贴资金使用方向使用国家补贴资金。"},{"i":25,"n":"第二十五条","txt":"项目单位的自筹资金应按计划及时足额投入。鼓励项目主管部门对项目安排必要的配套资金。"},{"i":26,"n":"第二十六条","txt":"国家高技术项目实行项目单位责任制，项目单位依照有关法律法规负责项目的筹划、筹资、建设、运营等，并配合国家有关部门和项目主管部门做好对国家补贴资金使用的监督、检查和审计工作。"},{"i":27,"n":"第二十七条","txt":"项目主管部门根据国家对项目资金申请报告的批复文件和项目审批、核准或备案文件，对项目实施情况和国家补贴资金的使用情况等进行监管。项目主管部门可根据具体情况要求项目单位编制项目初步设计、建设方案或实施方案。"},{"i":28,"n":"第二十八条","txt":"所有国家高技术项目应按照国家有关招标投标的法律法规做好招标工作。其中，对于使用国家补贴资金500万元及以上的项目，要严格按照国家发展改革委核准的项目招标内容和有关招标投标的法律法规开展招标工作。"},{"i":29,"n":"第二十九条","txt":"项目主管部门应在每年2月底和8月底以前，以正式文件向国家发展改革委提交包括项目进度情况、存在的问题、解决问题的具体措施和处理意见等内容的项目进展情况报告，并提出国家补贴资金的下达申请。项目单位应按照项目主管部门的要求报送有关项目进展情况。"},{"i":30,"n":"第三十条","txt":"项目单位应按照资金申请报告批复的总体目标组织实施。实施过程中，项目出现重大情况需调整的，应向项目主管部门报告。对不能完成总体目标的项目，由项目主管部门提出处理建议报国家发展改革委;对于其他不影响项目总体目标实现的调整，由项目主管部门负责审核调整，并抄报国家发展改革委。"},{"i":31,"n":"第三十一条","txt":"项目实施达到项目总体目标后，项目单位应及时做好项目验收准备工作，并向项目主管部门提出项目验收申请。项目主管部门应及时对项目进行验收，并将验收结论报送国家发展改革委。计划单列企业集团和中央管理企业在验收国家高技术项目时，应邀请第三方人员参加。项目单位要按国家有关规定妥善保管项目有关档案和验收材料。"},{"i":32,"n":"第三十二条","txt":"项目实施过程中和验收后，国家发展改革委可视情况组织或委托项目主管部门、有关中介机构或有关专家组对项目进行中期评估和后评估。"},{"i":33,"n":"第三十三条","txt":"项目实施过程中取得的专利、著作权等知识产权权属，按照有关法律法规执行。"},{"i":34,"n":"第三十四条","txt":"研制开发项目的国家补贴资金财务处理按照科研项目相应的财政拨款有关规定管理。其他国家高技术项目的国家补贴资金的财务处理按照资本公积管理。"},{"i":35,"n":"第三十五条","txt":"国家发展改革委负责对国家高技术项目实施情况进行监督。财政、审计、监察等部门依据职能分工进行监督检查。项目主管部门和项目单位应配合监督、审计、监察和检查工作。"},{"i":36,"n":"第三十六条","txt":"项目监督、审计、监察和检查工作应按照有关法律法规和本管理办法进行。"},{"i":37,"n":"第三十七条","txt":"国家高技术项目信息，除涉及国家秘密和国家安全，商业秘密和其他依法不适宜公开的外，应当采取适当方式向社会公开。国家发展改革委和项目主管部门受理单位、个人对国家高技术项目在审批、建设过程中违法违规行为的举报，并按照有关规定予以查处。"},{"i":38,"n":"第三十八条","txt":"对于按项目总体目标和项目内容按期或提前完成、通过验收，取得突出成绩的项目单位，以及在项目组织和管理中工作表现出色的项目主管部门及工作人员，国家发展改革委将给予表彰，并在今后的国家高技术项目评选中，对受表彰的项目主管部门组织申报的项目同等条件下优先安排。"},{"i":39,"n":"第三十九条","txt":"项目单位有下列行为之一的，国家发展改革委可以责令其限期整改，核减、停止拨付或收回国家补贴资金，并可视情节轻重提请或移交有关机关依法追究有关责任人的行政或法律责任： (一)提供虚假情况，骗取国家补贴资金的; (二)转移、侵占或者挪用国家补贴资金的; (三)擅自改变项目总体目标和主要建设内容的; (四)无违规行为，但无正当理由未按要求完成项目总体目标延期两年未验收的; (五)其他违反国家法律法规和本办法规定的行为。"},{"i":40,"n":"第四十条","txt":"项目组织部门、项目主管部门和评估、咨询单位及有关责任人在审批、管理、评估、咨询、监督、检查等过程中弄虚作假、玩忽职守、滥用职权、徇私舞弊、索贿受贿的，国家发展改革委可建议有关部门依法追究有关责任人的行政责任;构成犯罪的，由司法机关依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"项目主管部门应根据本办法的总体原则，结合本部门、本地区的具体情况，制订相应的实施细则，并报国家发展改革委备案。"},{"i":42,"n":"第四十二条","txt":"本办法由国家发展改革委负责解释。"},{"i":43,"n":"第四十三条","txt":"本办法自二〇〇六年四月一日起施行。"}],"guoyouliangyoucangchuwuliusheshibaohubanfa":[{"i":1,"n":"第一条","txt":"为加强国有粮油仓储物流设施保护，保证粮油仓储能力满足保障国家粮食安全的需要，根据《粮食流通管理条例》《中央储备粮管理条例》和相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内国有独资、国有控股粮油仓储单位的粮油仓储物流设施，混合所有制粮油仓储单位中涉及政府性资金资产投入建设、维修改造的粮油仓储物流设施。其他粮油仓储物流设施的保护参照本办法。 本办法所称粮油仓储物流设施包括从事粮油仓储活动所需的经营场地，仓房、油罐等存储设施，专用道路、铁路、码头等物流设施，以及烘干设施、器材库、清理维修车间等附属设施。"},{"i":3,"n":"第三条","txt":"国家粮食行政管理部门负责全国粮油仓储物流设施保护的行业指导和监督管理，根据国家粮食收储供应安全保障需要，制定全国粮油仓储物流设施建设规划，建立健全粮油仓储物流设施淘汰、更新及保护机制，将粮油仓储物流设施保护情况纳入粮食安全省长责任制监督考核体系。"},{"i":4,"n":"第四条","txt":"县级以上地方人民政府粮食行政管理部门负责本行政区域内粮油仓储物流设施保护的行业指导和监督管理，在上级粮食行政管理部门指导和本级人民政府领导下，根据本地区粮食收储供应安全保障需要，细化落实粮油仓储物流设施淘汰、更新及保护措施，会同有关部门组织开展粮油仓储物流设施保护的考核工作。"},{"i":5,"n":"第五条","txt":"任何单位和个人不得侵占、损坏、擅自拆除粮油仓储物流设施，不得擅自改变粮油仓储物流设施用途，不得危害粮油仓储物流设施安全和粮油储存安全。"},{"i":6,"n":"第六条","txt":"粮油仓储单位应当自设立或者开始从事粮油仓储活动之日起30个工作日内，依法将粮油仓储物流设施等情况向所在地粮食行政管理部门备案。粮油仓储物流设施规模、用途发生变化的，也应当及时备案。 粮油仓储单位应当建立健全粮油仓储物流设施管理和使用制度，定期检查评估、维护保养，做好记录、建立档案，并按照规定向粮食行政管理部门提供相关情况。"},{"i":7,"n":"第七条","txt":"因重大项目建设或涉及粮食流通格局优化调整，确需拆除、迁移粮油仓储物流设施或改变其用途的，组织拆除、迁移或者改变用途行为的单位应当征得相关粮油仓储单位同意，并事先经设施所在地粮食行政管理部门逐级报告至省级人民政府粮食行政管理部门。 粮油仓储单位应当自拆迁、改变用途行为发生之日起30个工作日内向所在地粮食行政管理部门备案。 被拆除、迁移粮油仓储物流设施所在地粮食行政管理部门应当按照“功能不降、先建后拆”的原则，负责统筹协调重建，确保辖区内粮油仓储物流设施总量、布局及结构满足粮食安全需要。"},{"i":8,"n":"第八条","txt":"依法对粮油仓储物流设施予以行政征收、征用的，被征收、征用单位应当自征收、征用之日起30个工作日内向粮油仓储物流设施所在地粮食行政管理部门备案。 征收后，如对当地粮食收储供应安全保障能力造成影响，征收主体上级人民政府的粮食行政管理部门应当根据粮油仓储物流设施的总量、布局及结构等予以协调重建。 征用的，征用主体上级人民政府的粮食行政管理部门应当协调在使用结束后尽快恢复原状及用途，不能恢复的，按照前款规定处理。"},{"i":9,"n":"第九条","txt":"粮油仓储单位出租、出借粮油仓储物流设施，应当与承租方签订合同，明确双方权利、义务，并自签订之日起30个工作日内向粮油仓储物流设施所在地粮食行政管理部门备案。 出租、出借不得破坏粮油仓储物流设施的功能，不得危及粮油仓储单位的粮油储存安全。"},{"i":10,"n":"第十条","txt":"粮油仓储物流设施不能满足粮油安全储存或粮食流通需要的，粮油仓储单位应当维修改造或重建;涉及布局和结构调整的，由所在地县级以上地方人民政府粮食行政管理部门统筹协调。 粮油仓储物流设施超过设计使用年限且不具有维修改造价值的，粮油仓储单位应当按照有关规定予以报废处置;具有历史文化价值的，所在地粮食行政管理部门应当依法协调修缮保留。"},{"i":11,"n":"第十一条","txt":"在粮油储存区内及临近区域，不得开展可能危及粮油仓储物流设施安全和粮油储存安全的活动，不得在安全距离内设置新的污染源、危险源。"},{"i":12,"n":"第十二条","txt":"粮油仓储物流设施因不可抗力遭受破坏时，粮油仓储单位应当根据需要对其进行修复或重建，所在地粮食行政管理部门应当协调支持。"},{"i":13,"n":"第十三条","txt":"为保持或升级粮油仓储物流设施功能，弥补仓容缺口，进行维修改造或新建扩建，各级人民政府粮食行政管理部门应当协调有关部门给予资金、政策等支持。"},{"i":14,"n":"第十四条","txt":"本办法涉及粮油仓储物流设施备案的具体规定,由省级人民政府粮食行政管理部门制定。备案应创新形式，简化程序，优化服务，积极推进电子化备案。"},{"i":15,"n":"第十五条","txt":"任何公民、法人和其他组织对侵占、损坏、擅自拆除粮油仓储物流设施，擅自改变粮油仓储物流设施用途，危害粮油仓储物流设施安全和粮油储存安全的违法行为，有权向各级人民政府粮食行政管理部门举报。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府粮食行政管理部门会同有关部门对侵占、损坏、擅自拆除粮油仓储物流设施，擅自改变粮油仓储物流设施用途，危害粮油仓储物流设施安全和粮油储存安全的违法行为予以依法制止和查处。"},{"i":17,"n":"第十七条","txt":"各级人民政府粮食行政管理部门应当调查和掌握辖区内粮油仓储物流设施的存量及变化情况，按照粮食流通统计制度规定逐级上报，并建立专门档案。"},{"i":18,"n":"第十八条","txt":"粮油仓储单位的有关违法行为及行政处罚信息由查处违法行为、实施行政处罚的粮食行政管理部门建立信用记录，纳入全国信用信息共享平台，并依照有关规定及时公开。"},{"i":19,"n":"第十九条","txt":"对保护粮油仓储物流设施有重大贡献的单位和个人，各级人民政府粮食行政管理部门应当协调予以适当奖励。"},{"i":20,"n":"第二十条","txt":"国家粮食行政管理部门根据有关规定，会同有关部门对各地落实本办法的情况进行监督考核，考核结果作为粮食基础设施建设投资及奖励、补助的依据。 对保护粮油仓储物流设施不力、严重危害粮食收储供应安全的地区和单位，国家粮食行政管理部门予以通报批评。"},{"i":21,"n":"第二十一条","txt":"任何公民、法人和其他组织违反本办法规定拆除、迁移粮油仓储物流设施，非法侵占、损坏粮油仓储物流设施或者擅自改变其用途，由粮油仓储物流设施所在地粮食行政管理部门责令其限期改正，并依法予以警告或者罚款;有违法所得的，没收违法所得;造成财产损失的，依法承担民事赔偿责任;构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"各级人民政府粮食行政管理部门及有关企事业单位工作人员违反本办法规定，滥用职权、营私舞弊或者玩忽职守，造成粮油仓储物流设施损失、损坏，视情节依纪依规予以警告、降级直至开除的行政处分。涉及违法的，移送司法机关处理;构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"粮油仓储单位违反本办法规定，未及时备案的，由备案管辖的粮食行政管理部门责令限期改正;拒不改正的，依法予以警告或者罚款。 粮油仓储单位因自身原因导致粮油仓储物流设施发生重大损失、损坏，应当中止其政策性粮油储存任务。"},{"i":24,"n":"第二十四条","txt":"本办法自2016年8月1日起施行。"},{"i":25,"n":"第二十五条","txt":"本办法所称粮油仓储单位，是指仓容规模500吨以上或者罐容规模100吨以上，专门从事粮油仓储活动，或者在粮油收购、销售、运输、加工、进出口等经营活动过程中从事粮油仓储活动的法人和其他组织。"}],"guojijinrongzuzhihewaiguozhengfudaikuantouzixiangm285535":[{"i":1,"n":"第一条","txt":"为加强国际金融组织和外国政府贷款(以下简称国外贷款)投资项目管理，提高国外贷款使用效益，根据《国务院关于投资体制改革的决定》和国家有关外债管理规定，制定本办法。"},{"i":2,"n":"第二条","txt":"借用世界银行、亚洲开发银行、国际农业发展基金会等国际金融组织贷款和外国政府贷款及与贷款混合使用的赠款、联合融资等投资项目的管理，适用本办法。"},{"i":3,"n":"第三条","txt":"境内企业、机构、团体均可申请借用国外贷款。"},{"i":4,"n":"第四条","txt":"国外贷款属于国家主权外债，按照政府投资资金进行管理。国外贷款主要用于公益性和公共基础设施建设，保护和改善生态环境，促进欠发达地区经济和社会发展。"},{"i":5,"n":"第五条","txt":"国外贷款备选项目规划是项目对外开展工作的依据。借用国外贷款的项目必须纳入国外贷款备选项目规划。 未纳入国外贷款备选项目规划的项目，国务院各有关部门、地方各级政府和项目用款单位不得向国际金融组织或外国政府等国外贷款机构正式提出贷款申请。"},{"i":6,"n":"第六条","txt":"国务院发展改革部门按照国民经济和社会发展规划、产业政策、外债管理及国外贷款使用原则和要求，编制国外贷款备选项目规划，并据此制定、下达年度项目签约计划。 世界银行、亚洲开发银行贷款和日本政府日元贷款备选项目规划由国务院发展改革部门提出，商国务院财政部门后报国务院批准。"},{"i":7,"n":"第七条","txt":"国务院行业主管部门、省级发展改革部门、计划单列企业集团和中央管理企业向国务院发展改革部门申报纳入国外贷款规划的备选项目。 国务院行业主管部门申报的项目，由地方政府安排配套资金、承担贷款偿还责任或提供贷款担保的，应当同时出具省级发展改革部门及有关部门意见。"},{"i":8,"n":"第八条","txt":"申报纳入国外贷款规划的备选项目材料包括以下内容： (一)项目简要情况; (二)项目建设必要性; (三)拟申请借用国外贷款的类别或国别; (四)贷款金额及用途; (五)贷款偿还责任。"},{"i":9,"n":"第九条","txt":"已纳入国际金融组织贷款、日本政府日元贷款备选项目规划的项目，如需调整贷款来源或撤销贷款的，应当将调整内容按照本办法第七条规定的程序报国务院发展改革部门。 纳入其他外国政府贷款备选项目规划的项目，如需调整贷款来源的，应当将调整内容在项目资金申请报告审批阶段一并报批。"},{"i":10,"n":"第十条","txt":"原批准使用其他资金的项目，拟申请转用国外贷款;或已批准使用国外贷款的项目，拟申请转用其他资金的，应当按照本办法第七条规定的程序报国务院发展改革部门。"},{"i":11,"n":"第十一条","txt":"国务院发展改革部门、省级发展改革部门参与项目的有关对外工作，指导和督促国外贷款规划及年度项目签约计划的落实。"},{"i":12,"n":"第十二条","txt":"纳入国外贷款备选项目规划的项目，应当区别不同情况履行审批、核准或备案手续： (一)由中央统借统还的项目，按照中央政府直接投资项目进行管理，其项目建议书、可行性研究报告由国务院发展改革部门审批或审核后报国务院审批。 (二)由省级政府负责偿还或提供还款担保的项目，按照省级政府直接投资项目进行管理，其项目审批权限，按国务院及国务院发展改革部门的有关规定执行。除应当报国务院及国务院发展改革部门审批的项目外，其他项目的可行性研究报告均由省级发展改革部门审批，审批权限不得下放。 (三)由项目用款单位自行偿还且不需政府担保的项目，参照《政府核准的投资项目目录》规定办理：凡《政府核准的投资项目目录》所列的项目，其项目申请报告分别由省级发展改革部门、国务院发展改革部门核准，或由国务院发展改革部门审核后报国务院核准;《政府核准的投资项目目录》之外的项目，报项目所在地省级发展改革部门备案。"},{"i":13,"n":"第十三条","txt":"项目纳入国外贷款备选项目规划并完成审批、核准或备案手续后，项目用款单位须向所在地省级发展改革部门提出项目资金申请报告。 项目资金申请报告由省级发展改革部门初审后，报国务院发展改革部门审批。 国务院行业主管部门、计划单列企业集团和中央管理企业的项目资金申请报告，直接报国务院发展改革部门审批。"},{"i":14,"n":"第十四条","txt":"由国务院及国务院发展改革部门审批的项目可行性研究报告，可行性研究报告中应当包括项目资金申请报告内容，不再单独审批项目资金申请报告。"},{"i":15,"n":"第十五条","txt":"项目资金申请报告应当具备以下内容： (一)项目概况，包括项目建设规模及内容、总投资、资本金、国外贷款及其他资金、项目业主、项目执行机构、项目建设期; (二)国外贷款来源及条件，包括国外贷款机构或贷款国别、还款期、宽限期、利率、承诺费等; (三)项目对外工作进展情况; (四)贷款使用范围，包括贷款用于土建、设备、材料、咨询和培训等的资金安排; (五)设备和材料采购清单及采购方式，包括主要设备和材料规格、数量、单价; (六)经济分析和财务评价结论; (七)贷款偿还及担保责任、还款资金来源及还款计划。"},{"i":16,"n":"第十六条","txt":"项目资金申请报告应当附以下文件： (一)项目批准文件(项目可行性研究报告批准文件、项目申请报告核准文件或项目备案文件)。 (二)国际金融组织和日本国际协力银行贷款项目，提供国外贷款机构对项目的评估报告。 (三)国务院行业主管部门提出项目资金申请报告时，如项目需地方政府安排配套资金、承担贷款偿还责任或提供贷款担保的，出具省级发展改革部门及有关部门意见。 (四)申请使用限制性采购的国外贷款项目，出具对国外贷款条件、国内外采购比例、设备价格等比选结果报告。"},{"i":17,"n":"第十七条","txt":"国务院发展改革部门审批项目资金申请报告的条件是： (一)符合国家利用国外贷款的政策及使用规定; (二)符合国外贷款备选项目规划; (三)项目已按规定履行审批、核准或备案手续; (四)国外贷款偿还和担保责任明确，还款资金来源及还款计划落实; (五)国外贷款机构对项目贷款已初步承诺。"},{"i":18,"n":"第十八条","txt":"项目资金申请报告批准后，项目建设内容、贷款金额及用途等发生变化的，须按本办法第十三条规定的程序将调整方案报国务院发展改革部门批准。"},{"i":19,"n":"第十九条","txt":"国务院及国务院发展改革部门对项目可行性研究报告或资金申请报告的批准文件，是对外谈判、签约和对内办理转贷生效、外债登记、招标采购和免税手续的依据。"},{"i":20,"n":"第二十条","txt":"未经国务院及国务院发展改革部门审批可行性研究报告或资金申请报告的项目，有关部门和单位不得对外签署贷款协定、协议和合同，外汇管理、税务、海关等部门及银行不予办理相关手续。"},{"i":21,"n":"第二十一条","txt":"项目资金申请报告自批准之日起两年内，项目未签订国外贷款转贷协议的，该批准文件自动失效。"},{"i":22,"n":"第二十二条","txt":"国务院发展改革部门、省级发展改革部门指导和协调项目实施工作，监督有关招投标活动。"},{"i":23,"n":"第二十三条","txt":"国外贷款项目出现余款时，项目用款单位应当及时办理有关余款取消手续，并按本办法第十三条规定的程序抄报国务院发展改革部门。 如将余款继续用于完善原项目建设的，应当参照项目资金申请报告的要求，编制余款使用方案，并按本办法第十三条规定的程序报国务院发展改革部门批准。"},{"i":24,"n":"第二十四条","txt":"负责将国外贷款进行转贷的转贷机构，应当根据国务院及国务院发展改革部门对项目可行性研究报告或资金申请报告的批准文件，对项目的国外贷款进行转贷，并于每年六月底和十二月底向国务院发展改革部门报送国外贷款支付和偿还情况。 由各级政府负责偿还国外贷款或提供还款担保的项目，转贷机构原则上应当按贷款方提供的贷款条件进行转贷。如以规避外债风险为目的需对上述项目转贷条件进行调整的，转贷机构应当事先征得国务院发展改革部门同意。"},{"i":25,"n":"第二十五条","txt":"项目用款单位要依法履行国外贷款偿还责任，及时进行外债登记，加强国外贷款债务风险管理。 项目用款单位要建立项目信息反馈制度，并于每年六月底和十二月底向批准项目的发展改革部门提交项目进度报告。"},{"i":26,"n":"第二十六条","txt":"国务院发展改革部门应当对项目实施情况和省级发展改革部门批准及管理项目情况进行监督检查，并对查实的问题提出处理意见。"},{"i":27,"n":"第二十七条","txt":"为确保对外还款，防止逃废债务，尚未偿还全部国外贷款的项目用款单位，在进行资产重组、产权变更或破产申请前，应当事先征得转贷机构对剩余债务偿还安排的书面认可，落实还贷责任，并将有关结果抄报国务院发展改革部门。"},{"i":28,"n":"第二十八条","txt":"省级发展改革部门依据本办法的规定，制定相应的管理办法。"},{"i":29,"n":"第二十九条","txt":"本办法由国家发展改革委负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自2005年3月1日起施行。此前有关国外贷款投资项目管理的规章和其他规范性文件，与本办法不一致的，按本办法规定执行。"}],"chengzhengongshuijiageguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范城镇供水价格管理，保障供水、用水双方的合法权益，促进城镇供水事业发展，节约和保护水资源，根据《中华人民共和国价格法》《城市供水条例》《政府制定价格行为规则》等法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内制定或者调整城镇供水价格行为。"},{"i":3,"n":"第三条","txt":"城镇供水价格是指城镇公共供水企业(以下称供水企业)通过一定的工程设施，将地表水、地下水进行必要的净化、消毒处理、输送，使水质水压符合国家规定的标准后供给用户使用的水价格。"},{"i":4,"n":"第四条","txt":"县级以上人民政府价格主管部门是城镇供水价格的主管部门。县级以上城镇供水行政主管部门按职责分工，协助政府价格主管部门做好城镇供水价格管理工作。"},{"i":5,"n":"第五条","txt":"城镇供水价格原则上实行政府定价，具体定价权限按地方定价目录的规定执行。"},{"i":6,"n":"第六条","txt":"制定城镇供水价格应当遵循覆盖成本、合理收益、节约用水、公平负担的原则。"},{"i":7,"n":"第七条","txt":"制定城镇供水价格，以成本监审为基础，按照“准许成本加合理收益”的方法，先核定供水企业供水业务的准许收入，再以准许收入为基础分类核定用户用水价格。 供水企业供水业务的准许收入由准许成本、准许收益和税金构成。"},{"i":8,"n":"第八条","txt":"供水企业准许成本包括固定资产折旧费、无形资产摊销和运行维护费，相关费用通过成本监审确定。"},{"i":9,"n":"第九条","txt":"准许收益按照有效资产乘以准许收益率计算确定。其中： (一)有效资产为供水企业投入、与供水业务相关的可计提收益的资产，包括固定资产净值、无形资产净值和营运资本。可计提收益的有效资产，通过成本监审核定。 (二)准许收益率的计算公式为：准许收益率=权益资本收益率×(1-资产负债率)+债务资本收益率×资产负债率。 其中：权益资本收益率，按照监管周期初始年前一年国家10年期国债平均收益率加不超过4个百分点核定;债务资本收益率，参考监管周期初始年前一年贷款市场报价利率(LPR)确定;资产负债率参照监管周期初始年前3企业实际资产负债率平均值核定，首次核定价格的，以开展成本监审时的前一年度财务数据核定。"},{"i":10,"n":"第十条","txt":"税金。包括所得税、城市维护建设税、教育费附加，依据国家现行相关税法规定核定。"},{"i":11,"n":"第十一条","txt":"核定供水企业平均供水价格，应当考虑本期生产能力利用情况，计算公式为： 当实际供水量不低于设计供水量的65%时，供水企业平均供水价格=准许收入÷核定供水量; 当实际供水量低于设计供水量的65%时，供水企业平均供水价格=准许收入÷{核定供水量÷[实际供水量÷(设计供水量×65%)]｝。 平均供水价格、准许收入均不含增值税，含增值税供水价格由各地根据供水企业实际执行税率计算确定;核定供水量=取水量×(1-自用水率)×(1-漏损率)。取水量、自用水率、漏损率通过成本监审确定。"},{"i":12,"n":"第十二条","txt":"分用户类别供水价格，应当以供水企业平均供水价格、当地用水结构为基础，按照居民生活用水保本微利、其他用水合理盈利的原则，统筹考虑当地供水事业发展需要、促进节约用水、社会承受能力等因素核定。"},{"i":13,"n":"第十三条","txt":"城镇供水价格监管周期原则上为3年，经测算需要调整供水价格的，应及时调整到位，价格调整幅度较大的，可以分步调整到位。建立供水价格与原水价格等上下游联动机制的，监管周期年限可以适当延长。具体价格监管周期年限由定价部门结合当地实际明确。 考虑当地经济社会发展水平和用户承受能力等因素，由于价格调整不到位导致供水企业难以达到准许收入的，当地人民政府应当予以相应补偿。"},{"i":14,"n":"第十四条","txt":"鼓励各地激励供水企业提升供水服务质量。核定供水价格应当充分考虑供水服务质量因素，将水质达标、用水保障、投诉处理情况等作为确定供水企业合理收益的重要因素。"},{"i":15,"n":"第十五条","txt":"城镇供水实行分类水价。根据使用性质分为居民生活用水、非居民用水、特种用水三类。 (一)居民生活用水主要指城镇居民住宅家庭的日常生活用水。 (二)非居民用水主要指工业、经营服务用水和行政事业单位用水、市政用水(环卫、绿化)、生态用水、消防用水等。 学校教学和学生生活用水、养老机构和残疾人托养机构等社会福利场所生活用水、宗教场所生活用水、社区组织工作用房和居民公益性服务设施用水等，按照居民生活类用水价格执行。 (三)特种用水主要包括洗车、以自来水为原料的纯净水生产、高尔夫球场用水等。 各类用水具体范围的划分，由省级城镇供水行政主管部门会同同级价格主管部门结合当地实际情况确定。"},{"i":16,"n":"第十六条","txt":"居民生活用水实行阶梯价格制度。居民生活用水阶梯水价设置应当不少于三级，级差按不低于1:1.5:3的比例安排。其中，第一阶梯水价原则上应当按照补偿成本的水平确定，并应当考虑本期生产能力利用情况。 阶梯水量由各地结合本地实际情况，按照一级满足居民基本生活用水需求、二级体现改善和提高居民生活质量用水需求的原则确定，并根据实施情况实行动态管理。具体可以参考《城镇居民生活用水量标准》(GB/T50331)，因地制宜确定用水量分级标准。 各地应当积极推进城镇供水“一户一表”改造，具备条件的应当安装智能水表，为全面实施居民生活用水阶梯水价及非居民用水超定额累进加价制度创造条件。未实行抄表到户的合表户居民和执行居民生活用水价格的非居民用户，供水价格按照不低于第一阶梯价格确定。"},{"i":17,"n":"第十七条","txt":"非居民用水及特种用水实行超定额累进加价制度，原则上水量分档不少于三档，二档水价加价标准不低于0.5倍，三档水价加价标准不低于1倍，具体分档水量和加价标准由各地自行确定。缺水地区要根据实际情况加大加价标准，充分反映水资源稀缺程度。 实行居民生活用水阶梯水价和非居民用水超定额累进加价后增加的收入，应当主要用于管网和户表改造、水质提升、弥补供水成本上涨等。"},{"i":18,"n":"第十八条","txt":"各地可以根据当地实际情况实行容量水价和计量水价相结合的两部制水价。容量水价用于补偿供水固定成本,计量水价用于补偿供水的运行维护费用等。"},{"i":19,"n":"第十九条","txt":"以旅游业为主或季节性消费特点明显的地区可以实行季节性水价。在枯水期实行较高的价格，丰水期实行较低的价格。"},{"i":20,"n":"第二十条","txt":"城镇供水应当装表到户、计量到户、抄表到户、收费到户、服务到户。"},{"i":21,"n":"第二十一条","txt":"供水企业暂未抄表到户由转供水单位收取水费的，终端用户具备表计条件的按照政府规定供水价格执行，供水企业应当尽快抄表到户;终端用户不具备表计条件的可以暂按政府规定供水价格向供水企业交纳供水费用并由终端用户公平分摊。公共部位、共用设施等用水应当计量，相应水费应当通过收取的物业费、租金或公共收益等解决，并建立健全费用分摊相关信息公示制度。"},{"i":22,"n":"第二十二条","txt":"新增建设项目用水必须装表到户。建设项目建筑区划红线内供水管道及设施建设安装费用由建设单位承担，供水管道和用水设备的安装应当坚持建设单位自愿委托的原则。"},{"i":23,"n":"第二十三条","txt":"各地应当加快二次加压调蓄供水设施改造，鼓励依法依规移交给供水企业实行专业运行维护。由供水企业负责运行管理的二次加压调蓄供水设施，其运行维护、修理更新成本计入供水价格，不得另行收费。"},{"i":24,"n":"第二十四条","txt":"供水工程安装及其他延伸服务(用户产权范围内的供水设施修理、维护、更换等)，应当加快引入市场竞争机制。除受用户委托开展的建设安装工程费用外，供水企业不得滥用垄断地位收取供水开户费、接入费、增容费等费用。"},{"i":25,"n":"第二十五条","txt":"供水企业或用户自愿委托相关机构对水表进行检定的，按照“谁委托、谁付费”原则，检定费用由委托方支付，但水表经检定不合格的，检定费用由供水企业承担，并免费为用户更换合格的水表。"},{"i":26,"n":"第二十六条","txt":"供水价格由各省、自治区、直辖市定价目录确定的定价部门制定或者调整。消费者、供水企业、供水行政主管部门及有关方面可以向价格主管部门提出定调价建议。"},{"i":27,"n":"第二十七条","txt":"制定居民生活用水价格水平或定价机制应当按照价格听证的有关规定开展听证。"},{"i":28,"n":"第二十八条","txt":"价格主管部门制定供水价格，应当开展成本监审，并实行成本公开。 在价格听证前，供水企业应当公开本企业有关经营情况和成本数据，以及社会关注的其它有关水价调整的信息;定价部门应当公开成本监审结论。依据已经生效实施的定价机制制定具体价格水平的，应当在制定价格的决定实施前公开启动定价机制的依据及理由。 县级以上价格主管部门应当建立定期成本监审制度，定期成本监审核定的定价成本，作为制定或者调整供水价格的基础。"},{"i":29,"n":"第二十九条","txt":"供水企业应当按照定价部门的规定，每年定期如实提供上一年度生产经营情况和成本数据，并对提供资料的真实性、合法性、完整性负责。 无正当理由拒绝、延迟提供相关资料，或者提供虚假资料的，价格主管部门责令限期改正。故意瞒报、虚报相关信息并获得不当收益的，在下一个监管周期进行追溯。"},{"i":30,"n":"第三十条","txt":"定价部门制定或者调整供水价格，应当及时向社会公开制定或者调整价格的决定。"},{"i":31,"n":"第三十一条","txt":"供水企业应当在营业场所醒目位置和企业门户网站公示各类水价、延伸服务价格、代收费标准，以及文件依据、服务咨询电话、举报投诉电话，并每年定期公布上一年度取水量、供水量、售水量、售水收入、水质检测报告等相关信息。"},{"i":32,"n":"第三十二条","txt":"用户应当按照规定的水价和计量标准按时交纳水费。用户逾期不支付水费的，应当按照约定支付违约金。用户承担的水资源税、污水处理费应当在收据中单独列示。 环卫绿化、生态景观、消防等用水应当优先利用再生水，因条件限制需使用城镇供水的，应当按照实际用水量支付水费。 城镇经济困难家庭以及市政等用水，根据相关规定需要减免水费的，当地人民政府应当给予供水企业相应的水费补偿。"},{"i":33,"n":"第三十三条","txt":"供水企业的供水水质、水压应当符合《生活饮用水卫生标准》等要求。供水水质、水压不符合国家规定标准的，用户有权向城镇供水行政主管部门投诉，供水企业应当承担相应的法律和经济责任。"},{"i":34,"n":"第三十四条","txt":"各级城镇供水行政主管部门应当建立健全城镇供水水质监管体系，加强水质管理，保证安全可靠供水。"},{"i":35,"n":"第三十五条","txt":"各级城镇供水行政主管部门应当加强供水服务行为监督，对擅自停止供水、未按照规定检修供水设施或者供水设施故障报修但未及时予以检修的，依法予以处罚。"},{"i":36,"n":"第三十六条","txt":"各省、自治区、直辖市人民政府价格主管部门应当会同同级城镇供水行政主管部门根据本办法制定城镇供水价格管理实施细则。"},{"i":37,"n":"第三十七条","txt":"本办法由国家发展和改革委员会会同住房和城乡建设部负责解释。"},{"i":38,"n":"第三十八条","txt":"本办法自2021年10月1日起施行。《国家计委、建设部关于印发<城市供水价格管理办法>的通知》(计价格〔1998〕1810号)和《国家发展改革委、建设部关于修订<城市供水价格管理办法>的通知》(发改价格〔2004〕2708号)同时废止。"}],"chengzhengongshuidingjiachengbenjianshenbanfa":[{"i":1,"n":"第一条","txt":"为提高城镇供水定价的科学性、合理性，加强供水成本监管，规范供水定价成本监审行为，根据《中华人民共和国价格法》《城市供水条例》《政府制定价格成本监审办法》等有关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内组织实施城镇供水价格制定或者调整过程中的成本监审行为。"},{"i":3,"n":"第三条","txt":"本办法所称城镇供水是指城镇公共供水企业(以下称供水企业)通过一定的工程设施，将地表水、地下水进行必要的净化、消毒处理、输送，使水质水压符合国家规定的标准后供给用户使用的水。"},{"i":4,"n":"第四条","txt":"城镇供水定价成本监审工作由政府价格主管部门负责组织实施。城镇供水行政主管部门应当配合价格主管部门做好成本监审工作。"},{"i":5,"n":"第五条","txt":"城镇供水定价成本监审应当遵循以下原则： (一)合法性原则。计入定价成本的各项费用，应当符合《中华人民共和国会计法》等有关法律、法规和财务会计制度、价格监管制度的规定。 (二)相关性原则。计入定价成本的各项费用，应当与城镇供水生产经营活动相关。 (三)合理性原则。计入定价成本的各项费用，应当反映城镇供水生产经营活动正常需要。影响定价成本水平的主要技术、经济指标，应当符合国家标准、地方标准;没有国家及地方标准的，应当符合社会公允水平。"},{"i":6,"n":"第六条","txt":"城镇供水企业应当建立健全成本核算制度，完整准确记录与核算生产经营成本和收入。"},{"i":7,"n":"第七条","txt":"核定城镇供水定价成本，应当以经会计师事务所或审计、税务等部门审计(审核)的年度财务会计报告、手续齐备的会计凭证、账簿，以及供水企业提供的真实、完整、有效的其他成本相关资料为基础。"},{"i":8,"n":"第八条","txt":"城镇供水定价成本包括固定资产折旧费、无形资产摊销和运行维护费。"},{"i":9,"n":"第九条","txt":"固定资产折旧费，是指与供水业务相关的固定资产按照本办法规定的折旧方法和年限计提的费用。"},{"i":10,"n":"第十条","txt":"无形资产摊销，是指与供水业务相关的软件、土地使用权等无形资产原值在有效期内的摊销。"},{"i":11,"n":"第十一条","txt":"运行维护费，是指供水企业维持供水正常运行的费用，包括原水费、外购成品水费、动力费、材料费、修理费、人工费、其他运营费用。 (一)原水费是指供水企业为保障本区域供水服务购入原水的费用(含原水预处理费用)。 (二)外购成品水费是指供水企业为保障本区域供水服务外购成品水的费用。 (三)动力费是指供水企业直接用于原水汲取、输送、制水生产及输配净水(含二次加压调蓄)所需动力的费用。 (四)材料费是指供水企业提供供水服务所耗用的消耗性材料等费用，包括用于制水过程中的各种药剂和净化材料消耗、机物料消耗。 (五)修理费是指供水企业因自行组织大修、抢修、日常检修、事故应急发生的材料消耗、事故备品备件和委托外部社会单位检修需要企业自行购买的材料费用，以及为维持供水正常运行所进行的外包修理活动发生的检修费用，不包括企业自行组织检修发生的人工费用。 (六)人工费是指供水企业为获得职工所提供服务而给予的各种形式"},{"i":12,"n":"第十二条","txt":"下列费用不得计入城镇供水定价成本： (一)不符合《中华人民共和国会计法》等有关法律、行政法规，财务制度和国家统一的会计制度，以及价格监管制度等规定的费用。 (二)与城镇供水生产经营活动无关的费用以及虽与供水生产经营活动有关，但有专项资金来源予以补偿的费用。 (三)固定资产盘亏、毁损、出售和报废的净损失。 (四)各类捐赠、赞助、滞纳金、违约金、罚款、计提准备金和公益广告、公益宣传、各类广告费用。 (五)向上级公司或者管理部门上交的利润性质的管理费用、代上级公司或者管理部门缴纳的各项费用、向出资人支付的利润分成以及对附属单位的补助支出等。 (六)对外投资等支出。 (七)其他不得计入供水定价成本的费用。"},{"i":13,"n":"第十三条","txt":"固定资产折旧费。计入定价成本的固定资产折旧费按照可计提折旧的固定资产原值、规定的固定资产分类折旧年限，采用年限平均法核定。 (一)固定资产原值原则上按照历史成本核定。按规定进行过清产核资的，按财政或国有资产监督管理部门认定的各类固定资产价值核定;未投入实际使用的、由政府补助或社会无偿投入的，以及评估增值的部分不计提折旧。已投入使用但未经财政、国有资产管理部门认定，或未竣工决算的固定资产，可由当地价格主管部门按照有关规定合理确定。 (二)固定资产折旧采用年限平均法，按照核定的固定资产原值分类确定。折旧年限根据固定资产的性质和实际使用情况确定(详见附表)，固定资产残值率原则上按3%~5%计算，不能回收的管道残值率可按零核定，已计提完折旧仍在使用的固定资产不再计提折旧费用。"},{"i":14,"n":"第十四条","txt":"无形资产摊销。从开始使用之日起、在有效使用期限内平摊计入定价成本。其中，土地使用权费用如果已计入地面建筑物价值且无法分离的，随建筑物提取折旧;其他情况下，均按土地使用权年限分摊。其他无形资产，有明确受益期限的按受益年限分摊，未明确受益年限的按不低于10年摊销。评估增值部分不计入无形资产原值。"},{"i":15,"n":"第十五条","txt":"原水费、外购成品水费。原水费及外购成品水费原则上按照监审期间最后一年实际发生费用计入定价成本。必要时，可以对提供成品水的独立制水公司进行成本调查。"},{"i":16,"n":"第十六条","txt":"动力费、材料费、修理费。按剔除不合理因素后的供水企业监审期间年平均费用核定计入定价成本。但修理费最高原则上不得超过与供水业务相关的固定资产原值的2%;超过上限标准的，供水企业应当证明其合理性，具体数额经评估论证后确定。特殊情况下，因不可抗力等因素造成的一次性费用过高的可以分期分摊。"},{"i":17,"n":"第十七条","txt":"人工费。 (一)职工工资总额按照核定的职工人数和平均工资确定。 1.职工人数。各地区一般可以15人/万立方米(日生产能力)为定员参考上限，结合实际制定当地城镇供水行业职工人数定员上限标准。供水企业监审期间最后一年实有在岗职工人数低于定员标准上限的，按照定员标准上限和实有在岗职工人数的算术平均值核定;实有在岗职工人数超过定员标准上限的，按照定员标准上限核定。 2.职工工资。职工平均工资原则上按照监审期间最后一年在岗职工实际平均水平确定，但最高不超过统计部门公布的当地监审期间最后一年公用事业行业(电力、热力、燃气及水生产和供应业)在岗职工平均工资。 (二)工会经费、职工教育经费、职工福利费、社会保险费(包含补充医疗和补充养老保险)、住房公积金，审核计算基数原则上按监审期间最后一年企业实缴基数确定，但最高不超过核定的工资总额和当地政府规定的基数，计算比例按照不超过国家或当地政府统一规定的比例"},{"i":18,"n":"第十八条","txt":"其他运营费用。 (一)生产经营类费用。水质检测和监测费、代收手续费、计量器具检定与更换费等按剔除不合理因素后的监审期间年平均值核定。 (二)管理类费用。会议费、交通费、差旅费、业务招待费等非生产性费用按剔除不合理因素后的监审期间年平均值核定。业务招待费最高不超过监审期间供水销售年平均收入的0.5%。 (三)纳入定价成本的相关税金。按照国家现行税法规定以监审期间最后一年实际水平核定。 (四)其他费用。低值易耗品等摊销费按照规定的摊销年限，采用直线摊销法核定。"},{"i":19,"n":"第十九条","txt":"供水企业获得的政府补助，用于购买固定资产的，按照本办法第十三条规定核定;用于补助专门项目的，直接冲减该项成本;未明确规定专项用途的，应当冲减总成本。"},{"i":20,"n":"第二十条","txt":"其他业务成本应当单独核算，不计入供水定价成本。其他业务与供水业务共同使用资产、人员或者统一支付的费用，依托供水业务从事生产经营活动，以及因从事供水业务而获得政府优惠政策等，不能单独核算或者核算不合理的，应当将其他业务收入按一定比例冲减成本。该比例可以采用收入比、直接人员数量比、资产比或者其他合理方法确定。"},{"i":21,"n":"第二十一条","txt":"可计提收益的有效资产，是指供水企业投资形成的制水、输配水的工程设施设备以及其他与供水业务相关的资产，包括固定资产净值、无形资产净值和营运资本。 (一)可计提收益的固定资产净值根据监审期间最后一年可计提折旧计入定价成本的固定资产期末数所对应的账面净值核定。以下资产不得纳入可计提收益的固定资产范围： 1.与供水业务无关的、未投入实际使用的固定资产。 2.不能提供价值有效证明的固定资产。 3.用户或地方政府无偿移交，由政府补助或者社会无偿投入等投资形成的资产。 4.固定资产评估增值部分。 5.其他不应计提收益的固定资产。 (二)可计提收益的无形资产，主要包括软件、土地使用权等。可计提收益的无形资产净值，根据监审期间最后一年可摊销计入定价成本的无形资产期末数所对应的账面净值核定。 (三)可计提收益的营运资本，指供水企业为提供供水服务，除固定资产、无形资产投资以外的正常运营所需要的周转资金。可计"},{"i":22,"n":"第二十二条","txt":"供水量和漏损率。核定供水量=取水量×(1-自用水率)×(1-漏损率)。 取水量包括取用原水量和外购成品水量。原水量指供水企业实际取用的全部原水量;外购成品水量指供水企业实际从外部购入的全部成品水量。 供水企业自用水率原则上据实核定，但应当在上限标准范围之内。各地上限标准应当在水厂设计水量的5%~10%范围内，根据《室外给水设计标准》(GB50013)有关规定，区分原水水质、处理工艺和构筑物类型等因素确定。 漏损率原则上按照《城镇供水管网漏损控制及评定标准》(CJJ92)确定的一级评定标准计算，漏损率高于一级评定标准的，超出部分不得计入成本。"},{"i":23,"n":"第二十三条","txt":"本办法未规定具体核算方法或者标准的其他费用项目，低于社会公允水平的，据实核算;明显超出社会公允水平的，按照社会公允水平核算。"},{"i":24,"n":"第二十四条","txt":"供水企业应当按照供水价格成本监管要求定期向当地价格主管部门及城镇供水行政主管部门上报供水业务成本和收入等数据。供水企业应当积极配合价格主管部门实施成本监审工作，客观如实反映情况，并提供其所要求的财务报告、会计凭证、账簿、科目汇总表等相关文件资料和电子原始数据。"},{"i":25,"n":"第二十五条","txt":"供水企业应当建立健全内部关联方交易管理制度，按照社会公允水平确定关联方交易价格。"},{"i":26,"n":"第二十六条","txt":"供水企业应当自收到成本监审书面通知之日起20个工作日内，向价格主管部门或其指定的单位提供定价成本监审所需资料，并对所提供成本资料的真实性、合法性、完整性负责。"},{"i":27,"n":"第二十七条","txt":"供水企业应当按照成本监审要求，向监审人员开放查询企业各类材料的权限，及时提供情况，反馈意见。供水企业拒绝提供、未在规定时间内提供、虚假或不完整提供成本监审所需资料的，价格主管部门可以按照从低原则核定定价成本。情节严重的，可以按照上一监审周期单位供水定价成本的50%核定本监审周期供水定价成本，由此产生的定价成本减少不能在后续监审周期内进行弥补，同时将相关单位及其负责人不良信用记录纳入全国信用信息共享平台，实施失信联合惩戒。"},{"i":28,"n":"第二十八条","txt":"各省、自治区、直辖市人民政府价格主管部门应当会同同级供水行政主管部门根据本办法制定城镇供水定价成本监审具体办法或实施细则。"},{"i":29,"n":"第二十九条","txt":"本办法由国家发展和改革委员会会同住房和城乡建设部负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自2021年10月1日起施行。《国家发展改革委印发<关于做好城市供水价格调整成本公开试点工作的指导意见>和<城市供水定价成本监审办法(试行)>的通知》(发改价格〔2010〕2613号)同时废止。 附表 注：1.电子设备包括电子计算机以及电子计算机控制的数控或程控系统等; 2.简易房是指简易结构房屋，如门岗用房、存放及遮盖物品用房等; 3.各省、自治区、直辖市可以参考本表结合当地实际制定城镇供水企业各类固定资产具体折旧年限。"}],"jichusheshihegongyongshiyetexujingyingguanlibanfa":[{"i":1,"n":"第一条","txt":"为鼓励和引导社会资本参与基础设施和公用事业建设运营，提高公共服务质量和效率，保护特许经营者合法权益，激发民间投资活力，保障社会公共利益和公共安全，促进经济社会持续健康发展，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的交通运输、市政工程、生态保护、环境治理、水利、能源、体育、旅游等基础设施和公用事业领域的特许经营活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称基础设施和公用事业特许经营，是指政府采用公开竞争方式依法选择中华人民共和国境内外的法人或者其他组织作为特许经营者，通过协议明确权利义务和风险分担，约定其在一定期限和范围内投资建设运营基础设施和公用事业并获得收益，提供公共产品或者公共服务。 商业特许经营以及不涉及产权移交环节的公建民营、公办民营等，不属于本办法所称基础设施和公用事业特许经营。"},{"i":4,"n":"第四条","txt":"基础设施和公用事业特许经营是基于使用者付费的政府和社会资本合作（PPP）模式，政府就项目投资建设运营与社会资本开展合作，不新设行政许可。 特许经营者获得协议约定期限内对特定基础设施和公用事业项目进行投资建设运营并取得收益的排他性权利，同时应当按照协议约定提供符合质量效率要求的公共产品或者公共服务，并依法接受监督管理。政府鼓励并支持特许经营者提升效率、降低成本，增进社会公众福祉，禁止无法律法规依据擅自增设行政许可事项以及通过前述擅自增设的行政许可事项向特许经营者收费，增加公共产品或者公共服务成本。禁止以基础设施和公用事业特许经营名义滥用行政权力排除、限制竞争。"},{"i":5,"n":"第五条","txt":"基础设施和公用事业特许经营应当坚持公开、公平、公正，保护各方信赖利益，并遵循以下原则： （一）发挥社会资本融资、专业、技术和管理优势，提高公共服务质量效率； （二）转变政府职能，强化政府与社会资本协商合作； （三）保护社会资本合法权益，保证特许经营持续性和稳定性； （四）兼顾经营性和公益性平衡，维护公共利益； （五）根据风险性质以及特许经营各方风险管控能力，明确风险分担机制并切实执行，保障项目持续稳定实施。"},{"i":6,"n":"第六条","txt":"基础设施和公用事业特许经营应当聚焦使用者付费项目，明确收费渠道和方式，项目经营收入具备覆盖建设投资和运营成本并获取一定投资回报的条件，不因采取特许经营而额外新增地方财政未来支出责任。 前款所称使用者付费，包括特许经营者直接向用户收费，以及由政府或其依法授权机构代为向用户收费。"},{"i":7,"n":"第七条","txt":"基础设施和公用事业特许经营可以采取以下方式： （一）在一定期限内，政府授予特许经营者投资新建或改扩建、运营基础设施和公用事业，期限届满移交政府； （二）在一定期限内，政府授予特许经营者投资新建或改扩建、拥有并运营基础设施和公用事业，期限届满移交政府； （三）在一定期限内，政府将已经建成的基础设施和公用事业项目转让特许经营者运营，期限届满移交政府； （四）国家规定的其他方式。 禁止在建设工程完成后直接将项目移交政府，或者通过提前终止协议等方式变相逃避运营义务。"},{"i":8,"n":"第八条","txt":"基础设施和公用事业特许经营期限应当根据行业特点、所提供公共产品或服务需求、项目生命周期、项目建设投资和运营成本、投资回收期等综合因素确定，充分保障特许经营者合法权益。 特许经营期限原则上不超过40年，投资规模大、回报周期长的特许经营项目可以根据实际情况适当延长，法律法规另有规定的除外。"},{"i":9,"n":"第九条","txt":"国务院发展改革部门牵头做好基础设施和公用事业特许经营模式推进工作，加强政策指导。地方各级发展改革部门发挥综合协调作用，严格把关项目实施领域、范围、方案等，依法依规履行项目审批、核准或者备案职责，推动项目落地实施。 国务院有关行业主管部门应当根据国务院关于规范实施政府和社会资本合作新机制的要求，按照各自职责履行行业管理职能；涉基础设施和公用事业特许经营政策事项，应当送国务院发展改革部门充分征求意见并经评估与宏观政策取向一致，未经评估论证或者经评估论证与宏观政策取向不一致的，不应当公布实施。地方各级自然资源、生态环境、住房城乡建设、交通运输、水利、能源、金融、安全监管等有关部门应当按照政府授权以及各自职责，依法开展特许经营项目相关工作。 政府及其工作部门发生的与特许经营项目相关的收入与支出应当符合有关预算的法律、行政法规以及国家有关规定。各级财政部门应当严格执行预算管理制度，依法加强政府资"},{"i":10,"n":"第十条","txt":"地方各级人民政府应当规范推进本级政府事权范围内的特许经营项目，依法依规授权有关行业主管部门、事业单位等作为基础设施和公用事业特许经营项目实施机构（以下简称“实施机构”），负责特许经营项目筹备、实施及监管，并明确其授权内容和范围。"},{"i":11,"n":"第十一条","txt":"特许经营项目提出的主要目的，应当为发挥社会资本在经营管理、技术创新等方面的优势，促进民间投资，提高公共产品和公共服务的质量效率。 特许经营项目应当符合国民经济和社会发展规划纲要、专项规划、区域规划、国土空间规划等，并且建设运营标准和监管要求明确。"},{"i":12,"n":"第十二条","txt":"实施机构根据授权，参照可行性研究报告编写规范，牵头编制特许经营方案。特许经营方案应当包括以下内容： （一）项目名称及概述，建设背景和必要性； （二）项目建设规模、投资总额、实施进度，以及提供公共产品或公共服务的标准等基本经济技术指标； （三）投资回报、价格及其测算； （四）项目可行性及特许经营可行性论证； （五）特许经营者应当具备的条件及选择方式； （六）政府承诺和保障； （七）特许经营涉及的国有资产管理要求，以及特许经营期限届满后资产处置方式； （八）应当明确的其他事项。 实施政府定价的特许经营项目，特许经营方案中有关投资回报、价格及其测算应当征求地方价格主管部门意见。 特许经营期限拟超过40年的，应当在特许经营方案中充分论证并随特许经营方案一并报请批准。 实施机构应当保证特许经营项目的完整性和连续性。"},{"i":13,"n":"第十三条","txt":"实施机构可以委托具有相应能力和经验的第三方机构，开展特许经营可行性论证，完善特许经营方案。"},{"i":14,"n":"第十四条","txt":"本办法所称特许经营可行性论证，应当从项目全生命周期成本、产出或服务效果、建设运营效率、风险防范控制等方面，特别是对采取特许经营模式和传统政府投资模式在投入产出、经济社会效益等方面进行比较分析，对项目是否适合采用特许经营模式进行论证。此外，还应当对相关领域市场发育程度、企业建设运营能力状况和参与意愿、项目产品服务使用者支付意愿和能力进行评估，确保特许经营模式可以落地实施。"},{"i":15,"n":"第十五条","txt":"特许经营方案按照政府投资项目审批权限和要求，报投资主管部门或者其他有关部门审核，合理控制项目建设内容和规模，明确项目产出方案。 审核特许经营方案时，应当对项目是否适合采取特许经营模式进行认真比较和论证，根据职责分工征求有关部门意见，必要时可以委托专业咨询机构进行评估。"},{"i":16,"n":"第十六条","txt":"实施机构根据经审定的特许经营方案，应当通过招标、谈判等公开竞争方式选择特许经营者。"},{"i":17,"n":"第十七条","txt":"实施机构应当在招标文件、谈判文件等公开选择特许经营者的文件中载明是否要求成立特许经营项目公司。"},{"i":18,"n":"第十八条","txt":"鼓励民营企业通过直接投资或者独资、控股、参股等方式积极参与特许经营项目。实施机构应当根据国务院发展改革部门制定的支持民营企业参与的新建及改扩建特许经营项目清单，结合项目实际情况，确定民营企业参与的具体方式。 对清单所列领域以外符合条件的传统及新型基础设施和公用事业项目，可以参照清单精神，探索采取特许经营模式，以适宜方式积极鼓励民营企业参与。 外商投资企业参照民营企业适用前款规定。"},{"i":19,"n":"第十九条","txt":"实施机构应当根据本办法第十六条规定，公平择优选择具有相应管理经验、专业能力、融资实力以及信用状况良好的法人或者其他组织作为特许经营者，将项目运营方案、收费单价、特许经营期限等作为选择特许经营者的重要标准。鼓励金融机构与参与竞争的法人或其他组织共同制定投融资方案。 特许经营者选择应当符合内外资准入等有关法律、行政法规规定。 依法选定的特许经营者，应当向社会公示。"},{"i":20,"n":"第二十条","txt":"实施机构应当与依法选定的特许经营者签订特许经营协议。 需要成立项目公司的，实施机构应当与依法选定的特许经营者签订初步协议，约定其在规定期限内注册成立项目公司，并与项目公司签订特许经营协议。 特许经营协议应当主要包括以下内容： （一）项目名称、内容； （二）特许经营方式、区域、范围和期限； （三）如成立项目公司，明确项目公司的经营范围、注册资本、股东出资方式、出资比例、股权转让等； （四）所提供产品或者服务的数量、质量和标准； （五）特许经营项目建设、运营期间的资产权属，以及相应的维护和更新改造； （六）监测评估； （七）投融资期限和方式； （八）收益取得方式，价格和收费标准的确定方法以及调整程序； （九）履约担保； （十）特许经营期内的风险分担； （十一）因法律法规、标准规范、国家政策等管理要求调整变化对特许经营者提出的相应要求，以及成本承担方式； （十二）政府承诺和保障； （十三）应"},{"i":21,"n":"第二十一条","txt":"选定的特许经营者及其投融资、建设责任不得调整。确需调整的，应当重新履行特许经营者选择程序。"},{"i":22,"n":"第二十二条","txt":"特许经营协议根据有关法律、行政法规和国家规定，约定特许经营者通过向用户收费、获得与特许经营项目相关的其他开发经营权益等方式取得收益。 由政府向用户统一收取后再向特许经营者支付的费用，政府应当主动公开收支明细，保证专款专用，按照特许经营协议约定定期支付。 政府可以在严防新增地方政府隐性债务、符合法律法规和有关政策规定要求的前提下，按照一视同仁的原则，在项目建设期对使用者付费项目给予政府投资支持；政府付费只能按规定补贴运营，不能补贴建设成本。除此之外，不得通过可行性缺口补助、承诺保底收益率、可用性付费等任何方式使用财政资金弥补项目建设投资和运营成本。将专项债券用作项目资本金的，应当按照国家关于资本金管理的规定和专项债券有关规定执行。"},{"i":23,"n":"第二十三条","txt":"特许经营协议应当明确价格或收费的确定和调整机制。特许经营项目价格或收费应当依据相关法律、行政法规、国家价格政策规定和特许经营协议约定予以确定和调整。 特许经营项目中实行政府定价的价格或者收费，应当执行有关定价机关制定的价格或者收费标准。"},{"i":24,"n":"第二十四条","txt":"政府可以在特许经营协议中就防止不必要的同类竞争性项目建设、有关配套公共服务和基础设施的提供等内容作出承诺，但不得承诺固定投资回报和其他法律、行政法规禁止的事项。"},{"i":25,"n":"第二十五条","txt":"政府采用资本金注入方式投资的特许经营项目，应当按照《政府投资条例》有关规定，履行审批手续。企业投资的特许经营项目，应当按照《企业投资项目核准和备案管理条例》有关规定，履行核准或者备案手续。实施机构应当协助特许经营者办理相关手续。 依法选定的特许经营者如果与项目前期办理审批、用地、规划等手续时的项目法人不一致的，应当依法办理项目法人变更手续，实施机构应当予以必要支持和便利。"},{"i":26,"n":"第二十六条","txt":"完成审批、核准或备案手续的项目如发生变更建设地点、调整主要建设内容、调整建设标准等重大情形，应报请原审批、核准机关重新履行项目审核程序，或者重新备案，必要时应重新开展特许经营模式可行性论证与特许经营方案审核工作。"},{"i":27,"n":"第二十七条","txt":"国家鼓励金融机构为特许经营项目提供财务顾问、融资顾问、银团贷款等金融服务。特许经营项目可以依法合规利用预期收益质押贷款，将项目相关收益作为还款来源。鼓励保险资金通过债权、股权、资产证券化产品等多种方式为特许经营项目提供多元化资金支持。 特许经营项目融资应当依法保护各方合法权益，稳妥处置债权债务关系。不得承诺以各类财政资金担保或者作为还款来源，防止新增地方政府隐性债务。"},{"i":28,"n":"第二十八条","txt":"积极支持符合条件的特许经营项目发行基础设施领域不动产投资信托基金（REITs）。鼓励符合条件的特许经营项目公司进行结构化融资，发行项目收益票据、不动产信托资产支持票据和资产证券化产品等。 国家鼓励特许经营项目按照市场化方式采用成立私募基金，引入战略投资者，发行企业债券、公司债券、非金融企业债务融资工具等方式拓宽投融资渠道。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府有关部门、特许经营实施机构、金融机构依法执行本办法规定的投融资支持措施，不应对不同所有制特许经营者区别对待。"},{"i":30,"n":"第三十条","txt":"特许经营协议各方当事人应当遵循诚实信用原则，按照约定全面履行义务。实施机构应当全面、按期履行签订特许经营协议、协调开展价格调整、支付代收的用户付费、监测验收等义务；特许经营者应当按照特许经营协议约定的数量、质量、标准、期限等，提供公共产品和公共服务，并履行协议约定的其他义务。 除法律、行政法规另有规定外，实施机构和特许经营者任何一方不履行特许经营协议约定义务或者履行义务不符合约定要求的，应当根据协议继续履行、采取补救措施或者赔偿损失。"},{"i":31,"n":"第三十一条","txt":"依法保护特许经营者合法权益。任何单位或者个人不得违反法律、行政法规和本办法规定，干涉特许经营者合法经营活动。"},{"i":32,"n":"第三十二条","txt":"特许经营者应当根据特许经营协议，执行有关特许经营项目投融资安排，确保相应资金或资金来源落实。"},{"i":33,"n":"第三十三条","txt":"特许经营项目涉及新建或改扩建有关基础设施和公用事业的，应当符合国土空间规划、有关专项规划、土地管理、环境保护、质量管理、安全生产等有关法律、行政法规、法定规划规定的规划条件和建设标准。"},{"i":34,"n":"第三十四条","txt":"特许经营者应当根据有关法律、行政法规、标准规范和特许经营协议，提供优质、持续、高效、安全的公共产品或者公共服务。 特许经营者在保障项目质量和产品服务质量的前提下，通过降低成本、提升效率、积极创新等方式产生的效益，除协议另有约定外，归特许经营者所有。"},{"i":35,"n":"第三十五条","txt":"特许经营各方应当遵守国有资产管理制度，规范特许经营项目有关阶段和环节涉及的国有资产管理，防止国有资产流失。 特许经营者应当按照技术规范，定期对特许经营项目设施进行检修和保养，保证设施运转正常及经营期限届满后资产按规定进行移交。"},{"i":36,"n":"第三十六条","txt":"特许经营者对涉及国家安全的事项负有保密义务，并应当建立和落实相应保密管理制度。 实施机构、有关部门及其工作人员对在特许经营活动和监督管理工作中知悉的特许经营者商业秘密负有保密义务。"},{"i":37,"n":"第三十七条","txt":"实施机构和特许经营者应当对特许经营项目建设、运营、维修、保养过程中有关资料，按照有关规定进行归档保存。"},{"i":38,"n":"第三十八条","txt":"实施机构应当按照特许经营协议严格履行有关义务，为特许经营者建设运营特许经营项目提供便利和支持，提高公共服务水平。 行政区划调整，政府换届、部门调整和负责人变更，不得影响特许经营协议履行。"},{"i":39,"n":"第三十九条","txt":"因法律、行政法规修改，或者政策调整损害特许经营者预期利益，或者根据公共利益需要，要求特许经营者提供协议约定以外的产品或服务的，应当依据特许经营协议约定或者协商达成补充协议，给予特许经营者公平合理补偿。法律法规有专门规定的，从其规定。"},{"i":40,"n":"第四十条","txt":"在特许经营协议有效期内，协议内容确需变更的，协议当事人应当在协商一致基础上签订补充协议。如协议变更可能对特许经营项目的存续债务产生重大影响的，应当事先征求债权人同意。特许经营项目涉及直接融资行为的，应当及时做好相关信息披露。特许经营项目涉及运营主体实质性变更、股权移交等重大事项的，应当及时书面告知相关行业主管部门。 特许经营期限届满后确有必要延长的，按照有关规定经充分评估论证，协商一致并报批准后，可以延长。"},{"i":41,"n":"第四十一条","txt":"在特许经营期限内，因特许经营协议一方严重违约或不可抗力等原因，导致特许经营者无法继续履行协议约定义务，或者出现特许经营协议约定的提前终止协议情形的，在与债权人协商一致后，可以提前终止协议。 因政府方原因导致特许经营协议提前终止的，政府应当收回特许经营项目，并根据实际情况和协议约定给予原特许经营者公平合理补偿。 因特许经营者原因导致特许经营协议提前终止的，特许经营者应当按照特许经营协议约定履行有关资产移交、债务清偿、违约赔偿责任，并在清算移交期间配合政府维持有关公共服务和公共产品的持续性和稳定性。"},{"i":42,"n":"第四十二条","txt":"特许经营期限届满终止或提前终止的，协议当事人应当按照特许经营协议约定，以及有关法律、行政法规和规定办理有关设施、资料、档案等的性能测试、评估、移交、接管、验收等手续。"},{"i":43,"n":"第四十三条","txt":"特许经营期限届满终止或者提前终止，对该基础设施和公用事业继续采用特许经营方式的，实施机构应当根据本办法规定重新选择特许经营者；同等条件下，可以优先选择原特许经营者。 特许经营期限内因确需改扩建等原因需要重新选择特许经营者的，同等条件下可以优先选择原特许经营者。 新的特许经营者选定之前，实施机构和原特许经营者应当制定预案，保障公共产品或公共服务的持续稳定提供。"},{"i":44,"n":"第四十四条","txt":"县级以上人民政府有关部门应当根据各自职责，对特许经营者执行法律、行政法规、行业标准、产品或服务技术规范，以及其他有关监管要求进行监督管理，并依法依规加强成本调查监审。 县级以上审计机关应当依法对特许经营活动进行审计。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府及其有关部门应当根据法律、行政法规和国务院决定保留的行政审批项目对特许经营进行监督管理，不得以实施特许经营为名违法增设行政审批项目或审批环节。"},{"i":46,"n":"第四十六条","txt":"实施机构应当根据特许经营协议和相关行业管理规定，会同有关方面定期对特许经营项目建设运营情况进行监测分析，定期开展运营评价，并按相关规定开展相应的绩效评价，并建立根据绩效评价结果、按照特许经营协议约定对价格进行调整的机制，保障所提供公共产品或公共服务的质量和效率；同时，结合特许经营者的经营和财务状况，评估项目潜在风险。 实施机构应当将社会公众意见作为监测分析和运营评价的重要内容。"},{"i":47,"n":"第四十七条","txt":"县级以上人民政府应当将特许经营有关政策措施、特许经营项目实施机构等相关单位及其职责等信息向社会公开。 实施机构应当将特许经营方案、特许经营者选择结果、特许经营协议主要内容及其变更或终止、政府投资支持、公共产品或服务标准、监测分析和运营评价结果等信息，依托全国投资项目在线审批监管平台，及时向社会公开。 特许经营者应当将项目每季度建设运营情况、经审计的年度财务报表、有关会计数据、财务核算、资产管理情况和其他有关财务指标等信息，通过适当方式向社会公开，并依法接受年度财务审计。 前款规定的应当公开的信息，不包括依法确定为国家秘密的信息，以及商业秘密和个人隐私信息。"},{"i":48,"n":"第四十八条","txt":"社会公众有权对特许经营活动进行监督，向有关监管部门投诉，或者向实施机构和特许经营者提出意见建议。"},{"i":49,"n":"第四十九条","txt":"特许经营者应当对特许经营协议约定服务区域内所有用户普遍地、无歧视地提供公共产品或公共服务，不得对新增用户实行差别待遇。"},{"i":50,"n":"第五十条","txt":"实施机构和特许经营者应当制定突发事件应急预案，按规定报有关部门。突发事件发生后，及时启动应急预案，保障公共产品或公共服务的正常提供。"},{"i":51,"n":"第五十一条","txt":"特许经营者因不可抗力等原因确实无法继续履行特许经营协议的，实施机构应当采取措施，保证持续稳定提供公共产品或公共服务。"},{"i":52,"n":"第五十二条","txt":"实施机构和特许经营者就特许经营协议履行发生争议的，应当协商解决。协商达成一致的，应当签订补充协议并遵照执行。"},{"i":53,"n":"第五十三条","txt":"实施机构和特许经营者就特许经营协议中的专业技术问题发生争议的，可以共同聘请专家或第三方机构进行调解。调解达成一致的，应当签订补充协议并遵照执行。"},{"i":54,"n":"第五十四条","txt":"特许经营者认为行政机关不依法订立、不依法履行、未按照约定履行或者违法变更、解除特许经营协议的，有陈述、申辩的权利，并可以依法申请行政复议或者提起行政诉讼。 特许经营项目相关协议各方因协议约定的权利义务产生的民商事争议，可以依法申请仲裁或者提起民事诉讼。"},{"i":55,"n":"第五十五条","txt":"特许经营协议存续期间发生争议，当事各方在争议解决过程中，应当继续履行特许经营协议义务，保证公共产品或公共服务的持续性和稳定性。"},{"i":56,"n":"第五十六条","txt":"实施机构、有关行政主管部门不履行法定职责、干预特许经营者正常经营活动的，依法追究有关责任；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"公职人员在特许经营管理服务过程中有下列行为之一，依据公职人员政务处分有关法律规定，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职；构成犯罪的，依法追究刑事责任： （一）违反规定向特许经营者收取、摊派财物的； （二）干预特许经营者正常经营活动，故意刁难、吃拿卡要的； （三）在特许经营管理服务活动中态度恶劣粗暴，造成不良后果或者影响的； （四）不按照本办法规定公开特许经营项目有关信息，造成不良后果或者影响的； （五）在特许经营者选择程序中设置不合理条件限制或排斥竞争，对不同所有制经营主体实行歧视待遇的； （六）其他侵犯特许经营管理服务对象利益的行为，造成不良后果或者影响的。 有前款第一项、第二项和第五项行为，情节特别严重的，予以开除。"},{"i":58,"n":"第五十八条","txt":"公职人员在特许经营管理服务过程中有下列行为之一，造成不良后果或者影响的，依据公职人员政务处分有关法律规定，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除；构成犯罪的，依法追究刑事责任： （一）滥用职权，危害国家利益、社会公共利益或者侵害公民、法人、其他组织合法权益的； （二）不履行或者不正确履行职责，玩忽职守，贻误工作的； （三）工作中变相增设审批手续、审批环节、审批条件，违规延长审批时限或提出不合理要求，存在形式主义、官僚主义行为的； （四）工作中有弄虚作假，误导、欺骗行为的； （五）泄露特许经营项目相关国家秘密、工作秘密，或者泄露因履行特许经营管理服务职责掌握的商业秘密、个人隐私的。 公职人员因前款规定行为导致特许经营协议无法履行或者不正常中止，影响公共产品或者公共服务持续性、稳定性的，参照前款规定予以处分。"},{"i":59,"n":"第五十九条","txt":"违反本办法第二十二条第二款规定，截留、挪用、坐收坐支由政府统一收取的特许经营项目用户付费款额，导致未能按特许经营协议约定向特许经营者支付服务费的，应当对有关责任人员依法予以处分。特许经营项目实施机构应当督促尽快补齐拖欠款额，造成损失的，按照特许经营协议约定补偿或者赔偿。"},{"i":60,"n":"第六十条","txt":"特许经营者违反法律、行政法规和国家强制性标准，严重危害公共利益，造成国有资产流失或者造成重大质量、安全事故或者突发环境事件的，有关部门应当责令限期改正并依法予以行政处罚；拒不改正、情节严重的，可以终止特许经营协议；构成犯罪的，依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"以欺骗、贿赂等不正当手段取得特许经营项目的，应当依法收回特许经营项目，向社会公开。"},{"i":62,"n":"第六十二条","txt":"县级以上人民政府有关部门应当对特许经营者及其从业人员的违法违规行为建立信用记录，纳入全国信用信息共享平台。对严重违法失信行为依法予以曝光，并会同有关部门依法依规实施联合惩戒。 完善政府诚信履约机制，将政府机构特许经营协议履行情况纳入政务诚信考核评价体系，有关违约失信行为依据国务院社会信用体系建设牵头部门制定的办法予以认定和惩戒。"},{"i":63,"n":"第六十三条","txt":"社会公众、特许经营者认为特许经营项目参与方违反本办法规定的行为损害自身合法权益的，可以依法向有监督管理职能的有关行业主管部门投诉。无法确定行业主管部门的，可以向特许经营项目所在地人民政府指定的特许经营综合协调部门投诉。投诉应当有明确的请求和必要的证明材料。收到投诉的部门应当依法处理投诉，维护投诉人合法权益。投诉处理期间不停止特许经营协议履行。"},{"i":64,"n":"第六十四条","txt":"基础设施和公用事业特许经营涉及国家安全审查的，按照国家有关规定执行。 2023年2月政府和社会资本合作项目清理核查前未完成招标采购程序的特许经营项目，以及后续新实施的特许经营项目，按本办法执行，有关政策规定与本办法不一致的，以本办法为准。"},{"i":65,"n":"第六十五条","txt":"法律、行政法规对基础设施和公用事业特许经营另有规定的，从其规定。"},{"i":66,"n":"第六十六条","txt":"本办法由国务院发展改革部门会同有关部门负责解释。"},{"i":67,"n":"第六十七条","txt":"本办法自2024年5月1日起施行，原《基础设施和公用事业特许经营管理办法》（国家发展改革委等6部委2015年第25号令）同时废止。"}],"jingneiwaiziyinhangwaizhaiguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进境内中、外资银行公平竞争，有效控制外债规模，防范外债风险，根据《中华人民共和国外资金融机构管理条例》、《中华人民共和国外汇管理条例》和有关外债管理规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称外资银行是指按照《中华人民共和国外资金融机构管理条例》及相关法律法规在中国境内设立的外资独资银行、中外合资银行和外国银行分行。"},{"i":3,"n":"第三条","txt":"国家对境内外资银行的外债实行总量控制。境内外资银行的外债包括境外借款、境外同业拆入、境外同业存款、境外联行和附属机构往来(负债方)、非居民存款和其他形式的对外负债。"},{"i":4,"n":"第四条","txt":"国家发展和改革委员会(下称“国家发展改革委”)会同中国银行业监督管理委员会(下称“银监会”)、国家外汇管理局(下称“外汇局”)，根据国民经济和社会发展需要、国际收支状况和外债承受能力，以及境内外资银行的资产负债状况和运营资金需求等，合理确定境内外资银行外债总量以及中长期和短期外债结构调控目标。"},{"i":5,"n":"第五条","txt":"境内外资银行借用外债，签约期限在1年期以上(不含1年期)的中长期外债，由国家发展改革委按年度核定发生额;签约期限在1年期以下的短期外债，由外汇局核定余额。"},{"i":6,"n":"第六条","txt":"每年2月底之前，境内外资银行须分别向国家发展改革委或外汇局提出关于本年度中长期外债发生额或短期外债余额的申请。其中，外资独资银行、中外合资银行分别通过商业注册所在地的发展改革委或外汇局的分支机构逐级向国家发展改革委或外汇局提出申请;外国银行分行由在中国境内的主报告行直接向国家发展改革委或外汇局提出申请。没有主报告行的，应通过商业注册所在地的发展改革委或外汇局的分支机构逐级向国家发展改革委或外汇局提出申请。"},{"i":7,"n":"第七条","txt":"境内外资银行申请年度外债总额，需分别向国家发展改革委或外汇局提供下列材料： (一)借用中长期或短期外债的申请报告，内容包括上年度的业务经营状况、资金来源和运用情况、所申请外债额度的依据和资金用途等。 (二)境外总行或地区管理部批准的对中国境内债务人的年度授信限额文件。 (三)外资独资银行、中外合资银行应提供报送银监会的上年度境内合并资产负债表和损益表。外国银行分行应提供报送银监会的分行上年度资产负债表和损益表，以及境内营业性分支机构上年度合并资产负债表和损益表。 (四)与申请人流动性需要或资金用途有关的证明材料。"},{"i":8,"n":"第八条","txt":"国家发展改革委、外汇局根据境内外资银行的上年度外债借用情况、其境外总行或地区管理部批准的本年度对中国境内债务人的年度授信限额、境内贷款项目需求(中长期外债)及流动性需要(短期外债)，分别核定境内外资银行本年度中长期外债发生额和短期外债余额。境内外资银行在本年度新借入的中长期外债不得超过国家发展改革委核定的额度;本年度内任一时点的短期外债余额不得超过外汇局核定的余额。"},{"i":9,"n":"第九条","txt":"外债总额确定后，境内外资银行可以根据业务需要在年度内向国家发展改革委或外汇局申请进行一次调整。国家发展改革委或外汇局根据情况决定是否批准。"},{"i":10,"n":"第十条","txt":"境内外资银行向境内机构发放外汇贷款按照国内外汇贷款方式管理。除出口押汇外，境内外资银行向境内机构发放的外汇贷款不得结汇。"},{"i":11,"n":"第十一条","txt":"境内外资银行对外提供担保，按对外担保进行管理;境内机构为境内债务人向境内外资银行提供担保按国内担保进行管理。"},{"i":12,"n":"第十二条","txt":"境内外资银行借用的外债资金不得结汇，还本付息不得购汇。境内外资银行办理其外债项下还本付息不需要外汇局核准。 经外汇局批准，境内机构可以选择境内外资银行开立外债项下专用账户。"},{"i":13,"n":"第十三条","txt":"外汇局负责对境内外资银行外债和国内外汇贷款的统计、监测工作。境内外资银行应于每月初5个工作日内向注册地外汇局分支机构报送外债统计数据，并按照国内外汇贷款的有关规定向当地外汇局报送国内外汇贷款相关信息。"},{"i":14,"n":"第十四条","txt":"外汇局对境内外资银行借用外债情况和发放外汇贷款情况进行定期和不定期现场或非现场检查。凡违反本办法规定的，外汇局可根据《中华人民共和国外汇管理条例》及相关法律法规进行处罚。"},{"i":15,"n":"第十五条","txt":"本办法由国家发展改革委、人民银行负责解释。此前其他规定与本办法有抵触的，以本办法为准。"},{"i":16,"n":"第十六条","txt":"本办法自颁布之日起30日后施行。"}],"waizhaiguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为加强外债管理，规范举借外债行为，提高外债资金使用效益，防范外债风险，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称“外债”，是指境内机构对非居民承担的以外币表示的债务。"},{"i":3,"n":"第三条","txt":"本办法所称“境内机构”，是指在中国境内依法设立的常设机构，包括但不限于政府机关、金融境内机构、企业、事业单位和社会团体。"},{"i":4,"n":"第四条","txt":"本办法所称“非居民”，是指中国境外的机构、自然人及其在中国境内依法设立的非常设机构。"},{"i":5,"n":"第五条","txt":"按照债务类型划分，外债分为外国政府贷款、国际金融组织贷款和国际商业贷款。 (一)外国政府贷款，是指中国政府向外国政府举借的官方信贷; (二)国际金融组织贷款，是指中国政府向世界银行、亚洲开发银行、联合国农业发展基金会和其他国际性、地区性金融机构举借的非商业性信贷; (三)国际商业贷款，是指境内机构向非居民举借的商业性信贷。包括： 1、向境外银行和其他金融机构借款; 2、向境外企业、其他机构和自然人借款; 3、境外发行中长期债券(含可转换债券)和短期债券(含商业票据、大额可转让存单等); 4、买方信贷、延期付款和其它形式的贸易融资; 5、国际融资租赁; 6、非居民外币存款; 7、补偿贸易中用现汇偿还的债务; 8、其它种类国际商业贷款。"},{"i":6,"n":"第六条","txt":"按照偿还责任划分，外债分为主权外债和非主权外债。 (一)主权外债，是指由国务院授权机构代表国家举借的、以国家信用保证对外偿还的外债。 (二)非主权外债，是指除主权外债以外的其它外债。"},{"i":7,"n":"第七条","txt":"本办法所称“对外担保”，是指境内机构依据《中华人民共和国担保法》，以保证、抵押或质押方式向非居民提供的担保。 对外担保形成的潜在对外偿还义务为或有外债。"},{"i":8,"n":"第八条","txt":"国家对各类外债和或有外债实行全口径管理。举借外债、对外担保、外债资金的使用和偿还须符合国家有关法律、法规和本办法的规定。"},{"i":9,"n":"第九条","txt":"国家发展计划委员会、财政部和国家外汇管理局是外债管理部门。"},{"i":10,"n":"第十条","txt":"国家发展计划委员会会同有关部门根据国民经济和社会发展需要，以及国际收支状况和外债承受能力，制定国家借用外债计划，合理确定全口径外债的总量和结构调控目标。"},{"i":11,"n":"第十一条","txt":"国家根据外债类型、偿还责任和债务人性质，对举借外债实行分类管理。"},{"i":12,"n":"第十二条","txt":"国际金融组织贷款和外国政府贷款由国家统一对外举借。 国家发展计划委员会会同财政部等有关部门制定世界银行、亚洲开发银行、联合国农业发展基金会和外国政府贷款备选项目规划，财政部根据规划组织对外谈判、磋商、签订借款协议和对国内债务人直接或通过有关金融机构转贷。其中，世界银行、亚洲开发银行、联合国农业发展基金会和重点国别外国政府贷款备选项目规划须经国务院批准。"},{"i":13,"n":"第十三条","txt":"财政部代表国家在境外发行债券由财政部报国务院审批，并纳入国家借用外债计划。其他任何境内机构在境外发行中长期债券均由国家发展计划委员会会同国家外汇管理局审核后报国务院审批;在境外发行短期债券由国家外汇管理局审批，其中设定滚动发行的，由国家外汇管理局会同国家发展计划委员会审批。"},{"i":14,"n":"第十四条","txt":"国家对国有商业银行举借中长期国际商业贷款实行余额管理，余额由国家发展计划委员会会同有关部门审核后报国务院审批。"},{"i":15,"n":"第十五条","txt":"境内中资企业等机构举借中长期国际商业贷款，须经国家发展计划委员会批准。"},{"i":16,"n":"第十六条","txt":"国家对境内中资机构举借短期国际商业贷款实行余额管理，余额由国家外汇管理局核定。"},{"i":17,"n":"第十七条","txt":"国家对境内外资金融机构举借外债实行总量控制，具体办法另行制定。"},{"i":18,"n":"第十八条","txt":"外商投资企业举借的中长期外债累计发生额和短期外债余额之和应当控制在审批部门批准的项目总投资和注册资本之间的差额以内。 在差额范围内，外商投资企业可自行举借外债。超出差额的，须经原审批部门重新核定项目总投资。"},{"i":19,"n":"第十九条","txt":"境内机构对外担保应当遵守国家法律、法规和外汇管理部门的有关规定。"},{"i":20,"n":"第二十条","txt":"境内机构不得为非经营性质的境外机构提供担保。"},{"i":21,"n":"第二十一条","txt":"未经国务院批准，任何政府机关、社会团体、事业单位不得举借外债或对外担保。"},{"i":22,"n":"第二十二条","txt":"境内机构对外签订借款合同或担保合同后，应当依据有关规定到外汇管理部门办理登记手续。国际商业贷款借款合同或担保合同须经登记后方能生效。"},{"i":23,"n":"第二十三条","txt":"外债资金应当主要用于经济发展和存量外债的结构调整。"},{"i":24,"n":"第二十四条","txt":"国际金融组织贷款和外国政府贷款等中长期国外优惠贷款重点用于基础性和公益性建设项目，并向中西部地区倾斜。"},{"i":25,"n":"第二十五条","txt":"中长期国际商业贷款重点用于引进先进技术和设备，以及产业结构和外债结构调整。"},{"i":26,"n":"第二十六条","txt":"境内企业所借中长期外债资金，应当严格按照批准的用途合理使用，不得挪作他用。确需变更用途的，应当按照原程序报批。"},{"i":27,"n":"第二十七条","txt":"境内企业所借短期外债资金主要用作流动资金，不得用于固定资产投资等中长期用途。"},{"i":28,"n":"第二十八条","txt":"使用外债资金的固定资产投资项目应当实行项目法人责任制，由项目法人对外债资金的使用效益负责。 依据《中华人民共和国招标投标法》和国外贷款机构有关规定需要进行招标采购的，应当严格按照规定执行。"},{"i":29,"n":"第二十九条","txt":"外债管理部门负责对外债资金使用进行管理和监督。"},{"i":30,"n":"第三十条","txt":"国家发展计划委员会依法依规对使用外债资金的国家重大建设项目进行监督管理。"},{"i":31,"n":"第三十一条","txt":"主权外债由国家统一对外偿还。主权外债资金由财政部直接或通过金融机构转贷给国内债务人的，国内债务人应当对财政部或转贷金融机构承担偿还责任。"},{"i":32,"n":"第三十二条","txt":"非主权外债由债务人自担风险、自行偿还。"},{"i":33,"n":"第三十三条","txt":"债务人可以用自有外汇资金偿还外债，也可经外汇管理部门核准用人民币购汇偿还外债。"},{"i":34,"n":"第三十四条","txt":"债务人无法偿还的外债，有担保人的，应当由担保人负责偿还。"},{"i":35,"n":"第三十五条","txt":"担保人按照担保合同规定需要履行对外代偿义务时，应当到外汇管理部门办理对外担保履约核准手续。"},{"i":36,"n":"第三十六条","txt":"债务人应当加强外债风险管理，适时调整和优化债务结构。 在不扩大原有外债规模的前提下，经国家发展计划委员会核准，债务人可以通过借入低成本外债、偿还高成本外债等方式，降低外债成本，优化债务结构，其中，涉及主权外债的，需经财政部核准。"},{"i":37,"n":"第三十七条","txt":"债务人可以保值避险为目的，委托具有相关资格的金融机构运用金融工具规避外债的汇率和利率风险。"},{"i":38,"n":"第三十八条","txt":"外债管理部门根据国家法律、法规和本办法有关规定，对外债和对外担保实施监管。"},{"i":39,"n":"第三十九条","txt":"外债管理部门履行监管职责时，有权要求债务人和相关单位提供有关资料，检查有关帐目和资产。"},{"i":40,"n":"第四十条","txt":"境内机构举借外债或对外担保时，未履行规定的审批手续或未按规定进行登记的，其对外签订的借款合同或担保合同不具有法律约束力。"},{"i":41,"n":"第四十一条","txt":"不以借款合同或担保合同等形式体现，但在实质上构成对外偿还义务或潜在对外偿还义务的对外借款或担保，须按照本办法纳入外债监管。"},{"i":42,"n":"第四十二条","txt":"禁止违反利益共享、风险共担原则，以保证外商直接投资固定回报等方式变相举借外债。"},{"i":43,"n":"第四十三条","txt":"未经外债管理部门批准，境外中资企业不得将其自身承担的债务风险和偿债责任转移到境内。"},{"i":44,"n":"第四十四条","txt":"经营外汇业务的金融机构在为境内机构开立外汇、外债账户和处理外汇资金往来业务时，发现违反本办法规定的行为，应当及时向有关外债管理部门报告，并协助外债管理部门进行调查。"},{"i":45,"n":"第四十五条","txt":"外债管理部门应当掌握外债动态，建立和完善全口径外债监测预警机制。"},{"i":46,"n":"第四十六条","txt":"国家外汇管理局负责外债的统计监测，定期公布外债统计数据。"},{"i":47,"n":"第四十七条","txt":"境内机构违反本办法规定举借外债或对外担保的，由其主管部门对直接负责的主管人员和其他直接责任人员依法给予相应的行政处分。构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"外债管理部门的工作人员徇私舞弊、滥用职权或玩忽职守，由其所在部门依法给予行政处分。构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"境内机构向香港、澳门特别行政区和台湾地区的机构举借债务或提供担保，比照本办法进行管理。"},{"i":50,"n":"第五十条","txt":"外债管理部门应当依据本办法，制定和完善有关实施细则。"},{"i":51,"n":"第五十一条","txt":"本办法由国家发展计划委员会、财政部和国家外汇管理局负责解释。"},{"i":52,"n":"第五十二条","txt":"本办法自2003年3月1日起施行。"}],"waishangtouzizhunrutebieguanlicuoshi-2":[],"waishangtouzizhunrutebieguanlicuoshi-3":[],"waishangtouzizhunrutebieguanlicuoshi":[],"waishangtouzianquanshenchabanfa-2":[{"i":1,"n":"第一条","txt":"为了适应推动形成全面开放新格局的需要，在积极促进外商投资的同时有效预防和化解国家安全风险，根据《中华人民共和国外商投资法》《中华人民共和国国家安全法》和相关法律，制定本办法。"},{"i":2,"n":"第二条","txt":"对影响或者可能影响国家安全的外商投资，依照本办法的规定进行安全审查。 本办法所称外商投资，是指外国投资者直接或者间接在中华人民共和国境内(以下简称境内)进行的投资活动，包括下列情形： (一)外国投资者单独或者与其他投资者共同在境内投资新建项目或者设立企业; (二)外国投资者通过并购方式取得境内企业的股权或者资产; (三)外国投资者通过其他方式在境内投资。"},{"i":3,"n":"第三条","txt":"国家建立外商投资安全审查工作机制(以下简称工作机制)，负责组织、协调、指导外商投资安全审查工作。 工作机制办公室设在国家发展改革委，由国家发展改革委、商务部牵头，承担外商投资安全审查的日常工作。"},{"i":4,"n":"第四条","txt":"下列范围内的外商投资，外国投资者或者境内相关当事人(以下统称当事人)应当在实施投资前主动向工作机制办公室申报： (一)投资军工、军工配套等关系国防安全的领域，以及在军事设施和军工设施周边地域投资; (二)投资关系国家安全的重要农产品、重要能源和资源、重大装备制造、重要基础设施、重要运输服务、重要文化产品与服务、重要信息技术和互联网产品与服务、重要金融服务、关键技术以及其他重要领域，并取得所投资企业的实际控制权。 前款第二项所称取得所投资企业的实际控制权，包括下列情形： (一)外国投资者持有企业50%以上股权; (二)外国投资者持有企业股权不足50%，但其所享有的表决权能够对董事会、股东会或者股东大会的决议产生重大影响; (三)其他导致外国投资者能够对企业的经营决策、人事、财务、技术等产生重大影响的情形。 对本条第一款规定范围(以下称申报范围)内的外商投资，工作机制办公室有权要求当事人申"},{"i":5,"n":"第五条","txt":"当事人向工作机制办公室申报外商投资前，可以就有关问题向工作机制办公室进行咨询。"},{"i":6,"n":"第六条","txt":"当事人向工作机制办公室申报外商投资，应当提交下列材料： (一)申报书; (二)投资方案; (三)外商投资是否影响国家安全的说明; (四)工作机制办公室规定的其他材料。 申报书应当载明外国投资者的名称、住所、经营范围、投资的基本情况以及工作机制办公室规定的其他事项。 工作机制办公室根据工作需要，可以委托省、自治区、直辖市人民政府有关部门代为收取并转送本条第一款规定的材料。"},{"i":7,"n":"第七条","txt":"工作机制办公室应当自收到当事人提交或者省、自治区、直辖市人民政府有关部门转送的符合本办法第六条规定的材料之日起15个工作日内，对申报的外商投资作出是否需要进行安全审查的决定，并书面通知当事人。工作机制办公室作出决定前，当事人不得实施投资。 工作机制办公室作出不需要进行安全审查决定的，当事人可以实施投资。"},{"i":8,"n":"第八条","txt":"外商投资安全审查分为一般审查和特别审查。工作机制办公室决定对申报的外商投资进行安全审查的，应当自决定之日起30个工作日内完成一般审查。审查期间，当事人不得实施投资。 经一般审查，认为申报的外商投资不影响国家安全的，工作机制办公室应当作出通过安全审查的决定;认为影响或者可能影响国家安全的，工作机制办公室应当作出启动特别审查的决定。工作机制办公室作出的决定应当书面通知当事人。"},{"i":9,"n":"第九条","txt":"工作机制办公室决定对申报的外商投资启动特别审查的，审查后应当按照下列规定作出决定，并书面通知当事人： (一)申报的外商投资不影响国家安全的，作出通过安全审查的决定; (二)申报的外商投资影响国家安全的，作出禁止投资的决定;通过附加条件能够消除对国家安全的影响，且当事人书面承诺接受附加条件的，可以作出附条件通过安全审查的决定，并在决定中列明附加条件。 特别审查应当自启动之日起60个工作日内完成;特殊情况下，可以延长审查期限。延长审查期限应当书面通知当事人。审查期间，当事人不得实施投资。"},{"i":10,"n":"第十条","txt":"工作机制办公室对申报的外商投资进行安全审查期间，可以要求当事人补充提供相关材料，并向当事人询问有关情况。当事人应当予以配合。 当事人补充提供材料的时间不计入审查期限。"},{"i":11,"n":"第十一条","txt":"工作机制办公室对申报的外商投资进行安全审查期间，当事人可以修改投资方案或者撤销投资。 当事人修改投资方案的，审查期限自工作机制办公室收到修改后的投资方案之日起重新计算;当事人撤销投资的，工作机制办公室终止审查。"},{"i":12,"n":"第十二条","txt":"工作机制办公室对申报的外商投资作出通过安全审查决定的，当事人可以实施投资;作出禁止投资决定的，当事人不得实施投资，已经实施的，应当限期处分股权或者资产以及采取其他必要措施，恢复到投资实施前的状态，消除对国家安全的影响;作出附条件通过安全审查决定的，当事人应当按照附加条件实施投资。"},{"i":13,"n":"第十三条","txt":"外商投资安全审查决定，由工作机制办公室会同有关部门、地方人民政府监督实施;对附条件通过安全审查的外商投资，可以采取要求提供有关证明材料、现场检查等方式，对附加条件的实施情况进行核实。"},{"i":14,"n":"第十四条","txt":"工作机制办公室对申报的外商投资作出不需要进行安全审查或者通过安全审查的决定后，当事人变更投资方案，影响或者可能影响国家安全的，应当依照本办法的规定重新向工作机制办公室申报。"},{"i":15,"n":"第十五条","txt":"有关机关、企业、社会团体、社会公众等认为外商投资影响或者可能影响国家安全的，可以向工作机制办公室提出进行安全审查的建议。"},{"i":16,"n":"第十六条","txt":"对申报范围内的外商投资，当事人未依照本办法的规定申报即实施投资的，由工作机制办公室责令限期申报;拒不申报的，责令限期处分股权或者资产以及采取其他必要措施，恢复到投资实施前的状态，消除对国家安全的影响。"},{"i":17,"n":"第十七条","txt":"当事人向工作机制办公室提供虚假材料或者隐瞒有关信息的，由工作机制办公室责令改正;提供虚假材料或者隐瞒有关信息骗取通过安全审查的，撤销相关决定;已经实施投资的，责令限期处分股权或者资产以及采取其他必要措施，恢复到投资实施前的状态，消除对国家安全的影响。"},{"i":18,"n":"第十八条","txt":"附条件通过安全审查的外商投资，当事人未按照附加条件实施投资的，由工作机制办公室责令改正;拒不改正的，责令限期处分股权或者资产以及采取其他必要措施，恢复到投资实施前的状态，消除对国家安全的影响。"},{"i":19,"n":"第十九条","txt":"当事人有本办法第十六条、第十七条、第十八条规定情形的，应当将其作为不良信用记录纳入国家有关信用信息系统，并按照国家有关规定实施联合惩戒。"},{"i":20,"n":"第二十条","txt":"国家机关工作人员在外商投资安全审查工作中，滥用职权、玩忽职守、徇私舞弊、泄露国家秘密或者其所知悉的商业秘密的，依法给予处分;构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"香港特别行政区、澳门特别行政区、台湾地区投资者进行投资，影响或者可能影响国家安全的，参照本办法的规定执行。"},{"i":22,"n":"第二十二条","txt":"外国投资者通过证券交易所或者国务院批准的其他证券交易场所购买境内企业股票，影响或者可能影响国家安全的，其适用本办法的具体办法由国务院证券监督管理机构会同工作机制办公室制定。"},{"i":23,"n":"第二十三条","txt":"本办法自公布之日起三十日后施行。"}],"waishangtouzianquanshenchabanfa":[{"i":1,"n":"第一条","txt":"为了适应推动形成全面开放新格局的需要，在积极促进外商投资的同时有效预防和化解国家安全风险，根据《中华人民共和国外商投资法》《中华人民共和国国家安全法》和相关法律，制定本办法。"},{"i":2,"n":"第二条","txt":"对影响或者可能影响国家安全的外商投资，依照本办法的规定进行安全审查。 本办法所称外商投资，是指外国投资者直接或者间接在中华人民共和国境内(以下简称境内)进行的投资活动，包括下列情形： (一)外国投资者单独或者与其他投资者共同在境内投资新建项目或者设立企业; (二)外国投资者通过并购方式取得境内企业的股权或者资产; (三)外国投资者通过其他方式在境内投资。"},{"i":3,"n":"第三条","txt":"国家建立外商投资安全审查工作机制(以下简称工作机制)，负责组织、协调、指导外商投资安全审查工作。 工作机制办公室设在国家发展改革委，由国家发展改革委、商务部牵头，承担外商投资安全审查的日常工作。"},{"i":4,"n":"第四条","txt":"下列范围内的外商投资，外国投资者或者境内相关当事人(以下统称当事人)应当在实施投资前主动向工作机制办公室申报： (一)投资军工、军工配套等关系国防安全的领域，以及在军事设施和军工设施周边地域投资; (二)投资关系国家安全的重要农产品、重要能源和资源、重大装备制造、重要基础设施、重要运输服务、重要文化产品与服务、重要信息技术和互联网产品与服务、重要金融服务、关键技术以及其他重要领域，并取得所投资企业的实际控制权。 前款第二项所称取得所投资企业的实际控制权，包括下列情形： (一)外国投资者持有企业50%以上股权; (二)外国投资者持有企业股权不足50%，但其所享有的表决权能够对董事会、股东会或者股东大会的决议产生重大影响; (三)其他导致外国投资者能够对企业的经营决策、人事、财务、技术等产生重大影响的情形。 对本条第一款规定范围(以下称申报范围)内的外商投资，工作机制办公室有权要求当事人申"},{"i":5,"n":"第五条","txt":"当事人向工作机制办公室申报外商投资前，可以就有关问题向工作机制办公室进行咨询。"},{"i":6,"n":"第六条","txt":"当事人向工作机制办公室申报外商投资，应当提交下列材料： (一)申报书; (二)投资方案; (三)外商投资是否影响国家安全的说明; (四)工作机制办公室规定的其他材料。 申报书应当载明外国投资者的名称、住所、经营范围、投资的基本情况以及工作机制办公室规定的其他事项。 工作机制办公室根据工作需要，可以委托省、自治区、直辖市人民政府有关部门代为收取并转送本条第一款规定的材料。"},{"i":7,"n":"第七条","txt":"工作机制办公室应当自收到当事人提交或者省、自治区、直辖市人民政府有关部门转送的符合本办法第六条规定的材料之日起15个工作日内，对申报的外商投资作出是否需要进行安全审查的决定，并书面通知当事人。工作机制办公室作出决定前，当事人不得实施投资。 工作机制办公室作出不需要进行安全审查决定的，当事人可以实施投资。"},{"i":8,"n":"第八条","txt":"外商投资安全审查分为一般审查和特别审查。工作机制办公室决定对申报的外商投资进行安全审查的，应当自决定之日起30个工作日内完成一般审查。审查期间，当事人不得实施投资。 经一般审查，认为申报的外商投资不影响国家安全的，工作机制办公室应当作出通过安全审查的决定;认为影响或者可能影响国家安全的，工作机制办公室应当作出启动特别审查的决定。工作机制办公室作出的决定应当书面通知当事人。"},{"i":9,"n":"第九条","txt":"工作机制办公室决定对申报的外商投资启动特别审查的，审查后应当按照下列规定作出决定，并书面通知当事人： (一)申报的外商投资不影响国家安全的，作出通过安全审查的决定; (二)申报的外商投资影响国家安全的，作出禁止投资的决定;通过附加条件能够消除对国家安全的影响，且当事人书面承诺接受附加条件的，可以作出附条件通过安全审查的决定，并在决定中列明附加条件。 特别审查应当自启动之日起60个工作日内完成;特殊情况下，可以延长审查期限。延长审查期限应当书面通知当事人。审查期间，当事人不得实施投资。"},{"i":10,"n":"第十条","txt":"工作机制办公室对申报的外商投资进行安全审查期间，可以要求当事人补充提供相关材料，并向当事人询问有关情况。当事人应当予以配合。 当事人补充提供材料的时间不计入审查期限。"},{"i":11,"n":"第十一条","txt":"工作机制办公室对申报的外商投资进行安全审查期间，当事人可以修改投资方案或者撤销投资。 当事人修改投资方案的，审查期限自工作机制办公室收到修改后的投资方案之日起重新计算;当事人撤销投资的，工作机制办公室终止审查。"},{"i":12,"n":"第十二条","txt":"工作机制办公室对申报的外商投资作出通过安全审查决定的，当事人可以实施投资;作出禁止投资决定的，当事人不得实施投资，已经实施的，应当限期处分股权或者资产以及采取其他必要措施，恢复到投资实施前的状态，消除对国家安全的影响;作出附条件通过安全审查决定的，当事人应当按照附加条件实施投资。"},{"i":13,"n":"第十三条","txt":"外商投资安全审查决定，由工作机制办公室会同有关部门、地方人民政府监督实施;对附条件通过安全审查的外商投资，可以采取要求提供有关证明材料、现场检查等方式，对附加条件的实施情况进行核实。"},{"i":14,"n":"第十四条","txt":"工作机制办公室对申报的外商投资作出不需要进行安全审查或者通过安全审查的决定后，当事人变更投资方案，影响或者可能影响国家安全的，应当依照本办法的规定重新向工作机制办公室申报。"},{"i":15,"n":"第十五条","txt":"有关机关、企业、社会团体、社会公众等认为外商投资影响或者可能影响国家安全的，可以向工作机制办公室提出进行安全审查的建议。"},{"i":16,"n":"第十六条","txt":"对申报范围内的外商投资，当事人未依照本办法的规定申报即实施投资的，由工作机制办公室责令限期申报;拒不申报的，责令限期处分股权或者资产以及采取其他必要措施，恢复到投资实施前的状态，消除对国家安全的影响。"},{"i":17,"n":"第十七条","txt":"当事人向工作机制办公室提供虚假材料或者隐瞒有关信息的，由工作机制办公室责令改正;提供虚假材料或者隐瞒有关信息骗取通过安全审查的，撤销相关决定;已经实施投资的，责令限期处分股权或者资产以及采取其他必要措施，恢复到投资实施前的状态，消除对国家安全的影响。"},{"i":18,"n":"第十八条","txt":"附条件通过安全审查的外商投资，当事人未按照附加条件实施投资的，由工作机制办公室责令改正;拒不改正的，责令限期处分股权或者资产以及采取其他必要措施，恢复到投资实施前的状态，消除对国家安全的影响。"},{"i":19,"n":"第十九条","txt":"当事人有本办法第十六条、第十七条、第十八条规定情形的，应当将其作为不良信用记录纳入国家有关信用信息系统，并按照国家有关规定实施联合惩戒。"},{"i":20,"n":"第二十条","txt":"国家机关工作人员在外商投资安全审查工作中，滥用职权、玩忽职守、徇私舞弊、泄露国家秘密或者其所知悉的商业秘密的，依法给予处分;构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"香港特别行政区、澳门特别行政区、台湾地区投资者进行投资，影响或者可能影响国家安全的，参照本办法的规定执行。"},{"i":22,"n":"第二十二条","txt":"外国投资者通过证券交易所或者国务院批准的其他证券交易场所购买境内企业股票，影响或者可能影响国家安全的，其适用本办法的具体办法由国务院证券监督管理机构会同工作机制办公室制定。"},{"i":23,"n":"第二十三条","txt":"本办法自公布之日起三十日后施行。"}],"waishangtouzixiangmuhezhunhebeianguanlibanfa":[{"i":1,"n":"第一条","txt":"为进一步深化外商投资管理体制改革，根据《中华人民共和国行政许可法》、《指导外商投资方向规定》、《国务院关于投资体制改革的决定》及《政府核准的投资项目目录(2013年本)》(以下简称《核准目录》)，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中外合资、中外合作、外商独资、外商投资合伙、外商并购境内企业、外商投资企业增资及再投资项目等各类外商投资项目。"},{"i":3,"n":"第三条","txt":"外商投资项目管理分为核准和备案两种方式。"},{"i":4,"n":"第四条","txt":"根据《核准目录》，实行核准制的外商投资项目的范围为： (一)《外商投资产业指导目录》中有中方控股(含相对控股)要求的总投资(含增资)3亿美元及以上鼓励类项目，总投资(含增资)5000万美元及以上限制类(不含房地产)项目，由国家发展和改革委员会核准。 (二)《外商投资产业指导目录》限制类中的房地产项目和总投资(含增资)5000万美元以下的其他限制类项目，由省级政府核准。《外商投资产业指导目录》中有中方控股(含相对控股)要求的总投资(含增资)3亿美元以下鼓励类项目，由地方政府核准。 (三)前两项规定之外的属于《核准目录》第一至十一项所列的外商投资项目，按照《核准目录》第一至十一项的规定核准。 (四)由地方政府核准的项目，省级政府可以根据本地实际情况具体划分地方各级政府的核准权限。由省级政府核准的项目，核准权限不得下放。 本办法所称项目核准机关，是指本条规定具有项目核准权限的行政机关。"},{"i":5,"n":"第五条","txt":"本办法第四条范围以外的外商投资项目由地方政府投资主管部门备案。"},{"i":6,"n":"第六条","txt":"外商投资企业增资项目总投资以新增投资额计算，并购项目总投资以交易额计算。"},{"i":7,"n":"第七条","txt":"外商投资涉及国家安全的，应当按照国家有关规定进行安全审查。"},{"i":8,"n":"第八条","txt":"拟申请核准的外商投资项目应按国家有关要求编制项目申请报告。项目申请报告应包括以下内容： (一)项目及投资方情况; (二)资源利用和生态环境影响分析; (三)经济和社会影响分析。 外国投资者并购境内企业项目申请报告应包括并购方情况、并购安排、融资方案和被并购方情况、被并购后经营方式、范围和股权结构、所得收入的使用安排等。"},{"i":9,"n":"第九条","txt":"国家发展和改革委员会根据实际需要，编制并颁布项目申请报告通用文本、主要行业的项目申请报告示范文本、项目核准文件格式文本。 对于应当由国家发展和改革委员会核准或者审核后报国务院核准的项目，国家发展和改革委员会制定并颁布《服务指南》，列明项目核准的申报材料和所需附件、受理方式、办理流程、办理时限等内容，为项目申报单位提供指导和服务。"},{"i":10,"n":"第十条","txt":"项目申请报告应附以下文件： (一)中外投资各方的企业注册证明材料及经审计的最新企业财务报表(包括资产负债表、利润表和现金流量表)、开户银行出具的资金信用证明; (二)投资意向书，增资、并购项目的公司董事会决议; (三)城乡规划行政主管部门出具的选址意见书(仅指以划拨方式提供国有土地使用权的项目); (四)国土资源行政主管部门出具的用地预审意见(不涉及新增用地，在已批准的建设用地范围内进行改扩建的项目，可以不进行用地预审); (五)环境保护行政主管部门出具的环境影响评价审批文件; (六)节能审查机关出具的节能审查意见; (七)以国有资产出资的，需由有关主管部门出具的确认文件; (八)根据有关法律法规的规定应当提交的其他文件。"},{"i":11,"n":"第十一条","txt":"按核准权限属于国家发展和改革委员会核准的项目，由项目所在地省级发展改革部门提出初审意见后，向国家发展和改革委员会报送项目申请报告;计划单列企业集团和中央管理企业可直接向国家发展和改革委员会报送项目申请报告，并附项目所在地省级发展改革部门的意见。"},{"i":12,"n":"第十二条","txt":"项目申报材料不齐全或者不符合有关要求的，项目核准机关应当在收到申报材料后5个工作日内一次告知项目申报单位补正。"},{"i":13,"n":"第十三条","txt":"对于涉及有关行业主管部门职能的项目，项目核准机关应当商请有关行业主管部门在7个工作日内出具书面审查意见。有关行业主管部门逾期没有反馈书面审查意见的，视为同意。"},{"i":14,"n":"第十四条","txt":"项目核准机关在受理项目申请报告之日起4个工作日内，对需要进行评估论证的重点问题委托有资质的咨询机构进行评估论证，接受委托的咨询机构应在规定的时间内提出评估报告。 对于可能会对公共利益造成重大影响的项目，项目核准机关在进行核准时应采取适当方式征求公众意见。对于特别重大的项目，可以实行专家评议制度。"},{"i":15,"n":"第十五条","txt":"项目核准机关自受理项目核准申请之日起20个工作日内，完成对项目申请报告的核准。如20个工作日内不能做出核准决定的，由本部门负责人批准延长10个工作日，并将延长期限的理由告知项目申报单位。 前款规定的核准期限，委托咨询评估和进行专家评议所需的时间不计算在内。"},{"i":16,"n":"第十六条","txt":"对外商投资项目的核准条件是： (一)符合国家有关法律法规和《外商投资产业指导目录》、《中西部地区外商投资优势产业目录》的规定; (二)符合发展规划、产业政策及准入标准; (三)合理开发并有效利用了资源; (四)不影响国家安全和生态安全; (五)对公众利益不产生重大不利影响; (六)符合国家资本项目管理、外债管理的有关规定。"},{"i":17,"n":"第十七条","txt":"对予以核准的项目，项目核准机关出具书面核准文件，并抄送同级行业管理、城乡规划、国土资源、环境保护、节能审查等相关部门;对不予核准的项目，应以书面说明理由，并告知项目申报单位享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":18,"n":"第十八条","txt":"拟申请备案的外商投资项目需由项目申报单位提交项目和投资方基本情况等信息，并附中外投资各方的企业注册证明材料、投资意向书及增资、并购项目的公司董事会决议等其他相关材料;"},{"i":19,"n":"第十九条","txt":"外商投资项目备案需符合国家有关法律法规、发展规划、产业政策及准入标准，符合《外商投资产业指导目录》、《中西部地区外商投资优势产业目录》。"},{"i":20,"n":"第二十条","txt":"对不予备案的外商投资项目，地方投资主管部门应在7个工作日内出具书面意见并说明理由。"},{"i":21,"n":"第二十一条","txt":"经核准或备案的项目如出现下列情形之一的，需向原批准机关申请变更： (一)项目地点发生变化; (二)投资方或股权发生变化; (三)项目主要建设内容发生变化; (四)有关法律法规和产业政策规定需要变更的其他情况。"},{"i":22,"n":"第二十二条","txt":"变更核准和备案的程序比照本办法前述有关规定执行。"},{"i":23,"n":"第二十三条","txt":"经核准的项目若变更后属于备案管理范围的，应按备案程序办理;予以备案的项目若变更后属于核准管理范围的，应按核准程序办理。"},{"i":24,"n":"第二十四条","txt":"核准或备案文件应规定文件的有效期。在有效期内未开工建设的，项目申报单位应当在有效期届满前30个工作日向原核准和备案机关提出延期申请。在有效期内未开工建设且未提出延期申请的，原核准文件期满后自动失效。"},{"i":25,"n":"第二十五条","txt":"对于未按规定权限和程序核准或者备案的项目，有关部门不得办理相关手续，金融机构不得提供信贷支持。"},{"i":26,"n":"第二十六条","txt":"各级项目核准和备案机关要切实履行核准和备案职责，改进监督、管理和服务，提高行政效率，并按照相关规定做好项目核准及备案的信息公开工作。"},{"i":27,"n":"第二十七条","txt":"各级发展改革部门应当会同同级行业管理、城乡规划、国土资源、环境保护、金融监管、安全生产监管等部门，对项目申报单位执行项目情况和外商投资项目核准或备案情况进行稽察和监督检查，加快完善信息系统，建立发展规划、产业政策、准入标准、诚信记录等信息的横向互通制度，及时通报对违法违规行为的查处情况，实现行政审批和市场监管的信息共享。"},{"i":28,"n":"第二十八条","txt":"国家发展和改革委员会要联合地方发展改革部门建立完善外商投资项目管理电子信息系统，实现外商投资项目可查询、可监督，提升事中事后监管水平。"},{"i":29,"n":"第二十九条","txt":"省级发展改革部门每月10日前汇总整理上月本省项目核准及备案相关情况，包括项目名称、核准及备案文号、项目所在地、中外投资方、建设内容、资金来源(包括总投资、资本金等)等，报送国家发展和改革委员会。"},{"i":30,"n":"第三十条","txt":"项目核准和备案机关及其工作人员违反本办法有关规定的，由其上级行政机关或者监察机关责令改正;情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":31,"n":"第三十一条","txt":"项目核准和备案机关工作人员，在项目核准和备案过程中滥用职权谋取私利，构成犯罪的，依法追究刑事责任;尚不构成犯罪的，依法给予行政处分。"},{"i":32,"n":"第三十二条","txt":"咨询评估机构及其人员、参与专家评议的专家，在编制项目申请报告、受项目核准机关委托开展评估或者参与专家评议过程中，不遵守国家法律法规和本办法规定的，依法追究相应责任。"},{"i":33,"n":"第三十三条","txt":"项目申报单位以拆分项目或提供虚假材料等不正当手段申请核准或备案的，项目核准和备案机关不予受理或者不予核准及备案。已经取得项目核准或备案文件的，项目核准和备案机关应依法撤销该项目的核准或备案文件。已经开工建设的，依法责令其停止建设。相应的项目核准和备案机关及有关部门应当将其纳入不良信用记录，并依法追究有关责任人的法律责任。"},{"i":34,"n":"第三十四条","txt":"具有项目核准职能的国务院行业管理部门和省级政府有关部门可以按照国家有关法律法规和本办法的规定，制定外商投资项目核准具体实施办法和相应的《服务指南》。"},{"i":35,"n":"第三十五条","txt":"香港特别行政区、澳门特别行政区和台湾地区的投资者在祖国大陆举办的投资项目，参照本办法执行。 外国投资者以人民币在境内投资的项目，按照本办法执行。"},{"i":36,"n":"第三十六条","txt":"法律、行政法规和国家对外商投资项目管理有专门规定的，按照有关规定执行。"},{"i":37,"n":"第三十七条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":38,"n":"第三十八条","txt":"本办法自2014年6月17日起施行。国家发展和改革委员会2004年10月9日发布的《外商投资项目核准暂行管理办法》(国家发展和改革委员会令第22号)同时废止。"}],"shixinxingweijiuzhenghoudexinyongxinxixiufuguanlib176428":[{"i":1,"n":"第一条","txt":"为规范信用信息修复工作，维护信用主体合法权益，进一步提升社会信用体系建设法治化、规范化水平，根据《中共中央办公厅 国务院办公厅印发<关于推进社会信用体系建设高质量发展促进形成新发展格局的意见>的通知》《国务院关于建立完善守信联合激励和失信联合惩戒制度 加快推进社会诚信建设的指导意见》《国务院办公厅关于加快推进社会信用体系建设 构建以信用为基础的新型监管机制的指导意见》《国务院办公厅关于进一步完善失信约束制度 构建诚信建设长效机制的指导意见》要求，制定本办法。"},{"i":2,"n":"第二条","txt":"信用主体依法享有信用信息修复的权利。除法律、法规和党中央、国务院政策文件明确规定不可修复的情形外，满足相关条件的信用主体均可按要求申请信用信息修复。"},{"i":3,"n":"第三条","txt":"本办法所称的信用信息修复，是指信用主体为积极改善自身信用状况，在纠正失信行为、履行相关义务后，向认定失信行为的单位（以下简称“认定单位”）或者归集失信信息的信用平台网站的运行机构（以下简称“归集机构”）提出申请，由认定单位或者归集机构按照有关规定，移除或终止公示失信信息的活动。 本办法所称的公示，是指归集机构整合相关信用信息并记于信用主体名下后，对依法可公开的信息在信用网站进行集中统一公示。"},{"i":4,"n":"第四条","txt":"本办法所称的失信信息，是指全国公共信用信息基础目录和地方公共信用信息补充目录中所列的对信用主体信用状况具有负面影响的信息，包括严重失信主体名单信息、行政处罚信息和其他失信信息。 本办法所称的严重失信主体名单，是指以法律、法规或党中央、国务院政策文件为依据设列的严重失信主体名单。"},{"i":5,"n":"第五条","txt":"全国信用信息共享平台、“信用中国”网站以及地方信用信息共享平台和信用网站（以下统称“信用平台网站”）开展信用信息修复活动，适用本办法。 有关行业主管（监管）部门建立的信用信息系统开展信用信息修复，可参照本办法执行。 法律、法规、部门规章和党中央、国务院文件对信用信息公示和修复另有规定的，从其规定。"},{"i":6,"n":"第六条","txt":"国家发展和改革委员会负责统筹协调指导信用信息修复工作。地方各级人民政府社会信用体系建设牵头部门负责统筹协调指导辖区内信用信息修复工作。各有关部门和单位按职责分工做好信用信息修复相关工作。"},{"i":7,"n":"第七条","txt":"信用信息修复的方式包括移出严重失信主体名单、终止公示行政处罚信息和修复其他失信信息。"},{"i":8,"n":"第八条","txt":"移出严重失信主体名单，是指认定单位按照有关规定，将信用主体从有关严重失信主体名单中移出。"},{"i":9,"n":"第九条","txt":"终止公示行政处罚信息，是指归集机构按照有关规定，对正在信用网站上公示的信用主体有关行政处罚信息终止公示。"},{"i":10,"n":"第十条","txt":"修复其他失信信息，按照认定单位有关规定执行。"},{"i":11,"n":"第十一条","txt":"依据法律、法规、部门规章建立信用信息修复制度的，由认定单位受理相关修复申请。 尚未建立信用信息修复制度的领域，由国家公共信用信息中心受理修复申请。国家公共信用信息中心作出决定后，在全国信用信息共享平台和“信用中国”网站更新相关信息。地方各级信用平台网站的运行机构配合国家公共信用信息中心做好信用信息修复相关工作。"},{"i":12,"n":"第十二条","txt":"移出严重失信主体名单的申请由认定单位负责受理。"},{"i":13,"n":"第十三条","txt":"认定单位应当严格按照已建立的严重失信主体名单制度规定，审核决定是否同意将信用主体移出名单。"},{"i":14,"n":"第十四条","txt":"“信用中国”网站自收到认定单位共享的移出名单之日起三个工作日内终止公示严重失信主体名单信息。"},{"i":15,"n":"第十五条","txt":"以简易程序作出的对法人和非法人组织的行政处罚信息，信用平台网站不进行归集和公示。 以普通程序作出的对法人和非法人组织的行政处罚信息，信用平台网站应当进行归集和公示。被处以警告、通报批评的行政处罚信息，不予公示。其他行政处罚信息最短公示期为三个月，最长公示期为三年，其中涉及食品、药品、特种设备、安全生产、消防领域行政处罚信息最短公示期一年。最短公示期届满后，方可按规定申请提前终止公示。最长公示期届满后，相关信息自动停止公示。 前款规定的行政处罚信息，同一行政处罚决定涉及多种处罚类型的，其公示期限以期限最长的类型为准。行政处罚信息的公示期限起点以行政处罚作出时间为准。 对自然人的行政处罚信息，信用平台网站原则上不公示。"},{"i":16,"n":"第十六条","txt":"法人和非法人组织对行政处罚决定不服，申请行政复议或提起行政诉讼的，相关程序终结前，除行政复议机关或人民法院认定需要停止执行的，相关行政处罚信息不暂停公示。 行政复议或行政诉讼程序终结后，行政处罚被依法撤销或变更的，原处罚机关应当及时将结果报送信用平台网站。信用平台网站应当自收到相关信息之日起三个工作日内撤销或修改相关信息。"},{"i":17,"n":"第十七条","txt":"法人和非法人组织认为信用平台网站对其行政处罚信息的公示内容有误、公示期限不符合规定或者行政处罚决定被依法撤销或变更的，可以向国家公共信用信息中心提出申诉。经核实符合申诉条件的，申诉结果应在七个工作日内反馈，信用平台网站应当及时更新信息。"},{"i":18,"n":"第十八条","txt":"提前终止公示对法人和非法人组织的行政处罚信息，应当同时满足以下条件： （一）完全履行行政处罚决定规定的义务，纠正违法行为； （二）达到最短公示期限； （三）公开作出信用承诺。承诺内容应包括所提交材料真实有效，并明确愿意承担违反承诺的相应责任。"},{"i":19,"n":"第十九条","txt":"法人和非法人组织申请提前终止公示行政处罚信息，应当通过“信用中国”网站向国家公共信用信息中心提出申请，并提交以下材料： （一）行政处罚机关出具的说明行政处罚决定书明确的责任义务已履行完毕的意见，或者其他可说明相关责任义务已履行完毕的材料； （二）信用承诺书。"},{"i":20,"n":"第二十条","txt":"国家公共信用信息中心收到提前终止法人和非法人组织行政处罚信息公示的申请后，应当对申请材料进行形式审查，材料齐全且符合要求的，予以受理；材料不齐全或者不符合要求的，应当在三个工作日内一次性告知信用主体予以补正，补正后符合要求的，予以受理。"},{"i":21,"n":"第二十一条","txt":"国家公共信用信息中心应当自受理之日起七个工作日内确定是否可以提前终止公示；对不予提前终止公示的，应当说明理由。"},{"i":22,"n":"第二十二条","txt":"法律、法规对相关违法违规行为规定了附带期限的惩戒措施的，在相关期限届满前，行政处罚信息不得提前终止公示。"},{"i":23,"n":"第二十三条","txt":"国家公共信用信息中心应当保障信用信息修复申请受理、审核确认、信息处理等流程线上运行。"},{"i":24,"n":"第二十四条","txt":"地方信用平台网站运行机构应当配合国家公共信用信息中心做好工作协同和信息同步。"},{"i":25,"n":"第二十五条","txt":"信用平台网站与认定单位、国家企业信用信息公示系统、有关行业主管（监管）部门信用信息系统建立信用信息修复信息共享机制。信用平台网站应当自收到信用信息修复信息之日起三个工作日内更新公示信息。信用平台网站应当在作出信用信息修复决定之日起三个工作日内将修复信息共享至认定单位和相关系统。"},{"i":26,"n":"第二十六条","txt":"从“信用中国”网站获取失信信息的第三方信用服务机构，应当建立信息更新机制，确保与“信用中国”网站保持一致。信息不一致的，以“信用中国”网站信息为准。 国家公共信用信息中心应当对第三方信用服务机构信息更新情况进行监督检查，对不及时更新修复信息的机构，可以暂停或者取消向其共享信息。"},{"i":27,"n":"第二十七条","txt":"信用主体申请信用信息修复应当秉持诚实守信原则，如有提供虚假材料、信用承诺严重不实或被行政机关认定为故意不履行承诺等行为，由受理申请的单位记入信用记录，纳入全国信用信息共享平台，与认定单位及时共享，相关信用记录在“信用中国”网站公示三年并不得提前终止公示，三年内不得在信用平台网站申请信用信息修复；构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"国家公共信用信息中心不得以任何形式向申请修复的信用主体收取费用。有不按规定办理信用信息修复、直接或变相向信用主体收取费用行为的，依法依规追究相关单位和人员责任。"},{"i":29,"n":"第二十九条","txt":"国家发展和改革委员会、县级及以上地方人民政府社会信用体系建设牵头部门应当会同有关部门加强对信用信息修复工作的督促指导，发现问题及时责令改正。"},{"i":30,"n":"第三十条","txt":"充分发挥有关部门、行业协会商会、第三方信用服务机构、专家学者、新闻媒体等作用，及时阐释和解读信用信息修复政策。鼓励开展各类诚信宣传教育，营造良好舆论环境。"},{"i":31,"n":"第三十一条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":32,"n":"第三十二条","txt":"本办法自2023年5月1日起施行。涉及信用平台网站的信用信息修复相关规定，凡与本办法不一致的停止执行。"}],"gongchengzixunhangyeguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强对工程咨询行业的管理，规范从业行为，保障工程咨询服务质量，促进投资科学决策、规范实施，发挥投资对优化供给结构的关键性作用，根据《中共中央国务院关于深化投融资体制改革的意见》(中发〔2016〕18号)、《企业投资项目核准和备案管理条例》(国务院令第673号)及有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"工程咨询是遵循独立、公正、科学的原则，综合运用多学科知识、工程实践经验、现代科学和管理方法，在经济社会发展、境内外投资建设项目决策与实施活动中，为投资者和政府部门提供阶段性或全过程咨询和管理的智力服务。"},{"i":3,"n":"第三条","txt":"工程咨询单位是指在中国境内设立的从事工程咨询业务并具有独立法人资格的企业、事业单位。 工程咨询单位及其从业人员应当遵守国家法律法规和政策要求，恪守行业规范和职业道德，积极参与和接受行业自律管理。"},{"i":4,"n":"第四条","txt":"国家发展改革委负责指导和规范全国工程咨询行业发展，制定工程咨询单位从业规则和标准，组织开展对工程咨询单位及其人员执业行为的监督管理。地方各级发展改革部门负责指导和规范本行政区域内工程咨询行业发展，实施对工程咨询单位及其人员执业行为的监督管理。"},{"i":5,"n":"第五条","txt":"各级发展改革部门对工程咨询行业协会等行业组织进行政策和业务指导，依法加强监管。"},{"i":6,"n":"第六条","txt":"对工程咨询单位实行告知性备案管理。工程咨询单位应当通过全国投资项目在线审批监管平台(以下简称在线平台)备案以下信息： (一)基本情况，包括企业营业执照(事业单位法人证书)、在岗人员及技术力量、从事工程咨询业务年限、联系方式等; (二)从事的工程咨询专业和服务范围; (三)备案专业领域的专业技术人员配备情况; (四)非涉密的咨询成果简介。 工程咨询单位应当保证所备案信息真实、准确、完整。备案信息有变化的，工程咨询单位应及时通过在线平台告知。 工程咨询单位基本信息由国家发展改革委通过在线平台向社会公布。"},{"i":7,"n":"第七条","txt":"工程咨询业务按照以下专业划分： (一)农业、林业;(二)水利水电;(三)电力(含火电、水电、核电、新能源);(四)煤炭;(五)石油天然气;(六)公路;(七)铁路、城市轨道交通;(八)民航;(九)水运(含港口河海工程);(十)电子、信息工程(含通信、广电、信息化);(十一)冶金(含钢铁、有色);(十二)石化、化工、医药;(十三)核工业;(十四)机械(含智能制造);(十五)轻工、纺织;(十六)建材;(十七)建筑;(十八)市政公用工程;(十九)生态建设和环境工程;(二十)水文地质、工程测量、岩土工程;(二十一)其他(以实际专业为准)。"},{"i":8,"n":"第八条","txt":"工程咨询服务范围包括： (一)规划咨询：含总体规划、专项规划、区域规划及行业规划的编制; (二)项目咨询：含项目投资机会研究、投融资策划，项目建议书(预可行性研究)、项目可行性研究报告、项目申请报告、资金申请报告的编制，政府和社会资本合作(PPP)项目咨询等; (三)评估咨询：各级政府及有关部门委托的对规划、项目建议书、可行性研究报告、项目申请报告、资金申请报告、PPP项目实施方案、初步设计的评估，规划和项目中期评价、后评价，项目概预决算审查，及其他履行投资管理职能所需的专业技术服务; (四)全过程工程咨询：采用多种服务方式组合，为项目决策、实施和运营持续提供局部或整体解决方案以及管理服务。有关工程设计、工程造价、工程监理等资格，由国务院有关主管部门认定。"},{"i":9,"n":"第九条","txt":"工程咨询单位订立服务合同和开展相应的咨询业务，应当与备案的专业和服务范围一致。"},{"i":10,"n":"第十条","txt":"工程咨询单位应当建立健全咨询质量管理制度，建立和实行咨询成果质量、成果文件审核等岗位人员责任制。"},{"i":11,"n":"第十一条","txt":"工程咨询单位应当和委托方订立书面合同，约定各方权利义务并共同遵守。合同中应明确咨询活动形成的知识产权归属。"},{"i":12,"n":"第十二条","txt":"工程咨询实行有偿服务。工程咨询服务价格由双方协商确定，促进优质优价，禁止价格垄断和恶意低价竞争。"},{"i":13,"n":"第十三条","txt":"编写咨询成果文件应当依据法律法规、有关发展建设规划、技术标准、产业政策以及政府部门发布的标准规范等。"},{"i":14,"n":"第十四条","txt":"咨询成果文件上应当加盖工程咨询单位公章和咨询工程师(投资)执业专用章。 工程咨询单位对咨询质量负总责。主持该咨询业务的人员对咨询成果文件质量负主要直接责任，参与人员对其编写的篇章内容负责。 实行咨询成果质量终身负责制。工程咨询单位在开展项目咨询业务时，应在咨询成果文件中就符合本办法第十三条要求，及独立、公正、科学的原则作出信用承诺。工程项目在设计使用年限内，因工程咨询质量导致项目单位重大损失的，应倒查咨询成果质量责任，并根据本办法第三十、三十一条进行处理，形成工程咨询成果质量追溯机制。"},{"i":15,"n":"第十五条","txt":"工程咨询单位应当建立从业档案制度，将委托合同、咨询成果文件等存档备查。"},{"i":16,"n":"第十六条","txt":"承担编制任务的工程咨询单位，不得承担同一事项的评估咨询任务。 承担评估咨询任务的工程咨询单位，与同一事项的编制单位、项目业主单位之间不得存在控股、管理关系或者负责人为同一人的重大关联关系。"},{"i":17,"n":"第十七条","txt":"国家设立工程咨询(投资)专业技术人员水平评价类职业资格制度。 通过咨询工程师(投资)职业资格考试并取得职业资格证书的人员，表明其已具备从事工程咨询(投资)专业技术岗位工作的职业能力和水平。 取得咨询工程师(投资)职业资格证书的人员从事工程咨询工作的，应当选择且仅能同时选择一个工程咨询单位作为其执业单位，进行执业登记并取得登记证书。"},{"i":18,"n":"第十八条","txt":"咨询工程师(投资)是工程咨询行业的核心技术力量。工程咨询单位应当配备一定数量的咨询工程师(投资)。"},{"i":19,"n":"第十九条","txt":"国家发展改革委和人力资源社会保障部按职责分工负责工程咨询(投资)专业技术人员职业资格制度实施的指导、监督、检查工作。 中国工程咨询协会具体承担咨询工程师(投资)的管理工作，开展考试、执业登记、继续教育、执业检查等管理事务。"},{"i":20,"n":"第二十条","txt":"执业登记分为初始登记、变更登记、继续登记和注销登记四类。 申请登记的人员，应当选择已通过在线平台备案的工程咨询单位，按照本办法第七条划分的专业申请登记。申请人最多可以申请两个专业。"},{"i":21,"n":"第二十一条","txt":"申请人登记合格取得《中华人民共和国咨询工程师(投资)登记证书》和执业专用章，登记证书和执业专用章是咨询工程师(投资)的执业证明。登记的有效期为3年。"},{"i":22,"n":"第二十二条","txt":"工程咨询单位应具备良好信誉和相应能力。国家发展改革委应当推进工程咨询单位资信管理体系建设，指导监督行业组织开展资信评价，为委托单位择优选择工程咨询单位和政府部门实施重点监督提供参考依据。"},{"i":23,"n":"第二十三条","txt":"工程咨询单位资信评价等级以一定时期内的合同业绩、守法信用记录和专业技术力量为主要指标，分为甲级和乙级两个级别，具体标准由国家发展改革委制定。"},{"i":24,"n":"第二十四条","txt":"甲级资信工程咨询单位的评定工作，由国家发展改革委指导有关行业组织开展。 乙级资信工程咨询单位的评定工作，由省级发展改革委指导有关行业组织开展。"},{"i":25,"n":"第二十五条","txt":"开展工程咨询单位资信评价工作的行业组织，应当根据本办法及资信评价标准开展资信评价工作，并向获得资信评价的工程咨询单位颁发资信评价等级证书。"},{"i":26,"n":"第二十六条","txt":"工程咨询单位的资信评价结果，由国家和省级发展改革委通过在线平台和“信用中国”网站向社会公布。 行业自律性质的资信评价等级，仅作为委托咨询业务的参考。任何单位不得对资信评价设置机构数量限制，不得对各类工程咨询单位设置区域性、行业性从业限制，也不得对未参加或未获得资信评价的工程咨询单位设置执业限制。"},{"i":27,"n":"第二十七条","txt":"国家和省级发展改革委应当依照有关法律法规、本办法及有关规定，制订工程咨询单位监督检查计划，按照一定比例开展抽查，并及时公布抽查结果。监督检查内容主要包括： (一)遵守国家法律法规及有关规定的情况; (二)信息备案情况; (三)咨询质量管理制度建立情况; (四)咨询成果质量情况; (五)咨询成果文件档案建立情况; (六)其他应当检查的内容。"},{"i":28,"n":"第二十八条","txt":"中国工程咨询协会应当对咨询工程师(投资)执业情况进行检查。检查内容包括： (一)遵守国家法律法规及有关规定的情况; (二)登记申请材料的真实性; (三)遵守职业道德、廉洁从业情况; (四)行使权利、履行义务情况; (五)接受继续教育情况; (六)其他应当检查的情况。"},{"i":29,"n":"第二十九条","txt":"国家和省级发展改革委应当对实施行业自律管理的工程咨询行业组织开展年度评估，提出加强和改进自律管理的建议。对评估中发现问题的，按照本办法第三十二条处理。"},{"i":30,"n":"第三十条","txt":"工程咨询单位有下列行为之一的，由发展改革部门责令改正;情节严重的，给予警告处罚并从备案名录中移除;已获得资信评价等级的，由开展资信评价的组织取消其评价等级。触犯法律的，依法追究法律责任。 (一)备案信息存在弄虚作假或与实际情况不符的; (二)违背独立公正原则，帮助委托单位骗取批准文件和国家资金的; (三)弄虚作假、泄露委托方的商业秘密以及采取不正当竞争手段损害其他工程咨询单位利益的; (四)咨询成果存在严重质量问题的; (五)未建立咨询成果文件完整档案的; (六)伪造、涂改、出租、出借、转让资信评价等级证书的; (七)弄虚作假、提供虚假材料申请资信评价的; (八)弄虚作假、帮助他人申请咨询工程师(投资)登记的; (九)其他违反法律法规的行为。 对直接责任人员，由发展改革部门责令改正，或给予警告处罚;涉及咨询工程师(投资)的，按本办法第三十一条处理。"},{"i":31,"n":"第三十一条","txt":"咨询工程师(投资)有下列行为之一的，由中国工程咨询协会视情节轻重给予警告、通报批评、注销登记证书并收回执业专用章。触犯法律的，依法追究法律责任。 (一)在执业登记中弄虚作假的; (二)准许他人以本人名义执业的; (三)涂改或转让登记证书和执业专用章的; (四)接受任何影响公正执业的酬劳的。"},{"i":32,"n":"第三十二条","txt":"行业组织有下列情形之一的，由国家或省级发展改革委责令改正或停止有关行业自律管理工作;情节严重的，对行业组织和责任人员给予警告处罚。触犯法律的，依法追究法律责任。 (一)无故拒绝工程咨询单位申请资信评价的; (二)无故拒绝申请人申请咨询工程师(投资)登记的; (三)未按规定标准开展资信评价的; (四)未按规定开展咨询工程师(投资)登记的; (五)伙同申请单位或申请人弄虚作假的; (六)其他违反法律、法规的行为。"},{"i":33,"n":"第三十三条","txt":"工程咨询行业有关单位、组织和人员的违法违规信息，列入不良记录，及时通过在线平台和“信用中国”网站向社会公布，并建立违法失信联合惩戒机制。"},{"i":34,"n":"第三十四条","txt":"本办法所称省级发展改革委是指各省、自治区、直辖市及计划单列市、新疆生产建设兵团发展改革委。"},{"i":35,"n":"第三十五条","txt":"本办法由国家发展改革委负责解释。"},{"i":36,"n":"第三十六条","txt":"本办法自2017年12月6日起施行。《工程咨询单位资格认定办法》(国家发展改革委2005年第29号令)、《国家发展改革委关于适用〈工程咨询单位资格认定办法〉有关条款的通知》(发改投资〔2009〕620号)、《咨询工程师(投资)管理办法》(国家发展改革委2013年第2号令)同时废止。"}],"gongchengzixunhangyeguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对工程咨询行业的管理，规范从业行为，保障工程咨询服务质量，促进投资科学决策、规范实施，发挥投资对优化供给结构的关键性作用，根据《中共中央、国务院关于深化投融资体制改革的意见》《政府投资条例》《企业投资项目核准和备案管理条例》及有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"工程咨询是遵循独立、公正、科学的原则，综合运用多学科知识、工程实践经验、现代科学和管理方法，在经济社会发展、境内外投资建设项目决策与实施活动中，为投资者和政府部门提供阶段性或全过程咨询和管理的智力服务。"},{"i":3,"n":"第三条","txt":"工程咨询单位是指在中国境内设立的从事工程咨询业务并具有独立法人资格的企业、事业单位。 工程咨询单位及其从业人员应当遵守国家法律法规和政策要求，恪守行业规范和职业道德，积极参与和接受行业自律管理。"},{"i":4,"n":"第四条","txt":"国家发展改革委负责指导和规范全国工程咨询行业发展，制定工程咨询单位从业规则和标准，组织开展对工程咨询单位及其人员执业行为的监督管理。地方各级发展改革部门负责指导和规范本行政区域内工程咨询行业发展，实施对工程咨询单位及其人员执业行为的监督管理。"},{"i":5,"n":"第五条","txt":"各级发展改革部门对工程咨询行业协会等行业组织进行政策和业务指导，依法加强监管。"},{"i":6,"n":"第六条","txt":"对工程咨询单位实行告知性备案管理。工程咨询单位应当通过全国投资项目在线审批监管平台（以下简称在线平台）备案以下信息： （一）基本情况，包括企业营业执照（事业单位法人证书）、在岗人员及技术力量、从事工程咨询业务年限、联系方式等； （二）从事的工程咨询专业和服务范围； （三）备案专业领域的专业技术人员配备情况； （四）非涉密的咨询成果简介。 工程咨询单位应当保证所备案信息真实、准确、完整。备案信息有变化的，工程咨询单位应及时通过在线平台告知。 工程咨询单位基本信息由国家发展改革委通过在线平台向社会公布。"},{"i":7,"n":"第七条","txt":"工程咨询业务按照以下专业划分： （一）农业、林业；（二）水利水电；（三）电力（含火电、水电、核电、新能源）；（四）煤炭；（五）石油天然气；（六）公路；（七）铁路、城市轨道交通；（八）民航；（九）水运（含港口河海工程）；（十）电子、信息工程（含通信、广电、信息化）；（十一）冶金（含钢铁、有色）；（十二）石化、化工、医药；（十三）核工业；（十四）机械（含智能制造）；（十五）轻工、纺织；（十六）建材；（十七）建筑；（十八）市政公用工程；（十九）生态建设和环境工程；（二十）水文地质、工程测量、岩土工程；（二十一）其他（以实际专业为准）。"},{"i":8,"n":"第八条","txt":"工程咨询服务范围包括： （一）规划咨询：含总体规划、专项规划、区域规划及行业规划的编制； （二）项目咨询：含项目投资机会研究、投融资策划，项目建议书（预可行性研究）、项目可行性研究报告、项目申请报告、资金申请报告的编制，政府和社会资本合作（PPP）项目咨询等； （三）评估咨询：各级政府及有关部门委托的对规划、项目建议书、可行性研究报告、项目申请报告、资金申请报告、PPP项目实施方案、初步设计的评估，规划和项目中期评价、后评价，项目概预决算审查，及其他履行投资管理职能所需的专业技术服务； （四）全过程工程咨询：采用多种服务方式组合，为项目决策、实施和运营持续提供局部或整体解决方案以及管理服务。有关工程设计、工程造价、工程监理等资格，由国务院有关主管部门认定。"},{"i":9,"n":"第九条","txt":"工程咨询单位订立服务合同和开展相应的咨询业务，应当与备案的专业和服务范围一致。"},{"i":10,"n":"第十条","txt":"工程咨询单位应当建立健全咨询质量管理制度，建立和实行咨询成果质量、成果文件审核等岗位人员责任制。"},{"i":11,"n":"第十一条","txt":"工程咨询单位应当和委托方订立书面合同，约定各方权利义务并共同遵守。合同中应明确咨询活动形成的知识产权归属。"},{"i":12,"n":"第十二条","txt":"工程咨询实行有偿服务。工程咨询服务价格由双方协商确定，促进优质优价，禁止价格垄断和恶意低价竞争。"},{"i":13,"n":"第十三条","txt":"编写咨询成果文件应当依据法律法规、有关发展建设规划、技术标准、产业政策以及政府部门发布的标准规范等。"},{"i":14,"n":"第十四条","txt":"咨询成果文件上应当加盖工程咨询单位公章和咨询工程师（投资）执业专用章。 工程咨询单位对咨询质量负总责。主持该咨询业务的人员对咨询成果文件质量负主要直接责任，参与人员对其编写的篇章内容负责。 实行咨询成果质量终身负责制。工程咨询单位在开展项目咨询业务时，应在咨询成果文件中就符合本办法第十三条要求，及独立、公正、科学的原则作出信用承诺。工程项目在设计使用年限内，因工程咨询质量导致项目单位重大损失的，应倒查咨询成果质量责任，并根据本办法第三十、三十一条进行处理，形成工程咨询成果质量追溯机制。"},{"i":15,"n":"第十五条","txt":"工程咨询单位应当建立从业档案制度，将委托合同、咨询成果文件等存档备查。"},{"i":16,"n":"第十六条","txt":"承担编制任务的工程咨询单位，不得承担同一事项的评估咨询任务。 承担评估咨询任务的工程咨询单位，与同一事项的编制单位、项目业主单位之间不得存在控股、管理关系或者负责人为同一人的重大关联关系。"},{"i":17,"n":"第十七条","txt":"国家设立工程咨询（投资）专业技术人员水平评价类职业资格制度。 通过咨询工程师（投资）职业资格考试并取得职业资格证书的人员，表明其已具备从事工程咨询（投资）专业技术岗位工作的职业能力和水平。 取得咨询工程师（投资）职业资格证书的人员从事工程咨询工作的，应当选择且仅能同时选择一个工程咨询单位作为其执业单位，进行执业登记并取得登记证书。"},{"i":18,"n":"第十八条","txt":"咨询工程师（投资）是工程咨询行业的核心技术力量。工程咨询单位应当配备一定数量的咨询工程师（投资）。"},{"i":19,"n":"第十九条","txt":"国家发展改革委和人力资源社会保障部按职责分工负责工程咨询（投资）专业技术人员职业资格制度实施的指导、监督、检查工作。 中国工程咨询协会具体承担咨询工程师（投资）的管理工作，开展考试、执业登记、继续教育、执业检查等管理事务。"},{"i":20,"n":"第二十条","txt":"执业登记分为初始登记、变更登记、继续登记和注销登记四类。 申请登记的人员，应当选择已通过在线平台备案的工程咨询单位，按照本办法第七条划分的专业申请登记。申请人最多可以申请两个专业。"},{"i":21,"n":"第二十一条","txt":"申请人登记合格取得《中华人民共和国咨询工程师（投资）登记证书》和执业专用章，登记证书和执业专用章是咨询工程师（投资）的执业证明。登记的有效期为3年。"},{"i":22,"n":"第二十二条","txt":"工程咨询单位应具备良好信誉和相应能力。国家发展改革委应当推进工程咨询单位资信管理体系建设，指导监督行业组织开展资信评价，为委托单位择优选择工程咨询单位和政府部门实施重点监督提供参考依据。"},{"i":23,"n":"第二十三条","txt":"工程咨询单位资信评价等级以一定时期内的合同业绩、守法信用记录和专业技术力量为主要指标，分为甲级和乙级两个级别，具体标准由国家发展改革委制定。"},{"i":24,"n":"第二十四条","txt":"甲级资信工程咨询单位的评定工作，由国家发展改革委指导有关行业组织开展。 乙级资信工程咨询单位的评定工作，由省级发展改革委指导有关行业组织开展。"},{"i":25,"n":"第二十五条","txt":"开展工程咨询单位资信评价工作的行业组织，应当根据本办法及资信评价标准开展资信评价工作，并向获得资信评价的工程咨询单位颁发资信评价等级证书。"},{"i":26,"n":"第二十六条","txt":"工程咨询单位的资信评价结果，由国家和省级发展改革委通过在线平台和“信用中国”网站向社会公布。 行业自律性质的资信评价等级，仅作为委托咨询业务的参考。任何单位不得对资信评价设置机构数量限制，不得对各类工程咨询单位设置区域性、行业性从业限制，也不得对未参加或未获得资信评价的工程咨询单位设置执业限制。"},{"i":27,"n":"第二十七条","txt":"国家和省级发展改革委应当依照有关法律法规、本办法及有关规定，制订工程咨询单位监督检查计划，按照一定比例开展抽查，并及时公布抽查结果。监督检查内容主要包括： （一）遵守国家法律法规及有关规定的情况； （二）信息备案情况； （三）咨询质量管理制度建立情况； （四）咨询成果质量情况； （五）咨询成果文件档案建立情况； （六）其他应当检查的内容。"},{"i":28,"n":"第二十八条","txt":"中国工程咨询协会应当对咨询工程师（投资）执业情况进行检查。检查内容包括： （一）遵守国家法律法规及有关规定的情况； （二）登记申请材料的真实性； （三）遵守职业道德、廉洁从业情况； （四）行使权利、履行义务情况； （五）接受继续教育情况； （六）其他应当检查的情况。"},{"i":29,"n":"第二十九条","txt":"国家和省级发展改革委应当对实施行业自律管理的工程咨询行业组织开展年度评估，提出加强和改进自律管理的建议。对评估中发现问题的，按照本办法第三十二条处理。"},{"i":30,"n":"第三十条","txt":"工程咨询单位有下列行为之一的，由发展改革部门责令改正；情节严重的，给予警告处罚并从备案名录中移除；已获得资信评价等级的，由开展资信评价的组织取消其评价等级。触犯法律的，依法追究法律责任。 （一）备案信息存在弄虚作假或与实际情况不符的； （二）违背独立公正原则，帮助委托单位骗取批准文件和国家资金的； （三）弄虚作假、泄露委托方的商业秘密以及采取不正当竞争手段损害其他工程咨询单位利益的； （四）咨询成果存在严重质量问题的； （五）未建立咨询成果文件完整档案的； （六）伪造、涂改、出租、出借、转让资信评价等级证书的； （七）弄虚作假、提供虚假材料申请资信评价的； （八）弄虚作假、帮助他人申请咨询工程师（投资）登记的； （九）其他违反法律法规的行为。 对直接责任人员，由发展改革部门责令改正，或给予警告处罚；涉及咨询工程师（投资）的，按本办法第三十一条处理。"},{"i":31,"n":"第三十一条","txt":"咨询工程师（投资）有下列行为之一的，由中国工程咨询协会视情节轻重给予警告、通报批评、注销登记证书并收回执业专用章。触犯法律的，依法追究法律责任。 （一）在执业登记中弄虚作假的； （二）准许他人以本人名义执业的； （三）涂改或转让登记证书和执业专用章的； （四）接受任何影响公正执业的酬劳的。"},{"i":32,"n":"第三十二条","txt":"行业组织有下列情形之一的，由国家或省级发展改革委责令改正或停止有关行业自律管理工作；情节严重的，对行业组织和责任人员给予警告处罚。触犯法律的，依法追究法律责任。 （一）无故拒绝工程咨询单位申请资信评价的； （二）无故拒绝申请人申请咨询工程师（投资）登记的； （三）未按规定标准开展资信评价的； （四）未按规定开展咨询工程师（投资）登记的； （五）伙同申请单位或申请人弄虚作假的； （六）其他违反法律、法规的行为。"},{"i":33,"n":"第三十三条","txt":"工程咨询行业有关单位、组织和人员的违法违规信息，列入不良记录，及时通过在线平台和“信用中国”网站向社会公布，并建立违法失信联合惩戒机制。"},{"i":34,"n":"第三十四条","txt":"本办法所称省级发展改革委是指各省、自治区、直辖市及计划单列市、新疆生产建设兵团发展改革委。"},{"i":35,"n":"第三十五条","txt":"本办法由国家发展改革委负责解释。"},{"i":36,"n":"第三十六条","txt":"本办法自2017年12月6日起施行。《工程咨询单位资格认定办法》（国家发展改革委2005年第29号令）、《国家发展改革委关于适用〈工程咨询单位资格认定办法〉有关条款的通知》（发改投资〔2009〕620号）、《咨询工程师（投资）管理办法》（国家发展改革委2013年第2号令）同时废止。"}],"gongchengjianshexiangmukanchashejizhaobiaotoubiaobb5865a-2":[{"i":1,"n":"第一条","txt":"为规范工程建设项目勘察设计招标投标活动，提高投资效益，保证工程质量，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行工程建设项目勘察设计招标投标活动，适用本办法。"},{"i":3,"n":"第三条","txt":"工程建设项目符合《工程建设项目招标范围和规模标准规定》（国家计委令第3号）规定的范围和标准的，必须依据本办法进行招标。 任何单位和个人不得将依法必须进行招标的项目化整为零或者以其他任何方式规避招标。"},{"i":4,"n":"第四条","txt":"按照国家规定需要履行项目审批、核准手续的依法必须进行招标的项目，有下列情形之一的，经项目审批、核准部门审批、核准，项目的勘察设计可以不进行招标： （一）涉及国家安全、国家秘密、抢险救灾或者属于利用扶贫资金实行以工代赈、需要使用农民工等特殊情况，不适宜进行招标； （二）主要工艺、技术采用不可替代的专利或者专有技术，或者其建筑艺术造型有特殊要求； （三）采购人依法能够自行勘察、设计； （四）已通过招标方式选定的特许经营项目投资人依法能够自行勘察、设计； （五）技术复杂或专业性强，能够满足条件的勘察设计单位少于三家，不能形成有效竞争； （六）已建成项目需要改、扩建或者技术改造，由其他单位进行设计影响项目功能配套性； （七）国家规定其他特殊情形。"},{"i":5,"n":"第五条","txt":"勘察设计招标工作由招标人负责。任何单位和个人不得以任何方式非法干涉招标投标活动。"},{"i":6,"n":"第六条","txt":"各级发展改革、工业和信息化、住房城乡建设、交通运输、铁道、水利、商务、广电、民航等部门依照《国务院办公厅印发国务院有关部门实施招标投标活动行政监督的职责分工意见的通知》（国办发〔2000〕34号）和各地规定的职责分工，对工程建设项目勘察设计招标投标活动实施监督，依法查处招标投标活动中的违法行为。"},{"i":7,"n":"第七条","txt":"招标人可以依据工程建设项目的不同特点，实行勘察设计一次性总体招标；也可以在保证项目完整性、连续性的前提下，按照技术要求实行分段或分项招标。 招标人不得利用前款规定限制或者排斥潜在投标人或者投标。依法必须进行招标的项目的招标人不得利用前款规定规避招标。"},{"i":8,"n":"第八条","txt":"依法必须招标的工程建设项目，招标人可以对项目的勘察、设计、施工以及与工程建设有关的重要设备、材料的采购，实行总承包招标。"},{"i":9,"n":"第九条","txt":"依法必须进行勘察设计招标的工程建设项目，在招标时应当具备下列条件： （一）招标人已经依法成立； （二）按照国家有关规定需要履行项目审批、核准或者备案手续的，已经审批、核准或者备案； （三）勘察设计有相应资金或者资金来源已经落实； （四）所必需的勘察设计基础资料已经收集完成； （五）法律法规规定的其他条件。"},{"i":10,"n":"第十条","txt":"工程建设项目勘察设计招标分为公开招标和邀请招标。 国有资金投资占控股或者主导地位的工程建设项目，以及国务院发展和改革部门确定的国家重点项目和省、自治区、直辖市人民政府确定的地方重点项目，除符合本办法第十一条规定条件并依法获得批准外，应当公开招标。"},{"i":11,"n":"第十一条","txt":"依法必须进行公开招标的项目，在下列情况下可以进行邀请招标： （一）技术复杂、有特殊要求或者受自然环境限制，只有少量潜在投标人可供选择； （二）采用公开招标方式的费用占项目合同金额的比例过大。 有前款第二项所列情形，属于按照国家有关规定需要履行项目审批、核准手续的项目，由项目审批、核准部门在审批、核准项目时作出认定；其他项目由招标人申请有关行政监督部门作出认定。 招标人采用邀请招标方式的，应保证有三个以上具备承担招标项目勘察设计的能力，并具有相应资质的特定法人或者其他组织参加投标。"},{"i":12,"n":"第十二条","txt":"招标人应当按照资格预审公告、招标公告或者投标邀请书规定的时间、地点出售招标文件或者资格预审文件。自招标文件或者资格预审文件出售之日起至停止出售之日止，最短不得少于五日。"},{"i":13,"n":"第十三条","txt":"进行资格预审的，招标人只向资格预审合格的潜在投标人发售招标文件，并同时向资格预审不合格的潜在投标人告知资格预审结果。"},{"i":14,"n":"第十四条","txt":"凡是资格预审合格的潜在投标人都应被允许参加投标。 招标人不得以抽签、摇号等不合理条件限制或者排斥资格预审合格的潜在投标人参加投标。"},{"i":15,"n":"第十五条","txt":"招标人应当根据招标项目的特点和需要编制招标文件。 勘察设计招标文件应当包括下列内容： （一）投标须知； （二）投标文件格式及主要合同条款； （三）项目说明书，包括资金来源情况； （四）勘察设计范围，对勘察设计进度、阶段和深度要求； （五）勘察设计基础资料； （六）勘察设计费用支付方式，对未中标人是否给予补偿及补偿标准； （七）投标报价要求； （八）对投标人资格审查的标准； （九）评标标准和方法； （十）投标有效期。 投标有效期，从提交投标文件截止日起计算。 对招标文件的收费应仅限于补偿印刷、邮寄的成本支出，招标人不得通过出售招标文件谋取利益。"},{"i":16,"n":"第十六条","txt":"招标人负责提供与招标项目有关的基础资料，并保证所提供资料的真实性、完整性。涉及国家秘密的除外。"},{"i":17,"n":"第十七条","txt":"对于潜在投标人在阅读招标文件和现场踏勘中提出的疑问，招标人可以书面形式或召开投标预备会的方式解答，但需同时将解答以书面方式通知所有招标文件收受人。该解答的内容为招标文件的组成部分。"},{"i":18,"n":"第十八条","txt":"招标人可以要求投标人在提交符合招标文件规定要求的投标文件外，提交备选投标文件，但应当在招标文件中做出说明，并提出相应的评审和比较办法。"},{"i":19,"n":"第十九条","txt":"招标人应当确定潜在投标人编制投标文件所需要的合理时间。 依法必须进行勘察设计招标的项目，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不得少于二十日。"},{"i":20,"n":"第二十条","txt":"除不可抗力原因外，招标人在发布招标公告或者发出投标邀请书后不得终止招标，也不得在出售招标文件后终止招标。"},{"i":21,"n":"第二十一条","txt":"投标人是响应招标、参加投标竞争的法人或者其他组织。 在其本国注册登记，从事建筑、工程服务的国外设计企业参加投标的，必须符合中华人民共和国缔结或者参加的国际条约、协定中所作的市场准入承诺以及有关勘察设计市场准入的管理规定。 投标人应当符合国家规定的资质条件。"},{"i":22,"n":"第二十二条","txt":"投标人应当按照招标文件或者投标邀请书的要求编制投标文件。投标文件中的勘察设计收费报价，应当符合国务院价格主管部门制定的工程勘察设计收费标准。"},{"i":23,"n":"第二十三条","txt":"投标人在投标文件有关技术方案和要求中不得指定与工程建设项目有关的重要设备、材料的生产供应者，或者含有倾向或者排斥特定生产供应者的内容。"},{"i":24,"n":"第二十四条","txt":"招标文件要求投标人提交投标保证金的，保证金数额不得超过勘察设计估算费用的百分之二，最多不超过十万元人民币。 依法必须进行招标的项目的境内投标单位，以现金或者支票形式提交的投标保证金应当从其基本账户转出。"},{"i":25,"n":"第二十五条","txt":"在提交投标文件截止时间后到招标文件规定的投标有效期终止之前，投标人不得撤销其投标文件，否则招标人可以不退还投标保证金。"},{"i":26,"n":"第二十六条","txt":"投标人在投标截止时间前提交的投标文件，补充、修改或撤回投标文件的通知，备选投标文件等，都必须加盖所在单位公章，并且由其法定代表人或授权代表签字，但招标文件另有规定的除外。 招标人在接收上述材料时，应检查其密封或签章是否完好，并向投标人出具标明签收人和签收时间的回执。"},{"i":27,"n":"第二十七条","txt":"以联合体形式投标的，联合体各方应签订共同投标协议，连同投标文件一并提交招标人。 联合体各方不得再单独以自己名义，或者参加另外的联合体投同一个标。 招标人接受联合体投标并进行资格预审的，联合体应当在提交资格预审申请文件前组成。资格预审后联合体增减、更换成员的，其投标无效。"},{"i":28,"n":"第二十八条","txt":"联合体中标的，应指定牵头人或代表，授权其代表所有联合体成员与招标人签订合同，负责整个合同实施阶段的协调工作。但是，需要向招标人提交由所有联合体成员法定代表人签署的授权委托书。"},{"i":29,"n":"第二十九条","txt":"投标人不得以他人名义投标，也不得利用伪造、转让、无效或者租借的资质证书参加投标，或者以任何方式请其他单位在自己编制的投标文件代为签字盖章，损害国家利益、社会公共利益和招标人的合法权益。"},{"i":30,"n":"第三十条","txt":"投标人不得通过故意压低投资额、降低施工技术要求、减少占地面积，或者缩短工期等手段弄虚作假，骗取中标。"},{"i":31,"n":"第三十一条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行；除不可抗力原因外，招标人不得以任何理由拖延开标，或者拒绝开标。 投标人对开标有异议的，应当在开标现场提出，招标人应当当场作出答复，并制作记录。"},{"i":32,"n":"第三十二条","txt":"评标工作由评标委员会负责。评标委员会的组成方式及要求，按《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》及《评标委员会和评标方法暂行规定》（国家计委等七部委联合令第12号）的有关规定执行。"},{"i":33,"n":"第三十三条","txt":"勘察设计评标一般采取综合评估法进行。评标委员会应当按照招标文件确定的评标标准和方法，结合经批准的项目建议书、可行性研究报告或者上阶段设计批复文件，对投标人的业绩、信誉和勘察设计人员的能力以及勘察设计方案的优劣进行综合评定。 招标文件中没有规定的标准和方法，不得作为评标的依据。"},{"i":34,"n":"第三十四条","txt":"评标委员会可以要求投标人对其技术文件进行必要的说明或介绍，但不得提出带有暗示性或诱导性的问题，也不得明确指出其投标文件中的遗漏和错误。"},{"i":35,"n":"第三十五条","txt":"根据招标文件的规定，允许投标人投备选标的，评标委员会可以对中标人所提交的备选标进行评审，以决定是否采纳备选标。不符合中标条件的投标人的备选标不予考虑。"},{"i":36,"n":"第三十六条","txt":"投标文件有下列情况之一的，评标委员会应当否决其投标： （一）未经投标单位盖章和单位负责人签字； （二）投标报价不符合国家颁布的勘察设计取费标准，或者低于成本，或者高于招标文件设定的最高投标限价； （三）未响应招标文件的实质性要求和条件。"},{"i":37,"n":"第三十七条","txt":"投标人有下列情况之一的，评标委员会应当否决其投标： （一）不符合国家或者招标文件规定的资格条件； （二）与其他投标人或者与招标人串通投标； （三）以他人名义投标，或者以其他方式弄虚作假； （四）以向招标人或者评标委员会成员行贿的手段谋取中标； （五）以联合体形式投标，未提交共同投标协议； （六）提交两个以上不同的投标文件或者投标报价，但招标文件要求提交备选投标的除外。"},{"i":38,"n":"第三十八条","txt":"评标委员会完成评标后，应当向招标人提出书面评标报告，推荐合格的中标候选人。 评标报告的内容应当符合《评标委员会和评标方法暂行规定》第四十二条的规定。但是，评标委员会决定否决所有投标的，应在评标报告中详细说明理由。"},{"i":39,"n":"第三十九条","txt":"评标委员会推荐的中标候选人应当限定在一至三人，并标明排列顺序。 能够最大限度地满足招标文件中规定的各项综合评价标准的投标人，应当推荐为中标候选人。"},{"i":40,"n":"第四十条","txt":"国有资金占控股或者主导地位的依法必须招标的项目，招标人应当确定排名第一的中标候选人为中标人。 排名第一的中标候选人放弃中标、因不可抗力提出不能履行合同，不按照招标文件要求提交履约保证金，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人。依次确定其他中标候选人与招标人预期差距较大，或者对招标人明显不利的，招标人可以重新招标。 招标人可以授权评标委员会直接确定中标人。 国务院对中标人的确定另有规定的，从其规定。"},{"i":41,"n":"第四十一条","txt":"招标人应在接到评标委员会的书面评标报告之日起三日内公示中标候选人，公示期不少于三日。"},{"i":42,"n":"第四十二条","txt":"招标人和中标人应当在投标有效期内并在自中标通知书发出之日起三十日内，按照招标文件和中标人的投标文件订立书面合同。 中标人履行合同应当遵守《合同法》以及《建设工程勘察设计管理条例》中勘察设计文件编制实施的有关规定。"},{"i":43,"n":"第四十三条","txt":"招标人不得以压低勘察设计费、增加工作量、缩短勘察设计周期等做为发出中标通知书的条件，也不得与中标人再行订立背离合同实质性内容的其他协议。"},{"i":44,"n":"第四十四条","txt":"招标人与中标人签订合同后五日内，应当向中标人和未中标人一次性退还投标保证金及银行同期存款利息。招标文件中规定给予未中标人经济补偿的，也应在此期限内一并给付。 招标文件要求中标人提交履约保证金的，中标人应当提交；经中标人同意，可将其投标保证金抵作履约保证金。"},{"i":45,"n":"第四十五条","txt":"招标人或者中标人采用其他未中标人投标文件中技术方案的，应当征得未中标人的书面同意，并支付合理的使用费。"},{"i":46,"n":"第四十六条","txt":"评标定标工作应当在投标有效期内完成，不能如期完成的，招标人应当通知所有投标人延长投标有效期。 同意延长投标有效期的投标人应当相应延长其投标担保的有效期，但不得修改投标文件的实质性内容。 拒绝延长投标有效期的投标人有权收回投标保证金。招标文件中规定给予未中标人补偿的，拒绝延长的投标人有权获得补偿。"},{"i":47,"n":"第四十七条","txt":"依法必须进行勘察设计招标的项目，招标人应当在确定中标人之日起十五日内，向有关行政监督部门提交招标投标情况的书面报告。 书面报告一般应包括以下内容： （一）招标项目基本情况； （二）投标人情况； （三）评标委员会成员名单； （四）开标情况； （五）评标标准和方法； （六）否决投标情况； （七）评标委员会推荐的经排序的中标候选人名单； （八）中标结果； （九）未确定排名第一的中标候选人为中标人的原因； （十）其他需说明的问题。"},{"i":48,"n":"第四十八条","txt":"在下列情况下，依法必须招标项目的招标人在分析招标失败的原因并采取相应措施后，应当依照本办法重新招标： （一）资格预审合格的潜在投标人不足三个的； （二）在投标截止时间前提交投标文件的投标人少于三个的； （三）所有投标均被否决的； （四）评标委员会否决不合格投标后，因有效投标不足三个使得投标明显缺乏竞争，评标委员会决定否决全部投标的； （五）根据第四十六条规定，同意延长投标有效期的投标人少于三个的。"},{"i":49,"n":"第四十九条","txt":"招标人重新招标后，发生本办法第四十八条情形之一的，属于按照国家规定需要政府审批、核准的项目，报经原项目审批、核准部门审批、核准后可以不再进行招标；其他工程建设项目，招标人可自行决定不再进行招标。"},{"i":50,"n":"第五十条","txt":"招标人有下列限制或者排斥潜在投标人行为之一的，由有关行政监督部门依照招标投标法第五十一条的规定处罚；其中，构成依法必须进行勘察设计招标的项目的招标人规避招标的，依照招标投标法第四十九条的规定处罚： （一）依法必须公开招标的项目不按照规定在指定媒介发布资格预审公告或者招标公告； （二）在不同媒介发布的同一招标项目的资格预审公告或者招标公告的内容不一致，影响潜在投标人申请资格预审或者投标。"},{"i":51,"n":"第五十一条","txt":"招标人有下列情形之一的，由有关行政监督部门责令改正，可以处10万元以下的罚款： （一）依法应当公开招标而采用邀请招标； （二）招标文件、资格预审文件的发售、澄清、修改的时限，或者确定的提交资格预审申请文件、投标文件的时限不符合招标投标法和招标投标法实施条例规定； （三）接受未通过资格预审的单位或者个人参加投标； （四）接受应当拒收的投标文件。 招标人有前款第一项、第三项、第四项所列行为之一的，对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":52,"n":"第五十二条","txt":"依法必须进行招标的项目的投标人以他人名义投标，利用伪造、转让、租借、无效的资质证书参加投标，或者请其他单位在自己编制的投标文件上代为签字盖章，弄虚作假，骗取中标的，中标无效。尚未构成犯罪的，处中标项目金额千分之五以上千分之十以下的罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下的罚款；有违法所得的，并处没收违法所得；情节严重的，取消其一年至三年内参加依法必须进行招标的项目的投标资格并予以公告，直至由工商行政管理机关吊销营业执照。"},{"i":53,"n":"第五十三条","txt":"招标人以抽签、摇号等不合理的条件限制或者排斥资格预审合格的潜在投标人参加投标，对潜在投标人实行歧视待遇的，强制要求投标人组成联合体共同投标的，或者限制投标人之间竞争的，责令改正，可以处一万元以上五万元以下的罚款。 依法必须进行招标的项目的招标人不按照规定组建评标委员会，或者确定、更换评标委员会成员违反招标投标法和招标投标法实施条例规定的，由有关行政监督部门责令改正，可以处10万元以下的罚款，对单位直接负责的主管人员和其他直接责任人员依法给予处分；违法确定或者更换的评标委员会成员作出的评审结论无效，依法重新进行评审。"},{"i":54,"n":"第五十四条","txt":"评标委员会成员有下列行为之一的，由有关行政监督部门责令改正；情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标；情节特别严重的，取消其担任评标委员会成员的资格： （一）不按照招标文件规定的评标标准和方法评标； （二）应当回避而不回避； （三）擅离职守； （四）私下接触投标人； （五）向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求； （六）对依法应当否决的投标不提出否决意见； （七）暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明； （八）其他不客观、不公正履行职务的行为。"},{"i":55,"n":"第五十五条","txt":"招标人与中标人不按照招标文件和中标人的投标文件订立合同，责令改正，可以处中标项目金额千分之五以上千分之十以下的罚款。"},{"i":56,"n":"第五十六条","txt":"本办法对违法行为及其处罚措施未做规定的，依据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》和有关法律、行政法规的规定执行。"},{"i":57,"n":"第五十七条","txt":"使用国际组织或者外国政府贷款、援助资金的项目进行招标，贷款方、资金提供方对工程勘察设计招标投标的条件和程序另有规定的，可以适用其规定，但违背中华人民共和国社会公共利益的除外。"},{"i":58,"n":"第五十八条","txt":"本办法发布之前有关勘察设计招标投标的规定与本办法不一致的，以本办法为准。法律或者行政法规另有规定的，从其规定。"},{"i":59,"n":"第五十九条","txt":"本办法由国家发展和改革委员会会同有关部门负责解释。"},{"i":60,"n":"第六十条","txt":"本办法自2003年8月1日起施行。"}],"gongchengjianshexiangmukanchashejizhaobiaotoubiaobb5865a":[{"i":1,"n":"第一条","txt":"为规范工程建设项目勘察设计招标投标活动，提高投资效益，保证工程质量，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行工程建设项目勘察设计招标投标活动，适用本办法。"},{"i":3,"n":"第三条","txt":"工程建设项目符合《工程建设项目招标范围和规模标准规定》(国家计委令第3号)规定的范围和标准的，必须依据本办法进行招标。 任何单位和个人不得将依法必须进行招标的项目化整为零或者以其他任何方式规避招标。"},{"i":4,"n":"第四条","txt":"按照国家规定需要履行项目审批、核准手续的依法必须进行招标的项目，有下列情形之一的，经项目审批、核准部门审批、核准，项目的勘察设计可以不进行招标： (一)涉及国家安全、国家秘密、抢险救灾或者属于利用扶贫资金实行以工代赈、需要使用农民工等特殊情况，不适宜进行招标; (二)主要工艺、技术采用不可替代的专利或者专有技术，或者其建筑艺术造型有特殊要求; (三)采购人依法能够自行勘察、设计; (四)已通过招标方式选定的特许经营项目投资人依法能够自行勘察、设计; (五)技术复杂或专业性强，能够满足条件的勘察设计单位少于三家，不能形成有效竞争; (六)已建成项目需要改、扩建或者技术改造，由其他单位进行设计影响项目功能配套性; (七)国家规定其他特殊情形。"},{"i":5,"n":"第五条","txt":"勘察设计招标工作由招标人负责。任何单位和个人不得以任何方式非法干涉招标投标活动。"},{"i":6,"n":"第六条","txt":"各级发展改革、工业和信息化、住房城乡建设、交通运输、铁道、水利、商务、广电、民航等部门依照《国务院办公厅印发国务院有关部门实施招标投标活动行政监督的职责分工意见的通知》(国办发[2000]34号)和各地规定的职责分工，对工程建设项目勘察设计招标投标活动实施监督，依法查处招标投标活动中的违法行为。"},{"i":7,"n":"第七条","txt":"招标人可以依据工程建设项目的不同特点，实行勘察设计一次性总体招标;也可以在保证项目完整性、连续性的前提下，按照技术要求实行分段或分项招标。 招标人不得利用前款规定限制或者排斥潜在投标人或者投标。依法必须进行招标的项目的招标人不得利用前款规定规避招标。"},{"i":8,"n":"第八条","txt":"依法必须招标的工程建设项目，招标人可以对项目的勘察、设计、施工以及与工程建设有关的重要设备、材料的采购，实行总承包招标。"},{"i":9,"n":"第九条","txt":"依法必须进行勘察设计招标的工程建设项目，在招标时应当具备下列条件： (一)招标人已经依法成立; (二)按照国家有关规定需要履行项目审批、核准或者备案手续的，已经审批、核准或者备案; (三)勘察设计有相应资金或者资金来源已经落实; (四)所必需的勘察设计基础资料已经收集完成; (五)法律法规规定的其他条件。"},{"i":10,"n":"第十条","txt":"工程建设项目勘察设计招标分为公开招标和邀请招标。 国有资金投资占控股或者主导地位的工程建设项目，以及国务院发展和改革部门确定的国家重点项目和省、自治区、直辖市人民政府确定的地方重点项目，除符合本办法第十一条规定条件并依法获得批准外，应当公开招标。"},{"i":11,"n":"第十一条","txt":"依法必须进行公开招标的项目，在下列情况下可以进行邀请招标： (一)技术复杂、有特殊要求或者受自然环境限制，只有少量潜在投标人可供选择; (二)采用公开招标方式的费用占项目合同金额的比例过大。 有前款第二项所列情形，属于按照国家有关规定需要履行项目审批、核准手续的项目，由项目审批、核准部门在审批、核准项目时作出认定;其他项目由招标人申请有关行政监督部门作出认定。 招标人采用邀请招标方式的，应保证有三个以上具备承担招标项目勘察设计的能力，并具有相应资质的特定法人或者其他组织参加投标。"},{"i":12,"n":"第十二条","txt":"招标人应当按照资格预审公告、招标公告或者投标邀请书规定的时间、地点出售招标文件或者资格预审文件。自招标文件或者资格预审文件出售之日起至停止出售之日止，最短不得少于五日。"},{"i":13,"n":"第十三条","txt":"进行资格预审的，招标人只向资格预审合格的潜在投标人发售招标文件，并同时向资格预审不合格的潜在投标人告知资格预审结果。"},{"i":14,"n":"第十四条","txt":"凡是资格预审合格的潜在投标人都应被允许参加投标。 招标人不得以抽签、摇号等不合理条件限制或者排斥资格预审合格的潜在投标人参加投标。"},{"i":15,"n":"第十五条","txt":"招标人应当根据招标项目的特点和需要编制招标文件。 勘察设计招标文件应当包括下列内容： (一)投标须知; (二)投标文件格式及主要合同条款; (三)项目说明书，包括资金来源情况; (四)勘察设计范围，对勘察设计进度、阶段和深度要求; (五)勘察设计基础资料; (六)勘察设计费用支付方式，对未中标人是否给予补偿及补偿标准; (七)投标报价要求; (八)对投标人资格审查的标准; (九)评标标准和方法; (十)投标有效期。 投标有效期，从提交投标文件截止日起计算。 对招标文件的收费应仅限于补偿印刷、邮寄的成本支出，招标人不得通过出售招标文件谋取利益。"},{"i":16,"n":"第十六条","txt":"招标人负责提供与招标项目有关的基础资料，并保证所提供资料的真实性、完整性。涉及国家秘密的除外。"},{"i":17,"n":"第十七条","txt":"对于潜在投标人在阅读招标文件和现场踏勘中提出的疑问，招标人可以书面形式或召开投标预备会的方式解答，但需同时将解答以书面方式通知所有招标文件收受人。该解答的内容为招标文件的组成部分。"},{"i":18,"n":"第十八条","txt":"招标人可以要求投标人在提交符合招标文件规定要求的投标文件外，提交备选投标文件，但应当在招标文件中做出说明，并提出相应的评审和比较办法。"},{"i":19,"n":"第十九条","txt":"招标人应当确定潜在投标人编制投标文件所需要的合理时间。 依法必须进行勘察设计招标的项目，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不得少于二十日。"},{"i":20,"n":"第二十条","txt":"除不可抗力原因外，招标人在发布招标公告或者发出投标邀请书后不得终止招标，也不得在出售招标文件后终止招标。"},{"i":21,"n":"第二十一条","txt":"投标人是响应招标、参加投标竞争的法人或者其他组织。 在其本国注册登记，从事建筑、工程服务的国外设计企业参加投标的，必须符合中华人民共和国缔结或者参加的国际条约、协定中所作的市场准入承诺以及有关勘察设计市场准入的管理规定。 投标人应当符合国家规定的资质条件。"},{"i":22,"n":"第二十二条","txt":"投标人应当按照招标文件或者投标邀请书的要求编制投标文件。投标文件中的勘察设计收费报价，应当符合国务院价格主管部门制定的工程勘察设计收费标准。"},{"i":23,"n":"第二十三条","txt":"投标人在投标文件有关技术方案和要求中不得指定与工程建设项目有关的重要设备、材料的生产供应者，或者含有倾向或者排斥特定生产供应者的内容。"},{"i":24,"n":"第二十四条","txt":"招标文件要求投标人提交投标保证金的，保证金数额不得超过勘察设计估算费用的百分之二，最多不超过十万元人民币。 依法必须进行招标的项目的境内投标单位，以现金或者支票形式提交的投标保证金应当从其基本账户转出。"},{"i":25,"n":"第二十五条","txt":"在提交投标文件截止时间后到招标文件规定的投标有效期终止之前，投标人不得撤销其投标文件，否则招标人可以不退还投标保证金。"},{"i":26,"n":"第二十六条","txt":"投标人在投标截止时间前提交的投标文件，补充、修改或撤回投标文件的通知，备选投标文件等，都必须加盖所在单位公章，并且由其法定代表人或授权代表签字，但招标文件另有规定的除外。 招标人在接收上述材料时，应检查其密封或签章是否完好，并向投标人出具标明签收人和签收时间的回执。"},{"i":27,"n":"第二十七条","txt":"以联合体形式投标的，联合体各方应签订共同投标协议，连同投标文件一并提交招标人。 联合体各方不得再单独以自己名义，或者参加另外的联合体投同一个标。 招标人接受联合体投标并进行资格预审的，联合体应当在提交资格预审申请文件前组成。资格预审后联合体增减、更换成员的，其投标无效。"},{"i":28,"n":"第二十八条","txt":"联合体中标的，应指定牵头人或代表，授权其代表所有联合体成员与招标人签订合同，负责整个合同实施阶段的协调工作。但是，需要向招标人提交由所有联合体成员法定代表人签署的授权委托书。"},{"i":29,"n":"第二十九条","txt":"投标人不得以他人名义投标，也不得利用伪造、转让、无效或者租借的资质证书参加投标，或者以任何方式请其他单位在自己编制的投标文件代为签字盖章，损害国家利益、社会公共利益和招标人的合法权益。"},{"i":30,"n":"第三十条","txt":"投标人不得通过故意压低投资额、降低施工技术要求、减少占地面积，或者缩短工期等手段弄虚作假，骗取中标。"},{"i":31,"n":"第三十一条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行;除不可抗力原因外，招标人不得以任何理由拖延开标，或者拒绝开标。 投标人对开标有异议的，应当在开标现场提出，招标人应当当场作出答复，并制作记录。"},{"i":32,"n":"第三十二条","txt":"评标工作由评标委员会负责。评标委员会的组成方式及要求，按《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》及《评标委员会和评标方法暂行规定》(国家计委等七部委联合令第12号)的有关规定执行。"},{"i":33,"n":"第三十三条","txt":"勘察设计评标一般采取综合评估法进行。评标委员会应当按照招标文件确定的评标标准和方法，结合经批准的项目建议书、可行性研究报告或者上阶段设计批复文件，对投标人的业绩、信誉和勘察设计人员的能力以及勘察设计方案的优劣进行综合评定。 招标文件中没有规定的标准和方法，不得作为评标的依据。"},{"i":34,"n":"第三十四条","txt":"评标委员会可以要求投标人对其技术文件进行必要的说明或介绍，但不得提出带有暗示性或诱导性的问题，也不得明确指出其投标文件中的遗漏和错误。"},{"i":35,"n":"第三十五条","txt":"根据招标文件的规定，允许投标人投备选标的，评标委员会可以对中标人所提交的备选标进行评审，以决定是否采纳备选标。不符合中标条件的投标人的备选标不予考虑。"},{"i":36,"n":"第三十六条","txt":"投标文件有下列情况之一的，评标委员会应当否决其投标： (一)未经投标单位盖章和单位负责人签字; (二)投标报价不符合国家颁布的勘察设计取费标准，或者低于成本，或者高于招标文件设定的最高投标限价; (三)未响应招标文件的实质性要求和条件。"},{"i":37,"n":"第三十七条","txt":"投标人有下列情况之一的，评标委员会应当否决其投标： (一)不符合国家或者招标文件规定的资格条件; (二)与其他投标人或者与招标人串通投标; (三)以他人名义投标，或者以其他方式弄虚作假; (四)以向招标人或者评标委员会成员行贿的手段谋取中标; (五)以联合体形式投标，未提交共同投标协议; (六)提交两个以上不同的投标文件或者投标报价，但招标文件要求提交备选投标的除外。"},{"i":38,"n":"第三十八条","txt":"评标委员会完成评标后，应当向招标人提出书面评标报告，推荐合格的中标候选人。 评标报告的内容应当符合《评标委员会和评标方法暂行规定》第四十二条的规定。但是，评标委员会决定否决所有投标的，应在评标报告中详细说明理由。"},{"i":39,"n":"第三十九条","txt":"评标委员会推荐的中标候选人应当限定在一至三人，并标明排列顺序。 能够最大限度地满足招标文件中规定的各项综合评价标准的投标人，应当推荐为中标候选人。"},{"i":40,"n":"第四十条","txt":"国有资金占控股或者主导地位的依法必须招标的项目，招标人应当确定排名第一的中标候选人为中标人。 排名第一的中标候选人放弃中标、因不可抗力提出不能履行合同，不按照招标文件要求提交履约保证金，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人。依次确定其他中标候选人与招标人预期差距较大，或者对招标人明显不利的，招标人可以重新招标。 招标人可以授权评标委员会直接确定中标人。 国务院对中标人的确定另有规定的，从其规定。"},{"i":41,"n":"第四十一条","txt":"招标人应在接到评标委员会的书面评标报告之日起三日内公示中标候选人，公示期不少于三日。"},{"i":42,"n":"第四十二条","txt":"招标人和中标人应当在投标有效期内并在自中标通知书发出之日起三十日内，按照招标文件和中标人的投标文件订立书面合同。 中标人履行合同应当遵守《合同法》以及《建设工程勘察设计管理条例》中勘察设计文件编制实施的有关规定。"},{"i":43,"n":"第四十三条","txt":"招标人不得以压低勘察设计费、增加工作量、缩短勘察设计周期等作为发出中标通知书的条件，也不得与中标人再行订立背离合同实质性内容的其他协议。"},{"i":44,"n":"第四十四条","txt":"招标人与中标人签订合同后五日内，应当向中标人和未中标人一次性退还投标保证金及银行同期存款利息。招标文件中规定给予未中标人经济补偿的，也应在此期限内一并给付。 招标文件要求中标人提交履约保证金的，中标人应当提交;经中标人同意，可将其投标保证金抵作履约保证金。"},{"i":45,"n":"第四十五条","txt":"招标人或者中标人采用其他未中标人投标文件中技术方案的，应当征得未中标人的书面同意，并支付合理的使用费。"},{"i":46,"n":"第四十六条","txt":"评标定标工作应当在投标有效期内完成，不能如期完成的，招标人应当通知所有投标人延长投标有效期。 同意延长投标有效期的投标人应当相应延长其投标担保的有效期，但不得修改投标文件的实质性内容。 拒绝延长投标有效期的投标人有权收回投标保证金。招标文件中规定给予未中标人补偿的，拒绝延长的投标人有权获得补偿。"},{"i":47,"n":"第四十七条","txt":"依法必须进行勘察设计招标的项目，招标人应当在确定中标人之日起十五日内，向有关行政监督部门提交招标投标情况的书面报告。 书面报告一般应包括以下内容： (一)招标项目基本情况; (二)投标人情况; (三)评标委员会成员名单; (四)开标情况; (五)评标标准和方法; (六)否决投标情况; (七)评标委员会推荐的经排序的中标候选人名单; (八)中标结果; (九)未确定排名第一的中标候选人为中标人的原因; (十)其他需说明的问题。"},{"i":48,"n":"第四十八条","txt":"在下列情况下，依法必须招标项目的招标人在分析招标失败的原因并采取相应措施后，应当依照本办法重新招标： (一)资格预审合格的潜在投标人不足三个的; (二)在投标截止时间前提交投标文件的投标人少于三个的; (三)所有投标均被否决的; (四)评标委员会否决不合格投标后，因有效投标不足三个使得投标明显缺乏竞争，评标委员会决定否决全部投标的; (五)根据第四十六条规定，同意延长投标有效期的投标人少于三个的。"},{"i":49,"n":"第四十九条","txt":"招标人重新招标后，发生本办法第四十八条情形之一的，属于按照国家规定需要政府审批、核准的项目，报经原项目审批、核准部门审批、核准后可以不再进行招标;其他工程建设项目，招标人可自行决定不再进行招标。"},{"i":50,"n":"第五十条","txt":"招标人有下列限制或者排斥潜在投标人行为之一的，由有关行政监督部门依照招标投标法第五十一条的规定处罚;其中，构成依法必须进行勘察设计招标的项目的招标人规避招标的，依照招标投标法第四十九条的规定处罚： (一)依法必须公开招标的项目不按照规定在指定媒介发布资格预审公告或者招标公告; (二)在不同媒介发布的同一招标项目的资格预审公告或者招标公告的内容不一致，影响潜在投标人申请资格预审或者投标。"},{"i":51,"n":"第五十一条","txt":"招标人有下列情形之一的，由有关行政监督部门责令改正，可以处10万元以下的罚款： (一)依法应当公开招标而采用邀请招标; (二)招标文件、资格预审文件的发售、澄清、修改的时限，或者确定的提交资格预审申请文件、投标文件的时限不符合招标投标法和招标投标法实施条例规定; (三)接受未通过资格预审的单位或者个人参加投标; (四)接受应当拒收的投标文件。 招标人有前款第一项、第三项、第四项所列行为之一的，对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":52,"n":"第五十二条","txt":"依法必须进行招标的项目的投标人以他人名义投标，利用伪造、转让、租借、无效的资质证书参加投标，或者请其他单位在自己编制的投标文件上代为签字盖章，弄虚作假，骗取中标的，中标无效。尚未构成犯罪的，处中标项目金额千分之五以上千分之十以下的罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下的罚款;有违法所得的，并处没收违法所得;情节严重的，取消其一年至三年内参加依法必须进行招标的项目的投标资格并予以公告，直至由工商行政管理机关吊销营业执照。"},{"i":53,"n":"第五十三条","txt":"招标人以抽签、摇号等不合理的条件限制或者排斥资格预审合格的潜在投标人参加投标，对潜在投标人实行歧视待遇的，强制要求投标人组成联合体共同投标的，或者限制投标人之间竞争的，责令改正，可以处一万元以上五万元以下的罚款。 依法必须进行招标的项目的招标人不按照规定组建评标委员会，或者确定、更换评标委员会成员违反招标投标法和招标投标法实施条例规定的，由有关行政监督部门责令改正，可以处10万元以下的罚款，对单位直接负责的主管人员和其他直接责任人员依法给予处分;违法确定或者更换的评标委员会成员作出的评审结论无效，依法重新进行评审。"},{"i":54,"n":"第五十四条","txt":"评标委员会成员有下列行为之一的，由有关行政监督部门责令改正;情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标;情节特别严重的，取消其担任评标委员会成员的资格： (一)不按照招标文件规定的评标标准和方法评标; (二)应当回避而不回避; (三)擅离职守; (四)私下接触投标人; (五)向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求; (六)对依法应当否决的投标不提出否决意见; (七)暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明; (八)其他不客观、不公正履行职务的行为。"},{"i":55,"n":"第五十五条","txt":"招标人与中标人不按照招标文件和中标人的投标文件订立合同，责令改正，可以处中标项目金额千分之五以上千分之十以下的罚款。"},{"i":56,"n":"第五十六条","txt":"本办法对违法行为及其处罚措施未做规定的，依据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》和有关法律、行政法规的规定执行。"},{"i":57,"n":"第五十七条","txt":"使用国际组织或者外国政府贷款、援助资金的项目进行招标，贷款方、资金提供方对工程勘察设计招标投标的条件和程序另有规定的，可以适用其规定，但违背中华人民共和国社会公共利益的除外。"},{"i":58,"n":"第五十八条","txt":"本办法发布之前有关勘察设计招标投标的规定与本办法不一致的，以本办法为准。法律或者行政法规另有规定的，从其规定。"},{"i":59,"n":"第五十九条","txt":"本办法由国家发展和改革委员会会同有关部门负责解释。"},{"i":60,"n":"第六十条","txt":"本办法自2003年8月1日起施行。"}],"gongchengjianshexiangmuzhaobiaotoubiaohuodongtousufb529c-2":[{"i":1,"n":"第一条","txt":"为保护国家利益、社会公共利益和招标投标当事人的合法权益，建立公平、高效的工程建设项目招标投标活动投诉处理机制，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于工程建设项目招标投标活动的投诉及其处理活动。 前款所称招标投标活动，包括招标、投标、开标、评标、中标以及签订合同等各阶段。"},{"i":3,"n":"第三条","txt":"投标人或者其他利害关系人认为招标投标活动不符合法律、法规和规章规定的，有权依法向有关行政监督部门投诉。 前款所称其他利害关系人是指投标人以外的，与招标项目或者招标活动有直接和间接利益关系的法人、其他组织和自然人。"},{"i":4,"n":"第四条","txt":"各级发展改革、工业和信息化、住房城乡建设、水利、交通运输、铁道、商务、民航等招标投标活动行政监督部门，依照《国务院办公厅印发国务院有关部门实施招标投标活动行政监督的职责分工的意见的通知》（国办发〔2000〕34号）和地方各级人民政府规定的职责分工，受理投诉并依法做出处理决定。 对国家重大建设项目（含工业项目）招标投标活动的投诉，由国家发展改革委受理并依法做出处理决定。对国家重大建设项目招标投标活动的投诉，有关行业行政监督部门已经收到的，应当通报国家发展改革委，国家发展改革委不再受理。"},{"i":5,"n":"第五条","txt":"行政监督部门处理投诉时，应当坚持公平、公正、高效原则，维持国家利益、社会公共利益和招标投标当事人的合法权益。"},{"i":6,"n":"第六条","txt":"行政监督部门应当确定本部门内部负责受理投诉的机构及其电话、传真、电子信箱和通讯地址，并向社会公布。"},{"i":7,"n":"第七条","txt":"投诉人投诉时，应当提交投诉书。投诉书应当包括下列内容： （一）投诉人的名称、地址及有效联系方式； （二）被投诉人的名称、地址及有效联系方式； （三）投诉事项的基本事实； （四）相关请求及主张； （五）有效线索和相关证明材料。 对招标投标法实施条例规定应先提出异议的事项进行投诉的，应当附提出异议的证明文件。已向有关行政监督部门投诉的，应当一并说明。 投诉人是法人的，投诉书必须由其法定代表人或者授权代表签字并盖章；其他组织或者自然人投诉的，投诉书必须由其主要负责人或者投诉人本人签字，并附有效身份证明复印件。 投诉书有关材料是外文的，投诉人应当同时提供其中文译本。"},{"i":8,"n":"第八条","txt":"投诉人不得以投诉为名排挤竞争对手，不得进行虚假、恶意投诉，阻碍招标投标活动的正常进行。"},{"i":9,"n":"第九条","txt":"投诉人认为招标投标活动不符合法律行政法规规定的，可以在知道或者应当知道之日起十日内提出书面投诉。依照有关行政法规提出异议的，异议答复期间不计算在内。"},{"i":10,"n":"第十条","txt":"投诉人可以自己直接投诉，也可以委托代理人办理投诉事务。代理人办理投诉事务时，应将授权委托书连同投诉书一并提交给行政监督部门。授权委托书应当明确有关委托代理权限和事项。"},{"i":11,"n":"第十一条","txt":"行政监督部门收到投诉书后，应当在三个工作日内进行审查，视情况分别做出以下处理决定。 （一）不符合投诉处理条件的，决定不予受理，并将不予受理的理由书面告知投诉人； （二）对符合投诉处理条件，但不属于本部门受理的投诉，书面告知投诉人向其他行政监督部门提出投诉； 对于符合投诉处理条件并决定受理的，收到投诉书之日即为正式受理。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的投诉，不予受理； （一）投诉人不是所投诉招标投标活动的参与者，或者与投诉项目无任何利害关系； （二）投诉事项不具体，且未提供有效线索，难以查证的； （三）投诉书未署具投诉人真实姓名、签字和有效联系方式的；以法人名义投诉的，投诉书未经法定代表人签字并加盖公章的； （四）超过投诉时效的； （五）已经作出处理决定，并且投诉人没有提出新的证据； （六）投诉事项应先提出异议没有提出异议、已进入行政复议或行政诉讼程序的。"},{"i":13,"n":"第十三条","txt":"行政监督部门负责投诉处理的工作人员，有下列情形之一的，应当主动回避： （一）近亲属是被投诉人、投诉人，或者是被投诉人、投诉人的主要负责人； （二）在近三年内本人曾经在被投诉人单位担任高级管理职务； （三）与被投诉人、投诉人有其他利害关系，可能影响对投诉事项公正处理的。"},{"i":14,"n":"第十四条","txt":"行政监督部门受理投诉后，应当调取、查阅有关文件，调查、核实有关情况。 对情况复杂、涉及面广的重大投诉事项，有权受理投诉的行政监督部门可以会同其他有关的行政监督部门进行联合调查，共同研究后由受理部门做出处理决定。"},{"i":15,"n":"第十五条","txt":"行政监督部门调查取证时，应当由两名以上行政执法人员进行，并做笔录，交被调查人签字确认。"},{"i":16,"n":"第十六条","txt":"在投诉处理过程中，行政监督部门应当听取被投诉人的陈述和申辩，必要时可通知投诉人和被投诉人进行质证。"},{"i":17,"n":"第十七条","txt":"行政监督部门负责处理投诉的人员应当严格遵守保密规定，对于在投诉处理过程中所接触到的国家秘密、商业秘密应当予以保密，也不得将投诉事项透露给与投诉无关的其他单位和个人。"},{"i":18,"n":"第十八条","txt":"行政监督部门处理投诉，有权查阅、复制有关文件、资料，调查有关情况，相关单位和人员应当予以配合。必要时，行政监督部门可以责令暂停招标投标活动。 对行政监督部门依法进行的调查，投诉人、被投诉人以及评标委员会成员等与投诉事项有关的当事人应当予以配合，如实提供有关资料及情况，不得拒绝、隐匿或者伪报。"},{"i":19,"n":"第十九条","txt":"投诉处理决定做出前，投诉人要求撤回投诉的，应当以书面形式提出并说明理由，由行政监督部门视以下情况，决定是否准予撤回； （一）已经查实有明显违法行为的，应当不准撤回，并继续调查直至做出处理决定； （二）撤回投诉不损害国家利益、社会公共利益或者其他当事人合法权益的，应当准予撤回，投诉处理过程终止。投诉人不得以同一事实和理由再提出投诉。"},{"i":20,"n":"第二十条","txt":"行政监督部门应当根据调查和取证情况，对投诉事项进行审查，按照下列规定做出处理决定： （一）投诉缺乏事实根据或者法律依据的，或者投诉人捏造事实、伪造材料或者以非法手段取得证明材料进行投诉的，驳回投诉； （二）投诉情况属实，招标投标活动确实存在违法行为的，依据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》及其他有关法规、规章做出处罚。"},{"i":21,"n":"第二十一条","txt":"负责受理投诉的行政监督部门应当自受理投诉之日起三十个工作日内，对投诉事项做出处理决定，并以书面形式通知投诉人、被投诉人和其他与投诉处理结果有关的当事人。需要检验、检测、鉴定、专家评审的，所需时间不计算在内。"},{"i":22,"n":"第二十二条","txt":"投诉处理决定应当包括下列主要内容： （一）投诉人和被投诉人的名称、住址； （二）投诉人的投诉事项及主张； （三）被投诉人的答辩及请求； （四）调查认定的基本事实； （五）行政监督部门的处理意见及依据。"},{"i":23,"n":"第二十三条","txt":"行政监督部门应当建立投诉处理档案，并做好保存和管理工作，接受有关方面的监督检查。"},{"i":24,"n":"第二十四条","txt":"行政监督部门在处理投诉过程中，发现被投诉人单位直接负责的主管人员和其他直接责任人员有违法、违规或者违纪行为的，应当建议其行政主管机关、纪检监察部门给予处分；情节严重构成犯罪的，移送司法机关处理。 对招标代理机构有违法行为，且情节严重的，依法暂停直至取消招标代理资格。"},{"i":25,"n":"第二十五条","txt":"当事人对行政监督部门的投诉处理决定不服或者行政监督部门逾期未做处理的，可以依法申请行政复议或者向人民法院提起行政诉讼。"},{"i":26,"n":"第二十六条","txt":"投诉人故意捏造事实、伪造证明材料或者以非法手段取得证明材料进行投诉，给他人造成损失的，依法承担赔偿责任。"},{"i":27,"n":"第二十七条","txt":"行政监督部门工作人员在处理投诉过程中徇私舞弊、滥用职权或者玩忽职守，对投诉人打击报复的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"行政监督部门在处理投诉过程中，不得向投诉人和被投诉人收取任何费用。"},{"i":29,"n":"第二十九条","txt":"对于性质恶劣、情节严重的投诉事项，行政监督部门可以将投诉处理结果在有关媒体上公布，接受舆论和公众监督。"},{"i":30,"n":"第三十条","txt":"本办法由国家发展改革委会同国务院有关部门解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2004年8月1日起施行。"}],"gongchengjianshexiangmuzhaobiaotoubiaohuodongtousufb529c":[{"i":1,"n":"第一条","txt":"为保护国家利益、社会公共利益和招标投标当事人的合法权益，建立公平、高效的工程建设项目招标投标活动投诉处理机制，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于工程建设项目招标投标活动的投诉及其处理活动。 前款所称招标投标活动，包括招标、投标、开标、评标、中标以及签订合同等各阶段。"},{"i":3,"n":"第三条","txt":"投标人或者其他利害关系人认为招标投标活动不符合法律、法规和规章规定的，有权依法向有关行政监督部门投诉。 前款所称其他利害关系人是指投标人以外的，与招标项目或者招标活动有直接和间接利益关系的法人、其他组织和自然人。"},{"i":4,"n":"第四条","txt":"各级发展改革、工业和信息化、住房城乡建设、水利、交通运输、铁道、商务、民航等招标投标活动行政监督部门，依照《国务院办公厅印发国务院有关部门实施招标投标活动行政监督的职责分工的意见的通知》(国办发[2000]34号)和地方各级人民政府规定的职责分工，受理投诉并依法做出处理决定。 对国家重大建设项目(含工业项目)招标投标活动的投诉，由国家发展改革委受理并依法做出处理决定。对国家重大建设项目招标投标活动的投诉，有关行业行政监督部门已经收到的，应当通报国家发展改革委，国家发展改革委不再受理。"},{"i":5,"n":"第五条","txt":"行政监督部门处理投诉时，应当坚持公平、公正、高效原则，维护国家利益、社会公共利益和招标投标当事人的合法权益。"},{"i":6,"n":"第六条","txt":"行政监督部门应当确定本部门内部负责受理投诉的机构及其电话、传真、电子信箱和通讯地址，并向社会公布。"},{"i":7,"n":"第七条","txt":"投诉人投诉时，应当提交投诉书。投诉书应当包括下列内容: (一)投诉人的名称、地址及有效联系方式; (二)被投诉人的名称、地址及有效联系方式; (三)投诉事项的基本事实; (四)相关请求及主张; (五)有效线索和相关证明材料。 对招标投标法实施条例规定应先提出异议的事项进行投诉的，应当附提出异议的证明文件。已向有关行政监督部门投诉的，应当一并说明。 投诉人是法人的，投诉书必须由其法定代表人或者授权代表签字并盖章;其他组织或者自然人投诉的，投诉书必须由其主要负责人或者投诉人本人签字，并附有效身份证明复印件。 投诉书有关材料是外文的，投诉人应当同时提供其中文译本。"},{"i":8,"n":"第八条","txt":"投诉人不得以投诉为名排挤竞争对手，不得进行虚假、恶意投诉，阻碍招标投标活动的正常进行。"},{"i":9,"n":"第九条","txt":"投诉人认为招标投标活动不符合法律行政法规规定的，可以在知道或者应当知道之日起十日内提出书面投诉。依照有关行政法规提出异议的，异议答复期间不计算在内。"},{"i":10,"n":"第十条","txt":"投诉人可以自己直接投诉，也可以委托代理人办理投诉事务。代理人办理投诉事务时，应将授权委托书连同投诉书一并提交给行政监督部门。授权委托书应当明确有关委托代理权限和事项。"},{"i":11,"n":"第十一条","txt":"行政监督部门收到投诉书后，应当在三个工作日内进行审查，视情况分别做出以下处理决定: (一)不符合投诉处理条件的，决定不予受理，并将不予受理的理由书面告知投诉人; (二)对符合投诉处理条件，但不属于本部门受理的投诉，书面告知投诉人向其他行政监督部门提出投诉; 对于符合投诉处理条件并决定受理的，收到投诉书之日即为正式受理。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的投诉，不予受理: (一)投诉人不是所投诉招标投标活动的参与者，或者与投诉项目无任何利害关系; (二)投诉事项不具体，且未提供有效线索，难以查证的; (三)投诉书未署具投诉人真实姓名、签字和有效联系方式的;以法人名义投诉的，投诉书未经法定代表人签字并加盖公章的; (四)超过投诉时效的; (五)已经作出处理决定，并且投诉人没有提出新的证据的; (六)投诉事项应先提出异议没有提出异议、已进入行政复议或行政诉讼程序的。"},{"i":13,"n":"第十三条","txt":"行政监督部门负责投诉处理的工作人员，有下列情形之一的，应当主动回避: (一)近亲属是被投诉人、投诉人，或者是被投诉人、投诉人的主要负责人; (二)在近三年内本人曾经在被投诉人单位担任高级管理职务; (三)与被投诉人、投诉人有其他利害关系，可能影响对投诉事项公正处理的。"},{"i":14,"n":"第十四条","txt":"行政监督部门受理投诉后，应当调取、查阅有关文件，调查、核实有关情况。 对情况复杂、涉及面广的重大投诉事项，有权受理投诉的行政监督部门可以会同其他有关的行政监督部门进行联合调查，共同研究后由受理部门做出处理决定。"},{"i":15,"n":"第十五条","txt":"行政监督部门调查取证时，应当由两名以上行政执法人员进行，并做笔录，交被调查人签字确认。"},{"i":16,"n":"第十六条","txt":"在投诉处理过程中，行政监督部门应当听取被投诉人的陈述和申辩，必要时可通知投诉人和被投诉人进行质证。"},{"i":17,"n":"第十七条","txt":"行政监督部门负责处理投诉的人员应当严格遵守保密规定，对于在投诉处理过程中所接触到的国家秘密、商业秘密应当予以保密，也不得将投诉事项透露给与投诉无关的其他单位和个人。"},{"i":18,"n":"第十八条","txt":"行政监督部门处理投诉，有权查阅、复制有关文件、资料，调查有关情况，相关单位和人员应当予以配合。必要时，行政监督部门可以责令暂停招标投标活动。 对行政监督部门依法进行的调查，投诉人、被投诉人以及评标委员会成员等与投诉事项有关的当事人应当予以配合，如实提供有关资料及情况，不得拒绝、隐匿或者伪报。"},{"i":19,"n":"第十九条","txt":"投诉处理决定做出前，投诉人要求撤回投诉的，应当以书面形式提出并说明理由，由行政监督部门视以下情况，决定是否准予撤回: (一)已经查实有明显违法行为的，应当不准撤回，并继续调查直至做出处理决定; (二)撤回投诉不损害国家利益、社会公共利益或者其他当事人合法权益的，应当准予撤回，投诉处理过程终止。投诉人不得以同一事实和理由再提出投诉。"},{"i":20,"n":"第二十条","txt":"行政监督部门应当根据调查和取证情况，对投诉事项进行审查，按照下列规定做出处理决定: (一)投诉缺乏事实根据或者法律依据的，或者投诉人捏造事实、伪造材料或者以非法手段取得证明材料进行投诉的，驳回投诉; (二)投诉情况属实，招标投标活动确实存在违法行为的，依据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》及其他有关法规、规章做出处罚。"},{"i":21,"n":"第二十一条","txt":"负责受理投诉的行政监督部门应当自受理投诉之日起三十个工作日内，对投诉事项做出处理决定，并以书面形式通知投诉人、被投诉人和其他与投诉处理结果有关的当事人。需要检验、检测、鉴定、专家评审的，所需时间不计算在内。"},{"i":22,"n":"第二十二条","txt":"投诉处理决定应当包括下列主要内容: (一)投诉人和被投诉人的名称、住址; (二)投诉人的投诉事项及主张; (三)被投诉人的答辩及请求; (四)调查认定的基本事实; (五)行政监督部门的处理意见及依据。"},{"i":23,"n":"第二十三条","txt":"行政监督部门应当建立投诉处理档案，并做好保存和管理工作，接受有关方面的监督检查。"},{"i":24,"n":"第二十四条","txt":"行政监督部门在处理投诉过程中，发现被投诉人单位直接负责的主管人员和其他直接责任人员有违法、违规或者违纪行为的，应当建议其行政主管机关、纪检监察部门给予处分;情节严重构成犯罪的，移送司法机关处理。 对招标代理机构有违法行为，且情节严重的，依法暂停直至取消招标代理资格。"},{"i":25,"n":"第二十五条","txt":"当事人对行政监督部门的投诉处理决定不服或者行政监督部门逾期未做处理的，可以依法申请行政复议或者向人民法院提起行政诉讼。"},{"i":26,"n":"第二十六条","txt":"投诉人故意捏造事实、伪造证明材料或者以非法手段取得证明材料进行投诉，给他人造成损失的，依法承担赔偿责任。"},{"i":27,"n":"第二十七条","txt":"行政监督部门工作人员在处理投诉过程中徇私舞弊、滥用职权或者玩忽职守，对投诉人打击报复的，依法给予行政处分;构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"行政监督部门在处理投诉过程中，不得向投诉人和被投诉人收取任何费用。"},{"i":29,"n":"第二十九条","txt":"对于性质恶劣、情节严重的投诉事项，行政监督部门可以将投诉处理结果在有关媒体上公布，接受舆论和公众监督。"},{"i":30,"n":"第三十条","txt":"本办法由国家发展改革委会同国务院有关部门解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2004年8月1日起施行。"}],"gongchengjianshexiangmushigongzhaobiaotoubiaobanfa-2":[{"i":1,"n":"第一条","txt":"为规范工程建设项目施工（以下简称工程施工）招标投标活动，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》和国务院有关部门的职责分工，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行工程施工招标投标活动，适用本办法。"},{"i":3,"n":"第三条","txt":"工程建设项目符合《工程建设项目招标范围和规模标准规定》（国家计委令第3号）规定的范围和标准的，必须通过招标选择施工单位。 任何单位和个人不得将依法必须进行招标的项目化整为零或者以其他任何方式规避招标。"},{"i":4,"n":"第四条","txt":"工程施工招标投标活动应当遵循公开、公平、公正和诚实信用的原则。"},{"i":5,"n":"第五条","txt":"工程施工招标投标活动，依法由招标人负责。任何单位和个人不得以任何方式非法干涉工程施工招标投标活动。 施工招标投标活动不受地区或者部门的限制。"},{"i":6,"n":"第六条","txt":"各级发展改革、工业和信息化、住房城乡建设、交通运输、铁道、水利、商务、民航等部门依照《国务院办公厅印发国务院有关部门实施招标投标活动行政监督的职责分工意见的通知》（国办发〔2000〕34号）和各地规定的职责分工，对工程施工招标投标活动实施监督，依法查处工程施工招标投标活动中的违法行为。"},{"i":7,"n":"第七条","txt":"工程施工招标人是依法提出施工招标项目、进行招标的法人或者其他组织。"},{"i":8,"n":"第八条","txt":"依法必须招标的工程建设项目，应当具备下列条件才能进行施工招标： （一）招标人已经依法成立； （二）初步设计及概算应当履行审批手续的，已经批准； （三）有相应资金或资金来源已经落实； （四）有招标所需的设计图纸及技术资料。"},{"i":9,"n":"第九条","txt":"工程施工招标分为公开招标和邀请招标。"},{"i":10,"n":"第十条","txt":"按照国家有关规定需要履行项目审批、核准手续的依法必须进行施工招标的工程建设项目，其招标范围、招标方式、招标组织形式应当报项目审批部门审批、核准。项目审批、核准部门应当及时将审批、核准确定的招标内容通报有关行政监督部门。"},{"i":11,"n":"第十一条","txt":"依法必须进行公开招标的项目，有下列情形之一的，可以邀请招标： （一）项目技术复杂或有特殊要求，或者受自然地域环境限制，只有少量潜在投标人可供选择； （二）涉及国家安全、国家秘密或者抢险救灾，适宜招标但不宜公开招标； （三）采用公开招标方式的费用占项目合同金额的比例过大 有前款第二项所列情形，属于本办法第十条规定的项目，由项目审批、核准部门在审批、核准项目时作出认定；其他项目由招标人申请有关行政监督部门作出认定。 全部使用国有资金投资或者国有资金投资占控股或者主导地位的并需要审批的工程建设项目的邀请招标，应当经项目审批部门批准，但项目审批部门只审批立项的，由有关行政监督部门审批。"},{"i":12,"n":"第十二条","txt":"依法必须进行施工招标的工程建设项目有下列情形之一的，可以不进行施工招标： （一）涉及国家安全、国家秘密、抢险救灾或者属于利用扶贫资金实行以工代赈需要使用农民工等特殊情况，不适宜进行招标； （二）施工主要技术采用不可替代的专利或者专有技术； （三）已通过招标方式选定的特许经营项目投资人依法能够自行建设； （四）采购人依法能够自行建设； （五）在建工程追加的附属小型工程或者主体加层工程，原中标人仍具备承包能力，并且其他人承担将影响施工或者功能配套要求； （六）国家规定的其他情形。"},{"i":13,"n":"第十三条","txt":"采用公开招标方式的，招标人应当发布招标公告，邀请不特定的法人或者其他组织投标。依法必须进行施工招标项目的招标公告，应当在国家指定的报刊和信息网络上发布。 采用邀请招标方式的，招标人应当向三家以上具备承担施工招标项目的能力、资信良好的特定的法人或者其他组织发出投标邀请书。"},{"i":14,"n":"第十四条","txt":"招标公告或者投标邀请书应当至少载明下列内容： （一）招标人的名称和地址； （二）招标项目的内容、规模、资金来源； （三）招标项目的实施地点和工期； （四）获取招标文件或者资格预审文件的地点和时间； （五）对招标文件或者资格预审文件收取的费用； （六）对投标人的资质等级的要求。"},{"i":15,"n":"第十五条","txt":"招标人应当按招标公告或者投标邀请书规定的时间、地点出售招标文件或资格预审文件。自招标文件或者资格预审文件出售之日起至停止出售之日止，最短不得少于五日。 招标人可以通过信息网络或者其他媒介发布招标文件，通过信息网络或者其他媒介发布的招标文件与书面招标文件具有同等法律效力，出现不一致时以书面招标文件为准，国家另有规定的除外。 对招标文件或者资格预审文件的收费应当限于补偿印刷、邮寄的成本支出，不得以营利为目的。对于所附的设计文件，招标人可以向投标人酌收押金；对于开标后投标人退还设计文件的，招标人应当向投标人退还押金。 招标文件或者资格预审文件售出后，不予退还。除不可抗力原因外，招标人在发布招标公告、发出投标邀请书后或者售出招标文件或资格预审文件后不得终止招标。"},{"i":16,"n":"第十六条","txt":"招标人可以根据招标项目本身的特点和需要，要求潜在投标人或者投标人提供满足其资格要求的文件，对潜在投标人或者投标人进行资格审查；国家对潜在投标人或者投标人的资格条件有规定的，依照其规定。"},{"i":17,"n":"第十七条","txt":"资格审查分为资格预审和资格后审。 资格预审，是指在投标前对潜在投标人进行的资格审查。 资格后审，是指在开标后对投标人进行的资格审查。 进行资格预审的，一般不再进行资格后审，但招标文件另有规定的除外。"},{"i":18,"n":"第十八条","txt":"采取资格预审的，招标人应当发布资格预审公告。资格预审公告适用本办法第十三条、第十四条有关招标公告的规定。 采取资格预审的，招标人应当在资格预审文件中载明资格预审的条件、标准和方法；采取资格后审的，招标人应当在招标文件中载明对投标人资格要求的条件、标准和方法。 招标人不得改变载明的资格条件或者以没有载明的资格条件对潜在投标人或者投标人进行资格审查。"},{"i":19,"n":"第十九条","txt":"经资格预审后，招标人应当向资格预审合格的潜在投标人发出资格预审合格通知书，告知获取招标文件的时间、地点和方法，并同时向资格预审不合格的潜在投标人告知资格预审结果。资格预审不合格的潜在投标人不得参加投标。 经资格后审不合格的投标人的投标应予否决。"},{"i":20,"n":"第二十条","txt":"资格审查应主要审查潜在投标人或者投标人是否符合下列条件： （一）具有独立订立合同的权利； （二）具有履行合同的能力，包括专业、技术资格和能力，资金、设备和其他物质设施状况，管理能力，经验、信誉和相应的从业人员； （三）没有处于被责令停业，投标资格被取消，财产被接管、冻结，破产状态； （四）在最近三年内没有骗取中标和严重违约及重大工程质量问题； （五）国家规定的其他资格条件。 资格审查时，招标人不得以不合理的条件限制、排斥潜在投标人或者投标人，不得对潜在投标人或者投标人实行歧视待遇。任何单位和个人不得以行政手段或者其他不合理方式限制投标人的数量。"},{"i":21,"n":"第二十一条","txt":"招标人符合法律规定的自行招标条件的，可以自行办理招标事宜。任何单位和个人不得强制其委托招标代理机构办理招标事宜。"},{"i":22,"n":"第二十二条","txt":"招标代理机构应当在招标人委托的范围内承担招标事宜。招标代理机构可以在其资格等级范围内承担下列招标事宜： （一）拟订招标方案，编制和出售招标文件、资格预审文件； （二）审查投标人资格； （三）编制标底； （四）组织投标人踏勘现场； （五）组织开标、评标，协助招标人定标； （六）草拟合同； （七）招标人委托的其他事项。 招标代理机构不得无权代理、越权代理，不得明知委托事项违法而进行代理。 招标代理机构不得在所代理的招标项目中投标或者代理投标，也不得为所代理的招标项目的投标人提供咨询；未经招标人同意，不得转让招标代理业务。"},{"i":23,"n":"第二十三条","txt":"工程招标代理机构与招标人应当签订书面委托合同，并按双方约定的标准收取代理费；国家对收费标准有规定的，依照其规定。"},{"i":24,"n":"第二十四条","txt":"招标人根据施工招标项目的特点和需要编制招标文件。招标文件一般包括下列内容： （一）招标公告或投标邀请书； （二）投标人须知； （三）合同主要条款； （四）投标文件格式； （五）采用工程量清单招标的，应当提供工程量清单； （六）技术条款； （七）设计图纸； （八）评标标准和方法； （九）投标辅助材料。 招标人应当在招标文件中规定实质性要求和条件，并用醒目的方式标明。"},{"i":25,"n":"第二十五条","txt":"招标人可以要求投标人在提交符合招标文件规定要求的投标文件外，提交备选投标方案，但应当在招标文件中作出说明，并提出相应的评审和比较办法。"},{"i":26,"n":"第二十六条","txt":"招标文件规定的各项技术标准应符合国家强制性标准。 招标文件中规定的各项技术标准均不得要求或标明某一特定的专利、商标、名称、设计、原产地或生产供应者，不得含有倾向或者排斥潜在投标人的其他内容。如果必须引用某一生产供应者的技术标准才能准确或清楚地说明拟招标项目的技术标准时，则应当在参照后面加上“或相当于”的字样。"},{"i":27,"n":"第二十七条","txt":"施工招标项目需要划分标段、确定工期的，招标人应当合理划分标段、确定工期，并在招标文件中载明。对工程技术上紧密相连、不可分割的单位工程不得分割标段。 招标人不得以不合理的标段或工期限制或者排斥潜在投标人或者投标人。依法必须进行施工招标的项目的招标人不得利用划分标段规避招标。"},{"i":28,"n":"第二十八条","txt":"招标文件应当明确规定所有评标因素，以及如何将这些因素量化或者据以进行评估。 在评标过程中，不得改变招标文件中规定的评标标准、方法和中标条件。"},{"i":29,"n":"第二十九条","txt":"招标文件应当规定一个适当的投标有效期，以保证招标人有足够的时间完成评标和与中标人签订合同。投标有效期从投标人提交投标文件截止之日起计算。 在原投标有效期结束前，出现特殊情况的，招标人可以书面形式要求所有投标人延长投标有效期。投标人同意延长的，不得要求或被允许修改其投标文件的实质性内容，但应当相应延长其投标保证金的有效期；投标人拒绝延长的，其投标失效，但投标人有权收回其投标保证金。因延长投标有效期造成投标人损失的，招标人应当给予补偿，但因不可抗力需要延长投标有效期的除外。"},{"i":30,"n":"第三十条","txt":"施工招标项目工期较长的，招标文件中可以规定工程造价指数体系、价格调整因素和调整方法。"},{"i":31,"n":"第三十一条","txt":"招标人应当确定投标人编制投标文件所需要的合理时间；但是，依法必须进行招标的项目，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不得少于二十日。"},{"i":32,"n":"第三十二条","txt":"招标人根据招标项目的具体情况，可以组织潜在投标人踏勘项目现场，向其介绍工程场地和相关环境的有关情况。潜在投标人依据招标人介绍情况作出的判断和决策，由投标人自行负责。 招标人不得单独或者分别组织任何一个投标人进行现场踏勘。"},{"i":33,"n":"第三十三条","txt":"对于潜在投标人在阅读招标文件和现场踏勘中提出的疑问，招标人可以书面形式或召开投标预备会的方式解答，但需同时将解答以书面方式通知所有购买招标文件的潜在投标人。该解答的内容为招标文件的组成部分。"},{"i":34,"n":"第三十四条","txt":"招标人可根据项目特点决定是否编制标底。编制标底的，标底编制过程和标底在开标前必须保密。 招标项目编制标底的，应根据批准的初步设计、投资概算，依据有关计价办法，参照有关工程定额，结合市场供求状况，综合考虑投资、工期和质量等方面的因素合理确定。 标底由招标人自行编制或委托中介机构编制。一个工程只能编制一个标底。 任何单位和个人不得强制招标人编制或报审标底，或干预其确定标底。 招标项目可以不设标底，进行无标底招标。 招标人设有最高投标限价的，应当在招标文件中明确最高投标限价或者最高投标限价的计算方法。招标人不得规定最低投标限价。"},{"i":35,"n":"第三十五条","txt":"投标人是响应招标、参加投标竞争的法人或者其他组织。招标人的任何不具独立法人资格的附属机构（单位），或者为招标项目的前期准备或者监理工作提供设计、咨询服务的任何法人及其任何附属机构（单位），都无资格参加该招标项目的投标。"},{"i":36,"n":"第三十六条","txt":"投标人应当按照招标文件的要求编制投标文件。投标文件应当对招标文件提出的实质性要求和条件作出响应。 投标文件一般包括下列内容： （一）投标函； （二）投标报价； （三）施工组织设计； （四）商务和技术偏差表。 投标人根据招标文件载明的项目实际情况，拟在中标后将中标项目的部分非主体、非关键性工作进行分包的，应当在投标文件中载明。"},{"i":37,"n":"第三十七条","txt":"招标人可以在招标文件中要求投标人提交投标保证金。投标保证金除现金外，可以是银行出具的银行保函、保兑支票、银行汇票或现金支票。 投标保证金不得超过项目估算价的百分之二，但最高不得超过八十万元人民币。投标保证金有效期应当与投标有效期一致。 投标人应当按照招标文件要求的方式和金额，将投标保证金随投标文件提交给招标人或其委托的招标代理机构。 依法必须进行施工招标的项目的境内投标单位，以现金或者支票形式提交的投标保证金应当从其基本账户转出。"},{"i":38,"n":"第三十八条","txt":"投标人应当在招标文件要求提交投标文件的截止时间前，将投标文件密封送达投标地点。招标人收到投标文件后，应当向投标人出具标明签收人和签收时间的凭证，在开标前任何单位和个人不得开启投标文件。 在招标文件要求提交投标文件的截止时间后送达的投标文件，招标人应当拒收。 依法必须进行施工招标的项目提交投标文件的投标人少于三个的，招标人在分析招标失败的原因并采取相应措施后，应当依法重新招标。重新招标后投标人仍少于三个的，属于必须审批、核准的工程建设项目，报经原审批、核准部门审批、核准后可以不再进行招标；其他工程建设项目，招标人可自行决定不再进行招标。"},{"i":39,"n":"第三十九条","txt":"投标人在招标文件要求提交投标文件的截止时间前，可以补充、修改、替代或者撤回已提交的投标文件，并书面通知招标人。补充、修改的内容为投标文件的组成部分。"},{"i":40,"n":"第四十条","txt":"在提交投标文件截止时间后到招标文件规定的投标有效期终止之前，投标人不得撤销其投标文件，否则招标人可以不退还其投标保证金。"},{"i":41,"n":"第四十一条","txt":"在开标前，招标人应妥善保管好已接收的投标文件、修改或撤回通知、备选投标方案等投标资料。"},{"i":42,"n":"第四十二条","txt":"两个以上法人或者其他组织可以组成一个联合体，以一个投标人的身份共同投标。 联合体各方签订共同投标协议后，不得再以自己名义单独投标，也不得组成新的联合体或参加其他联合体在同一项目中投标。"},{"i":43,"n":"第四十三条","txt":"招标人接受联合体投标并进行资格预审的，联合体应当在提交资格预审申请文件前组成。资格预审后联合体增减、更换成员的，其投标无效。"},{"i":44,"n":"第四十四条","txt":"联合体各方应当指定牵头人，授权其代表所有联合体成员负责投标和合同实施阶段的主办、协调工作，并应当向招标人提交由所有联合体成员法定代表人签署的授权书。"},{"i":45,"n":"第四十五条","txt":"联合体投标的，应当以联合体各方或者联合体中牵头人的名义提交投标保证金。以联合体中牵头人名义提交的投标保证金，对联合体各成员具有约束力。"},{"i":46,"n":"第四十六条","txt":"下列行为均属投标人串通投标报价： （一）投标人之间相互约定抬高或压低投标报价； （二）投标人之间相互约定，在招标项目中分别以高、中、低价位报价； （三）投标人之间先进行内部竞价，内定中标人，然后再参加投标； （四）投标人之间其他串通投标报价的行为。"},{"i":47,"n":"第四十七条","txt":"下列行为均属招标人与投标人串通投标： （一）招标人在开标前开启投标文件并将有关信息泄露给其他投标人，或者授意投标人撤换、修改投标文件； （二）招标人向投标人泄露标底、评标委员会成员等信息； （三）招标人明示或者暗示投标人压低或抬高投标报价； （四）招标人明示或者暗示投标人为特定投标人中标提供方便； （五）招标人与投标人为谋求特定中标人中标而采取的其他串通行为。"},{"i":48,"n":"第四十八条","txt":"投标人不得以他人名义投标。 前款所称以他人名义投标，指投标人挂靠其他施工单位，或从其他单位通过受让或租借的方式获取资格或资质证书，或者由其他单位及其法定代表人在自己编制的投标文件上加盖印章和签字等行为。"},{"i":49,"n":"第四十九条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行；开标地点应当为招标文件中确定的地点。 投标人对开标有异议的，应当在开标现场提出，招标人应当当场作出答复，并制作记录。"},{"i":50,"n":"第五十条","txt":"投标文件有下列情形之一的，招标人应当拒收： （一）逾期送达； （二）未按招标文件要求密封。 有下列情形之一的，评标委员会应当否决其投标： （一）投标文件未经投标单位盖章和单位负责人签字； （二）投标联合体没有提交共同投标协议； （三）投标人不符合国家或者招标文件规定的资格条件； （四）同一投标人提交两个以上不同的投标文件或者投标报价，但招标文件要求提交备选投标的除外； （五）投标报价低于成本或者高于招标文件设定的最高投标限价； （六）投标文件没有对招标文件的实质性要求和条件作出响应； （七）投标人有串通投标、弄虚作假、行贿等违法行为。"},{"i":51,"n":"第五十一条","txt":"评标委员会可以书面方式要求投标人对投标文件中含义不明确、对同类问题表述不一致或者有明显文字和计算错误的内容作必要的澄清、说明或补正。评标委员会不得向投标人提出带有暗示性或诱导性的问题，或向其明确投标文件中的遗漏和错误。"},{"i":52,"n":"第五十二条","txt":"投标文件不响应招标文件的实质性要求和条件的，评标委员会不得允许投标人通过修正或撤销其不符合要求的差异或保留，使之成为具有响应性的投标。"},{"i":53,"n":"第五十三条","txt":"评标委员会在对实质上响应招标文件要求的投标进行报价评估时，除招标文件另有约定外，应当按下述原则进行修正： （一）用数字表示的数额与用文字表示的数额不一致时，以文字数额为准； （二）单价与工程量的乘积与总价之间不一致时，以单价为准。若单价有明显的小数点错位，应以总价为准，并修改单价。 按前款规定调整后的报价经投标人确认后产生约束力。 投标文件中没有列入的价格和优惠条件在评标时不予考虑。"},{"i":54,"n":"第五十四条","txt":"对于投标人提交的优越于招标文件中技术标准的备选投标方案所产生的附加收益，不得考虑进评标价中。符合招标文件的基本技术要求且评标价最低或综合评分最高的投标人，其所提交的备选方案方可予以考虑。"},{"i":55,"n":"第五十五条","txt":"招标人设有标底的，标底在评标中应当作为参考，但不得作为评标的唯一依据。"},{"i":56,"n":"第五十六条","txt":"评标委员会完成评标后，应向招标人提出书面评标报告。评标报告由评标委员会全体成员签字。 依法必须进行招标的项目，招标人应当自收到评标报告之日起三日内公示中标候选人，公示期不得少于三日。 中标通知书由招标人发出。"},{"i":57,"n":"第五十七条","txt":"评标委员会推荐的中标候选人应当限定在一至三人，并标明排列顺序。招标人应当接受评标委员会推荐的中标候选人，不得在评标委员会推荐的中标候选人之外确定中标人。"},{"i":58,"n":"第五十八条","txt":"国有资金占控股或者主导地位的依法必须进行招标的项目，招标人应当确定排名第一的中标候选人为中标人。排名第一的中标候选人放弃中标、因不可抗力提出不能履行合同、不按照招标文件的要求提交履约保证金，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人。依次确定其他中标候选人与招标人预期差距较大，或者对招标人明显不利的，招标人可以重新招标。 招标人可以授权评标委员会直接确定中标人。 国务院对中标人的确定另有规定的，从其规定。"},{"i":59,"n":"第五十九条","txt":"招标人不得向中标人提出压低报价、增加工作量、缩短工期或其他违背中标人意愿的要求，以此作为发出中标通知书和签订合同的条件。"},{"i":60,"n":"第六十条","txt":"中标通知书对招标人和中标人具有法律效力。中标通知书发出后，招标人改变中标结果的，或者中标人放弃中标项目的，应当依法承担法律责任。"},{"i":61,"n":"第六十一条","txt":"招标人全部或者部分使用非中标单位投标文件中的技术成果或技术方案时，需征得其书面同意，并给予一定的经济补偿。"},{"i":62,"n":"第六十二条","txt":"招标人和中标人应当在投标有效期内并在自中标通知书发出之日起三十日内，按照招标文件和中标人的投标文件订立书面合同。招标人和中标人不得再行订立背离合同实质性内容的其他协议。 招标人要求中标人提供履约保证金或其他形式履约担保的，招标人应当同时向中标人提供工程款支付担保。 招标人不得擅自提高履约保证金，不得强制要求中标人垫付中标项目建设资金。"},{"i":63,"n":"第六十三条","txt":"招标人最迟应当在与中标人签订合同后五日内，向中标人和未中标的投标人退还投标保证金及银行同期存款利息。"},{"i":64,"n":"第六十四条","txt":"合同中确定的建设规模、建设标准、建设内容、合同价格应当控制在批准的初步设计及概算文件范围内；确需超出规定范围的，应当在中标合同签订前，报原项目审批部门审查同意。凡应报经审查而未报的，在初步设计及概算调整时，原项目审批部门一律不予承认。"},{"i":65,"n":"第六十五条","txt":"依法必须进行施工招标的项目，招标人应当自发出中标通知书之日起十五日内，向有关行政监督部门提交招标投标情况的书面报告。 前款所称书面报告至少应包括下列内容： （一）招标范围； （二）招标方式和发布招标公告的媒介； （三）招标文件中投标人须知、技术条款、评标标准和方法、合同主要条款等内容； （四）评标委员会的组成和评标报告； （五）中标结果。"},{"i":66,"n":"第六十六条","txt":"招标人不得直接指定分包人。"},{"i":67,"n":"第六十七条","txt":"对于不具备分包条件或者不符合分包规定的，招标人有权在签订合同或者中标人提出分包要求时予以拒绝。发现中标人转包或违法分包时，可要求其改正；拒不改正的，可终止合同，并报请有关行政监督部门查处。 监理人员和有关行政部门发现中标人违反合同约定进行转包或违法分包的，应当要求中标人改正，或者告知招标人要求其改正；对于拒不改正的，应当报请有关行政监督部门查处。"},{"i":68,"n":"第六十八条","txt":"依法必须进行招标的项目而不招标的，将必须进行招标的项目化整为零或者以其他任何方式规避招标的，有关行政监督部门责令限期改正，可以处项目合同金额千分之五以上千分之十以下的罚款；对全部或者部分使用国有资金的项目，项目审批部门可以暂停项目执行或者暂停资金拨付；对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":69,"n":"第六十九条","txt":"招标代理机构违法泄露应当保密的与招标投标活动有关的情况和资料的，或者与招标人、投标人串通损害国家利益、社会公共利益或者他人合法权益的，由有关行政监督部门处五万元以上二十五万元以下罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下罚款；有违法所得的，并处没收违法所得；情节严重的，有关行政监督部门可停止其一定时期内参与相关领域的招标代理业务，资格认定部门可暂停直至取消招标代理资格；构成犯罪的，由司法部门依法追究刑事责任。给他人造成损失的，依法承担赔偿责任。 前款所列行为影响中标结果，并且中标人为前款所列行为的受益人的，中标无效。"},{"i":70,"n":"第七十条","txt":"招标人以不合理的条件限制或者排斥潜在投标人的，对潜在投标人实行歧视待遇的，强制要求投标人组成联合体共同投标的，或者限制投标人之间竞争的，有关行政监督部门责令改正，可处一万元以上五万元以下罚款。"},{"i":71,"n":"第七十一条","txt":"依法必须进行招标项目的招标人向他人透露已获取招标文件的潜在投标人的名称、数量或者可能影响公平竞争的有关招标投标的其他情况的，或者泄露标底的，有关行政监督部门给予警告，可以并处一万元以上十万元以下的罚款；对单位直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。 前款所列行为影响中标结果的，中标无效。"},{"i":72,"n":"第七十二条","txt":"招标人在发布招标公告、发出投标邀请书或者售出招标文件或资格预审文件后终止招标的，应当及时退还所收取的资格预审文件、招标文件的费用，以及所收取的投标保证金及银行同期存款利息。给潜在投标人或者投标人造成损失的，应当赔偿损失。"},{"i":73,"n":"第七十三条","txt":"招标人有下列限制或者排斥潜在投标人行为之一的，由有关行政监督部门依照招标投标法第五十一条的规定处罚；其中，构成依法必须进行施工招标的项目的招标人规避招标的，依照招标投标法第四十九条的规定处罚： （一）依法应当公开招标的项目不按照规定在指定媒介发布资格预审公告或者招标公告； （二）在不同媒介发布的同一招标项目的资格预审公告或者招标公告的内容不一致，影响潜在投标人申请资格预审或者投标。 招标人有下列情形之一的，由有关行政监督部门责令改正，可以处10万元以下的罚款： （一）依法应当公开招标而采用邀请招标； （二）招标文件、资格预审文件的发售、澄清、修改的时限，或者确定的提交资格预审申请文件、投标文件的时限不符合招标投标法和招标投标法实施条例规定； （三）接受未通过资格预审的单位或者个人参加投标； （四）接受应当拒收的投标文件。 招标人有前款第一项、第三项、第四项所列行为之一的，对单位直接负责"},{"i":74,"n":"第七十四条","txt":"投标人相互串通投标或者与招标人串通投标的，投标人以向招标人或者评标委员会成员行贿的手段谋取中标的，中标无效，由有关行政监督部门处中标项目金额千分之五以上千分之十以下的罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下的罚款；有违法所得的，并处没收违法所得；情节严重的，取消其一至二年的投标资格，并予以公告，直至由工商行政管理机关吊销营业执照；构成犯罪的，依法追究刑事责任。给他人造成损失的，依法承担赔偿责任。投标人未中标的，对单位的罚款金额按照招标项目合同金额依照招标投标法规定的比例计算。"},{"i":75,"n":"第七十五条","txt":"投标人以他人名义投标或者以其他方式弄虚作假，骗取中标的，中标无效，给招标人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。 依法必须进行招标项目的投标人有前款所列行为尚未构成犯罪的，有关行政监督部门处中标项目金额千分之五以上千分之十以下的罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下的罚款；有违法所得的，并处没收违法所得；情节严重的，取消其一至三年投标资格，并予以公告，直至由工商行政管理机关吊销营业执照。投标人未中标的，对单位的罚款金额按照招标项目合同金额依照招标投标法规定的比例计算。"},{"i":76,"n":"第七十六条","txt":"依法必须进行招标的项目，招标人违法与投标人就投标价格、投标方案等实质性内容进行谈判的，有关行政监督部门给予警告，对单位直接负责的主管人员和其他直接责任人员依法给予处分。 前款所列行为影响中标结果的，中标无效。"},{"i":77,"n":"第七十七条","txt":"评标委员会成员收受投标人的财物或者其他好处的，没收收受的财物，可以并处三千元以上五万元以下的罚款，取消担任评标委员会成员的资格并予以公告，不得再参加依法必须进行招标的项目的评标；构成犯罪的，依法追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"评标委员会成员应当回避而不回避，擅离职守，不按照招标文件规定的评标标准和方法评标，私下接触投标人，向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求，对依法应当否决的投标不提出否决意见，暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明，或者有其他不能客观公正地履行职责行为的，有关行政监督部门责令改正；情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标；情节特别严重的，取消其担任评标委员会成员的资格。"},{"i":79,"n":"第七十九条","txt":"依法必须进行招标的项目的招标人不按照规定组建评标委员会，或者确定、更换评标委员会成员违反招标投标法和招标投标法实施条例规定的，由有关行政监督部门责令改正，可以处10万元以下的罚款，对单位直接负责的主管人员和其他直接责任人员依法给予处分；违法确定或者更换的评标委员会成员作出的评审决定无效，依法重新进行评审。"},{"i":80,"n":"第八十条","txt":"依法必须进行招标的项目的招标人有下列情形之一的，由有关行政监督部门责令改正，可以处中标项目金额千分之十以下的罚款；给他人造成损失的，依法承担赔偿责任；对单位直接负责的主管人员和其他直接责任人员依法给予处分： （一）无正当理由不发出中标通知书； （二）不按照规定确定中标人； （三）中标通知书发出后无正当理由改变中标结果； （四）无正当理由不与中标人订立合同； （五）在订立合同时向中标人提出附加条件。"},{"i":81,"n":"第八十一条","txt":"中标通知书发出后，中标人放弃中标项目的，无正当理由不与招标人签订合同的，在签订合同时向招标人提出附加条件或者更改合同实质性内容的，或者拒不提交所要求的履约保证金的，取消其中标资格，投标保证金不予退还；给招标人的损失超过投标保证金数额的，中标人应当对超过部分予以赔偿；没有提交投标保证金的，应当对招标人的损失承担赔偿责任。对依法必须进行施工招标的项目的中标人，由有关行政监督部门责令改正，可以处中标金额千分之十以下罚款。"},{"i":82,"n":"第八十二条","txt":"中标人将中标项目转让给他人的，将中标项目肢解后分别转让给他人的，违法将中标项目的部分主体、关键性工作分包给他人的，或者分包人再次分包的，转让、分包无效，有关行政监督部门处转让、分包项目金额千分之五以上千分之十以下的罚款；有违法所得的，并处没收违法所得；可以责令停业整顿；情节严重的，由工商行政管理机关吊销营业执照。"},{"i":83,"n":"第八十三条","txt":"招标人与中标人不按照招标文件和中标人的投标文件订立合同的，合同的主要条款与招标文件、中标人的投标文件的内容不一致，或者招标人、中标人订立背离合同实质性内容的协议的，有关行政监督部门责令改正；可以处中标项目金额千分之五以上千分之十以下的罚款。"},{"i":84,"n":"第八十四条","txt":"中标人不履行与招标人订立的合同的，履约保证金不予退还，给招标人造成的损失超过履约保证金数额的，还应当对超过部分予以赔偿；没有提交履约保证金的，应当对招标人的损失承担赔偿责任。 中标人不按照与招标人订立的合同履行义务，情节严重的，有关行政监督部门取消其二至五年参加招标项目的投标资格并予以公告，直至由工商行政管理机关吊销营业执照。 因不可抗力不能履行合同的，不适用前两款规定。"},{"i":85,"n":"第八十五条","txt":"招标人不履行与中标人订立的合同的，应当返还中标人的履约保证金，并承担相应的赔偿责任；没有提交履约保证金的，应当对中标人的损失承担赔偿责任。 因不可抗力不能履行合同的，不适用前款规定。"},{"i":86,"n":"第八十六条","txt":"依法必须进行施工招标的项目违反法律规定，中标无效的，应当依照法律规定的中标条件从其余投标人中重新确定中标人或者依法重新进行招标。 中标无效的，发出的中标通知书和签订的合同自始没有法律约束力，但不影响合同中独立存在的有关解决争议方法的条款的效力。"},{"i":87,"n":"第八十七条","txt":"任何单位违法限制或者排斥本地区、本系统以外的法人或者其他组织参加投标的，为招标人指定招标代理机构的，强制招标人委托招标代理机构办理招标事宜的，或者以其他方式干涉招标投标活动的，有关行政监督部门责令改正；对单位直接负责的主管人员和其他直接责任人员依法给予警告、记过、记大过的处分，情节较重 的，依法给予降级、撤职、开除的处分。 个人利用职权进行前款违法行为的，依照前款规定追究责任。"},{"i":88,"n":"第八十八条","txt":"对招标投标活动依法负有行政监督职责的国家机关工作人员徇私舞弊、滥用职权或者玩忽职守，构成犯罪的，依法追究刑事责任；不构成犯罪的，依法给予行政处分。"},{"i":89,"n":"第八十九条","txt":"投标人或者其他利害关系人认为工程建设项目施工招标投标活动不符合国家规定的，可以自知道或者应当知道之日起10日内向有关行政监督部门投诉。投诉应当有明确的请求和必要的证明材料。"},{"i":90,"n":"第九十条","txt":"使用国际组织或者外国政府贷款、援助资金的项目进行招标，贷款方、资金提供方对工程施工招标投标活动的条件和程序有不同规定的，可以适用其规定，但违背中华人民共和国社会公共利益的除外。"},{"i":91,"n":"第九十一条","txt":"本办法由国家发展改革委会同有关部门负责解释。"},{"i":92,"n":"第九十二条","txt":"本办法自2003年5月1日起施行。"}],"gongchengjianshexiangmushigongzhaobiaotoubiaobanfa":[{"i":1,"n":"第一条","txt":"为规范工程建设项目施工(以下简称工程施工)招标投标活动，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》和国务院有关部门的职责分工，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行工程施工招标投标活动，适用本办法。"},{"i":3,"n":"第三条","txt":"工程建设项目符合《工程建设项目招标范围和规模标准规定》(国家计委令第3号)规定的范围和标准的，必须通过招标选择施工单位。 任何单位和个人不得将依法必须进行招标的项目化整为零或者以其他任何方式规避招标。"},{"i":4,"n":"第四条","txt":"工程施工招标投标活动应当遵循公开、公平、公正和诚实信用的原则。"},{"i":5,"n":"第五条","txt":"工程施工招标投标活动，依法由招标人负责。任何单位和个人不得以任何方式非法干涉工程施工招标投标活动。 施工招标投标活动不受地区或者部门的限制。"},{"i":6,"n":"第六条","txt":"各级发展改革、工业和信息化、住房城乡建设、交通运输、铁道、水利、商务、民航等部门依照《国务院办公厅印发国务院有关部门实施招标投标活动行政监督的职责分工意见的通知》(国办发〔2000〕34号)和各地规定的职责分工，对工程施工招标投标活动实施监督，依法查处工程施工招标投标活动中的违法行为。"},{"i":7,"n":"第七条","txt":"工程施工招标人是依法提出施工招标项目、进行招标的法人或者其他组织。"},{"i":8,"n":"第八条","txt":"依法必须招标的工程建设项目，应当具备下列条件才能进行施工招标： (一)招标人已经依法成立; (二)初步设计及概算应当履行审批手续的，已经批准; (三)有相应资金或资金来源已经落实; (四)有招标所需的设计图纸及技术资料。"},{"i":9,"n":"第九条","txt":"工程施工招标分为公开招标和邀请招标。"},{"i":10,"n":"第十条","txt":"按照国家有关规定需要履行项目审批、核准手续的依法必须进行施工招标的工程建设项目，其招标范围、招标方式、招标组织形式应当报项目审批部门审批、核准。项目审批、核准部门应当及时将审批、核准确定的招标内容通报有关行政监督部门。"},{"i":11,"n":"第十一条","txt":"依法必须进行公开招标的项目，有下列情形之一的，可以邀请招标： (一)项目技术复杂或有特殊要求，或者受自然地域环境限制，只有少量潜在投标人可供选择; (二)涉及国家安全、国家秘密或者抢险救灾，适宜招标但不宜公开招标; (三)采用公开招标方式的费用占项目合同金额的比例过大。 有前款第二项所列情形，属于本办法第十条规定的项目，由项目审批、核准部门在审批、核准项目时作出认定;其他项目由招标人申请有关行政监督部门作出认定。 全部使用国有资金投资或者国有资金投资占控股或者主导地位的并需要审批的工程建设项目的邀请招标，应当经项目审批部门批准，但项目审批部门只审批立项的，由有关行政监督部门审批。"},{"i":12,"n":"第十二条","txt":"依法必须进行施工招标的工程建设项目有下列情形之一的，可以不进行施工招标： (一)涉及国家安全、国家秘密、抢险救灾或者属于利用扶贫资金实行以工代赈需要使用农民工等特殊情况，不适宜进行招标; (二)施工主要技术采用不可替代的专利或者专有技术; (三)已通过招标方式选定的特许经营项目投资人依法能够自行建设; (四)采购人依法能够自行建设; (五)在建工程追加的附属小型工程或者主体加层工程，原中标人仍具备承包能力，并且其他人承担将影响施工或者功能配套要求; (六)国家规定的其他情形。"},{"i":13,"n":"第十三条","txt":"采用公开招标方式的，招标人应当发布招标公告，邀请不特定的法人或者其他组织投标。依法必须进行施工招标项目的招标公告，应当在国家指定的报刊和信息网络上发布。 采用邀请招标方式的，招标人应当向三家以上具备承担施工招标项目的能力、资信良好的特定的法人或者其他组织发出投标邀请书。"},{"i":14,"n":"第十四条","txt":"招标公告或者投标邀请书应当至少载明下列内容： (一)招标人的名称和地址; (二)招标项目的内容、规模、资金来源; (三)招标项目的实施地点和工期; (四)获取招标文件或者资格预审文件的地点和时间; (五)对招标文件或者资格预审文件收取的费用; (六)对投标人的资质等级的要求。"},{"i":15,"n":"第十五条","txt":"招标人应当按招标公告或者投标邀请书规定的时间、地点出售招标文件或资格预审文件。自招标文件或者资格预审文件出售之日起至停止出售之日止，最短不得少于五日。 招标人可以通过信息网络或者其他媒介发布招标文件，通过信息网络或者其他媒介发布的招标文件与书面招标文件具有同等法律效力，出现不一致时以书面招标文件为准，国家另有规定的除外。 对招标文件或者资格预审文件的收费应当限于补偿印刷、邮寄的成本支出，不得以营利为目的。对于所附的设计文件，招标人可以向投标人酌收押金;对于开标后投标人退还设计文件的，招标人应当向投标人退还押金。 招标文件或者资格预审文件售出后，不予退还。除不可抗力原因外，招标人在发布招标公告、发出投标邀请书后或者售出招标文件或资格预审文件后不得终止招标。"},{"i":16,"n":"第十六条","txt":"招标人可以根据招标项目本身的特点和需要，要求潜在投标人或者投标人提供满足其资格要求的文件，对潜在投标人或者投标人进行资格审查;国家对潜在投标人或者投标人的资格条件有规定的，依照其规定。"},{"i":17,"n":"第十七条","txt":"资格审查分为资格预审和资格后审。 资格预审，是指在投标前对潜在投标人进行的资格审查。 资格后审，是指在开标后对投标人进行的资格审查。 进行资格预审的，一般不再进行资格后审，但招标文件另有规定的除外。"},{"i":18,"n":"第十八条","txt":"采取资格预审的，招标人应当发布资格预审公告。资格预审公告适用本办法第十三条、第十四条有关招标公告的规定。 采取资格预审的，招标人应当在资格预审文件中载明资格预审的条件、标准和方法;采取资格后审的，招标人应当在招标文件中载明对投标人资格要求的条件、标准和方法。 招标人不得改变载明的资格条件或者以没有载明的资格条件对潜在投标人或者投标人进行资格审查。"},{"i":19,"n":"第十九条","txt":"经资格预审后，招标人应当向资格预审合格的潜在投标人发出资格预审合格通知书，告知获取招标文件的时间、地点和方法，并同时向资格预审不合格的潜在投标人告知资格预审结果。资格预审不合格的潜在投标人不得参加投标。 经资格后审不合格的投标人的投标应予否决。"},{"i":20,"n":"第二十条","txt":"资格审查应主要审查潜在投标人或者投标人是否符合下列条件： (一)具有独立订立合同的权利; (二)具有履行合同的能力，包括专业、技术资格和能力，资金、设备和其他物质设施状况，管理能力，经验、信誉和相应的从业人员; (三)没有处于被责令停业，投标资格被取消，财产被接管、冻结，破产状态; (四)在最近三年内没有骗取中标和严重违约及重大工程质量问题; (五)国家规定的其他资格条件。 资格审查时，招标人不得以不合理的条件限制、排斥潜在投标人或者投标人，不得对潜在投标人或者投标人实行歧视待遇。任何单位和个人不得以行政手段或者其他不合理方式限制投标人的数量。"},{"i":21,"n":"第二十一条","txt":"招标人符合法律规定的自行招标条件的，可以自行办理招标事宜。任何单位和个人不得强制其委托招标代理机构办理招标事宜。"},{"i":22,"n":"第二十二条","txt":"招标代理机构应当在招标人委托的范围内承担招标事宜。招标代理机构可以在其资格等级范围内承担下列招标事宜： (一)拟订招标方案，编制和出售招标文件、资格预审文件; (二)审查投标人资格; (三)编制标底; (四)组织投标人踏勘现场; (五)组织开标、评标，协助招标人定标; (六)草拟合同; (七)招标人委托的其他事项。 招标代理机构不得无权代理、越权代理，不得明知委托事项违法而进行代理。 招标代理机构不得在所代理的招标项目中投标或者代理投标，也不得为所代理的招标项目的投标人提供咨询;未经招标人同意，不得转让招标代理业务。"},{"i":23,"n":"第二十三条","txt":"工程招标代理机构与招标人应当签订书面委托合同，并按双方约定的标准收取代理费;国家对收费标准有规定的，依照其规定。"},{"i":24,"n":"第二十四条","txt":"招标人根据施工招标项目的特点和需要编制招标文件。招标文件一般包括下列内容： (一)招标公告或投标邀请书; (二)投标人须知; (三)合同主要条款; (四)投标文件格式; (五)采用工程量清单招标的，应当提供工程量清单; (六)技术条款; (七)设计图纸; (八)评标标准和方法; (九)投标辅助材料。 招标人应当在招标文件中规定实质性要求和条件，并用醒目的方式标明。"},{"i":25,"n":"第二十五条","txt":"招标人可以要求投标人在提交符合招标文件规定要求的投标文件外，提交备选投标方案，但应当在招标文件中作出说明，并提出相应的评审和比较办法。"},{"i":26,"n":"第二十六条","txt":"招标文件规定的各项技术标准应符合国家强制性标准。 招标文件中规定的各项技术标准均不得要求或标明某一特定的专利、商标、名称、设计、原产地或生产供应者，不得含有倾向或者排斥潜在投标人的其他内容。如果必须引用某一生产供应者的技术标准才能准确或清楚地说明拟招标项目的技术标准时，则应当在参照后面加上“或相当于”的字样。"},{"i":27,"n":"第二十七条","txt":"施工招标项目需要划分标段、确定工期的，招标人应当合理划分标段、确定工期，并在招标文件中载明。对工程技术上紧密相联、不可分割的单位工程不得分割标段。 招标人不得以不合理的标段或工期限制或者排斥潜在投标人或者投标人。依法必须进行施工招标的项目的招标人不得利用划分标段规避招标。"},{"i":28,"n":"第二十八条","txt":"招标文件应当明确规定所有评标因素，以及如何将这些因素量化或者据以进行评估。 在评标过程中，不得改变招标文件中规定的评标标准、方法和中标条件。"},{"i":29,"n":"第二十九条","txt":"招标文件应当规定一个适当的投标有效期，以保证招标人有足够的时间完成评标和与中标人签订合同。投标有效期从投标人提交投标文件截止之日起计算。 在原投标有效期结束前，出现特殊情况的，招标人可以书面形式要求所有投标人延长投标有效期。投标人同意延长的，不得要求或被允许修改其投标文件的实质性内容，但应当相应延长其投标保证金的有效期;投标人拒绝延长的，其投标失效，但投标人有权收回其投标保证金。因延长投标有效期造成投标人损失的，招标人应当给予补偿，但因不可抗力需要延长投标有效期的除外。"},{"i":30,"n":"第三十条","txt":"施工招标项目工期较长的，招标文件中可以规定工程造价指数体系、价格调整因素和调整方法。"},{"i":31,"n":"第三十一条","txt":"招标人应当确定投标人编制投标文件所需要的合理时间;但是，依法必须进行招标的项目，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不得少于二十日。"},{"i":32,"n":"第三十二条","txt":"招标人根据招标项目的具体情况，可以组织潜在投标人踏勘项目现场，向其介绍工程场地和相关环境的有关情况。潜在投标人依据招标人介绍情况作出的判断和决策，由投标人自行负责。 招标人不得单独或者分别组织任何一个投标人进行现场踏勘。"},{"i":33,"n":"第三十三条","txt":"对于潜在投标人在阅读招标文件和现场踏勘中提出的疑问，招标人可以书面形式或召开投标预备会的方式解答，但需同时将解答以书面方式通知所有购买招标文件的潜在投标人。该解答的内容为招标文件的组成部分。"},{"i":34,"n":"第三十四条","txt":"招标人可根据项目特点决定是否编制标底。编制标底的，标底编制过程和标底在开标前必须保密。 招标项目编制标底的，应根据批准的初步设计、投资概算，依据有关计价办法，参照有关工程定额，结合市场供求状况，综合考虑投资、工期和质量等方面的因素合理确定。 标底由招标人自行编制或委托中介机构编制。一个工程只能编制一个标底。 任何单位和个人不得强制招标人编制或报审标底，或干预其确定标底。 招标项目可以不设标底，进行无标底招标。 招标人设有最高投标限价的，应当在招标文件中明确最高投标限价或者最高投标限价的计算方法。招标人不得规定最低投标限价。"},{"i":35,"n":"第三十五条","txt":"投标人是响应招标、参加投标竞争的法人或者其他组织。招标人的任何不具独立法人资格的附属机构(单位)，或者为招标项目的前期准备或者监理工作提供设计、咨询服务的任何法人及其任何附属机构(单位)，都无资格参加该招标项目的投标。"},{"i":36,"n":"第三十六条","txt":"投标人应当按照招标文件的要求编制投标文件。投标文件应当对招标文件提出的实质性要求和条件作出响应。 投标文件一般包括下列内容： (一)投标函; (二)投标报价; (三)施工组织设计; (四)商务和技术偏差表。 投标人根据招标文件载明的项目实际情况，拟在中标后将中标项目的部分非主体、非关键性工作进行分包的，应当在投标文件中载明。"},{"i":37,"n":"第三十七条","txt":"招标人可以在招标文件中要求投标人提交投标保证金。投标保证金除现金外，可以是银行出具的银行保函、保兑支票、银行汇票或现金支票。 投标保证金不得超过项目估算价的百分之二，但最高不得超过八十万元人民币。投标保证金有效期应当与投标有效期一致。 投标人应当按照招标文件要求的方式和金额，将投标保证金随投标文件提交给招标人或其委托的招标代理机构。 依法必须进行施工招标的项目的境内投标单位，以现金或者支票形式提交的投标保证金应当从其基本账户转出。"},{"i":38,"n":"第三十八条","txt":"投标人应当在招标文件要求提交投标文件的截止时间前，将投标文件密封送达投标地点。招标人收到投标文件后，应当向投标人出具标明签收人和签收时间的凭证，在开标前任何单位和个人不得开启投标文件。 在招标文件要求提交投标文件的截止时间后送达的投标文件，招标人应当拒收。 依法必须进行施工招标的项目提交投标文件的投标人少于三个的，招标人在分析招标失败的原因并采取相应措施后，应当依法重新招标。重新招标后投标人仍少于三个的，属于必须审批、核准的工程建设项目，报经原审批、核准部门批准后可以不再进行招标;其他工程建设项目，招标人可自行决定不再进行招标。"},{"i":39,"n":"第三十九条","txt":"投标人在招标文件要求提交投标文件的截止时间前，可以补充、修改、替代或者撤回已提交的投标文件，并书面通知招标人。补充、修改的内容为投标文件的组成部分。"},{"i":40,"n":"第四十条","txt":"在提交投标文件截止时间后到招标文件规定的投标有效期终止之前，投标人不得撤销其投标文件，否则招标人可以不退还其投标保证金。"},{"i":41,"n":"第四十一条","txt":"在开标前，招标人应妥善保管好已接收的投标文件、修改或撤回通知、备选投标方案等投标资料。"},{"i":42,"n":"第四十二条","txt":"两个以上法人或者其他组织可以组成一个联合体，以一个投标人的身份共同投标。 联合体各方签订共同投标协议后，不得再以自己名义单独投标，也不得组成新的联合体或参加其他联合体在同一项目中投标。"},{"i":43,"n":"第四十三条","txt":"招标人接受联合体投标并进行资格预审的，联合体应当在提交资格预审申请文件前组成。资格预审后联合体增减、更换成员的，其投标无效。"},{"i":44,"n":"第四十四条","txt":"联合体各方应当指定牵头人，授权其代表所有联合体成员负责投标和合同实施阶段的主办、协调工作，并应当向招标人提交由所有联合体成员法定代表人签署的授权书。"},{"i":45,"n":"第四十五条","txt":"联合体投标的，应当以联合体各方或者联合体中牵头人的名义提交投标保证金。以联合体中牵头人名义提交的投标保证金，对联合体各成员具有约束力。"},{"i":46,"n":"第四十六条","txt":"下列行为均属投标人串通投标报价： (一)投标人之间相互约定抬高或压低投标报价; (二)投标人之间相互约定，在招标项目中分别以高、中、低价位报价; (三)投标人之间先进行内部竞价，内定中标人，然后再参加投标; (四)投标人之间其他串通投标报价的行为。"},{"i":47,"n":"第四十七条","txt":"下列行为均属招标人与投标人串通投标： (一)招标人在开标前开启投标文件并将有关信息泄露给其他投标人，或者授意投标人撤换、修改投标文件; (二)招标人向投标人泄露标底、评标委员会成员等信息; (三)招标人明示或者暗示投标人压低或抬高投标报价; (四)招标人明示或者暗示投标人为特定投标人中标提供方便; (五)招标人与投标人为谋求特定中标人中标而采取的其他串通行为。"},{"i":48,"n":"第四十八条","txt":"投标人不得以他人名义投标。 前款所称以他人名义投标，指投标人挂靠其他施工单位，或从其他单位通过受让或租借的方式获取资格或资质证书，或者由其他单位及其法定代表人在自己编制的投标文件上加盖印章和签字等行为。"},{"i":49,"n":"第四十九条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行;开标地点应当为招标文件中确定的地点。 投标人对开标有异议的，应当在开标现场提出，招标人应当当场作出答复，并制作记录。"},{"i":50,"n":"第五十条","txt":"投标文件有下列情形之一的，招标人应当拒收： (一)逾期送达; (二)未按招标文件要求密封。 有下列情形之一的，评标委员会应当否决其投标： (一)投标文件未经投标单位盖章和单位负责人签字; (二)投标联合体没有提交共同投标协议; (三)投标人不符合国家或者招标文件规定的资格条件; (四)同一投标人提交两个以上不同的投标文件或者投标报价，但招标文件要求提交备选投标的除外; (五)投标报价低于成本或者高于招标文件设定的最高投标限价; (六)投标文件没有对招标文件的实质性要求和条件作出响应; (七)投标人有串通投标、弄虚作假、行贿等违法行为。"},{"i":51,"n":"第五十一条","txt":"评标委员会可以书面方式要求投标人对投标文件中含义不明确、对同类问题表述不一致或者有明显文字和计算错误的内容作必要的澄清、说明或补正。评标委员会不得向投标人提出带有暗示性或诱导性的问题，或向其明确投标文件中的遗漏和错误。"},{"i":52,"n":"第五十二条","txt":"投标文件不响应招标文件的实质性要求和条件的，评标委员会不得允许投标人通过修正或撤销其不符合要求的差异或保留，使之成为具有响应性的投标。"},{"i":53,"n":"第五十三条","txt":"评标委员会在对实质上响应招标文件要求的投标进行报价评估时，除招标文件另有约定外，应当按下述原则进行修正： (一)用数字表示的数额与用文字表示的数额不一致时，以文字数额为准; (二)单价与工程量的乘积与总价之间不一致时，以单价为准。若单价有明显的小数点错位，应以总价为准，并修改单价。 按前款规定调整后的报价经投标人确认后产生约束力。 投标文件中没有列入的价格和优惠条件在评标时不予考虑。"},{"i":54,"n":"第五十四条","txt":"对于投标人提交的优越于招标文件中技术标准的备选投标方案所产生的附加收益，不得考虑进评标价中。符合招标文件的基本技术要求且评标价最低或综合评分最高的投标人，其所提交的备选方案方可予以考虑。"},{"i":55,"n":"第五十五条","txt":"招标人设有标底的，标底在评标中应当作为参考，但不得作为评标的唯一依据。"},{"i":56,"n":"第五十六条","txt":"评标委员会完成评标后，应向招标人提出书面评标报告。评标报告由评标委员会全体成员签字。 依法必须进行招标的项目，招标人应当自收到评标报告之日起三日内公示中标候选人，公示期不得少于三日。 中标通知书由招标人发出。"},{"i":57,"n":"第五十七条","txt":"评标委员会推荐的中标候选人应当限定在一至三人，并标明排列顺序。招标人应当接受评标委员会推荐的中标候选人，不得在评标委员会推荐的中标候选人之外确定中标人。"},{"i":58,"n":"第五十八条","txt":"国有资金占控股或者主导地位的依法必须进行招标的项目，招标人应当确定排名第一的中标候选人为中标人。排名第一的中标候选人放弃中标、因不可抗力提出不能履行合同、不按照招标文件的要求提交履约保证金，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人。依次确定其他中标候选人与招标人预期差距较大，或者对招标人明显不利的，招标人可以重新招标。 招标人可以授权评标委员会直接确定中标人。 国务院对中标人的确定另有规定的，从其规定。"},{"i":59,"n":"第五十九条","txt":"招标人不得向中标人提出压低报价、增加工作量、缩短工期或其他违背中标人意愿的要求，以此作为发出中标通知书和签订合同的条件。"},{"i":60,"n":"第六十条","txt":"中标通知书对招标人和中标人具有法律效力。中标通知书发出后，招标人改变中标结果的，或者中标人放弃中标项目的，应当依法承担法律责任。"},{"i":61,"n":"第六十一条","txt":"招标人全部或者部分使用非中标单位投标文件中的技术成果或技术方案时，需征得其书面同意，并给予一定的经济补偿。"},{"i":62,"n":"第六十二条","txt":"招标人和中标人应当在投标有效期内并在自中标通知书发出之日起三十日内，按照招标文件和中标人的投标文件订立书面合同。招标人和中标人不得再行订立背离合同实质性内容的其他协议。 招标人要求中标人提供履约保证金或其他形式履约担保的，招标人应当同时向中标人提供工程款支付担保。 招标人不得擅自提高履约保证金，不得强制要求中标人垫付中标项目建设资金。"},{"i":63,"n":"第六十三条","txt":"招标人最迟应当在与中标人签订合同后五日内，向中标人和未中标的投标人退还投标保证金及银行同期存款利息。"},{"i":64,"n":"第六十四条","txt":"合同中确定的建设规模、建设标准、建设内容、合同价格应当控制在批准的初步设计及概算文件范围内;确需超出规定范围的，应当在中标合同签订前，报原项目审批部门审查同意。凡应报经审查而未报的，在初步设计及概算调整时，原项目审批部门一律不予承认。"},{"i":65,"n":"第六十五条","txt":"依法必须进行施工招标的项目，招标人应当自发出中标通知书之日起十五日内，向有关行政监督部门提交招标投标情况的书面报告。 前款所称书面报告至少应包括下列内容： (一)招标范围; (二)招标方式和发布招标公告的媒介; (三)招标文件中投标人须知、技术条款、评标标准和方法、合同主要条款等内容; (四)评标委员会的组成和评标报告; (五)中标结果。"},{"i":66,"n":"第六十六条","txt":"招标人不得直接指定分包人。"},{"i":67,"n":"第六十七条","txt":"对于不具备分包条件或者不符合分包规定的，招标人有权在签订合同或者中标人提出分包要求时予以拒绝。发现中标人转包或违法分包时，可要求其改正;拒不改正的，可终止合同，并报请有关行政监督部门查处。 监理人员和有关行政部门发现中标人违反合同约定进行转包或违法分包的，应当要求中标人改正，或者告知招标人要求其改正;对于拒不改正的，应当报请有关行政监督部门查处。"},{"i":68,"n":"第六十八条","txt":"依法必须进行招标的项目而不招标的，将必须进行招标的项目化整为零或者以其他任何方式规避招标的，有关行政监督部门责令限期改正，可以处项目合同金额千分之五以上千分之十以下的罚款;对全部或者部分使用国有资金的项目，项目审批部门可以暂停项目执行或者暂停资金拨付;对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":69,"n":"第六十九条","txt":"招标代理机构违法泄露应当保密的与招标投标活动有关的情况和资料的，或者与招标人、投标人串通损害国家利益、社会公共利益或者他人合法权益的，由有关行政监督部门处五万元以上二十五万元以下罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下罚款;有违法所得的，并处没收违法所得;情节严重的，有关行政监督部门可停止其一定时期内参与相关领域的招标代理业务，资格认定部门可暂停直至取消招标代理资格;构成犯罪的，由司法部门依法追究刑事责任。给他人造成损失的，依法承担赔偿责任。 前款所列行为影响中标结果，并且中标人为前款所列行为的受益人的，中标无效。"},{"i":70,"n":"第七十条","txt":"招标人以不合理的条件限制或者排斥潜在投标人的，对潜在投标人实行歧视待遇的，强制要求投标人组成联合体共同投标的，或者限制投标人之间竞争的，有关行政监督部门责令改正，可处一万元以上五万元以下罚款。"},{"i":71,"n":"第七十一条","txt":"依法必须进行招标项目的招标人向他人透露已获取招标文件的潜在投标人的名称、数量或者可能影响公平竞争的有关招标投标的其他情况的，或者泄露标底的，有关行政监督部门给予警告，可以并处一万元以上十万元以下的罚款;对单位直接负责的主管人员和其他直接责任人员依法给予处分;构成犯罪的，依法追究刑事责任。 前款所列行为影响中标结果的，中标无效。"},{"i":72,"n":"第七十二条","txt":"招标人在发布招标公告、发出投标邀请书或者售出招标文件或资格预审文件后终止招标的，应当及时退还所收取的资格预审文件、招标文件的费用，以及所收取的投标保证金及银行同期存款利息。给潜在投标人或者投标人造成损失的，应当赔偿损失。"},{"i":73,"n":"第七十三条","txt":"招标人有下列限制或者排斥潜在投标人行为之一的，由有关行政监督部门依照招标投标法第五十一条的规定处罚;其中，构成依法必须进行施工招标的项目的招标人规避招标的，依照招标投标法第四十九条的规定处罚： (一)依法应当公开招标的项目不按照规定在指定媒介发布资格预审公告或者招标公告; (二)在不同媒介发布的同一招标项目的资格预审公告或者招标公告的内容不一致，影响潜在投标人申请资格预审或者投标。 招标人有下列情形之一的，由有关行政监督部门责令改正，可以处10万元以下的罚款： (一)依法应当公开招标而采用邀请招标; (二)招标文件、资格预审文件的发售、澄清、修改的时限，或者确定的提交资格预审申请文件、投标文件的时限不符合招标投标法和招标投标法实施条例规定; (三)接受未通过资格预审的单位或者个人参加投标; (四)接受应当拒收的投标文件。 招标人有前款第一项、第三项、第四项所列行为之一的，对单位直接负责"},{"i":74,"n":"第七十四条","txt":"投标人相互串通投标或者与招标人串通投标的，投标人以向招标人或者评标委员会成员行贿的手段谋取中标的，中标无效，由有关行政监督部门处中标项目金额千分之五以上千分之十以下的罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下的罚款;有违法所得的，并处没收违法所得;情节严重的，取消其一至二年的投标资格，并予以公告，直至由工商行政管理机关吊销营业执照;构成犯罪的，依法追究刑事责任。给他人造成损失的，依法承担赔偿责任。投标人未中标的，对单位的罚款金额按照招标项目合同金额依照招标投标法规定的比例计算。"},{"i":75,"n":"第七十五条","txt":"投标人以他人名义投标或者以其他方式弄虚作假，骗取中标的，中标无效，给招标人造成损失的，依法承担赔偿责任;构成犯罪的，依法追究刑事责任。 依法必须进行招标项目的投标人有前款所列行为尚未构成犯罪的，有关行政监督部门处中标项目金额千分之五以上千分之十以下的罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下的罚款;有违法所得的，并处没收违法所得;情节严重的，取消其一至三年投标资格，并予以公告，直至由工商行政管理机关吊销营业执照。投标人未中标的，对单位的罚款金额按照招标项目合同金额依照招标投标法规定的比例计算。"},{"i":76,"n":"第七十六条","txt":"依法必须进行招标的项目，招标人违法与投标人就投标价格、投标方案等实质性内容进行谈判的，有关行政监督部门给予警告，对单位直接负责的主管人员和其他直接责任人员依法给予处分。 前款所列行为影响中标结果的，中标无效。"},{"i":77,"n":"第七十七条","txt":"评标委员会成员收受投标人的财物或者其他好处的，没收收受的财物，可以并处三千元以上五万元以下的罚款，取消担任评标委员会成员的资格并予以公告，不得再参加依法必须进行招标的项目的评标;构成犯罪的，依法追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"评标委员会成员应当回避而不回避，擅离职守，不按照招标文件规定的评标标准和方法评标，私下接触投标人，向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求，对依法应当否决的投标不提出否决意见，暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明，或者有其他不能客观公正地履行职责行为的，有关行政监督部门责令改正;情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标;情节特别严重的，取消其担任评标委员会成员的资格。"},{"i":79,"n":"第七十九条","txt":"依法必须进行招标的项目的招标人不按照规定组建评标委员会，或者确定、更换评标委员会成员违反招标投标法和招标投标法实施条例规定的，由有关行政监督部门责令改正，可以处10万元以下的罚款，对单位直接负责的主管人员和其他直接责任人员依法给予处分;违法确定或者更换的评标委员会成员作出的评审决定无效，依法重新进行评审。"},{"i":80,"n":"第八十条","txt":"依法必须进行招标的项目的招标人有下列情形之一的，由有关行政监督部门责令改正，可以处中标项目金额千分之十以下的罚款;给他人造成损失的，依法承担赔偿责任;对单位直接负责的主管人员和其他直接责任人员依法给予处分： (一)无正当理由不发出中标通知书; (二)不按照规定确定中标人; (三)中标通知书发出后无正当理由改变中标结果; (四)无正当理由不与中标人订立合同; (五)在订立合同时向中标人提出附加条件。"},{"i":81,"n":"第八十一条","txt":"中标通知书发出后，中标人放弃中标项目的，无正当理由不与招标人签订合同的，在签订合同时向招标人提出附加条件或者更改合同实质性内容的，或者拒不提交所要求的履约保证金的，取消其中标资格，投标保证金不予退还;给招标人的损失超过投标保证金数额的，中标人应当对超过部分予以赔偿;没有提交投标保证金的，应当对招标人的损失承担赔偿责任。对依法必须进行施工招标的项目的中标人，由有关行政监督部门责令改正，可以处中标金额千分之十以下罚款。"},{"i":82,"n":"第八十二条","txt":"中标人将中标项目转让给他人的，将中标项目肢解后分别转让给他人的，违法将中标项目的部分主体、关键性工作分包给他人的，或者分包人再次分包的，转让、分包无效，有关行政监督部门处转让、分包项目金额千分之五以上千分之十以下的罚款;有违法所得的，并处没收违法所得;可以责令停业整顿;情节严重的，由工商行政管理机关吊销营业执照。"},{"i":83,"n":"第八十三条","txt":"招标人与中标人不按照招标文件和中标人的投标文件订立合同的，合同的主要条款与招标文件、中标人的投标文件的内容不一致，或者招标人、中标人订立背离合同实质性内容的协议的，有关行政监督部门责令改正;可以处中标项目金额千分之五以上千分之十以下的罚款。"},{"i":84,"n":"第八十四条","txt":"中标人不履行与招标人订立的合同的，履约保证金不予退还，给招标人造成的损失超过履约保证金数额的，还应当对超过部分予以赔偿;没有提交履约保证金的，应当对招标人的损失承担赔偿责任。 中标人不按照与招标人订立的合同履行义务，情节严重的，有关行政监督部门取消其二至五年参加招标项目的投标资格并予以公告，直至由工商行政管理机关吊销营业执照。 因不可抗力不能履行合同的，不适用前两款规定。"},{"i":85,"n":"第八十五条","txt":"招标人不履行与中标人订立的合同的，应当返还中标人的履约保证金，并承担相应的赔偿责任;没有提交履约保证金的，应当对中标人的损失承担赔偿责任。 因不可抗力不能履行合同的，不适用前款规定。"},{"i":86,"n":"第八十六条","txt":"依法必须进行施工招标的项目违反法律规定，中标无效的，应当依照法律规定的中标条件从其余投标人中重新确定中标人或者依法重新进行招标。 中标无效的，发出的中标通知书和签订的合同自始没有法律约束力，但不影响合同中独立存在的有关解决争议方法的条款的效力。"},{"i":87,"n":"第八十七条","txt":"任何单位违法限制或者排斥本地区、本系统以外的法人或者其他组织参加投标的，为招标人指定招标代理机构的，强制招标人委托招标代理机构办理招标事宜的，或者以其他方式干涉招标投标活动的，有关行政监督部门责令改正;对单位直接负责的主管人员和其他直接责任人员依法给予警告、记过、记大过的处分，情节较重的，依法给予降级、撤职、开除的处分。 个人利用职权进行前款违法行为的，依照前款规定追究责任。"},{"i":88,"n":"第八十八条","txt":"对招标投标活动依法负有行政监督职责的国家机关工作人员徇私舞弊、滥用职权或者玩忽职守，构成犯罪的，依法追究刑事责任;不构成犯罪的，依法给予行政处分。"},{"i":89,"n":"第八十九条","txt":"投标人或者其他利害关系人认为工程建设项目施工招标投标活动不符合国家规定的，可以自知道或者应当知道之日起10日内向有关行政监督部门投诉。投诉应当有明确的请求和必要的证明材料。"},{"i":90,"n":"第九十条","txt":"使用国际组织或者外国政府贷款、援助资金的项目进行招标，贷款方、资金提供方对工程施工招标投标活动的条件和程序有不同规定的，可以适用其规定，但违背中华人民共和国社会公共利益的除外。"},{"i":91,"n":"第九十一条","txt":"本办法由国家发展改革委会同有关部门负责解释。"},{"i":92,"n":"第九十二条","txt":"本办法自2003年5月1日起施行。"}],"gongchengjianshexiangmushenbaocailiaozengjiazhaobi0c39f9":[{"i":1,"n":"第一条","txt":"为了规范工程建设项目的招标活动，依据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于《工程建设项目招标范围和规模标准规定》(国家发展计划委员会令第3号)中规定的依法必须进行招标且按照国家有关规定需要履行项目审批、核准手续的各类工程建设项目。"},{"i":3,"n":"第三条","txt":"本规定第二条包括的工程建设项目，必须在报送的项目可行性研究报告或者资金申请报告、项目申请报告中增加有关招标的内容。"},{"i":4,"n":"第四条","txt":"增加的招标内容包括： (一)建设项目的勘察、设计、施工、监理以及重要设备、材料等采购活动的具体招标范围(全部或者部分招标); (二)建设项目的勘察、设计、施工、监理以及重要设备、材料等采购活动拟采用的招标组织形式(委托招标或者自行招标);拟自行招标的，还应按照《工程建设项目自行招标试行办法》(国家发展计划委员会令第5号)规定报送书面材料; (三)建设项目的勘察、设计、施工、监理以及重要设备、材料等采购活动拟采用的招标方式(公开招标或者邀请招标);国家发展改革委确定的国家重点项目和省、自治区、直辖市人民政府确定的地方重点项目，拟采用邀请招标的，应对采用邀请招标的理由作出说明; (四)其他有关内容。 报送招标内容时应附招标基本情况表(表式见附表一)。"},{"i":5,"n":"第五条","txt":"属于下列情况之一的，建设项目可以不进行招标。但在报送可行性研究报告或者资金申请报告、项目申请报告中须提出不招标申请，并说明不招标原因： (一)涉及国家安全、国家秘密、抢险救灾或者属于利用扶贫资金实行以工代赈、需要使用农民工等特殊情况，不适宜进行招标; (二)建设项目的勘察、设计，采用不可替代的专利或者专有技术，或者其建筑艺术造型有特殊要求; (三)承包商、供应商或者服务提供者少于三家，不能形成有效竞争; (四)采购人依法能够自行建设、生产或者提供; (五)已通过招标方式选定的特许经营项目投资人依法能够自行建设、生产或者提供; (六)需要向原中标人采购工程、货物或者服务，否则将影响施工或者配套要求; (七)国家规定的其他特殊情形。"},{"i":6,"n":"第六条","txt":"经项目审批、核准部门审批、核准，工程建设项目因特殊情况可以在报送可行性研究报告或者资金申请报告、项目申请报告前先行开展招标活动，但应在报送的可行性研究报告或者资金申请报告、项目申请报告中予以说明。项目审批、核准部门认定先行开展的招标活动中有违背法律、法规的情形的，应要求其纠正。"},{"i":7,"n":"第七条","txt":"在项目可行性研究报告或者资金申请报告、项目申请报告中增加的招标内容，作为附件与可行性研究报告或者资金申请报告、项目申请报告一同报送。"},{"i":8,"n":"第八条","txt":"项目审批、核准部门应依据法律、法规规定的权限，对项目建设单位拟定的招标范围、招标组织形式、招标方式等内容提出是否予以审批、核准的意见。项目审批、核准部门对招标事项审批、核准意见格式见附表二。"},{"i":9,"n":"第九条","txt":"审批、核准招标事项，按以下分工办理： (一)应报送国家发展改革委审批和国家发展改革委核报国务院审批的建设项目，由国家发展改革委审批; (二)应报送国务院行业主管部门审批的建设项目，由国务院行业主管部门审批; (三)应报送地方人民政府发展改革部门审批和地方人民政府发展改革部门核报地方人民政府审批的建设项目，由地方人民政府发展改革部门审批; (四)按照规定应报送国家发展改革委核准的建设项目，由国家发展改革委核准; (五)按照规定应报送地方人民政府发展改革部门核准的建设项目，由地方人民政府发展改革部门核准。"},{"i":10,"n":"第十条","txt":"使用国际金融组织或者外国政府资金的建设项目，资金提供方对建设项目报送招标内容有规定的，从其规定。"},{"i":11,"n":"第十一条","txt":"项目建设单位在招标活动中对审批、核准的招标范围、招标组织形式、招标方式等作出改变的，应向原审批部门重新办理有关审批、核准手续。"},{"i":12,"n":"第十二条","txt":"项目审批、核准部门应将审批、核准建设项目招标内容的意见抄送有关行政监督部门。"},{"i":13,"n":"第十三条","txt":"项目建设单位在报送招标内容中弄虚作假，或者在招标活动中违背项目审批、核准部门核准事项，由项目审批、核准部门和有关行政监督部门依法处罚。"},{"i":14,"n":"第十四条","txt":"本规定由国家发展改革委解释。"},{"i":15,"n":"第十五条","txt":"本规定自发布之日起施行。 附表一 招标基本情况表 附表二 审批部门核准意见"}],"gongchengjianshexiangmuzixingzhaobiaoshixingbanfa":[{"i":1,"n":"第一条","txt":"为了规范工程建设项目招标人自行招标行为，加强对招标投标活动的监督，根据《中华人民共和国招标投标法》(以下简称招标投标法)、《中华人民共和国招标投标法实施条例》(以下简称招标投标法实施条例)和《国务院办公厅印发国务院有关部门实施招标投标活动行政监督的职责分工意见的通知》(国办发〔2000〕34号)，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于经国家发展改革委审批、核准(含经国家发展改革委初审后报国务院审批)依法必须进行招标的工程建设项目的自行招标活动。 前款工程建设项目的招标范围和规模标准，适用《工程建设项目招标范围和规模标准规定》(国家计委第3号令)。"},{"i":3,"n":"第三条","txt":"招标人是指依照法律规定进行工程建设项目的勘察、设计、施工、监理以及与工程建设有关的重要设备、材料等招标的法人。"},{"i":4,"n":"第四条","txt":"招标人自行办理招标事宜，应当具有编制招标文件和组织评标的能力，具体包括： (一)具有项目法人资格(或者法人资格); (二)具有与招标项目规模和复杂程度相适应的工程技术、概预算、财务和工程管理等方面专业技术力量; (三)有从事同类工程建设项目招标的经验; (四)拥有3名以上取得招标职业资格的专职招标业务人员; (五)熟悉和掌握招标投标法及有关法规规章。"},{"i":5,"n":"第五条","txt":"招标人自行招标的，项目法人或者组建中的项目法人应当在向国家发展改革委上报项目可行性研究报告或者资金申请报告、项目申请报告时，一并报送符合本办法第四条规定的书面材料。 书面材料应当至少包括： (一)项目法人营业执照、法人证书或者项目法人组建文件; (二)与招标项目相适应的专业技术力量情况; (三)取得招标职业资格的专职招标业务人员的基本情况; (四)拟使用的专家库情况; (五)以往编制的同类工程建设项目招标文件和评标报告，以及招标业绩的证明材料; (六)其他材料。 在报送可行性研究报告或者资金申请报告、项目申请报告前，招标人确需通过招标方式或者其他方式确定勘察、设计单位开展前期工作的，应当在前款规定的书面材料中说明。"},{"i":6,"n":"第六条","txt":"国家发展改革委审查招标人报送的书面材料，核准招标人符合本办法规定的自行招标条件的，招标人可以自行办理招标事宜。任何单位和个人不得限制其自行办理招标事宜，也不得拒绝办理工程建设有关手续。"},{"i":7,"n":"第七条","txt":"国家发展改革委审查招标人报送的书面材料，认定招标人不符合本办法规定的自行招标条件的，在批复、核准可行性研究报告或者资金申请报告、项目申请报告时，要求招标人委托招标代理机构办理招标事宜。"},{"i":8,"n":"第八条","txt":"一次核准手续仅适用于一个工程建设项目。"},{"i":9,"n":"第九条","txt":"招标人不具备自行招标条件，不影响国家发展改革委对项目的审批或者核准。"},{"i":10,"n":"第十条","txt":"招标人自行招标的，应当自确定中标人之日起十五日内，向国家发展改革委提交招标投标情况的书面报告。书面报告至少应包括下列内容： (一)招标方式和发布资格预审公告、招标公告的媒介; (二)招标文件中投标人须知、技术规格、评标标准和方法、合同主要条款等内容; (三)评标委员会的组成和评标报告; (四)中标结果。"},{"i":11,"n":"第十一条","txt":"招标人不按本办法规定要求履行自行招标核准手续的或者报送的书面材料有遗漏的，国家发展改革委要求其补正;不及时补正的，视同不具备自行招标条件。 招标人履行核准手续中有弄虚作假情况的，视同不具备自行招标条件。"},{"i":12,"n":"第十二条","txt":"招标人不按本办法提交招标投标情况的书面报告的，国家发展改革委要求补正;拒不补正的，给予警告，并视招标人是否有招标投标法第五章以及招标投标法实施条例第六章规定的违法行为，给予相应的处罚。"},{"i":13,"n":"第十三条","txt":"任何单位和个人非法强制招标人委托招标代理机构或者其他组织办理招标事宜的，非法拒绝办理工程建设有关手续的，或者以其他任何方式非法干预招标人自行招标活动的，由国家发展改革委依据招标投标法以及招标投标法实施条例的有关规定处罚或者向有关行政监督部门提出处理建议。"},{"i":14,"n":"第十四条","txt":"本办法自发布之日起施行。"}],"gongchengjianshexiangmuhuowuzhaobiaotoubiaobanfa-2":[{"i":1,"n":"第一条","txt":"为规范工程建设项目的货物招标投标活动，保护国家利益、社会公共利益和招标投标活动当事人的合法权益，保证工程质量，提高投资效益，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》和国务院有关部门的职责分工，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内工程建设项目货物招标投标活动。"},{"i":3,"n":"第三条","txt":"工程建设项目符合《工程建设项目招标范围和规模标准规定》（原国家计委令第3号）规定的范围和标准的，必须通过招标选择货物供应单位。 任何单位和个人不得将依法必须进行招标的项目化整为零或者以其他任何方式规避招标。"},{"i":4,"n":"第四条","txt":"工程建设项目货物招标投标活动应当遵循公开、公平、公正和诚实信用的原则。货物招标投标活动不受地区或者部门的限制。"},{"i":5,"n":"第五条","txt":"工程建设项目货物招标投标活动，依法由招标人负责。 工程建设项目招标人对项目实行总承包招标时，未包括在总承包范围内的货物属于依法必须进行招标的项目范围且达到国家规定规模标准的，应当由工程建设项目招标人依法组织招标。 工程建设项目实行总承包招标时，以暂估价形式包括在总承包范围内的货物属于依法必须进行招标的项目范围且达到国家规定规模标准的，应当依法组织招标。"},{"i":6,"n":"第六条","txt":"各级发展改革、工业和信息化、住房城乡建设、交通运输、铁道、水利、民航等部门依照国务院和地方各级人民政府关于工程建设项目行政监督的职责分工，对工程建设项目中所包括的货物招标投标活动实施监督，依法查处货物招标投标活动中的违法行为。"},{"i":7,"n":"第七条","txt":"工程建设项目招标人是依法提出招标项目、进行招标的法人或者其他组织。本办法第五条总承包中标人单独或者共同招标时，也为招标人。"},{"i":8,"n":"第八条","txt":"依法必须招标的工程建设项目，应当具备下列条件才能进行货物招标： （一）招标人已经依法成立； （二）按照国家有关规定应当履行项目审批、核准或者备案手续的，已经审批、核准或者备案； （三）有相应资金或者资金来源已经落实； （四）能够提出货物的使用与技术要求。"},{"i":9,"n":"第九条","txt":"依法必须进行招标的工程建设项目，按国家有关规定需要履行审批、核准手续的，招标人应当在报送的可行性研究报告、资金申请报告或者项目申请报告中将货物招标范围、招标方式（公开招标或邀请招标）、招标组织形式（自行招标或委托招标）等有关招标内容报项目审批、核准部门审批、核准。项目审批、核准部门应当将审批、核准的招标内容通报有关行政监督部门。"},{"i":10,"n":"第十条","txt":"货物招标分为公开招标和邀请招标。"},{"i":11,"n":"第十一条","txt":"依法应当公开招标的项目，有下列情形之一的，可以邀请招标： （一）技术复杂、有特殊要求或者受自然环境限制，只有少量潜在投标人可供选择； （二）采用公开招标方式的费用占项目合同金额的比例过大； （三）涉及国家安全、国家秘密或者抢险救灾，适宜招标但不宜公开招标。 有前款第二项所列情形，属于按照国家有关规定需要履行项目审批、核准手续的依法必须进行招标的项目，由项目审批、核准部门认定；其他项目由招标人申请有关行政监督部门作出认定。"},{"i":12,"n":"第十二条","txt":"采用公开招标方式的，招标人应当发布资格预审公告或者招标公告。依法必须进行货物招标的资格预审公告或者招标公告，应当在国家指定的报刊或者信息网络上发布。 采用邀请招标方式的，招标人应当向三家以上具备货物供应的能力、资信良好的特定的法人或者其他组织发出投标邀请书。"},{"i":13,"n":"第十三条","txt":"招标公告或者投标邀请书应当载明下列内容： （一）招标人的名称和地址； （二）招标货物的名称、数量、技术规格、资金来源； （三）交货的地点和时间； （四）获取招标文件或者资格预审文件的地点和时间； （五）对招标文件或者资格预审文件收取的费用； （六）提交资格预审申请书或者投标文件的地点和截止日期； （七）对投标人的资格要求。"},{"i":14,"n":"第十四条","txt":"招标人应当按照资格预审公告、招标公告或者投标邀请书规定的时间、地点发售招标文件或者资格预审文件。自招标文件或者资格预审文件发售之日起至停止发售之日止，最短不得少于五日。 招标人可以通过信息网络或者其他媒介发布招标文件，通过信息网络或者其他媒介发布的招标文件与书面招标文件具有同等法律效力，出现不一致时以书面招标文件为准，但国家另有规定的除外。 对招标文件或者资格预审文件的收费应当限于补偿印刷、邮寄的成本支出，不得以营利为目的。 除不可抗力原因外，招标文件或者资格预审文件发出后，不予退还；招标人在发布招标公告、发出投标邀请书后或者发出招标文件或资格预审文件后不得终止招标。招标人终止招标的，应当及时发布公告，或者以书面形式通知被邀请的或者已经获取资格预审文件、招标文件的潜在投标人。已经发售资格预审文件、招标文件或者已经收取投标保证金的，招标人应当及时退还所收取的资格预审文件、招标文件的费用，"},{"i":15,"n":"第十五条","txt":"招标人可以根据招标货物的特点和需要，对潜在投标人或者投标人进行资格审查；国家对潜在投标人或者投标人的资格条件有规定的，依照其规定。"},{"i":16,"n":"第十六条","txt":"资格审查分为资格预审和资格后审。 资格预审，是指招标人出售招标文件或者发出投标邀请书前对潜在投标人进行的资格审查。资格预审一般适用于潜在投标人较多或者大型、技术复杂货物的招标。 资格后审，是指在开标后对投标人进行的资格审查。资格后审一般在评标过程中的初步评审开始时进行。"},{"i":17,"n":"第十七条","txt":"采取资格预审的，招标人应当发布资格预审公告。资格预审公告适用本办法第十二条、第十三条有关招标公告的规定。"},{"i":18,"n":"第十八条","txt":"资格预审文件一般包括下列内容： （一）资格预审公告； （二）申请人须知； （三）资格要求； （四）其他业绩要求； （五）资格审查标准和方法； （六）资格预审结果的通知方式。"},{"i":19,"n":"第十九条","txt":"采取资格预审的，招标人应当在资格预审文件中详细规定资格审查的标准和方法；采取资格后审的，招标人应当在招标文件中详细规定资格审查的标准和方法。 招标人在进行资格审查时，不得改变或补充载明的资格审查标准和方法或者以没有载明的资格审查标准和方法对潜在投标人或者投标人进行资格审查。"},{"i":20,"n":"第二十条","txt":"经资格预审后，招标人应当向资格预审合格的潜在投标人发出资格预审合格通知书，告知获取招标文件的时间、地点和方法，并同时向资格预审不合格的潜在投标人告知资格预审结果。依法必须招标的项目通过资格预审的申请人不足三个的，招标人在分析招标失败的原因并采取相应措施后，应当重新招标。 对资格后审不合格的投标人，评标委员会应当否决其投标。"},{"i":21,"n":"第二十一条","txt":"招标文件一般包括下列内容： （一）招标公告或者投标邀请书； （二）投标人须知； （三）投标文件格式； （四）技术规格、参数及其他要求； （五）评标标准和方法； （六）合同主要条款。 招标人应当在招标文件中规定实质性要求和条件，说明不满足其中任何一项实质性要求和条件的投标将被拒绝，并用醒目的方式标明；没有标明的要求和条件在评标时不得作为实质性要求和条件。对于非实质性要求和条件，应规定允许偏差的最大范围、最高项数，以及对这些偏差进行调整的方法。 国家对招标货物的技术、标准、质量等有规定的，招标人应当按照其规定在招标文件中提出相应要求。"},{"i":22,"n":"第二十二条","txt":"招标货物需要划分标包的，招标人应合理划分标包，确定各标包的交货期，并在招标文件中如实载明。 招标人不得以不合理的标包限制或者排斥潜在投标人或者投标人。依法必须进行招标的项目的招标人不得利用标包划分规避招标"},{"i":23,"n":"第二十三条","txt":"招标人允许中标人对非主体货物进行分包的，应当在招标文件中载明。主要设备、材料或者供货合同的主要部分不得要求或者允许分包。 除招标文件要求不得改变标准货物的供应商外，中标人经招标人同意改变标准货物的供应商的，不应视为转包和违法分包。"},{"i":24,"n":"第二十四条","txt":"招标人可以要求投标人在提交符合招标文件规定要求的投标文件外，提交备选投标方案，但应当在招标文件中作出说明。不符合中标条件的投标人的备选投标方案不予考虑。"},{"i":25,"n":"第二十五条","txt":"招标文件规定的各项技术规格应当符合国家技术法规的规定。 招标文件中规定的各项技术规格均不得要求或标明某一特定的专利技术、商标、名称、设计、原产地或供应者等，不得含有倾向或者排斥潜在投标人的其他内容。如果必须引用某一供应者的技术规格才能准确或清楚地说明拟招标货物的技术规格时，则应当在参照后面加上“或相当于”的字样。"},{"i":26,"n":"第二十六条","txt":"招标文件应当明确规定评标时包含价格在内的所有评标因素，以及据此进行评估的方法。 在评标过程中，不得改变招标文件中规定的评标标准、方法和中标条件。"},{"i":27,"n":"第二十七条","txt":"招标人可以在招标文件中要求投标人以自己的名义提交投标保证金。投标保证金除现金外，可以是银行出具的银行保函、保兑支票、银行汇票或现金支票，也可以是招标人认可的其他合法担保形式。依法必须进行招标的项目的境内投标单位，以现金或者支票形式提交的投标保证金应当从其基本账户转出。 投标保证金不得超过项目估算价的百分之二，但最高不得超过八十万元人民币。投标保证金有效期应当与投标有效期一致。 投标人应当按照招标文件要求的方式和金额，在提交投标文件截止时间前将投标保证金提交给招标人或其委托的招标代理机构。"},{"i":28,"n":"第二十八条","txt":"招标文件应当规定一个适当的投标有效期，以保证招标人有足够的时间完成评标和与中标人签订合同。投标有效期从招标文件规定的提交投标文件截止之日起计算。 在原投标有效期结束前，出现特殊情况的，招标人可以书面形式要求所有投标人延长投标有效期。投标人同意延长的，不得要求或被允许修改其投标文件的实质性内容，但应当相应延长其投标保证金的有效期；投标人拒绝延长的，其投标失效，但投标人有权收回其投标保证金及银行同期存款利息。 依法必须进行招标的项目同意延长投标有效期的投标人少于三个的，招标人在分析招标失败的原因并采取相应措施后，应当重新招标。"},{"i":29,"n":"第二十九条","txt":"对于潜在投标人在阅读招标文件中提出的疑问，招标人应当以书面形式、投标预备会方式或者通过电子网络解答，但需同时将解答以书面方式通知所有购买招标文件的潜在投标人。该解答的内容为招标文件的组成部分。 除招标文件明确要求外，出席投标预备会不是强制性的，由潜在投标人自行决定，并自行承担由此可能产生的风险。"},{"i":30,"n":"第三十条","txt":"招标人应当确定投标人编制投标文件所需的合理时间。依法必须进行招标的货物，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不得少于二十日。"},{"i":31,"n":"第三十一条","txt":"对无法精确拟定其技术规格的货物，招标人可以采用两阶段招标程序。 在第一阶段，招标人可以首先要求潜在投标人提交技术建议，详细阐明货物的技术规格、质量和其它特性。招标人可以与投标人就其建议的内容进行协商和讨论，达成一个统一的技术规格后编制招标文件。 在第二阶段，招标人应当向第一阶段提交了技术建议的投标人提供包含统一技术规格的正式招标文件，投标人根据正式招标文件的要求提交包括价格在内的最后投标文件。 招标人要求投标人提交投标保证金的，应当在第二阶段提出。"},{"i":32,"n":"第三十二条","txt":"投标人是响应招标、参加投标竞争的法人或者其他组织。 法定代表人为同一个人的两个及两个以上法人，母公司、全资子公司及其控股公司，都不得在同一货物招标中同时投标。 违反前两款规定的，相关投标均无效。 一个制造商对同一品牌同一型号的货物，仅能委托一个代理商参加投标。"},{"i":33,"n":"第三十三条","txt":"投标人应当按照招标文件的要求编制投标文件。投标文件应当对招标文件提出的实质性要求和条件作出响应。 投标文件一般包括下列内容： （一）投标函； （二）投标一览表； （三）技术性能参数的详细描述 （四）商务和技术偏差表； （五）投标保证金； （六）有关资格证明文件； （七）招标文件要求的其他内容 投标人根据招标文件载明的货物实际情况，拟在中标后将供货合同中的非主要部分进行分包的，应当在投标文件中载明。"},{"i":34,"n":"第三十四条","txt":"投标人应当在招标文件要求提交投标文件的截止时间前，将投标文件密封送达招标文件中规定的地点。招标人收到投标文件后，应当向投标人出具标明签收人和签收时间的凭证，在开标前任何单位和个人不得开启投标文件。 在招标文件要求提交投标文件的截止时间后送达的投标文件，招标人应当拒收。 依法必须进行招标的项目，提交投标文件的投标人少于三个的，招标人在分析招标失败的原因并采取相应措施后，应当重新招标。重新招标后投标人仍少于三个，按国家有关规定需要履行审批、核准手续的依法必须进行招标的项目，报项目审批、核准部门审批、核准后可以不再进行招标。"},{"i":35,"n":"第三十五条","txt":"投标人在招标文件要求提交投标文件的截止时间前，可以补充、修改、替代或者撤回已提交的投标文件，并书面通知招标人。补充、修改的内容为投标文件的组成部分。"},{"i":36,"n":"第三十六条","txt":"在提交投标文件截止时间后，投标人不得撤销其投标文件，否则招标人可以不退还其投标保证金。"},{"i":37,"n":"第三十七条","txt":"招标人应妥善保管好已接收的投标文件、修改或撤回通知、备选投标方案等投标资料，并严格保密。"},{"i":38,"n":"第三十八条","txt":"两个以上法人或者其他组织可以组成一个联合体，以一个投标人的身份共同投标。 联合体各方签订共同投标协议后，不得再以自己名义单独投标，也不得组成或参加其他联合体在同一项目中投标；否则相关投标均无效。 联合体中标的，应当指定牵头人或代表，授权其代表所有联合体成员与招标人签订合同，负责整个合同实施阶段的协调工作。但是，需要向招标人提交由所有联合体成员法定代表人签署的授权委托书。"},{"i":39,"n":"第三十九条","txt":"招标人接受联合体投标并进行资格预审的，联合体应当在提交资格预审申请文件前组成。资格预审后联合体增减、更换成员的，其投标无效。 招标人不得强制资格预审合格的投标人组成联合体。"},{"i":40,"n":"第四十条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行；开标地点应当为招标文件中确定的地点。 投标人或其授权代表有权出席开标会，也可以自主决定不参加开标会。 投标人对开标有异议的，应当在开标现场提出，招标人应当当场作出答复，并制作记录。"},{"i":41,"n":"第四十一条","txt":"投标文件有下列情形之一的，招标人应当拒收： （一）逾期送达； （二）未按招标文件要求密封。 有下列情形之一的，评标委员会应当否决其投标： （一）投标文件未经投标单位盖章和单位负责人签字； （二）投标联合体没有提交共同投标协议； （三）投标人不符合国家或者招标文件规定的资格条件； （四）同一投标人提交两个以上不同的投标文件或者投标报价，但招标文件要求提交备选投标的除外； （五）投标标价低于成本或者高于招标文件设定的最高投标限价； （六）投标文件没有对招标文件的实质性要求和条件作出响应； （七）投标人有串通投标、弄虚作假、行贿等违法行为。 依法必须招标的项目评标委员会否决所有投标的，或者评标委员会否决一部分投标后其他有效投标不足三个使得投标明显缺乏竞争，决定否决全部投标的，招标人在分析招标失败的原因并采取相应措施后，应当重新招标。"},{"i":42,"n":"第四十二条","txt":"评标委员会可以书面方式要求投标人对投标文件中含义不明确、对同类问题表述不一致或者有明显文字和计算错误的内容作必要的澄清、说明或补正。评标委员会不得向投标人提出带有暗示性或诱导性的问题，或向其明确投标文件中的遗漏和错误。"},{"i":43,"n":"第四十三条","txt":"投标文件不响应招标文件的实质性要求和条件的，评标委员会不得允许投标人通过修正或撤销其不符合要求的差异或保留，使之成为具有响应性的投标。"},{"i":44,"n":"第四十四条","txt":"技术简单或技术规格、性能、制作工艺要求统一的货物，一般采用经评审的最低投标价法进行评标。技术复杂或技术规格、性能、制作工艺要求难以统一的货物，一般采用综合评估法进行评标。"},{"i":45,"n":"第四十五条","txt":"符合招标文件要求且评标价最低或综合评分最高而被推荐为中标候选人的投标人，其所提交的备选投标方案方可予以考虑。"},{"i":46,"n":"第四十六条","txt":"评标委员会完成评标后，应向招标人提出书面评标报告。评标报告由评标委员会全体成员签字。"},{"i":47,"n":"第四十七条","txt":"评标委员会在书面评标报告中推荐的中标候选人应当限定在一至三人，并标明排列顺序。招标人应当接受评标委员会推荐的中标候选人，不得在评标委员会推荐的中标候选人之外确定中标人。 依法必须进行招标的项目，招标人应当自收到评标报告之日起三日内公示中标候选人，公示期不得少于三日。"},{"i":48,"n":"第四十八条","txt":"国有资金占控股或者主导地位的依法必须进行招标的项目，招标人应当确定排名第一的中标候选人为中标人。排名第一的中标候选人放弃中标、因不可抗力提出不能履行合同、不按照招标文件要求提交履约保证金，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人。依次确定其他中标候选人与招标人预期差距较大，或者对招标人明显不利的，招标人可以重新招标。 招标人可以授权评标委员会直接确定中标人。 国务院对中标人的确定另有规定的，从其规定。"},{"i":49,"n":"第四十九条","txt":"招标人不得向中标人提出压低报价、增加配件或者售后服务量以及其他超出招标文件规定的违背中标人意愿的要求，以此作为发出中标通知书和签订合同的条件。"},{"i":50,"n":"第五十条","txt":"中标通知书对招标人和中标人具有法律效力。中标通知书发出后，招标人改变中标结果的，或者中标人放弃中标项目的，应当依法承担法律责任。 中标通知书由招标人发出，也可以委托其招标代理机构发出。"},{"i":51,"n":"第五十一条","txt":"招标人和中标人应当在投标有效期内并在自中标通知书发出之日起三十日内，按照招标文件和中标人的投标文件订立书面合同。招标人和中标人不得再行订立背离合同实质性内容的其他协议。 招标文件要求中标人提交履约保证金或者其他形式履约担保的，中标人应当提交；拒绝提交的，视为放弃中标项目。招标人要求中标人提供履约保证金或其他形式履约担保的，招标人应当同时向中标人提供货物款支付担保。 履约保证金不得超过中标合同金额的10%。"},{"i":52,"n":"第五十二条","txt":"招标人最迟应当在书面合同签订后五日内，向中标人和未中标的投标人一次性退还投标保证金及银行同期存款利息。"},{"i":53,"n":"第五十三条","txt":"必须审批的工程建设项目，货物合同价格应当控制在批准的概算投资范围内；确需超出范围的，应当在中标合同签订前，报原项目审批部门审查同意。项目审批部门应当根据招标的实际情况，及时作出批准或者不予批准的决定；项目审批部门不予批准的，招标人应当自行平衡超出的概算。"},{"i":54,"n":"第五十四条","txt":"依法必须进行货物招标的项目，招标人应当自确定中标人之日起十五日内，向有关行政监督部门提交招标投标情况的书面报告。 前款所称书面报告至少应包括下列内容： （一）招标货物基本情况； （二）招标方式和发布招标公告或者资格预审公告的媒介； （三）招标文件中投标人须知、技术条款、评标标准和方法、合同主要条款等内容； （四）评标委员会的组成和评标报告； （五）中标结果。"},{"i":55,"n":"第五十五条","txt":"招标人有下列限制或者排斥潜在投标行为之一的，由有关行政监督部门依照招标投标法第五十一条的规定处罚；其中，构成依法必须进行招标的项目的招标人规避招标的，依照招标投标法第四十九条的规定处罚： （一）依法应当公开招标的项目不按照规定在指定媒介发布资格预审公告或者招标公告； （二）在不同媒介发布的同一招标项目的资格预审公告或者招标公告内容不一致，影响潜在投标人申请资格预审或者投标。"},{"i":56,"n":"第五十六条","txt":"招标人有下列情形之一的，由有关行政监督部门责令改正，可以处10万元以下的罚款： （一）依法应当公开招标而采用邀请招标； （二）招标文件、资格预审文件的发售、澄清、修改的时限，或者确定的提交资格预审申请文件、投标文件的时限不符合招标投标法和招标投标法实施条例规定； （三）接受未通过资格预审的单位或者个人参加投标； （四）接受应当拒收的投标文件。 招标人有前款第一项、第三项、第四项所列行为之一的，对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":57,"n":"第五十七条","txt":"评标委员会成员有下列行为之一的，由有关行政监督部门责令改正；情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标；情节特别严重的，取消其担任评标委员会成员的资格： （一）应当回避而不回避； （二）擅离职守； （三）不按照招标文件规定的评标标准和方法评标； （四）私下接触投标人； （五）向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求； （六）对依法应当否决的投标不提出否决意见； （七）暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明； （八）其他不客观、不公正履行职务的行为。"},{"i":58,"n":"第五十八条","txt":"依法必须进行招标的项目的招标人有下列情形之一的，由有关行政监督部门责令改正，可以处中标项目金额千分之十以下的罚款；给他人造成损失的，依法承担赔偿责任；对单位直接负责的主管人员和其他直接责任人员依法给予处分： （一）无正当理由不发出中标通知书； （二）不按照规定确定中标人； （三）中标通知书发出后无正当理由改变中标结果； （四）无正当理由不与中标人订立合同； （五）在订立合同时向中标人提出附加条件。 中标通知书发出后，中标人放弃中标项目的，无正当理由不与招标人签订合同的，在签订合同时向招标人提出附加条件或者更改合同实质性内容的，或者拒不提交所要求的履约保证金的，取消其中标资格，投标保证金不予退还；给招标人的损失超过投标保证金数额的，中标人应当对超过部分予以赔偿；没有提交投标保证金的，应当对招标人的损失承担赔偿责任。对依法必须进行招标的项目的中标人，由有关行政监督部门责令改正，可以处中标金"},{"i":59,"n":"第五十九条","txt":"招标人不履行与中标人订立的合同的，应当返还中标人的履约保证金，并承担相应的赔偿责任；没有提交履约保证金的，应当对中标人的损失承担赔偿责任。 因不可抗力不能履行合同的，不适用前款规定。"},{"i":60,"n":"第六十条","txt":"中标无效的，发出的中标通知书和签订的合同自始没有法律约束力，但不影响合同中独立存在的有关解决争议方法的条款的效力。"},{"i":61,"n":"第六十一条","txt":"不属于工程建设项目，但属于固定资产投资的货物招标投标活动，参照本办法执行。"},{"i":62,"n":"第六十二条","txt":"使用国际组织或者外国政府贷款、援助资金的项目进行招标，贷款方、资金提供方对货物招标投标活动的条件和程序有不同规定的，可以适用其规定，但违背中华人民共和国社会公共利益的除外。"},{"i":63,"n":"第六十三条","txt":"本办法由国家发展和改革委员会会同有关部门负责解释。"},{"i":64,"n":"第六十四条","txt":"本办法自2005年3月1日起施行。"}],"gongchengjianshexiangmuhuowuzhaobiaotoubiaobanfa":[{"i":1,"n":"第一条","txt":"为规范工程建设项目的货物招标投标活动，保护国家利益、社会公共利益和招标投标活动当事人的合法权益，保证工程质量，提高投资效益，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》和国务院有关部门的职责分工，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内工程建设项目货物招标投标活动。"},{"i":3,"n":"第三条","txt":"工程建设项目符合《工程建设项目招标范围和规模标准规定》(原国家计委令第3号)规定的范围和标准的，必须通过招标选择货物供应单位。 任何单位和个人不得将依法必须进行招标的项目化整为零或者以其他任何方式规避招标。"},{"i":4,"n":"第四条","txt":"工程建设项目货物招标投标活动应当遵循公开、公平、公正和诚实信用的原则。货物招标投标活动不受地区或者部门的限制。"},{"i":5,"n":"第五条","txt":"工程建设项目货物招标投标活动，依法由招标人负责。 工程建设项目招标人对项目实行总承包招标时，未包括在总承包范围内的货物属于依法必须进行招标的项目范围且达到国家规定规模标准的，应当由工程建设项目招标人依法组织招标。 工程建设项目实行总承包招标时，以暂估价形式包括在总承包范围内的货物属于依法必须进行招标的项目范围且达到国家规定规模标准的，应当依法组织招标。"},{"i":6,"n":"第六条","txt":"各级发展改革、工业和信息化、住房城乡建设、交通运输、铁道、水利、民航等部门依照国务院和地方各级人民政府关于工程建设项目行政监督的职责分工，对工程建设项目中所包括的货物招标投标活动实施监督，依法查处货物招标投标活动中的违法行为。"},{"i":7,"n":"第七条","txt":"工程建设项目招标人是依法提出招标项目、进行招标的法人或者其他组织。本办法第五条总承包中标人单独或者共同招标时，也为招标人。"},{"i":8,"n":"第八条","txt":"依法必须招标的工程建设项目，应当具备下列条件才能进行货物招标： (一)招标人已经依法成立; (二)按照国家有关规定应当履行项目审批、核准或者备案手续的，已经审批、核准或者备案; (三)有相应资金或者资金来源已经落实; (四)能够提出货物的使用与技术要求。"},{"i":9,"n":"第九条","txt":"依法必须进行招标的工程建设项目，按国家有关规定需要履行审批、核准手续的，招标人应当在报送的可行性研究报告、资金申请报告或者项目申请报告中将货物招标范围、招标方式(公开招标或邀请招标)、招标组织形式(自行招标或委托招标)等有关招标内容报项目审批、核准部门审批、核准。项目审批、核准部门应当将审批、核准的招标内容通报有关行政监督部门。"},{"i":10,"n":"第十条","txt":"货物招标分为公开招标和邀请招标。"},{"i":11,"n":"第十一条","txt":"依法应当公开招标的项目，有下列情形之一的，可以邀请招标： (一)技术复杂、有特殊要求或者受自然环境限制，只有少量潜在投标人可供选择; (二)采用公开招标方式的费用占项目合同金额的比例过大; (三)涉及国家安全、国家秘密或者抢险救灾，适宜招标但不宜公开招标。 有前款第二项所列情形，属于按照国家有关规定需要履行项目审批、核准手续的依法必须进行招标的项目，由项目审批、核准部门认定;其他项目由招标人申请有关行政监督部门作出认定。"},{"i":12,"n":"第十二条","txt":"采用公开招标方式的，招标人应当发布资格预审公告或者招标公告。依法必须进行货物招标的招标公告，应当在国家指定的报刊或者信息网络上发布。 采用邀请招标方式的，招标人应当向三家以上具备货物供应的能力、资信良好的特定的法人或者其他组织发出投标邀请书。"},{"i":13,"n":"第十三条","txt":"招标公告或者投标邀请书应当载明下列内容： (一)招标人的名称和地址; (二)招标货物的名称、数量、技术规格、资金来源; (三)交货的地点和时间; (四)获取招标文件或者资格预审文件的地点和时间; (五)对招标文件或者资格预审文件收取的费用; (六)提交资格预审申请书或者投标文件的地点和截止日期; (七)对投标人的资格要求。"},{"i":14,"n":"第十四条","txt":"招标人应当按照资格预审公告、招标公告或者投标邀请书规定的时间、地点发售招标文件或者资格预审文件。自招标文件或者资格预审文件发售之日起至停止发售之日止，最短不得少于五日。 招标人可以通过信息网络或者其他媒介发布招标文件，通过信息网络或者其他媒介发布的招标文件与书面招标文件具有同等法律效力，出现不一致时以书面招标文件为准，但国家另有规定的除外。 对招标文件或者资格预审文件的收费应当限于补偿印刷、邮寄的成本支出，不得以营利为目的。 除不可抗力原因外，招标文件或者资格预审文件发出后，不予退还;招标人在发布招标公告、发出投标邀请书后或者发出招标文件或资格预审文件后不得终止招标。招标人终止招标的，应当及时发布公告，或者以书面形式通知被邀请的或者已经获取资格预审文件、招标文件的潜在投标人。已经发售资格预审文件、招标文件或者已经收取投标保证金的，招标人应当及时退还所收取的资格预审文件、招标文件的费用，"},{"i":15,"n":"第十五条","txt":"招标人可以根据招标货物的特点和需要，对潜在投标人或者投标人进行资格审查;国家对潜在投标人或者投标人的资格条件有规定的，依照其规定。"},{"i":16,"n":"第十六条","txt":"资格审查分为资格预审和资格后审。 资格预审，是指招标人出售招标文件或者发出投标邀请书前对潜在投标人进行的资格审查。资格预审一般适用于潜在投标人较多或者大型、技术复杂货物的招标。 资格后审，是指在开标后对投标人进行的资格审查。资格后审一般在评标过程中的初步评审开始时进行。"},{"i":17,"n":"第十七条","txt":"采取资格预审的，招标人应当发布资格预审公告。资格预审公告适用本办法第十二条、第十三条有关招标公告的规定。"},{"i":18,"n":"第十八条","txt":"资格预审文件一般包括下列内容： (一)资格预审公告; (二)申请人须知; (三)资格要求; (四)其他业绩要求; (五)资格审查标准和方法; (六)资格预审结果的通知方式。"},{"i":19,"n":"第十九条","txt":"采取资格预审的，招标人应当在资格预审文件中详细规定资格审查的标准和方法;采取资格后审的，招标人应当在招标文件中详细规定资格审查的标准和方法。 招标人在进行资格审查时，不得改变或补充载明的资格审查标准和方法或者以没有载明的资格审查标准和方法对潜在投标人或者投标人进行资格审查。"},{"i":20,"n":"第二十条","txt":"经资格预审后，招标人应当向资格预审合格的潜在投标人发出资格预审合格通知书，告知获取招标文件的时间、地点和方法，并同时向资格预审不合格的潜在投标人告知资格预审结果。依法必须招标的项目通过资格预审的申请人不足三个的，招标人在分析招标失败的原因并采取相应措施后，应当重新招标。 对资格后审不合格的投标人，评标委员会应当否决其投标。"},{"i":21,"n":"第二十一条","txt":"招标文件一般包括下列内容： (一)招标公告或者投标邀请书; (二)投标人须知; (三)投标文件格式; (四)技术规格、参数及其他要求; (五)评标标准和方法; (六)合同主要条款。 招标人应当在招标文件中规定实质性要求和条件，说明不满足其中任何一项实质性要求和条件的投标将被拒绝，并用醒目的方式标明;没有标明的要求和条件在评标时不得作为实质性要求和条件。对于非实质性要求和条件，应规定允许偏差的最大范围、最高项数，以及对这些偏差进行调整的方法。 国家对招标货物的技术、标准、质量等有规定的，招标人应当按照其规定在招标文件中提出相应要求。"},{"i":22,"n":"第二十二条","txt":"招标货物需要划分标包的，招标人应合理划分标包，确定各标包的交货期，并在招标文件中如实载明。 招标人不得以不合理的标包限制或者排斥潜在投标人或者投标人。依法必须进行招标的项目的招标人不得利用标包划分规避招标。"},{"i":23,"n":"第二十三条","txt":"招标人允许中标人对非主体货物进行分包的，应当在招标文件中载明。主要设备、材料或者供货合同的主要部分不得要求或者允许分包。 除招标文件要求不得改变标准货物的供应商外，中标人经招标人同意改变标准货物的供应商的，不应视为转包和违法分包。"},{"i":24,"n":"第二十四条","txt":"招标人可以要求投标人在提交符合招标文件规定要求的投标文件外，提交备选投标方案，但应当在招标文件中作出说明。不符合中标条件的投标人的备选投标方案不予考虑。"},{"i":25,"n":"第二十五条","txt":"招标文件规定的各项技术规格应当符合国家技术法规的规定。 招标文件中规定的各项技术规格均不得要求或标明某一特定的专利技术、商标、名称、设计、原产地或供应者等，不得含有倾向或者排斥潜在投标人的其他内容。如果必须引用某一供应者的技术规格才能准确或清楚地说明拟招标货物的技术规格时，则应当在参照后面加上“或相当于”的字样。"},{"i":26,"n":"第二十六条","txt":"招标文件应当明确规定评标时包含价格在内的所有评标因素，以及据此进行评估的方法。 在评标过程中，不得改变招标文件中规定的评标标准、方法和中标条件。"},{"i":27,"n":"第二十七条","txt":"招标人可以在招标文件中要求投标人以自己的名义提交投标保证金。投标保证金除现金外，可以是银行出具的银行保函、保兑支票、银行汇票或现金支票，也可以是招标人认可的其他合法担保形式。依法必须进行招标的项目的境内投标单位，以现金或者支票形式提交的投标保证金应当从其基本账户转出。 投标保证金不得超过项目估算价的百分之二，但最高不得超过八十万元人民币。投标保证金有效期应当与投标有效期一致。 投标人应当按照招标文件要求的方式和金额，在提交投标文件截止时间前将投标保证金提交给招标人或其委托的招标代理机构。"},{"i":28,"n":"第二十八条","txt":"招标文件应当规定一个适当的投标有效期，以保证招标人有足够的时间完成评标和与中标人签订合同。投标有效期从招标文件规定的提交投标文件截止之日起计算。 在原投标有效期结束前，出现特殊情况的，招标人可以书面形式要求所有投标人延长投标有效期。投标人同意延长的，不得要求或被允许修改其投标文件的实质性内容，但应当相应延长其投标保证金的有效期;投标人拒绝延长的，其投标失效，但投标人有权收回其投标保证金及银行同期存款利息。 依法必须进行招标的项目同意延长投标有效期的投标人少于三个的，招标人在分析招标失败的原因并采取相应措施后，应当重新招标。"},{"i":29,"n":"第二十九条","txt":"对于潜在投标人在阅读招标文件中提出的疑问，招标人应当以书面形式、投标预备会方式或者通过电子网络解答，但需同时将解答以书面方式通知所有购买招标文件的潜在投标人。该解答的内容为招标文件的组成部分。 除招标文件明确要求外，出席投标预备会不是强制性的，由潜在投标人自行决定，并自行承担由此可能产生的风险。"},{"i":30,"n":"第三十条","txt":"招标人应当确定投标人编制投标文件所需的合理时间。依法必须进行招标的货物，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不得少于二十日。"},{"i":31,"n":"第三十一条","txt":"对无法精确拟定其技术规格的货物，招标人可以采用两阶段招标程序。 在第一阶段，招标人可以首先要求潜在投标人提交技术建议，详细阐明货物的技术规格、质量和其它特性。招标人可以与投标人就其建议的内容进行协商和讨论，达成一个统一的技术规格后编制招标文件。 在第二阶段，招标人应当向第一阶段提交了技术建议的投标人提供包含统一技术规格的正式招标文件，投标人根据正式招标文件的要求提交包括价格在内的最后投标文件。 招标人要求投标人提交投标保证金的，应当在第二阶段提出。"},{"i":32,"n":"第三十二条","txt":"投标人是响应招标、参加投标竞争的法人或者其他组织。 法定代表人为同一个人的两个及两个以上法人，母公司、全资子公司及其控股公司，都不得在同一货物招标中同时投标。 一个制造商对同一品牌同一型号的货物，仅能委托一个代理商参加投标。 违反前两款规定的，相关投标均无效。"},{"i":33,"n":"第三十三条","txt":"投标人应当按照招标文件的要求编制投标文件。投标文件应当对招标文件提出的实质性要求和条件作出响应。投标文件一般包括下列内容： (一)投标函; (二)投标一览表; (三)技术性能参数的详细描述; (四)商务和技术偏差表; (五)投标保证金; (六)有关资格证明文件; (七)招标文件要求的其他内容。 投标人根据招标文件载明的货物实际情况，拟在中标后将供货合同中的非主要部分进行分包的，应当在投标文件中载明。"},{"i":34,"n":"第三十四条","txt":"投标人应当在招标文件要求提交投标文件的截止时间前，将投标文件密封送达招标文件中规定的地点。招标人收到投标文件后，应当向投标人出具标明签收人和签收时间的凭证，在开标前任何单位和个人不得开启投标文件。 在招标文件要求提交投标文件的截止时间后送达的投标文件，招标人应当拒收。 依法必须进行招标的项目，提交投标文件的投标人少于三个的，招标人在分析招标失败的原因并采取相应措施后，应当重新招标。重新招标后投标人仍少于三个，按国家有关规定需要履行审批、核准手续的依法必须进行招标的项目，报项目审批、核准部门审批、核准后可以不再进行招标。"},{"i":35,"n":"第三十五条","txt":"投标人在招标文件要求提交投标文件的截止时间前，可以补充、修改、替代或者撤回已提交的投标文件，并书面通知招标人。补充、修改的内容为投标文件的组成部分。"},{"i":36,"n":"第三十六条","txt":"在提交投标文件截止时间后，投标人不得撤销其投标文件，否则招标人可以不退还其投标保证金。"},{"i":37,"n":"第三十七条","txt":"招标人应妥善保管好已接收的投标文件、修改或撤回通知、备选投标方案等投标资料，并严格保密。"},{"i":38,"n":"第三十八条","txt":"两个以上法人或者其他组织可以组成一个联合体，以一个投标人的身份共同投标。 联合体各方签订共同投标协议后，不得再以自己名义单独投标，也不得组成或参加其他联合体在同一项目中投标;否则相关投标均无效。 联合体中标的，应当指定牵头人或代表，授权其代表所有联合体成员与招标人签订合同，负责整个合同实施阶段的协调工作。但是，需要向招标人提交由所有联合体成员法定代表人签署的授权委托书。"},{"i":39,"n":"第三十九条","txt":"招标人接受联合体投标并进行资格预审的，联合体应当在提交资格预审申请文件前组成。资格预审后联合体增减、更换成员的，其投标无效。 招标人不得强制资格预审合格的投标人组成联合体。"},{"i":40,"n":"第四十条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行;开标地点应当为招标文件中确定的地点。 投标人或其授权代表有权出席开标会，也可以自主决定不参加开标会。 投标人对开标有异议的，应当在开标现场提出，招标人应当当场作出答复，并制作记录。"},{"i":41,"n":"第四十一条","txt":"投标文件有下列情形之一的，招标人应当拒收： (一)逾期送达; (二)未按招标文件要求密封。 有下列情形之一的，评标委员会应当否决其投标： (一)投标文件未经投标单位盖章和单位负责人签字; (二)投标联合体没有提交共同投标协议; (三)投标人不符合国家或者招标文件规定的资格条件; (四)同一投标人提交两个以上不同的投标文件或者投标报价，但招标文件要求提交备选投标的除外; (五)投标标价低于成本或者高于招标文件设定的最高投标限价; (六)投标文件没有对招标文件的实质性要求和条件作出响应; (七)投标人有串通投标、弄虚作假、行贿等违法行为。 依法必须招标的项目评标委员会否决所有投标的，或者评标委员会否决一部分投标后其他有效投标不足三个使得投标明显缺乏竞争，决定否决全部投标的，招标人在分析招标失败的原因并采取相应措施后，应当重新招标。"},{"i":42,"n":"第四十二条","txt":"评标委员会可以书面方式要求投标人对投标文件中含义不明确、对同类问题表述不一致或者有明显文字和计算错误的内容作必要的澄清、说明或补正。评标委员会不得向投标人提出带有暗示性或诱导性的问题，或向其明确投标文件中的遗漏和错误。"},{"i":43,"n":"第四十三条","txt":"投标文件不响应招标文件的实质性要求和条件的，评标委员会不得允许投标人通过修正或撤销其不符合要求的差异或保留，使之成为具有响应性的投标。"},{"i":44,"n":"第四十四条","txt":"技术简单或技术规格、性能、制作工艺要求统一的货物，一般采用经评审的最低投标价法进行评标。技术复杂或技术规格、性能、制作工艺要求难以统一的货物，一般采用综合评估法进行评标。"},{"i":45,"n":"第四十五条","txt":"符合招标文件要求且评标价最低或综合评分最高而被推荐为中标候选人的投标人，其所提交的备选投标方案方可予以考虑。"},{"i":46,"n":"第四十六条","txt":"评标委员会完成评标后，应向招标人提出书面评标报告。评标报告由评标委员会全体成员签字。"},{"i":47,"n":"第四十七条","txt":"评标委员会在书面评标报告中推荐的中标候选人应当限定在一至三人，并标明排列顺序。招标人应当接受评标委员会推荐的中标候选人，不得在评标委员会推荐的中标候选人之外确定中标人。 依法必须进行招标的项目，招标人应当自收到评标报告之日起三日内公示中标候选人，公示期不得少于三日。"},{"i":48,"n":"第四十八条","txt":"国有资金占控股或者主导地位的依法必须进行招标的项目，招标人应当确定排名第一的中标候选人为中标人。排名第一的中标候选人放弃中标、因不可抗力提出不能履行合同、不按照招标文件要求提交履约保证金，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人。依次确定其他中标候选人与招标人预期差距较大，或者对招标人明显不利的，招标人可以重新招标。 招标人可以授权评标委员会直接确定中标人。 国务院对中标人的确定另有规定的，从其规定。"},{"i":49,"n":"第四十九条","txt":"招标人不得向中标人提出压低报价、增加配件或者售后服务量以及其他超出招标文件规定的违背中标人意愿的要求，以此作为发出中标通知书和签订合同的条件。"},{"i":50,"n":"第五十条","txt":"中标通知书对招标人和中标人具有法律效力。中标通知书发出后，招标人改变中标结果的，或者中标人放弃中标项目的，应当依法承担法律责任。 中标通知书由招标人发出，也可以委托其招标代理机构发出。"},{"i":51,"n":"第五十一条","txt":"招标人和中标人应当在投标有效期内并在自中标通知书发出之日起三十日内，按照招标文件和中标人的投标文件订立书面合同。招标人和中标人不得再行订立背离合同实质性内容的其他协议。 招标文件要求中标人提交履约保证金或者其他形式履约担保的，中标人应当提交;拒绝提交的，视为放弃中标项目。招标人要求中标人提供履约保证金或其他形式履约担保的，招标人应当同时向中标人提供货物款支付担保。 履约保证金不得超过中标合同金额的10%。"},{"i":52,"n":"第五十二条","txt":"招标人最迟应当在书面合同签订后五日内，向中标人和未中标的投标人一次性退还投标保证金及银行同期存款利息。"},{"i":53,"n":"第五十三条","txt":"必须审批的工程建设项目，货物合同价格应当控制在批准的概算投资范围内;确需超出范围的，应当在中标合同签订前，报原项目审批部门审查同意。项目审批部门应当根据招标的实际情况，及时作出批准或者不予批准的决定;项目审批部门不予批准的，招标人应当自行平衡超出的概算。"},{"i":54,"n":"第五十四条","txt":"依法必须进行货物招标的项目，招标人应当自确定中标人之日起十五日内，向有关行政监督部门提交招标投标情况的书面报告。 前款所称书面报告至少应包括下列内容： (一)招标货物基本情况; (二)招标方式和发布招标公告或者资格预审公告的媒介; (三)招标文件中投标人须知、技术条款、评标标准和方法、合同主要条款等内容; (四)评标委员会的组成和评标报告; (五)中标结果。"},{"i":55,"n":"第五十五条","txt":"招标人有下列限制或者排斥潜在投标行为之一的，由有关行政监督部门依照招标投标法第五十一条的规定处罚;其中，构成依法必须进行招标的项目的招标人规避招标的，依照招标投标法第四十九条的规定处罚： (一)依法应当公开招标的项目不按照规定在指定媒介发布资格预审公告或者招标公告; (二)在不同媒介发布的同一招标项目的资格预审公告或者招标公告内容不一致，影响潜在投标人申请资格预审或者投标。"},{"i":56,"n":"第五十六条","txt":"招标人有下列情形之一的，由有关行政监督部门责令改正，可以处10万元以下的罚款： (一)依法应当公开招标而采用邀请招标; (二)招标文件、资格预审文件的发售、澄清、修改的时限，或者确定的提交资格预审申请文件、投标文件的时限不符合招标投标法和招标投标法实施条例规定; (三)接受未通过资格预审的单位或者个人参加投标; (四)接受应当拒收的投标文件。 招标人有前款第一项、第三项、第四项所列行为之一的，对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":57,"n":"第五十七条","txt":"评标委员会成员有下列行为之一的，由有关行政监督部门责令改正;情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标;情节特别严重的，取消其担任评标委员会成员的资格： (一)应当回避而不回避; (二)擅离职守; (三)不按照招标文件规定的评标标准和方法评标; (四)私下接触投标人; (五)向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求; (六)对依法应当否决的投标不提出否决意见; (七)暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明; (八)其他不客观、不公正履行职务的行为。"},{"i":58,"n":"第五十八条","txt":"依法必须进行招标的项目的招标人有下列情形之一的，由有关行政监督部门责令改正，可以处中标项目金额千分之十以下的罚款;给他人造成损失的，依法承担赔偿责任;对单位直接负责的主管人员和其他直接责任人员依法给予处分： (一)无正当理由不发出中标通知书; (二)不按照规定确定中标人; (三)中标通知书发出后无正当理由改变中标结果; (四)无正当理由不与中标人订立合同; (五)在订立合同时向中标人提出附加条件。 中标通知书发出后，中标人放弃中标项目的，无正当理由不与招标人签订合同的，在签订合同时向招标人提出附加条件或者更改合同实质性内容的，或者拒不提交所要求的履约保证金的，取消其中标资格，投标保证金不予退还;给招标人的损失超过投标保证金数额的，中标人应当对超过部分予以赔偿;没有提交投标保证金的，应当对招标人的损失承担赔偿责任。对依法必须进行招标的项目的中标人，由有关行政监督部门责令改正，可以处中标金"},{"i":59,"n":"第五十九条","txt":"招标人不履行与中标人订立的合同的，应当返还中标人的履约保证金，并承担相应的赔偿责任;没有提交履约保证金的，应当对中标人的损失承担赔偿责任。 因不可抗力不能履行合同的，不适用前款规定。"},{"i":60,"n":"第六十条","txt":"中标无效的，发出的中标通知书和签订的合同自始没有法律约束力，但不影响合同中独立存在的有关解决争议方法的条款的效力。"},{"i":61,"n":"第六十一条","txt":"不属于工程建设项目，但属于固定资产投资的货物招标投标活动，参照本办法执行。"},{"i":62,"n":"第六十二条","txt":"使用国际组织或者外国政府贷款、援助资金的项目进行招标，贷款方、资金提供方对货物招标投标活动的条件和程序有不同规定的，可以适用其规定，但违背中华人民共和国社会公共利益的除外。"},{"i":63,"n":"第六十三条","txt":"本办法由国家发展和改革委员会会同有关部门负责解释。"},{"i":64,"n":"第六十四条","txt":"本办法自2005年3月1日起施行。"}],"bixuzhaobiaodigongchengxiangmuguiding":[{"i":1,"n":"第一条","txt":"为了确定必须招标的工程项目，规范招标投标活动，提高工作效率、降低企业成本、预防腐败，根据《中华人民共和国招标投标法》第三条的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"全部或者部分使用国有资金投资或者国家融资的项目包括： (一)使用预算资金200万元人民币以上，并且该资金占投资额10%以上的项目; (二)使用国有企业事业单位资金，并且该资金占控股或者主导地位的项目。"},{"i":3,"n":"第三条","txt":"使用国际组织或者外国政府贷款、援助资金的项目包括： (一)使用世界银行、亚洲开发银行等国际组织贷款、援助资金的项目; (二)使用外国政府及其机构贷款、援助资金的项目。"},{"i":4,"n":"第四条","txt":"不属于本规定第二条、第三条规定情形的大型基础设施、公用事业等关系社会公共利益、公众安全的项目，必须招标的具体范围由国务院发展改革部门会同国务院有关部门按照确有必要、严格限定的原则制订，报国务院批准。"},{"i":5,"n":"第五条","txt":"本规定第二条至第四条规定范围内的项目，其勘察、设计、施工、监理以及与工程建设有关的重要设备、材料等的采购达到下列标准之一的，必须招标： (一)施工单项合同估算价在400万元人民币以上; (二)重要设备、材料等货物的采购，单项合同估算价在200万元人民币以上; (三)勘察、设计、监理等服务的采购，单项合同估算价在100万元人民币以上。 同一项目中可以合并进行的勘察、设计、施工、监理以及与工程建设有关的重要设备、材料等的采购，合同估算价合计达到前款规定标准的，必须招标。"},{"i":6,"n":"第六条","txt":"本规定自2018年6月1日起施行。"}],"kouyazhuijiaomoshouwupingujiaguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对扣押、追缴、没收物品估价管理，规范扣押、追缴、没收物品估价工作，保障刑事诉讼活动的顺利进行，依据国家有关法律和最高人民法院、最高人民检察院、公安部、国家计委的有关规定，特制定本办法。"},{"i":2,"n":"第二条","txt":"人民法院、人民检察院、公安机关各自管辖的刑事案件，对于价格不明或者价格难以确定的扣押、追缴、没收物品需要估价的，应当委托指定的估价机构估价。案件移送时，应当附有《扣押、追缴、没收物品估价鉴定结论书》。"},{"i":3,"n":"第三条","txt":"公安机关移送人民检察院审查起诉和人民检察院向人民法院提起公诉的案件，对估价结论有异议的，应当由提出异议的机关自行委托估价机构重新估价。"},{"i":4,"n":"第四条","txt":"对于扣押、追缴、没收的珍贵文物，珍贵、濒危动物及其制品，珍稀植物及其制品，毒品，淫秽物品，枪支、弹药等不以价格数额作为定罪量刑标准的，不需要估价。"},{"i":5,"n":"第五条","txt":"国务院及地方人民政府价格部门是扣押、追缴、没收物品估价工作的主管部门，其设立的价格事务所是各级人民法院、人民检察院、公安机关指定的扣押、追缴、没收物品估价机构，其他任何机构或者个人不得对扣押、追缴、没收物品估价。"},{"i":6,"n":"第六条","txt":"价格事务所出具的扣押、追缴、没收物品估价鉴定结论，经人民法院、人民检察院、公安机关确认，可以作为办理案件的依据。"},{"i":7,"n":"第七条","txt":"各级人民法院、人民检察院、公安机关遇有本办法第二条所列情形时，应当委托同级价格部门设立的价格事务所进行估价。"},{"i":8,"n":"第八条","txt":"委托机关在委托估价时，应当送交《扣押、追缴、没收物品估价委托书》。《扣押、追缴、没收物品估价委托书》应当包括以下内容： (一)估价的理由和要求; (二)扣押、追缴、没收物品的品名、牌号、规格、种类、数量、来源，以及购置、生产、使用时间; (三)起获扣押、追缴、没收物品时其被使用、损坏程度的记录，重要的扣押、追缴、没收物品，应当附照片; (四)起获扣押、追缴、没收物品的时间、地点; (五)其他需要说明的情况。 委托机关送交的《扣押、追缴、没收物品估价委托书》必须加盖单位公章。"},{"i":9,"n":"第九条","txt":"价格事务所接到人民法院、人民检察院、公安机关的《扣押、追缴、没收物品估价委托书》时，应当认真审核委托书的各项内容及要求，如委托书所提要求无法做到时，应当立即与委托机关协商。"},{"i":10,"n":"第十条","txt":"价格事务所在接受委托后，应当按照《扣押、追缴、没收物品估价委托书》载明的情况对实物进行查验，如发现差异，应立即与委托机关共同确认。 价格事务所一般不留存扣押、追缴、没收物品，如确需留存时，应当征得委托机关同意并严格办理交接手续。"},{"i":11,"n":"第十一条","txt":"价格事务所估价确实需要时，可以提请委托机关协助查阅有关的帐目、文件等资料。可以向与委托事项有关的单位和个人进行调查或索取证明材料。"},{"i":12,"n":"第十二条","txt":"价格事务所应当在接受估价委托之日起七日内作出扣押、追缴、没收物品估价鉴定结论;另有约定的，在约定期限内作出。"},{"i":13,"n":"第十三条","txt":"价格事务所办理的扣押、追缴、没收物品估价鉴定，应当由两名以上估价工作人员共同承办，出具的估价鉴定结论，必须经过内部审议。 价格事务所估价人员，遇有下列情形之一的，应当回避： (一)与估价事项当事人有亲属关系或与该估价事项有利害关系的; (二)与估价事项当事人有其他关系，可能影响对扣押、追缴、没收物品公正估价的。"},{"i":14,"n":"第十四条","txt":"价格事务所在完成估价后，应当向委托机关出具《扣押、追缴、没收物品估价鉴定结论书》。《扣押、追缴、没收物品估价鉴定结论书》应当包括以下内容： (一)估价范围和内容; (二)估价依据; (三)估价方法和过程要述; (四)估价结论; (五)其他需要说明的问题及有关材料; (六)估价工作人员签名。 价格事务所出具的《扣押、追缴、没收物品估价鉴定结论书》必须加盖单位公章。"},{"i":15,"n":"第十五条","txt":"委托机关对价格事务所出具的《扣押、追缴、没收物品估价鉴定结论书》有异议的，可以向原估价机构要求补充鉴定或者重新鉴定，也可以直接委托上级价格部门设立的价格事务所复核或者重新估价。"},{"i":16,"n":"第十六条","txt":"接受委托的价格事务所认为必要时，在征得委托机关同意后，可以将委托事项转送上级价格部门设立的价格事务所进行估价，并将有关情况书面通知原委托估价机关。"},{"i":17,"n":"第十七条","txt":"国家计划委员会直属价格事务所是扣押、追缴、没收物品估价的最终复核裁定机构。"},{"i":18,"n":"第十八条","txt":"价格事务所必须按照国家的有关法律规定，以及最高人民法院、最高人民检察院制定的有关司法解释和各项价格法规，客观公正、准确及时地估定扣押、追缴、没收物品价格。"},{"i":19,"n":"第十九条","txt":"扣押、追缴、没收物品估价的基准日除法律、法规和司法解释另有规定外，应当由委托机关根据案件实际情况确定。"},{"i":20,"n":"第二十条","txt":"价格事务所对委托估价的文物、邮票、字画、贵重金银、珠宝及其制品等特殊物品，应当送有关专业部门作出技术、质量鉴定后，根据其提供的有关依据，作出估价结论。"},{"i":21,"n":"第二十一条","txt":"按照国家有关价格工作的管理规定，扣押、追缴、没收物品估价工作实行统一领导、分级管理。"},{"i":22,"n":"第二十二条","txt":"国家计划委员会的主要职责： (一)会同最高人民法院、最高人民检察院、公安部制定、解释扣押、追缴、没收物品估价工作的基本原则。 (二)确定划分国家和地方价格部门在扣押、追缴、没收物品估价工作中的主要职责。 (三)负责管理、指导、监督、检查全国扣押、追缴、没收物品估价工作。 (四)其设立的价格事务所办理最高人民法院、最高人民检察院、公安部委托的扣押、追缴、没收物品估价;协调或者办理跨地区(省、自治区、直辖市)、跨部门的扣押、追缴、没收物品估价业务;办理疑难、重大案件涉及的扣押、追缴、没收物品估价。"},{"i":23,"n":"第二十三条","txt":"各省、自治区、直辖市价格部门的主要职责： (一)贯彻执行最高人民法院、最高人民检察院、公安部和国家计委对估价工作制定的各项方针、政策和基本原则，会同同级司法机关制定本地区有关扣押、追缴、没收物品估价的具体规定。 (二)其设立的价格事务所办理同级人民法院、人民检察院、公安机关委托的扣押、追缴、没收物品估价;办理本地区内跨地(市)县，有相当难度的扣押、追缴、没收物品估价及复核工作;协助上级价格部门设立的价格事务所进行扣押、追缴、没收物品估价工作。"},{"i":24,"n":"第二十四条","txt":"地(市)县(市、区)价格部门的职责： (一)贯彻执行估价工作的有关规定，协助上级价格部门做好扣押、追缴、没收物品估价工作。接受上级价格部门对扣押、追缴、没收物品估价工作的管理、指导、监督、检查。 (二)其设立的价格事务所办理同级人民法院、人民检察院、公安机关委托的扣押、追缴、没收物品估价，协助上级价格部门设立的价格事务所进行扣押、追缴、没收物品估价工作。"},{"i":25,"n":"第二十五条","txt":"严禁估价人员虚假鉴定、徇私舞弊、玩忽职守、泄露涉案秘密。凡违反规定，造成估价失实，或者对办理案件造成不良影响的，对责任人员将视情节，给予处分;构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"价格事务所和鉴定人对出具的《扣押、追缴、没收物品估价鉴定结论书》的内容分别承担相应法律责任。"},{"i":27,"n":"第二十七条","txt":"价格事务所及其工作人员对估价工作中涉及的有关资料和情况负责保密。"},{"i":28,"n":"第二十八条","txt":"其他涉案物品的估价，以及行政执法机关提请价格部门设立的价格事务所对收缴、罚没、扣押物品的估价，可以参照本办法执行。"},{"i":29,"n":"第二十九条","txt":"价格事务所在进行扣押、追缴、没收物品估价时，可以向委托估价机关收取合理的估价鉴定费。估价鉴定收费办法由国家计委会同最高人民法院、最高人民检察院、公安部并商有关部门另行制定。"},{"i":30,"n":"第三十条","txt":"本办法自颁布之日起施行。 附件： 一、扣押、追缴、没收物品估价委托书(样本) 二、扣押、追缴、没收物品估价鉴定结论书(样本)"}],"chengzhuangdianlisheshixukezhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强承装（修、试）电力设施许可管理，规范承装（修、试）电力设施许可行为，维护承装、承修、承试电力设施市场秩序，促进电力安全，根据《中华人民共和国行政许可法》《电力供应与使用条例》《电力监管条例》和国家有关规定，制定本办法为。"},{"i":2,"n":"第二条","txt":"承装（修、试）电力设施许可证（以下简称许可证）的申请、受理、审查、颁发、管理和监督，适用本办法。"},{"i":3,"n":"第三条","txt":"国家能源局负责指导、监督全国许可证的颁发和管理。 国家能源局派出机构（以下简称派出机构）负责辖区内许可证的受理、审查、颁发和日常监督管理。"},{"i":4,"n":"第四条","txt":"在中华人民共和国境内从事承装、承修、承试电力设施活动的，应当按照本办法的规定取得许可证。除国家能源局另有规定外，任何单位或者个人未取得许可证，不得从事承装、承修、承试电力设施活动。 本办法所称承装、承修、承试电力设施，是指对输电、供电、受电电力设施的安装、维修和试验。"},{"i":5,"n":"第五条","txt":"取得许可证的单位依法开展活动，受法律保护。"},{"i":6,"n":"第六条","txt":"许可证分为承装、承修、承试三个类别。 取得承装类许可证的，可以从事电力设施的安装活动。 取得承修类许可证的，可以从事电力设施的维修活动。 取得承试类许可证的，可以从事电力设施的试验活动。"},{"i":7,"n":"第七条","txt":"许可证分为一级、二级、三级、四级和五级。 取得一级许可证的，可以从事所有电压等级电力设施的安装、维修或者试验活动。 取得二级许可证的，可以从事330千伏以下电压等级电力设施的安装、维修或者试验活动。 取得三级许可证的，可以从事110千伏以下电压等级电力设施的安装、维修或者试验活动。 取得四级许可证的，可以从事35千伏以下电压等级电力设施的安装、维修或者试验活动。 取得五级许可证的，可以从事10千伏以下电压等级电力设施的安装、维修或者试验活动。"},{"i":8,"n":"第八条","txt":"申请许可证应当具备法人资格及健全有效的安全生产组织和制度，并符合下列条件： （一）净资产 具有与开展承装（修、试）电力设施活动相适应的净资产，其所占总资产比例不低于15%。 （二）技术负责人、安全负责人 1.申请一级至三级许可证的，分别拥有5年以上与所申请许可证类别相适应的电力设施安装、维修或试验管理工作经历，具有电力相关专业中级以上职称；其中申请一级许可证的，应具有电力相关专业高级职称; 2.申请四级至五级许可证的，分别拥有3年以上与所申请许可证类别相适应的电力设施安装、维修或试验管理工作经历，具有电力相关专业初级以上职称。 （三）专业技术及技能人员 1.申请一级至三级许可证的，电力相关专业技术人员分别不少于50人、30人和15人，其中具有中级以上技术任职资格的分别不少于30人、15人和5人;电力相关专业技能人员分别不少于60人、30人和20人，其中高压电工分别不少于30人、15人和"},{"i":9,"n":"第九条","txt":"申请一级至三级许可证的，除具备本办法第八条规定的相应条件外，还应具有下列与申请的许可证类别和等级相适应的业绩： （一）申请一级至三级承装类许可证的，最近3年内应分别具有从事330（220）千伏、110（66）千伏、35千伏以下10千伏以上电压等级变（配）电及线路设施的安装活动业绩，且质量合格；在此期间从事电力设施安装业务的最高年度工程结算收入分别不少于2亿元、1亿元和3000万元； （二）申请一级至三级承修类或承试类许可证的，最近2年均应分别具有从事330(220)千伏、110(66)千伏、35千伏以下10千伏以上电压等级变（配）电及线路设施的维修或试验活动业绩。"},{"i":10,"n":"第十条","txt":"申请许可证，应当向申请人所在地的派出机构提出，并提交申请表;申请一级至三级许可证的，还需要提交相关业绩材料。"},{"i":11,"n":"第十一条","txt":"取得许可证的单位合并或分立后新设单位申请许可证的，应当提交申请表以及合并或分立相关材料。 分立后至多一个单位可承继分立前单位从事同类活动的业绩；其他新设单位同时申请该类别许可证的，按首次申请办理。"},{"i":12,"n":"第十二条","txt":"派出机构收到申请，应当对申请材料是否齐全、是否符合法定形式进行审查。派出机构有权要求申请人就申请事项作出解释或者说明。"},{"i":13,"n":"第十三条","txt":"派出机构对申请人提出的申请，应当根据下列情况分别作出处理： （一）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （二）申请材料不齐全或者不符合法定形式的，应当当场或者五日内向申请人发出申请材料补正通知书，并一次告知需要补正的全部内容； （三）申请材料齐全并符合法定形式的，或者申请人按照派出机构的要求提交全部补正申请材料的，应当向申请人发出受理通知书。"},{"i":14,"n":"第十四条","txt":"派出机构应当自受理之日起十五日内完成申请审查，并按下列规定作出是否许可的决定： （一）经审查，申请人的条件符合法定条件、标准的，派出机构应当依法作出准予许可的书面决定，并自作出决定之日起五日内向申请人颁发、送达许可证； （二）经审查，申请人的条件不符合法定条件、标准的，派出机构应当依法作出不予许可的决定，以书面形式通知申请人，通知书中应当说明不予许可的理由。"},{"i":15,"n":"第十五条","txt":"派出机构在审查过程中认为需要对申请材料的实质性内容进行核实的，应当指派两名以上的工作人员进行现场核查。"},{"i":16,"n":"第十六条","txt":"派出机构自受理通知书发出之日起十五日内不能作出决定的，经派出机构负责人批准，可以延长十日，并将延长期限的理由告知申请人。"},{"i":17,"n":"第十七条","txt":"派出机构应当按照国家有关规定建立信息公开工作制度，向社会公开承装（修、试）电力设施许可的依据、条件、程序、期限、办理情况以及申请材料目录、申请材料示范文本等信息。"},{"i":18,"n":"第十八条","txt":"许可证的变更分为许可事项变更和登记事项变更。 许可事项变更是指许可证类别和等级的变更。 登记事项变更是指承装（修、试）电力设施单位名称、住所、法定代表人等事项的变更。 变更后的许可证，有效期限不变。"},{"i":19,"n":"第十九条","txt":"申请许可事项变更，应当提交本办法第十条规定的相关材料；派出机构按照本办法第三章规定的程序予以办理。 申请增加许可证类别或者提高许可证等级的，在申请之日起前一年内未出现下列情形的，应予受理： （一）发生较大以上生产安全事故或者二次以上一般生产安全事故的； （二）发生重大质量责任事故的； （三）超越许可范围从事承装（修、试）电力设施活动的； （四）涂改、倒卖、出租、出借许可证，或者以其他形式非法转让许可证的； （五）违反国家有关规定将本单位承包的承装（修、试）电力设施业务转包或者分包的。"},{"i":20,"n":"第二十条","txt":"承装（修、试）电力设施单位名称、住所或者法定代表人发生变化的，应当自市场监督管理部门依法办理变更登记之日起三十日内，提出登记事项变更申请，并提交登记事项变更申请表。 变更后的住所与原住所属于不同派出机构管辖的，应当向变更后住所地的派出机构提出登记事项变更申请。 派出机构应当自收到登记事项变更申请之日起十日内，办理变更手续。"},{"i":21,"n":"第二十一条","txt":"许可证有效期为六年。 有效期届满需要延续的，应当在有效期届满三十日前提出申请，并提交申请表;申请一级至三级许可证有效期延续的，还应分别提供在其许可范围内的330（220）千伏以上、110（66）千以上、10千伏以上电压等级相关业绩材料。 派出机构应当在许可证有效期届满前作出是否准予延续的决定。逾期未作出决定的，视为同意延续并补办相应手续。"},{"i":22,"n":"第二十二条","txt":"许可证损毁或遗失的，应当及时向颁发许可证的派出机构申请补办，并提交下列材料： （一）许可证补办申请表； （二）损毁许可证原件或者许可证遗失声明。 派出机构应当自收到许可证补办申请之日起三日内补发许可证。"},{"i":23,"n":"第二十三条","txt":"国家能源局对派出机构实施承装（修、试）电力设施许可工作进行监督检查，及时纠正工作中的违法行为。"},{"i":24,"n":"第二十四条","txt":"派出机构依法对辖区内从事承装（修、试）电力设施活动的单位或者个人的下列事项实施监督检查： （一）依法取得许可证的情况； （二）在许可范围内从事承装（修、试）电力设施活动的情况； （三）依法使用许可证的情况； （四）符合许可证法定条件的情况； （五）遵守国家有关转包或者分包承装（修、试）电力设施业务规定的情况； （六）遵守国家其他有关规定的情况。"},{"i":25,"n":"第二十五条","txt":"承装（修、试）电力设施单位有下列情形之一的，应当按照规定向有关派出机构报送信息： （一）人员、资产等情况发生重大变化，已不符合许可证法定条件、标准的，应当自发生重大变化之日起三十日内向颁发许可证的派出机构报告； （二）解散、破产、倒闭、歇业、合并或者分立的，应当自市场监督管理部门办理相关手续之日起十日内向颁发许可证的派出机构报告； （三）发生生产安全事故的，应当按照国家有关规定向事故发生地派出机构报告； （四）发生重大质量责任事故的，应当自有关主管机关作出事故结论之日起十日内，向事故发生地派出机构报告。 前款第（三）项、第（四）项规定事项，事故发生地不属于颁发许可证的派出机构管辖的，事故发生地派出机构应当及时将有关情况通报颁发许可证的派出机构。"},{"i":26,"n":"第二十六条","txt":"派出机构对电力企业遵守承装（修、试）电力设施许可制度的情况实施监督检查。 电网企业对用户受电工程依法实施检查及竣工检验，应当查验施工企业是否具有许可证;对未经许可或者超越许可范围承揽用户受电工程的，应当立即向派出机构报告。"},{"i":27,"n":"第二十七条","txt":"派出机构履行监督检查职责，可以采取下列措施： （一）进入被检查单位的生产经营场所进行检查； （二）询问被检查单位的工作人员，要求其对有关检查事项作出说明； （三）查阅、复制与检查事项有关的文件、资料，对可能被转移、隐匿、损毁的文件、资料予以封存； （四）对与检查事项有关的业务组织技术鉴定； （五）对检查中发现的违法行为，有权当场予以纠正或者要求限期改正。 派出机构实施监督检查，被检查单位应当依法予以配合。"},{"i":28,"n":"第二十八条","txt":"国家能源局及其派出机构应按照国家关于加快构建以信用为基础的新型监管机制的要求，依法组织实施承装（修、试）电力设施单位信用监管，并与“双随机、一公开”监管相结合，采取差异化监管措施，不断提升信用监管效能。"},{"i":29,"n":"第二十九条","txt":"承装（修、试）电力设施单位的人员、资产等情况发生重大变化，已不符合相应许可证条件、标准的，派出机构应当责令其限期整改;逾期不改或整改后仍不符合许可证条件的，派出机构应根据其实际具有的条件，重新核定许可证的类别和等级。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，国家能源局及其派出机构可以依法撤销承装（修、试）电力设施许可： （一）派出机构工作人员滥用职权、玩忽职守作出准予许可决定的； （二）超越法定职权作出准予许可决定的； （三）违反法定程序作出准予许可决定的； （四）对不具备申请资格或者不符合法定条件的申请人准予许可的； （五）依法可以撤销许可的其他情形。 承装（修、试）电力设施单位以欺骗、贿赂等不正当手段取得许可的，应当予以撤销。 依照本条第一款的规定撤销许可，承装（修、试）电力设施单位的合法权益受到损害的，派出机构应当依法给予赔偿。依照本条第二款的规定撤销许可的，承装（修、试）电力设施单位基于许可取得的利益不受保护。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，派出机构应当依法办理承装（修、试）电力设施许可注销手续： （一）许可有效期届满未按照本办法规定申请延续或者延续申请未批准的； （二）承装（修、试）电力设施单位因解散、破产、倒闭、歇业、合并、分立等原因依法终止的； （三）许可依法被撤销、撤回，或者许可证被依法吊销的； （四）法律、法规规定的应当注销许可的其他情形。"},{"i":32,"n":"第三十二条","txt":"申请人隐瞒有关情况或者提供虚假申请材料申请承装（修、试）电力设施许可的，派出机构不予受理或者不予许可，并给予警告；情节严重的，一年内不再受理其许可申请。"},{"i":33,"n":"第三十三条","txt":"承装（修、试）电力设施单位采取欺骗、贿赂等不正当手段取得许可的，由派出机构撤销许可，给予警告，处一万元以上三万元以下罚款；情节严重的，三年内不再受理其许可申请；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"承装（修、试）电力设施单位转包或违法分包承装（修、试）电力设施业务，涂改、倒卖、出租、出借许可证，或者以其他形式非法转让许可证的，《建设工程质量管理条例》等法律法规对上述违法行为有相关行政处罚规定的，依照其规定执行；未作规定的，由派出机构责令其改正，给予警告，并处一万元以上三万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"违反本办法规定未取得许可证或者超越许可范围，非法从事承装、承修、承试电力设施活动的，《无证无照经营查处办法》《建设工程质量管理条例》等法律法规对上述违法行为有相关行政处罚规定的，依照其规定执行；未作规定的，由派出机构责令其停止相关经营活动，给予警告，并处一万元以上三万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"承装（修、试）电力设施单位在从事承装、承修、承试电力设施活动中发生重大以上生产安全事故或者重大质量责任事故，由派出机构依法降低许可证等级；情节严重的，依法吊销许可证。"},{"i":37,"n":"第三十七条","txt":"承装（修、试）电力设施单位未按照本办法规定办理许可证登记事项变更手续的，由派出机构责令其限期办理；逾期未办理的，处五千元以下罚款。"},{"i":38,"n":"第三十八条","txt":"电力企业违反国家有关规定，将承装（修、试）电力设施业务发包给未取得许可证或者超越许可范围承揽工程的单位或者个人的，由派出机构责令其限期改正，给予警告，并处一万元以上三万元以下罚款。 电网企业发现未取得许可证或者超越许可范围承揽用户受电工程的单位或者个人，未按照本办法规定及时报告的，由派出机构给予警告，处一万元以上三万元以下罚款。"},{"i":39,"n":"第三十九条","txt":"违反本办法第二十四条、第二十五条、第二十六条、第二十七条规定，向派出机构提供虚假或隐瞒重要事实的文件、资料，或者拒绝、阻碍派出机构及其从事监管工作的人员依法履行监管职责的，依照《电力监管条例》有关规定追究其责任。"},{"i":40,"n":"第四十条","txt":"国家能源局及其派出机构工作人员玩忽职守、滥用职权、徇私舞弊、收受贿赂的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本办法中所称“以上”、“以下”、“不低于”、“不少于”均包含本数。"},{"i":42,"n":"第四十二条","txt":"许可证由国家能源局统一印制，分为正本和副本，具有同等法律效力。"},{"i":43,"n":"第四十三条","txt":"本办法自2020年10月11日起施行。原国家电力监管委员会于2009年12月18日公布的《承装（修、试）电力设施许可证管理办法》（国家电力监管委员会令第28号）同时废止。"}],"zhaobiaogonggaohegongshixinxifabuguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范招标公告和公示信息发布活动，保证各类市场主体和社会公众平等、便捷、准确地获取招标信息，根据《中华人民共和国招标投标法》《中华人民共和国招标投标法实施条例》等有关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称招标公告和公示信息，是指招标项目的资格预审公告、招标公告、中标候选人公示、中标结果公示等信息。"},{"i":3,"n":"第三条","txt":"依法必须招标项目的招标公告和公示信息，除依法需要保密或者涉及商业秘密的内容外，应当按照公益服务、公开透明、高效便捷、集中共享的原则，依法向社会公开。"},{"i":4,"n":"第四条","txt":"国家发展改革委根据招标投标法律法规规定，对依法必须招标项目招标公告和公示信息发布媒介的信息发布活动进行监督管理。 省级发展改革部门对本行政区域内招标公告和公示信息发布活动依法进行监督管理。省级人民政府另有规定的，从其规定。"},{"i":5,"n":"第五条","txt":"依法必须招标项目的资格预审公告和招标公告，应当载明以下内容： (一)招标项目名称、内容、范围、规模、资金来源; (二)投标资格能力要求，以及是否接受联合体投标; (三)获取资格预审文件或招标文件的时间、方式; (四)递交资格预审文件或投标文件的截止时间、方式; (五)招标人及其招标代理机构的名称、地址、联系人及联系方式; (六)采用电子招标投标方式的，潜在投标人访问电子招标投标交易平台的网址和方法; (七)其他依法应当载明的内容。"},{"i":6,"n":"第六条","txt":"依法必须招标项目的中标候选人公示应当载明以下内容： (一)中标候选人排序、名称、投标报价、质量、工期(交货期)，以及评标情况; (二)中标候选人按照招标文件要求承诺的项目负责人姓名及其相关证书名称和编号; (三)中标候选人响应招标文件要求的资格能力条件; (四)提出异议的渠道和方式; (五)招标文件规定公示的其他内容。 依法必须招标项目的中标结果公示应当载明中标人名称。"},{"i":7,"n":"第七条","txt":"依法必须招标项目的招标公告和公示信息应当根据招标投标法律法规，以及国家发展改革委会同有关部门制定的标准文件编制，实现标准化、格式化。"},{"i":8,"n":"第八条","txt":"依法必须招标项目的招标公告和公示信息应当在“中国招标投标公共服务平台”或者项目所在地省级电子招标投标公共服务平台(以下统一简称“发布媒介”)发布。"},{"i":9,"n":"第九条","txt":"省级电子招标投标公共服务平台应当与“中国招标投标公共服务平台”对接，按规定同步交互招标公告和公示信息。对依法必须招标项目的招标公告和公示信息，发布媒介应当与相应的公共资源交易平台实现信息共享。 “中国招标投标公共服务平台”应当汇总公开全国招标公告和公示信息，以及本办法第八条规定的发布媒介名称、网址、办公场所、联系方式等基本信息，及时维护更新，与全国公共资源交易平台共享，并归集至全国信用信息共享平台，按规定通过“信用中国”网站向社会公开。"},{"i":10,"n":"第十条","txt":"拟发布的招标公告和公示信息文本应当由招标人或其招标代理机构盖章，并由主要负责人或其授权的项目负责人签名。采用数据电文形式的，应当按规定进行电子签名。 招标人或其招标代理机构发布招标公告和公示信息，应当遵守招标投标法律法规关于时限的规定。"},{"i":11,"n":"第十一条","txt":"依法必须招标项目的招标公告和公示信息鼓励通过电子招标投标交易平台录入后交互至发布媒介核验发布，也可以直接通过发布媒介录入并核验发布。 按照电子招标投标有关数据规范要求交互招标公告和公示信息文本的，发布媒介应当自收到起12小时内发布。采用电子邮件、电子介质、传真、纸质文本等其他形式提交或者直接录入招标公告和公示信息文本的，发布媒介应当自核验确认起1个工作日内发布。核验确认最长不得超过3个工作日。 招标人或其招标代理机构应当对其提供的招标公告和公示信息的真实性、准确性、合法性负责。发布媒介和电子招标投标交易平台应当对所发布的招标公告和公示信息的及时性、完整性负责。 发布媒介应当按照规定采取有效措施，确保发布招标公告和公示信息的数据电文不被篡改、不遗漏和至少10年内可追溯。"},{"i":12,"n":"第十二条","txt":"发布媒介应当免费提供依法必须招标项目的招标公告和公示信息发布服务，并允许社会公众和市场主体免费、及时查阅前述招标公告和公示的完整信息。"},{"i":13,"n":"第十三条","txt":"发布媒介应当通过专门栏目发布招标公告和公示信息，并免费提供信息归类和检索服务，对新发布的招标公告和公示信息作醒目标识，方便市场主体和社会公众查阅。 发布媒介应当设置专门栏目，方便市场主体和社会公众就其招标公告和公示信息发布工作反映情况、提出意见，并及时反馈。"},{"i":14,"n":"第十四条","txt":"发布媒介应当实时统计本媒介招标公告和公示信息发布情况，及时向社会公布，并定期报送相应的省级以上发展改革部门或省级以上人民政府规定的其他部门。"},{"i":15,"n":"第十五条","txt":"依法必须招标项目的招标公告和公示信息除在发布媒介发布外，招标人或其招标代理机构也可以同步在其他媒介公开，并确保内容一致。 其他媒介可以依法全文转载依法必须招标项目的招标公告和公示信息，但不得改变其内容，同时必须注明信息来源。"},{"i":16,"n":"第十六条","txt":"依法必须招标项目的招标公告和公示信息有下列情形之一的，潜在投标人或者投标人可以要求招标人或其招标代理机构予以澄清、改正、补充或调整： (一)资格预审公告、招标公告载明的事项不符合本办法第五条规定，中标候选人公示载明的事项不符合本办法第六条规定; (二)在两家以上媒介发布的同一招标项目的招标公告和公示信息内容不一致; (三)招标公告和公示信息内容不符合法律法规规定。 招标人或其招标代理机构应当认真核查，及时处理，并将处理结果告知提出意见的潜在投标人或者投标人。"},{"i":17,"n":"第十七条","txt":"任何单位和个人认为招标人或其招标代理机构在招标公告和公示信息发布活动中存在违法违规行为的，可以依法向有关行政监督部门投诉、举报;认为发布媒介在招标公告和公示信息发布活动中存在违法违规行为的，根据有关规定可以向相应的省级以上发展改革部门或其他有关部门投诉、举报。"},{"i":18,"n":"第十八条","txt":"招标人或其招标代理机构有下列行为之一的，由有关行政监督部门责令改正，并视情形依照《中华人民共和国招标投标法》第四十九条、第五十一条及有关规定处罚： (一)依法必须公开招标的项目不按照规定在发布媒介发布招标公告和公示信息; (二)在不同媒介发布的同一招标项目的资格预审公告或者招标公告的内容不一致，影响潜在投标人申请资格预审或者投标; (三)资格预审公告或者招标公告中有关获取资格预审文件或者招标文件的时限不符合招标投标法律法规规定; (四)资格预审公告或者招标公告中以不合理的条件限制或者排斥潜在投标人。"},{"i":19,"n":"第十九条","txt":"发布媒介在发布依法必须招标项目的招标公告和公示信息活动中有下列情形之一的，由相应的省级以上发展改革部门或其他有关部门根据有关法律法规规定，责令改正;情节严重的，可以处1万元以下罚款： (一)违法收取费用; (二)无正当理由拒绝发布或者拒不按规定交互信息; (三)无正当理由延误发布时间; (四)因故意或重大过失导致发布的招标公告和公示信息发生遗漏、错误; (五)违反本办法的其他行为。 其他媒介违规发布或转载依法必须招标项目的招标公告和公示信息的，由相应的省级以上发展改革部门或其他有关部门根据有关法律法规规定，责令改正;情节严重的，可以处1万元以下罚款。"},{"i":20,"n":"第二十条","txt":"对依法必须招标项目的招标公告和公示信息进行澄清、修改，或者暂停、终止招标活动，采取公告形式向社会公布的，参照本办法执行。"},{"i":21,"n":"第二十一条","txt":"使用国际组织或者外国政府贷款、援助资金的招标项目，贷款方、资金提供方对招标公告和公示信息的发布另有规定的，适用其规定。"},{"i":22,"n":"第二十二条","txt":"本办法所称以上、以下包含本级或本数。"},{"i":23,"n":"第二十三条","txt":"本办法由国家发展改革委负责解释。"},{"i":24,"n":"第二十四条","txt":"本办法自2018年1月1日起施行。《招标公告发布暂行办法》(国家发展计划委第4号令)和《国家计委关于指定发布依法必须招标项目招标公告的媒介的通知》(计政策〔2000〕868号)同时废止。"}],"zhaobiaotoubiaolingyuxinyongguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为加强和规范招标投标领域信用管理，维护公平竞争、诚实守信的市场秩序，促进全国统一大市场建设，根据《中华人民共和国招标投标法》《中华人民共和国招标投标法实施条例》《国务院办公厅印发〈关于建立企业信用状况综合评价体系的实施方案〉的通知》（国办发〔2026〕8号）等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于招标人、投标人、招标代理机构和评标专家在招标投标领域的公共信用信息归集、共享、公示、查询、应用，以及公共信用评价和评价结果应用等活动。 本办法所称招标投标领域公共信用信息，是指招标投标行政监督部门、司法机关等依法产生和获取，能够反映招标投标活动中招标人、投标人、招标代理机构和评标专家信用状况的信息，包括登记注册基本信息、司法裁判及执行信息、行政管理信息、经营（活动）异常名录信息、严重失信主体名单信息、公共信用评价结果信息等。"},{"i":3,"n":"第三条","txt":"招标投标领域信用管理遵循依法合规、统一分类、公正平等、信息共享的原则。"},{"i":4,"n":"第四条","txt":"国家发展改革委指导和协调全国招标投标领域信用管理工作。国务院工业和信息化、住房城乡建设、交通运输、水利、农业农村、商务、广电、能源、铁路、民航等部门按照职责分工，负责组织实施本行业的招标投标领域公共信用信息归集、共享、公示、查询、应用，公共信用评价和评价结果应用，以及相关监督管理工作。 县级以上地方招标投标指导协调部门负责指导和协调本行政区域内招标投标领域信用管理工作。县级以上地方招标投标行政监督部门在各自职责范围内，负责组织实施招标投标领域公共信用信息归集、共享、公示、查询、应用，公共信用评价结果应用，以及相关监督管理工作。"},{"i":5,"n":"第五条","txt":"国家发展改革委依照《全国公共信用信息基础目录》，合理确定招标投标领域公共信用信息范围，以及具体的信息类别、归集共享内容、信息产生单位、归集共享依据等。"},{"i":6,"n":"第六条","txt":"各级招标投标行政监督部门对其产生的招标人、投标人、招标代理机构、评标专家的招标投标领域公共信用信息，应当按照全国统一的数据规范进行标注，自信息产生之日起二十个工作日内归集至全国信用信息共享平台。 信用信息共享平台、公共资源交易平台、招标投标行政监督部门有关业务系统应当加强互联互通，提升信息共享质量和时效性。"},{"i":7,"n":"第七条","txt":"“信用中国”网站集中公示招标人、投标人、招标代理机构的招标投标领域公共信用信息，以及其来源、依据、记录时间等。全国公共资源交易平台网站集中公示评标专家依法被取消评标资格的行政处罚信息，以及其来源、依据、记录时间等。 国务院招标投标行政监督部门可以通过门户网站、行业信息平台等渠道，公示本行业的招标投标领域公共信用信息。"},{"i":8,"n":"第八条","txt":"依法必须进行招标的项目应当查询、应用招标投标领域公共信用信息。 “信用中国”网站按照公益性原则提供招标投标领域公共信用信息查询服务，并向公共资源交易平台提供信息调用接口。公共资源交易平台应当加强技术保障，为招标投标活动提供公共信用信息查询服务。"},{"i":9,"n":"第九条","txt":"依法必须进行招标的项目，招标人、评标委员会通过“信用中国”网站或者公共资源交易平台，查询投标人的招标投标领域公共信用信息；发现下列信息的，评标委员会应当依法否决其投标，招标人也不得将其确定为中标人： （一）串通投标、以行贿手段谋取中标，受到取消一定期限内投标资格的行政处罚且期限尚未届满； （二）以他人名义投标或者以其他方式弄虚作假骗取中标，受到取消一定期限内投标资格的行政处罚且期限尚未届满； （三）不按照与招标人订立的合同履行义务，受到取消一定期限内投标资格的行政处罚且期限尚未届满； （四）依法被列为失信被执行人； （五）法律、行政法规或者国务院规定的其他应当否决投标的信息。 投标人公共信用信息查询情况应当纳入招标投标资料，随招标投标情况书面报告一并提交有关行政监督部门。"},{"i":10,"n":"第十条","txt":"依法必须进行招标的项目，招标人拟委托招标代理机构开展招标代理业务的，通过“信用中国”网站查询招标代理机构的招标投标领域公共信用信息；发现下列信息的，招标人不得委托其开展招标代理业务： （一）泄露应当保密的与招标投标活动有关的情况和资料，受到禁止一定期限内从事招标代理业务的行政处罚且期限尚未届满； （二）与招标人、投标人串通损害国家利益、社会公共利益或者他人合法权益，受到禁止一定期限内从事招标代理业务的行政处罚且期限尚未届满； （三）通过向招标人有关工作人员行贿、提供回扣或者给予其他不正当利益等手段承接招标代理业务，受到禁止一定期限内从事招标代理业务的行政处罚且期限尚未届满； （四）在所代理的招标项目中投标、代理投标，受到禁止一定期限内从事招标代理业务的行政处罚且期限尚未届满； （五）向评标专家行贿，或者引导评标专家作出倾向或者排斥特定投标人的评标意见，受到禁止一定期限内从事招标代理业务"},{"i":11,"n":"第十一条","txt":"国务院有关部门评标专家库或者省级综合评标专家库（以下简称“评标专家库”）组建单位选聘评标专家时，应当核验拟聘任专家的招标投标领域公共信用信息；存在下列信息的，不得聘任其为评标专家： （一）受到取消担任评标委员会成员资格的行政处罚； （二）依法依规被列入严重失信主体名单； （三）法律、行政法规或者国务院规定的其他不得担任评标委员会成员的信息。"},{"i":12,"n":"第十二条","txt":"在库评标专家存在下列信息的，评标专家库组建单位应当与其解除聘任关系，调整出库，通报入库推荐单位，并向社会公开： （一）应当回避而不回避，受到取消担任评标委员会成员资格的行政处罚； （二）与招标人、招标代理机构、投标人或者其他利害关系人私下接触或者相互串通，受到取消担任评标委员会成员资格的行政处罚； （三）向招标人征询确定中标人的意向，或者接受任何单位、个人提出的倾向、排斥特定投标人要求，受到取消担任评标委员会成员资格的行政处罚； （四）暗示或者诱导投标人作出澄清、说明，或者接受投标人主动提出的澄清、说明，受到取消担任评标委员会成员资格的行政处罚； （五）对其他评标委员会成员的独立评标施加不当影响，受到取消担任评标委员会成员资格的行政处罚； （六）违法透露对投标文件的评审和比较、中标候选人的推荐以及与评标有关的其他情况，受到取消担任评标委员会成员资格的行政处罚； （七）索取或者收受评标劳"},{"i":13,"n":"第十三条","txt":"招标人、投标人、招标代理机构按照《信用修复管理办法》（国家发展改革委令2025年第36号）完成信用修复的，不再公示相关招标投标领域公共信用信息。 对附带期限的行政处罚，在行政处罚期限届满前，不得提前终止公示。"},{"i":14,"n":"第十四条","txt":"招标人、投标人、招标代理机构认为“信用中国”网站对其招标投标领域公共信用信息公示有误的，通过“信用中国”网站向信息产生部门提出申诉。有关部门应当在收到申诉的七个工作日内向“信用中国”网站反馈申诉处理结果，“信用中国”网站及时更新信息。 评标专家认为全国公共资源交易平台网站对其行政处罚信息公示有误的，通过全国公共资源交易平台网站向信息产生部门提出申诉。有关部门应当在收到申诉的七个工作日内向全国公共资源交易平台网站反馈申诉处理结果，全国公共资源交易平台网站及时更新信息。"},{"i":15,"n":"第十五条","txt":"各级信用信息共享平台、公共资源交易平台运行服务机构及其工作人员应当加强信用信息安全保护，不得泄露、篡改、窃取、毁损招标投标领域公共信用信息，不得利用公共信用信息谋取非法利益。"},{"i":16,"n":"第十六条","txt":"国务院招标投标行政监督部门遵循公益性原则，对招标人、投标人、招标代理机构开展公共信用评价，反映相关主体遵守法律法规和管理规定等情况。 国务院招标投标行政监督部门应当确定本行业全国统一的公共信用评价规则，明确评价指标、评价方法、评价流程、评价周期、等级分类、结果应用等事项，并向社会公开。国务院招标投标行政监督部门暂未开展本行业公共信用评价的，可以参考使用公共信用综合评价规则，建立本行业的公共信用评价规则。"},{"i":17,"n":"第十七条","txt":"开展公共信用评价应当平等对待各类企业，不得实施下列评价行为： （一）根据不同地区、所有制形式、规模等设置差异化得分； （二）将业绩、市场占有率等不能反映企业信用状况的信息纳入信用评价范围； （三）在信用评价中设置无上限加分项； （四）其他违规设置交易壁垒的评价行为。"},{"i":18,"n":"第十八条","txt":"国务院招标投标行政监督部门应当及时向社会公布本行业的公共信用评价结果，并同步共享至全国信用信息共享平台，通过“信用中国”网站公示。"},{"i":19,"n":"第十九条","txt":"国务院招标投标行政监督部门应当建立本行业公共信用评价异议申诉机制，明确异议申诉的渠道和程序，并向社会公开。 被评价对象对评价结果有异议的，按照国务院招标投标行政监督部门公布的渠道和程序，提出异议申诉。有关招标投标行政监督部门应当及时处理异议申诉申请，经核实符合申诉条件的，及时更正有关内容。"},{"i":20,"n":"第二十条","txt":"地方招标投标指导协调部门、行政监督部门不得自行开展对招标人、投标人、招标代理机构的招标投标领域信用评价。"},{"i":21,"n":"第二十一条","txt":"鼓励招标人在下列环节应用公共信用评价结果： （一）设置评标标准（资格审查标准）、定标规则； （二）确定投标保证金、履约保证金缴纳机制； （三）核验中标候选人履约能力； （四）确定预付款比例和进度款支付比例； （五）其他需要衡量投标人、潜在投标人公共信用状况的环节。 招标人在前款所列环节应用公共信用评价结果的，应当在招标文件（资格预审文件）中载明。 国务院招标投标行政监督部门可以结合本行业实际，对招标人在评标标准（资格审查标准）中设置公共信用评价结果权重的上限提出要求。 除法律、行政法规或者国务院另有规定外，招标投标指导协调部门、行政监督部门不得限制招标人应用公共信用评价结果的自主权。"},{"i":22,"n":"第二十二条","txt":"银行、担保机构或者保险机构可以在出具投标、履约保函（保单）前，查询投标人、中标人的公共信用评价结果，并根据公共信用评价结果采用差异化保函（保单）费率。"},{"i":23,"n":"第二十三条","txt":"各级招标投标行政监督部门应当根据招标人、投标人、招标代理机构的公共信用评价结果，实施差异化监管，提高或者降低抽查比例和检查频次，并可以实施告知承诺制、优先办理、简化程序、简化证明材料等便利服务措施。"},{"i":24,"n":"第二十四条","txt":"招标人应用公共信用评价结果，应当符合招标项目实际需要，不得实施下列行为： （一）在资格审查、评标、定标中，将信用评价结果作为唯一条件，或者赋予不合理权重； （二）区别对待不同地区、所有制形式、规模的企业的同一等级信用评价结果； （三）其他违规应用信用评价结果，限制、排斥潜在投标人或者投标人的行为。"},{"i":25,"n":"第二十五条","txt":"省级招标投标指导协调部门会同行政监督部门，可以对本地区政府投资项目在招标文件编制、中标候选人履约能力核验等环节，应用公共信用评价结果作出细化规定，但不得与国务院招标投标行政监督部门的公共信用评价规则相冲突，不得区别对待不同地区、所有制形式、规模的企业。 各级招标投标指导协调部门会同行政监督部门，对公共信用评价和具体应用情况进行动态监测，畅通企业、社会公众问题反映渠道，及时纠正违法信用评价和应用活动。"},{"i":26,"n":"第二十六条","txt":"评标专家库组建单位结合日常管理需要，可以参照本办法第十六条、第十八条、第十九条、第二十三条，对评标专家开展信用评价和评价结果应用。评标专家库组建单位开展评价的，应当公开评价规则，及时向被评价对象反馈评价结果，畅通异议申诉渠道，并根据评价结果，采取下列差异化管理措施： （一）对信用等级较高的评标专家，在保证抽取随机性、公正性的前提下，适当提高抽取概率； （二）对信用等级较低的评标专家，加强履职风险评估，并视情采取降低抽取频次、暂停抽取等措施； （三）其他应用信用评价结果的管理措施。"},{"i":27,"n":"第二十七条","txt":"依法必须进行招标的项目，招标人违反本办法第九条、第十条规定，未按要求查询和应用招标投标领域公共信用信息的，由有关招标投标行政监督部门责令改正，可以处十万元以下的罚款。 前款所列行为影响中标结果的，中标无效，应当依法重新招标。"},{"i":28,"n":"第二十八条","txt":"依法必须进行招标的项目，评标委员会成员违反本办法第九条规定，未按要求查询和应用招标投标领域公共信用信息的，依照《中华人民共和国招标投标法》和《中华人民共和国招标投标法实施条例》关于对依法应当否决的投标不提出否决意见的追责条款，责令改正，并可以依法给予禁止在一定期限内评标、取消担任评标委员会成员资格等行政处罚。 前款所列行为影响中标结果的，中标无效，应当依法重新招标或者评标。"},{"i":29,"n":"第二十九条","txt":"招标人违反本办法第二十四条规定，在公共信用评价结果应用中限制、排斥潜在投标人或者投标人的，依照《中华人民共和国招标投标法》和《中华人民共和国招标投标法实施条例》关于对限制、排斥潜在投标人或者投标人的追责条款，责令改正，并可以依法给予罚款等行政处罚。"},{"i":30,"n":"第三十条","txt":"招标投标行政监督部门违反本办法，归集共享招标投标领域公共信用信息不及时、不准确、不完整的，由其上级机关责令改正；造成严重后果的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":31,"n":"第三十一条","txt":"招标投标指导协调部门、行政监督部门或者其他单位非法干预企业自主应用公共信用评价结果的，由其上级机关责令改正；对负有责任的领导人员和直接责任人员，依照《中华人民共和国招标投标法》和《中华人民共和国招标投标法实施条例》关于对非法干涉招标投标活动的追责条款予以处理。"},{"i":32,"n":"第三十二条","txt":"招标投标指导协调部门、行政监督部门或者其他单位违反本办法，弄虚作假、徇私舞弊、滥用职权的，由其上级机关责令改正，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"招标投标领域公共信用信息的发布、维护单位及其工作人员违反本办法，在信用信息的归集、共享、公示过程中弄虚作假、徇私舞弊的，由其主管部门责令改正，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"本办法规定的招标投标领域公共信用信息主要包括下列类别： （一）登记注册基本信息，指企业名称、统一社会信用代码、成立日期等； （二）司法裁判及执行信息，指企业破产案件审判流程节点信息、破产程序中人民法院发布的各类公告、人民法院制作的破产程序法律文书等； （三）行政管理信息，指招标投标行政监督部门依法作出的企业资质、人员资格等行政许可信息，以及依据招标投标相关法律法规作出的行政处罚信息等； （四）经营（活动）异常名录信息，指企业被依法纳入或者移出经营异常名录等信息； （五）严重失信主体名单信息，指招标人、投标人、招标代理机构和评标专家依法依规被列入严重失信主体名单的信息； （六）公共信用评价结果信息，指招标投标行政监督部门产生的公共信用评价结果。"},{"i":35,"n":"第三十五条","txt":"招标投标领域市场化信用评价依照《国务院办公厅印发〈关于建立企业信用状况综合评价体系的实施方案〉的通知》（国办发〔2026〕8号）等国家有关规定执行。"},{"i":36,"n":"第三十六条","txt":"本办法由国家发展改革委会同工业和信息化部、住房城乡建设部、交通运输部、水利部、农业农村部、商务部、广电总局负责解释。"},{"i":37,"n":"第三十七条","txt":"本办法自2027年1月1日起施行。"}],"zhaobiaotoubiaolingyugongpingjingzhengshenchaguize":[{"i":1,"n":"第一条","txt":"为加强和规范招标投标领域公平竞争审查，维护公平竞争市场秩序，根据《中华人民共和国招标投标法》《中华人民共和国招标投标法实施条例》等有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"招标投标领域公平竞争审查工作，适用本规则。"},{"i":3,"n":"第三条","txt":"本规则所称公平竞争审查，是指行政机关和法律、法规授权的具有管理公共事务职能的组织（以下统称政策制定机关）对拟制定的招标投标领域涉及经营主体经济活动的规章、行政规范性文件、其他政策性文件以及具体政策措施（以下统称政策措施）是否存在排除、限制竞争情形进行审查评估的活动。 除法律、行政法规或者国务院规定的公平竞争审查例外情形，未经公平竞争审查或者经审查存在排除、限制竞争情形的，不得出台有关政策措施。"},{"i":4,"n":"第四条","txt":"政策制定机关履行公平竞争审查职责。政策制定机关应当确定专门机构具体负责政策措施的公平竞争审查工作。 多个部门联合制定政策措施的，由牵头部门组织开展公平竞争审查，各参与部门对职责范围内的政策措施负责。"},{"i":5,"n":"第五条","txt":"政策制定机关应当尊重和保障招标人组织招标、选择招标代理机构、编制资格预审文件和招标文件的自主权，不得制定以下政策措施： （一）为招标人指定招标代理机构或者违法限定招标人选择招标代理机构的方式； （二）为招标人指定投标资格、技术、商务条件； （三）为招标人指定特定类型的资格审查方法或者评标方法； （四）为招标人指定具体的资格审查标准或者评标标准； （五）为招标人指定评标委员会成员； （六）对于已经纳入统一的公共资源交易平台体系的电子交易系统，限制招标人自主选择； （七）强制招标人或者招标代理机构选择电子认证服务； （八）为招标人或者招标代理机构指定特定交易工具； （九）为招标人指定承包商（供应商）预选库、资格库或者备选名录等； （十）要求招标人依照本地区创新产品名单、优先采购产品名单等地方性扶持政策开展招标投标活动； （十一）以其他不合理条件限制招标人自主权的政策措施。"},{"i":6,"n":"第六条","txt":"政策制定机关应当落实全国统一的市场准入条件，对经营主体参与投标活动，不得制定以下政策措施： （一）对市场准入负面清单以外的行业、领域、业务，要求经营主体在参与投标活动前取得行政许可； （二）要求经营主体在本地区设立分支机构、缴纳税收社保或者与本地区经营主体组成联合体； （三）要求经营主体取得本地区业绩或者奖项； （四）要求经营主体取得培训合格证、上岗证等特定地区或者特定行业组织颁发的相关证书； （五）要求经营主体取得特定行业组织成员身份； （六）以其他不合理条件限制经营主体参与投标的政策措施。"},{"i":7,"n":"第七条","txt":"政策制定机关制定标准招标文件（示范文本）和标准资格预审文件（示范文本），应当平等对待不同地区、所有制形式的经营主体，不得在标准招标文件（示范文本）和标准资格预审文件（示范文本）中设置以下内容： （一）根据经营主体取得业绩的区域设置差异性得分； （二）根据经营主体的所有制形式设置差异性得分； （三）根据经营主体投标产品的产地设置差异性得分； （四）根据经营主体的规模、注册地址、注册资金、市场占有率、负债率、净资产规模等设置差异性得分； （五）根据联合体成员单位的注册地址、所有制形式等设置差异性得分； （六）其他排除或者限制竞争的内容。"},{"i":8,"n":"第八条","txt":"政策制定机关制定定标相关政策措施，应当尊重和保障招标人定标权，落实招标人定标主体责任，不得制定以下政策措施： （一）为招标人指定定标方法； （二）为招标人指定定标单位或者定标人员； （三）将定标权交由招标人或者其授权的评标委员会以外的其他单位或者人员行使； （四）规定直接以抽签、摇号、抓阄等方式确定合格投标人、中标候选人或者中标人； （五）以其他不合理条件限制招标人定标权的政策措施。"},{"i":9,"n":"第九条","txt":"政策制定机关可以通过组织开展信用评价引导经营主体诚信守法参与招标投标活动，并可以通过制定实施相应政策措施鼓励经营主体应用信用评价结果，但应当平等对待不同地区、所有制形式的经营主体，依法保障经营主体自主权，不得制定以下政策措施： （一）在信用信息记录、归集、共享等方面对不同地区或者所有制形式的经营主体作出区别规定； （二）对不同地区或者所有制形式经营主体的资质、资格、业绩等采用不同信用评价标准； （三）根据经营主体的所在地区或者所有制形式采取差异化的信用监管措施； （四）没有法定依据，限制经营主体参考使用信用评价结果的自主权； （五）其他排除限制竞争或者损害经营主体合法权益的政策措施。"},{"i":10,"n":"第十条","txt":"政策制定机关制定涉及招标投标交易监管和服务的政策措施，应当平等保障各类经营主体参与，不得在交易流程上制定以下政策措施： （一）规定招标投标交易服务机构行使审批、备案、监管、处罚等具有行政管理性质的职能； （二）强制非公共资源交易项目进入公共资源交易平台交易； （三）对能够通过告知承诺和事后核验核实真伪的事项，强制投标人在投标环节提供原件； （四）在获取招标文件、开标环节违法要求投标人的法定代表人、技术负责人、项目负责人或者其他特定人员到场； （五）其他不当限制经营主体参与招标投标的政策措施。"},{"i":11,"n":"第十一条","txt":"政策制定机关制定涉及保证金的政策措施，不得设置以下不合理限制： （一）限制招标人依法收取保证金； （二）要求经营主体缴纳除投标保证金、履约保证金、工程质量保证金、农民工工资保证金以外的其他保证金； （三）限定经营主体缴纳保证金的形式； （四）要求经营主体从特定机构开具保函（保险）； （五）在招标文件之外设定保证金退还的前置条件； （六）其他涉及保证金的不合理限制措施。"},{"i":12,"n":"第十二条","txt":"政策制定机关应当建立本机关公平竞争审查工作机制，明确公平竞争审查负责机构、审查标准和审查流程，规范公平竞争审查行为。"},{"i":13,"n":"第十三条","txt":"政策措施应当在提请审议或者报批前完成公平竞争审查。 政策制定机关应当作出符合或者不符合审查标准的书面审查结论。适用有关法律、行政法规或者国务院规定的公平竞争审查例外情形的，应当在审查结论中说明理由。"},{"i":14,"n":"第十四条","txt":"政策制定机关在对政策措施开展公平竞争审查过程中，应当以适当方式听取有关经营主体、行业协会商会等意见；除依法保密外，应当向社会公开征求意见。 在起草政策措施的其他环节已经向社会公开征求意见或者征求过有关方面意见的，可以不再专门就公平竞争审查征求意见。"},{"i":15,"n":"第十五条","txt":"政策制定机关可以委托第三方机构对拟出台政策措施的公平竞争影响、已出台政策措施的竞争效果和本地区招标投标公平竞争审查制度总体实施情况、市场竞争状况等开展评估。"},{"i":16,"n":"第十六条","txt":"地方各级招标投标指导协调部门会同招标投标行政监督部门，应当定期组织开展政策措施评估，发现违反公平竞争审查有关规定的，应当及时纠正。"},{"i":17,"n":"第十七条","txt":"公民、法人或者其他组织认为政策措施妨碍公平竞争的，有权向政策制定机关及其上一级机关反映。 地方各级招标投标指导协调部门、招标投标行政监督部门应当建立招标投标市场壁垒线索征集机制，动态清理废止各类有违公平竞争的政策措施。"},{"i":18,"n":"第十八条","txt":"公民、法人或者其他组织认为资格预审文件、招标文件存在排斥、限制潜在投标人不合理条件的，有权依照《招标投标法》及其实施条例相关规定提出异议和投诉。招标投标行政监督部门、招标人应当按照规定程序处理。"},{"i":19,"n":"第十九条","txt":"政策制定机关未进行公平竞争审查或者违反审查标准出台政策措施的，由上级机关责令改正；拒不改正或者不及时改正的，对直接负责的主管人员和其他相关责任人员依照《中华人民共和国公职人员政务处分法》第三十九条、《中华人民共和国公务员法》第六十一条等有关规定依法给予处分。"},{"i":20,"n":"第二十条","txt":"政策制定机关作为招标人编制招标公告、资格预审文件和招标文件，以及公共资源交易平台运行服务机构制定招标投标交易服务文件，应当参照本规则开展公平竞争审查。"},{"i":21,"n":"第二十一条","txt":"本规则由国家发展改革委会同有关部门负责解释。"},{"i":22,"n":"第二十二条","txt":"本规则自2024年5月1日起施行。"}],"zhengfuzhidingjiagetingzhengbanfa":[{"i":1,"n":"第一条","txt":"为规范政府制定价格听证行为，提高政府制定价格的民主性、科学性和透明度，根据《中华人民共和国价格法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称政府制定价格听证(以下简称定价听证)，是指定价机关依法制定(含调整，下同)政府指导价、政府定价的价格水平或者定价机制过程中，由政府价格主管部门采取听证会形式，征求经营者、消费者和有关方面的意见，对制定价格的必要性、可行性、合理性进行论证的活动。 前款所称定价机关，包括有定价权的省、自治区、直辖市(以下统称省级)以上人民政府价格主管部门、有关部门和经省级人民政府授权的市、县人民政府。 前款所称定价机制，是指与列入定价听证目录的定价项目价格水平确定直接相关的定价办法、公式等。"},{"i":3,"n":"第三条","txt":"制定关系群众切身利益的公用事业价格、公益性服务价格和自然垄断经营的商品和服务价格等政府指导价、政府定价的价格水平，应当实行定价听证。 制定定价机制，应当实行定价听证或者公开征求社会意见。依据已经生效实施的定价机制制定具体价格水平时，可以不再开展定价听证。 听证的具体项目通过定价听证目录确定，容易引发抢购、囤积，造成市场异常波动的商品价格，通过其他方式征求意见，不纳入定价听证目录。 定价听证目录是指由省级以上人民政府价格主管部门依据政府定价目录制定的应当经定价听证的商品和服务清单。定价听证目录应当在听取社会意见的基础上制定、修订并及时公布。法律、法规、规章规定实行定价听证的项目自动进入定价听证目录。 制定定价听证目录以外的政府指导价、政府定价，定价机关认为有必要的，也可以实行定价听证。"},{"i":4,"n":"第四条","txt":"定价听证应当遵循公开、公平、公正、效率的原则。"},{"i":5,"n":"第五条","txt":"听证会应当公开举行，允许旁听和新闻报道，但涉及国家秘密或者商业秘密的除外。 政府价格主管部门可以通过互联网以视频或者文字、图片形式公开听证会内容。"},{"i":6,"n":"第六条","txt":"定价听证由政府价格主管部门组织。 省级以上定价机关制定价格需要听证的，由同级政府价格主管部门组织听证。 省级人民政府授权市、县人民政府制定价格的，由市、县人民政府价格主管部门组织听证。 制定在局部地区执行的价格需要听证的，政府价格主管部门可以委托下级政府价格主管部门组织听证。委托听证的，应当出具书面委托书并予以监督指导。"},{"i":7,"n":"第七条","txt":"政府价格主管部门可以通过政府购买服务等方式，由第三方机构参与定价听证的组织工作。 前款所称第三方机构，是指政府价格主管部门、定价机关、与听证事项直接相关的经营者及其主管单位以外的机构，包括但不限于科研机构、咨询机构等企事业单位和社会组织。"},{"i":8,"n":"第八条","txt":"听证会设听证人，代表政府价格主管部门专门听取听证会意见。 听证人由政府价格主管部门工作人员、定价机关工作人员，以及政府价格主管部门聘请的社会知名人士、专业人士担任。听证会主持人由听证人中的政府价格主管部门的工作人员兼任。 听证人不得少于三人，具体人数及人员构成由政府价格主管部门确定。"},{"i":9,"n":"第九条","txt":"听证人履行下列职责： (一)听取听证会参加人的意见陈述，并可以询问; (二)提出听证报告。"},{"i":10,"n":"第十条","txt":"听证会参加人由下列人员构成： (一)消费者; (二)经营者; (三)与定价听证项目有关的其他利益相关方; (四)相关领域的专家、学者; (五)政府价格主管部门认为有必要参加听证会的政府部门、社会组织和其他人员。鼓励消费者组织参加听证会。 听证会参加人的人数和人员的构成比例由政府价格主管部门根据听证项目的实际情况确定，其中消费者人数不得少于听证会参加人总数的五分之二。"},{"i":11,"n":"第十一条","txt":"听证会参加人由下列方式产生： (一)消费者采取自愿报名、随机选取和消费者组织或者其他群众组织推荐相结合的方式; (二)经营者、与定价听证项目有关的其他利益相关方采取自愿报名、随机选取方式，也可以由政府价格主管部门委托行业组织、政府主管部门推荐; (三)专家、学者、政府部门、社会组织和其他人员由政府价格主管部门聘请。 随机选取可以结合定价听证项目的特点，根据不同职业、行业、地域等，合理设置类别并分配名额。 政府价格主管部门可以根据听证项目的实际情况规定听证会参加人条件。 定价机关、听证组织部门的工作人员及其近亲属不得担任听证会参加人。"},{"i":12,"n":"第十二条","txt":"听证会参加人的权利和义务： (一)可以向有关经营者、行业组织、政府主管部门了解与听证事项相关的情况; (二)出席听证会，就听证事项发表意见、阐明理由; (三)保守国家秘密和商业秘密，遵守听证会纪律; (四)因特殊原因不能出席的，应当提前3个工作日告知听证组织部门，同时提交书面意见。"},{"i":13,"n":"第十三条","txt":"听证会设记录员。记录员由政府价格主管部门指定的人员担任，如实记录听证会参加人的意见。"},{"i":14,"n":"第十四条","txt":"公开举行的听证会设旁听席。旁听人员由政府价格主管部门根据公民、法人或者其他组织报名情况以及场地情况，确定人数并按照报名顺序选取或者随机抽取。 旁听人员对定价方案有意见的，可以在听证会结束后以书面形式向听证组织部门提出。旁听人员不得在听证会现场发言、提问，不得有妨碍听证秩序的行为。"},{"i":15,"n":"第十五条","txt":"公开举行的听证会设记者席。与会采访的新闻媒体由政府价格主管部门根据新闻媒体报名情况，按照报名顺序选取或者随机抽取。政府价格主管部门可以邀请新闻媒体采访听证会。"},{"i":16,"n":"第十六条","txt":"参与听证会的人员应当遵守宪法和法律法规、遵守公共秩序、尊重社会公德，不得使用不文明用语，不得进行恶意攻击以及有组织的言论煽动，不得恶意片面传播听证发言内容，不得编造、传播虚假信息扰乱经济秩序和社会秩序，不得发表与定价方案无关的内容。"},{"i":17,"n":"第十七条","txt":"定价听证依据下列情况提起： (一)定价机关是政府价格主管部门的，由政府价格主管部门提起; (二)定价机关是其他部门的，由该部门向同级政府价格主管部门提起; (三)定价机关是多个部门的，由牵头部门向同级政府价格主管部门提起; (四)定价机关是市、县人民政府的，由负责具体定价工作的市、县政府价格主管部门提起，或者由负责具体定价工作的市、县政府有关部门向同级政府价格主管部门提起。"},{"i":18,"n":"第十八条","txt":"定价机关提起定价听证时，应当向政府价格主管部门提交定价方案、与制定价格有关的定价成本监审报告或者成本调查报告，以及经营者按要求公开成本信息的情况、其他相关信息资料。 定价机关和经营者应当确保所提供资料的完整、真实和准确性。"},{"i":19,"n":"第十九条","txt":"定价方案应当包括下列内容： (一)拟制定价格水平或者定价机制的具体项目; (二)现行价格和拟制定的价格水平，单位调价额和调价幅度; (三)拟制定的定价机制主要内容、适用条件; (四)拟制定价格水平或者定价机制的依据和理由; (五)拟制定价格水平或者定价机制对经济、社会影响的分析; (六)其他与制定价格水平或者定价机制有关的资料。"},{"i":20,"n":"第二十条","txt":"听证会举行30日前，政府价格主管部门应当通过政府网站、新闻媒体向社会公告以下事项： (一)定价听证事项; (二)听证会举行的时间; (三)听证会参加人、旁听人员、新闻媒体的名额、产生方式及具体报名办法。 拟对听证会进行网络公开的，应当一并公告。"},{"i":21,"n":"第二十一条","txt":"听证会举行15日前，政府价格主管部门应当通过政府网站、新闻媒体向社会公告以下事项： (一)听证会举行的时间、地点; (二)定价方案; (三)与制定价格有关的成本监审或者成本调查的办法和结论; (四)听证人、听证会参加人、旁听人员名单，包括姓名、职业。 听证会同时网络公开的，应当一并公告网址及时间。 第三方机构参与定价听证的组织工作的，应当公布第三方机构的基本信息。 听证会因故取消或推迟举行的，政府价格主管部门应当向社会公告并作出说明。"},{"i":22,"n":"第二十二条","txt":"听证会举行15日前，政府价格主管部门应当向听证会参加人送达下列材料： (一)听证会通知; (二)定价方案; (三)与制定价格有关的成本监审或者成本调查报告; (四)听证会议程; (五)听证会纪律。"},{"i":23,"n":"第二十三条","txt":"听证会应当在有三分之二以上听证会参加人出席且消费者人数不少于实际出席人数五分之二时举行;出席人数不足或者消费者人数不足的，听证会应当延期举行。"},{"i":24,"n":"第二十四条","txt":"听证会可以一次举行，也可以分次举行。听证会按照下列议程进行： (一)主持人宣布听证事项和听证会纪律，介绍听证会参加人、听证人; (二)定价方案提出人陈述定价方案; (三)定价成本监审人或者成本调查人介绍定价成本监审、成本调查的办法、结论及相关情况; (四)听证会参加人对定价方案发表意见，进行询问，被询问人应当进行必要的解释说明; (五)必要时，主持人可以组织听证会参加人围绕主要分歧点进行补充陈述; (六)主持人总结发言。"},{"i":25,"n":"第二十五条","txt":"听证会参加人应当审阅涉及本人的听证笔录并签字。"},{"i":26,"n":"第二十六条","txt":"听证会举行后，听证人应当根据听证笔录制作听证报告。听证报告包括下列内容： (一)听证会的基本情况; (二)听证会参加人对定价方案的意见; (三)听证人对听证会参加人意见的处理建议，包括对听证会参加人主要意见采纳与不采纳的建议和理由说明; (四)其他有关情况。 听证人之间对听证会参加人意见的处理建议存在分歧的，应当在听证报告中列明相关听证人的不同意见。"},{"i":27,"n":"第二十七条","txt":"政府价格主管部门应当在听证会举行后15日内将听证笔录、听证报告一并提交定价机关。"},{"i":28,"n":"第二十八条","txt":"定价机关作出定价决定时应当充分考虑听证会的意见。 定价机关根据听证会的意见，对定价方案作出修改后，如有必要，可以再次举行听证会，或者采取其他方式征求社会意见。"},{"i":29,"n":"第二十九条","txt":"定价机关需要报请本级人民政府或者上级定价机关批准后才能作出定价决定的，上报定价方案时应当同时提交听证报告。"},{"i":30,"n":"第三十条","txt":"定价机关应当在定价听证结束之日起一年内作出定价决定。逾期未作出定价决定的，应当重新开展定价听证。 开展定价听证后，制定价格的依据发生重大变化的，定价机关应当重新提起定价听证。"},{"i":31,"n":"第三十一条","txt":"定价机关作出定价决定后，应当通过政府网站、新闻媒体向社会公布定价决定和对听证会参加人主要意见的采纳情况及理由。"},{"i":32,"n":"第三十二条","txt":"定价机关可以通过政府网站、新闻媒体就听证事项听取社会各方面的意见。"},{"i":33,"n":"第三十三条","txt":"制定在局部地区执行的价格或者降低价格的，听证会可以采取下列简易程序： (一)只设主持人; (二)听证会参加人由消费者、经营者构成; (三)听证会按照本办法第二十四条第(一)、(四)、(六)项规定的议程进行。 采取简易程序时，公告时限和材料送达时限可以适当缩短。"},{"i":34,"n":"第三十四条","txt":"政府价格主管部门可以参照本办法有关规定，通过互联网试点开展定价网络听证。网络听证的参加人应当实行实名注册。"},{"i":35,"n":"第三十五条","txt":"定价机关制定定价听证目录内商品和服务价格，未举行听证会的，由本级人民政府或者上级政府价格主管部门宣布定价无效，责令改正;对直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":36,"n":"第三十六条","txt":"政府价格主管部门违反本办法规定程序组织或者举行听证会，情节严重的，由本级人民政府或者上级政府价格主管部门责令改正，给予通报批评;对直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":37,"n":"第三十七条","txt":"政府价格主管部门、定价机关和第三方机构的工作人员在听证会的组织或者举行过程中，玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分;构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"参与听证会的其他人员违反听证纪律、妨碍听证秩序情节严重的，记入信用记录，纳入全国信用信息共享平台。 参与听证会的其他人员违反法律法规的，依法追究法律责任。"},{"i":39,"n":"第三十九条","txt":"听证经费申请纳入同级财政预算。"},{"i":40,"n":"第四十条","txt":"省级人民政府价格主管部门可以依据本办法制定实施细则。"},{"i":41,"n":"第四十一条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":42,"n":"第四十二条","txt":"本办法自2019年1月10日起施行。国家发展和改革委员会2008年10月15日发布的《政府制定价格听证办法》(国家发展和改革委员会令第2号)同时废止。"}],"zhengfuzhidingjiagechengbenjianshenbanfa":[{"i":1,"n":"第一条","txt":"为加强对政府制定价格商品和服务的成本监管，规范政府制定价格成本监审行为，提高政府价格决策科学性，根据《中华人民共和国价格法》和有关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国务院价格主管部门及有关部门，省、自治区、直辖市人民政府价格主管部门及有关部门，和经省、自治区、直辖市人民政府授权的市、县人民政府(以下简称定价机关)依法制定或者调整商品和服务价格(以下简称制定价格)过程中的成本监审行为，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称成本监审是指定价机关通过审核经营者成本，核定政府制定价格成本(以下简称定价成本)的行为，是政府制定价格的重要程序，是价格监管的重要内容。 本办法所称定价成本，是指定价机关核定的经营者生产经营或者提供政府制定价格的商品或者服务的合理费用支出，是政府制定价格的基本依据。"},{"i":4,"n":"第四条","txt":"各级定价机关负责组织实施本级定价权限范围内的成本监审，履行主体责任，对成本监审结论负责。"},{"i":5,"n":"第五条","txt":"成本监审项目实行目录管理。成本监审目录由国务院价格主管部门和省、自治区、直辖市人民政府价格主管部门分别依据中央和地方定价目录确定，并及时向社会公布。 自然垄断环节以及依成本定价的重要公用事业和公益性服务应当列入成本监审目录。成本监审目录应当根据政府定价目录修订情况和价格监管需要适时调整。 列入成本监审目录的商品和服务，未经成本监审的，不得制定价格，没有正式营业或者营业不满一个会计年度的除外。"},{"i":6,"n":"第六条","txt":"成本监审应当遵循公正、公开、科学、规范、效率的原则。"},{"i":7,"n":"第七条","txt":"成本监审包括制定价格前监审和定期监审两种形式。 成本监审目录中应当明确不同商品和服务的监审形式以及定期监审的间隔周期，定期监审的间隔周期不得少于一年。"},{"i":8,"n":"第八条","txt":"定价机关原则上应当对生产经营同种商品或者提供同种服务的所有经营者实施成本监审。经营者数量众多的，可以选取一定数量的有代表性的经营者实施成本监审。"},{"i":9,"n":"第九条","txt":"国务院价格主管部门及有关部门，省、自治区、直辖市人民政府价格主管部门及有关部门可以根据不同商品和服务的实际情况，制定具体商品和服务的定价成本监审办法。"},{"i":10,"n":"第十条","txt":"定价机关根据工作需要，可以委托价格主管部门或者有关部门开展成本监审部分工作，也可以通过政府购买服务等方式，委托或聘请专业机构或者人员参与成本监审工作。以政府购买服务等方式委托或聘请的，应当签订合同，明确工作内容及相关责任。"},{"i":11,"n":"第十一条","txt":"经营者应当建立健全成本核算制度，完整准确记录并单独核算定价商品或者服务的生产经营成本和收入。"},{"i":12,"n":"第十二条","txt":"定价机关应当逐步建立健全成本信息公开制度，经营者应当按照定价机关的规定公开成本，定价机关制定价格应当公开成本监审结论。"},{"i":13,"n":"第十三条","txt":"成本监审应当履行书面通知、资料初审、实地审核、意见告知、出具报告等程序。"},{"i":14,"n":"第十四条","txt":"定价机关实施成本监审，应当书面通知有关经营者，明确成本监审范围、监审形式、监审期间(成本审核会计年度期间)，以及需要提供的资料和进行实地审核的要求等内容。"},{"i":15,"n":"第十五条","txt":"经营者应当自收到书面通知之日起20个工作日内提供相关商品或者服务成本监审所需资料(以下简称成本资料)，并对所提供成本资料的真实性、合法性、完整性负责。成本资料应当包括下列内容： (一)按照定价机关要求和规定表式核算填报的成本报表，主要成本项目的核算方法、成本费用分摊方法及其相关依据; (二)经会计师事务所审计或者政府有关部门审核的年度财务报告; (三)生产量、销售量、服务量以及相关的统计报表; (四)成本监审所需的其他资料。"},{"i":16,"n":"第十六条","txt":"定价机关应当自收到经营者报送成本资料之日起10个工作日内对其完整性进行初审，资料不完整的，应当要求经营者限期补充。"},{"i":17,"n":"第十七条","txt":"经营者报送的成本资料经初审合格的，定价机关应当开展实地审核，调查了解经营者生产经营情况，查阅、复制有关资料，按照本办法第三章和相关商品或者服务的定价成本监审办法及有关规定对经营者成本进行审核。 实地审核过程中，定价机关可以根据工作需要，要求经营者补充提供成本相关资料。"},{"i":18,"n":"第十八条","txt":"定价机关应当将经营者成本审核初步意见告知经营者。经营者对成本审核初步意见有异议的，可以向定价机关提出书面意见及理由。"},{"i":19,"n":"第十九条","txt":"定价机关应当在对成本监审程序、成本审核方法和标准等进行复核后，核定定价成本，出具成本监审报告。成本监审报告应当包括下列内容： (一)成本监审项目; (二)成本监审依据; (三)成本监审程序; (四)经营者基本情况; (五)经营者成本审核情况; (六)成本监审结论; (七)定价成本核定表; (八)其他需要说明的事项。"},{"i":20,"n":"第二十条","txt":"成本监审工作人员与经营者有利害关系的，应当回避。定价机关及其工作人员不得将获得的经营者成本资料用于价格监管以外的任何其他目的，不得泄露经营者的商业秘密。"},{"i":21,"n":"第二十一条","txt":"定价机关应当按照档案管理制度建立成本监审卷宗并存档。卷宗应当实行“一项目一卷宗”制度，内容包括：成本监审书面通知、经营者报送的成本资料、成本监审报告等。"},{"i":22,"n":"第二十二条","txt":"核定定价成本应当遵循以下原则： (一)合法性。计入定价成本的费用应当符合有关法律、法规，财务制度和国家统一的会计制度，以及价格监管制度等规定。 (二)相关性。计入定价成本的费用应当与定价商品或者服务生产经营过程直接相关或者间接相关。 (三)合理性。计入定价成本的费用应当反映生产经营活动正常需要，并按照合理方法和合理标准核算;影响定价成本水平的主要技术、经济指标应当符合行业标准或者公允水平。"},{"i":23,"n":"第二十三条","txt":"核定定价成本，应当以经会计师事务所审计或者政府有关部门审核的年度财务报告以及手续齐备的原始凭证及账册为基础，有关费用按照本办法第二十四条至第三十九条规定核定。"},{"i":24,"n":"第二十四条","txt":"原材料、燃料和动力的单位产品消耗数量、损耗率等主要技术指标，应当按照有关消耗定额或者损耗率的国家标准或者行业标准核定，没有国家标准或者行业标准的，参照可比经营者平均水平核定。同行业内各经营者之间技术指标不可比的，应当考虑经营者实际情况和区域差异等因素，并参照经营者历史水平合理核定。 原材料、燃料等购进价格明显高于同期同类产品市场平均价格的，原则上应当按照同期同类产品市场平均价格确定其进货成本。"},{"i":25,"n":"第二十五条","txt":"职工工资总额按照职工平均工资与职工人数核定。其中，职工平均工资原则上据实核定，但不得超过统计部门公布的当地该行业职工平均工资水平;职工人数按照实际在岗职工人数核定，政府有关部门或者行业有明确规定的，不得超过其规定人数。由政府有关部门进行工资管理的，职工工资总额上限为按照其工资管理规定核定的数值。 因解除与职工的劳动关系给予的补偿，按照一定年限分摊计入定价成本。"},{"i":26,"n":"第二十六条","txt":"工会经费、职工教育经费、职工福利费、社会保险费(包含补充医疗和补充养老保险)、住房公积金，审核计算基数原则上按照经营者实缴基数核定，但不得超过核定的工资总额和当地政府规定的基数，计算比例按照不超过国家或者当地政府统一规定的比例确定。应当在工会经费、职工教育经费和职工福利费中列支的费用，不得在其他费用项目中列支。"},{"i":27,"n":"第二十七条","txt":"固定资产、无形资产等各类资产的原值，参照合理规模，遵循历史成本原则核定。按照规定进行过清产核资的，根据有关部门认定的固定资产价值核定。未投入实际使用的、不能提供价值有效证明的、由政府补助或者社会无偿投入的资产，以及评估增值的部分不得计提折旧或者摊销费用。"},{"i":28,"n":"第二十八条","txt":"固定资产折旧方法采用年限平均法(交通运输等行业可以采用工作量折旧法)。折旧年限应当根据固定资产的性质、设计使用年限和行业规范，并考虑资产使用状况合理核定。经营者确定的固定资产折旧年限明显低于实际使用年限，成本监审时应当按照实际使用年限调整折旧年限。残值率一般按3-5%计算。行业定价成本监审办法有规定的，从其规定。"},{"i":29,"n":"第二十九条","txt":"实行特许经营的，固定资产折旧年限按照不同情况分别处理： (一)特许经营期满后资产无偿移交的，固定资产折旧年限最高不超过特许经营期; (二)特许经营期满后资产有偿转让的，按照第二十八条规定确定折旧年限。"},{"i":30,"n":"第三十条","txt":"无形资产从开始使用之日起，在有效使用期限内分摊计入年度费用中。其中，土地使用权费已计入地面建筑物价值且无法分离的，随建筑物提取折旧;其他按照土地使用权年限分摊。特许经营权费用原则上不得计入定价成本，政府规定允许计入的，按照特许经营年限分摊，没有特许经营年限的按30年分摊。专利权等其他无形资产，按照受益年限分摊，没有明确受益年限的按不少于10年分摊。"},{"i":31,"n":"第三十一条","txt":"修理费用原则上据实核定，也可以按照固定资产原值的一定比例核定，或者在固定资产原值的一定比例内据实核定。"},{"i":32,"n":"第三十二条","txt":"管理费用中，人员相关费用按照本办法第二十五和二十六条规定核定;会议费、交通费、差旅费、业务招待费等非生产性费用按照监审期间内平均水平核定，其中业务招待费不得超过当年主营业务(指生产经营监审商品或者服务的业务，下同)收入的5‰。"},{"i":33,"n":"第三十三条","txt":"销售费用中，人员相关费用按照本办法第二十五和二十六条规定核定，其他项目原则上据实核定。"},{"i":34,"n":"第三十四条","txt":"财务费用中的利息支出原则上据实核定。年度利息支出差异较大的，按照还款期计算的年平均利息核定。自有资本金比例未达到国家规定的，不足部分的借款利息不得计入定价成本。"},{"i":35,"n":"第三十五条","txt":"经营者获得的与监审商品或者服务有关的政府补助，用于购买固定资产的，按照第二十七和二十八条规定核定;用于补助专门项目的，直接冲减该项费用;未明确规定专项用途的，应当冲减总成本。"},{"i":36,"n":"第三十六条","txt":"经营者生产经营多种商品或者服务的，应当采取合理的方法分摊共同发生的费用。"},{"i":37,"n":"第三十七条","txt":"其他业务成本应当单独核算，不计入监审商品或者服务成本。其他业务与主营业务共同使用资产、人员或者统一支付费用，依托主营业务从事生产经营活动，以及因从事主营业务而获得政府优惠政策，不能单独核算或者核算不合理的，应当将其他业务收入按照一定比例冲减总成本。该比例可采用收入比、直接人员数量比、资产比或者其他合理方法确定。"},{"i":38,"n":"第三十八条","txt":"本办法未规定的其他费用，有关法律法规和国家政策已明确规定核算原则和标准的，按照相关规定核定;没有明确规定的，原则上据实核定，但应当符合公允水平。"},{"i":39,"n":"第三十九条","txt":"下列费用不得计入定价成本： (一)不符合《中华人民共和国会计法》等有关法律、行政法规，财务制度和国家统一的会计制度，以及价格监管制度等的费用; (二)与监审商品或者服务生产经营过程无关的费用; (三)虽与监审商品或者服务生产经营过程有关、但有专项资金来源予以补偿的费用; (四)固定资产盘亏、毁损、闲置和出售的净损失; (五)向上级公司或者管理部门上交的利润性质的管理费用、代上级公司或者管理部门缴纳的各项费用、向出资人支付的利润分成以及对附属单位的补助支出等; (六)各类捐赠、赞助、滞纳金、违约金、罚款，以及计提的准备金; (七)公益广告、公益宣传费用，以及垄断性行业的各类广告费; (八)经营者过度购置固定资产所增加的支出(折旧、修理费、借款利息等); (九)其他不合理费用。"},{"i":40,"n":"第四十条","txt":"同种商品或者服务有多个经营者的，应当在审核单个经营者成本基础上，通过汇总平均，核定商品或者服务的定价成本。"},{"i":41,"n":"第四十一条","txt":"根据本办法应当开展成本监审的商品和服务，定价机关制定价格未开展成本监审的，由价格主管部门、上级主管部门或者本级人民政府责令改正;情况严重的通报批评;造成重大影响的，对直接责任人员和领导人员，依法给予处分。"},{"i":42,"n":"第四十二条","txt":"从事成本监审工作的人员泄露国家秘密、商业秘密以及滥用职权、徇私舞弊、玩忽职守、索贿受贿，依法给予处分，构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"经营者拒绝提供成本监审所需资料，或者提供虚假资料、不完整提供资料的，定价机关可以中止成本监审、按照从低原则核定成本，并将其不良信用记录纳入全国信用信息共享平台，实施失信联合惩戒。"},{"i":44,"n":"第四十四条","txt":"成本监审工作所需经费，纳入本部门年度同级财政预算。"},{"i":45,"n":"第四十五条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":46,"n":"第四十六条","txt":"本办法自2018年1月1日起施行。国家发展改革委2006年3月1日发布的《政府制定价格成本监审办法》和2007年6月5日发布的《定价成本监审一般技术规范(试行)》同时废止。"}],"zhengfuzhidingjiagexingweiguize":[{"i":1,"n":"第一条","txt":"为规范政府制定价格行为，提高政府制定价格的科学性、公正性和透明度，保护消费者和经营者的合法权益，根据《中华人民共和国价格法》，制定本规则。"},{"i":2,"n":"第二条","txt":"国务院价格主管部门及有关部门，省、自治区、直辖市人民政府价格主管部门及有关部门，和经省、自治区、直辖市人民政府授权的市、县人民政府(以下简称定价机关)依法制定或者调整实行政府指导价、政府定价的商品和服务价格水平以及定价机制的行为，适用本规则。 法律、法规另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"国家实行并完善主要由市场决定价格的机制。政府制定价格的范围主要为重要公用事业、公益性服务和自然垄断经营的商品和服务等，具体以中央定价目录和地方定价目录(以下简称定价目录)为准。 经省、自治区、直辖市人民政府授权的市、县人民政府制定价格，具体工作由其所属价格主管部门或者有关部门负责。 定价机关应当按照法定的权限制定价格，不得越权定价。"},{"i":4,"n":"第四条","txt":"定价目录应当依照法定程序制定，逐项明确定价内容和定价机关，并根据经济社会发展情况适时调整，及时向社会公布。"},{"i":5,"n":"第五条","txt":"制定价格应当遵循公平、公开、公正和效率的原则。"},{"i":6,"n":"第六条","txt":"制定价格应当依据有关商品和服务的社会平均成本、市场供求状况、国民经济与社会发展要求以及社会承受能力。商品和服务价格与国际市场价格、替代商品和服务价格联系紧密的，可以参考相关价格。 网络型自然垄断环节价格，按照“准许成本加合理收益”的原则制定。"},{"i":7,"n":"第七条","txt":"国务院价格主管部门及有关部门，省、自治区、直辖市人民政府价格主管部门及有关部门应当根据不同行业特点，逐步建立商品和服务的定价机制，实现商品和服务价格调整机制化。"},{"i":8,"n":"第八条","txt":"定价机关应当根据经济社会发展情况、社会各方面的反映以及价格执行期限等，适时制定价格。"},{"i":9,"n":"第九条","txt":"定价机关制定价格，应当履行价格调查、成本监审或者成本调查、听取社会意见、合法性审查、集体审议、作出制定价格的决定等程序。 依法应当开展成本监审、专家论证、价格听证、风险评估的，按照有关规定执行。 已经依法制定定价机制的，定价机关应当按照定价机制确定具体价格水平。"},{"i":10,"n":"第十条","txt":"定价机关制定价格，可以要求相关经营者、行业组织、政府有关部门提供制定价格所需的资料。"},{"i":11,"n":"第十一条","txt":"定价机关制定价格，应当对市场供求、社会承受能力进行调查，分析对相关行业、消费者的影响。"},{"i":12,"n":"第十二条","txt":"定价机关制定价格，应当开展成本监审或者成本调查，并逐步建立成本信息公开制度。 依法应当开展成本监审的，按照成本监审的有关规定执行，未经成本监审的，不得制定价格。"},{"i":13,"n":"第十三条","txt":"制定专业性、技术性较强的商品和服务价格时，定价机关应当邀请有关方面的专家进行论证。"},{"i":14,"n":"第十四条","txt":"定价机关制定价格，应当听取经营者、消费者或其代表，以及有关方面的意见。 对依法应当通过听证方式征求意见的，由政府价格主管部门主持，按照价格听证的有关规定开展听证;未经听证不得制定价格。"},{"i":15,"n":"第十五条","txt":"制定价格对经济社会可能造成重大影响的，应当开展风险评估。 风险评估可以单独进行，也可以结合听取社会意见、专家论证等一并进行。"},{"i":16,"n":"第十六条","txt":"定价机关履行本规则第十一条至第十五条规定程序后，应当形成制定价格的方案。方案应当载明以下内容： (一)现行价格和拟制定的价格、单位调价幅度; (二)制定价格的依据和理由; (三)制定价格对相关行业和消费者的影响; (四)成本监审报告或者成本调查报告; (五)经营者、消费者或其代表，以及有关方面的主要意见及采纳情况; (六)经过听证的，附听证报告; (七)经过专家论证的，附专家论证意见及采纳情况; (八)经过风险评估的，附风险评估意见; (九)价格的执行时间、期限和范围。"},{"i":17,"n":"第十七条","txt":"定价机关制定价格，应当开展合法性审查。实行合法性审查的方式、机构和工作规则，由定价机关规定。合法性审查内容包括： (一)制定价格事项是否符合定价目录规定的权限和范围; (二)制定价格的程序是否符合法定程序; (三)需要审查的其他事项。"},{"i":18,"n":"第十八条","txt":"定价机关应当对制定价格的方案实行集体审议。实行集体审议的方式、人员组成和工作规则，由省级以上定价机关规定。"},{"i":19,"n":"第十九条","txt":"国务院价格主管部门及有关部门制定重要的商品和服务价格，应当按照有关规定报国务院批准。 省、自治区、直辖市价格主管部门及有关部门制定重要的商品和服务价格，应当按照有关规定报同级人民政府批准。"},{"i":20,"n":"第二十条","txt":"定价机关是政府其他部门的，作出制定价格决定前应当书面征求同级价格主管部门的意见。"},{"i":21,"n":"第二十一条","txt":"按照本规则履行相关程序后，认为需要制定价格的，定价机关应当适时作出制定价格的决定。制定价格的决定应当载明以下内容： (一)制定价格的项目、制定的价格; (二)制定价格的依据; (三)价格的执行时间和范围; (四)作出决定的定价机关名称和作出决定的日期。 制定价格的决定原则上应当由定价机关制发。授权市、县人民政府制定价格的，经市、县人民政府批准，可以由价格主管部门或者有关部门制发并抄报市、县人民政府。"},{"i":22,"n":"第二十二条","txt":"定价机关应当按照档案管理制度建立制定价格的卷宗并存档。 卷宗应当实行“一价一卷宗”，内容包括：制定价格的方案、制定价格的决定及相关材料。"},{"i":23,"n":"第二十三条","txt":"制定价格的决定实施后，定价机关应当对决定的执行情况进行跟踪调查和监测，并适时进行后评估。后评估的内容包括： (一)价格的执行情况，执行中存在的问题及原因; (二)经营者经营状况、成本、劳动生产率和市场供求变化对价格的影响; (三)相关商品和服务市场供求状况和价格的变化情况; (四)社会各方面对所制定价格的意见; (五)制定的价格对经济社会发展和消费者、经营者的影响; (六)其他有关情况。"},{"i":24,"n":"第二十四条","txt":"制定价格的决定实施后，如果制定价格的依据发生重大变化，定价机关应当适时调整价格。"},{"i":25,"n":"第二十五条","txt":"经营者、消费者、政府相关部门及有关方面(以下简称建议人)可以向定价机关提出制定价格的建议。建议内容主要包括建议制定价格的具体商品或者服务名称、建议价格、依据和理由等。"},{"i":26,"n":"第二十六条","txt":"制定价格有建议人的，定价机关应当以适当的方式将建议办理情况告知建议人。"},{"i":27,"n":"第二十七条","txt":"定价机关听取经营者、消费者或其代表，以及有关方面的意见时，可以选择向社会公开征求意见、书面征求意见、召开座谈会、组织听证、实地走访等方式。"},{"i":28,"n":"第二十八条","txt":"定价机关制定价格时，可以通过政府购买服务等方式发挥第三方机构的积极作用。"},{"i":29,"n":"第二十九条","txt":"除涉及国家秘密外，定价机关应当及时向社会公开制定价格的决定。"},{"i":30,"n":"第三十条","txt":"定价机关应当建立严格规范的内部监督制约机制。 上级价格主管部门负责对下级价格主管部门制定价格行为的监督和指导。政府其他有关部门的制定价格行为应当接受价格主管部门的监督。"},{"i":31,"n":"第三十一条","txt":"定价机关制定价格，应当接受社会监督。单位和个人可以对制定价格过程中的违法违规行为进行举报。"},{"i":32,"n":"第三十二条","txt":"定价机关有违法行为的，由政府价格主管部门依据《价格法》进行查处。"},{"i":33,"n":"第三十三条","txt":"定价机关的工作人员在制定价格工作中有违法行为，构成犯罪的，依法追究刑事责任;尚不构成犯罪的，依法给予行政处分。"},{"i":34,"n":"第三十四条","txt":"各省、自治区、直辖市价格主管部门可以依据本规则并结合本地实际情况制定实施细则。"},{"i":35,"n":"第三十五条","txt":"本规则由国家发展和改革委员会解释。"},{"i":36,"n":"第三十六条","txt":"本规则自2018年1月1日起施行。2006年3月17日国家发展和改革委员会发布的《政府制定价格行为规则》同时废止。"}],"xinjianchundiandongchengyongcheqiyeguanliguiding-2":[{"i":1,"n":"第一条","txt":"为促进新能源汽车产业发展，发挥市场主体的作用，支持社会资本和具有技术创新能力的企业参与纯电动乘用车科研生产，根据《中华人民共和国行政许可法》及《政府核准投资项目管理办法》、《汽车产业发展政策》等有关法律、法规和规章，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中国境内投资新建独立法人纯电动乘用车生产企业(以下简称“新建企业”)。"},{"i":3,"n":"第三条","txt":"本规定所称“纯电动乘用车”，包括纯电动和增程式(具备外接充电功能的串联式混合动力)乘用车，分别指国家标准GB/T 19596-2004《电动汽车术语》中第3.1.1.1.1款和第3.1.1.1.2.1款所定义的车辆。“乘用车”包含轿车和其他乘用车，是指整车(含底盘)为自制的、国家标准GB/T 3730.1-2001《汽车和挂车类型的术语和定义》中第2.1.1.1款至第2.1.1.10款所定义的车辆。"},{"i":4,"n":"第四条","txt":"国家发展改革委、工业和信息化部在各自职责范围内负责新建企业投资项目和车辆生产企业及产品准入的监督管理。"},{"i":5,"n":"第五条","txt":"新建企业投资项目应执行《国务院关于发布政府核准的投资项目目录(2014年本)的通知》(国发[2014]53号)和《汽车产业发展政策》有关规定。"},{"i":6,"n":"第六条","txt":"新建企业投资项目的投资总额和生产规模不受《汽车产业发展政策》有关最低要求限制，由投资主体自行决定。 新建企业可生产纯电动乘用车，不能生产任何以内燃机为驱动动力的汽车产品。"},{"i":7,"n":"第七条","txt":"新建企业的投资主体应按照《政府核准投资项目管理办法》有关要求编制投资项目申请报告，并向国家发展改革委提供投资项目申请企业的企业概况、基础能力、试制样车说明及证明材料。"},{"i":8,"n":"第八条","txt":"新建企业的投资主体应具备以下基本条件： (一)在中国境内注册，具备与项目投资相适应的自有资金规模和融资能力。 (二)具有纯电动乘用车产品从概念设计、系统和结构设计到样车研制、试验、定型的完整研发经历。具有专业研发团队和整车正向研发能力，掌握整车控制系统、动力蓄电池系统、整车集成和整车轻量化方面的核心技术以及相应的试验验证能力，拥有纯电动乘用车自主知识产权和已授权的相关发明专利。 (三)具有整车试制能力，具备完整的纯电动乘用车样车试制条件，包括车身及底盘制造、动力蓄电池系统集成、整车装配等主要试制工艺和装备。 (四)自行试制同一型式的纯电动乘用车样车数量不少于15辆。提供的样车经过国家认定的检测机构检验，在符合汽车国家标准和电动汽车相关标准的前提下，在安全性、可靠性、动力性、整车轻量化、经济性等方面达到规定的技术要求。"},{"i":9,"n":"第九条","txt":"新建企业投资项目申请报告应包括以下内容: (一)具备纯电动乘用车整车正向开发能力的研发机构。至少具备整车及动力系统匹配、整车管理系统、车载能源管理系统、车辆轻量化、车辆安全等关键技术的设计开发能力、试验检测能力以及对整车产品运行状态的监控能力。 (二)与生产纲领、产品结构相适应的车身成型、涂装、总装等整车生产工艺和装备，以及动力蓄电池系统集成等关键部件的生产能力和一致性保证能力。 (三)纯电动乘用车产品的销售及售后服务体系。 (四)新建企业要有履行保障消费者权益等社会责任的承诺和措施，并提供担保企业和经公证的担保期不低于5年(以项目建成投产为起始点)的担保合同。"},{"i":10,"n":"第十条","txt":"国家发展改革委应当依据《政府核准投资项目管理办法》有关规定对新建企业投资项目申请进行审查，并征求工业和信息化部的意见。"},{"i":11,"n":"第十一条","txt":"国家发展改革委应当对新建企业投资项目申请组织专家进行评估，由纯电动乘用车行业专家库中的专家组成投资项目评审委员会，对投资项目申请企业提供的附件一和附件二的真实性和符合性进行审查，并在30个工作日内出具评审意见。 纯电动乘用车行业专家库由国家发展改革委会同工业和信息化部负责组建。"},{"i":12,"n":"第十二条","txt":"投资项目完成建设后，新建企业及产品按照工业和信息化部《乘用车生产企业及产品准入管理规则》和《新能源汽车生产企业及产品准入管理规则》的相关要求，通过考核后列入《车辆生产企业及产品公告》，并按单独类别管理。"},{"i":13,"n":"第十三条","txt":"新建企业生产的纯电动乘用车产品应使用该企业拥有所有权的注册商标和品牌，且符合乘用车、电动汽车相关国家标准和行业标准的要求，所采用动力蓄电池单体和系统应当是符合汽车动力蓄电池行业规范条件的企业生产的产品。新建企业须提交对纯电动乘用车电池、电机、电控系统等核心部件的质保承诺，质保承诺的内容应符合国家支持新能源汽车推广应用的相关规定。"},{"i":14,"n":"第十四条","txt":"新建企业列入《车辆生产企业及产品公告》的纯电动乘用车产品有效期为3年，有效期届满前30日可提出延期申请，审查通过可以延长有效期，每次延期不超过3年。"},{"i":15,"n":"第十五条","txt":"新建企业应建立生产一致性管理体系，保证实际生产的产品与列入《车辆生产企业及产品公告》的产品相符。对企业生产未经许可或不符合标准的产品，依照《道路交通安全法》和工业和信息化部《车辆生产企业及产品一致性监督管理办法》有关规定进行处理。"},{"i":16,"n":"第十六条","txt":"工业和信息化部对新建企业承诺履行情况、售后服务保障情况、产品安全性和一致性等方面开展评价，评价结果向社会公开。"},{"i":17,"n":"第十七条","txt":"工业和信息化部对新建企业准入条件保持情况进行抽查，对不能保持生产准入相关条件或已经破产的企业，依法撤销、注销或暂停其《车辆生产企业及产品公告》。暂停期间，企业不得办理更名、迁址等变更手续。"},{"i":18,"n":"第十八条","txt":"新建企业投资项目和准入管理的监管及法律责任，按照国家有关法律法规以及《政府核准投资项目管理办法》等规定执行。"},{"i":19,"n":"第十九条","txt":"本规定由国家发展和改革委员会、工业和信息化部负责解释。"},{"i":20,"n":"第二十条","txt":"本规定自2015年7月10日起施行。"}],"shuiligongchenggongshuijiageguanlibanfa":[{"i":1,"n":"第一条","txt":"为科学合理核定水利工程供水价格，完善水利工程供水定价机制，促进水资源节约、保护和合理利用，促进水利工程良性运行、水利事业健康发展，保障国家水安全，根据《中华人民共和国价格法》《中华人民共和国水法》以及《政府制定价格行为规则》等法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内制定和调整中央直属及跨省（自治区、直辖市）重大水利工程供水价格的行为。"},{"i":3,"n":"第三条","txt":"本办法所称水利工程供水价格，是指水利工程供水经营者通过拦、蓄、引、提等水利工程设施销售的天然水价格。"},{"i":4,"n":"第四条","txt":"中央直属及跨省（自治区、直辖市）水利工程供水价格原则上实行政府定价，由国务院价格主管部门制定和调整。鼓励有条件的水利工程由供需双方协商确定价格，或通过招投标等公开公平竞争形成价格。"},{"i":5,"n":"第五条","txt":"制定和调整水利工程供水价格遵循以下原则： （一）激励约束并重。按照“准许成本加合理收益”的方法核定水利工程供水价格，强化成本约束的同时，合理确定投资回报，促进水利工程良性运行。 （二）用户公平负担。区分供水经营者类别和性质，科学归集和分摊不同功能类型和供水类别的成本，统筹考虑用户承受能力，兼顾其他公共政策目标，确定供水价格。 （三）发挥市场作用。与水利投融资体制机制改革相适应，充分发挥价格杠杆作用，鼓励和引导社会资本参与水利工程建设和运营，为扩大市场化融资规模创造条件。"},{"i":6,"n":"第六条","txt":"水利工程供水价格原则上以水利工程供水经营者为单位核定。同一水利工程供水经营者所属的多个工程供水价格统一核定，其中多个工程向不同区域供水且区域差异较大的，可分别定价。同一水利工程向不同区域供水且成本差异较大的，可按区域分别定价。"},{"i":7,"n":"第七条","txt":"水利工程供水价格以准许收入为基础核定，具体根据工程情况分类确定。政府投入实行保本或微利，社会资本投入收益率适当高一些。少数国家重大水利工程根据实际情况，供水价格可按照保障工程正常运行和满足还贷需要制定。"},{"i":8,"n":"第八条","txt":"水利工程供水价格监管周期为5年。如监管周期内工程投资、供水量、成本等发生重大变化，可以提前校核调整。"},{"i":9,"n":"第九条","txt":"水利工程供水实行分类定价，按供水对象分为农业用水价格和非农业用水价格。农业用水是指由水利工程直接供应的粮食作物、经济作物和水产养殖等用水；非农业用水是指由水利工程直接供应的除农业用水外的其他用水，其中供水力发电用水和生态用水价格由供需双方协商确定，生态用水价格参考供水成本协商。"},{"i":10,"n":"第十条","txt":"供水经营者供水业务的准许收入由准许成本、准许收益和税金构成。其中，按满足运行还贷需要制定水价的工程，准许收入原则上按照补偿工程运行维护费用和贷款本息确定。"},{"i":11,"n":"第十一条","txt":"准许成本包括固定资产折旧费、无形资产摊销费和运行维护费等，由国务院价格主管部门按照《政府制定价格成本监审办法》《水利工程供水定价成本监审办法》等通过成本监审核定。"},{"i":12,"n":"第十二条","txt":"准许收益按可计提收益的供水有效资产乘以准许收益率计算确定。 （一）可计提收益的供水有效资产为成本监审核定的由供水经营者投入且与供水业务相关的允许计提投资回报的资产，包括固定资产净值、无形资产净值和营运资本。 （二）准许收益率按权益资本收益率和债务资本收益率加权平均确定。计算公式为： 准许收益率＝权益资本收益率×（1－资产负债率）+债务资本收益率×资产负债率 区分社会资本投入和政府资本金注入形成的供水有效资产，分别确定权益资本收益率。社会资本投入形成的供水有效资产，权益资本收益率综合考虑工程运行状况、供水结构、下游用户承受能力等因素，按监管周期初始年前一年国家10年期国债平均收益率加不超过4个百分点确定；政府资本金注入形成的供水有效资产，权益资本收益率按不超过监管周期初始年前一年国家10年期国债平均收益率确定。 债务资本收益率参考供水经营者实际融资结构，如实际贷款利率高于监管周期初始年前"},{"i":13,"n":"第十三条","txt":"税金包括所得税、城市维护建设税、教育费附加，依据国家现行相关税法规定核定。"},{"i":14,"n":"第十四条","txt":"供水价格按供水业务准许收入除以计价点核定售水量确定。综合考虑农业、非农业用水状况和用户承受能力等，国务院价格主管部门制定供农业用水和非农业用水价格，其中供农业用水权益资本收益率适当低一些。 核定售水量为上一监管周期年平均售水量，有设计供水量的工程，上一监管周期年平均售水总量低于工程设计供水量60%的，按设计供水量的60%确定。有供水力发电用水和生态用水的，相应水量予以剔除。核定农业售水量和非农业售水量按照上一监管周期年平均农业和非农业实际售水量的比例确定。新建工程在达产过程中，核定售水量按上一监管周期最末两年平均售水量且不低于设计供水量的60%确定。原有工程因上游来水、用水需求发生较大变化导致实际售水量较多低于设计供水量的，可视情调整核定售水量，保障工程运行维护需要。实际农业售水量超过上一监管周期核定农业售水量的部分，可适当上浮供农业用水价格。 供水价格不含增值税，增值税根据实际执行税"},{"i":15,"n":"第十五条","txt":"国务院价格主管部门综合考虑供水成本、市场供求状况、国民经济与社会发展要求以及用户承受能力等，合理制定水利工程供水价格。价格调整幅度较大时，可分步调整到位。"},{"i":16,"n":"第十六条","txt":"长距离引调水工程供水价格按照“受益者分摊”的原则，兼顾地区差异，分区段或口门制定。"},{"i":17,"n":"第十七条","txt":"新建水利工程运行初期的供水价格，由国务院价格主管部门依据经批复的可行性研究报告、初步设计的成本参数及设计供水量确定，保障工程正常运行；可行性研究报告、初步设计的成本参数与成本监审有关规定不一致的，按成本监审有关规定进行调整。具备成本监审条件后，由国务院价格主管部门开展成本监审，制定供水价格。"},{"i":18,"n":"第十八条","txt":"新建重大水利工程实行基本水价和计量水价相结合的两部制水价，原有工程具备条件的可实行两部制水价。基本水价按照适当补偿工程基本运行维护费用、合理偿还贷款本息的原则核定，原则上不超过综合水价的50%。 新建工程的基本水费按设计供水量收取，原有工程按核定售水量收取；计量水费按计价点的实际售水量收取。"},{"i":19,"n":"第十九条","txt":"供水水源受季节影响较大的水利工程，供水价格可实行季节水价。"},{"i":20,"n":"第二十条","txt":"除向水力发电、生态用水、城乡供水企业供水以外，水利工程向终端用水户直接供水的，应当实行定额管理，超定额用水实行累进加价。"},{"i":21,"n":"第二十一条","txt":"水利工程供水价格的制定和调整，由国务院价格主管部门依职责实施。水利工程供水经营者可通过国务院水行政主管部门向国务院价格主管部门提出定调价建议，或直接向国务院价格主管部门提出定调价建议，同时抄报国务院水行政主管部门。"},{"i":22,"n":"第二十二条","txt":"国务院价格主管部门制定和调整水利工程供水价格，应当开展成本监审，其结果作为制定和调整供水价格的基本依据。"},{"i":23,"n":"第二十三条","txt":"水利工程供水经营者应当配合国务院价格主管部门的价格制定和调整工作，如实提供生产经营及成本情况，并对提供资料的真实性、合法性、完整性负责。无正当理由拒绝、延迟提供相关资料，或者提供虚假资料的，国务院价格主管部门责令限期改正；故意瞒报、虚报相关信息并获得不当收益的，在下一次价格校核时进行追溯，视情采取降低准许收益率等措施。"},{"i":24,"n":"第二十四条","txt":"国务院价格主管部门制定和调整水利工程供水价格，应当通过门户网站等形式向社会公开价格水平等相关信息。"},{"i":25,"n":"第二十五条","txt":"水利工程供水应当实行价格公示制度。水利工程供水经营者必须严格执行国家水价政策，并向社会公开供水价格。"},{"i":26,"n":"第二十六条","txt":"水利工程供水实行按量计价，一般以产权分界点或交水断面的计量售水量作为计价点售水量。水利工程供水经营者应当完善供水计量设施并定期进行率定，主动向用户公开计量数据。"},{"i":27,"n":"第二十七条","txt":"用户应当按照规定的计量标准和水价标准按期交纳水费。用户逾期不交纳水费的，应当按照约定支付违约金。"},{"i":28,"n":"第二十八条","txt":"新建水利工程应当在项目前期工作阶段，由项目法人、供水经营者或其出资人代表与用户代表或用户所在县级及以上人民政府授权代表签订框架协议，就水价测算边界条件进行约定，包括准许收益率等关键参数取值、两部制水价设置等，并抄报国务院价格主管部门和水行政主管部门。"},{"i":29,"n":"第二十九条","txt":"各省（自治区、直辖市）价格主管部门可以参照本办法，对本省（自治区、直辖市）骨干水利工程供水价格进行管理，或商水行政主管部门参照本办法并结合本地实际情况，制定本省（自治区、直辖市）水利工程供水价格管理办法。"},{"i":30,"n":"第三十条","txt":"本办法由国务院价格主管部门负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2023年4月1日起施行。本办法发布前国家发展改革委、水利部有关规定与本办法不符的，以本办法为准。国家发展改革委、水利部2003年发布的《水利工程供水价格管理办法》（国家发展改革委、水利部2003年第4号令）同时废止。"}],"shuiligongchenggongshuidingjiachengbenjianshenbanf57e971":[{"i":1,"n":"第一条","txt":"为加强水利工程供水成本监管，规范定价成本监审行为，提高政府价格监管的科学性、合理性和透明度，促进水利工程良性运行、水利事业健康发展，根据《中华人民共和国价格法》和《政府制定价格成本监审办法》（国家发展改革委2017年第8号令）等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于国务院价格主管部门对实行政府定价的中央直属及跨省（自治区、直辖市）重大水利工程供水经营者（以下简称“供水经营者”）实施定价成本监审的行为。"},{"i":3,"n":"第三条","txt":"本办法所称水利工程供水定价成本，是指供水经营者通过拦、蓄、引、提等水利工程设施提供天然水过程中发生的合理费用支出。"},{"i":4,"n":"第四条","txt":"水利工程供水定价成本监审应当遵循以下原则： （一）合法性原则。计入定价成本的费用应当符合《中华人民共和国会计法》等有关法律法规、国家有关财务会计制度、价格监管制度等规定。 （二）相关性原则。计入定价成本的费用，应当与水利工程供水生产经营活动相关。 （三）合理性原则。计入定价成本的费用，应当反映水利工程供水生产经营活动正常需要，并按照合理方法和合理标准核算；影响定价成本水平的主要技术、经济指标，应当符合行业标准或者社会公允水平。"},{"i":5,"n":"第五条","txt":"核定水利工程供水定价成本，应当以监审期间经会计师事务所审计或者政府有关部门审核的年度财务报告、会计凭证、账簿，以及水量统计报表、水利工程投资、生产运行、政府审批核准文件等相关资料为基础。"},{"i":6,"n":"第六条","txt":"水利工程供水定价成本监审周期原则上为5年。首次成本监审，监审期根据实际运营年度及工程运行情况合理确定。"},{"i":7,"n":"第七条","txt":"供水经营者应当积极配合做好成本监审工作，如实客观反映情况，并按照要求提供财务报告、会计凭证、账簿、科目汇总表等相关文件资料和电子数据。"},{"i":8,"n":"第八条","txt":"供水经营者应当按照本办法要求，建立健全供水业务成本核算制度，完整准确记录并单独核算各类供水业务的生产经营成本和收入情况，并于每年4月底前向国务院价格主管部门和国务院水行政主管部门报送。"},{"i":9,"n":"第九条","txt":"水利工程供水定价成本包括固定资产折旧费、无形资产摊销费、运行维护费和纳入定价成本的相关税金。其中，运行维护费包括：材料费、修理费、大修理费、职工薪酬、管理费用、销售费用、其他运行维护费，以及供水经营者为保障本区域供水服务购入原水的费用。"},{"i":10,"n":"第十条","txt":"固定资产折旧费指与水利工程供水相关的可计提折旧的固定资产按照规定的折旧年限和方法计提的费用。"},{"i":11,"n":"第十一条","txt":"无形资产摊销费指供水经营者持有的与水利工程供水相关的无形资产按照规定的年限和方法计提的费用。"},{"i":12,"n":"第十二条","txt":"材料费指水利工程供水运行维护过程中实际消耗的原材料、辅助材料、备品备件、燃料动力以及其他直接材料的费用。"},{"i":13,"n":"第十三条","txt":"修理费指为维持水利工程正常运行所进行的修理和维护活动发生的费用。 大修理费指为恢复或提升固定资产的性能、延长固定资产使用年限，对其进行较大规模修理发生的费用。"},{"i":14,"n":"第十四条","txt":"职工薪酬指供水经营者从事水利工程运行维护、经营管理人员的工资、奖金等各种形式的报酬以及其他相关费用。具体包括：职工工资（基本工资、奖金、津贴和补贴）；职工福利费；基本养老保险费、基本医疗保险费、失业保险费、工伤保险费和生育保险费等社会保险费，以及按照法律法规规定为职工缴纳的补充养老保险费（年金）和补充医疗保险费；住房公积金和补充住房公积金；工会经费和职工教育经费；符合政策规定的离退休费用等。 劳务派遣、临时用工性质的用工支出未包含在工资总额内的，在不超过国家有关规定的范围内按照实际发生数核定。"},{"i":15,"n":"第十五条","txt":"销售费用指供水经营者在供水销售过程中发生的费用，包括运输费、资料费、包装费、保险费、租赁费、销售服务费、代办手续费等。"},{"i":16,"n":"第十六条","txt":"管理费用指供水经营者管理部门为组织和管理供水经营发生的费用，包括办公费、差旅费、业务招待费、印刷费、水电费、取暖费、会议费、培训费、公安消防费、低值易耗品摊销、土地使用费、物业管理费等。"},{"i":17,"n":"第十七条","txt":"其他运行维护费指水利工程运行维护过程中发生的除上述费用之外的水质检测费、水文水工观测费、研发费用、安全生产费用、劳务费、劳动保护费、生产用车使用费、委托业务费、临时设施费和应急保供任务发生费用、安全鉴定及检测费用等。"},{"i":18,"n":"第十八条","txt":"纳入定价成本的相关税金包括车船使用税、房产税、土地使用税和印花税。"},{"i":19,"n":"第十九条","txt":"固定资产折旧费。按照核定的监审期间最末一年可计提折旧的固定资产原值、规定的折旧年限，采用年限平均法分类核定。 （一）可计提折旧的固定资产。指履行必要审批手续购买、建设的与水利工程供水业务相关的资产，以及政府无偿划拨的供水业务相关资产，不包括供水经营者开办的多种经营企业及“三产”等与供水业务无关的资产。 固定资产原值遵循历史成本原则核定。按照规定进行过清产核资的，根据财政或国有资产监督管理部门认定的各类固定资产价值核定；未实际投入使用的、不能提供固定资产价值有效证明的或者社会无偿投入的固定资产，以及固定资产评估增值的部分不计提折旧。 （二）固定资产折旧费按照核定的固定资产原值分类确定。折旧年限根据固定资产的性质、设计使用年限和行业规范，并考虑资产使用状况合理核定，各类固定资产折旧年限不低于附件规定的折旧年限。固定资产残值率按附件规定的残值率核定。供水经营者实际固定资产折旧年限高于本办法规"},{"i":20,"n":"第二十条","txt":"无形资产摊销费。计入定价成本的无形资产摊销费按照核定的监审期间最末一年无形资产原值、规定的摊销年限，采用直线摊销法核定。土地使用权费已计入地面建筑物价值且无法分离的，随建筑物提取折旧；专利权等其他无形资产，按照受益年限摊销，没有明确受益年限的按10年摊销。"},{"i":21,"n":"第二十一条","txt":"材料费、修理费。按照保障水利工程供水设施正常运行的原则，根据剔除不合理因素后的监审期间平均值核定。材料费和修理费用合计原则上不得超过监审期内每年固定资产原值期末数平均值的2%。"},{"i":22,"n":"第二十二条","txt":"大修理费。大修理费按照剔除不合理因素后的监审期间平均值核定；数额较大的，可按照一定年限分摊计入定价成本。其中，供水经营者为事业单位的，可根据水利工程老化状况，按照不超过监审期间最末一年固定资产原值的1.5%核定大修理费；对于老化比较严重、运营存在较大困难的水利工程，大修理费计提比例可以在不超过4%的范围内适当提高。 事业单位供水经营者计提大修理费的，应当单独设置账户归集并记录大修理相关支出情况。大修理费专款专用于工程修理维护；有用于其他用途的，大修理费不得计入定价成本，以往年度计提的大修理费也应当从定价成本中冲减。"},{"i":23,"n":"第二十三条","txt":"原水费。按照监审期间实际发生费用平均值计入定价成本。原水费明显过高的可以对提供原水的单位进行成本调查并予以核定。"},{"i":24,"n":"第二十四条","txt":"职工薪酬。职工工资原则上按照监审期间最末一年的实际值核定。政府有关部门对供水经营者进行工资管理的，职工工资总额不得超过政府有关部门核定的数值；政府有关部门没有进行工资管理的，职工平均工资按照不超过统计部门统计的当地水利管理行业或相关行业职工平均工资水平核定。职工人数按照实际在岗职工人数核定，政府有关部门有明确规定的，不得超过其规定人数。因解除与职工劳动关系所给予的补偿，按照一定年限分摊计入相应科目。 工会经费、职工教育经费、职工福利费、社会保险费（包括补充医疗和补充养老保险）、住房公积金，计算基数原则上按照监审期间最末一年实缴基数核定，但不得超过核定的工资总额和当地政府规定的基数，计提比例不高于国家或地方规定的比例。"},{"i":25,"n":"第二十五条","txt":"销售费用、管理费用。按照保障水利工程供水设施正常运行的原则，根据剔除不合理因素后的监审期间平均值核定。销售费用和管理费用不包含固定资产折旧费、无形资产摊销费和职工薪酬。"},{"i":26,"n":"第二十六条","txt":"其他运行维护费。根据剔除不合理因素后的监审期间平均值核定。"},{"i":27,"n":"第二十七条","txt":"纳入定价成本的相关税金。按照现行国家税法规定计算的监审期间平均值核定。"},{"i":28,"n":"第二十八条","txt":"下列费用不得计入定价成本： （一）不符合《中华人民共和国会计法》等有关法律、行政法规、财务制度和国家统一的会计制度规定的费用，以及价格监管制度等的费用； （二）与水利工程供水生产经营过程无关的费用； （三）虽与水利工程供水生产经营过程有关，但有专项资金来源予以补偿的费用； （四）固定资产盘亏、毁损、闲置和出售的净损失； （五）向上级公司或者管理部门上交的利润性质的管理费用、代上级公司或者管理部门缴纳的各项费用、向出资人支付的利润分成以及对附属单位的补助支出等； （六）各类捐赠、赞助、滞纳金、违约金、罚款，以及计提的准备金； （七）各类广告、宣传费用（不包括安全警示宣传费用）； （八）其他不合理费用。"},{"i":29,"n":"第二十九条","txt":"水利工程供水成本分类归集，不能直接归集的，按照要求在各类业务之间进行分摊。长距离引调水水利工程成本按照“受益者分摊”的原则，分区段或口门归集分摊。"},{"i":30,"n":"第三十条","txt":"供水经营者应当采取合理方法分别核定经营性业务成本和公益性业务成本。 供水经营者单独核算公益性业务和经营性业务且相关成本费用核算分摊合理的，按照供水经营者核算值确定公益性和经营性业务成本；未单独核算或者成本费用分摊不合理的，按照库容量等对总成本进行分摊，并核定公益性成本（防洪、排涝等）和经营性成本。 其中，总成本是指核定的未剔除政府补助部分的总成本，包含公共基础设施计提折旧。"},{"i":31,"n":"第三十一条","txt":"水利工程供水成本中由政府投入形成的部分，应当区分供水经营者属性，按照顺序冲减各类业务成本。 （一）供水经营者为事业单位的，财政补助形成固定资产、无形资产及当期费用的，计入成本的部分先冲减公益性成本再冲减经营性成本。 （二）供水经营者为企业的，供水经营者获得的与水利工程有关的政府投资和补助补贴（形成政府资本金的除外）形成固定资产、无形资产和当期费用的，计入定价成本的部分冲减水利工程总成本。"},{"i":32,"n":"第三十二条","txt":"供水经营者供水同时也有发电业务的，发电业务和供水业务按照监审期间应收平均收入比例分摊经营性成本。"},{"i":33,"n":"第三十三条","txt":"其他业务成本应当单独核算，不计入供水成本。其他业务与水利工程供水业务共同使用资产、人员或者统一支付费用，依托主营业务从事生产经营活动，以及因从事主营业务而获得政府优惠政策，不能单独核算或者核算成本不合理的，应当将其他业务收入按照一定比例冲减供水成本。"},{"i":34,"n":"第三十四条","txt":"供水力发电用水和生态用水业务收入应当冲减供水业务成本。"},{"i":35,"n":"第三十五条","txt":"水利工程供水定价成本以供水经营者为单位核定，水利工程供水定价不以供水经营者为单位定价的，相关定价成本应当结合定价需要合理确定成本核定单位。"},{"i":36,"n":"第三十六条","txt":"核定售水量为监审期间年平均售水量，有设计供水量的工程，监审周期年平均售水总量低于工程设计供水量60%的，按设计供水量的60%确定。有供水力发电用水和生态用水的，相应水量予以剔除。新建工程在达产过程中，核定售水量按监审期间最末两年平均售水量且不低于设计供水量的60%确定。原有工程因上游来水、用水需求发生较大变化导致实际售水量较多低于设计供水量的，可视情调整核定售水量，保障工程运行维护需要。"},{"i":37,"n":"第三十七条","txt":"可计提收益的供水有效资产为供水经营者投入且与供水业务相关的允许计提投资回报的资产，包括固定资产净值、无形资产净值和营运资本。以下资产不得纳入可计提收益的供水有效资产范围： （一）与供水业务无关的资产； （二）未投入实际使用的资产； （三）不能提供价值有效证明的资产； （四）由用户或政府无偿移交、社会无偿投入及除政府资本金注入之外的其他政府投资和补助补贴的资产； （五）1994年财政部清产核资资产价值重估之后评估增值部分的资产； （六）其他不应当计提收益的固定资产、无形资产和营运资本。"},{"i":38,"n":"第三十八条","txt":"可计提收益的固定资产（无形资产）净值，暂按监审期间最末一年可计提收益的固定资产（无形资产）原值减去核定的累计折旧额（摊销额）核定。自本办法实施后该水利工程第二个监审周期起，按监审期间最末一年可计提收益的固定资产（无形资产）原值所对应的账面净值核定。"},{"i":39,"n":"第三十九条","txt":"可计提收益的营运资本，指供水经营者为提供供水服务，除固定资产和无形资产投资以外的正常运营所需要的周转资金。营运资本按照不高于核定的运行维护费（扣除原水费）除以监审期间最末一年流动资产周转次数核定。"},{"i":40,"n":"第四十条","txt":"供水经营者应当自收到成本监审书面通知之日起20个工作日内，提供定价成本监审所需资料，并对资料的真实性、合法性、完整性负责。所需资料应当包括下列内容： （一）经会计师事务所审计或者政府有关部门审核的年度财务报告，以及手续齐备的会计凭证、账簿，费用支出、收入明细账，监审期间内各年末最末级科目余额表； （二）按照要求和规定表式填报的成本报表，主要成本项目的核算方法、成本费用分摊方法及相关依据； （三）渠首供水量、最末端计量点实际供水量、产权分界点或交水断面计量售水量以及水量相关的统计报表； （四）营业执照或准许经营许可证等能够说明经营范围的相关证明材料； （五）水利工程设施分布、结构、规划示意图； （六）成本监审所需的其他资料。"},{"i":41,"n":"第四十一条","txt":"供水经营者应当按照成本监审要求，向监审人员开放查询各类资料的权限，及时提供情况，反馈意见。供水经营者拒绝提供、未在规定时间内提供、虚假或不完整提供成本监审所需资料的，国务院价格主管部门责令限期改正，到期未改正的，可按照从低原则核定定价成本，由此产生的定价成本减少不能在以后成本监审周期内进行弥补。"},{"i":42,"n":"第四十二条","txt":"各省（自治区、直辖市）价格主管部门可以参照本办法，对本省（自治区、直辖市）骨干水利工程供水经营者实施定价成本监审，或商水行政主管部门参照本办法并结合本地实际情况，制定本省（自治区、直辖市）水利工程供水定价成本监审办法。"},{"i":43,"n":"第四十三条","txt":"本办法由国务院价格主管部门负责解释。"},{"i":44,"n":"第四十四条","txt":"本办法自2023年4月1日起施行。本办法发布前国家发展改革委、水利部有关规定与本办法不符的，以本办法为准。国家发展改革委、水利部2006年发布的《水利工程供水定价成本监审办法（试行）》（发改价格〔2006〕310号）同时废止。 附件：水利工程固定资产折旧年限表 附件"}],"shuixiaobiaoshiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为推动节水技术进步，提高用水产品水效，促进节水产品推广，依据《中华人民共和国水法》、《中华人民共和国产品质量法》、《中华人民共和国进出口商品检验法》、《中华人民共和国循环经济促进法》和《中华人民共和国计量法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称水效标识，是指采用企业自我声明和信息备案的方式，表示用水产品水效等级等性能的一种符合性标志。"},{"i":3,"n":"第三条","txt":"国家对节水潜力大、使用面广的用水产品实行水效标识制度，国家发展和改革委员会（以下简称国家发展改革委）、水利部、国家质量监督检验检疫总局（以下简称国家质检总局）按照部门职责分工，负责水效标识制度的建立并组织实施。"},{"i":4,"n":"第四条","txt":"国家发展改革委、水利部、国家质检总局和国家认证认可监督管理委员会（以下简称国家认监委）制定并公布《中华人民共和国实施水效标识的产品目录》（以下简称《目录》），确定适用的产品范围和依据的水效标准。"},{"i":5,"n":"第五条","txt":"地方各级发展改革部门、水行政主管部门、质量技术监督部门和出入境检验检疫机构（以下简称地方质检部门），在各自的职责范围内对水效标识制度的实施开展监督检查。"},{"i":6,"n":"第六条","txt":"列入《目录》产品的生产者和进口商应当向国家质检总局、国家发展改革委和水利部共同授权的中国标准化研究院（以下简称授权机构）备案水效标识及相关信息。"},{"i":7,"n":"第七条","txt":"国家发展改革委、水利部、国家质检总局和国家认监委会同有关部门制定产品水效标识实施规则，确定统一的水效标识样式和规格。"},{"i":8,"n":"第八条","txt":"凡列入《目录》的产品，应当在产品或者产品最小包装的明显部位标注水效标识，并在产品使用说明书中予以说明。对于网络交易，销售者应当在产品信息展示主页面醒目位置展示相应的水效标识。"},{"i":9,"n":"第九条","txt":"列入《目录》产品的生产者和进口商，可以利用自有检验检测实验室或者委托依法取得资质认定的第三方检验检测机构，依据相关产品水效强制性国家标准进行检验检测，确定产品水效等级。 企业自有检验检测实验室应当依据相关产品水效强制性国家标准规定的检测方法和要求进行检测，如实出具产品水效检验检测报告。 第三方检验检测机构接受生产者和进口商的委托，应当依据相关产品水效强制性国家标准规定的检测方法和要求进行检测，保证检验检测结果客观公正，保守受检产品和企业的商业秘密，并承担相应法律责任。 出具产品水效检验检测报告的实验室应当按照国家有关规定参加水效能力验证或者比对。"},{"i":10,"n":"第十条","txt":"利用自有检验检测实验室确定水效等级的生产者和进口商，应当保证其检验检测实验室具备按照水效强制性国家标准进行检验检测的能力，检验检测实验室应当对其出具的检验检测报告负责，检验检测设备应当按照有关规定进行检定或校准，并鼓励其取得国家认可机构的认可。"},{"i":11,"n":"第十一条","txt":"生产者和进口商应当根据国家统一规定的水效标识样式（基本样式见附件）、规格以及标注规定，印制和使用水效标识。 在产品包装物、说明书、广告宣传以及网络商品交易产品信息展示主页面中使用的水效标识，可按比例放大或者缩小，并清晰可辨。"},{"i":12,"n":"第十二条","txt":"水效标识应当包括以下基本内容： （一）中文名称“中国水效标识”； （二）英文名称“China  Water  Efficiency  Label”； （三）生产者名称或者简称； （四）产品规格型号； （五）水效等级； （六）水效指标； （七）依据的水效强制性国家标准编号； （八）水效信息码。"},{"i":13,"n":"第十三条","txt":"列入《目录》的产品，应当于出厂前或者入境前加施水效标识。生产者应当于产品出厂前、进口商应当于产品入境前向授权机构提交完整备案材料，并申请水效标识备案，申请备案应当提供以下材料： （一）生产者营业执照或者登记注册证明复制件；进口商营业执照以及与境外生产者订立的相关合同复制件； （二）产品水效检验检测报告； （三）水效标识样本； （四）产品基本配置清单等有关材料； （五）利用自有检验检测实验室进行检验检测的，应当提供其检验检测能力证明材料，包括实验室人员能力、设备能力和检验检测管理规范等，已经获得国家认可机构认可的，还应当提供相应认可证书及附件复制件；利用第三方检验检测机构进行检验检测的，应当提供检验检测机构的资质认定证书及附件复制件； （六）由代理人提交备案材料的，应当有生产者或者进口商的委托代理文件等。 上述材料应当真实、准确、完整。 外文材料应当附有中文译本，并以中文文本为准。"},{"i":14,"n":"第十四条","txt":"水效标识内容发生变化的，应当重新备案。"},{"i":15,"n":"第十五条","txt":"授权机构应当对生产者和进口商使用的水效标识及产品水效检验检测报告进行形式核验。"},{"i":16,"n":"第十六条","txt":"授权机构应当自收到完整备案材料之日起10个工作日内完成水效标识的备案形式核验工作。 授权机构应当在备案的形式核验通过之日起5个工作日内公告备案信息。 水效标识备案不收取费用，企业提交备案材料应保存不少于两年。"},{"i":17,"n":"第十七条","txt":"质检部门对列入《目录》的产品依法进行水效标识监督检查、专项检查和验证管理。地方质检部门将检查结果通报同级发展改革部门和水行政主管部门，并通知授权机构。"},{"i":18,"n":"第十八条","txt":"授权机构不得对水效标识不合格产品生产者或者进口商的相关备案信息予以备案。对已备案的应当予以撤销并及时公告。"},{"i":19,"n":"第十九条","txt":"列入《目录》产品的生产者、销售者（含网络商品经营者）、第三方交易平台（场所）经营者、企业自有检验检测部门和第三方检验检测机构等应当接受监督检查、专项检查和验证管理。"},{"i":20,"n":"第二十条","txt":"列入《目录》产品的生产者和进口商应当对其使用的水效标识信息真实性和准确性负责，不得伪造或者冒用水效标识。"},{"i":21,"n":"第二十一条","txt":"销售者（含网络商品经营者）应当建立并执行进货检查验收制度，对列入《目录》的产品，验明产品水效标识，不得销售应当标注但未标注水效标识的产品，不得伪造或者冒用水效标识。 第三方交易平台（场所）经营者对通过平台（场所）销售的列入《目录》的产品应当建立水效标识检查监控制度，发现有违反本办法规定的行为应当及时采取措施制止。"},{"i":22,"n":"第二十二条","txt":"授权机构应当建立规范的工作制度，客观、公正开展备案工作，保守备案产品和企业的商业秘密。授权机构应当定期向国家发展改革委、水利部和国家质检总局报告水效标识的实施情况。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人不得利用水效标识对其产品进行虚假宣传，误导消费者。"},{"i":24,"n":"第二十四条","txt":"任何单位和个人对违反本办法的行为，可以向地方质检部门举报。有关部门应当及时调查处理，并为举报人保密，授权机构应当给予配合。"},{"i":25,"n":"第二十五条","txt":"国家发展改革委、水利部和国家质检总局对违反本办法规定的行为建立信用记录，并纳入全国统一的信用信息共享平台。"},{"i":26,"n":"第二十六条","txt":"在用水产品中掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的，或者进口属于掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的，利用水效标识进行虚假宣传的，依据《中华人民共和国产品质量法》、《中华人民共和国进出口商品检验法》以及其他法律法规的规定予以处罚。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，生产者或者进口商未办理水效标识备案，或者应当办理变更手续而未办理的，予以通报；有下列情形之一的，予以通报，并处一万元以上三万元以下罚款： （一）应当标注水效标识而未标注的； （二）使用不符合规定的水效标识的； （三）伪造、冒用水效标识的。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，销售者（含网络商品经营者）有下列情形之一的，予以通报，并处一万元以上三万元以下罚款： （一）销售应当标注但未标注水效标识的产品的； （二）销售使用不符合规定的水效标识的产品的； （三）在网络交易产品信息主页面展示的水效标识不符合规定的； （四）伪造、冒用水效标识的。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，第三方检验检测机构、企业自有检验检测实验室，在水效检验检测中伪造检验检测结果或者出具虚假水效检验检测报告，以及水效能力验证或者比对结果不符合规定的，依据《中华人民共和国产品质量法》、《检验检测机构资质认定管理办法》进行处罚，授权机构在一年内不再采信其检验检测结果。"},{"i":30,"n":"第三十条","txt":"从事水效标识管理的国家工作人员及授权机构工作人员，玩忽职守、滥用职权、包庇放纵违法行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"对外国驻华使领馆自用、样品检测等特殊情况的列入《目录》的产品，可以免于加施水效标识及备案，具体要求和程序另行规定。"},{"i":32,"n":"第三十二条","txt":"本办法由国家发展改革委、水利部和国家质检总局负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2018年3月1日起施行。 附件 水效标识基本样式 各类产品水效标识样式和内容会根据产品的实际情况，对标识尺寸、水效等级、标注内容、依据标准号等进行调整，在产品水效标识实施规则进行明确规定。"}],"shuixiaobiaoshiguanlibanfa-3":[{"i":1,"n":"第一条","txt":"为推动节水技术进步，提高用水产品水效，促进节水产品推广，依据《中华人民共和国水法》、《中华人民共和国产品质量法》、《中华人民共和国进出口商品检验法》、《中华人民共和国循环经济促进法》和《中华人民共和国计量法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称水效标识，是指采用企业自我声明和信息备案的方式，表示用水产品水效等级等性能的一种符合性标志。"},{"i":3,"n":"第三条","txt":"国家对节水潜力大、使用面广的用水产品实行水效标识制度，国家发展和改革委员会(以下简称国家发展改革委)、水利部、国家质量监督检验检疫总局(以下简称国家质检总局)按照部门职责分工，负责水效标识制度的建立并组织实施。"},{"i":4,"n":"第四条","txt":"国家发展改革委、水利部、国家质检总局和国家认证认可监督管理委员会(以下简称国家认监委)制定并公布《中华人民共和国实施水效标识的产品目录》(以下简称《目录》)，确定适用的产品范围和依据的水效标准。"},{"i":5,"n":"第五条","txt":"地方各级发展改革部门、水行政主管部门、质量技术监督部门和出入境检验检疫机构(以下简称地方质检部门)，在各自的职责范围内对水效标识制度的实施开展监督检查。"},{"i":6,"n":"第六条","txt":"列入《目录》产品的生产者和进口商应当向国家质检总局、国家发展改革委和水利部共同授权的中国标准化研究院(以下简称授权机构)备案水效标识及相关信息。"},{"i":7,"n":"第七条","txt":"国家发展改革委、水利部、国家质检总局和国家认监委会同有关部门制定产品水效标识实施规则，确定统一的水效标识样式和规格。"},{"i":8,"n":"第八条","txt":"凡列入《目录》的产品，应当在产品或者产品最小包装的明显部位标注水效标识，并在产品使用说明书中予以说明。对于网络交易，销售者应当在产品信息展示主页面醒目位置展示相应的水效标识。"},{"i":9,"n":"第九条","txt":"列入《目录》产品的生产者和进口商，可以利用自有检验检测实验室或者委托依法取得资质认定的第三方检验检测机构，依据相关产品水效强制性国家标准进行检验检测，确定产品水效等级。 企业自有检验检测实验室应当依据相关产品水效强制性国家标准规定的检测方法和要求进行检测，如实出具产品水效检验检测报告。 第三方检验检测机构接受生产者和进口商的委托，应当依据相关产品水效强制性国家标准规定的检测方法和要求进行检测，保证检验检测结果客观公正，保守受检产品和企业的商业秘密，并承担相应法律责任。 出具产品水效检验检测报告的实验室应当按照国家有关规定参加水效能力验证或者比对。"},{"i":10,"n":"第十条","txt":"利用自有检验检测实验室确定水效等级的生产者和进口商，应当保证其检验检测实验室具备按照水效强制性国家标准进行检验检测的能力，检验检测实验室应当对其出具的检验检测报告负责，检验检测设备应当按照有关规定进行检定或校准，并鼓励其取得国家认可机构的认可。"},{"i":11,"n":"第十一条","txt":"生产者和进口商应当根据国家统一规定的水效标识样式(基本样式见附件)、规格以及标注规定，印制和使用水效标识。 在产品包装物、说明书、广告宣传以及网络商品交易产品信息展示主页面中使用的水效标识，可按比例放大或者缩小，并清晰可辨。"},{"i":12,"n":"第十二条","txt":"水效标识应当包括以下基本内容： (一)中文名称“中国水效标识”; (二)英文名称“China Water Efficiency Label”; (三)生产者名称或者简称; (四)产品规格型号; (五)水效等级; (六)水效指标; (七)依据的水效强制性国家标准编号; (八)水效信息码。"},{"i":13,"n":"第十三条","txt":"列入《目录》的产品，应当于出厂前或者入境前加施水效标识。生产者应当于产品出厂前、进口商应当于产品入境前向授权机构提交完整备案材料，并申请水效标识备案，申请备案应当提供以下材料： (一)生产者营业执照或者登记注册证明复制件;进口商营业执照以及与境外生产者订立的相关合同复制件; (二)产品水效检验检测报告; (三)水效标识样本; (四)产品基本配置清单等有关材料; (五)利用自有检验检测实验室进行检验检测的，应当提供其检验检测能力证明材料，包括实验室人员能力、设备能力和检验检测管理规范等，已经获得国家认可机构认可的，还应当提供相应认可证书及附件复制件;利用第三方检验检测机构进行检验检测的，应当提供检验检测机构的资质认定证书及附件复制件; (六)由代理人提交备案材料的，应当有生产者或者进口商的委托代理文件等。 上述材料应当真实、准确、完整。 外文材料应当附有中文译本，并以中文文本为准。"},{"i":14,"n":"第十四条","txt":"水效标识内容发生变化的，应当重新备案。"},{"i":15,"n":"第十五条","txt":"授权机构应当对生产者和进口商使用的水效标识及产品水效检验检测报告进行形式核验。"},{"i":16,"n":"第十六条","txt":"授权机构应当自收到完整备案材料之日起10个工作日内完成水效标识的备案形式核验工作。 授权机构应当在备案的形式核验通过之日起5个工作日内公告备案信息。 水效标识备案不收取费用，企业提交备案材料应保存不少于两年。"},{"i":17,"n":"第十七条","txt":"质检部门对列入《目录》的产品依法进行水效标识监督检查、专项检查和验证管理。地方质检部门将检查结果通报同级发展改革部门和水行政主管部门，并通知授权机构。"},{"i":18,"n":"第十八条","txt":"授权机构不得对水效标识不合格产品生产者或者进口商的相关备案信息予以备案。对已备案的应当予以撤销并及时公告。"},{"i":19,"n":"第十九条","txt":"列入《目录》产品的生产者、销售者(含网络商品经营者)、第三方交易平台(场所)经营者、企业自有检验检测部门和第三方检验检测机构等应当接受监督检查、专项检查和验证管理。"},{"i":20,"n":"第二十条","txt":"列入《目录》产品的生产者和进口商应当对其使用的水效标识信息真实性和准确性负责，不得伪造或者冒用水效标识。"},{"i":21,"n":"第二十一条","txt":"销售者(含网络商品经营者)应当建立并执行进货检查验收制度，对列入《目录》的产品，验明产品水效标识，不得销售应当标注但未标注水效标识的产品，不得伪造或者冒用水效标识。 第三方交易平台(场所)经营者对通过平台(场所)销售的列入《目录》的产品应当建立水效标识检查监控制度，发现有违反本办法规定的行为应当及时采取措施制止。"},{"i":22,"n":"第二十二条","txt":"授权机构应当建立规范的工作制度，客观、公正开展备案工作，保守备案产品和企业的商业秘密。授权机构应当定期向国家发展改革委、水利部和国家质检总局报告水效标识的实施情况。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人不得利用水效标识对其产品进行虚假宣传，误导消费者。"},{"i":24,"n":"第二十四条","txt":"任何单位和个人对违反本办法的行为，可以向地方质检部门举报。有关部门应当及时调查处理，并为举报人保密，授权机构应当给予配合。"},{"i":25,"n":"第二十五条","txt":"国家发展改革委、水利部和国家质检总局对违反本办法规定的行为建立信用记录，并纳入全国统一的信用信息共享平台。"},{"i":26,"n":"第二十六条","txt":"在用水产品中掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的，或者进口属于掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的，利用水效标识进行虚假宣传的，依据《中华人民共和国产品质量法》、《中华人民共和国进出口商品检验法》以及其他法律法规的规定予以处罚。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，生产者或者进口商未办理水效标识备案，或者应当办理变更手续而未办理的，予以通报;有下列情形之一的，予以通报，并处一万元以上三万元以下罚款： (一)应当标注水效标识而未标注的; (二)使用不符合规定的水效标识的; (三)伪造、冒用水效标识的。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，销售者(含网络商品经营者)有下列情形之一的，予以通报，并处一万元以上三万元以下罚款： (一)销售应当标注但未标注水效标识的产品的; (二)销售使用不符合规定的水效标识的产品的; (三)在网络交易产品信息主页面展示的水效标识不符合规定的; (四)伪造、冒用水效标识的。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，第三方检验检测机构、企业自有检验检测实验室，在水效检验检测中伪造检验检测结果或者出具虚假水效检验检测报告，以及水效能力验证或者比对结果不符合规定的，依据《中华人民共和国产品质量法》、《检验检测机构资质认定管理办法》进行处罚，授权机构在一年内不再采信其检验检测结果。"},{"i":30,"n":"第三十条","txt":"从事水效标识管理的国家工作人员及授权机构工作人员，玩忽职守、滥用职权、包庇放纵违法行为的，依法给予处分;构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"对外国驻华使领馆自用、样品检测等特殊情况的列入《目录》的产品，可以免于加施水效标识及备案，具体要求和程序另行规定。"},{"i":32,"n":"第三十二条","txt":"本办法由国家发展改革委、水利部和国家质检总局负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2018年3月1日起施行。 附件 水效标识基本样式 各类产品水效标识样式和内容会根据产品的实际情况，对标识尺寸、水效等级、标注内容、依据标准号等进行调整，在产品水效标识实施规则进行明确规定。 水效标识管理办法 水效标识管理办法 水效标识管理办法"}],"shuixiaobiaoshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为推动节水技术进步，提高用水产品水效，促进节水产品推广，依据《中华人民共和国水法》、《中华人民共和国产品质量法》、《中华人民共和国进出口商品检验法》、《中华人民共和国循环经济促进法》和《中华人民共和国计量法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称水效标识，是指采用企业自我声明和信息备案的方式，表示用水产品水效等级等性能的一种符合性标志。"},{"i":3,"n":"第三条","txt":"国家对节水潜力大、使用面广的用水产品实行水效标识制度，国家发展和改革委员会（以下简称国家发展改革委）、水利部、国家质量监督检验检疫总局（以下简称国家质检总局）按照部门职责分工，负责水效标识制度的建立并组织实施。"},{"i":4,"n":"第四条","txt":"国家发展改革委、水利部、国家质检总局和国家认证认可监督管理委员会（以下简称国家认监委）制定并公布《中华人民共和国实施水效标识的产品目录》（以下简称《目录》），确定适用的产品范围和依据的水效标准。"},{"i":5,"n":"第五条","txt":"地方各级发展改革部门、水行政主管部门、质量技术监督部门和出入境检验检疫机构（以下简称地方质检部门），在各自的职责范围内对水效标识制度的实施开展监督检查。"},{"i":6,"n":"第六条","txt":"列入《目录》产品的生产者和进口商应当向国家质检总局、国家发展改革委和水利部共同授权的中国标准化研究院（以下简称授权机构）备案水效标识及相关信息。"},{"i":7,"n":"第七条","txt":"国家发展改革委、水利部、国家质检总局和国家认监委会同有关部门制定产品水效标识实施规则，确定统一的水效标识样式和规格。"},{"i":8,"n":"第八条","txt":"凡列入《目录》的产品，应当在产品或者产品最小包装的明显部位标注水效标识，并在产品使用说明书中予以说明。对于网络交易，销售者应当在产品信息展示主页面醒目位置展示相应的水效标识。"},{"i":9,"n":"第九条","txt":"列入《目录》产品的生产者和进口商，可以利用自有检验检测实验室或者委托依法取得资质认定的第三方检验检测机构，依据相关产品水效强制性国家标准进行检验检测，确定产品水效等级。 企业自有检验检测实验室应当依据相关产品水效强制性国家标准规定的检测方法和要求进行检测，如实出具产品水效检验检测报告。 第三方检验检测机构接受生产者和进口商的委托，应当依据相关产品水效强制性国家标准规定的检测方法和要求进行检测，保证检验检测结果客观公正，保守受检产品和企业的商业秘密，并承担相应法律责任。 出具产品水效检验检测报告的实验室应当按照国家有关规定参加水效能力验证或者比对。"},{"i":10,"n":"第十条","txt":"利用自有检验检测实验室确定水效等级的生产者和进口商，应当保证其检验检测实验室具备按照水效强制性国家标准进行检验检测的能力，检验检测实验室应当对其出具的检验检测报告负责，检验检测设备应当按照有关规定进行检定或校准，并鼓励其取得国家认可机构的认可。"},{"i":11,"n":"第十一条","txt":"生产者和进口商应当根据国家统一规定的水效标识样式（基本样式见附件）、规格以及标注规定，印制和使用水效标识。 在产品包装物、说明书、广告宣传以及网络商品交易产品信息展示主页面中使用的水效标识，可按比例放大或者缩小，并清晰可辨。"},{"i":12,"n":"第十二条","txt":"水效标识应当包括以下基本内容： （一）中文名称“中国水效标识”； （二）英文名称“China Water Efficiency Label”； （三）生产者名称或者简称； （四）产品规格型号； （五）水效等级； （六）水效指标； （七）依据的水效强制性国家标准编号； （八）水效信息码。"},{"i":13,"n":"第十三条","txt":"列入《目录》的产品，应当于出厂前或者入境前加施水效标识。生产者应当于产品出厂前、进口商应当于产品入境前向授权机构提交完整备案材料，并申请水效标识备案，申请备案应当提供以下材料： （一）生产者营业执照或者登记注册证明复制件；进口商营业执照以及与境外生产者订立的相关合同复制件； （二）产品水效检验检测报告； （三）水效标识样本； （四）产品基本配置清单等有关材料； （五）利用自有检验检测实验室进行检验检测的，应当提供其检验检测能力证明材料，包括实验室人员能力、设备能力和检验检测管理规范等，已经获得国家认可机构认可的，还应当提供相应认可证书及附件复制件；利用第三方检验检测机构进行检验检测的，应当提供检验检测机构的资质认定证书及附件复制件； （六）由代理人提交备案材料的，应当有生产者或者进口商的委托代理文件等。 上述材料应当真实、准确、完整。 外文材料应当附有中文译本，并以中文文本为准。"},{"i":14,"n":"第十四条","txt":"水效标识内容发生变化的，应当重新备案。"},{"i":15,"n":"第十五条","txt":"授权机构应当对生产者和进口商使用的水效标识及产品水效检验检测报告进行形式核验。"},{"i":16,"n":"第十六条","txt":"授权机构应当自收到完整备案材料之日起10个工作日内完成水效标识的备案形式核验工作。 授权机构应当在备案的形式核验通过之日起5个工作日内公告备案信息。 水效标识备案不收取费用，企业提交备案材料应保存不少于两年。"},{"i":17,"n":"第十七条","txt":"质检部门对列入《目录》的产品依法进行水效标识监督检查、专项检查和验证管理。地方质检部门将检查结果通报同级发展改革部门和水行政主管部门，并通知授权机构。"},{"i":18,"n":"第十八条","txt":"授权机构不得对水效标识不合格产品生产者或者进口商的相关备案信息予以备案。对已备案的应当予以撤销并及时公告。"},{"i":19,"n":"第十九条","txt":"列入《目录》产品的生产者、销售者（含网络商品经营者）、第三方交易平台（场所）经营者、企业自有检验检测部门和第三方检验检测机构等应当接受监督检查、专项检查和验证管理。"},{"i":20,"n":"第二十条","txt":"列入《目录》产品的生产者和进口商应当对其使用的水效标识信息真实性和准确性负责，不得伪造或者冒用水效标识。"},{"i":21,"n":"第二十一条","txt":"销售者（含网络商品经营者）应当建立并执行进货检查验收制度，对列入《目录》的产品，验明产品水效标识，不得销售应当标注但未标注水效标识的产品，不得伪造或者冒用水效标识。 第三方交易平台（场所）经营者对通过平台（场所）销售的列入《目录》的产品应当建立水效标识检查监控制度，发现有违反本办法规定的行为应当及时采取措施制止。"},{"i":22,"n":"第二十二条","txt":"授权机构应当建立规范的工作制度，客观、公正开展备案工作，保守备案产品和企业的商业秘密。授权机构应当定期向国家发展改革委、水利部和国家质检总局报告水效标识的实施情况。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人不得利用水效标识对其产品进行虚假宣传，误导消费者。"},{"i":24,"n":"第二十四条","txt":"任何单位和个人对违反本办法的行为，可以向地方质检部门举报。有关部门应当及时调查处理，并为举报人保密，授权机构应当给予配合。"},{"i":25,"n":"第二十五条","txt":"国家发展改革委、水利部和国家质检总局对违反本办法规定的行为建立信用记录，并纳入全国统一的信用信息共享平台。"},{"i":26,"n":"第二十六条","txt":"在用水产品中掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的，或者进口属于掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的，利用水效标识进行虚假宣传的，依据《中华人民共和国产品质量法》、《中华人民共和国进出口商品检验法》以及其他法律法规的规定予以处罚。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，生产者或者进口商未办理水效标识备案，或者应当办理变更手续而未办理的，予以通报；有下列情形之一的，予以通报，并处一万元以上三万元以下罚款： （一）应当标注水效标识而未标注的； （二）使用不符合规定的水效标识的； （三）伪造、冒用水效标识的。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，销售者（含网络商品经营者）有下列情形之一的，予以通报，并处一万元以上三万元以下罚款： （一）销售应当标注但未标注水效标识的产品的； （二）销售使用不符合规定的水效标识的产品的； （三）在网络交易产品信息主页面展示的水效标识不符合规定的； （四）伪造、冒用水效标识的。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，第三方检验检测机构、企业自有检验检测实验室，在水效检验检测中伪造检验检测结果或者出具虚假水效检验检测报告，以及水效能力验证或者比对结果不符合规定的，依据《中华人民共和国产品质量法》、《检验检测机构资质认定管理办法》进行处罚，授权机构在一年内不再采信其检验检测结果。"},{"i":30,"n":"第三十条","txt":"从事水效标识管理的国家工作人员及授权机构工作人员，玩忽职守、滥用职权、包庇放纵违法行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"对外国驻华使领馆自用、样品检测等特殊情况的列入《目录》的产品，可以免于加施水效标识及备案，具体要求和程序另行规定。"},{"i":32,"n":"第三十二条","txt":"本办法由国家发展改革委、水利部和国家质检总局负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2018年3月1日起施行。"}],"shuidianzhandabayunxinganquanjianduguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强水电站大坝运行安全监督管理，保障人民生命财产安全，促进经济社会持续健康安全发展，根据《中华人民共和国安全生产法》、《水库大坝安全管理条例》、《电力监管条例》、《生产安全事故报告和调查处理条例》、《电力安全事故应急处置和调查处理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"水电站大坝运行安全管理应当坚持安全第一、预防为主、综合治理的方针。"},{"i":3,"n":"第三条","txt":"本规定适用于以发电为主、总装机容量五万千瓦及以上的大、中型水电站大坝(以下简称大坝)。 本规定所称大坝，是指包括横跨河床和水库周围垭口的所有永久性挡水建筑物、泄洪建筑物、输水和过船建筑物的挡水结构以及这些建筑物与结构的地基、近坝库岸、边坡和附属设施。"},{"i":4,"n":"第四条","txt":"电力企业是大坝运行安全的责任主体，应当遵守国家有关法律法规和标准规范，建立健全大坝运行安全组织体系和应急工作机制，加强大坝运行全过程安全管理，确保大坝运行安全。"},{"i":5,"n":"第五条","txt":"国家能源局负责大坝运行安全综合监督管理。 国家能源局派出机构(以下简称派出机构)具体负责本辖区大坝运行安全监督管理。 国家能源局大坝安全监察中心(以下简称大坝中心)负责大坝运行安全技术监督管理服务，为国家能源局及其派出机构开展大坝运行安全监督管理提供技术支持。"},{"i":6,"n":"第六条","txt":"电力企业应当保证大坝安全监测系统、泄洪消能和防护设施、应急电源等安全设施与大坝主体工程同时设计、同时施工、同时投入运行。 大坝蓄水验收和枢纽工程专项验收前应当分别经过蓄水安全鉴定和竣工安全鉴定。"},{"i":7,"n":"第七条","txt":"电力企业应当加强大坝安全检查、运行维护与除险加固等工作，保证大坝主体结构完好，大坝安全设施运行可靠。"},{"i":8,"n":"第八条","txt":"电力企业应当加强大坝安全监测与信息化建设工作，及时整理分析监测成果，监控大坝运行安全状态，并且按照要求向大坝中心报送大坝运行安全信息。对坝高一百米以上的大坝、库容一亿立方米以上的大坝和病险坝，电力企业应当建立大坝安全在线监控系统，并且接受大坝中心的监督。"},{"i":9,"n":"第九条","txt":"电力企业应当对大坝进行日常巡视检查。 每年汛期及汛前、汛后，枯水期、冰冻期，遭遇大洪水、发生有感地震或者极端气象等特殊情况，电力企业应当对大坝进行详细检查。 电力企业应当及时处理发现的大坝缺陷和隐患。"},{"i":10,"n":"第十条","txt":"电力企业应当每年年底开展大坝安全年度详查，总结本年度大坝安全管理工作，整编分析大坝监测资料，分析水库、水工建筑物、闸门及启闭机、监测系统和应急电源的运行情况，提出大坝安全年度详查报告并且报送大坝中心。"},{"i":11,"n":"第十一条","txt":"电力企业应当按照国家规定做好水电站防洪度汛工作。 水库调度和发电运行应当以确保大坝运行安全为前提，严格遵循批准的汛期调度运用计划和水库运用与电站运行调度规程。汛期水库汛限水位以上防洪库容的运用，必须服从防汛指挥机构的调度指挥。 汛期发生影响正常泄洪的情况时，电力企业应当及时处置并且报告大坝中心。"},{"i":12,"n":"第十二条","txt":"电力企业应当建立大坝安全应急管理体系，制定大坝安全应急预案，建立与地方政府、相关单位的应急联动机制。 遇有超标准洪水、地震、地质灾害、大体积漂浮物等险情， 电力企业应当按照规定启动大坝安全应急机制，采取必要措施保障大坝安全，并且报告派出机构和大坝中心。"},{"i":13,"n":"第十三条","txt":"任何单位、部门不得擅自改变或者调整水电站原批准的功能。任何改变或者调整水电站功能的方案，应当依法报有关项目核准(或者审批)部门批准。"},{"i":14,"n":"第十四条","txt":"水电站进行工程改造或者扩建，应当依法报有关项目核准(或者审批)部门批准。 大坝枢纽范围内新建、改建或者扩建建筑物，应当按照规定进行大坝安全影响专项论证并且经过大坝安全技术监督单位评审。"},{"i":15,"n":"第十五条","txt":"工程降低等别以及大坝退役(包括大坝报废、拆除或者拆除重建)应当充分论证，经过有关项目核准(或者审批)部门同意后方可以实施。"},{"i":16,"n":"第十六条","txt":"电力企业负责人及相关管理人员应当具备大坝安全专业知识和管理能力，定期培训。 从事大坝运行安全监测、维护及闸门启闭操作的作业人员应当经过相关技术培训，持证上岗。"},{"i":17,"n":"第十七条","txt":"电力企业应当按照国家规定及时收集、整理和保存大坝建设工程档案、运行维护资料及相应原始记录。"},{"i":18,"n":"第十八条","txt":"电力企业委托大坝运行安全专业技术服务单位承担大坝运行安全分析、监测、测试、检验、检查、维护等具体工作的，大坝运行安全责任仍由委托方承担。 国家对专业技术服务有资质要求的，承担技术服务的单位应当具有相应资质。"},{"i":19,"n":"第十九条","txt":"大坝中心应当定期检查大坝安全状况，评定大坝安全等级。 定期检查一般每五年进行一次，检查时间一般不超过一年半。首次定期检查后，定期检查间隔可以根据大坝安全风险情况动态调整，但不得少于三年或者超过十年。"},{"i":20,"n":"第二十条","txt":"大坝遭受超标准洪水或者破坏性地震等自然灾害以及其他严重事件后，大坝中心应当对大坝进行特种检查，重新评定大坝安全等级。"},{"i":21,"n":"第二十一条","txt":"大坝安全等级分为正常坝、病坝和险坝三级。 符合下列条件的大坝，评定为正常坝： (一)防洪能力符合规范要求;或者非常运用情况下的防洪能力略有不足，但大坝安全风险低且可控; (二)坝基良好;或者虽然存在局部缺陷但无趋势性恶化，大坝整体安全; (三)大坝结构安全度符合规范要求;或者略有不足，但大坝安全风险低且可控; (四)大坝运行性态总体正常; (五)近坝库岸和工程边坡稳定或者基本稳定。 具有下列情形之一的大坝，评定为病坝： (一)正常运用情况下的防洪能力略有不足，但风险较低;或者非常运用情况下的防洪能力不足，风险较高; (二)坝基存在局部缺陷，且有趋势性恶化，可能危及大坝整体安全; (三)大坝结构安全度不符合规范要求，存在安全风险，可能危及大坝整体安全; (四)大坝运行性态异常，存在安全风险，可能危及大坝安全; (五)近坝库岸和工程边坡有失稳征兆，失稳后影响工程正常运用。 具有下列情形之一"},{"i":22,"n":"第二十二条","txt":"电力企业应当限期完成对病坝、险坝的处理。 病坝、险坝以及正常坝的重大工程缺陷和隐患的处理应当专项设计、专项审查、专项施工和专项验收。"},{"i":23,"n":"第二十三条","txt":"大坝评定为险坝后，电力企业应当立即降低水库运行水位，直至放空水库。病坝消缺前或者消缺过程中，如情况恶化或者发生重大险情，应当降低水库运行水位，极端情况下可以放空水库。"},{"i":24,"n":"第二十四条","txt":"大坝运行实行安全注册登记制度。电力企业应当在规定期限内申请办理大坝安全注册登记。 在规定期限内不申请办理安全注册登记的大坝，不得投入运行，其发电机组不得并网发电。"},{"i":25,"n":"第二十五条","txt":"大坝安全注册应当符合下列条件： (一)依法取得核准(或者审批)手续; (二)新建大坝具有竣工安全鉴定报告及其专题报告;已运行大坝具有近期的定期检查报告和定期检查审查意见; (三)有完整的大坝勘测、设计、施工、监理资料和运行资料; (四)有职责明确的管理机构、符合岗位要求的专业运行人员、健全的大坝安全管理规章制度和操作规程。"},{"i":26,"n":"第二十六条","txt":"大坝中心具体受理大坝安全注册登记申请，组织注册现场检查并且提出注册检查意见，经国家能源局批准后向电力企业颁发大坝安全注册登记证。"},{"i":27,"n":"第二十七条","txt":"大坝安全注册等级分为甲、乙、丙三级。 (一)通过竣工安全鉴定或者安全等级评定为正常坝的， 根据管理实绩考核结果，颁发甲级注册登记证或者乙级注册登记证; (二)安全等级评定为病坝的，管理实绩考核结果满足要求的，颁发丙级注册登记证; (三)安全等级评定为险坝的，在完成除险加固后颁发相应注册登记证。 不满足注册条件或者未取得注册登记证的大坝，电力企业应当在大坝中心登记备案，并且限期完成大坝安全注册。"},{"i":28,"n":"第二十八条","txt":"大坝安全注册实行动态管理。甲级注册登记证有效期为五年，乙级、丙级注册登记证有效期为三年。 注册事项发生变化，电力企业应当及时办理注册变更。 注册登记证有效期满前，电力企业应当申请大坝安全换证注册。期满后逾期六个月仍未申请换证的，注销注册登记证。 工程降低等别应当办理大坝安全注册变更手续;大坝退役应当办理大坝安全注册注销手续。"},{"i":29,"n":"第二十九条","txt":"新建大坝通过蓄水安全鉴定后，在其发电机组转入商业运营前，应当将工程蓄水安全鉴定报告和蓄水验收鉴定书以及有关安全管理情况等报大坝中心备案。"},{"i":30,"n":"第三十条","txt":"国家能源局应当定期公布大坝安全注册登记和定期检查情况。 派出机构应当督促电力企业开展安全注册登记和定期检查工作，并且结合注册现场检查、定期检查等工作对电力企业执行国家有关安全法律法规和标准规范的情况进行监督检查，发现违法违规行为，依法处理;发现重大安全隐患，责令电力企业及时整改。 派出机构应当会同大坝中心对电力企业病坝治理、险坝除险加固等重大安全隐患治理和风险管控工作进行安全督查，督促电力企业按照要求开展相关工作。"},{"i":31,"n":"第三十一条","txt":"大坝中心应当对电力企业大坝安全监测、检查、维护、信息化建设及信息报送等工作进行监督、检查和指导，对大坝安全监测系统进行评价鉴定，对电力企业报送的大坝运行安全信息进行分析处理，对注册(备案)登记的大坝运行安全进行远程在线技术监督。"},{"i":32,"n":"第三十二条","txt":"国家能源局及其派出机构、大坝中心应当依法对大坝退役安全进行监督管理。 国家能源局及其派出机构、大坝中心应当依法组织或者参与大坝溃坝、库水漫坝等运行安全事故的调查处理。"},{"i":33,"n":"第三十三条","txt":"电力企业应当积极配合国家能源局及其派出机构、大坝中心做好大坝安全监督管理工作。"},{"i":34,"n":"第三十四条","txt":"电力企业有下列情形之一的，依据《安全生产法》第九十五条，由派出机构责令停止建设或者停产停业整顿， 限期改正;逾期未改正的，将其列入安全生产不良信用记录和安全生产诚信“黑名单”，处以五十万元以上一百万元以下的罚 款，对其直接负责的主管人员和其他直接责任人员处以二万元以上五万元以下的罚款： (一)大坝安全设施未与主体工程同时设计、同时施工、同时投入运行的; (二)未按照规定组织蓄水安全鉴定和竣工安全鉴定的; (三)未按照规定开展大坝安全定期检查的; (四)擅自改变、调整水电站原批准功能的，擅自进行工程改造或者扩建的，擅自降低工程等别或者实施大坝退役的。"},{"i":35,"n":"第三十五条","txt":"电力企业未按照规定及时开展病坝治理、险坝 除险加固等重大安全隐患治理和风险管控工作的，依据《安全生产法》第九十九条，由派出机构给予警告并且责令限期整改; 拒不整改的，责令停产停业整顿，将其列入安全生产不良信用记录和安全生产诚信“黑名单”，并且处以十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处以二万元以上五万元以下的罚款。"},{"i":36,"n":"第三十六条","txt":"电力企业有下列情形之一的，依据《安全生产法》第九十八条，由派出机构责令限期改正，可以处以十万元以下的罚款;逾期未改正的，责令停产停业整顿，将其列入安全生产不良信用记录和安全生产诚信“黑名单”，并且处以十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处以二万元以上五万元以下的罚款： (一)未在规定期限内办理大坝安全注册登记和备案的; (二)未按照规定制定大坝安全应急预案的。"},{"i":37,"n":"第三十七条","txt":"电力企业未按照规定及时报告大坝险情或者提供虚假报告的，依据《安全生产法》第九十一条，由派出机构对其主要负责人处以二万元以上五万元以下的罚款，将其列入安全生产不良信用记录和安全生产诚信“黑名单”。"},{"i":38,"n":"第三十八条","txt":"电力企业有下列情形之一的，由派出机构给予警告并且责令限期改正;逾期未改正的，可以处以一万元的罚款，并且对其主要负责人处以一万元的罚款： (一)未按照规定开展大坝安全监测、检查、运行维护、年度详查、信息报送和信息化建设的; (二)未按照规定收集、整理、分析和保存大坝运行资料的。"},{"i":39,"n":"第三十九条","txt":"从事大坝安全分析、监测、测试、检验等专业 技术服务的单位，出具虚假材料或者造成事故的，依法追究责任，并且将其列入安全生产不良信用记录和安全生产诚信“黑名单”。"},{"i":40,"n":"第四十条","txt":"大坝中心违反本规定，有下列情形之一的，由国家能源局责令限期改正;逾期未改正的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分： (一)没有正当理由，拒不受理大坝安全注册登记申请和备案的; (二)未经批准，擅自颁发大坝安全注册登记证的; (三)不按照要求开展定期检查和特种检查的。"},{"i":41,"n":"第四十一条","txt":"大坝安全监督管理工作人员未按照本规定履行大坝安全监督管理职责的，由所在单位责令限期改正;存在徇私舞弊、滥用职权、玩忽职守行为的，由所在单位或者上级行政机关依法给予行政处分;构成犯罪的，依法追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"水电站输水隧洞、压力钢管、调压井、发电厂房、尾水隧洞等输水发电建筑物及过坝建筑物及其附属设施应当参照本规定相关要求开展安全检查，发现缺陷及时处理。"},{"i":43,"n":"第四十三条","txt":"对运行大坝进行安全评价等技术服务，依照国家有关规定，实行公示基准价格的有偿服务。"},{"i":44,"n":"第四十四条","txt":"以发电为主、总装机容量小于五万千瓦的大坝运行安全监督管理，参照本规定执行。"},{"i":45,"n":"第四十五条","txt":"大坝安全注册登记、备案、定期检查、除险加固、安全监测、信息报送、信息化建设以及应急管理等方面的具体要求由国家能源局另行制定。"},{"i":46,"n":"第四十六条","txt":"本规定自2015年4月1日起施行。原国家电力监管委员会《水电站大坝运行安全管理规定》同时废止。"}],"qichechanyetouziguanliguiding":[{"i":1,"n":"第一条","txt":"为深入学习贯彻习近平新时代中国特色社会主义思想和党的十九大精神，适应汽车产业改革开放新形势，完善汽车产业投资管理，推动汽车产业高质量发展，依据《行政许可法》《企业投资项目核准和备案管理条例》等相关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"完善汽车产业投资项目准入标准，加强事中事后监管，规范市场主体投资行为，引导社会资本合理投向。严格控制新增传统燃油汽车产能，积极推动新能源汽车健康有序发展，着力构建智能汽车创新发展体系。"},{"i":3,"n":"第三条","txt":"坚持使市场在汽车产业资源配置中起决定性作用，更好发挥政府作用;坚持简政放权、放管结合、优化服务;坚持开放合作、公平竞争;坚持谁投资谁负责、谁审批谁监管、谁主管谁监管。"},{"i":4,"n":"第四条","txt":"本规定适用于各类市场主体在中国境内的汽车投资项目。"},{"i":5,"n":"第五条","txt":"汽车投资项目分为以下类型： (一)汽车整车投资项目按照驱动动力系统分为燃油汽车和纯电动汽车投资项目，包括乘用车和商用车两个产品类别。燃油汽车投资项目是指以发动机提供驱动动力的汽车投资项目(含替代燃料汽车)，包括传统燃油汽车、普通混合动力汽车，以及插电式混合动力汽车等投资项目。纯电动汽车投资项目是指以电动机提供驱动动力的汽车投资项目，包括纯电动汽车(含增程式电动汽车)、燃料电池汽车等投资项目。智能汽车投资项目根据驱动动力系统分别按照燃油汽车或纯电动汽车投资项目管理; (二)其他投资项目包括汽车发动机、动力电池、燃料电池和车身总成等汽车零部件，专用汽车、挂车，以及动力电池回收利用、汽车零部件再制造投资项目。"},{"i":6,"n":"第六条","txt":"汽车整车和其他投资项目均由地方发展改革部门实施备案管理。其中，汽车整车投资项目由省级发展改革部门备案。"},{"i":7,"n":"第七条","txt":"优化燃油汽车产能布局，推动产业向产能利用充分、产业基础扎实、配套体系完善、竞争优势明显的省份聚集。汽车产能利用率低的省份和企业应加大资金投入和兼并重组力度，加快技术进步，淘汰落后产能，增强市场竞争力。"},{"i":8,"n":"第八条","txt":"科学规划新能源汽车产业布局，现有燃油汽车企业应加大研发投入、调整产品结构，发展纯电动汽车、插电式混合动力汽车、燃料电池汽车等新能源汽车。严格新建纯电动汽车企业投资项目管理，防范盲目布点和低水平重复建设。新建纯电动汽车企业及现有企业纯电动汽车扩能项目，应建设在产业基础好、创新要素全、配套能力强、发展空间大的省份及大气污染防治重点区域。推动新增产能向新能源汽车消费需求旺盛和燃油汽车替代潜力较大省份集中。"},{"i":9,"n":"第九条","txt":"聚焦汽车产业发展重点，加快推进新能源汽车、智能汽车、节能汽车及关键零部件，先进制造装备，动力电池回收利用技术、汽车零部件再制造技术及装备研发和产业化。主要包括： (一)新能源汽车领域重点发展非金属复合材料、高强度轻质合金、高强度钢等轻量化材料的车身、零部件和整车，全功能、高性能的整车控制系统，高效驱动系统、先进车用动力电池和燃料电池产品，车用动力电池等制造、检测技术和专用装备; (二)智能汽车领域重点发展复杂环境感知、新型智能终端、车载智能计算平台等关键共性技术，车载传感器、中央处理器、专用芯片、操作系统、无线通讯设备等关键零部件和系统，推动技术研发能力、测试评价能力、军民融合能力、安全保障能力建设; (三)节能汽车领域重点发展高效发动机、先进自动变速器和混合动力系统等节能技术和产品; (四)动力电池回收利用领域重点发展动力电池高效回收利用技术和专用装备，推动梯级利用、再生利用与处置等"},{"i":10,"n":"第十条","txt":"调整产业组织结构，增强企业竞争能力。通过股权投资、产能合作等方式，推动企业兼并重组和战略合作，联合研发产品，共同组织生产，提升产业集中度。开展混合所有制改革，推动国有汽车企业与其他各类企业强强联合，组建具有世界一流水平的汽车企业集团。整合产、学、研、用等领域优势资源，推动汽车产业骨干企业组建产业联盟和产业联合体。推动汽车企业开放零部件供应体系，发挥各自优势，共同打造具有国际竞争力的平台化、专业化零部件企业集团。"},{"i":11,"n":"第十一条","txt":"禁止建设以下燃油汽车投资项目(不在中国境内销售产品的投资项目除外)： (一)新建独立燃油汽车企业; (二)现有汽车企业跨乘用车、商用车类别建设燃油汽车生产能力; (三)现有燃油汽车企业整体搬迁至外省份(列入国家级区域发展规划或不改变企业股权结构的项目除外); (四)对行业管理部门特别公示的燃油汽车企业进行投资(企业原有股东投资或将该企业转为非独立法人的投资项目除外)。"},{"i":12,"n":"第十二条","txt":"现有汽车企业扩大燃油汽车生产能力投资项目，应符合以下条件： (一)上两个年度汽车产能利用率均高于同产品类别(乘用车和商用车)行业平均水平; (二)上两个年度新能源汽车产量占比均高于行业平均水平; (三)上两个年度研发费用支出占主营业务收入的比例均高于3%; (四)产品具有国际竞争力; (五)项目所在省份上两个年度汽车产能利用率均高于同产品类别行业平均水平，且不存在行业管理部门特别公示的同产品类别燃油汽车企业。"},{"i":13,"n":"第十三条","txt":"燃油乘用车扩能投资项目，除符合本规定第十二条外，企业平均燃料消耗量应满足国家标准和有关规定的要求，异地新建扩能投资项目，建设规模应不低于15万辆且企业上年度总产量不低于30万辆。"},{"i":14,"n":"第十四条","txt":"现有汽车企业建设插电式混合动力汽车生产能力投资项目，可不受本规定第十二条第(二)、(五)项约束。"},{"i":15,"n":"第十五条","txt":"现有汽车企业兼并其他同产品类别独立汽车企业，并将其转为非独立汽车企业且不增加其原有产能的，可不受本规定第十二条、第十三条约束。"},{"i":16,"n":"第十六条","txt":"以下情况扩大燃油汽车生产能力，可不受本规定第十二条第(五)项约束： (一)在不新增汽车企业集团总产能的前提下，集团所属独立汽车企业通过调配内部产能，建设燃油汽车扩能项目; (二)在不新增所在省份总产能的前提下，独立汽车企业通过兼并重组建设燃油汽车扩能项目。"},{"i":17,"n":"第十七条","txt":"新建独立纯电动汽车企业投资项目(含现有汽车企业跨乘用车、商用车类别建设纯电动汽车生产能力)所在省份，应符合以下条件： (一)上两个年度汽车产能利用率均高于同产品类别行业平均水平; (二)现有新建独立同产品类别纯电动汽车企业投资项目均已建成且年产量达到建设规模。"},{"i":18,"n":"第十八条","txt":"新建独立纯电动汽车企业投资项目的企业法人，应符合以下条件： (一)已建立产品研发机构，拥有专业研发团队，具有纯电动汽车概念设计、系统和结构设计经历和能力;整车控制系统、车用动力电池系统、整车集成和轻量化等方面的研发以及相应的试验验证能力;车身及底盘制造、车用动力电池系统集成、整车装配等方面的研发以及相应的试制能力;研制的产品主要技术指标达到行业领先水平; (二)拥有纯电动汽车核心技术发明专利和知识产权，并得到授权或确认; (三)产品售后服务保障有力，承诺对项目建成投产后5年内销售的产品质量投保或由相关企业提供担保。保险公司或担保企业近3年年均净资产与担保期内新建企业销售的产品金额相适应。"},{"i":19,"n":"第十九条","txt":"新建独立纯电动汽车企业投资项目企业法人的股东，应符合以下条件： (一)股东在项目建成且年产量达到建设规模前，不撤出股本; (二)股东对关键零部件具有较强掌控能力，拥有整车控制系统、驱动电机、车用动力电池等关键零部件的知识产权和生产能力; (三)主要法人股东应符合以下条件： 1.股权占比高于三分之一; 2.控股的现有新建独立纯电动汽车企业投资项目均已建成，年产量达到建设规模，且不存在违规建设项目; 3.自有资金和融资能力能够满足项目建设及运营需要; (四)主要法人股东还应符合以下条件之一： 1.汽车整车企业为主要法人股东的，其中燃油汽车企业上两个年度汽车产能利用率和新能源汽车产量占比均高于行业平均水平，纯电动汽车企业上年度产量达到建设规模; 2.汽车零部件企业为主要法人股东的，上两个年度整车控制系统、驱动电机或车用动力电池的配套装车量累计大于10万套; 3.设计研发企业、境外企业等其他市"},{"i":20,"n":"第二十条","txt":"新建独立纯电动汽车企业投资项目，应符合以下条件： (一)建设内容包括： 1.纯电动汽车持续研发能力，在已有研发机构基础上，建立产品信息数据库，提升产品概念设计、试制试装、试验检测和整车运行状态监控等能力，研制的产品主要技术指标达到行业领先水平; 2.建设规模，纯电动乘用车不低于10万辆，纯电动商用车不低于5000辆; 3.车身成型、涂装、总装等整车生产工艺和装备，以及车用动力电池系统等关键部件的生产能力和一致性保证能力; 4.纯电动汽车产品质量保障、市场销售、售后服务及车用动力电池回收利用管理体系; (二)项目建成投产后，只生产自有注册商标和品牌的纯电动汽车产品。"},{"i":21,"n":"第二十一条","txt":"现有汽车企业扩大同产品类别纯电动汽车生产能力，燃油汽车企业上两个年度汽车产能利用率均高于行业平均水平，纯电动汽车企业上年度纯电动汽车产量达到建设规模;拟生产产品的能耗、续驶里程等主要技术指标达到行业领先水平。"},{"i":22,"n":"第二十二条","txt":"现有汽车企业异地新建同产品类别纯电动汽车生产能力，除符合本规定第二十一条外，项目的建设规模：乘用车不低于10万辆，商用车不低于5000辆。"},{"i":23,"n":"第二十三条","txt":"新建汽车发动机企业投资项目企业法人应具备较强研发能力，研制的产品主要技术指标达到行业领先水平。新建汽车发动机企业和现有企业新增发动机产品投资项目，发动机产品应满足国家最新汽车排放标准相应要求。"},{"i":24,"n":"第二十四条","txt":"新建车用动力电池单体/系统企业投资项目，应符合以下条件： (一)企业法人已建立车用动力电池产品研发机构，拥有专业研发团队，具有相关研发经历。单体企业应掌握材料等方面核心技术研发和试验验证能力，系统企业应掌握电池管理及热管理系统等方面核心技术研发和试验验证能力; (二)拟建设的设施具有较高智能化水平，在厂房布置、生产线设计、智能装备投入、数字化信息管理及生产环境控制、过程控制等方面能够满足智能制造的要求。单体项目生产工序应覆盖电极制备、化成、单体装配等工艺过程，系统项目应具备模组生产、系统装配及测试等能力; (三)产品主要技术指标应达到行业领先水平; (四)企业法人承担车用动力电池回收利用生产者责任，项目配套建设车用动力电池回收利用管理体系。"},{"i":25,"n":"第二十五条","txt":"现有车用动力电池企业扩能项目，除符合本规定第二十四条外，企业上两个年度车用动力电池产能利用率均不低于80%。"},{"i":26,"n":"第二十六条","txt":"新建车用燃料电池电堆/系统投资项目，应符合以下条件： (一)企业法人已建立车用燃料电池产品研发机构，拥有专业研发团队，具有相关研发经历。燃料电池电堆企业应具备双极板、膜电极等关键部件核心技术研发和试验验证能力。燃料电池系统企业应具备电堆控制系统等关键部件核心技术研发和试验验证能力; (二)燃料电池电堆项目应建设双极板、膜电极等关键部件和电堆组装的生产能力。燃料电池系统项目应建设电堆控制系统等关键部件和电堆系统组装的生产能力; (三)产品主要技术指标应达到行业领先水平。"},{"i":27,"n":"第二十七条","txt":"车身总成投资项目有关要求： (一)新建独立车身总成企业投资项目，企业法人应建立产品研发机构，拥有专业研发团队，具有相关研发经历，具备新材料、新工艺等车身轻量化核心技术研发和试验验证能力;项目应采用先进技术工艺，建设应用碳纤维等非金属复合材料、铝等轻质合金或其他轻量化新材料的车身成型和组装等生产能力; (二)禁止新建应用普通钢板等传统材料、采用冲压焊接等传统工艺制造车身的独立车身总成企业投资项目。"},{"i":28,"n":"第二十八条","txt":"专用汽车和挂车投资项目有关要求： (一)新建专用汽车和挂车企业投资项目，企业法人应建立产品研发机构，拥有专业研发团队，具有相关研发经历，具备专用装置的技术研发和试验验证能力; (二)禁止新建仓栅车、栏板车、自卸车和普通厢式车等普通运输类专用汽车和普通运输类挂车企业投资项目; (三)专用汽车企业不得建设各类汽车底盘和整车生产能力，特种作业车底盘自制自用除外。"},{"i":29,"n":"第二十九条","txt":"车用动力电池回收、梯级利用、再生利用与处置等投资项目，应符合国家有关法律法规和标准要求，采用先进适用的工艺技术及装备，实现不可利用残余物无害化处理。"},{"i":30,"n":"第三十条","txt":"汽车零部件再制造投资项目，应符合国家有关法律法规和标准要求，企业具备相应的旧件回收能力，具有必要的拆解、清洗、制造、装配、质量检测等技术装备，采用先进技术工艺，建立完善的再制造质量控制标准和生产规范，保证再制造产品与原型新品具有同样性能质量。"},{"i":31,"n":"第三十一条","txt":"省级发展改革部门应按照《企业投资项目核准和备案管理条例》《企业投资项目核准和备案管理办法》制定并公开汽车投资项目备案服务指南，明确项目备案所需的信息内容以及办理的条件、流程等。"},{"i":32,"n":"第三十二条","txt":"企业提交的汽车投资项目信息应包括以下内容： (一)企业法人、股东构成等基本情况; (二)拟建项目情况，包括项目名称、总投资额、建设地点、建设规模、建设内容等; (三)项目符合本规定的说明; (四)项目符合相关法律法规的声明; (五)有关规定需要提交的其他信息。"},{"i":33,"n":"第三十三条","txt":"地方发展改革部门发现企业以分拆项目、隐瞒有关情况或者提供虚假申报信息等不正当手段备案的，应责令其限期整改。已备案项目信息发生较大变更的，企业应及时告知备案机关。"},{"i":34,"n":"第三十四条","txt":"项目法人应通过全国投资项目在线审批监管平台进行项目申报，申请获得唯一项目代码，如实报送项目开工建设、建设进度、竣工等建设实施基本信息，并对项目信息的真实性、合法性和完整性负责。"},{"i":35,"n":"第三十五条","txt":"地方发展改革部门要严格执行《企业投资项目核准和备案管理条例》等规定，并通过全国投资项目在线审批监管平台及时将项目信息报送国家发展改革委。"},{"i":36,"n":"第三十六条","txt":"省级发展改革部门每季度应进行汽车投资项目的统计和分析。对信息不完整的，应要求企业及时补充相关信息;对建设内容与项目信息不符的，应责令企业限期改正;对逾期不改正的，应依法予以处罚，并将其列入失信企业名单，纳入全国信用信息共享平台及相关公示系统，向社会公开。"},{"i":37,"n":"第三十七条","txt":"国家发展改革委建立不定期抽查制度，对不符合规定的汽车投资项目进行公示，列入项目异常信用记录，纳入全国信用信息共享平台;并责令地方发展改革部门和企业进行整改。"},{"i":38,"n":"第三十八条","txt":"各级地方政府不得妨碍市场公平竞争，违规为汽车投资项目提供税收、资金、土地等优惠条件。"},{"i":39,"n":"第三十九条","txt":"对涉及产业安全的新建、兼并重组和股权变更等重大汽车投资项目，有关部门应按规定及时进行反垄断审查。涉及外商投资的，还应按规定进行安全审查。"},{"i":40,"n":"第四十条","txt":"各级发展改革部门应与规划、国土、环境保护、安全生产、金融及行业管理等部门建立健全协同监管和联合执法机制，提高监管执法效率。"},{"i":41,"n":"第四十一条","txt":"对各级发展改革部门在监督管理中查实违规的汽车投资项目，由备案机关撤销其备案并抄送相关部门，由规划、国土、环境保护、安全生产、金融及行业管理等部门进一步处理。对经认定的严重失信主体，实施联合惩戒。违反法律规定的，依法进行处罚。"},{"i":42,"n":"第四十二条","txt":"按照谁审批谁监管、谁主管谁监管的原则，各级发展改革部门要建立健全监督责任制和责任追究制，加强汽车投资项目事中事后监管。对不依法履行监管职责或者监督不力的单位，给予约谈、通报，责令限期整改;逾期不改正的，在整改到位前暂停备案。对负有责任的领导人员和直接责任人员，依法依规给予问责、处理。"},{"i":43,"n":"第四十三条","txt":"汽车产能监测和统计： (一)汽车整车和关键零部件企业应将上年度相关产品产量、 建成产能、在建产能和规划产能情况，于每年1月底前上报省级发展改革部门并抄报国家发展改革委; (二)省级发展改革部门应及时掌握本地区相关汽车产品生产情况和产能变化情况，于每年3月底前将本地区上年度产量和产能汇总情况上报国家发展改革委。"},{"i":44,"n":"第四十四条","txt":"汽车产能发布和预警： (一)国家发展改革委应建立汽车产能核查和信息发布工作机制，及时发布汽车产能变动信息，加强产能预警，引导企业合理投资，为地方汽车投资项目管理提供服务; (二)省级发展改革部门应健全本地区汽车产能核查体系，研判产能利用率变动情况，加强对企业的指导和监督，有效应对和及时化解产能过剩风险，不断提高产能利用水平。"},{"i":45,"n":"第四十五条","txt":"已审批或核准的汽车投资项目变更建设内容、主要股东等事宜，需报原项目审批或核准机关办理。"},{"i":46,"n":"第四十六条","txt":"本规定由国家发展改革委根据实际情况适时予以修订。"},{"i":47,"n":"第四十七条","txt":"本规定由国家发展改革委负责解释。"},{"i":48,"n":"第四十八条","txt":"本规定自2019年1月10日起施行。外商投资准入特别管理措施有专门规定的，从其规定。新能源汽车企业清理规范专项行动前正式受理的新建独立纯电动汽车企业投资项目，由省级发展改革部门在本规定实施前参照原规定研究办理。其他有关文件与本规定不一致的，按照本规定执行。"}],"qichechanpinwaibubiaoshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范汽车生产企业产品外部标识，保护消费者合法权益，推动汽车生产企业增强质量意识和品牌意识，贯彻《汽车产业发展政策》，根据有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的“汽车产品外部标识”是指注册商品商标、生产企业名称、商品产地、车型名称及型号、发动机排量、变速箱型式、驱动型式及反映车辆特征的其他标识。"},{"i":3,"n":"第三条","txt":"本办法适用于在中国境内生产的面向国内市场销售的汽车。对在中国境内生产的面向国外市场的汽车和进口汽车不做统一要求。"},{"i":4,"n":"第四条","txt":"汽车行业主管部门负责对汽车产品外部标识的标注进行规范和管理。"},{"i":5,"n":"第五条","txt":"国产汽车在车身前部外表面的易见部位上应当至少装置一个能永久保持的商品商标。"},{"i":6,"n":"第六条","txt":"国产乘用车、商用车、挂车在车身尾部显著位置(在保险杠之上的后部车身表面)上，应标注汽车生产企业名称、商品商标、车型名称等。如果标注商品图形商标，则应标注于车身尾部外表面的左右中间位置(车身尾部带备用轮胎架或车身后部左右开门的车辆除外)。 汽车生产企业的合资各方如将各自中文汉字名称的简称进行组合或将各自注册的汉字商标进行组合标注的，可不再标注生产企业名称。"},{"i":7,"n":"第七条","txt":"采用外购底盘的专用车应保留原底盘的商品商标、生产企业名称等，同时还应标注专用车生产企业的名称、商品商标、车型名称等信息。"},{"i":8,"n":"第八条","txt":"汽车零部件产品应标注生产企业商品商标或企业名称，具体标注方式由企业自行决定。"},{"i":9,"n":"第九条","txt":"汽车生产企业名称必须采用中文汉字标注。车长超过4.2m的车型，其中文汉字高度不得低于25mm，车长不超过4.2m的车型，其中文汉字高度不得低于20mm。生产企业名称和商品文字商标必须采用同一材料标注。"},{"i":10,"n":"第十条","txt":"车型名称可以采用中文汉字，也可以采用字母，其文字高度不得低于15mm。"},{"i":11,"n":"第十一条","txt":"汽车产品外部标识标注的内容应当与车辆产品标牌、车辆整车出厂合格证明等文件标注的内容一致。"},{"i":12,"n":"第十二条","txt":"乘用车、商用车车身的前部和尾部标识中，汽车生产企业名称、商品商标、车型名称等应能永久保持，不得采用油漆喷涂方式和不干胶粘贴方式。"},{"i":13,"n":"第十三条","txt":"本办法所称汽车是指国家标准(GB/T 3730.1—2001)2.1款定义的车辆，包括乘用车(2.1.1款定义)和商用车(2.1.2款定义)，其中2.1.1.11，2.1.2.3.5，2.1.2.3.6款定义的车辆为专用汽车;所称挂车指国家标准(GB/T 3730.1—2001)2.2款定义的车辆。"},{"i":14,"n":"第十四条","txt":"本办法中的“汽车生产企业名称”是指汽车生产企业在工商部门登记注册的企业名称或汽车生产企业《公告》名称。 具体标注时，既可以采用企业全称，也可以采用企业简称，当采用企业简称时应在申报《道路机动车辆生产企业及产品公告》时备案。 国内汽车生产企业(集团)的控股子公司可以按照母公司的要求标注企业名称或简称。"},{"i":15,"n":"第十五条","txt":"本办法中的“永久保持”是指在产品使用寿命时间内不允许老化和自然脱落。"},{"i":16,"n":"第十六条","txt":"2006年2月1日开始，申报《道路机动车辆生产企业及产品公告》(以下简称《公告》)的新产品必须符合本办法的规定，不符合本办法要求的，将不予登录《公告》。"},{"i":17,"n":"第十七条","txt":"汽车生产企业应尽快按照本办法的规定对《公告》内车型车身外部标识进行调整，2006年5月1日起《公告》内所有车型均需符合本办法要求，否则暂停有关车型《公告》。"},{"i":18,"n":"第十八条","txt":"本办法自2006年2月1日起施行。"}],"hainanziyoumaoyigangwaishangtouzizhunrutebieguanli968e67-2":[],"hainanziyoumaoyigangwaishangtouzizhunrutebieguanli968e67":[],"qingjieshengchanshenhebanfa":[{"i":1,"n":"第一条","txt":"为促进清洁生产，规范清洁生产审核行为，根据《中华人民共和国清洁生产促进法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称清洁生产审核，是指按照一定程序，对生产和服务过程进行调查和诊断，找出能耗高、物耗高、污染重的原因，提出降低能耗、物耗、废物产生以及减少有毒有害物料的使用、产生和废弃物资源化利用的方案，进而选定并实施技术经济及环境可行的清洁生产方案的过程。"},{"i":3,"n":"第三条","txt":"本办法适用于中华人民共和国领域内所有从事生产和服务活动的单位以及从事相关管理活动的部门。"},{"i":4,"n":"第四条","txt":"国家发展和改革委员会会同环境保护部负责全国清洁生产审核的组织、协调、指导和监督工作。县级以上地方人民政府确定的清洁生产综合协调部门会同环境保护主管部门、管理节能工作的部门(以下简称“节能主管部门”)和其他有关部门，根据本地区实际情况，组织开展清洁生产审核。"},{"i":5,"n":"第五条","txt":"清洁生产审核应当以企业为主体，遵循企业自愿审核与国家强制审核相结合、企业自主审核与外部协助审核相结合的原则，因地制宜、有序开展、注重实效。"},{"i":6,"n":"第六条","txt":"清洁生产审核分为自愿性审核和强制性审核。"},{"i":7,"n":"第七条","txt":"国家鼓励企业自愿开展清洁生产审核。本办法第八条规定以外的企业，可以自愿组织实施清洁生产审核。"},{"i":8,"n":"第八条","txt":"有下列情形之一的企业，应当实施强制性清洁生产审核： (一)污染物排放超过国家或者地方规定的排放标准，或者虽未超过国家或者地方规定的排放标准，但超过重点污染物排放总量控制指标的; (二)超过单位产品能源消耗限额标准构成高耗能的; (三)使用有毒有害原料进行生产或者在生产中排放有毒有害物质的。 其中有毒有害原料或物质包括以下几类： 第一类，危险废物。包括列入《国家危险废物名录》的危险废物，以及根据国家规定的危险废物鉴别标准和鉴别方法认定的具有危险特性的废物。 第二类，剧毒化学品、列入《重点环境管理危险化学品目录》的化学品，以及含有上述化学品的物质。 第三类，含有铅、汞、镉、铬等重金属和类金属砷的物质。第四类，《关于持久性有机污染物的斯德哥尔摩公约》附件所列物质。 第五类，其他具有毒性、可能污染环境的物质。"},{"i":9,"n":"第九条","txt":"本办法第八条第(一)款、第(三)款规定实施强制性清洁生产审核的企业名单，由所在地县级以上环境保护主管部门按照管理权限提出，逐级报省级环境保护主管部门核定后确定，根据属地原则书面通知企业，并抄送同级清洁生产综合协调部门和行业管理部门。 本办法第八条第(二)款规定实施强制性清洁生产审核的企业名单，由所在地县级以上节能主管部门按照管理权限提出，逐级报省级节能主管部门核定后确定，根据属地原则书面通知企业，并抄送同级清洁生产综合协调部门和行业管理部门。"},{"i":10,"n":"第十条","txt":"各省级环境保护主管部门、节能主管部门应当按照各自职责，分别汇总提出应当实施强制性清洁生产审核的企业单位名单，由清洁生产综合协调部门会同环境保护主管部门或节能主管部门，在官方网站或采取其他便于公众知晓的方式分期分批发布。"},{"i":11,"n":"第十一条","txt":"实施强制性清洁生产审核的企业，应当在名单公布后一个月内，在当地主要媒体、企业官方网站或采取其他便于公众知晓的方式公布企业相关信息。 (一)本办法第八条第(一)款规定实施强制性清洁生产审核的企业，公布的主要信息包括：企业名称、法人代表、企业所在地址、排放污染物名称、排放方式、排放浓度和总量、超标及超总量情况。 (二)本办法第八条第(二)款规定实施强制性清洁生产审核的企业，公布的主要信息包括：企业名称、法人代表、企业所在地址、主要能源品种及消耗量、单位产值能耗、单位产品能耗、超过单位产品能耗限额标准情况。 (三)本办法第八条第(三)款规定实施强制性清洁生产审核的企业，公布的主要信息包括：企业名称、法人代表、企业所在地址、使用有毒有害原料的名称、数量、用途，排放有毒有害物质的名称、浓度和数量，危险废物的产生和处置情况，依法落实环境风险防控措施情况等。 (四)符合本办法第八条两款以上情况的企业"},{"i":12,"n":"第十二条","txt":"列入实施强制性清洁生产审核名单的企业应当在名单公布后两个月内开展清洁生产审核。 本办法第八条第(三)款规定实施强制性清洁生产审核的企业，两次清洁生产审核的间隔时间不得超过五年。"},{"i":13,"n":"第十三条","txt":"自愿实施清洁生产审核的企业可参照强制性清洁生产审核的程序开展审核。"},{"i":14,"n":"第十四条","txt":"清洁生产审核程序原则上包括审核准备、预审核、审核、方案的产生和筛选、方案的确定、方案的实施、持续清洁生产等。"},{"i":15,"n":"第十五条","txt":"清洁生产审核以企业自行组织开展为主。实施强制性清洁生产审核的企业，如果自行独立组织开展清洁生产审核，应具备本办法第十六条第(二)款、第(三)款的条件。 不具备独立开展清洁生产审核能力的企业，可以聘请外部专家或委托具备相应能力的咨询服务机构协助开展清洁生产审核。"},{"i":16,"n":"第十六条","txt":"协助企业组织开展清洁生产审核工作的咨询服务机构，应当具备下列条件： (一)具有独立法人资格，具备为企业清洁生产审核提供公平、公正和高效率服务的质量保证体系和管理制度。 (二)具备开展清洁生产审核物料平衡测试、能量和水平衡测试的基本检测分析器具、设备或手段。 (三)拥有熟悉相关行业生产工艺、技术规程和节能、节水、污染防治管理要求的技术人员。 (四)拥有掌握清洁生产审核方法并具有清洁生产审核咨询经验的技术人员。"},{"i":17,"n":"第十七条","txt":"列入本办法第八条第(一)款和第(三)款规定实施强制性清洁生产审核的企业，应当在名单公布之日起一年内，完成本轮清洁生产审核并将清洁生产审核报告报当地县级以上环境保护主管部门和清洁生产综合协调部门。 列入第八条第(二)款规定实施强制性清洁生产审核的企业，应当在名单公布之日起一年内，完成本轮清洁生产审核并将清洁生产审核报告报当地县级以上节能主管部门和清洁生产综合协调部门。"},{"i":18,"n":"第十八条","txt":"县级以上清洁生产综合协调部门应当会同环境保护主管部门、节能主管部门，对企业实施强制性清洁生产审核的情况进行监督，督促企业按进度开展清洁生产审核。"},{"i":19,"n":"第十九条","txt":"有关部门以及咨询服务机构应当为实施清洁生产审核的企业保守技术和商业秘密。"},{"i":20,"n":"第二十条","txt":"县级以上环境保护主管部门或节能主管部门，应当在各自的职责范围内组织清洁生产专家或委托相关单位，对以下企业实施清洁生产审核的效果进行评估验收： (一)国家考核的规划、行动计划中明确指出需要开展强制性清洁生产审核工作的企业。 (二)申请各级清洁生产、节能减排等财政资金的企业。 上述涉及本办法第八条第(一)款、第(三)款规定实施强制性清洁生产审核企业的评估验收工作由县级以上环境保护主管部门牵头，涉及本办法第八条第(二)款规定实施强制性清洁生产审核企业的评估验收工作由县级以上节能主管部门牵头。"},{"i":21,"n":"第二十一条","txt":"对企业实施清洁生产审核评估的重点是对企业清洁生产审核过程的真实性、清洁生产审核报告的规范性、清洁生产方案的合理性和有效性进行评估。"},{"i":22,"n":"第二十二条","txt":"对企业实施清洁生产审核的效果进行验收，应当包括以下主要内容： (一)企业实施完成清洁生产方案后，污染减排、能源资源利用效率、工艺装备控制、产品和服务等改进效果，环境、经济效益是否达到预期目标。 (二)按照清洁生产评价指标体系，对企业清洁生产水平进行评定。"},{"i":23,"n":"第二十三条","txt":"对本办法第二十条中企业实施清洁生产审核效果的评估验收，所需费用由组织评估验收的部门报请地方政府纳入预算。承担评估验收工作的部门或者单位不得向被评估验收企业收取费用。"},{"i":24,"n":"第二十四条","txt":"自愿实施清洁生产审核的企业如需评估验收，可参照强制性清洁生产审核的相关条款执行。"},{"i":25,"n":"第二十五条","txt":"清洁生产审核评估验收的结果可作为落后产能界定等工作的参考依据。"},{"i":26,"n":"第二十六条","txt":"县级以上清洁生产综合协调部门会同环境保护主管部门、节能主管部门，应当每年定期向上一级清洁生产综合协调部门和环境保护主管部门、节能主管部门报送辖区内企业开展清洁生产审核情况、评估验收工作情况。"},{"i":27,"n":"第二十七条","txt":"国家发展和改革委员会、环境保护部会同相关部门建立国家级清洁生产专家库，发布行业清洁生产评价指标体系、重点行业清洁生产审核指南，组织开展清洁生产培训，为企业开展清洁生产审核提供信息和技术支持。 各级清洁生产综合协调部门会同环境保护主管部门、节能主管部门可以根据本地实际情况，组织开展清洁生产培训，建立地方清洁生产专家库。"},{"i":28,"n":"第二十八条","txt":"对自愿实施清洁生产审核，以及清洁生产方案实施后成效显著的企业，由省级清洁生产综合协调部门和环境保护主管部门、节能主管部门对其进行表彰，并在当地主要媒体上公布。"},{"i":29,"n":"第二十九条","txt":"各级清洁生产综合协调部门及其他有关部门在制定实施国家重点投资计划和地方投资计划时，应当将企业清洁生产实施方案中的提高能源资源利用效率、预防污染、综合利用等清洁生产项目列为重点领域，加大投资支持力度。"},{"i":30,"n":"第三十条","txt":"排污费资金可以用于支持企业实施清洁生产。对符合《排污费征收使用管理条例》规定的清洁生产项目，各级财政部门、环境保护部门在排污费使用上优先给予安排。"},{"i":31,"n":"第三十一条","txt":"企业开展清洁生产审核和培训的费用，允许列入企业经营成本或者相关费用科目。"},{"i":32,"n":"第三十二条","txt":"企业可以根据实际情况建立企业内部清洁生产表彰奖励制度，对清洁生产审核工作中成效显著的人员给予奖励。"},{"i":33,"n":"第三十三条","txt":"对本办法第八条规定实施强制性清洁生产审核的企业，违反本办法第十一条规定的，按照《中华人民共和国清洁生产促进法》第三十六条规定处罚。"},{"i":34,"n":"第三十四条","txt":"违反本办法第八条、第十七条规定，不实施强制性清洁生产审核或在审核中弄虚作假的，或者实施强制性清洁生产审核的企业不报告或者不如实报告审核结果的，按照《中华人民共和国清洁生产促进法》第三十九条规定处罚。"},{"i":35,"n":"第三十五条","txt":"企业委托的咨询服务机构不按照规定内容、程序进行清洁生产审核，弄虚作假、提供虚假审核报告的，由省、自治区、直辖市、计划单列市及新疆生产建设兵团清洁生产综合协调部门会同环境保护主管部门或节能主管部门责令其改正，并公布其名 单。造成严重后果的，追究其法律责任。"},{"i":36,"n":"第三十六条","txt":"对违反本办法相关规定受到处罚的企业或咨询服务机构，由省级清洁生产综合协调部门和环境保护主管部门、节能主管部门建立信用记录，归集至全国信用信息共享平台，会同其他有关部门和单位实行联合惩戒。"},{"i":37,"n":"第三十七条","txt":"有关部门的工作人员玩忽职守，泄露企业技术和商业秘密，造成企业经济损失的，按照国家相应法律法规予以处罚。"},{"i":38,"n":"第三十八条","txt":"本办法由国家发展和改革委员会和环境保护部负责解释。"},{"i":39,"n":"第三十九条","txt":"各省、自治区、直辖市、计划单列市及新疆生产建设兵团可以依照本办法制定实施细则。"},{"i":40,"n":"第四十条","txt":"本办法自2016年7月1日起施行。原《清洁生产审核暂行办法》(国家发展和改革委员会、国家环境保护总局令第16号)同时废止。"}],"meitanchukoupeieguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范煤炭出口，保证煤炭出口配额管理工作符合效率、公正、公开和透明的原则，维护煤炭的正常出口秩序，根据《中华人民共和国对外贸易法》和《中华人民共和国货物进出口管理条例》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家发展和改革委员会(以下简称发展改革委)会同商务部负责确定全国煤炭出口配额总量及分配工作。"},{"i":3,"n":"第三条","txt":"本办法适用于一般贸易方式下煤炭的出口。其他贸易方式下煤炭出口按现行有关规定办理。"},{"i":4,"n":"第四条","txt":"每年煤炭出口配额总量及申请程序，由发展改革委于上一年10月31日前在中国经济信息网(http://www.cei.gov.cn)、国家发展和改革委员会网站(http://www.sdpc.gov.cn)上公布。"},{"i":5,"n":"第五条","txt":"确定煤炭出口配额总量时，应当考虑以下因素： (一)保障国家经济安全; (二)合理利用煤炭资源; (三)符合国家有关产业发展规划、目标和政策; (四)国际、国内市场供求状况。"},{"i":6,"n":"第六条","txt":"煤炭出口实行国营贸易管理。已获得煤炭出口国营贸易经营权的出口企业可以申请煤炭出口配额。"},{"i":7,"n":"第七条","txt":"出口企业应当以正式书面方式向发展改革委提出配额申请，并按要求提交相关文件和资料。"},{"i":8,"n":"第八条","txt":"发展改革委于每年11月1日至11月15日受理煤炭出口企业提出的下一年度煤炭出口配额申请。"},{"i":9,"n":"第九条","txt":"发展改革委会同商务部于每年12月15日前将下一年度煤炭出口配额总量的80%下达给企业。剩余部分将不晚于当年6月30日下达。"},{"i":10,"n":"第十条","txt":"煤炭出口配额参考企业上一年度煤炭出口实绩分配。"},{"i":11,"n":"第十一条","txt":"煤炭出口配额有效期截止到当年12月31日。"},{"i":12,"n":"第十二条","txt":"如发生下列情况时，可以对已分配的配额进行调整： (一)国际市场发生重大变化; (二)国内资源状况发生重大变化; (三)出口企业配额使用进度明显不均衡; (四)其他需要调整配额的情况。"},{"i":13,"n":"第十三条","txt":"煤炭出口企业凭配额批准文件，按照有关出口许可证管理规定，向商务部授权的许可证发证机构申领出口许可证，凭出口许可证向海关办理报关验放手续。 煤炭出口许可证管理按照商务部许可证管理有关规定执行。"},{"i":14,"n":"第十四条","txt":"煤炭出口企业于每月5日前将上月煤炭出口配额使用情况报发展改革委备案。"},{"i":15,"n":"第十五条","txt":"煤炭出口经营者在煤炭出口中有违法、违规行为，受到海关、税务、商检、外汇管理等部门处罚的，发展改革委可酌情扣减其已获得的煤炭出口配额。"},{"i":16,"n":"第十六条","txt":"煤炭出口经营者伪造、变造出口配额批准文件或出口许可证，或者以欺骗或其他不正当手段获取出口配额、批准文件或出口许可证的，依照《货物进出口条例》第六十六条、六十七条规定处罚。发展改革委并可以取消其已获得的煤炭出口配额。"},{"i":17,"n":"第十七条","txt":"对配额分配决定或处罚决定有异议的，可以依照《行政复议法》提起行政复议，也可以依法向人民法院提起诉讼。"},{"i":18,"n":"第十八条","txt":"本办法由发展改革委、商务部、海关总署负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自2004年7月1日起施行。"}],"meitankuangquzongtiguihuaguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为规范煤炭资源勘查开发秩序，保护和合理开发利用煤炭资源，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于国家发展改革委审批的矿区总体规划。"},{"i":3,"n":"第三条","txt":"煤炭资源开发必须编制矿区总体规划。经批准的矿区总体规划，是煤炭工业发展规划、煤矿建设项目开展前期准备工作和办理核准的基本依据。"},{"i":4,"n":"第四条","txt":"国家发展改革委和省级发展改革委负责矿区总体规划的监督管理，煤炭行业管理、安全生产监管、国土资源、环保、水利、监察等部门在各自职责范围内参与管理。"},{"i":5,"n":"第五条","txt":"煤炭矿区总体规划由省级发展改革委委托具有甲级煤炭工程咨询资质的单位编制。"},{"i":6,"n":"第六条","txt":"编制煤炭矿区总体规划应当坚持合理布局、有序开发、规模生产和综合利用的原则，符合国家法律、法规、标准、规范等有关规定。"},{"i":7,"n":"第七条","txt":"多个相邻煤田、大型煤田要在科学论证的基础上，合理划分矿区。"},{"i":8,"n":"第八条","txt":"编制煤炭矿区总体规划应当在普查和必要的详查地质报告基础上进行，详查及以上区域面积占矿区含煤面积的60%左右。 矿区内有多个地质勘查报告时，省级发展改革委应当委托具有相应资质的地质勘查单位编制地质资料汇编报告。 编制矿区总体规划所依据的地质资料应当符合有关规范的要求，并取得相应资质单位的评审意见。"},{"i":9,"n":"第九条","txt":"煤炭矿区总体规划应当与国家主体功能区规划、国家能源规划、煤炭工业发展规划、省级以上人民政府批准的城镇总体规划等相衔接。"},{"i":10,"n":"第十条","txt":"煤炭矿区总体规划设计文件应当包括下列内容： (一)规划编制的依据、指导思想和原则; (二)矿区概况，包括矿区位置、资源条件、勘查程度等; (三)矿区开发目的和必要性，矿区开发对地区经济社会发展的作用和意义，煤炭市场前景和产品竞争力; (四)矿区开发企业基本情况，生产和在建矿区应当说明矿区生产开发现状; (五)矿区和井(矿)田范围确定依据，井田划分的技术经济比较; (六)矿井(露天矿)建设规模、服务年限、开拓方式、井口位置和工业场地; (七)矿区建设规模、均衡生产服务年限、煤炭资源补充勘查意见和矿井建设顺序; (八)煤炭洗选加工，包括煤质特征、原煤可选性、产品利用方向、煤炭洗选加工及布局等; (九)矿区与煤伴生资源、煤层气(煤矿瓦斯)、矿井水和煤矸石等资源综合开发利用方案; (十)外部建设条件，矿区铁路、公路、供电电源及供电方案、供水水源及供水方式、通讯等; (十一)矿区总平面布置及辅助"},{"i":11,"n":"第十一条","txt":"资源储量为中型、规划总规模300万吨/年及以上的矿区，其总体规划由矿区所在省级发展改革委会同省级煤炭行业管理等部门提出审查意见后，报国家发展改革委审批。"},{"i":12,"n":"第十二条","txt":"国家发展改革委收到报送的矿区总体规划文件后，对申报材料不齐全或者不符合要求的，应在收到申报材料后10个工作日内一次性告知申报单位，补充相关情况和文件。逾期不通知的，自收到申报材料之日起即视为受理。 申报单位应在统筹兼顾资源状况、技术经济、开发合理、管理规范等方面的基础上，提出矿区开发主体企业的建议。"},{"i":13,"n":"第十三条","txt":"国家发展改革委在受理矿区总体规划后，应当委托有资质的评估机构进行评估或者组织专家评审。 接受委托的评估机构应当在规定的时间内提出评估报告，并对评估结论负责。评估机构在进行评估时，可要求规划申报单位就有关问题进行说明。 在咨询评估过程中，评估机构应当向国家发展改革委报告评估进度等有关情况。"},{"i":14,"n":"第十四条","txt":"煤炭矿区总体规划评估报告应当包括下列内容： (一)矿区概况及开发企业基本情况; (二)矿区范围及勘查程度评价; (三)资源条件评价，包括地层与构造、煤层、水文地质、开采技术条件及工程地质、资源储量、煤质等; (四)矿区开发的必要性; (五)矿区开发评价，包括矿区开发现状、规划原则、井(矿)田划分方案、规划建设规模、矿区均衡生产服务年限等; (六)煤炭洗选加工和资源综合利用评价，包括原煤可选性及产品利用方向、煤炭洗选加工与布局、资源综合利用等; (七)外部建设条件评价，包括矿区铁路、公路、供电电源及供电方案、供水水源及供水方式等; (八)矿区总平面布置及辅助设施评价，包括矿区地面布置、建设用地、防洪排涝等; (九)矿区安全生产与灾害防治评价; (十)矿区环境保护、水土保持和节能减排评价; (十一)主要结论和建议; (十二)评估报告应当附规划矿井(露天矿)基本特征表、矿区勘查程度图、矿区井"},{"i":15,"n":"第十五条","txt":"对于可能会对公众利益造成重大影响的矿区，省级发展改革委在报批矿区总体规划前，应当采取适当方式征求公众意见。"},{"i":16,"n":"第十六条","txt":"国家发展改革委对同意批复的矿区总体规划，应当向规划申报单位下达批复文件，同时抄送相关省(区、市)人民政府和国务院有关部门;对不同意批复的矿区总体规划，应当告知规划申报单位。"},{"i":17,"n":"第十七条","txt":"煤炭矿区总体规划实行动态管理。已批准的矿区总体规划，矿区范围、井(矿)田划分和建设规模发生较大变化的，应编制矿区总体规划(修改版)，明确矿区总体规划修改内容，并按照上述程序重新报批。 矿区总体规划(修改版)申报时间距原规划批复时间原则上不少于五年。评估或者评审矿区总体规划(修改版)，应当对矿区总体规划修改内容作出评价。"},{"i":18,"n":"第十八条","txt":"省级发展改革委在收到矿区总体规划批复文件后，应当将批复文件转发省级国土资源、水利、铁路、电力等部门，以及矿区所在地市(盟)、县(旗)人民政府和矿区开发主体企业。"},{"i":19,"n":"第十九条","txt":"接受委托编制、评估煤炭矿区总体规划的工程咨询单位、评估机构，违反有关规定，提供虚假报告，违法所得在五千元及以上的，处五千元以上三万元以下的罚款;没有违法所得或者违法所得不足五千元的，处二千元以上一万元以下的罚款;对其直接负责的主管人员和其他直接责任人员处一千元以上一万元以下的罚款;构成犯罪的，依法追究刑事责任。 对有前款违法行为且情节严重的工程咨询单位、评估机构，应当由资质认定单位依法取消其相应资质。"},{"i":20,"n":"第二十条","txt":"煤炭矿区总体规划的委托编制、审批部门违反本规定，在委托编制、审批中徇私舞弊、滥用职权、玩忽职守的，由上级行政主管机关或者监察机关责令改正，依法对其直接负责的主管人员和其他直接责任人员给予处分。"},{"i":21,"n":"第二十一条","txt":"矿区煤炭开发企业在矿区总体规划未经批准或者违反经批准的矿区总体规划，擅自从事煤矿建设、生产的，由省级发展改革委会同有关部门责令停止建设、生产，并对相关企业负责人、直接负责的主管人员和其他直接责任人员处一千元以上一万元以下的罚款;构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"煤炭资源储量为小型、规划总规模300万吨/年以下的矿区，其总体规划由省级发展改革委审批，报国家发展改革委备案。 省级发展改革委审批的矿区总体规划，参照本规定执行。"},{"i":23,"n":"第二十三条","txt":"本规定由国家发展改革委负责解释。"},{"i":24,"n":"第二十四条","txt":"本规定自发布之日起三十日后施行，《国家发展改革委关于规范煤炭矿区总体规划审批管理工作的通知》(发改能源〔2004〕891号)同时废止。"}],"meiganshizongheliyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为深入推进煤矸石综合利用健康有序发展，发展循环经济，减少其对土地资源占用和环境影响，提高资源利用效率，促进煤矿安全生产，根据《清洁生产促进法》、《固体废物污染环境防治法》、《循环经济促进法》、《煤炭法》等法律，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内对煤矸石综合利用的管理活动，适用本办法。 本办法所称煤矸石，是指煤矿在开拓掘进、采煤和煤炭洗选等生产过程中排出的含碳岩石，是煤矿生产过程中的废弃物。 本办法所称煤矸石综合利用，是指利用煤矸石进行井下充填、发电、生产建筑材料、回收矿产品、制取化工产品、筑路、土地复垦等。"},{"i":3,"n":"第三条","txt":"煤矸石综合利用应当坚持减少排放和扩大利用相结合，实行就近利用、分类利用、大宗利用、高附加值利用，提升技术水平，实现经济效益、社会效益和环境效益有机统一，加强全过程管理，提高煤矸石利用量和利用率。"},{"i":4,"n":"第四条","txt":"国家发展改革委会同科技部、工业和信息化部、财政部、国土资源部、环境保护部、住房城乡建设部、税务总局、质检总局、安全监管总局、能源局、煤矿安监局等负责起草、拟订、发布煤矸石综合利用相关规划、产业和扶持政策、技术规范等，并在各自职责范围内开展煤矸石综合利用管理工作。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人民政府资源综合利用主管部门负责本办法的贯彻实施，以及本行政区域内煤矸石综合利用活动的监督、管理和协调工作。省、自治区、直辖市人民政府其他相关部门在各自职责范围内支持配合煤矸石综合利用工作。"},{"i":6,"n":"第六条","txt":"设区的市级环境保护部门、资源综合利用主管部门会同煤炭行业管理部门负责统计和发布本地区煤矸石产生、贮存、流向、利用、处置等数据信息。 省、自治区、直辖市环境保护部门和资源综合利用主管部门应于每年3月底前，将本地区上年度统计数据报环境保护部、国家发展改革委。"},{"i":7,"n":"第七条","txt":"有关行业协会、社会中介组织要积极发挥在技术指导、市场推广和信息咨询服务等方面的作用，加强行业自律。"},{"i":8,"n":"第八条","txt":"主要产煤省份（内蒙古、山西、陕西、河南、山东、新疆、贵州、安徽、云南等）资源综合利用主管部门，要会同有关部门根据煤炭工业发展规划、矿区总体规划和矿产资源规划等组织编制本行政区域煤矸石综合利用发展规划（或实施方案），并将控制煤矸石利用碳排放纳入当地控制温室气体排放总体工作方案（或低碳发展规划）。"},{"i":9,"n":"第九条","txt":"煤炭开发项目（包括选煤厂项目）的项目核准申请报告中资源开发及综合利用分析篇章中须包括煤矸石综合利用和治理方案，明确煤矸石综合利用途径和处置方式。对未提供煤矸石综合利用方案的煤炭开发项目，有关主管部门不得予以核准。 煤矸石综合利用方案中涉及煤矸石产生单位自行建设的工程，要与煤矿（选煤厂）工程同时设计、同时施工、同时投产使用;涉及为其他单位提供煤矸石的工程，煤矸石利用单位应当具备符合国家产业政策和环境保护要求的生产与处置能力。"},{"i":10,"n":"第十条","txt":"新建（改扩建）煤矿及选煤厂应节约土地、防止环境污染，禁止建设永久性煤矸石堆放场（库）。确需建设临时性堆放场（库）的，其占地规模应当与煤炭生产和洗选加工能力相匹配，原则上占地规模按不超过3年储矸量设计，且必须有后续综合利用方案。煤矸石临时性堆放场（库）选址、设计、建设及运行管理应当符合《一般工业固体废物贮存、处置场污染控制标准》、《煤炭工程项目建设用地指标》等相关要求。"},{"i":11,"n":"第十一条","txt":"煤炭生产企业要因地制宜，采用合理的开采方式，煤炭和耕地复合度高的地区应当采用煤矸石井下充填开采技术，其他具备条件的地区也要优先和积极推广应用此项技术，有效控制地面沉陷、损毁耕地，减少煤矸石排放量。煤炭行业主管部门会同国土资源主管部门制订煤矸石井下充填开采技术标准体系，编制煤矸石井下充填开采方案。"},{"i":12,"n":"第十二条","txt":"利用煤矸石进行土地复垦时，应严格按照《土地复垦条例》和国土、环境保护等相关部门出台的有关规定执行，遵守相关技术规范、质量控制标准和环保要求。"},{"i":13,"n":"第十三条","txt":"煤矸石发电项目应当按照国家有关部门低热值煤发电项目规定进行规划建设，煤矸石使用量不低于入炉燃料的60%（重量比），且收到基低位发热量不低于5020千焦（1200千卡）/千克，应根据煤矸石资源量合理配备循环流化床锅炉及发电机组，并在煤矸石的使用环节配备准确可靠的计量器具。鼓励能量梯级利用，满足周边用户热（冷）负荷需要。对申报资源综合利用认定的发电项目（机组），其入炉混合燃料收到基低位发热量应不高于12550千焦（3000千卡）/千克。"},{"i":14,"n":"第十四条","txt":"煤矸石综合利用要符合国家环境保护相关规定，达标排放。煤矸石发电企业应严格执行《火电厂大气污染物排放标准》等相关标准规定的限值要求和总量控制要求，应建立环保设施管理制度，并实行专人负责;发电机组烟气系统必须安装烟气自动在线监控装置，并符合《固定污染源烟气排放连续监测技术规范》要求，同时保留好完整的脱硫脱硝除尘系统数据，且保存一年以上;煤矸石发电产生的粉煤灰、脱硫石膏、废烟气脱硝催化剂等固体废弃物应按照有关规定进行综合利用和妥善处置。"},{"i":15,"n":"第十五条","txt":"煤矸石产生单位应对既有的煤矸石堆场（库）的安全和环保负责，应制定治理方案，明确整改期限，采取有效综合利用措施消纳煤矸石、消除矸石山；对确难以综合利用的，须采取安全环保措施，并进行无害化处置，按照矿山生态环境保护与恢复治理技术规范等要求进行煤矸石堆场的生态保护与修复，防治煤矸石自燃对大气及周边环境的污染，鼓励对煤矸石山进行植被绿化。"},{"i":16,"n":"第十六条","txt":"下列产品和工程项目，应当符合国家或行业有关质量、环境、节能和安全标准： （一）利用煤矸石生产的建筑材料或其他与煤矸石综合利用相关的产品； （二）煤矸石井下充填置换工程； （三）利用煤矸石或制品的建筑、道路等工程； （四）其他与煤矸石综合利用相关的工程项目。"},{"i":17,"n":"第十七条","txt":"国家鼓励煤矸石大宗利用和高附加值利用： （一）煤矸石井下充填； （二）煤矸石循环流化床发电和热电联产； （三）煤矸石生产建筑材料； （四）从煤矸石中回收矿产品； （五）煤矸石土地复垦及矸石山生态环境恢复； （六）其他大宗、高附加值利用方式。"},{"i":18,"n":"第十八条","txt":"通过国家科技计划（基金、专项）等对煤矸石高附加值利用关键共性技术的自主创新研究和产业化推广给予一定支持。"},{"i":19,"n":"第十九条","txt":"煤矸石利用单位可按照《国家鼓励的资源综合利用认定管理办法》有关要求和程序申报资源综合利用认定。符合条件的，可根据国家有关规定申请享受并网运行、财税等资源综合利用鼓励扶持政策。对符合燃煤发电机组环保电价及环保设施运行管理的煤矸石综合利用发电（含热电联产）企业，可享受环保电价政策。"},{"i":20,"n":"第二十条","txt":"对符合国家或行业质量标准的煤矸石及其制品，设计、施工单位应在设计、建筑施工中优先选用。"},{"i":21,"n":"第二十一条","txt":"各级资源综合利用主管部门应会同相关部门，根据本地区实际情况制定相应的引导、扶持、监管措施。"},{"i":22,"n":"第二十二条","txt":"煤炭开发项目（包括选煤厂项目）正式运行后，煤矸石综合利用未按照项目核准申请报告中的综合利用方案实施的，项目核准部门应监督其限期整改，整改合格后方可进行综合验收。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十条规定，新建（改扩建）煤矿或煤炭洗选企业建设永久性煤矸石堆场的或不符合《煤炭工程项目建设用地指标》要求的，由国土资源等部门监督其限期整改。 违反本办法第十条、第十二条、第十四条、第十六条有关规定对环境造成污染的，由环境保护部门依法处罚；煤矸石发电企业超标排放的，由所在地价格主管部门依据环境保护部门提供的环保设施运行情况，按照燃煤发电机组环保电价及环保设施运行监管办法有关规定罚没其环保电价款，同时环境保护部门每年向社会公告不达标企业名单。 违反本办法第十六条（一）项的，由质量技术监督部门依据《产品质量法》进行处罚；违反本办法第十五条、第十六条（二）（三）（四）项造成安全事故的，由安监部门依据有关规定进行处罚。 对达不到本办法第十三条、第十四条、第十五条、第十六条规定，弄虚作假、不符合质量标准和安全要求、超标排放的，有关部门应及时取消其享受国家相关鼓励扶持政策资格，并限期整改"},{"i":24,"n":"第二十四条","txt":"任何单位和个人在煤矸石堆场取矸时，要明确安全责任主体，制定安全技术措施，不得影响煤矿生产安全，造成财产损失或引发生产安全事故的，安全监管等部门要依法追究相关单位和人员责任。"},{"i":25,"n":"第二十五条","txt":"对获得国家和地方资金支持的煤矸石综合利用项目，所在地区科技、投资、环保等部门应当对项目进展、资金使用、环境影响情况进行监督检查，并进行资源综合利用效果的后评估。"},{"i":26,"n":"第二十六条","txt":"本办法自2015年3月1日起施行。原国家经贸委等八部门联合发布的《煤矸石综合利用管理办法》（国经贸资〔1998〕80号）同时废止。"}],"teshuhexiquemeileikaifaliyongguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为保护和合理开发利用特殊和稀缺煤类，根据《中华人民共和国煤炭法》及有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事特殊和稀缺煤类的开发建设、生产管理、加工利用等活动，必须遵守本规定。"},{"i":3,"n":"第三条","txt":"本规定所称的特殊和稀缺煤类，是指具有某种煤质特征、特殊性能和重要经济价值，资源储量相对较少的煤炭种类，包括肥煤、焦煤、瘦煤和无烟煤等。 国家发展改革委、能源局根据国民经济发展需要，适时公布特殊和稀缺煤类矿区范围(首批公布的特殊和稀缺煤类矿区范围见附件)。"},{"i":4,"n":"第四条","txt":"国家对特殊和稀缺煤类实行保护性开发利用，坚持统一规划、有序开发、总量控制、高效利用的原则，禁止乱采滥挖和浪费行为。"},{"i":5,"n":"第五条","txt":"县级以上煤炭行业管理部门负责特殊和稀缺煤类开发利用的监督管理。"},{"i":6,"n":"第六条","txt":"国家对特殊和稀缺煤类实行生产总量控制，并加强规划管理，优化开发布局。 按照国家的总体要求，省级煤炭行业管理部门可以根据资源储量、市场供需、利用方向等，安排本地区煤炭企业特殊和稀缺煤类的产量。"},{"i":7,"n":"第七条","txt":"特殊和稀缺煤类矿区的资源开发由中方控股。"},{"i":8,"n":"第八条","txt":"特殊和稀缺煤类优先采用露天开采。矿区均衡生产服务年限不得低于矿区规范规定的1.2倍。"},{"i":9,"n":"第九条","txt":"特殊和稀缺煤类煤矿的设计服务年限不得低于煤矿设计规范规定的1.2倍。"},{"i":10,"n":"第十条","txt":"新建大中型特殊和稀缺煤类煤矿投产后10年内，原则上不得通过改扩建、技术改造(产业升级)、资源整合(兼并重组)和生产能力核定等方式提高生产能力。"},{"i":11,"n":"第十一条","txt":"在特殊和稀缺煤类采区范围内不得建设公用工程或者其他工程，确需压覆煤炭资源建设的，应当与煤矿企业充分协商，由省级煤炭行业管理部门报国务院煤炭行业管理部门同意后，方可批准建设，并由建设单位依法对压占资源及其他损失予以补偿。 在未设采区的特殊和稀缺煤类矿区范围内，确需建设公用工程或者其他工程的，由省级煤炭行业管理部门报国务院煤炭行业管理部门备案后，方可组织施工建设。"},{"i":12,"n":"第十二条","txt":"国家鼓励开展极薄煤层、薄煤层、厚煤层等开采技术研究，鼓励生产企业采用无煤柱、充填等开采技术，提高资源回采率。 特殊和稀缺煤类矿井采区回采率：薄煤层不低于88%，中厚煤层不低于83%，厚煤层不低于78%。"},{"i":13,"n":"第十三条","txt":"生产企业不得超能力生产，不得使用落后工艺，不得采厚弃薄、采易弃难。"},{"i":14,"n":"第十四条","txt":"国家鼓励生产企业在安全、合理、经济的前提下，对特殊和稀缺煤类进行复采或者开采边角残煤和极薄煤层等。"},{"i":15,"n":"第十五条","txt":"生产企业应当制定管理制度，对采区回采率完成情况进行考核。 省级煤炭行业管理部门应当定期对生产企业采区回采率等进行考核，并将考核结果抄报国务院煤炭行业管理部门。"},{"i":16,"n":"第十六条","txt":"国家对在特殊和稀缺煤类保护和开采工作中做出突出贡献的单位和个人给予奖励。 达到本规定要求且考核优秀的生产企业，国家发展改革委在煤矿项目核准等方面给予优先安排。"},{"i":17,"n":"第十七条","txt":"因地质条件、安全条件等原因，造成采区或者工作面资源无法开采回收的，生产企业应当及时制定处理方案，报省级煤炭行业管理部门审查批准后方可核销。省级煤炭行业管理部门应当将审查结果抄报国务院煤炭行业管理部门，并抄送同级国土资源管理部门。"},{"i":18,"n":"第十八条","txt":"省级煤炭行业管理部门负责审查生产企业的煤矿储量年度报告，将审查结果抄报国务院煤炭行业管理部门，并抄送同级国土资源管理部门。"},{"i":19,"n":"第十九条","txt":"国家鼓励开展选煤技术研发，提高精煤产率。特殊和稀缺煤类应当全部洗选。"},{"i":20,"n":"第二十条","txt":"经洗选加工的优质特殊和稀缺煤类应当优先用于冶金、化工、材料等行业。限制特殊和稀缺煤类作为燃料直接利用。"},{"i":21,"n":"第二十一条","txt":"违反本规定要求，未达到规定回采率的，由煤炭行业管理部门责令限期改正;逾期仍达不到规定回采率的，责令停止生产。"},{"i":22,"n":"第二十二条","txt":"生产企业有下列情形之一的，由省级煤炭行业管理部门责令限期改正;逾期不改正的，处三万元的罚款。 (一)超过省级煤炭行业管理部门安排的产量限额进行生产的; (二)未按照本规定第十七条要求制定处理方案并报审核; (三)未按照本规定第十八条要求报送煤矿储量年度报告。"},{"i":23,"n":"第二十三条","txt":"国家机关工作人员违反本规定，徇私舞弊、玩忽职守、滥用职权的，由其所在机关或者上级机关依法给予处分;构成犯罪的，由司法机关依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"本规定所称的生产企业，是指从事特殊和稀缺煤类生产的煤矿企业。"},{"i":25,"n":"第二十五条","txt":"本规定由国家发展改革委、能源局负责解释。"},{"i":26,"n":"第二十六条","txt":"省级煤炭行业管理部门可以依据本规定，结合本地区实际制定实施细则，并报国务院煤炭行业管理部门备案。"},{"i":27,"n":"第二十七条","txt":"本规定自发布之日起30日后施行。 附件："}],"shengchanmeikuanghuicailvguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为合理开发和保护煤炭资源，提高煤炭资源回采率，根据《中华人民共和国煤炭法》及有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中华人民共和国境内从事煤炭生产的煤矿企业。"},{"i":3,"n":"第三条","txt":"煤矿企业应当执行煤炭开采相关规定，遵循合理开采程序，加强煤炭资源管理，达到本规定要求的煤炭资源回采率。"},{"i":4,"n":"第四条","txt":"煤矿企业主要负责人对本企业生产煤矿回采率负第一责任人责任，总工程师负技术责任。"},{"i":5,"n":"第五条","txt":"国家发展改革委、国家能源局负责全国生产煤矿回采率的监督管理。 县级以上地方人民政府煤炭行业管理部门负责本行政区域内生产煤矿回采率的监督管理。"},{"i":6,"n":"第六条","txt":"煤矿设计单位应当严格执行有关规定，采区设计回采率不得低于本规定的要求。"},{"i":7,"n":"第七条","txt":"生产煤矿回采率的确定应当坚持安全效益、分类指导的原则，煤矿企业必须合理开采煤炭资源。"},{"i":8,"n":"第八条","txt":"煤矿企业必须开采井田范围内的可采煤层。可采煤层的标准如下表： 缺煤地区可采煤层标准，由省级煤炭行业管理部门依据有关规定，结合本地区实际情况制定。"},{"i":9,"n":"第九条","txt":"具备下列情形之一的可采煤层，经具有相关资质单位论证并报请省级煤炭行业管理部门批准，可以不采或者暂时不采： (一)具有重大灾害威胁的(水、火、冲击地压、煤与瓦斯突出等); (二)受地质构造影响严重、岩浆侵蚀破坏严重、不稳定煤层局部达到可采厚度的孤立块段，开采其他煤层又不会造成破坏的; (三)受其他煤矿、煤层开采影响，无法安全开采或者开采极为困难的。"},{"i":10,"n":"第十条","txt":"生产煤矿回采率主要考核采区回采率。采区回采率按如下公式计算： 采区采出煤量是指采区内所有工作面采出煤量与掘进煤量之和。 采区动用储量是指采区采出煤量与损失煤量之和。"},{"i":11,"n":"第十一条","txt":"井工煤矿采区回采率标准："},{"i":12,"n":"第十二条","txt":"露天煤矿采区回采率标准："},{"i":13,"n":"第十三条","txt":"具备下列情形之一的煤矿，由省级煤炭行业管理部门组织对其回采率考核指标进行评估修正，并报国务院煤炭行业管理部门备案： (一)地质构造复杂，厚煤层、中厚煤层和薄煤层的水文地质损失量分别超过可采储量20%、15%和10%的; (二)煤层赋存不稳定，采区可采范围经井下勘探证实不足采区开采范围50%的; (三)开采“三下一上”(铁路下、水体下、建(构)筑物下和承压水体上)煤层的。"},{"i":14,"n":"第十四条","txt":"煤矿企业应当建立健全生产煤矿回采率管理制度，依照国家有关规定编制生产煤矿回采率管理图表和台账。"},{"i":15,"n":"第十五条","txt":"煤矿企业应当健全回采率管理机构，配备回采率管理人员，负责本单位回采率管理工作。"},{"i":16,"n":"第十六条","txt":"煤矿企业应当根据地质条件和煤层赋存状况，选择合理的采煤方法，不得吃肥丢瘦、浪费煤炭资源。"},{"i":17,"n":"第十七条","txt":"矿井开采煤层群时，应当按照由上而下的顺序进行开采，不得弃采薄煤层。确需反顺序开采的，经具有相关资质单位论证并报请省级煤炭行业管理部门批准后实施。"},{"i":18,"n":"第十八条","txt":"具备分层开采的缓倾斜厚煤层，原则上应当坚持分层开采。 对采用一次采全高开采的厚煤层，不得丢顶煤、底煤或者用煤皮作假顶。"},{"i":19,"n":"第十九条","txt":"凡有条件的新矿井、新水平和新采区，应当优先集中开拓，联合布置，实现合理集中生产;应当不断优化采区设计，合理加大水平、阶段垂高与采区走向长度和工作面长度，改进巷道布置，减少煤柱损失。"},{"i":20,"n":"第二十条","txt":"矿井留设保护煤柱必须符合有关规定，经批准的煤柱不得随意扩大。 鼓励有条件的矿井采用无煤柱开采、充填开采等开采技术。"},{"i":21,"n":"第二十一条","txt":"薄煤层优先采用机械化开采，提高资源回采率。"},{"i":22,"n":"第二十二条","txt":"煤矿企业应当定期组织开展生产煤矿回采率检查，并将采区回采率作为考核企业领导班子成员、管理人员及从业人员的重要指标。 煤矿企业应当定期开展回采率评优活动，对成绩突出的集体和个人给予奖励。"},{"i":23,"n":"第二十三条","txt":"实行煤矿储量、损失量年报和采区回采率月报、季报、年报制度，具体办法由省级煤炭行业管理部门制定。 每年3月底前，采区回采率年报由省级煤炭行业管理部门审核后，报国务院煤炭行业管理部门备案。"},{"i":24,"n":"第二十四条","txt":"各级煤炭行业管理部门应当对辖区内生产煤矿回采率进行不定期抽查，并将抽查情况向社会公布。"},{"i":25,"n":"第二十五条","txt":"各级煤炭行业管理部门应当对辖区内生产煤矿回采率进行年度考核，公布考核结果。 考核结果可作为安排矿产资源节约与综合利用奖励资金和企业缴纳资源税的依据。"},{"i":26,"n":"第二十六条","txt":"国家鼓励煤矿企业采用新技术、新工艺、新装备提高回采率。凡符合下列条件之一的，由各级煤炭行业管理部门给予表彰或者奖励： (一)创造、采用、推广提高采区回采率的新技术、新工艺、新装备以及新管理办法，使采区回采率高于规定指标，取得较显著经济效益的; (二)在安全、经济、合理的原则下，对小于可采厚度的薄煤层进行开采的; (三)对由于各种原因丢弃的残煤和煤柱，在安全、经济、合理的原则下，通过复采等形式最大限度地采出或利用的。"},{"i":27,"n":"第二十七条","txt":"对违反本规定第六条要求的设计单位，煤炭行业管理部门责令改正，并通报相关部门依法查处;由资质认定单位视情节轻重，依法降低资质等级或者吊销资质证书。"},{"i":28,"n":"第二十八条","txt":"生产煤矿未达到本规定第十一条、第十二条采区回采率标准的，由煤炭行业管理部门责令限期改正;逾期仍不达标的，责令停止生产。"},{"i":29,"n":"第二十九条","txt":"煤矿企业有下列情形之一的，由煤炭行业管理部门责令限期改正;逾期不改正的，处三万元罚款;构成犯罪的，依法追究刑事责任： (一)对可采煤层丢弃不采的; (二)违反开采顺序的; (三)一次采全高开采丢顶煤、底煤或者用煤皮作假顶的; (四)留设保护煤柱不符合有关规定的; (五)未按规定提交采区回采率报告的。"},{"i":30,"n":"第三十条","txt":"国家机关工作人员违反本规定，徇私舞弊、玩忽职守、滥用职权的，由任免机关或者监察机关按照管理权限给予相应的政纪处分;涉嫌犯罪的，移送司法机关追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"本规定由国家发展改革委、国家能源局负责解释。"},{"i":32,"n":"第三十二条","txt":"省级煤炭行业管理部门可以根据本规定制定实施细则。"},{"i":33,"n":"第三十三条","txt":"本规定自发布之日起三十日后施行，《生产矿井煤炭资源回采率暂行管理办法》(煤炭工业部令[1998]第5号)同时废止。"}],"dianliqiyexinxibaosongguiding":[{"i":1,"n":"第一条","txt":"为了加强电力监管，规范电力企业、电力调度机构、电力交易机构信息报送行为，维护电力市场秩序，根据《电力监管条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"电力企业、电力调度机构、电力交易机构向国家发展改革委、国家能源局及其派出机构、省级政府主管部门报送与监管事项相关的文件、资料，适用本规定。"},{"i":3,"n":"第三条","txt":"电力企业、电力调度机构、电力交易机构报送信息遵循真实、及时、完整的原则。"},{"i":4,"n":"第四条","txt":"国家能源局及其派出机构根据电力企业、电力调度机构、电力交易机构报送的信息，对电力企业、电力调度机构、电力交易机构依法从事电力业务的情况实施监管。"},{"i":5,"n":"第五条","txt":"从事发电业务的企业应当报送下列信息： （一）企业基本情况； （二）签订和履行并网调度协议、购售电合同的情况； （三）上网电价情况； （四）电力市场交易情况； （五）燃料购入、消耗、库存情况； （六）煤电等电源项目纳入规划核准、开工、投产情况； （七）电力安全生产情况； （八）国家能源局及其派出机构要求报送的其他信息。"},{"i":6,"n":"第六条","txt":"从事输电业务的企业应当报送下列信息： （一）企业基本情况、企业生产经营情况； （二）电网结构情况，网内发电装机分布和容量情况； （三）签订和履行购售电合同的情况； （四）执行输电电价情况； （五）输电成本构成及其变动情况； （六）输电通道运行情况； （七）电费结算情况； （八）可再生能源电力消纳量完成情况； （九）电力安全生产情况； （十）国家能源局及其派出机构要求报送的其他信息。"},{"i":7,"n":"第七条","txt":"从事供电业务的企业应当报送下列信息： （一）企业基本情况； （二）提供供电服务的情况； （三）提供电力社会普遍服务的情况； （四）执行配电电价、销售电价的情况； （五）供电成本构成及其变动情况； （六）电力安全生产情况； （七）国家能源局及其派出机构要求报送的其他信息。"},{"i":8,"n":"第八条","txt":"电力调度机构应当报送下列信息： （一）电力系统运行情况； （二）电力供需形势情况； （三）执行电力市场运行规则、电力调度规则和电网运行规则的情况； （四）电力现货市场、电力辅助服务市场运行情况（含跨区跨省交易）； （五）电力并网运行管理、电力辅助服务管理情况； （六）签订和履行并网调度协议的情况； （七）电力安全生产情况； （八）国家能源局及其派出机构要求报送的其他信息。"},{"i":9,"n":"第九条","txt":"电力交易机构应当报送下列信息： （一）执行电力市场运行规则情况； （二）电力中长期市场运行情况（含跨区跨省交易）； （三）电力市场结算、清算情况； （四）电力市场信息披露情况； （五）国家指令性计划、政府间框架协议执行情况； （六）国家能源局及其派出机构要求报送的其他信息。"},{"i":10,"n":"第十条","txt":"国家能源局省级派出机构（以下简称省级派出机构）辖区内的电力企业、省级电力调度机构、省级电力交易机构向省级派出机构、省级政府主管部门报送信息。省级派出机构汇总后报国家能源局。 未设立省级派出机构的省、自治区、直辖市范围内的电力企业、省级电力调度机构、省级电力交易机构，向国家能源局区域派出机构（以下简称区域派出机构）、省级政府主管部门报送信息。"},{"i":11,"n":"第十一条","txt":"中国南方电网有限责任公司、国家电网公司所属区域电网公司、区域电力调度机构向区域派出机构报送信息。"},{"i":12,"n":"第十二条","txt":"区域派出机构汇总本辖区内的信息，报国家发展改革委、国家能源局。"},{"i":13,"n":"第十三条","txt":"中央电力企业、国家电力调度机构向国家发展改革委、国家能源局报送信息。"},{"i":14,"n":"第十四条","txt":"电力企业、电力调度机构、电力交易机构应当指定具体负责信息报送的机构和人员，并报国家能源局及其派出机构备案。"},{"i":15,"n":"第十五条","txt":"电力企业、电力调度机构、电力交易机构报送信息，应当经本单位负责的主管人员审核、签发，重要信息应当经主要负责人签发。"},{"i":16,"n":"第十六条","txt":"国家能源局及其派出机构根据电力企业、电力调度机构、电力交易机构报送信息的内容，确定具体的报送形式和期限。"},{"i":17,"n":"第十七条","txt":"电力企业、电力调度机构、电力交易机构应当按照有关规定，通过信函、电报、电传、传真、电子数据交换和电子邮件等方式报送信息。"},{"i":18,"n":"第十八条","txt":"电力企业、电力调度机构、电力交易机构报送信息应当按照有关规定，填报报表、提交报告或者提供有关材料。"},{"i":19,"n":"第十九条","txt":"电力企业、电力调度机构、电力交易机构报送信息应当符合下列期限要求： （一） 日报应当在下一日12时前报出； （二） 周报或者旬报应当在下一周或者下一旬的第2个工作日前报出； （三）月报应当在下一月的8日前报出； （四）季报应当在下一季度的第12日前报出； （五）年报快报应当在下一年的1月20日前报出； （六）年报应当在下一年的3月20日前报出。 电力企业、电力调度机构、电力交易机构应当按照国家能源局的有关规定将与监管相关的信息系统接入电力监管信息系统，报送有关实时信息。 电力安全生产信息、企业财务信息的报送期限，法律、法规、规章另有规定的，从其规定。"},{"i":20,"n":"第二十条","txt":"电力监管机构根据履行监管职责的需要，要求电力企业、电力调度机构、电力交易机构及时报送有关信息的，电力企业、电力调度机构、电力交易机构应当按照要求报送。"},{"i":21,"n":"第二十一条","txt":"电力企业、电力调度机构、电力交易机构未能按照规定期限报送信息的，应当及时向国家能源局及其派出机构报告，并在国家能源局及其派出机构批准的期限内补报。"},{"i":22,"n":"第二十二条","txt":"国家能源局及其派出机构审查电力企业、电力调度机构、电力交易机构报送的信息，发现有违反电力监管法规、规章情形的，应当责令其改正并按照有关规定做出处理。"},{"i":23,"n":"第二十三条","txt":"国家能源局及其派出机构审查电力企业、电力调度机构、电力交易机构报送的信息，发现电力企业、电力调度机构、电力交易机构在安全生产、成本管理、服务质量等方面存在问题的，应当对其提出整改建议。"},{"i":24,"n":"第二十四条","txt":"国家能源局及其派出机构整理、分析电力企业、电力调度机构、电力交易机构报送的信息，适时向社会公开。"},{"i":25,"n":"第二十五条","txt":"国家能源局及其派出机构建立电力企业报送信息的内部管理制度，明确工作程序、职责分工和责任。国家发展改革委、国家能源局及其派出机构、省级政府主管部门工作人员应当严格遵守保密纪律，保守在监管工作中知悉的国家秘密、商业秘密。"},{"i":26,"n":"第二十六条","txt":"国家能源局及其派出机构对电力企业、电力调度机构、电力交易机构报送信息的情况进行监督检查。"},{"i":27,"n":"第二十七条","txt":"国家能源局及其派出机构通过网站等媒介定期通报电力企业、电力调度机构、电力交易机构信息报送情况，对在信息报送工作中表现突出的单位和人员给予表彰。"},{"i":28,"n":"第二十八条","txt":"电力企业、电力调度机构、电力交易机构未按照本规定报送信息的，由国家能源局及其派出机构责令其改正；情节严重的，给予通报批评。"},{"i":29,"n":"第二十九条","txt":"电力企业、电力调度机构、电力交易机构提供虚假信息或者隐瞒重要事实的，依照《电力监管条例》有关规定处理。"},{"i":30,"n":"第三十条","txt":"国家能源局派出机构根据本规定制定实施办法，报国家能源局批准后执行。"},{"i":31,"n":"第三十一条","txt":"本规定自2024年4月1日起施行。原2005年11月30日发布的《电力企业信息报送规定》（原国家电力监管委员会令第13号）同时废止。"}],"dianlikekaoxingguanlibanfa":[{"i":1,"n":"第一条","txt":"能源安全事关国家经济社会发展全局，电力供应保障是能源安全的重要组成部分。党中央、国务院高度重视电力供应保障工作，习近平总书记多次作出重要指示批示。为充分发挥电力可靠性管理在电力供应保障工作中的基础性作用，促进电力工业高质量发展，提升供电水平，满足人民日益增长的美好生活需要，依据《中华人民共和国电力法》《电力供应与使用条例》《电网调度管理条例》《电力设施保护条例》和《电力监管条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"电力可靠性管理是指为提高电力可靠性水平而开展的管理活动，包括电力系统、发电、输变电、供电、用户可靠性管理等。"},{"i":3,"n":"第三条","txt":"电力企业和电力用户依照本办法开展电力可靠性管理工作。国家能源局及其派出机构、地方政府能源管理部门和电力运行管理部门依据本办法对电力可靠性管理工作进行监督管理。"},{"i":4,"n":"第四条","txt":"国家能源局负责全国电力可靠性的监督管理，国家能源局派出机构、地方政府能源管理部门和电力运行管理部门根据各自职责和国家有关规定负责辖区内的电力可靠性监督管理。"},{"i":5,"n":"第五条","txt":"电力企业是电力可靠性管理的重要责任主体，其法定代表人是电力可靠性管理第一责任人。电力企业按照下列要求开展本企业电力可靠性管理工作： (一)贯彻执行国家有关电力可靠性管理规定，制定本企业电力可靠性管理工作制度; (二)建立电力可靠性管理工作体系，落实电力可靠性管理相关岗位及职责; (三)采集分析电力可靠性信息，并按规定准确、及时、完整报送; (四)开展电力可靠性管理创新、成果应用以及培训交流。"},{"i":6,"n":"第六条","txt":"电力用户是其产权内配用电系统和设备可靠性管理的责任主体，做好配用电系统和设备的配置与运行维护。"},{"i":7,"n":"第七条","txt":"鼓励电力设备制造企业充分应用电力可靠性管理的成果，加强产品可靠性设计、试验及生产过程质量控制，依靠技术进步、管理创新和标准完善，提升设备可靠性水平。"},{"i":8,"n":"第八条","txt":"充分发挥行业协会等的作用，开展行业自律和服务，提供技术支持，推动可靠性信息应用，开展交流与合作。"},{"i":9,"n":"第九条","txt":"电力系统可靠性管理指为保障电力系统充裕性和安全性而开展的活动，包括电力系统风险的事前预测预警、事中过程管控、事后总结评估及采取的防范措施。"},{"i":10,"n":"第十条","txt":"电网企业应当对电力供应及安全风险进行预测，对运行数据开展监测分析并评估电力系统满足电力电量需求的能力。在系统稳定破坏事件、影响系统安全的非计划停运事件和停电事件发生时，电网企业应当依据《电网调度管理条例》果断快速处置;开展事后评价，对发现的风险进行闭环管控。"},{"i":11,"n":"第十一条","txt":"电网企业应当根据电力系统风险和自然灾害影响，制定风险管控措施，完善输电系统网络结构。对发现的风险和隐患按规定向政府有关部门和相关电力企业预警。"},{"i":12,"n":"第十二条","txt":"发电企业和配置自备发电机组的其他企业要根据政府有关部门和电力调度机构的要求做好电力供应保障工作，提高设备运行可靠性，不得无故停运或隐瞒真实原因申请停运。 发电企业应当做好涉网安全管理，加强机组燃料、蓄水管控，制定重要时期的燃料计划与预案，制定水库调度运行计划，对发现的风险和隐患及时报电力调度机构。 新能源发电企业应当加强发电功率预测管理。"},{"i":13,"n":"第十三条","txt":"积极稳妥推动发电侧、电网侧和用户侧储能建设，合理确定建设规模，加强安全管理，推进源网荷储一体化和多能互补。建立新型储能建设需求发布机制，充分考虑系统各类灵活性调节资源的性能，允许各类储能设施参与系统运行，增强电力系统的综合调节能力。"},{"i":14,"n":"第十四条","txt":"各级能源管理部门应当科学制定并适时调整电力规划，优化配置各种类型的电源规模和比例，统筹安排备用容量，合理划分黑启动区域。国家能源局派出机构应当对辖区省级电力规划的执行情况进行监管。 负荷备用容量为最大发电负荷的2-5%，事故备用容量为最大发电负荷的10%左右，区外来电、新能源发电、不可中断用户占比高的地区，应当适当提高负荷备用容量。每个黑启动区域须合理配置1-2台具备黑启动能力且具有足够容量的机组。"},{"i":15,"n":"第十五条","txt":"经国务院批复的国家级城市群，应当适当提高电力可靠性标准，加强区域电力系统的统筹规划和项目建设衔接，优化资源配置，推进电网协调有序发展。"},{"i":16,"n":"第十六条","txt":"国家能源局及其派出机构应当按照权限和程序，指导有关单位制订大面积停电应急预案，组织、协调、指导电力突发安全事件应急处置工作，对电力供应和运行的风险管控情况进行监管。地方政府电力运行管理部门应当会同有关部门开展电力需求侧管理，严格审核事故及超计划用电的限电序位表，严禁发生非不可抗力拉闸限电。"},{"i":17,"n":"第十七条","txt":"发电可靠性管理是指为实现发电机组及配套设备的可靠性目标而开展的活动，包括并网燃煤(燃气)、水力、核能、风力、太阳能等发电机组及配套设备的可靠性管理。"},{"i":18,"n":"第十八条","txt":"燃煤(燃气)发电企业应当对参与深度调峰的发电机组开展可靠性评估，加强关键部件监测，确保调峰安全裕度。电力调度机构应当优化调峰控制策略，综合考虑发电机组的安全性和经济性。"},{"i":19,"n":"第十九条","txt":"水电流域梯级电站和具备调节性能的水电站应当建立水情自动测报系统，做好电站水库优化调度，建立信息共享机制。"},{"i":20,"n":"第二十条","txt":"核电企业应当对常规岛和配套设备(非核级设备)开展设备分级、监测与诊断、健康管理、全寿命周期可靠性管理、动态风险评价等工作。"},{"i":21,"n":"第二十一条","txt":"沙漠、戈壁、荒漠地区的大规模风力、太阳能等可再生能源发电企业要建立与之适应的电力可靠性管理体系，加强系统和设备的可靠性管理，防止大面积脱网，对电网稳定运行造成影响。"},{"i":22,"n":"第二十二条","txt":"发电企业应当建立发电设备分级管理制度，完善事故预警机制，构建设备标准化管理流程。发电企业应当基于可靠性信息，建立动态优化的设备运行、检修和缺陷管理体系，定期评估影响机组可靠性的风险因素，掌握设备状态、特性和运行规律，发挥对机组运行维护的指导作用。"},{"i":23,"n":"第二十三条","txt":"地方政府能源管理部门和电力运行管理部门应当对燃煤(燃气)发电企业的燃料库存、水电站入库水量情况进行监测分析、协调处理，保障能源供应。"},{"i":24,"n":"第二十四条","txt":"输变电可靠性管理是指为实现输变电系统和设备的可靠性目标而开展的活动，包括交流和直流的输变电系统和设备的可靠性管理。"},{"i":25,"n":"第二十五条","txt":"电力企业应当合理安排变电站站址和线路路径，科学选择主接线和站间联络方式，增加系统运行的安全裕度。"},{"i":26,"n":"第二十六条","txt":"电力企业应当加强线路带电作业、无人机巡检、设备状态监测等先进技术应用，优化输变电设备运维检修模式。"},{"i":27,"n":"第二十七条","txt":"鼓励电力企业基于可靠性数据开展电力设备选型和运行维护工作，建立核心组部件溯源管理机制，优先选用高可靠性的输变电设备，鼓励开展状态检修，提高设备运行可靠性。"},{"i":28,"n":"第二十八条","txt":"地方政府能源管理部门和电力运行管理部门按职责组织指导开展电力设施保护工作。"},{"i":29,"n":"第二十九条","txt":"供电可靠性管理是指为实现向用户可靠供电的目标而开展的活动，包括配电系统和设备的可靠性管理。"},{"i":30,"n":"第三十条","txt":"供电企业应当加强城乡配电网建设，合理设置变电站、配变布点，合理选择配电网接线方式，保障供电能力。"},{"i":31,"n":"第三十一条","txt":"供电企业应当强化设备的监测和分析，加强巡视和维护，及时消除设备缺陷和隐患。"},{"i":32,"n":"第三十二条","txt":"供电企业应当开展综合停电和配电网故障快速抢修复电管理，推广不停电作业和配电自动化等技术，减少停电时间、次数和影响范围。"},{"i":33,"n":"第三十三条","txt":"地方政府能源管理部门应当将供电可靠性指标纳入电力系统规划，并与城乡建设总体规划衔接。"},{"i":34,"n":"第三十四条","txt":"地方政府发展改革部门可依据本地区供电可靠性水平，按照合理成本和优质优价原则，完善可靠性电价机制。"},{"i":35,"n":"第三十五条","txt":"用户可靠性管理是指为保证用电的可靠性目标，减少对电网安全和其他用户造成影响，对其产权内的配用电系统和设备开展的活动。"},{"i":36,"n":"第三十六条","txt":"电力用户应当根据国家有关规定和标准开展配用电工程建设与运行维护，消除设备隐患，预防电气设备事故，防止对公用电网造成影响。"},{"i":37,"n":"第三十七条","txt":"电力用户配用电设备危及系统安全时，应当立即检修或者停用。因用户原因导致电力企业无法向其他用户正常供电或造成其他严重后果的，应当承担相应责任。"},{"i":38,"n":"第三十八条","txt":"重要电力用户应当按规定配置自备应急电源，加强运行维护，容量应当达到保安负荷的120%。地方政府电力运行管理部门应当确定重要电力用户名单，对重要电力用户自备应急电源配置和使用情况进行监督管理。国家能源局派出机构对重要电力用户供电电源配置情况进行监督管理。"},{"i":39,"n":"第三十九条","txt":"供电企业应当按规定为重要电力用户提供相应的供电电源，指导和督促重要用户安全使用自备应急电源。对重要电力用户较为集中的区域，供电企业应当科学合理规划和建设供电设施，及时满足重要用户用电需要，确保供电能力和供电质量。"},{"i":40,"n":"第四十条","txt":"电力网络安全坚持积极防御、综合防范的方针，坚持安全分区、网络专用、横向隔离、纵向认证的原则，加强全业务、全生命周期网络安全管理，提高电力可靠性。"},{"i":41,"n":"第四十一条","txt":"电力企业应当落实网络安全保护责任，健全网络安全组织体系，设立专门的网络安全管理及监督机构，加快各级网络安全专业人员配备;落实网络安全等级保护、关键信息基础设施安全保护和数据安全制度，加强网络安全审查、容灾备份、监测审计、态势感知、纵深防御、信任体系建设、供应链管理等工作;开展网络安全监测、风险评估和隐患排查治理，提高网络安全监测分析与应急处置能力。"},{"i":42,"n":"第四十二条","txt":"电力企业应当强化电力监控系统安全防护，完善结构安全、本体安全和基础设施安全，逐步推广安全免疫。电力企业应当开展电力监控系统安全防护评估，并将其纳入电力系统安全评价体系。电力调度机构应当加强对直接调度范围内的发电厂涉网部分电力监控系统安全防护的技术监督。"},{"i":43,"n":"第四十三条","txt":"电力用户是其产权内配用电系统和设备网络安全责任主体，应当根据国家有关规定和标准开展网络安全防护，预防网络安全事件，防止对公用电网造成影响。电力企业应当在并网协议中明确网络安全相关要求并监督落实。"},{"i":44,"n":"第四十四条","txt":"国家能源局依法依规履行电力行业网络安全监督管理职责，地方各级人民政府有关部门按照法律、行政法规和国务院的规定，履行网络安全属地监督管理职责，国家能源局派出机构根据授权开展网络安全监督管理工作。"},{"i":45,"n":"第四十五条","txt":"电力可靠性信息实行统一管理、分级负责。国家能源局负责全国电力可靠性信息的统计、分析、发布和核查，国家能源局派出机构负责辖区内电力可靠性信息分析、发布和核查。 根据工作需要，国家能源局及其派出机构可以委托行业协会、科研单位及技术咨询机构等协助开展电力可靠性信息统计分析、预测、评估、评价等工作。"},{"i":46,"n":"第四十六条","txt":"国家能源局应当建立电力可靠性监督管理信息系统，实施全国范围内电力可靠性信息注册、报送、分析、评价、应用、核查等监督管理工作，通过电力可靠性监督管理信息系统实时向国家能源局派出机构、省级政府能源管理部门和电力运行管理部门推送辖区内电力可靠性信息。"},{"i":47,"n":"第四十七条","txt":"电力企业应当建立电力可靠性信息报送机制和校核制度，准确、及时、完整报送电力可靠性信息。 供电企业应当按国家有关规定定期公布供电可靠性指标。"},{"i":48,"n":"第四十八条","txt":"电力企业应当通过电力可靠性监督管理信息系统向国家能源局报送以下电力可靠性信息： (一)发电设备可靠性信息，包括100兆瓦及以上容量火力发电机组、300兆瓦及以上容量核电机组常规岛、50兆瓦及以上容量水力发电机组的可靠性信息，总装机50兆瓦及以上容量风力发电场、10兆瓦及以上集中式太阳能发电站的可靠性信息; (二)输变电设备可靠性信息，包括110(66)千伏及以上电压等级输变电设备可靠性信息; (三)直流输电系统可靠性信息，包括±120千伏及以上电压等级直流输电系统可靠性信息; (四)供电可靠性信息，包括35千伏及以下电压等级供电系统用户可靠性信息; (五)其他电力可靠性信息。"},{"i":49,"n":"第四十九条","txt":"电力可靠性信息报送应当符合下列期限要求： (一)每月8日前报送上月火力发电机组主要设备、核电机组、水力发电机组、输变电设备、直流输电系统以及供电系统用户可靠性信息; (二)每季度首月12日前报送上一季度发电机组辅助设备、风力发电场和太阳能发电站的可靠性信息。"},{"i":50,"n":"第五十条","txt":"电力企业应当于每年2月15日前将上一年度电力可靠性管理和技术分析报告报送所在地国家能源局派出机构、省级政府能源管理部门和电力运行管理部门;中央电力企业总部于每年3月1日前报送国家能源局。 省级电网企业应当于每年1月份将上一年度电力系统可靠性的评估和本年度的预测情况，报国家能源局派出机构、省级政府能源管理部门和电力运行管理部门;中央电网企业总部于每年2月份报送国家能源局。 系统稳定破坏事件、非计划停运事件、停电事件的等级分类、信息报送内容和程序由国家能源局另行规定。"},{"i":51,"n":"第五十一条","txt":"国家能源局应当定期发布电力可靠性指标。"},{"i":52,"n":"第五十二条","txt":"电力可靠性监督管理信息系统中的原始信息、统计分析信息及年度电力可靠性评价、评估、预测结果等须按程序经国家能源局审核后对外发布或使用。"},{"i":53,"n":"第五十三条","txt":"国家能源局负责以下电力可靠性监督管理工作： (一)研究起草电力可靠性监督管理规章、制定电力可靠性监督管理规范性文件和电力可靠性行业技术标准，并组织实施; (二)建立健全电力可靠性监督管理工作体系; (三)对国家能源局派出机构、地方政府能源管理部门和电力运行管理部门、电力企业、电力用户贯彻执行电力可靠性管理规章制度的情况进行监督管理; (四)组织建立电力可靠性监督管理信息系统，统计分析电力可靠性信息，组织实施电力可靠性预测、评估和评价工作; (五)组织开展电力可靠性管理工作检查、核查; (六)发布电力可靠性指标和电力可靠性监管报告; (七)对特别重大系统稳定破坏事件、特别重大非计划停运事件、特别重大停电事件进行分析、核查; (八)推动电力可靠性理论研究和技术应用; (九)组织电力可靠性技术和管理培训; (十)开展电力可靠性国际交流与合作。"},{"i":54,"n":"第五十四条","txt":"国家能源局派出机构负责辖区内以下电力可靠性监督管理工作： (一)建立健全电力可靠性监督管理工作体系; (二)对电力企业贯彻执行电力可靠性管理规章制度的情况进行监督管理; (三)分析、发布可靠性信息，组织实施电力可靠性预测、评估和评价工作; (四)开展电力可靠性管理工作检查、核查、处罚; (五)对重大系统稳定破坏事件、重大非计划停运事件、重大停电事件进行分析、核查; (六)监督指导电力企业排查治理电力可靠性管理中发现的风险和隐患; (七)发布电力可靠性指标和电力可靠性监管报告。"},{"i":55,"n":"第五十五条","txt":"地方政府能源管理部门和电力运行管理部门按各自职责负责辖区内以下电力可靠性监督管理工作： (一)建立健全地方政府电力可靠性监督管理工作体系; (二)对电力系统的充裕性进行监测协调和监督管理，保障电力供应; (三)对电力用户贯彻执行电力可靠性管理规章制度的情况进行监督管理; (四)组织落实国家乡村振兴、优化营商环境、电网升级改造等工作中相关电力可靠性要求; (五)监督指导重要电力用户排查治理电力可靠性管理中发现的风险和隐患; (六)支持和配合国家能源局派出机构开展相关电力可靠性监督管理工作。"},{"i":56,"n":"第五十六条","txt":"国家能源局派出机构应当会同地方政府能源管理部门和电力运行管理部门建立电力可靠性联席协调机制，定期分析、通报电力供需和电网运行情况，协调解决电力供应和电力系统稳定运行面临的问题。"},{"i":57,"n":"第五十七条","txt":"国家能源局及其派出机构、地方政府能源管理部门和电力运行管理部门对电力可靠性管理规章制度落实情况进行监督检查，可以采取以下措施： (一)进入电力企业进行检查并询问相关人员，要求其对检查事项作出说明; (二)查阅、复制与检查事项有关的文件、资料和信息。"},{"i":58,"n":"第五十八条","txt":"国家能源局及其派出机构、地方政府能源管理部门和电力运行管理部门对电力企业报送的信息和报告存在疑问的，应当要求作出说明，可以开展现场核查。"},{"i":59,"n":"第五十九条","txt":"任何单位和个人发现电力可靠性管理不到位或存在弄虚作假情况的，有权向国家能源局及其派出机构、地方政府能源管理部门和电力运行管理部门举报，国家能源局及其派出机构、地方政府能源管理部门和电力运行管理部门应当及时处理。"},{"i":60,"n":"第六十条","txt":"鼓励电力企业、科研单位和电力用户等根据电力规划、建设、生产、供应、使用和设备制造等工作需要，研究、开发和采用先进的可靠性科学技术和管理方法，对取得显著成绩的单位和个人给予表彰奖励。"},{"i":61,"n":"第六十一条","txt":"国家能源局及其派出机构、地方政府能源管理部门和电力运行管理部门未按照本办法实施电力可靠性监督管理有关工作并造成严重后果的，依法追究其责任。"},{"i":62,"n":"第六十二条","txt":"电力企业有下列情形之一的，由国家能源局及其派出机构根据《电力监管条例》第三十四条的规定予以处罚： (一)拒绝或者阻碍国家能源局及其派出机构从事电力可靠性监管工作的人员依法履行监管职责的; (二)提供虚假或者隐瞒重要事实的电力可靠性信息的; (三)供电企业未按照本办法规定定期披露其供电可靠性指标的。"},{"i":63,"n":"第六十三条","txt":"国家能源局及其派出机构、地方政府能源管理部门和电力运行管理部门按照电力行业信用体系规定，对电力可靠性监督检查过程中产生的约谈、通报、奖励、处罚等记录依法依规进行归集、共享和公示，对相应的责任主体依法实施守信激励与失信惩戒。"},{"i":64,"n":"第六十四条","txt":"本办法自2022年6月1日起施行，《电力可靠性监督管理办法》(国家电力监管委员会令第24号)同时废止。"}],"dianlianquanshengchanjianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为了有效实施电力安全生产监督管理，预防和减少电力事故，保障电力系统安全稳定运行和电力可靠供应，依据《中华人民共和国安全生产法》、《中华人民共和国突发事件应对法》、《电力监管条例》、《生产安全事故报告和调查处理条例》、《电力安全事故应急处置和调查处理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内以发电、输电、供电、电力建设为主营业务并取得相关业务许可或按规定豁免电力业务许可的电力企业。"},{"i":3,"n":"第三条","txt":"国家能源局及其派出机构依照本办法，对电力企业的电力运行安全(不包括核安全)、电力建设施工安全、电力工程质量安全、电力应急、水电站大坝运行安全和电力可靠性工作等方面实施监督管理。"},{"i":4,"n":"第四条","txt":"电力安全生产工作应当坚持“安全第一、预防为主、综合治理”的方针，建立电力企业具体负责、政府监管、行业自律和社会监督的工作机制。"},{"i":5,"n":"第五条","txt":"电力企业是电力安全生产的责任主体，应当遵照国家有关安全生产的法律法规、制度和标准，建立健全电力安全生产责任制，加强电力安全生产管理，完善电力安全生产条件，确保电力安全生产。"},{"i":6,"n":"第六条","txt":"任何单位和个人对违反本办法和国家有关电力安全生产监督管理规定的行为，有权向国家能源局及其派出机构投诉和举报，国家能源局及其派出机构应当依法处理。"},{"i":7,"n":"第七条","txt":"电力企业的主要负责人对本单位的安全生产工作全面负责。电力企业从业人员应当依法履行安全生产方面的义务。"},{"i":8,"n":"第八条","txt":"电力企业应当履行下列电力安全生产管理基本职责： (一)依照国家安全生产法律法规、制度和标准，制定并落实本单位电力安全生产管理制度和规程; (二)建立健全电力安全生产保证体系和监督体系，落实安全生产责任; (三)按照国家有关法律法规设置安全生产管理机构、配备专职安全管理人员; (四)按照规定提取和使用电力安全生产费用，专门用于改善安全生产条件; (五)按照有关规定建立健全电力安全生产隐患排查治理制度和风险预控体系，开展隐患排查及风险辨识、评估和监控工作，并对安全隐患和风险进行治理、管控; (六)开展电力安全生产标准化建设; (七)开展电力安全生产培训宣传教育工作，负责以班组长、新工人、农民工为重点的从业人员安全培训; (八)开展电力可靠性管理工作，建立健全电力可靠性管理工作体系，准确、及时、完整报送电力可靠性信息; (九)建立电力应急管理体系，健全协调联动机制，制定各级各类应急预案并开展"},{"i":9,"n":"第九条","txt":"发电企业应当按照规定对水电站大坝进行安全注册，开展大坝安全定期检查和信息化建设工作;对燃煤发电厂贮灰场进行安全备案，开展安全巡查和定期安全评估工作。"},{"i":10,"n":"第十条","txt":"电力建设单位应当对电力建设工程施工安全和工程质量安全负全面管理责任，履行工程组织、协调和监督职责，并按照规定将电力工程项目的安全生产管理情况向当地派出机构备案，向相关电力工程质监机构进行工程项目质量监督注册申请。"},{"i":11,"n":"第十一条","txt":"供电企业应当配合地方政府对电力用户安全用电提供技术指导。"},{"i":12,"n":"第十二条","txt":"电力企业应当共同维护电力系统安全稳定运行。在电网互联、发电机组并网过程中应严格履行安全责任，并在双方的联(并)网调度协议中具体明确，不得擅自联(并)网和解网。"},{"i":13,"n":"第十三条","txt":"各级电力调度机构是涉及电力系统安全的电力安全事故(事件)处置的指挥机构，发生电力安全事故(事件)或遇有危及电力系统安全的情况时，电力调度机构有权采取必要的应急处置措施，相关电力企业应当严格执行调度指令。"},{"i":14,"n":"第十四条","txt":"电力调度机构应当加强电力系统安全稳定运行管理，科学合理安排系统运行方式，开展电力系统安全分析评估，统筹协调电网安全和并网运行机组安全。"},{"i":15,"n":"第十五条","txt":"电力企业应当加强发电设备设施和输变配电设备设施安全管理和技术管理，强化电力监控系统(或设备)专业管理，完善电力系统调频、调峰、调压、调相、事故备用等性能，满足电力系统安全稳定运行的需要。"},{"i":16,"n":"第十六条","txt":"发电机组、风电场以及光伏电站等并入电网运行，应当满足相关技术标准，符合电网运行的有关安全要求。"},{"i":17,"n":"第十七条","txt":"电力企业应当根据国家有关规定和标准，制订、完善和落实预防电网大面积停电的安全技术措施、反事故措施和应急预案，建立完善与国家能源局及其派出机构、地方人民政府及电力用户等的应急协调联动机制。"},{"i":18,"n":"第十八条","txt":"国家能源局依法负责全国电力安全生产监督管理工作。国家能源局派出机构(以下简称“派出机构”)按照属地化管理的原则，负责辖区内电力安全生产监督管理工作。 涉及跨区域的电力安全生产监督管理工作，由国家能源局负责或者协调确定具体负责的区域派出机构;同一区域内涉及跨省的电力安全生产监督管理工作，由当地区域派出机构负责或者协调确定具体负责的省级派出机构。 50兆瓦以下小水电站的安全生产监督管理工作，按照相关规定执行。50兆瓦以下小水电站的涉网安全由派出机构负责监督管理。"},{"i":19,"n":"第十九条","txt":"国家能源局及其派出机构应当采取多种形式，加强有关安全生产的法律法规、制度和标准的宣传，向电力企业传达国家有关安全生产工作各项要求，提高从业人员的安全生产意识。"},{"i":20,"n":"第二十条","txt":"国家能源局及其派出机构应当建立健全电力行业安全生产工作协调机制，及时协调、解决安全生产监督管理中存在的重大问题。"},{"i":21,"n":"第二十一条","txt":"国家能源局及其派出机构应当依法对电力企业执行有关安全生产法规、标准和规范情况进行监督检查。 国家能源局组织开展全国范围的电力安全生产大检查，制定检查工作方案，并对重点地区、重要电力企业、关键环节开展重点督查。派出机构组织开展辖区内的电力安全生产大检查，对部分电力企业进行抽查。"},{"i":22,"n":"第二十二条","txt":"国家能源局及其派出机构对现场检查中发现的安全生产违法、违规行为，应当责令电力企业当场予以纠正或者限期整改。对现场检查中发现的重大安全隐患，应当责令其立即整改;安全隐患危及人身安全时，应当责令其立即从危险区域内撤离人员。"},{"i":23,"n":"第二十三条","txt":"国家能源局及其派出机构应当监督指导电力企业隐患排查治理工作，按照有关规定对重大安全隐患挂牌督办。"},{"i":24,"n":"第二十四条","txt":"国家能源局及其派出机构应当统计分析电力安全生产信息，并定期向社会公布。根据工作需要，可以要求电力企业报送与电力安全生产相关的文件、资料、图纸、音频或视频记录和有关数据。 国家能源局及其派出机构发现电力企业在报送资料中存在弄虚作假及其他违规行为的，应当及时纠正和处理。"},{"i":25,"n":"第二十五条","txt":"国家能源局及其派出机构应当依法组织或参与电力事故调查处理。 国家能源局组织或参与重大和特别重大电力事故调查处理;督办有重大社会影响的电力安全事件。派出机构组织或参与较大和一般电力事故调查处理，对电力系统安全稳定运行或对社会造成较大影响的电力安全事件组织专项督查。"},{"i":26,"n":"第二十六条","txt":"国家能源局及其派出机构应当依法组织开展电力应急管理工作。 国家能源局负责制定电力应急体系发展规划和国家大面积停电事件专项应急预案，开展重大电力突发安全事件应急处置和分析评估工作。派出机构应当按照规定权限和程序，组织、协调、指导电力突发安全事件应急处置工作。"},{"i":27,"n":"第二十七条","txt":"国家能源局及其派出机构应当组织开展电力安全培训和宣传教育工作。"},{"i":28,"n":"第二十八条","txt":"国家能源局及其派出机构配合地方政府有关部门、相关行业管理部门，对重要电力用户安全用电、供电电源配置、自备应急电源配置和使用实施监督管理。"},{"i":29,"n":"第二十九条","txt":"国家能源局及其派出机构应当建立安全生产举报制度，公开举报电话、信箱和电子邮件地址，受理有关电力安全生产的举报;受理的举报事项经核实后，对违法行为严重的电力企业，应当向社会公告。"},{"i":30,"n":"第三十条","txt":"电力企业造成电力事故的，依照《生产安全事故报告和调查处理条例》和《电力安全事故应急处置和调查处理条例》，承担相应的法律责任。"},{"i":31,"n":"第三十一条","txt":"国家能源局及其派出机构从事电力安全生产监督管理工作的人员滥用职权、玩忽职守或者徇私舞弊的，依法给予行政处分;构成犯罪的，由司法机关依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"国家能源局及其派出机构通过现场检查发现电力企业有违反本办法规定的行为时，可以对电力企业主要负责人或安全生产分管负责人进行约谈，情节严重的，依据《安全生产法》第九十条，可以要求其停工整顿，对发电企业要求其暂停并网运行。"},{"i":33,"n":"第三十三条","txt":"电力企业有违反本办法规定的行为时，国家能源局及其派出机构可以对其违规情况向行业进行通报，对影响电力用户安全可靠供电行为的处理情况，向社会公布。"},{"i":34,"n":"第三十四条","txt":"电力企业发生电力安全事件后，存在下列情况之一的，国家能源局及其派出机构可以责令限期改正，逾期不改正的应当将其列入安全生产不良信用记录和安全生产诚信“黑名单”，并处以1万元以下的罚款： (一)迟报、漏报、谎报、瞒报电力安全事件信息的; (二)不及时组织应急处置的; (三)未按规定对电力安全事件进行调查处理的。"},{"i":35,"n":"第三十五条","txt":"电力企业未履行本办法第八条规定的，由国家能源局及其派出机构责令限期整改，逾期不整改的，对电力企业主要负责人予以警告;情节严重的，由国家能源局及其派出机构对电力企业主要负责人处以1万元以下的罚款。"},{"i":36,"n":"第三十六条","txt":"电力企业有下列情形之一的，由国家能源局及其派出机构责令限期改正;逾期不改正的，由国家能源局及其派出机构依据《电力监管条例》第三十四条，对其处以5万元以上、50万元以下的罚款，并将其列入安全生产不良信用记录和安全生产诚信“黑名单”： (一)拒绝或阻挠国家能源局及其派出机构从事监督管理工作的人员依法履行电力安全生产监督管理职责的; (二)向国家能源局及其派出机构提供虚假或隐瞒重要事实的文件、资料的。"},{"i":37,"n":"第三十七条","txt":"本办法下列用语的含义： (一)电力系统，是指由发电、输电、变电、配电以及电力调度等环节组成的电能生产、传输和分配的系统。 (二)电力事故，是指电力生产、建设过程中发生的电力安全事故、电力人身伤亡事故、发电设备或输变电设备设施损坏造成直接经济损失的事故。 (三)电力安全事件，是指未构成电力安全事故，但影响电力(热力)正常供应，或对电力系统安全稳定运行构成威胁，可能引发电力安全事故或造成较大社会影响的事件。 (四)重大安全隐患，是指可能造成一般以上人身伤亡事故、电力安全事故、直接经济损失100万元以上的电力设备事故和其他对社会造成较大影响的隐患。"},{"i":38,"n":"第三十八条","txt":"本办法自二〇一五年三月一日起施行。原国家电力监管委员会《电力安全生产监管办法》同时废止。"}],"dianlishichangyunxingjibenguize":[{"i":1,"n":"第一条","txt":"为规范电力市场行为，依法保护市场成员的合法权益，保证电力市场的统一、开放、竞争、有序，按照《中共中央 国务院关于进一步深化电力体制改革的若干意见》《中共中央 国务院关于加快建设全国统一大市场的意见》等有关精神，根据有关法律和《电力监管条例》等行政法规，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则适用于各类电力市场。"},{"i":3,"n":"第三条","txt":"国家能源局及其派出机构（以下简称电力监管机构）、国务院有关部门根据职能对电力市场实施监督管理。"},{"i":4,"n":"第四条","txt":"本规则所称的电力市场成员包括经营主体、电力市场运营机构和提供输配电服务的电网企业等。其中，经营主体包括参与电力市场交易的发电企业、售电企业、电力用户和新型经营主体（含储能企业、虚拟电厂、负荷聚合商等）；电力市场运营机构包括电力交易机构、电力调度机构。"},{"i":5,"n":"第五条","txt":"电力市场实行注册制度。电力交易机构根据国家有关规定建立市场注册制度，具体负责电力市场注册管理工作。经营主体进入或者退出电力市场应当办理相应的注册手续。"},{"i":6,"n":"第六条","txt":"电力市场运营机构按职责负责电力市场交易、电力调度和交易结果执行，以及配套的准入注册、计量结算、信息披露等，维护电力系统的安全稳定运行。"},{"i":7,"n":"第七条","txt":"电网企业应当公平开放输电网、配电网，根据交易结果为经营主体提供安全、优质、经济的输配电服务，根据结算依据向经营主体结算相关费用。严格执行国家规定的输配电价，并接受相关电力监管机构的监督检查。"},{"i":8,"n":"第八条","txt":"经营主体应当按照有关规定履行交易结果，根据交易结果使用输配电网。"},{"i":9,"n":"第九条","txt":"电力市场应当按照国家有关规定组建电力市场管理委员会，作为独立于电力交易机构的自治性议事协调机制，对电力市场成员实施自律管理。"},{"i":10,"n":"第十条","txt":"电力市场交易类型包括电能量交易、电力辅助服务交易、容量交易等。"},{"i":11,"n":"第十一条","txt":"电能量交易按照交易周期分为电力中长期交易和电力现货交易。 电力中长期交易，是指对未来某一时期内交割电力产品或服务的交易，包含数年、年、月、周、多日等不同时间维度的交易。 电力现货交易，是指通过现货交易平台在日前及更短时间内集中开展的次日、日内至实时调度之前电力交易活动的总称。"},{"i":12,"n":"第十二条","txt":"电力辅助服务交易是指由经营主体通过市场化方式提供调频、备用和调峰等有偿电力辅助服务。"},{"i":13,"n":"第十三条","txt":"容量交易的标的是在未来一定时期内，由发电机组、储能等提供的能够可靠支撑最大负荷的出力能力。根据新型电力系统建设需要，逐步推动建立市场化的容量成本回收机制，探索通过容量补偿、容量市场等方式，引导经营主体合理投资，保障电力系统长期容量充裕。"},{"i":14,"n":"第十四条","txt":"国家统筹推进全国统一电力市场体系建设，持续完善电力市场功能，发挥市场机制作用。"},{"i":15,"n":"第十五条","txt":"电能量交易由电力市场运营机构按照电力市场运行规则组织实施，也可以由电力交易双方协商。"},{"i":16,"n":"第十六条","txt":"经营主体在履行市场注册程序后，参与电能量市场交易。 经营主体之间不得实行串通报价、哄抬价格以及扰乱市场秩序等行为。经营主体进行电能量交易，不得滥用市场支配地位操纵市场价格；有多个发电厂组成的发电企业进行电能量交易，不得集中报价。"},{"i":17,"n":"第十七条","txt":"电能量交易应通过电力市场运营机构校核后执行。"},{"i":18,"n":"第十八条","txt":"经营主体应当按照有关规定提供用以维护电压、频率稳定和电网故障恢复等方面的电力辅助服务。"},{"i":19,"n":"第十九条","txt":"电力辅助服务分为基本电力辅助服务和有偿电力辅助服务。其中，基本电力辅助服务是经营主体应当无偿提供的电力辅助服务。有偿电力辅助服务是经营主体在基本电力辅助服务之外提供的其他电力辅助服务。具备条件的辅助服务采用市场竞争方式确定提供者。"},{"i":20,"n":"第二十条","txt":"各地按照国家有关规定确定参与辅助服务市场的准入条件时，应当实行公平准入，不得指定特定主体或对特定主体作出歧视性规定。"},{"i":21,"n":"第二十一条","txt":"国家能源局会同国家发展改革委负责制定电力辅助服务管理办法及基本交易规则，明确电力辅助服务的具体内容、技术标准、提供方式、考核方式。"},{"i":22,"n":"第二十二条","txt":"承诺按照要求提供电力辅助服务的经营主体，在实际运行中，电力调度机构按照有关规定进行考核。"},{"i":23,"n":"第二十三条","txt":"经营主体应当安装符合国家标准的电能计量装置，由电能计量检测机构检定后投入使用。 本规则所称电能计量检测机构，是指经政府计量行政部门认可、电能交易双方确认的电能计量检测机构。"},{"i":24,"n":"第二十四条","txt":"电能计量检测机构对电能计量装置实行定期校核。经营主体可以申请校核电能计量装置，经校核，电能计量装置误差达不到规定精度的，由此发生的费用由该电能计量装置的产权方承担；电能计量装置误差达到规定精度的，由此发生的费用由申请方承担。"},{"i":25,"n":"第二十五条","txt":"参与电能量交易的经营主体，应当明确各自电能计量点。电能计量点位于经营主体与电网企业的产权分界点，产权分界点不能安装电能计量装置的，由双方协商确定电能计量点。法定或者约定的计量点计量的电能作为电费结算的依据。经营主体以计量点为分界承担电能损耗和相关责任，国家另有规定的除外。"},{"i":26,"n":"第二十六条","txt":"电网企业应当建立并维护电能计量数据库，并按照有关规定向经营主体公布相关的电能计量数据。"},{"i":27,"n":"第二十七条","txt":"电力市场结算包括电能量交易结算、电力辅助服务交易结算、容量交易结算等。"},{"i":28,"n":"第二十八条","txt":"电网企业和电力调度机构负责向电力交易机构提供相关数据，电力交易机构负责提供电力市场交易结算依据和服务，电网企业受经营主体委托提供相关结算服务。"},{"i":29,"n":"第二十九条","txt":"电力市场成员应当按照政策要求和电力市场运行规则规定的电费结算方式和期限结算电费。"},{"i":30,"n":"第三十条","txt":"经营主体应当执行有关电网运行管理的规程、规定，服从统一调度，加强设备维护，按照并网协议配备必要的安全设施，提供电力辅助服务，维护电力系统的安全稳定运行。"},{"i":31,"n":"第三十一条","txt":"电力调度机构应当严格执行电力调度规则，合理安排系统运行方式，及时预报或者通报影响电力系统安全运行的信息，防止电网事故，保障电网运行安全。负责电力市场交易的安全校核，并公布校核方法、参数。根据电力供需形势、设备运行状况、安全约束条件和系统运行状况，统筹安排电力设备检修计划。电力并网运行管理规定及实施细则由电力监管机构制定。"},{"i":32,"n":"第三十二条","txt":"电力市场技术支持系统建设应当符合规定的性能指标要求，具备能量管理、交易管理、电能计量、结算系统、合同管理、报价处理、市场分析与预测、交易信息、监管系统等功能。"},{"i":33,"n":"第三十三条","txt":"电力市场运营机构负责管理和维护电力市场技术支持系统，保障电力市场运营所需的交易安全、数据安全和网络安全。电力市场技术支持系统建设应当符合规定的性能指标要求，以电力市场运行规则为基础，统一规划、统一设计、统一管理、同步实施、分别维护，根据电力市场发展的需要及时更新。"},{"i":34,"n":"第三十四条","txt":"国家发展改革委、国家能源局会同有关部门依职责开展市场监管，引导市场价格运行在合理区间。电力市场应建立健全电力市场风险防控机制，防范市场风险，保障电力系统安全和市场平稳运行，维护经营主体合法权益和社会公共利益。"},{"i":35,"n":"第三十五条","txt":"电力监管机构根据维护电力市场正常运作和电力系统安全的需要，制定电力市场暂停、中止、恢复等干预规则，规定电力市场干预措施实施条件和相关处理方法。"},{"i":36,"n":"第三十六条","txt":"电力市场运营机构按照“谁运营、谁防范，谁运营、谁监控”的原则，履行市场监控和风险防控责任，对市场依规开展监测，接受电力监管机构监管。市场成员应共同遵守并按规定落实电力市场风险防控职责。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人不得非法干预电力市场正常运行，不得实施地方保护、市场分割、指定交易、区域壁垒等妨碍统一市场和公平竞争的政策。"},{"i":38,"n":"第三十八条","txt":"信息披露应当遵循“安全、及时、真实、准确、完整、易于使用”的原则。信息披露主体应严格按照要求披露信息，并对其披露信息的真实性、准确性、完整性、及时性负责。"},{"i":39,"n":"第三十九条","txt":"经营主体、电网企业应当按照有关规定向电力市场运营机构提供信息。电力市场运营机构在确保信息安全基础上，定期向经营主体和社会公众按要求披露电力市场运行信息。"},{"i":40,"n":"第四十条","txt":"电力监管机构制定电力市场信息披露规则并监督实施。"},{"i":41,"n":"第四十一条","txt":"电力市场运营机构违反本规则规定，有下列情形之一的，按照《电力监管条例》第三十三条的规定处理： （一）不按照本规则及配套规则规定组织交易的； （二）未经电力监管机构审定同意，擅自出台交易细则开展相关电力市场活动的； （三）擅自执行未按法定权限、程序制修订的规则的； （四）其他违反本规则规定且造成社会不良影响的。"},{"i":42,"n":"第四十二条","txt":"任何单位和个人扰乱电力市场运营机构的秩序且影响电力市场活动正常进行，或者危害电力市场及相关技术支持系统安全的，按照有关规定处理；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"国家能源局及其派出机构会同有关部门依据本规则组织制定相关配套规则和实施细则。"},{"i":44,"n":"第四十四条","txt":"本规则由国家发展改革委、国家能源局解释。"},{"i":45,"n":"第四十五条","txt":"本规则自2024年7月1日起施行，2005年10月13日发布的《电力市场运营基本规则》（原国家电力监管委员会令第10号）同时废止。"}],"dianlijianshegongchengshigonganquanjianduguanlibanb48e60":[{"i":1,"n":"第一条","txt":"为了加强电力建设工程施工安全监督管理，保障人民群众生命和财产安全，根据《中华人民共和国安全生产法》、《中华人民共和国特种设备安全法》、《建设工程安全生产管理条例》、《电力监管条例》、《生产安全事故报告和调查处理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于电力建设工程的新建、扩建、改建、拆除等有关活动，以及国家能源局及其派出机构对电力建设工程施工安全实施监督管理。 本办法所称电力建设工程，包括火电、水电、核电(除核岛外)、风电、太阳能发电等发电建设工程，输电、配电等电网建设工程，及其他电力设施建设工程。 本办法所称电力建设工程施工安全包括电力建设、勘察设计、施工、监理单位等涉及施工安全的生产活动。"},{"i":3,"n":"第三条","txt":"电力建设工程施工安全坚持“安全第一、预防为主、综合治理”的方针，建立“企业负责、职工参与、行业自律、政府监管、社会监督”的管理机制。"},{"i":4,"n":"第四条","txt":"电力建设单位、勘察设计单位、施工单位、监理单位及其他与电力建设工程施工安全有关的单位，必须遵守安全生产法律法规和标准规范，建立健全安全生产保证体系和监督体系，建立安全生产责任制和安全生产规章制度，保证电力建设工程施工安全，依法承担安全生产责任。"},{"i":5,"n":"第五条","txt":"开展电力建设工程施工安全的科学技术研究和先进技术的推广应用，推进企业和工程建设项目实施安全生产标准化建设，推进电力建设工程安全生产科学管理，提高电力建设工程施工安全水平。"},{"i":6,"n":"第六条","txt":"建设单位对电力建设工程施工安全负全面管理责任，具体内容包括： (一)建立健全安全生产组织和管理机制，负责电力建设工程安全生产组织、协调、监督职责; (二)建立健全安全生产监督检查和隐患排查治理机制，实施施工现场全过程安全生产管理; (三)建立健全安全生产应急响应和事故处置机制，实施突发事件应急抢险和事故救援; (四)建立电力建设工程项目应急管理体系，编制应急综合预案，组织勘察设计、施工、监理等单位制定各类安全事故应急预案，落实应急组织、程序、资源及措施，定期组织演练，建立与国家有关部门、地方政府应急体系的协调联动机制，确保应急工作有效实施; (五)及时协调和解决影响安全生产重大问题。 建设工程实行工程总承包的，总承包单位应当按照合同约定，履行建设单位对工程的安全生产责任;建设单位应当监督工程总承包单位履行对工程的安全生产责任。"},{"i":7,"n":"第七条","txt":"建设单位应当按照国家有关规定实施电力建设工程招投标管理，具体包括： (一)应当将电力建设工程发包给具有相应资质等级的单位，禁止中标单位将中标项目的主体和关键性工作分包给他人完成; (二)应当在电力建设工程招标文件中对投标单位的资质、安全生产条件、安全生产费用使用、安全生产保障措施等提出明确要求; (三)应当审查投标单位主要负责人、项目负责人、专职安全生产管理人员是否满足国家规定的资格要求; (四)应当与勘察设计、施工、监理等中标单位签订安全生产协议。"},{"i":8,"n":"第八条","txt":"按照国家有关安全生产费用投入和使用管理规定，电力建设工程概算应当单独计列安全生产费用，不得在电力建设工程投标中列入竞争性报价。根据电力建设工程进展情况，及时、足额向参建单位支付安全生产费用。"},{"i":9,"n":"第九条","txt":"建设单位应当向参建单位提供满足安全生产的要求的施工现场及毗邻区域内各种地下管线、气象、水文、地质等相关资料，提供相邻建筑物和构筑物、地下工程等有关资料。"},{"i":10,"n":"第十条","txt":"建设单位应当组织参建单位落实防灾减灾责任，建立健全自然灾害预测预警和应急响应机制，对重点区域、重要部位地质灾害情况进行评估检查。 应当对施工营地选址布置方案进行风险分析和评估，合理选址。组织施工单位对易发生泥石流、山体滑坡等地质灾害工程项目的生活办公营地、生产设备设施、施工现场及周边环境开展地质灾害隐患排查，制定和落实防范措施。"},{"i":11,"n":"第十一条","txt":"建设单位应当执行定额工期，不得压缩合同约定的工期。如工期确需调整，应当对安全影响进行论证和评估。论证和评估应当提出相应的施工组织措施和安全保障措施。"},{"i":12,"n":"第十二条","txt":"建设单位应当履行工程分包管理责任，严禁施工单位转包和违法分包，将分包单位纳入工程安全管理体系，严禁以包代管。"},{"i":13,"n":"第十三条","txt":"建设单位应在电力建设工程开工报告批准之日起15日内，将保证安全施工的措施，包括电力建设工程基本情况、参建单位基本情况、安全组织及管理措施、安全投入计划、施工组织方案、应急预案等内容向建设工程所在地国家能源局派出机构备案。"},{"i":14,"n":"第十四条","txt":"勘察设计单位应当按照法律法规和工程建设强制性标准进行电力建设工程的勘察设计，提供的勘察设计文件应当真实、准确、完整，满足工程施工安全的需要。 在编制设计计划书时应当识别设计适用的工程建设强制性标准并编制条文清单。"},{"i":15,"n":"第十五条","txt":"勘察单位在勘察作业过程中，应当制定并落实安全生产技术措施，保证作业人员安全，保障勘察区域各类管线、设施和周边建筑物、构筑物安全。"},{"i":16,"n":"第十六条","txt":"电力建设工程所在区域存在自然灾害或电力建设活动可能引发地质灾害风险时，勘察设计单位应当制定相应专项安全技术措施，并向建设单位提出灾害防治方案建议。 应当监控基础开挖、洞室开挖、水下作业等重大危险作业的地质条件变化情况，及时调整设计方案和安全技术措施。"},{"i":17,"n":"第十七条","txt":"设计单位在规划阶段应当开展安全风险、地质灾害分析和评估，优化工程选线、选址方案;可行性研究阶段应当对涉及电力建设工程安全的重大问题进行分析和评价;初步设计应当提出相应施工方案和安全防护措施。"},{"i":18,"n":"第十八条","txt":"对于采用新技术、新工艺、新流程、新设备、新材料和特殊结构的电力建设工程，勘察设计单位应当在设计文件中提出保障施工作业人员安全和预防生产安全事故的措施建议;不符合现行相关安全技术规范或标准规定的，应当提请建设单位组织专题技术论证，报送相应主管部门同意。"},{"i":19,"n":"第十九条","txt":"勘察设计单位应当根据施工安全操作和防护的需要，在设计文件中注明涉及施工安全的重点部位和环节，提出防范安全生产事故的指导意见;工程开工前，应当向参建单位进行技术和安全交底，说明设计意图;施工过程中，对不能满足安全生产要求的设计，应当及时变更。"},{"i":20,"n":"第二十条","txt":"施工单位应当具备相应的资质等级，具备国家规定的安全生产条件，取得安全生产许可证，在许可的范围内从事电力建设工程施工活动。"},{"i":21,"n":"第二十一条","txt":"施工单位应当按照国家法律法规和标准规范组织施工，对其施工现场的安全生产负责。应当设立安全生产管理机构，按规定配备专(兼)职安全生产管理人员，制定安全管理制度和操作规程。"},{"i":22,"n":"第二十二条","txt":"施工单位应当按照国家有关规定计列和使用安全生产费用。应当编制安全生产费用使用计划，专款专用。"},{"i":23,"n":"第二十三条","txt":"电力建设工程实行施工总承包的，由施工总承包单位对施工现场的安全生产负总责，具体包括： (一)施工单位或施工总承包单位应当自行完成主体工程的施工，除可依法对劳务作业进行劳务分包外，不得对主体工程进行其它形式的施工分包;禁止任何形式的转包和违法分包; (二)施工单位或施工总承包单位依法将主体工程以外项目进行专业分包的，分包单位必须具有相应资质和安全生产许可证，合同中应当明确双方在安全生产方面的权利和义务。施工单位或施工总承包单位履行电力建设工程安全生产监督管理职责，承担工程安全生产连带管理责任，分包单位对其承包的施工现场安全生产负责; (三)施工单位或施工总承包单位和专业承包单位实行劳务分包的，应当分包给具有相应资质的单位，并对施工现场的安全生产承担主体责任。"},{"i":24,"n":"第二十四条","txt":"施工单位应当履行劳务分包安全管理责任，将劳务派遣人员、临时用工人员纳入其安全管理体系，落实安全措施，加强作业现场管理和控制。"},{"i":25,"n":"第二十五条","txt":"电力建设工程开工前，施工单位应当开展现场查勘，编制施工组织设计、施工方案和安全技术措施并按技术管理相关规定报建设单位、监理单位同意。 分部分项工程施工前，施工单位负责项目管理的技术人员应当向作业人员进行安全技术交底，如实告知作业场所和工作岗位可能存在的风险因素、防范措施以及现场应急处置方案，并由双方签字确认;对复杂自然条件、复杂结构、技术难度大及危险性较大的分部分项工程需编制专项施工方案并附安全验算结果，必要时召开专家会议论证确认。"},{"i":26,"n":"第二十六条","txt":"施工单位应当定期组织施工现场安全检查和隐患排查治理，严格落实施工现场安全措施，杜绝违章指挥、违章作业、违反劳动纪律行为发生。"},{"i":27,"n":"第二十七条","txt":"施工单位应当对因电力建设工程施工可能造成损害和影响的毗邻建筑物、构筑物、地下管线、架空线缆、设施及周边环境采取专项防护措施。对施工现场出入口、通道口、孔洞口、邻近带电区、易燃易爆及危险化学品存放处等危险区域和部位采取防护措施并设置明显的安全警示标志。"},{"i":28,"n":"第二十八条","txt":"施工单位应当制定用火、用电、易燃易爆材料使用等消防安全管理制度，确定消防安全责任人，按规定设置消防通道、消防水源，配备消防设施和灭火器材。"},{"i":29,"n":"第二十九条","txt":"施工单位应当按照国家有关规定采购、租赁、验收、检测、发放、使用、维护和管理施工机械、特种设备，建立施工设备安全管理制度、安全操作规程及相应的管理台帐和维保记录档案。 施工单位使用的特种设备应当是取得许可生产并经检验合格的特种设备。特种设备的登记标志、检测合格标志应当置于该特种设备的显著位置。 安装、改造、修理特种设备的单位，应当具有国家规定的相应资质，在施工前按规定履行告知手续，施工过程按照相关规定接受监督检验。"},{"i":30,"n":"第三十条","txt":"施工单位应当按照相关规定组织开展安全生产教育培训工作。企业主要负责人、项目负责人、专职安全生产管理人员、特种作业人员需经培训合格后持证上岗，新入场人员应当按规定经过三级安全教育。"},{"i":31,"n":"第三十一条","txt":"施工单位对电力建设工程进行调试、试运行前，应当按照法律法规和工程建设强制性标准，编制调试大纲、试验方案，对各项试验方案制定安全技术措施并严格实施。"},{"i":32,"n":"第三十二条","txt":"施工单位应当根据电力建设工程施工特点、范围，制定应急救援预案、现场处置方案，对施工现场易发生事故的部位、环节进行监控。实行施工总承包的，由施工总承包单位组织分包单位开展应急管理工作。"},{"i":33,"n":"第三十三条","txt":"监理单位应当按照法律法规和工程建设强制性标准实施监理，履行电力建设工程安全生产管理的监理职责。监理单位资源配置应当满足工程监理要求，依据合同约定履行电力建设工程施工安全监理职责，确保安全生产监理与工程质量控制、工期控制、投资控制的同步实施。"},{"i":34,"n":"第三十四条","txt":"监理单位应当建立健全安全监理工作制度，编制含有安全监理内容的监理规划和监理实施细则，明确监理人员安全职责以及相关工作安全监理措施和目标。"},{"i":35,"n":"第三十五条","txt":"监理单位应当组织或参加各类安全检查活动，掌握现场安全生产动态，建立安全管理台帐。重点审查、监督下列工作： (一)按照工程建设强制性标准和安全生产标准及时审查施工组织设计中的安全技术措施和专项施工方案; (二)审查和验证分包单位的资质文件和拟签订的分包合同、人员资质、安全协议; (三)审查安全管理人员、特种作业人员、特种设备操作人员资格证明文件和主要施工机械、工器具、安全用具的安全性能证明文件是否符合国家有关标准;检查现场作业人员及设备配置是否满足安全施工的要求; (四)对大中型起重机械、脚手架、跨越架、施工用电、危险品库房等重要施工设施投入使用前进行安全检查签证。土建交付安装、安装交付调试及整套启动等重大工序交接前进行安全检查签证; (五)对工程关键部位、关键工序、特殊作业和危险作业进行旁站监理;对复杂自然条件、复杂结构、技术难度大及危险性较大分部分项工程专项施工方案的实施进行现场监理"},{"i":36,"n":"第三十六条","txt":"在实施监理过程中，发现存在生产安全事故隐患的，应当要求施工单位及时整改;情节严重的，应当要求施工单位暂时或部分停止施工，并及时报告建设单位。施工单位拒不整改或者不停止施工的，监理单位应当及时向国家能源局派出机构和政府有关部门报告。"},{"i":37,"n":"第三十七条","txt":"国家能源局依法实施电力建设工程施工安全的监督管理，具体内容包括： (一)建立健全电力建设工程安全生产监管机制,制定电力建设工程施工安全行业标准; (二)建立电力建设工程施工安全生产事故和重大事故隐患约谈、诫勉制度; (三)加强层级监督指导，对事故多发地区、安全管理薄弱的企业和安全隐患突出的项目、部位实施重点监督检查。"},{"i":38,"n":"第三十八条","txt":"国家能源局派出机构按照国家能源局授权实施辖区内电力建设工程施工安全监督管理，具体内容如下： (一)部署和组织开展辖区内电力建设工程施工安全监督检查; (二)建立电力建设工程施工安全生产事故和重大事故隐患约谈、诫勉制度; (三)依法组织或参加辖区内电力建设工程施工安全事故的调查与处理，做好事故分析和上报工作。"},{"i":39,"n":"第三十九条","txt":"国家能源局及其派出机构履行电力建设工程施工安全监督管理职责时，可以采取下列监管措施： (一)要求被检查单位提供有关安全生产的文件和资料(含相关照片、录像及电子文本等)，按照国家规定如实公开有关信息; (二)进入被检查单位施工现场进行监督检查，纠正施工中违反安全生产要求的行为; (三)对检查中发现的生产安全事故隐患，责令整改;对重大生产安全事故隐患实施挂牌督办，重大生产安全事故隐患整改前或整改过程中无法保证安全的，责令其从危险区域撤出作业人员或者暂时停止施工; (四)约谈存在生产安全事故隐患整改不到位的单位，受理和查处有关安全生产违法行为的举报和投诉，披露违反本办法有关规定的行为和单位，并向社会公布; (五)法律法规规定的其它措施。"},{"i":40,"n":"第四十条","txt":"国家能源局及其派出机构应建立电力建设工程施工安全领域相关单位和人员的信用记录，并将其纳入国家统一的信用信息平台，依法公开严重违法失信信息，并对相关责任单位和人员采取一定期限内市场禁入等惩戒措施。"},{"i":41,"n":"第四十一条","txt":"生产安全事故或自然灾害发生后，有关单位应当及时启动相关应急预案，采取有效措施，最大程度减少人员伤亡、财产损失，防止事故扩大和衍生事故发生。建设、勘察设计、施工、监理等单位应当按规定报告事故信息。"},{"i":42,"n":"第四十二条","txt":"国家能源局及其派出机构有下列行为之一的，对直接负责的主管人员和其它直接责任人员依法给予处分;构成犯罪的，依法追究刑事责任： (一)迟报、漏报、瞒报、谎报事故的; (二)阻碍、干涉事故调查工作的; (三)在事故调查中营私舞弊、作伪证或者指使他人作伪证的; (四)不依法履行监管职责或者监督不力，造成严重后果的; (五)在实施监管过程中索取或者收受他人财物或者谋取其他利益; (六)其他违反国家法律法规的行为。"},{"i":43,"n":"第四十三条","txt":"建设单位未按规定提取和使用安全生产费用的，责令限期改正;逾期未改正的，责令该建设工程停止施工。"},{"i":44,"n":"第四十四条","txt":"电力建设工程参建单位有下列情形之一的，责令改正;拒不改正的，处5万元以上50万元以下的罚款;造成严重后果，构成犯罪的，依法追究刑事责任： (一)拒绝或者阻碍国家能源局及其派出机构及其从事监管工作的人员依法履行监管职责的; (二)提供虚假或者隐瞒重要事实的文件、资料; (三)未按照国家有关监管规章、规则的规定披露有关信息的。"},{"i":45,"n":"第四十五条","txt":"建设单位有下列行为之一的，责令限期改正，并处20万元以上50万元以下的罚款;造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任;造成损失的，依法承担赔偿责任： (一)对电力勘察、设计、施工、调试、监理等单位提出不符合安全生产法律、法规和强制性标准规定的要求的; (二)违规压缩合同约定工期的; (三)将工程发包给不具有相应资质等级的施工单位的。"},{"i":46,"n":"第四十六条","txt":"电力勘察设计单位有下列行为之一的，责令限期改正，并处10万元以上30万元以下的罚款;情节严重的，责令停业整顿，提请相关部门降低资质等级，直至吊销资质证书;造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任;造成损失的，依法承担赔偿责任： (一)未按照法律、法规和工程建设强制性标准进行勘察、设计的; (二)采用新技术、新工艺、新流程、新设备、新材料的电力建设工程和特殊结构的电力建设工程，设计单位未在设计中提出保障施工作业人员安全和预防生产安全事故的措施建议的。"},{"i":47,"n":"第四十七条","txt":"施工单位有下列行为之一的，责令限期改正;逾期未改正的，责令停业整顿，并处10万元以上30万元以下的罚款;情节严重的，提请相关部门降低资质等级，直至吊销资质证书;造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任;造成损失的，依法承担赔偿责任： (一)未按本办法设立安全生产管理机构、配备专(兼)职安全生产管理人员或者分部分项工程施工时无专(兼)职安全生产管理人员现场监督的; (二)主要负责人、项目负责人、专职安全生产管理人员、特种(殊)作业人员未持证上岗的; (三)使用国家明令淘汰、禁止使用的危及电力施工安全的工艺、设备、材料的; (四)未按照规定在施工起重机械和整体提升脚手架、模板等自升式架设设施验收合格后取得使用登记证书的; (五)未向作业人员提供安全防护用品、用具的; (六)未在施工现场的危险部位设置明显的安全警示标志，或者未按照国家有关规定在施工现场设置消"},{"i":48,"n":"第四十八条","txt":"挪用安全生产费用的，责令限期改正，并处挪用费用20%以上50%以下的罚款;造成重大安全事故，构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"监理单位有下列行为之一的，责令限期改正;逾期未改正的，责令停业整顿，并处10万元以上30万元以下的罚款;情节严重的，提请相关部门降低资质等级，直至吊销资质证书;造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任;造成损失的，依法承担赔偿责任： (一)未对重大安全技术措施或者专项施工方案进行审查的; (二)发现安全事故隐患未及时要求施工单位整改或者暂时停止施工的; (三)施工单位拒不整改或者不停止施工，未及时向有关主管部门报告的; (四)未依照法律、法规和工程建设强制性标准实施监理的。"},{"i":50,"n":"第五十条","txt":"违反本办法的规定，施工单位的主要负责人、项目负责人未履行安全生产管理职责的，责令限期改正;逾期未改正的，责令施工单位停业整顿;造成重大安全事故、重大伤亡事故或者其他严重后果，构成犯罪的，依照刑法有关规定追究刑事责任。 作业人员不服管理、违反规章制度和操作规程冒险作业造成重大伤亡事故或者其他严重后果，构成犯罪的，依照刑法有关规定追究刑事责任。 施工单位的主要负责人、项目负责人有前款违法行为，尚不够刑事处罚的，处2万元以上20万元以下的罚款或者按照管理权限给予撤职处分;自刑罚执行完毕或者受处分之日起，5年内不得担任任何施工单位的主要负责人、项目负责人。"},{"i":51,"n":"第五十一条","txt":"本办法规定的行政处罚，由国家能源局及其派出机构或者其他有关部门依照法定职权决定。有关法律、行政法规对电力建设工程安全生产违法行为的行政处罚决定机关另有规定的，从其规定。"},{"i":52,"n":"第五十二条","txt":"本办法自公布之日起30日后施行，原电监会发布的《电力建设安全生产监督管理办法》(电监安全﹝2007﹞38号)同时废止。"},{"i":53,"n":"第五十三条","txt":"本办法由国家发展和改革委员会负责解释。"}],"dianlijiankongxitonganquanfanghuguiding-2":[{"i":1,"n":"第一条","txt":"为了加强电力监控系统的信息安全管理，防范黑客及恶意代码等对电力监控系统的攻击及侵害，保障电力系统的安全稳定运行，根据《电力监管条例》、《中华人民共和国计算机信息系统安全保护条例》和国家有关规定，结合电力监控系统的实际情况，制定本规定。"},{"i":2,"n":"第二条","txt":"电力监控系统安全防护工作应当落实国家信息安全等级保护制度，按照国家信息安全等级保护的有关要求，坚持“安全分区、网络专用、横向隔离、纵向认证”的原则，保障电力监控系统的安全。"},{"i":3,"n":"第三条","txt":"本规定所称电力监控系统，是指用于监视和控制电力生产及供应过程的、基于计算机及网络技术的业务系统及智能设备，以及做为基础支撑的通信及数据网络等。"},{"i":4,"n":"第四条","txt":"本规定适用于发电企业、电网企业以及相关规划设计、施工建设、安装调试、研究开发等单位。"},{"i":5,"n":"第五条","txt":"国家能源局及其派出机构依法对电力监控系统安全防护工作进行监督管理。"},{"i":6,"n":"第六条","txt":"发电企业、电网企业内部基于计算机和网络技术的业务系统，应当划分为生产控制大区和管理信息大区。 生产控制大区可以分为控制区（安全区I）和非控制区（安全区Ⅱ）;管理信息大区内部在不影响生产控制大区安全的前提下，可以根据各企业不同安全要求划分安全区。 根据应用系统实际情况，在满足总体安全要求的前提下，可以简化安全区的设置，但是应当避免形成不同安全区的纵向交叉联接。"},{"i":7,"n":"第七条","txt":"电力调度数据网应当在专用通道上使用独立的网络设备组网，在物理层面上实现与电力企业其它数据网及外部公用数据网的安全隔离。 电力调度数据网划分为逻辑隔离的实时子网和非实时子网，分别连接控制区和非控制区。"},{"i":8,"n":"第八条","txt":"生产控制大区的业务系统在与其终端的纵向联接中使用无线通信网、电力企业其它数据网（非电力调度数据网）或者外部公用数据网的虚拟专用网络方式（VPN）等进行通信的，应当设立安全接入区。"},{"i":9,"n":"第九条","txt":"在生产控制大区与管理信息大区之间必须设置经国家指定部门检测认证的电力专用横向单向安全隔离装置。 生产控制大区内部的安全区之间应当采用具有访问控制功能的设备、防火墙或者相当功能的设施，实现逻辑隔离。 安全接入区与生产控制大区中其他部分的联接处必须设置经国家指定部门检测认证的电力专用横向单向安全隔离装置。"},{"i":10,"n":"第十条","txt":"在生产控制大区与广域网的纵向联接处应当设置经过国家指定部门检测认证的电力专用纵向加密认证装置或者加密认证网关及相应设施。"},{"i":11,"n":"第十一条","txt":"安全区边界应当采取必要的安全防护措施，禁止任何穿越生产控制大区和管理信息大区之间边界的通用网络服务。 生产控制大区中的业务系统应当具有高安全性和高可靠性，禁止采用安全风险高的通用网络服务功能。"},{"i":12,"n":"第十二条","txt":"依照电力调度管理体制建立基于公钥技术的分布式电力调度数字证书及安全标签，生产控制大区中的重要业务系统应当采用认证加密机制。"},{"i":13,"n":"第十三条","txt":"电力监控系统在设备选型及配置时，应当禁止选用经国家相关管理部门检测认定并经国家能源局通报存在漏洞和风险的系统及设备;对于已经投入运行的系统及设备，应当按照国家能源局及其派出机构的要求及时进行整改，同时应当加强相关系统及设备的运行管理和安全防护。生产控制大区中除安全接入区外，应当禁止选用具有无线通信功能的设备。"},{"i":14,"n":"第十四条","txt":"电力监控系统安全防护是电力安全生产管理体系的有机组成部分。电力企业应当按照“谁主管谁负责，谁运营谁负责”的原则，建立健全电力监控系统安全防护管理制度，将电力监控系统安全防护工作及其信息报送纳入日常安全生产管理体系，落实分级负责的责任制。 电力调度机构负责直接调度范围内的下一级电力调度机构、变电站、发电厂涉网部分的电力监控系统安全防护的技术监督，发电厂内其它监控系统的安全防护可以由其上级主管单位实施技术监督。"},{"i":15,"n":"第十五条","txt":"电力调度机构、发电厂、变电站等运行单位的电力监控系统安全防护实施方案必须经本企业的上级专业管理部门和信息安全管理部门以及相应电力调度机构的审核，方案实施完成后应当由上述机构验收。 接入电力调度数据网络的设备和应用系统，其接入技术方案和安全防护措施必须经直接负责的电力调度机构同意。"},{"i":16,"n":"第十六条","txt":"建立健全电力监控系统安全防护评估制度，采取以自评估为主、检查评估为辅的方式，将电力监控系统安全防护评估纳入电力系统安全评价体系。"},{"i":17,"n":"第十七条","txt":"建立健全电力监控系统安全的联合防护和应急机制，制定应急预案。电力调度机构负责统一指挥调度范围内的电力监控系统安全应急处理。 当遭受网络攻击，生产控制大区的电力监控系统出现异常或者故障时，应当立即向其上级电力调度机构以及当地国家能源局派出机构报告，并联合采取紧急防护措施，防止事态扩大，同时应当注意保护现场，以便进行调查取证。"},{"i":18,"n":"第十八条","txt":"电力监控系统相关设备及系统的开发单位、供应商应当以合同条款或者保密协议的方式保证其所提供的设备及系统符合本规定的要求，并在设备及系统的全生命周期内对其负责。 电力监控系统专用安全产品的开发单位、使用单位及供应商，应当按国家有关要求做好保密工作，禁止关键技术和设备的扩散。"},{"i":19,"n":"第十九条","txt":"对生产控制大区安全评估的所有评估资料和评估结果，应当按国家有关要求做好保密工作。"},{"i":20,"n":"第二十条","txt":"国家能源局及其派出机构负责制定电力监控系统安全防护相关管理和技术规范，并监督实施。"},{"i":21,"n":"第二十一条","txt":"对于不符合本规定要求的，相关单位应当在规定的期限内整改;逾期未整改的，由国家能源局及其派出机构依据国家有关规定予以处罚。"},{"i":22,"n":"第二十二条","txt":"对于因违反本规定，造成电力监控系统故障的，由其上级单位按相关规程规定进行处理;发生电力设备事故或者造成电力安全事故（事件）的，按国家有关事故（事件）调查规定进行处理。"},{"i":23,"n":"第二十三条","txt":"本规定下列用语的含义或范围： （一）电力监控系统具体包括电力数据采集与监控系统、能量管理系统、变电站自动化系统、换流站计算机监控系统、发电厂计算机监控系统、配电自动化系统、微机继电保护和安全自动装置、广域相量测量系统、负荷控制系统、水调自动化系统和水电梯级调度自动化系统、电能量计量系统、实时电力市场的辅助控制系统、电力调度数据网络等。 （二）电力调度数据网络，是指各级电力调度专用广域数据网络、电力生产专用拨号网络等。 （三）控制区，是指由具有实时监控功能、纵向联接使用电力调度数据网的实时子网或者专用通道的各业务系统构成的安全区域。 （四）非控制区，是指在生产控制范围内由在线运行但不直接参与控制、是电力生产过程的必要环节、纵向联接使用电力调度数据网的非实时子网的各业务系统构成的安全区域。"},{"i":24,"n":"第二十四条","txt":"本规定自2014年9月1日起施行。2004年12月20日原国家电力监管委员会发布的《电力二次系统安全防护规定》（国家电力监管委员会令第5号）同时废止。"}],"dianlijiankongxitonganquanfanghuguiding":[{"i":1,"n":"第一条","txt":"为了强化电力监控系统安全防护，保障电力系统安全稳定运行，根据《中华人民共和国网络安全法》《电力监管条例》《关键信息基础设施安全保护条例》等法律法规和国家有关规定，结合电力监控系统的实际情况，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国境内的电力监控系统运营者以及与其相关的规划设计、研究开发、产品制造、施工建设、安装调试等单位。"},{"i":3,"n":"第三条","txt":"电力监控系统安全防护应当落实国家网络安全等级保护和关键信息基础设施安全保护等制度，坚持“安全分区、网络专用、横向隔离、纵向认证”结构安全原则，强化安全免疫、态势感知、动态评估和备用应急措施，构建持续发展完善的防护体系。"},{"i":4,"n":"第四条","txt":"电力监控系统应当实施分区防护，防护区域按照安全等级从高到低划分为生产控制区（可以分为安全Ⅰ区和安全Ⅱ区）和管理信息区（可以分为安全Ⅲ区和安全Ⅳ区）。不同电力监控系统的生产控制区、管理信息区可以分别独立设置。"},{"i":5,"n":"第五条","txt":"电力监控系统各业务模块应当根据功能和安全等级要求部署。对电力一次系统（设备）进行实时监控的业务模块应当按照安全Ⅰ区防护要求部署；与安全Ⅰ区的业务模块交互紧密，对电力生产和供应影响较大但不直接实施控制的业务模块应当按照不低于安全Ⅱ区防护要求部署；与电力生产和供应相关，实现运行指挥、分析决策的业务模块应当按照不低于安全Ⅲ区防护要求部署；其他业务模块应当按照不低于安全Ⅳ区防护要求部署。 基于计算机及网络技术的业务系统及设备的分区，不得降低电力监控系统安全防护强度。"},{"i":6,"n":"第六条","txt":"部署在生产控制区的业务模块与终端联接使用非电力监控专用网络（如公用有线通信网络、无线通信网络、运营者其他数据网等）通信或终端不具备物理访问控制条件的，应当设立安全接入区。"},{"i":7,"n":"第七条","txt":"根据实际情况，在满足总体安全要求的前提下，可以简化安全区的设置，低安全等级业务模块可以就高放置于高安全等级区域，但是应当避免形成不同安全区的纵向交叉联接。"},{"i":8,"n":"第八条","txt":"生产控制区应当使用电力监控专用网络。电力监控专用网络应当在专用通道上使用独立的网络设备组网，在物理层面上实现与运营者其他数据网及外部公用数据网的安全隔离。 电力监控专用网络划分为逻辑隔离的实时子网和非实时子网，分别连接安全Ⅰ区和安全Ⅱ区。"},{"i":9,"n":"第九条","txt":"生产控制区与管理信息区、安全接入区之间的联接处应当设置电力专用横向单向安全隔离装置。"},{"i":10,"n":"第十条","txt":"安全Ⅰ区与安全Ⅱ区之间、安全Ⅲ区与安全Ⅳ区之间、安全接入区与终端之间应当设置具有访问控制功能的设备、防火墙或者相当功能的逻辑隔离设施。"},{"i":11,"n":"第十一条","txt":"生产控制区与电力监控专用网络的广域网之间的联接处应当设置电力专用纵向加密认证装置或者加密认证网关。"},{"i":12,"n":"第十二条","txt":"电力调度机构应当依照电力调度管理体制建立基于数字证书等技术的分布式电力调度认证机制。生产控制区处理重要业务过程中应当采用应用层端到端加密认证机制，其中与电力调度机构交互业务数据应当纳入电力调度认证机制，保障数据传输的完整性和真实性。"},{"i":13,"n":"第十三条","txt":"生产控制区应当具有高安全性和高可靠性，禁止采用安全风险高的通用网络服务功能，禁止选用具有无线通信功能的产品，应当对外设接入行为进行管控。 生产控制区重要业务应当优先采用可信验证措施实现安全免疫。"},{"i":14,"n":"第十四条","txt":"安全接入区应当设置负责转发采集与控制报文的通信代理模块，通信代理模块与终端之间的通信应当采用加密认证措施。业务模块经安全接入区与终端之间传输控制指令等重要的数据时，应当与终端进行端到端的身份认证。 安全接入区内应当简化功能配置，禁止存储重要的数据，并使用可信验证措施加强通信代理模块保护。"},{"i":15,"n":"第十五条","txt":"电力监控系统各分区边界应当采取必要的安全防护措施，禁止任何穿越生产控制区与管理信息区、安全接入区之间边界的通用网络服务。"},{"i":16,"n":"第十六条","txt":"电力监控系统优先选用安全可信的产品和服务。不得选用存在已知安全缺陷、漏洞等风险但未采取有效补救措施的产品和服务。 电力监控系统投运前应当进行安全加固，对于已经投入运行且存在漏洞或风险的系统及设备，应当按照国家能源局及其派出机构的要求及时进行整改，同时应当加强相关系统及设备的运行管理和安全防护。"},{"i":17,"n":"第十七条","txt":"运营者应当建立网络安全监测预警机制，建设基于内置探针等的网络安全监测手段，实时监视分析电力监控系统网络安全运行状态及可疑行为告警。与调度数据网相连的电力监控系统，其网络安全运行状态及可疑行为告警信息应当同步传送至相应电力调度机构。监视过程中应当尽量避免对原始安全数据的重复采集。"},{"i":18,"n":"第十八条","txt":"电力监控系统安全防护是电力安全生产管理体系的有机组成部分。运营者是电力监控系统安全防护的责任主体，其主要负责人对电力监控系统安全防护负总责。运营者应当按照“谁主管谁负责，谁运营谁负责”的原则，建立健全电力监控系统安全防护管理制度，将电力监控系统安全防护工作及其信息报送纳入日常安全生产管理体系，落实分级负责的责任制。"},{"i":19,"n":"第十九条","txt":"运营者在电力监控系统规划设计、建设运营过程中，应当保证网络安全技术措施同步规划、同步建设、同步使用。"},{"i":20,"n":"第二十条","txt":"运营者在电力监控系统规划设计阶段，应当制定电力监控系统安全防护方案并通过本单位电力监控系统网络安全管理部门以及相应电力调度机构审核，系统投运前应当完成方案实施并通过本单位电力监控系统网络安全管理部门验收。 接入调度数据网的系统及设备，其接入技术方案和安全防护措施必须经相应电力调度机构审核同意。 需要设立安全接入区的电力监控系统，应当在安全防护方案中对接入对象规模进行评估，避免单个安全接入区接入规模过大，可以按业务、地域分别设立安全接入区。"},{"i":21,"n":"第二十一条","txt":"健全电力监控系统安全防护评估制度，采取以自评估为主、检查评估为辅的方式，将电力监控系统安全防护评估纳入电力系统安全评价体系。 省级及以上电力调度机构应当定期将调管范围内电力监控系统安全防护评估和整改情况报国家能源局及其派出机构。"},{"i":22,"n":"第二十二条","txt":"运营者应当以合同条款的方式要求电力监控系统供应商保证：提供的产品和服务未设置恶意程序、不存在已知安全缺陷和漏洞，并在产品和服务的全生命周期内负责；当产品和服务存在安全缺陷、漏洞等风险时，立即采取补救措施，并及时告知运营者；当存在重大漏洞隐患时，及时向国家能源局及其派出机构报告。"},{"i":23,"n":"第二十三条","txt":"电力监控系统专用安全产品应当采用统一的技术路线。 国家电力调度控制中心牵头，中国南方电网电力调度控制中心和主要电力企业等参与，组建电力监控系统专用安全产品管理委员会，负责电力监控系统专用安全产品管理，统筹解决重大问题，保障电力监控系统专用安全产品安全可控。"},{"i":24,"n":"第二十四条","txt":"管理委员会严格落实有关政策法规要求，制定工作章程，动态维护电力监控系统专用安全产品目录及技术规范，组织并推动安全认证和安全检测，督促运营者及相关单位落实供应链安全管控措施，组织开展电力监控系统专用安全产品风险评估，对存在安全风险的电力监控系统专用安全产品进行通报。"},{"i":25,"n":"第二十五条","txt":"管理委员会建立议事机制，国家能源局和政府有关部门可以派员参加管理委员会有关会议。管理委员会应当于每年11月1日前向国家能源局报告工作开展情况，包括但不限于：工作章程制修订情况，电力监控系统专用安全产品目录及技术规范制修订情况，安全认证和安全检测工作开展情况，运营者专用安全产品管理情况，风险评估及通报情况等。管理委员会运作出现重大问题时应当提请国家能源局组织协调解决。"},{"i":26,"n":"第二十六条","txt":"运营者应当选用经管理委员会组织检测认证合格的电力监控系统专用安全产品，不得选用经管理委员会通报存在供应链安全风险的产品。运营者对专用安全产品的采购、运行、退役等全过程安全管理负责。"},{"i":27,"n":"第二十七条","txt":"电力监控系统安全防护方案、安全测试评估报告和漏洞隐患细节等有关资料应当按国家有关要求做好保密工作。管理委员会和运营者等应当按国家有关要求做好保密工作，禁止关键技术和产品的扩散。"},{"i":28,"n":"第二十八条","txt":"重要电力监控系统应当建立系统备用和恢复机制，对重要设备冗余配置，对重要的数据定期备份，并定期进行恢复性测试，支撑系统故障的快速处理和恢复，保障电力监控系统业务连续性。"},{"i":29,"n":"第二十九条","txt":"健全电力监控系统安全的联合防护和应急机制，制定应急预案并定期开展演练。电力调度机构负责统一指挥调度范围内的电力监控系统安全应急处置，定期组织联合演练。 当遭受网络攻击，电力监控系统出现异常或者故障时，运营者应当立即启动应急预案，向相应电力调度机构以及当地国家能源局派出机构报告，并联合采取紧急防护措施，防止事态扩大，同时注意保护现场，以便进行调查和溯源取证。"},{"i":30,"n":"第三十条","txt":"国家能源局负责制定电力监控系统安全防护相关管理和技术规范，国家能源局及其派出机构依法对电力监控系统安全防护工作进行监督管理，电力调度机构负责技术支持。 运营者应当建立本单位电力监控系统安全防护技术监督体系，全方位开展技术监督工作。电力调度机构对直接调度范围内的下一级电力调度机构、变电站（换流站）、发电厂（站）等涉网部分的电力监控系统安全防护进行技术监督。电力监控系统网络安全技术监督管理办法由国家能源局制定。"},{"i":31,"n":"第三十一条","txt":"运营者有下列情形之一的，由国家能源局及其派出机构责令改正，给予警告；拒不改正或者导致危害网络安全等后果的，处一万元以上十万元以下罚款，对直接负责的主管人员处五千元以上五万元以下罚款，涉及关键信息基础设施的，处十万元以上一百万元以下罚款，对直接负责的主管人员处一万元以上十万元以下罚款： （一）未采取安全分区、边界防护等防范计算机病毒和网络攻击、网络侵入等危害网络安全行为的技术措施； （二）未采取网络安全监测预警等技术措施监测、记录网络运行状态、网络安全事件。 在发生危害网络安全的事件时，未按规定及时报告的，由国家能源局及其派出机构责令改正，给予警告；拒不改正或者导致危害网络安全等后果的，处一万元以上十万元以下罚款，对直接负责的主管人员处五千元以上五万元以下罚款，涉及关键信息基础设施的重大事件，处十万元以上一百万元以下罚款，对直接负责的主管人员处一万元以上十万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"运营者拒绝、阻碍国家能源局及其派出机构依法实施的监督检查或依照本规定委托电力调度机构组织开展的技术监督的，由国家能源局及其派出机构责令改正；拒不改正或情节严重的，处五万元以上五十万元以下罚款，对直接负责的主管人员和其他直接责任人员，处一万元以上十万元以下罚款。"},{"i":33,"n":"第三十三条","txt":"电力调度机构在技术监督过程中发现被监督电力监控系统存在可能导致网络安全事件的重大安全风险时，可以采取断开其数据网络连接、断开其电力一次设备连接等措施管控安全风险。"},{"i":34,"n":"第三十四条","txt":"对于其他不符合本规定要求的，由国家能源局及其派出机构责令改正；拒不改正或者导致危害网络安全等后果的，由国家能源局及其派出机构依法依规予以处罚。"},{"i":35,"n":"第三十五条","txt":"对于因违反本规定，造成电力监控系统故障的，由其运营者按相关规程规定进行处理；导致电力设备事故或者造成电力安全事故（事件）的，按国家有关事故（事件）调查规定进行处理。"},{"i":36,"n":"第三十六条","txt":"本规定下列用语的含义或范围： （一）电力监控系统，是指用于监视和控制电力生产及供应过程的、基于计算机及网络技术的业务系统及设备，以及作为基础支撑的通信设施及数据网络等，包括但不限于实现继电保护和安全自动控制、调度监控、变电站（换流站）监控、发电厂监控、新能源发电监控、分布式电源监控、储能电站监控、虚拟电厂监控、配电自动化、变电站集控、发电集中监视、发电机励磁和调速、电力现货市场交易、直流控制保护、负荷监控、计费控制等功能的系统，以及支撑以上功能的通信设施、数据网络及配套网管系统。 （二）电力监控专用网络，是指承载电力监视和控制业务的专用广域数据网络、专用局域网络以及专用通信线路等，如调度数据网（各级电力调度专用广域数据网络）、发电企业集中监视中心与电厂之间的专用数据网络、调度自动化和厂站自动化的专用局域网、继电保护和安全自动装置使用的专用通信通道等。 （三）物理访问控制，是指电力监控系"},{"i":37,"n":"第三十七条","txt":"本规定自2025年1月1日起施行。2014年8月1日国家发展改革委公布的《电力监控系统安全防护规定》（国家发展改革委2014年第14号令）同时废止。"}],"dianlisheshibaohutiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《电力设施保护条例》(以下简称《条例》)第三十一条规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"本细则适用于中华人民共和国境内国有、集体、外资、合资、个人已建或在建的电力设施。"},{"i":3,"n":"第三条","txt":"电力管理部门、公安部门、电力企业和人民群众都有保护电力设施的义务。各级地方人民政府设立的由同级人民政府所属有关部门和电力企业(包括：电网经营企业、供电企业、发电企业)负责人组成的电力设施保护领导小组，负责领导所辖行政区域内电力设施的保护工作，其办事机构设在相应的电网经营企业，负责电力设施保护的日常工作。 电力设施保护领导小组，应当在有关电力线路沿线组织群众护线，群众护线组织成员由相应的电力设施保护领导小组发给护线证件。 各省(自治区、直辖市)电力管理部门可制定办法，规定群众护线组织形式、权利、义务、责任等。"},{"i":4,"n":"第四条","txt":"电力企业必须加强对电力设施的保护工作。对危害电力设施安全的行为，电力企业有权制止并可以劝其改正、责其恢复原状、强行排除妨害，责令赔偿损失、请求有关行政主管部门和司法机关处理，以及采取法律、法规或政府授权的其他必要手段。"},{"i":5,"n":"第五条","txt":"架空电力线路保护区，是为了保证已建架空电力线路的安全运行和保障人民生活的正常供电而必须设置的安全区域。在厂矿、城镇、集镇、村庄等人口密集地区，架空电力线路保护区为导线边线在最大计算风偏后的水平距离和风偏后距建筑物的水平安全距离之和所形成的两平行线内的区域。各级电压导线边线在计算导线最大风偏情况下，距建筑物的水平安全距离如下："},{"i":6,"n":"第六条","txt":"江河电缆保护区的宽度为： (一)敷设于二级及以上航道时，为线路两侧各100米所形成的两平行线内的水域; (二)敷设于三级及以下航道时，为线路两侧各50米所形成的两平行线内的水域。"},{"i":7,"n":"第七条","txt":"地下电力电缆保护区的宽度为地下电力电缆线路地面标桩两侧各0.75米所形成两平行线内区域。 发电设施附属的输油、输灰、输水管线的保护区依本条规定确定。 在保护区内禁止使用机械掘土、种植林木;禁止挖坑、取土、兴建建筑物和构筑物;不得堆放杂物或倾倒酸、碱、盐及其他有害化学物品。"},{"i":8,"n":"第八条","txt":"禁止在电力电缆沟内同时埋设其他管道。未经电力企业同意，不准在地下电力电缆沟内埋设输油、输气等易燃易爆管道。管道交叉通过时，有关单位应当协商，并采取安全措施，达成协议后方可施工。"},{"i":9,"n":"第九条","txt":"电力管理部门应在下列地点设置安全标志： (一)架空电力线路穿越的人口密集地段; (二)架空电力线路穿越的人员活动频繁的地区; (三)车辆、机械频繁穿越架空电力线路的地段; (四)电力线路上的变压器平台。"},{"i":10,"n":"第十条","txt":"任何单位和个人不得在距电力设施周围五百米范围内(指水平距离)进行爆破作业。因工作需要必须进行爆破作业时，应当按国家颁发的有关爆破作业的法律法规，采取可靠的安全防范措施，确保电力设施安全，并征得当地电力设施产权单位或管理部门的书面同意，报经政府有关管理部门批准。 在规定范围外进行的爆破作业必须确保电力设施的安全。"},{"i":11,"n":"第十一条","txt":"任何单位或个人不得冲击、扰乱发电、供电企业的生产和工作秩序，不得移动、损害生产场所的生产设施及标志物。"},{"i":12,"n":"第十二条","txt":"任何单位或个人不得在距架空电力线路杆塔、拉线基础外缘的下列范围内进行取土、打桩、钻探、开挖或倾倒酸、碱、盐及其他有害化学物品的活动： (一)35千伏及以下电力线路杆塔、拉线周围5米的区域; (二)66千伏及以上电力线路杆塔、拉线周围10米的区域。 在杆塔、拉线基础的上述距离范围外进行取土、堆物、打桩、钻探、开挖活动时，必须遵守下列要求： (一)预留出通往杆塔、拉线基础供巡视和检修人员、车辆通行的道路; (二)不得影响基础的稳定，如可能引起基础周围土壤、砂石滑坡，进行上述活动的单位或个人应当负责修筑护坡加固; (三)不得损坏电力设施接地装置或改变其埋设深度。"},{"i":13,"n":"第十三条","txt":"在架空电力线路保护区内，任何单位或个人不得种植可能危及电力设施和供电安全的树木、竹子等高杆植物。"},{"i":14,"n":"第十四条","txt":"超过4米高度的车辆或机械通过架空电力线路时，必须采取安全措施，并经县级以上的电力管理部门批准。"},{"i":15,"n":"第十五条","txt":"架空电力线路一般不得跨越房屋。对架空电力线路通道内的原有房屋，架空电力线路建设单位应当与房屋产权所有者协商搬迁，拆迁费不得超出国家规定标准;特殊情况需要跨越房屋时，设计建设单位应当采取增加杆塔高度、缩短档距等安全措施，以保证被跨越房屋的安全。被跨越房屋不得再行增加高度。超越房屋的物体高度或房屋周边延伸出的物体长度必须符合安全距离的要求。"},{"i":16,"n":"第十六条","txt":"架空电力线路建设项目和公用工程、城市绿化及其他工程之间发生妨碍时，按下述原则处理： (一)新建架空电力线路建设工程、项目需穿过林区时，应当按国家有关电力设计的规程砍伐出通道，通道内不得再种植树木;对需砍伐的树木由架空电力线路建设单位按国家的规定办理手续和付给树木所有者一次性补偿费用，并与其签定不再在通道内种植树木的协议。 (二)架空电力线路建设项目、计划已经当地城市建设规划主管部门批准的，园林部门对影响架空电力线路安全运行的树木，应当负责修剪，并保持今后树木自然生长最终高度和架空电力线路导线之间的距离符合安全距离的要求。 (三)根据城市绿化规划的要求，必须在已建架空电力线路保护区内种植树木时，园林部门需与电力管理部门协商，征得同意后，可种植低矮树种，并由园林部门负责修剪以保持树木自然生长最终高度和架空电力线路导线之间的距离符合安全距离的要求。 (四)架空电力线路导线在最大弧垂或最大风偏"},{"i":17,"n":"第十七条","txt":"城乡建设规划主管部门审批或规划已建电力设施(或已经批准新建、改建、扩建、规划的电力设施)两侧的新建建筑物时，应当会同当地电力管理部门审查后批准。"},{"i":18,"n":"第十八条","txt":"在依法划定的电力设施保护区内，任何单位和个人不得种植危及电力设施安全的树木、竹子或高杆植物。 电力企业对已划定的电力设施保护区域内新种植或自然生长的可能危及电力设施安全的树木、竹子，应当予以砍伐，并不予支付林木补偿费、林地补偿费、植被恢复费等任何费用。"},{"i":19,"n":"第十九条","txt":"电力管理部门对检举、揭发破坏电力设施或哄抢、盗窃电力设施器材的行为符合事实的单位或个人，给予2000元以下的奖励;对同破坏电力设施或哄抢、盗窃电力设施器材的行为进行斗争并防止事故发生的单位或个人，给予2000元以上的奖励;对为保护电力设施与自然灾害作斗争，成绩突出或为维护电力设施安全做出显著成绩的单位或个人，根据贡献大小，给予相应物质奖励。 对维护、保护电力设施作出重大贡献的单位或个人，除按以上规定给予物质奖励外，还可由电力管理部门、公安部门或当地人民政府根据各自的权限给予表彰或荣誉奖励。"},{"i":20,"n":"第二十条","txt":"下列危害电力设施的行为，情节显著轻微的，由电力管理部门责令改正;拒不改正的，处1000元以上10000元以下罚款： (一)损坏使用中的杆塔基础的; (二)损坏、拆卸、盗窃使用中或备用塔材、导线等电力设施的; (三)拆卸、盗窃使用中或备用变压器等电力设备的。破坏电力设备、危害公共安全构成犯罪的，依法追究其刑事责任。"},{"i":21,"n":"第二十一条","txt":"下列违反《电力设施保护条例》和本细则的行为，尚不构成犯罪的，由公安机关依据《中华人民共和国治安管理处罚法》予以处理： (一)盗窃、哄抢库存或者已废弃停止使用的电力设施器材的; (二)盗窃、哄抢尚未安装完毕或尚未交付使用单位验收的电力设施的; (三)其他违反治安管理的行为。"},{"i":22,"n":"第二十二条","txt":"电力管理部门为保护电力设施安全，对违法行为予以行政处罚，应当依照法定程序进行。"},{"i":23,"n":"第二十三条","txt":"本实施细则自发布之日起施行，原能源部、公安部1992年12月2日发布的《电力设施保护条例实施细则》同时废止。"}],"dianlizhongdashiguyinhuanpandingbiaozhunjizhilijiac65903":[{"i":1,"n":"第一条","txt":"为加强电力重大事故隐患（以下简称重大隐患）判定及排查治理工作，有效防范遏制电力事故，根据《中华人民共和国安全生产法》《电力监管条例》以及有关法律法规规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称重大隐患是指电力企业因安全风险管控措施缺失、失效或者弱化，可能造成大面积停电、重大人员伤亡、重大经济损失等严重后果的人的不安全行为、物的不安全状态、作业场所或者作业环境的其他不安全因素和安全管理上的缺陷。"},{"i":3,"n":"第三条","txt":"本规定适用于电力领域重大隐患的判定、排查治理及监督管理。危险化学品、消防（火灾）、特种设备等有关行业领域对重大事故隐患判定标准另有规定的，适用其规定。"},{"i":4,"n":"第四条","txt":"电力企业承担重大隐患排查治理主体责任，按照本规定开展重大隐患排查治理工作。国家能源局及其派出机构、地方电力管理部门负重大隐患治理监督管理责任，按照本规定对电力企业重大隐患排查治理工作开展监督管理。"},{"i":5,"n":"第五条","txt":"电网或电力设备设施出现的下列任一项情形判定为一项重大隐患： （一）直流输电控制保护系统、330千伏以上电网安全稳定控制系统的策略表或定值单未根据电网变化进行必要的整定、调整，或现场执行与电网调度机构正式下发的策略表或定值单不一致； （二）直流输电控制保护装置、330千伏以上电网安全稳定控制装置未采用双重化以上配置；220千伏以上电厂涉网保护装置及其二次回路、直流电源、通信通道、路由等不满足冗余配置要求； （三）单机容量100兆瓦以上火电、核电机组，40兆瓦以上水电机组的励磁系统未按要求配置电力系统稳定器功能，或同步发电机机组并网运行时电力系统稳定器未按照规程规定要求投入运行； （四）并入500千伏以上电压等级电网的单机容量200兆瓦以上发电机组未按要求开展进相试验； （五）并入220千伏以上电压等级电网的风电场、光伏电站、电化学储能电站不具备国家标准规定的低电压穿越能力、高电压穿越能力"},{"i":6,"n":"第六条","txt":"单套容量200兆瓦以上的燃气—蒸汽联合循环发电机组、单机容量300兆瓦以上的燃煤发电机组、光热发电机组、核电（常规岛部分）出现的下列任一项情形判定为一项重大隐患： （一）拟启动的汽轮机调节部套（含主、调节汽阀）卡涩，或进入同一汽缸串联布置的主、调节汽阀严密性均不合格，或超速保护试验未按规定执行或结果不合格； （二）未制定处置汽轮机组转速飞升的应急措施，或制定了应急措施未定期开展应急演练； （三）临近控制室、主要通道、日常作业场所的高温高压汽水系统在调试、运行中泄漏时进行带压堵漏或未采取有效隔离或未采取停运措施； （四）发电机组轴系支撑和旋转部件金属材质不合格或未按规定开展金属检验； （五）燃煤锅炉烟风道、除尘器、脱硫吸收塔、脱硝催化剂装置、渣仓、粉仓料斗（含灰斗）、输煤栈桥等重点设备设施的钢结构、支吊架、承重焊接部位总体强度不满足结构强度要求。"},{"i":7,"n":"第七条","txt":"水电站出现的下列任一项情形判定为一项重大隐患： （一）厂房未进行防洪设计或防洪设计不满足规范要求； （二）主厂房最底层廊道未设置防水淹厂房报警系统； （三）中控室不能通过硬布线回路或其他可靠方式直接控制机组停机、关闭事故闸门和压力钢管主阀门； （四）厂房渗漏、检修排水系统不能正常工作； （五）工程边坡稳定性不满足规范规定，经评估可能导致崩塌滑坡等严重后果；输水发电建筑物及其他工程建筑物、金属结构设备、机电设备等存在严重质量缺陷或带病运行，经评估可能导致结构破坏、设备损毁等严重后果的情形。"},{"i":8,"n":"第八条","txt":"水电站大坝出现的下列任一项情形判定为一项重大隐患： （一）水电站大坝未按规定办理安全注册登记； （二）水库未经蓄水验收即投入使用或擅自抬高汛限水位和正常蓄水位； （三）大坝存在防洪能力不满足相应设防标准，大坝整体稳定性，坝体贯穿性裂缝，坝体、坝基、坝肩渗漏或者渗透稳定性不满足相应设计规范，泄洪消能建筑物损坏或淤堵，泄水闸门、启闭机无法安全运行，枢纽区地质灾害等问题，经过分析论证，需要尽最大可能降低水库水位的情形； （四）泄洪工作闸门操作电源不能正常工作且无可靠应急电源。"},{"i":9,"n":"第九条","txt":"燃煤发电厂贮灰场大坝出现的下列任一项情形判定为一项重大隐患： （一）贮灰场未按规定开展安全评估； （二）贮灰场安全等级评定为险情贮灰场； （三）贮灰场坝体有裂缝、滑坡征兆等严重异常情况且未采取处理措施； （四）在贮灰场安全管理范围内进行爆破、打井、采石、采矿、取土等危及贮灰场安全的作业。"},{"i":10,"n":"第十条","txt":"电力建设工程、电力检修（含技术改造）项目出现的下列任一项情形判定为一项重大隐患： （一）未经论证的情况下压缩合同约定工期，或论证后应采取的措施未落实； （二）电力建设工程、检修项目发包给不具备安全生产条件或相应资质的企业或个人； （三）无资质或超资质、超经营范围承揽电力建设工程、电力检修项目； （四）电力建设工程中超过一定规模的危险性较大的分部分项工程，其专项施工方案未按规定开展编制、审核、批准、专家论证、技术交底，方案存在严重缺陷或方案规定的重要安全保障措施未落实，以及方案实施过程中，因自然条件、地质条件、周边环境或者施工工艺等安全生产条件发生重大变化，方案内容应当作出重大调整但未调整，或者调整后未履行审核、批准、专家论证、技术交底等管理程序； （五）施工单位或施工总承包单位对电力建设主体工程进行转包或违法分包； （六）开展爆破、动火、高处、起重吊装、临时用电、有限空间、临近带电体等"},{"i":11,"n":"第十一条","txt":"电力建设工程质量管理出现的下列任一项情形判定为一项重大隐患： （一）建设单位未按照国家有关规定办理工程质量监督手续，或未接受质量监督，或未按规定取得质量监督并网意见书即并网； （二）电力建设工程因质量问题未通过竣工验收，或验收不合格即交付使用； （三）勘察、设计单位未按照工程建设强制性标准和国家有关勘察、设计深度要求编制勘察、设计文件，或者重大设计变更未按规定履行变更程序； （四）施工单位在主要建（构）筑物的基础、主体结构、主要设备、承重构件等关键部位施工中偷工减料，或使用不合格的建筑材料、建筑构配件和设备，或有不按照工程设计图纸、施工技术标准施工的其他行为； （五）监理单位与建设单位或者施工单位串通，弄虚作假、降低工程质量；或者虚构、伪造、篡改相关监理记录，未对工程关键部位、重要工序开展检查即签署通过，将不合格的建设工程、建筑材料、建筑构配件和设备按照合格签字。"},{"i":12,"n":"第十二条","txt":"覆盖一个以上地级行政区的电力监控系统和500千伏以上电压等级并网厂站电力监控系统出现的下列任一项情形判定为一项重大隐患： （一）生产控制区与管理信息区、安全接入区之间的联接处未部署电力专用横向单向安全隔离装置； （二）生产控制区与电力监控专用网络的广域网之间的联接处未部署电力专用纵向加密认证装置或加密认证网关； （三）生产控制区内部网络与外部网络非法连通（包括跨区直联、连接互联网等）。"},{"i":13,"n":"第十三条","txt":"电力企业安全管理出现的下列任一项情形判定为一项重大隐患： （一）上岗作业的特种作业人员未按照规定经专门的安全作业培训并取得相应资格； （二）新建、改建、扩建工程的关键安全设施，未与主体工程同时设计、同时施工、同时投入生产和使用； （三）关闭、破坏直接关系生产安全的监控、报警、防护、救生设备、设施，或篡改、隐瞒、销毁其相关数据、信息； （四）未按规定制定本单位生产安全事故应急救援预案或未定期组织应急演练。"},{"i":14,"n":"第十四条","txt":"除第五条至十三条所列情形外，其他严重违反电力安全生产法律法规、规章、政策文件和强制性标准，或可能导致大面积停电、重大人员伤亡、重大经济损失等严重后果的电力安全隐患，可判定为重大隐患。"},{"i":15,"n":"第十五条","txt":"电力企业主要负责人是本单位重大隐患排查治理的第一责任人，对重大隐患排查治理工作全面负责。"},{"i":16,"n":"第十六条","txt":"电力企业应当建立以下重大隐患排查治理制度： （一）主要负责人、分管负责人、部门和岗位人员重大隐患排查治理工作要求、职责范围、防控责任； （二）重大隐患排查事项、具体内容和排查周期； （三）重大隐患的治理流程； （四）重大隐患治理结果评估； （五）重大隐患排查治理能力培训； （六）重大隐患内部报告奖励机制； （七）资金、人员和设备设施保障。"},{"i":17,"n":"第十七条","txt":"电力企业应当定期组织安全生产管理人员、专业技术人员和其他相关人员排查本单位重大隐患，对排查出的重大隐患应当进行登记。登记信息应当包括排查对象、时间、人员、隐患具体描述等内容，经电力企业主要负责人审核确认后妥善保存，并告知从业人员和相关人员在紧急情况下应当采取的应急措施。"},{"i":18,"n":"第十八条","txt":"电力企业应当建立重大隐患报告制度，发现重大隐患应在3个工作日内向国家能源局派出机构、相应地方电力管理部门报告，涉及水电站大坝安全的重大隐患应同时报送国家能源局大坝安全监察中心。重大隐患信息报告应当包括：隐患名称、隐患现状及其产生的原因、隐患危害程度和治理难易程度分析、隐患的治理计划等（详见附件）。"},{"i":19,"n":"第十九条","txt":"重大隐患涉及相邻地区、单位或社会公众安全的，电力企业应当及时通知相邻地区、单位，并报告地方人民政府有关部门，在现场进行必要的隔离并设置安全警示标志。"},{"i":20,"n":"第二十条","txt":"电力企业应当建立重大隐患管理台账，制定切实可行的治理方案，落实治理责任、治理资金、治理措施和治理期限，限期整改到位。在重大隐患治理过程中，应当加强监测，采取有效的预防措施确保安全，必要时应当制定应急预案，开展应急演练。 重大隐患治理工作涉及其他单位的，电力企业应当协调相关单位及时治理，存在困难的应当报告国家能源局及其派出机构、相应地方电力管理部门协调解决。"},{"i":21,"n":"第二十一条","txt":"在重大隐患排除前或排除过程中无法保证安全的，电力企业应当将该工程或项目停建停产停业，或停止运行存在重大隐患的设备设施，撤离人员，并及时向国家能源局派出机构、相应地方电力管理部门报告。"},{"i":22,"n":"第二十二条","txt":"重大隐患治理工作结束后，电力企业应当组织对重大隐患的治理情况进行评估，并及时将评估结果报告国家能源局派出机构、相应地方电力管理部门；涉及水电站大坝运行安全的，应同时报告国家能源局大坝安全监察中心。"},{"i":23,"n":"第二十三条","txt":"电力企业治理完成国家能源局及其派出机构、地方电力管理部门检查发现并责令停建停产停业治理的重大隐患后，应组织评估，符合安全生产条件和检查单位要求后，方可恢复生产经营或使用。"},{"i":24,"n":"第二十四条","txt":"电力企业重大隐患排查治理情况应当及时向职工大会或职工代表大会报告。"},{"i":25,"n":"第二十五条","txt":"电力企业应当对事故隐患排查过程中发现的共性问题和典型隐患，从规划设计、物资采购、施工调试、运行管理等各环节分析隐患成因，从管理和技术上制定落实治理防范措施。"},{"i":26,"n":"第二十六条","txt":"国家能源局派出机构、大坝安全监察中心，以及地方电力管理部门、电力建设工程质量监督机构应将检查发现或企业报送的重大隐患情况（详见附件），于10个工作日内逐级报送至国家能源局。 国家能源局派出机构、地方电力管理部门可依照法律法规和相关规定对整改难度大、整改时间长或者外部因素造成生产经营单位自身难以消除的重大隐患治理进行督办，国家能源局认为有必要的，可直接督办。督办可采用督办通知单的方式，内容主要包括：督办名称、督办事项、整改和过程防控要求、办理期限、督办解除程序和方式。"},{"i":27,"n":"第二十七条","txt":"任何单位或个人发现重大隐患或重大隐患排查治理违法行为，均有权向国家能源局及其派出机构、地方电力管理部门报告或举报。"},{"i":28,"n":"第二十八条","txt":"国家能源局及其派出机构、相应地方电力管理部门应当加强信息化建设，定期统计分析电力企业重大隐患排查治理情况，并将重大隐患纳入相关信息系统管理。"},{"i":29,"n":"第二十九条","txt":"国家能源局及其派出机构、相应地方电力管理部门对检查中发现的重大隐患，应当责令立即排除或限期排除；重大隐患排除前或排除过程中无法保证安全的，应当责令从危险区域内撤出作业人员，责令暂时停建停产停业，或停止使用相关设备设施。"},{"i":30,"n":"第三十条","txt":"国家能源局及其派出机构、地方电力管理部门的工作人员，在监督检查中发现重大隐患，不依法及时处理的，给予降级或者撤职的处分；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"电力企业的主要负责人未组织建立并落实重大隐患排查治理工作机制，或者未及时消除重大隐患的，责令限期改正，处二万元以上五万元以下的罚款；逾期未改正的，处五万元以上十万元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"电力企业未建立重大隐患排查治理制度，或者重大隐患排查治理情况未报告的，责令限期改正，处十万元以下的罚款；逾期未改正的，责令停建停产停业整顿，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"电力企业未将重大隐患排查治理情况如实记录或者未向从业人员通报的，责令限期改正，处十万元以下的罚款；逾期未改正的，责令停建停产停业整顿，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款。"},{"i":34,"n":"第三十四条","txt":"电力企业未采取措施消除重大隐患的，责令立即消除或者限期消除，处五万元以下的罚款；电力企业拒不执行的，责令停建停产停业整顿，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"本规定“以上”“超过”含本数，“以下”不含本数。"},{"i":36,"n":"第三十六条","txt":"本规定中所称电力企业是指以从事发电、输电、供电生产和电力建设等为主营业务的企业；所称水电站是指国家能源局监督管理范围内水电站。"},{"i":37,"n":"第三十七条","txt":"本规定由国家发展改革委、国家能源局负责解释。"},{"i":38,"n":"第三十八条","txt":"本规定自2026年7月1日起施行。 附件：重大隐患信息报告单"}],"dianzizhaobiaotoubiaobanfa-2":[{"i":1,"n":"第一条","txt":"为了规范电子招标投标活动，促进电子招标投标健康发展，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》（以下分别简称招标投标法、招标投标法实施条例），制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行电子招标投标活动，适用本办法。 本办法所称电子招标投标活动是指以数据电文形式，依托电子招标投标系统完成的全部或者部分招标投标交易、公共服务和行政监督活动。 数据电文形式与纸质形式的招标投标活动具有同等法律效力。"},{"i":3,"n":"第三条","txt":"电子招标投标系统根据功能的不同，分为交易平台、公共服务平台和行政监督平台。 交易平台是以数据电文形式完成招标投标交易活动的信息平台。公共服务平台是满足交易平台之间信息交换、资源共享需要，并为市场主体、行政监督部门和社会公众提供信息服务的信息平台。行政监督平台是行政监督部门和监察机关在线监督电子招标投标活动的信息平台。 电子招标投标系统的开发、检测、认证、运营应当遵守本办法及所附《电子招标投标系统技术规范》（以下简称技术规范）。"},{"i":4,"n":"第四条","txt":"国务院发展改革部门负责指导协调全国电子招标投标活动，各级地方人民政府发展改革部门负责指导协调本行政区域内电子招标投标活动。各级人民政府发展改革、工业和信息化、住房城乡建设、交通运输、铁道、水利、商务等部门，按照规定的职责分工，对电子招标投标活动实施监督，依法查处电子招标投标活动中的违法行为。 依法设立的招标投标交易场所的监管机构负责督促、指导招标投标交易场所推进电子招标投标工作，配合有关部门对电子招标投标活动实施监督。 省级以上人民政府有关部门对本行政区域内电子招标投标系统的建设、运营，以及相关检测、认证活动实施监督。 监察机关依法对与电子招标投标活动有关的监察对象实施监察。"},{"i":5,"n":"第五条","txt":"电子招标投标交易平台按照标准统一、互联互通、公开透明、安全高效的原则以及市场化、专业化、集约化方向建设和运营。"},{"i":6,"n":"第六条","txt":"依法设立的招标投标交易场所、招标人、招标代理机构以及其他依法设立的法人组织可以按行业、专业类别，建设和运营电子招标投标交易平台。国家鼓励电子招标投标交易平台平等竞争。"},{"i":7,"n":"第七条","txt":"电子招标投标交易平台应当按照本办法和技术规范规定，具备下列主要功能： （一）在线完成招标投标全部交易过程； （二）编辑、生成、对接、交换和发布有关招标投标数据信息； （三）提供行政监督部门和监察机关依法实施监督和受理投诉所需的监督通道； （四）本办法和技术规范规定的其他功能。"},{"i":8,"n":"第八条","txt":"电子招标投标交易平台应当按照技术规范规定，执行统一的信息分类和编码标准，为各类电子招标投标信息的互联互通和交换共享开放数据接口、公布接口要求。 电子招标投标交易平台接口应当保持技术中立，与各类需要分离开发的工具软件相兼容对接，不得限制或者排斥符合技术规范规定的工具软件与其对接。"},{"i":9,"n":"第九条","txt":"电子招标投标交易平台应当允许社会公众、市场主体免费注册登录和获取依法公开的招标投标信息，为招标投标活动当事人、行政监督部门和监察机关按各自职责和注册权限登录使用交易平台提供必要条件。"},{"i":10,"n":"第十条","txt":"电子招标投标交易平台应当依照《中华人民共和国认证认可条例》等有关规定进行检测、认证，通过检测、认证的电子招标投标交易平台应当在省级以上电子招标投标公共服务平台上公布。 电子招标投标交易平台服务器应当设在中华人民共和国境内。"},{"i":11,"n":"第十一条","txt":"电子招标投标交易平台运营机构应当是依法成立的法人，拥有一定数量的专职信息技术、招标专业人员。"},{"i":12,"n":"第十二条","txt":"电子招标投标交易平台运营机构应当根据国家有关法律法规及技术规范，建立健全电子招标投标交易平台规范运行和安全管理制度，加强监控、检测，及时发现和排除隐患。"},{"i":13,"n":"第十三条","txt":"电子招标投标交易平台运营机构应当采用可靠的身份识别、权限控制、加密、病毒防范等技术，防范非授权操作，保证交易平台的安全、稳定、可靠。"},{"i":14,"n":"第十四条","txt":"电子招标投标交易平台运营机构应当采取有效措施，验证初始录入信息的真实性，并确保数据电文不被篡改、不遗漏和可追溯。"},{"i":15,"n":"第十五条","txt":"电子招标投标交易平台运营机构不得以任何手段限制或者排斥潜在投标人，不得泄露依法应当保密的信息，不得弄虚作假、串通投标或者为弄虚作假、串通投标提供便利。"},{"i":16,"n":"第十六条","txt":"招标人或者其委托的招标代理机构应当在其使用的电子招标投标交易平台注册登记，选择使用除招标人或招标代理机构之外第三方运营的电子招标投标交易平台的，还应当与电子招标投标交易平台运营机构签订使用合同，明确服务内容、服务质量、服务费用等权利和义务，并对服务过程中相关信息的产权归属、保密责任、存档等依法作出约定。 电子招标投标交易平台运营机构不得以技术和数据接口配套为由，要求潜在投标人购买指定的工具软件。"},{"i":17,"n":"第十七条","txt":"招标人或者其委托的招标代理机构应当在资格预审公告、招标公告或者投标邀请书中载明潜在投标人访问电子招标投标交易平台的网络地址和方法。依法必须进行公开招标项目的上述相关公告应当在电子招标投标交易平台和国家指定的招标公告媒介同步发布。"},{"i":18,"n":"第十八条","txt":"招标人或者其委托的招标代理机构应当及时将数据电文形式的资格预审文件、招标文件加载至电子招标投标交易平台，供潜在投标人下载或者查阅。"},{"i":19,"n":"第十九条","txt":"数据电文形式的资格预审公告、招标公告、资格预审文件、招标文件等应当标准化、格式化，并符合有关法律法规以及国家有关部门颁发的标准文本的要求。"},{"i":20,"n":"第二十条","txt":"除本办法和技术规范规定的注册登记外，任何单位和个人不得在招标投标活动中设置注册登记、投标报名等前置条件限制潜在投标人下载资格预审文件或者招标文件。"},{"i":21,"n":"第二十一条","txt":"在投标截止时间前，电子招标投标交易平台运营机构不得向招标人或者其委托的招标代理机构以外的任何单位和个人泄露下载资格预审文件、招标文件的潜在投标人名称、数量以及可能影响公平竞争的其他信息。"},{"i":22,"n":"第二十二条","txt":"招标人对资格预审文件、招标文件进行澄清或者修改的，应当通过电子招标投标交易平台以醒目的方式公告澄清或者修改的内容，并以有效方式通知所有已下载资格预审文件或者招标文件的潜在投标人。"},{"i":23,"n":"第二十三条","txt":"电子招标投标交易平台的运营机构，以及与该机构有控股或者管理关系可能影响招标公正性的任何单位和个人，不得在该交易平台进行的招标项目中投标和代理投标。"},{"i":24,"n":"第二十四条","txt":"投标人应当在资格预审公告、招标公告或者投标邀请书载明的电子招标投标交易平台注册登记，如实递交有关信息，并经电子招标投标交易平台运营机构验证。"},{"i":25,"n":"第二十五条","txt":"投标人应当通过资格预审公告、招标公告或者投标邀请书载明的电子招标投标交易平台递交数据电文形式的资格预审申请文件或者投标文件。"},{"i":26,"n":"第二十六条","txt":"电子招标投标交易平台应当允许投标人离线编制投标文件，并且具备分段或者整体加密、解密功能。 投标人应当按照招标文件和电子招标投标交易平台的要求编制并加密投标文件。 投标人未按规定加密的投标文件，电子招标投标交易平台应当拒收并提示。"},{"i":27,"n":"第二十七条","txt":"投标人应当在投标截止时间前完成投标文件的传输递交，并可以补充、修改或者撤回投标文件。投标截止时间前未完成投标文件传输的，视为撤回投标文件。投标截止时间后送达的投标文件，电子招标投标交易平台应当拒收。 电子招标投标交易平台收到投标人送达的投标文件，应当即时向投标人发出确认回执通知，并妥善保存投标文件。在投标截止时间前，除投标人补充、修改或者撤回投标文件外，任何单位和个人不得解密、提取投标文件。"},{"i":28,"n":"第二十八条","txt":"资格预审申请文件的编制、加密、递交、传输、接收确认等，适用本办法关于投标文件的规定。"},{"i":29,"n":"第二十九条","txt":"电子开标应当按照招标文件确定的时间，在电子招标投标交易平台上公开进行，所有投标人均应当准时在线参加开标。"},{"i":30,"n":"第三十条","txt":"开标时，电子招标投标交易平台自动提取所有投标文件，提示招标人和投标人按招标文件规定方式按时在线解密。解密全部完成后，应当向所有投标人公布投标人名称、投标价格和招标文件规定的其他内容。"},{"i":31,"n":"第三十一条","txt":"因投标人原因造成投标文件未解密的，视为撤销其投标文件；因投标人之外的原因造成投标文件未解密的，视为撤回其投标文件，投标人有权要求责任方赔偿因此遭受的直接损失。部分投标文件未解密的，其他投标文件的开标可以继续进行。 招标人可以在招标文件中明确投标文件解密失败的补救方案，投标文件应按照招标文件的要求作出响应。"},{"i":32,"n":"第三十二条","txt":"电子招标投标交易平台应当生成开标记录并向社会公众公布，但依法应当保密的除外。"},{"i":33,"n":"第三十三条","txt":"电子评标应当在有效监控和保密的环境下在线进行。 根据国家规定应当进入依法设立的招标投标交易场所的招标项目，评标委员会成员应当在依法设立的招标投标交易场所登录招标项目所使用的电子招标投标交易平台进行评标。 评标中需要投标人对投标文件澄清或者说明的，招标人和投标人应当通过电子招标投标交易平台交换数据电文。"},{"i":34,"n":"第三十四条","txt":"评标委员会完成评标后，应当通过电子招标投标交易平台向招标人提交数据电文形式的评标报告。"},{"i":35,"n":"第三十五条","txt":"依法必须进行招标的项目中标候选人和中标结果应当在电子招标投标交易平台进行公示和公布。"},{"i":36,"n":"第三十六条","txt":"招标人确定中标人后，应当通过电子招标投标交易平台以数据电文形式向中标人发出中标通知书，并向未中标人发出中标结果通知书。 招标人应当通过电子招标投标交易平台，以数据电文形式与中标人签订合同。"},{"i":37,"n":"第三十七条","txt":"鼓励招标人、中标人等相关主体及时通过电子招标投标交易平台递交和公布中标合同履行情况的信息。"},{"i":38,"n":"第三十八条","txt":"资格预审申请文件的解密、开启、评审、发出结果通知书等，适用本办法关于投标文件的规定。"},{"i":39,"n":"第三十九条","txt":"投标人或者其他利害关系人依法对资格预审文件、招标文件、开标和评标结果提出异议，以及招标人答复，均应当通过电子招标投标交易平台进行。"},{"i":40,"n":"第四十条","txt":"招标投标活动中的下列数据电文应当按照《中华人民共和国电子签名法》和招标文件的要求进行电子签名并进行电子存档： （一）资格预审公告、招标公告或者投标邀请书； （二）资格预审文件、招标文件及其澄清、补充和修改； （三）资格预审申请文件、投标文件及其澄清和说明； （四）资格审查报告、评标报告； （五）资格预审结果通知书和中标通知书； （六）合同； （七）国家规定的其他文件。"},{"i":41,"n":"第四十一条","txt":"电子招标投标交易平台应当依法及时公布下列主要信息： （一）招标人名称、地址、联系人及联系方式； （二）招标项目名称、内容范围、规模、资金来源和主要技术要求； （三）招标代理机构名称、资格、项目负责人及联系方式； （四）投标人名称、资质和许可范围、项目负责人； （五）中标人名称、中标金额、签约时间、合同期限； （六）国家规定的公告、公示和技术规范规定公布和交换的其他信息。 鼓励招标投标活动当事人通过电子招标投标交易平台公布项目完成质量、期限、结算金额等合同履行情况。"},{"i":42,"n":"第四十二条","txt":"各级人民政府有关部门应当按照《中华人民共和国政府信息公开条例》等规定，在本部门网站及时公布并允许下载下列信息： （一）有关法律法规规章及规范性文件； （二）取得相关工程、服务资质证书或货物生产、经营许可证的单位名称、营业范围及年检情况； （三）取得有关职称、职业资格的从业人员的姓名、电子证书编号； （四）对有关违法行为作出的行政处理决定和招标投标活动的投诉处理情况； （五）依法公开的工商、税务、海关、金融等相关信息。"},{"i":43,"n":"第四十三条","txt":"设区的市级以上人民政府发展改革部门会同有关部门，按照政府主导、共建共享、公益服务的原则，推动建立本地区统一的电子招标投标公共服务平台，为电子招标投标交易平台、招标投标活动当事人、社会公众和行政监督部门、监察机关提供信息服务。"},{"i":44,"n":"第四十四条","txt":"电子招标投标公共服务平台应当按照本办法和技术规范规定，具备下列主要功能： （一）链接各级人民政府及其部门网站，收集、整合和发布有关法律法规规章及规范性文件、行政许可、行政处理决定、市场监管和服务的相关信息； （二）连接电子招标投标交易平台、国家规定的公告媒介，交换、整合和发布本办法第四十一条规定的信息； （三）连接依法设立的评标专家库，实现专家资源共享； （四）支持不同电子认证服务机构数字证书的兼容互认； （五）提供行政监督部门和监察机关依法实施监督、监察所需的监督通道； （六）整合分析相关数据信息，动态反映招标投标市场运行状况、相关市场主体业绩和信用情况。 属于依法必须公开的信息，公共服务平台应当无偿提供。 公共服务平台应同时遵守本办法第八条至第十五条规定。"},{"i":45,"n":"第四十五条","txt":"电子招标投标交易平台应当按照本办法和技术规范规定，在任一电子招标投标公共服务平台注册登记，并向电子招标投标公共服务平台及时提供本办法第四十一条规定的信息，以及双方协商确定的其他信息。 电子招标投标公共服务平台应当按照本办法和技术规范规定，开放数据接口、公布接口要求，与电子招标投标交易平台及时交换招标投标活动所必需的信息，以及双方协商确定的其他信息。 电子招标投标公共服务平台应当按照本办法和技术规范规定，开放数据接口、公布接口要求，与上一层级电子招标投标公共服务平台连接并注册登记，及时交换本办法第四十四条规定的信息，以及双方协商确定的其他信息。 电子招标投标公共服务平台应当允许社会公众、市场主体免费注册登录和获取依法公开的招标投标信息，为招标人、投标人、行政监督部门和监察机关按各自职责和注册权限登录使用公共服务平台提供必要条件。"},{"i":46,"n":"第四十六条","txt":"电子招标投标活动及相关主体应当自觉接受行政监督部门、监察机关依法实施的监督、监察。"},{"i":47,"n":"第四十七条","txt":"行政监督部门、监察机关结合电子政务建设，提升电子招标投标监督能力，依法设置并公布有关法律法规规章、行政监督的依据、职责权限、监督环节、程序和时限、信息交换要求和联系方式等相关内容。"},{"i":48,"n":"第四十八条","txt":"电子招标投标交易平台和公共服务平台应当按照本办法和技术规范规定，向行政监督平台开放数据接口、公布接口要求，按有关规定及时对接交换和公布有关招标投标信息。 行政监督平台应当开放数据接口，公布数据接口要求，不得限制和排斥已通过检测认证的电子招标投标交易平台和公共服务平台与其对接交换信息，并参照执行本办法第八条至第十五条的有关规定。"},{"i":49,"n":"第四十九条","txt":"电子招标投标交易平台应当依法设置电子招标投标工作人员的职责权限，如实记录招标投标过程、数据信息来源，以及每一操作环节的时间、网络地址和工作人员，并具备电子归档功能。 电子招标投标公共服务平台应当记录和公布相关交换数据信息的来源、时间并进行电子归档备份。 任何单位和个人不得伪造、篡改或者损毁电子招标投标活动信息。"},{"i":50,"n":"第五十条","txt":"行政监督部门、监察机关及其工作人员，除依法履行职责外，不得干预电子招标投标活动，并遵守有关信息保密的规定。"},{"i":51,"n":"第五十一条","txt":"投标人或者其他利害关系人认为电子招标投标活动不符合有关规定的，通过相关行政监督平台进行投诉。"},{"i":52,"n":"第五十二条","txt":"行政监督部门和监察机关在依法监督检查招标投标活动或者处理投诉时，通过其平台发出的行政监督或者行政监察指令，招标投标活动当事人和电子招标投标交易平台、公共服务平台的运营机构应当执行，并如实提供相关信息，协助调查处理。"},{"i":53,"n":"第五十三条","txt":"电子招标投标系统有下列情形的，责令改正；拒不改正的，不得交付使用，已经运营的应当停止运营。 （一）不具备本办法及技术规范规定的主要功能； （二）不向行政监督部门和监察机关提供监督通道； （三）不执行统一的信息分类和编码标准； （四）不开放数据接口、不公布接口要求； （五）不按照规定注册登记、对接、交换、公布信息； （六）不满足规定的技术和安全保障要求； （七）未按照规定通过检测和认证。"},{"i":54,"n":"第五十四条","txt":"招标人或者电子招标投标系统运营机构存在以下情形的，视为限制或者排斥潜在投标人，依照招标投标法第五十一条规定处罚。 （一）利用技术手段对享有相同权限的市场主体提供有差别的信息； （二）拒绝或者限制社会公众、市场主体免费注册并获取依法必须公开的招标投标信息； （三）违规设置注册登记、投标报名等前置条件； （四）故意与各类需要分离开发并符合技术规范规定的工具软件不兼容对接； （五）故意对递交或者解密投标文件设置障碍。"},{"i":55,"n":"第五十五条","txt":"电子招标投标交易平台运营机构有下列情形的，责令改正，并按照有关规定处罚。 （一）违反规定要求投标人注册登记、收取费用； （二）要求投标人购买指定的工具软件； （三）其他侵犯招标投标活动当事人合法权益的情形。"},{"i":56,"n":"第五十六条","txt":"电子招标投标系统运营机构向他人透露已获取招标文件的潜在投标人的名称、数量、投标文件内容或者对投标文件的评审和比较以及其他可能影响公平竞争的招标投标信息，参照招标投标法第五十二条关于招标人泄密的规定予以处罚。"},{"i":57,"n":"第五十七条","txt":"招标投标活动当事人和电子招标投标系统运营机构协助招标人、投标人串通投标的，依照招标投标法第五十三条和招标投标法实施条例第六十七条规定处罚。"},{"i":58,"n":"第五十八条","txt":"招标投标活动当事人和电子招标投标系统运营机构伪造、篡改、损毁招标投标信息，或者以其他方式弄虚作假的，依照招标投标法第五十四条和招标投标法实施条例第六十八条规定处罚。"},{"i":59,"n":"第五十九条","txt":"电子招标投标系统运营机构未按照本办法和技术规范规定履行初始录入信息验证义务，造成招标投标活动当事人损失的，应当承担相应的赔偿责任。"},{"i":60,"n":"第六十条","txt":"有关行政监督部门及其工作人员不履行职责，或者利用职务便利非法干涉电子招标投标活动的，依照有关法律法规处理。"},{"i":61,"n":"第六十一条","txt":"招标投标协会应当按照有关规定，加强电子招标投标活动的自律管理和服务。"},{"i":62,"n":"第六十二条","txt":"电子招标投标某些环节需要同时使用纸质文件的，应当在招标文件中明确约定；当纸质文件与数据电文不一致时，除招标文件特别约定外，以数据电文为准。"},{"i":63,"n":"第六十三条","txt":"本办法未尽事宜，按照有关法律、法规、规章执行。"},{"i":64,"n":"第六十四条","txt":"本办法由国家发展和改革委员会会同有关部门负责解释。"},{"i":65,"n":"第六十五条","txt":"技术规范作为本办法的附件，与本办法具有同等效力。"},{"i":66,"n":"第六十六条","txt":"本办法自2013年5月1日起施行。"}],"dianzizhaobiaotoubiaobanfa-3":[{"i":1,"n":"第一条","txt":"为了规范电子招标投标活动，促进电子招标投标健康发展，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》(以下分别简称招标投标法、招标投标法实施条例)，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行电子招标投标活动，适用本办法。 本办法所称电子招标投标活动是指以数据电文形式，依托电子招标投标系统完成的全部或者部分招标投标交易、公共服务和行政监督活动。 数据电文形式与纸质形式的招标投标活动具有同等法律效力。"},{"i":3,"n":"第三条","txt":"电子招标投标系统根据功能的不同，分为交易平台、公共服务平台和行政监督平台。 交易平台是以数据电文形式完成招标投标交易活动的信息平台。公共服务平台是满足交易平台之间信息交换、资源共享需要，并为市场主体、行政监督部门和社会公众提供信息服务的信息平台。行政监督平台是行政监督部门和监察机关在线监督电子招标投标活动的信息平台。 电子招标投标系统的开发、检测、认证、运营应当遵守本办法及所附《电子招标投标系统技术规范》(以下简称技术规范)。"},{"i":4,"n":"第四条","txt":"国务院发展改革部门负责指导协调全国电子招标投标活动，各级地方人民政府发展改革部门负责指导协调本行政区域内电子招标投标活动。各级人民政府发展改革、工业和信息化、住房城乡建设、交通运输、铁道、水利、商务等部门，按照规定的职责分工，对电子招标投标活动实施监督，依法查处电子招标投标活动中的违法行为。 依法设立的招标投标交易场所的监管机构负责督促、指导招标投标交易场所推进电子招标投标工作，配合有关部门对电子招标投标活动实施监督。 省级以上人民政府有关部门对本行政区域内电子招标投标系统的建设、运营，以及相关检测、认证活动实施监督。 监察机关依法对与电子招标投标活动有关的监察对象实施监察。"},{"i":5,"n":"第五条","txt":"电子招标投标交易平台按照标准统一、互联互通、公开透明、安全高效的原则以及市场化、专业化、集约化方向建设和运营。"},{"i":6,"n":"第六条","txt":"依法设立的招标投标交易场所、招标人、招标代理机构以及其他依法设立的法人组织可以按行业、专业类别，建设和运营电子招标投标交易平台。国家鼓励电子招标投标交易平台平等竞争。"},{"i":7,"n":"第七条","txt":"电子招标投标交易平台应当按照本办法和技术规范规定，具备下列主要功能： (一)在线完成招标投标全部交易过程; (二)编辑、生成、对接、交换和发布有关招标投标数据信息; (三)提供行政监督部门和监察机关依法实施监督和受理投诉所需的监督通道; (四)本办法和技术规范规定的其他功能。"},{"i":8,"n":"第八条","txt":"电子招标投标交易平台应当按照技术规范规定，执行统一的信息分类和编码标准，为各类电子招标投标信息的互联互通和交换共享开放数据接口、公布接口要求。 电子招标投标交易平台接口应当保持技术中立，与各类需要分离开发的工具软件相兼容对接，不得限制或者排斥符合技术规范规定的工具软件与其对接。"},{"i":9,"n":"第九条","txt":"电子招标投标交易平台应当允许社会公众、市场主体免费注册登录和获取依法公开的招标投标信息，为招标投标活动当事人、行政监督部门和监察机关按各自职责和注册权限登录使用交易平台提供必要条件。"},{"i":10,"n":"第十条","txt":"电子招标投标交易平台应当依照《中华人民共和国认证认可条例》等有关规定进行检测、认证，通过检测、认证的电子招标投标交易平台应当在省级以上电子招标投标公共服务平台上公布。 电子招标投标交易平台服务器应当设在中华人民共和国境内。"},{"i":11,"n":"第十一条","txt":"电子招标投标交易平台运营机构应当是依法成立的法人，拥有一定数量的专职信息技术、招标专业人员。"},{"i":12,"n":"第十二条","txt":"电子招标投标交易平台运营机构应当根据国家有关法律法规及技术规范，建立健全电子招标投标交易平台规范运行和安全管理制度，加强监控、检测，及时发现和排除隐患。"},{"i":13,"n":"第十三条","txt":"电子招标投标交易平台运营机构应当采用可靠的身份识别、权限控制、加密、病毒防范等技术，防范非授权操作，保证交易平台的安全、稳定、可靠。"},{"i":14,"n":"第十四条","txt":"电子招标投标交易平台运营机构应当采取有效措施，验证初始录入信息的真实性，并确保数据电文不被篡改、不遗漏和可追溯。"},{"i":15,"n":"第十五条","txt":"电子招标投标交易平台运营机构不得以任何手段限制或者排斥潜在投标人，不得泄露依法应当保密的信息，不得弄虚作假、串通投标或者为弄虚作假、串通投标提供便利。"},{"i":16,"n":"第十六条","txt":"招标人或者其委托的招标代理机构应当在其使用的电子招标投标交易平台注册登记，选择使用除招标人或招标代理机构之外第三方运营的电子招标投标交易平台的，还应当与电子招标投标交易平台运营机构签订使用合同，明确服务内容、服务质量、服务费用等权利和义务，并对服务过程中相关信息的产权归属、保密责任、存档等依法作出约定。 电子招标投标交易平台运营机构不得以技术和数据接口配套为由，要求潜在投标人购买指定的工具软件。"},{"i":17,"n":"第十七条","txt":"招标人或者其委托的招标代理机构应当在资格预审公告、招标公告或者投标邀请书中载明潜在投标人访问电子招标投标交易平台的网络地址和方法。依法必须进行公开招标项目的上述相关公告应当在电子招标投标交易平台和国家指定的招标公告媒介同步发布。"},{"i":18,"n":"第十八条","txt":"招标人或者其委托的招标代理机构应当及时将数据电文形式的资格预审文件、招标文件加载至电子招标投标交易平台，供潜在投标人下载或者查阅。"},{"i":19,"n":"第十九条","txt":"数据电文形式的资格预审公告、招标公告、资格预审文件、招标文件等应当标准化、格式化，并符合有关法律法规以及国家有关部门颁发的标准文本的要求。"},{"i":20,"n":"第二十条","txt":"除本办法和技术规范规定的注册登记外，任何单位和个人不得在招标投标活动中设置注册登记、投标报名等前置条件限制潜在投标人下载资格预审文件或者招标文件。"},{"i":21,"n":"第二十一条","txt":"在投标截止时间前，电子招标投标交易平台运营机构不得向招标人或者其委托的招标代理机构以外的任何单位和个人泄露下载资格预审文件、招标文件的潜在投标人名称、数量以及可能影响公平竞争的其他信息。"},{"i":22,"n":"第二十二条","txt":"招标人对资格预审文件、招标文件进行澄清或者修改的，应当通过电子招标投标交易平台以醒目的方式公告澄清或者修改的内容，并以有效方式通知所有已下载资格预审文件或者招标文件的潜在投标人。"},{"i":23,"n":"第二十三条","txt":"电子招标投标交易平台的运营机构，以及与该机构有控股或者管理关系可能影响招标公正性的任何单位和个人，不得在该交易平台进行的招标项目中投标和代理投标。"},{"i":24,"n":"第二十四条","txt":"投标人应当在资格预审公告、招标公告或者投标邀请书载明的电子招标投标交易平台注册登记，如实递交有关信息，并经电子招标投标交易平台运营机构验证。"},{"i":25,"n":"第二十五条","txt":"投标人应当通过资格预审公告、招标公告或者投标邀请书载明的电子招标投标交易平台递交数据电文形式的资格预审申请文件或者投标文件。"},{"i":26,"n":"第二十六条","txt":"电子招标投标交易平台应当允许投标人离线编制投标文件，并且具备分段或者整体加密、解密功能。 投标人应当按照招标文件和电子招标投标交易平台的要求编制并加密投标文件。 投标人未按规定加密的投标文件，电子招标投标交易平台应当拒收并提示。"},{"i":27,"n":"第二十七条","txt":"投标人应当在投标截止时间前完成投标文件的传输递交，并可以补充、修改或者撤回投标文件。投标截止时间前未完成投标文件传输的，视为撤回投标文件。投标截止时间后送达的投标文件，电子招标投标交易平台应当拒收。 电子招标投标交易平台收到投标人送达的投标文件，应当即时向投标人发出确认回执通知，并妥善保存投标文件。在投标截止时间前，除投标人补充、修改或者撤回投标文件外，任何单位和个人不得解密、提取投标文件。"},{"i":28,"n":"第二十八条","txt":"资格预审申请文件的编制、加密、递交、传输、接收确认等，适用本办法关于投标文件的规定。"},{"i":29,"n":"第二十九条","txt":"电子开标应当按照招标文件确定的时间，在电子招标投标交易平台上公开进行，所有投标人均应当准时在线参加开标。"},{"i":30,"n":"第三十条","txt":"开标时，电子招标投标交易平台自动提取所有投标文件，提示招标人和投标人按招标文件规定方式按时在线解密。解密全部完成后，应当向所有投标人公布投标人名称、投标价格和招标文件规定的其他内容。"},{"i":31,"n":"第三十一条","txt":"因投标人原因造成投标文件未解密的，视为撤销其投标文件;因投标人之外的原因造成投标文件未解密的，视为撤回其投标文件，投标人有权要求责任方赔偿因此遭受的直接损失。部分投标文件未解密的，其他投标文件的开标可以继续进行。 招标人可以在招标文件中明确投标文件解密失败的补救方案，投标文件应按照招标文件的要求作出响应。"},{"i":32,"n":"第三十二条","txt":"电子招标投标交易平台应当生成开标记录并向社会公众公布，但依法应当保密的除外。"},{"i":33,"n":"第三十三条","txt":"电子评标应当在有效监控和保密的环境下在线进行。 根据国家规定应当进入依法设立的招标投标交易场所的招标项目，评标委员会成员应当在依法设立的招标投标交易场所登录招标项目所使用的电子招标投标交易平台进行评标。 评标中需要投标人对投标文件澄清或者说明的，招标人和投标人应当通过电子招标投标交易平台交换数据电文。"},{"i":34,"n":"第三十四条","txt":"评标委员会完成评标后，应当通过电子招标投标交易平台向招标人提交数据电文形式的评标报告。"},{"i":35,"n":"第三十五条","txt":"依法必须进行招标的项目中标候选人和中标结果应当在电子招标投标交易平台进行公示和公布。"},{"i":36,"n":"第三十六条","txt":"招标人确定中标人后，应当通过电子招标投标交易平台以数据电文形式向中标人发出中标通知书，并向未中标人发出中标结果通知书。 招标人应当通过电子招标投标交易平台，以数据电文形式与中标人签订合同。"},{"i":37,"n":"第三十七条","txt":"鼓励招标人、中标人等相关主体及时通过电子招标投标交易平台递交和公布中标合同履行情况的信息。"},{"i":38,"n":"第三十八条","txt":"资格预审申请文件的解密、开启、评审、发出结果通知书等，适用本办法关于投标文件的规定。"},{"i":39,"n":"第三十九条","txt":"投标人或者其他利害关系人依法对资格预审文件、招标文件、开标和评标结果提出异议，以及招标人答复，均应当通过电子招标投标交易平台进行。"},{"i":40,"n":"第四十条","txt":"招标投标活动中的下列数据电文应当按照《中华人民共和国电子签名法》和招标文件的要求进行电子签名并进行电子存档： (一)资格预审公告、招标公告或者投标邀请书; (二)资格预审文件、招标文件及其澄清、补充和修改; (三)资格预审申请文件、投标文件及其澄清和说明; (四)资格审查报告、评标报告; (五)资格预审结果通知书和中标通知书; (六)合同; (七)国家规定的其他文件。"},{"i":41,"n":"第四十一条","txt":"电子招标投标交易平台应当依法及时公布下列主要信息： (一)招标人名称、地址、联系人及联系方式; (二)招标项目名称、内容范围、规模、资金来源和主要技术要求; (三)招标代理机构名称、资格、项目负责人及联系方式; (四)投标人名称、资质和许可范围、项目负责人; (五)中标人名称、中标金额、签约时间、合同期限; (六)国家规定的公告、公示和技术规范规定公布和交换的其他信息。 鼓励招标投标活动当事人通过电子招标投标交易平台公布项目完成质量、期限、结算金额等合同履行情况。"},{"i":42,"n":"第四十二条","txt":"各级人民政府有关部门应当按照《中华人民共和国政府信息公开条例》等规定，在本部门网站及时公布并允许下载下列信息： (一)有关法律法规规章及规范性文件; (二)取得相关工程、服务资质证书或货物生产、经营许可证的单位名称、营业范围及年检情况; (三)取得有关职称、职业资格的从业人员的姓名、电子证书编号; (四)对有关违法行为作出的行政处理决定和招标投标活动的投诉处理情况; (五)依法公开的工商、税务、海关、金融等相关信息。"},{"i":43,"n":"第四十三条","txt":"设区的市级以上人民政府发展改革部门会同有关部门，按照政府主导、共建共享、公益服务的原则，推动建立本地区统一的电子招标投标公共服务平台，为电子招标投标交易平台、招标投标活动当事人、社会公众和行政监督部门、监察机关提供信息服务。"},{"i":44,"n":"第四十四条","txt":"电子招标投标公共服务平台应当按照本办法和技术规范规定，具备下列主要功能： (一)链接各级人民政府及其部门网站，收集、整合和发布有关法律法规规章及规范性文件、行政许可、行政处理决定、市场监管和服务的相关信息; (二)连接电子招标投标交易平台、国家规定的公告媒介，交换、整合和发布本办法第四十一条规定的信息; (三)连接依法设立的评标专家库，实现专家资源共享; (四)支持不同电子认证服务机构数字证书的兼容互认; (五)提供行政监督部门和监察机关依法实施监督、监察所需的监督通道; (六)整合分析相关数据信息，动态反映招标投标市场运行状况、相关市场主体业绩和信用情况。 属于依法必须公开的信息，公共服务平台应当无偿提供。 公共服务平台应同时遵守本办法第八条至第十五条规定。"},{"i":45,"n":"第四十五条","txt":"电子招标投标交易平台应当按照本办法和技术规范规定，在任一电子招标投标公共服务平台注册登记，并向电子招标投标公共服务平台及时提供本办法第四十一条规定的信息，以及双方协商确定的其他信息。 电子招标投标公共服务平台应当按照本办法和技术规范规定，开放数据接口、公布接口要求，与电子招标投标交易平台及时交换招标投标活动所必需的信息，以及双方协商确定的其他信息。 电子招标投标公共服务平台应当按照本办法和技术规范规定，开放数据接口、公布接口要求，与上一层级电子招标投标公共服务平台连接并注册登记，及时交换本办法第四十四条规定的信息，以及双方协商确定的其他信息。 电子招标投标公共服务平台应当允许社会公众、市场主体免费注册登录和获取依法公开的招标投标信息，为招标人、投标人、行政监督部门和监察机关按各自职责和注册权限登录使用公共服务平台提供必要条件。"},{"i":46,"n":"第四十六条","txt":"电子招标投标活动及相关主体应当自觉接受行政监督部门、监察机关依法实施的监督、监察。"},{"i":47,"n":"第四十七条","txt":"行政监督部门、监察机关结合电子政务建设，提升电子招标投标监督能力，依法设置并公布有关法律法规规章、行政监督的依据、职责权限、监督环节、程序和时限、信息交换要求和联系方式等相关内容。"},{"i":48,"n":"第四十八条","txt":"电子招标投标交易平台和公共服务平台应当按照本办法和技术规范规定，向行政监督平台开放数据接口、公布接口要求，按有关规定及时对接交换和公布有关招标投标信息。 行政监督平台应当开放数据接口，公布数据接口要求，不得限制和排斥已通过检测认证的电子招标投标交易平台和公共服务平台与其对接交换信息，并参照执行本办法第八条至第十五条的有关规定。"},{"i":49,"n":"第四十九条","txt":"电子招标投标交易平台应当依法设置电子招标投标工作人员的职责权限，如实记录招标投标过程、数据信息来源，以及每一操作环节的时间、网络地址和工作人员，并具备电子归档功能。 电子招标投标公共服务平台应当记录和公布相关交换数据信息的来源、时间并进行电子归档备份。 任何单位和个人不得伪造、篡改或者损毁电子招标投标活动信息。"},{"i":50,"n":"第五十条","txt":"行政监督部门、监察机关及其工作人员，除依法履行职责外，不得干预电子招标投标活动，并遵守有关信息保密的规定。"},{"i":51,"n":"第五十一条","txt":"投标人或者其他利害关系人认为电子招标投标活动不符合有关规定的，通过相关行政监督平台进行投诉。"},{"i":52,"n":"第五十二条","txt":"行政监督部门和监察机关在依法监督检查招标投标活动或者处理投诉时，通过其平台发出的行政监督或者行政监察指令，招标投标活动当事人和电子招标投标交易平台、公共服务平台的运营机构应当执行，并如实提供相关信息，协助调查处理。"},{"i":53,"n":"第五十三条","txt":"电子招标投标系统有下列情形的，责令改正;拒不改正的，不得交付使用，已经运营的应当停止运营。 (一)不具备本办法及技术规范规定的主要功能; (二)不向行政监督部门和监察机关提供监督通道; (三)不执行统一的信息分类和编码标准; (四)不开放数据接口、不公布接口要求; (五)不按照规定注册登记、对接、交换、公布信息; (六)不满足规定的技术和安全保障要求; (七)未按照规定通过检测和认证。"},{"i":54,"n":"第五十四条","txt":"招标人或者电子招标投标系统运营机构存在以下情形的，视为限制或者排斥潜在投标人，依照招标投标法第五十一条规定处罚。 (一)利用技术手段对享有相同权限的市场主体提供有差别的信息; (二)拒绝或者限制社会公众、市场主体免费注册并获取依法必须公开的招标投标信息; (三)违规设置注册登记、投标报名等前置条件; (四)故意与各类需要分离开发并符合技术规范规定的工具软件不兼容对接; (五)故意对递交或者解密投标文件设置障碍。"},{"i":55,"n":"第五十五条","txt":"电子招标投标交易平台运营机构有下列情形的，责令改正，并按照有关规定处罚。 (一)违反规定要求投标人注册登记、收取费用; (二)要求投标人购买指定的工具软件; (三)其他侵犯招标投标活动当事人合法权益的情形。"},{"i":56,"n":"第五十六条","txt":"电子招标投标系统运营机构向他人透露已获取招标文件的潜在投标人的名称、数量、投标文件内容或者对投标文件的评审和比较以及其他可能影响公平竞争的招标投标信息，参照招标投标法第五十二条关于招标人泄密的规定予以处罚。"},{"i":57,"n":"第五十七条","txt":"招标投标活动当事人和电子招标投标系统运营机构协助招标人、投标人串通投标的，依照招标投标法第五十三条和招标投标法实施条例第六十七条规定处罚。"},{"i":58,"n":"第五十八条","txt":"招标投标活动当事人和电子招标投标系统运营机构伪造、篡改、损毁招标投标信息，或者以其他方式弄虚作假的，依照招标投标法第五十四条和招标投标法实施条例第六十八条规定处罚。"},{"i":59,"n":"第五十九条","txt":"电子招标投标系统运营机构未按照本办法和技术规范规定履行初始录入信息验证义务，造成招标投标活动当事人损失的，应当承担相应的赔偿责任。"},{"i":60,"n":"第六十条","txt":"有关行政监督部门及其工作人员不履行职责，或者利用职务便利非法干涉电子招标投标活动的，依照有关法律法规处理。"},{"i":61,"n":"第六十一条","txt":"招标投标协会应当按照有关规定，加强电子招标投标活动的自律管理和服务。"},{"i":62,"n":"第六十二条","txt":"电子招标投标某些环节需要同时使用纸质文件的，应当在招标文件中明确约定;当纸质文件与数据电文不一致时，除招标文件特别约定外，以数据电文为准。"},{"i":63,"n":"第六十三条","txt":"本办法未尽事宜，按照有关法律、法规、规章执行。"},{"i":64,"n":"第六十四条","txt":"本办法由国家发展和改革委员会会同有关部门负责解释。"},{"i":65,"n":"第六十五条","txt":"技术规范作为本办法的附件，与本办法具有同等效力。"},{"i":66,"n":"第六十六条","txt":"本办法自2013年5月1日起施行。 附件：《电子招标投标系统技术规范―第1部分》 电子招标投标系统技术规范 第1部分：交易平台技术规范 2013年 目 录 1 范围 2 规范性引用文件 3 术语和定义 4 交易平台结构 4.1 电子招标投标系统架构图 4.2 交易平台结构图 5 交易平台基本功能要求 5.1 用户注册 5.2 招标方案 5.3 投标邀请 5.4 发标 5.5 投标 5.6 开标 5.7 评标 5.8 定标 5.9 费用管理 5.10 异议 5.11 招标异常 5.12 存档、归档 5.13 监督 6 交易平台信息资源库 6.1 招标项目信息库 6.2 招标人信息库 6.3 招标代理机构信息库 6.4 投标人信息库 6.5 专家信息库 6.6 价格信息库 7 交易平台的系统接口 7.1 公共服务平台的接口 7.2 与行政监督平台的接口 7.3 与专业工具软件的接口 8 交"}],"diannengzhiliangguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强电能质量管理，保障电力系统电能质量水平，优化电力营商环境，更好满足电力用户电能质量需求，支撑电力系统的安全、稳定、优质、经济运行，依照《中华人民共和国电力法》《电力供应与使用条例》《电网调度管理条例》和《电力监管条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内的电力生产、供应和使用过程中的电能质量管理工作。"},{"i":3,"n":"第三条","txt":"本办法所称的电能质量管理，是指综合采用技术、经济、行政等手段，使电力系统电能质量限制在国家标准规定范围内，以保证发电、供电和用电三方的正常运行和合法权益的活动，包括发电电能质量管理、输配电电能质量管理、用电电能质量管理，以及信息管理、监督管理等。"},{"i":4,"n":"第四条","txt":"电能质量管理应当遵循“标准指引、预防为主、综合治理”的方针，发电、供电和用电各方应在工程项目规划、设计、建设、运行的全过程贯彻电能质量主动防治的理念，共同维护电气安全使用环境。"},{"i":5,"n":"第五条","txt":"保障电力系统电能质量是发电企业、电网企业、电力用户的共同责任。建立健全政府监督管理、行业自律和企业履责的机制，强化和落实发电企业、电网企业、电力用户的主体责任，共同维护电力系统电能质量水平。因发电、电网或用户原因引起电能质量问题时，责任主体应当按“谁干扰，谁治理”的原则及时处理，并接受监督管理。"},{"i":6,"n":"第六条","txt":"国家能源局负责全国电能质量管理和监督工作，建立健全电能质量管理制度和行业标准；地方各级电力管理部门负责本行政区域内电能质量管理工作，建立健全电力用户电能质量管理制度，协调处理电能质量问题诉求，监督各方落实主体责任；国家能源局派出机构负责辖区内电能质量监督工作，监督检查电网企业和发电企业执行国家法律法规、政策文件等的情况。"},{"i":7,"n":"第七条","txt":"电网企业、发电企业和电力用户应贯彻执行国家有关电能质量管理规定。电网企业和发电企业应建立健全本企业电能质量管理制度，明确负责电能质量管理的部门及人员，开展电能质量管理和信息采集分析工作。"},{"i":8,"n":"第八条","txt":"电网企业负责所属电网电能质量管理工作。负责所属电网电能质量监测和调控。负责发电并网点和电力用户公共连接点的电能质量管理。协助国家能源局及其派出机构、地方各级电力管理部门督促发电企业、电力用户电能质量治理措施落实。"},{"i":9,"n":"第九条","txt":"发电企业负责所属厂（场）站电能质量管理工作。负责发电厂（场）站电能质量监测、电能质量问题防治，配合开展并网点电能质量管理等工作。"},{"i":10,"n":"第十条","txt":"电力用户负责所属厂站（房）或设备（设施）电能质量管理工作。负责用电电能质量监测、电能质量问题防治，配合开展公共连接点电能质量管理等工作。"},{"i":11,"n":"第十一条","txt":"行业协会开展电能质量行业自律与服务，开展信息分析与应用、技术交流与合作等工作。鼓励支持行业协会开展职业能力培训与评价等服务工作。"},{"i":12,"n":"第十二条","txt":"鼓励电能质量监测装置、治理设备制造企业加强产品的生产过程控制及检验，确保提供符合标准要求的合格产品。鼓励发电企业、电力用户使用经电能质量特性检测认证的发电和用电设备。"},{"i":13,"n":"第十三条","txt":"发电企业应当服从电力调度指令落实调频、调压有关措施，确保电能质量符合国家标准。"},{"i":14,"n":"第十四条","txt":"新（改、扩）建的新能源场站、10千伏及以上电压等级并网的分布式电源和新型储能应当在接入电力系统规划可研阶段开展电能质量评估，配置电能质量在线监测装置，采取必要的电能质量防治措施。治理设备、在线监测装置应当与主体工程同时设计、同时施工、同时验收、同时投运。在试运行阶段（6个月内），应当开展电能质量监测，指标超标时应当主动采取治理措施。"},{"i":15,"n":"第十五条","txt":"发电企业应当在生产运行阶段开展电能质量监测工作，针对自身原因引起的电能质量问题主动采取防治措施。新能源发电场站应当配置电能质量在线监测装置，并配合问题调查分析，为电能质量指标统计和问题分析提供数据支撑。"},{"i":16,"n":"第十六条","txt":"10千伏以下电压等级并网的分布式电源应当配置具备必要的电能质量监测功能的设备，并进行电能质量指标超标预警和主动控制。电能质量指标不符合国家标准有关规定的，应当采取防治措施。采取防治措施后电能质量仍不符合国家标准，影响电网安全运行或其他电力用户正常用电时，应当配合电网企业执行出力控制或离网控制。"},{"i":17,"n":"第十七条","txt":"发电企业应当开展电能质量管理工作相关信息采集与问题分析治理能力建设，建立变流器等干扰源设备、治理设备、监测装置台账库，定期维护更新。"},{"i":18,"n":"第十八条","txt":"电网企业应当不断完善网架结构、优化运行方式，提高电网适应性。在发电设备和用电设备接入电力系统时，电网企业应当审核发电设备和用电设备接入电力系统产生电能质量干扰的情况，可按照国家有关规定拒绝不符合规定的发电设备和用电设备接入电力系统。"},{"i":19,"n":"第十九条","txt":"高压直流输电、柔性输电等非线性设施规划设计阶段应当开展电能质量评估，配置电能质量在线监测装置，必要时配置电能质量调控设备，且与主体工程同时设计、同时施工、同时验收、同时投运。"},{"i":20,"n":"第二十条","txt":"电网企业应当加强对新能源场站并网点、10千伏及以上接有干扰源用户的公共连接点的电能质量问题分析。由于发电企业或电力用户影响电能质量或者干扰电力系统安全运行时，发电企业或电力用户应采取防治措施予以消除。对不采取措施或者采取措施不力的，电网企业可按照国家有关规定拒绝其接入电网或者中止供电，并报送本级电力管理部门、抄报所属国家能源局派出机构。 干扰源用户消除引起中止供电的原因后，电网企业应当在24小时内恢复供电，不能在24小时内恢复供电的，应向干扰源用户说明原因。"},{"i":21,"n":"第二十一条","txt":"电网企业应当开展电能质量管理工作相关信息采集与问题分析治理能力建设，建立电能质量监测、调控设备台账，定期维护更新。"},{"i":22,"n":"第二十二条","txt":"干扰源用户接入电力系统时，应当在规划可研阶段开展电能质量评估，采取必要的电能质量防治措施，并与主体工程同时设计、同时施工、同时验收、同时投运。在试运行阶段（6个月内），应当开展电能质量监测，指标超标时应当主动采取治理措施。"},{"i":23,"n":"第二十三条","txt":"对电能质量有特殊要求的用户在接入电力系统时，应当自行开展电能质量需求分析，采用耐受水平与电能质量需求相匹配的用电设备，以及配置合适的电能质量控制设备，确保电能质量满足自身需求。"},{"i":24,"n":"第二十四条","txt":"存在电能质量问题的干扰源用户和对电能质量有特殊要求的用户应当加强电能质量监测分析，针对自身原因引起的电能质量问题主动采取防治措施，并配合问题调查分析，提供数据支撑。"},{"i":25,"n":"第二十五条","txt":"干扰源用户和对电能质量有特殊要求的用户应当建立干扰源设备、对电能质量有特殊需求的设备、治理设备、监测装置台账库，定期维护更新。"},{"i":26,"n":"第二十六条","txt":"鼓励各方为对电能质量有特殊要求的用户提供有偿增值服务等。"},{"i":27,"n":"第二十七条","txt":"电能质量信息实行统一管理、分级负责。国家能源局负责全国电能质量信息的管理工作。地方各级电力管理部门负责本行政区域内电能质量信息的管理工作。 根据工作需要，国家能源局可以委托行业协会、科研单位及技术咨询机构等协助开展电能质量信息统计、指标评价等工作。"},{"i":28,"n":"第二十八条","txt":"电网企业等相关企业应当按规定准确、及时、完整地向国家能源局、地方各级电力管理部门报送电能质量信息。 电能质量信息报送内容和程序由国家能源局另行规定。"},{"i":29,"n":"第二十九条","txt":"国家能源局及其派出机构、地方各级电力管理部门应当根据职责及时受理发电企业、电网企业、电力用户对电能质量问题的诉求，必要时可开展监督检查。 根据工作需要，国家能源局及其派出机构、地方各级电力管理部门可以委托具有相关资质的机构协助开展电能质量问题分析、检验测试等工作。"},{"i":30,"n":"第三十条","txt":"国家能源局及其派出机构、地方各级电力管理部门可对发电企业、电网企业及电力用户开展电能质量监督检查, 受监督检查企业及其工作人员应予以配合： （一）进入受监督检查企业进行检查; （二）询问受监督检查企业的工作人员,要求其对有关检查事项做出说明; （三）查阅、复制与检查事项有关的文件、资料和电子数据; （四）调取、分析受监督检查企业的有关电能质量信息。 监督检查时可以邀请电能质量专业相关专家参加并提供专业意见建议。对监督检查中发现的违法违规行为,国家能源局及其派出机构、地方各级电力管理部门有权当场予以纠正或责令限期改正。对不采取措施或者采取措施不力的, 依法依规纳入不良信用记录。"},{"i":31,"n":"第三十一条","txt":"本办法下列用语的含义： （一）电能质量，是指电力系统指定点处的电特性，关系到供用电设备正常工作（或运行）的电压、电流、频率的各种指标偏离基准技术参数的程度。电能质量指标包括电力系统频率偏差、供电电压偏差、谐波（间谐波）、三相电压不平衡、电压波动与闪变、电压暂升/暂降与短时中断等，各项电能质量指标应符合下列国家标准： 1.《电能质量 电力系统频率偏差》(GB/T 15945)； 2.《电能质量 供电电压偏差》(GB/T 12325)； 3.《电能质量 公用电网谐波》(GB/T 14549)； 4.《电能质量 公用电网间谐波》(GB/T 24337)； 5.《电能质量 三相电压不平衡度》(GB/T 15543)； 6.《电能质量 电压波动和闪变》(GB/T 12326)； 7.《电能质量 电压暂降与短时中断》（GB/T 30137）； 8.其他电能质量相关国家标准。 （二）干扰源，是指接入"},{"i":32,"n":"第三十二条","txt":"本办法由国家发展改革委、国家能源局负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2024年4月1日起施行。原电力工业部发布的《电网电能质量技术监督管理规定》（电综〔1998〕第211号）同时废止。"}],"shiyoutianranqijichusheshiguihuajiansheyuyunyinggu8eaf14":[{"i":1,"n":"第一条","txt":"为规范石油天然气基础设施规划建设与运营管理，提高服务质量和效率，维护市场相关方合法权益和社会公共利益，保障石油天然气安全稳定供应，促进行业高质量发展，根据《中华人民共和国能源法》《中华人民共和国石油天然气管道保护法》，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国领域和管辖的其他海域石油天然气基础设施规划建设与运营管理活动，适用本办法。 城镇等燃气设施、国防及军事设施、石油储备设施的规划建设与运营按相关法律法规规定执行。"},{"i":3,"n":"第三条","txt":"石油天然气基础设施规划建设与运营管理遵循以下原则： （一）落实总体国家安全观，保障国家能源安全，维护公共安全和生态安全，服务经济民生和国防需求。 （二）统筹规划、经济合理，便捷接入、高效使用，优化运营、科学监管。 （三）服务石油天然气行业市场体系建设，推动绿色低碳和可持续发展。"},{"i":4,"n":"第四条","txt":"国务院能源主管部门主管全国石油天然气基础设施规划建设与运营管理工作。 省级人民政府能源主管部门负责本行政区域石油天然气基础设施规划建设与运营相关管理工作。"},{"i":5,"n":"第五条","txt":"鼓励和支持石油天然气基础设施基础性、关键性和前沿性重大技术、装备及相关新材料的研究、开发、示范、推广应用和产业化发展。支持人工智能等先进信息技术应用，推动基础设施建设和运营的数字化、智能化发展。建立健全石油天然气基础设施领域标准体系，保障供应安全和绿色低碳转型，促进新技术、新产业、新业态发展。 完善产业、金融、政府采购等支持政策，鼓励、引导社会资本参与基础设施技术创新，激发各类经营主体参与石油天然气基础设施投资建设的积极性。"},{"i":6,"n":"第六条","txt":"国务院能源主管部门依据国民经济和社会发展规划及全国综合能源规划，衔接国土空间规划、相关区域规划，结合石油天然气资源禀赋和生产消费情况、生态环境保护要求等，组织编制全国石油天然气基础设施发展规划或在全国石油天然气规划中明确全国石油天然气基础设施发展布局。 省级人民政府能源主管部门依据全国综合能源规划、全国石油天然气规划、相关区域能源规划并结合本行政区域实际情况，在组织编制本行政区域能源规划或石油天然气规划中明确本行政区域石油天然气基础设施发展布局，并与国土空间规划等相关规划衔接。"},{"i":7,"n":"第七条","txt":"国务院能源主管部门协调跨省（自治区、直辖市）的石油天然气干线管网等重大油气基础设施规划建设。加强各级国土空间规划与全国综合能源规划、全国石油天然气规划衔接，预留石油天然气基础设施建设用地、用海。 新建石油天然气跨境、跨省（自治区、直辖市）管道和新增跨境、跨省（自治区、直辖市）连通项目，应纳入全国石油天然气基础设施规划布局后组织实施，各级地方人民政府能源主管部门不得自行分段规划及审批。"},{"i":8,"n":"第八条","txt":"石油天然气基础设施规划，应当遵循行业发展规律，坚持统筹兼顾，强化科学论证。组织编制石油天然气基础设施规划的部门应当征求有关部门、相关企业和行业组织以及有关专家等方面的意见。 石油天然气基础设施规划应当明确规划期内发展目标、主要任务、区域布局、重点项目、保障措施等内容。"},{"i":9,"n":"第九条","txt":"石油天然气基础设施规划按照规定的权限和程序报经批准后实施。经批准的石油天然气基础设施规划应当按照政府信息公开等相关规定予以公布。 各级石油天然气基础设施规划实施过程中，规划编制部门应加强跟踪监测，就规划实施情况开展评估。根据评估结果确需对规划进行调整的，应当报经原规划批准机关同意。"},{"i":10,"n":"第十条","txt":"承担国家石油天然气干线管道建设主体责任的企业，应当落实全国综合能源规划、石油天然气规划等相关规划，优化决策程序，落实项目投资和建设条件，加快石油天然气干线管道投资建设。 支持各类社会资本特别是民间资本按照市场化原则参股石油天然气管道项目。鼓励符合资质、融资、信用等条件的社会资本特别是民间资本参与石油天然气储备库、液化天然气接收站等基础设施投资建设。"},{"i":11,"n":"第十一条","txt":"石油天然气基础设施项目按照投资管理体制相关规定，依法分别实行审批、核准或备案管理。省级能源主管部门审批或者核准的石油天然气基础设施项目，应当抄报国务院能源主管部门。在役石油天然气管道（省、自治区、直辖市）局部迁建改造（不跨省）等项目规划建设，按本行政区域企业投资等有关规定管理。 已审批或核准的建设项目，项目建设期存在变更建设地点或者拟对投资规模、建设规模、建设内容等做出较大变化需要变更申请情形的，项目申报单位应当按照规定的程序向原审批或核准部门提出变更申请。已备案项目的项目法人发生变化、项目建设地点、规模、内容发生重大变更或者放弃项目建设的，企业应当及时告知备案机关并修改相关信息。"},{"i":12,"n":"第十二条","txt":"除涉及国家秘密的项目外，项目单位应当通过全国投资项目在线审批监管平台及时、如实报送项目开工建设、建设进度、竣工等基本信息。 石油天然气基础设施项目规划、审批、建设过程中，应按照相关法律法规要求开展相关影响评价，采取严格的生态环保措施，预防或减少生态破坏、环境污染或温室气体排放。生态环境保护工程、水土保持设施工程、安全设施工程、治安反恐防范工程等应当与石油天然气基础设施工程项目同时设计、同时建设、同时验收、同时投入使用。 石油天然气基础设施与铁路、公路、航道、港口等相遇相交或交叉并行的，应符合相关法律规定、国家标准、行业标准及规范要求。 石油天然气基础设施项目建成后应当按照法律、法规和有关规定进行竣工验收。"},{"i":13,"n":"第十三条","txt":"国家建立完善石油天然气基础设施接入和使用机制，各类石油天然气基础设施运营企业均应支持符合政府规划、符合安全运行条件的设施接入（含管道上下载开口等）和使用。石油天然气输送管网设施运营企业还应制定企业实施细则，明确公平接入和使用的申请条件、工作程序和商务条款等。 石油天然气田开发项目（含页岩油气等非常规石油天然气）、煤制油气项目、大型炼化基地以及石油储备库、地下储气库、进口液化天然气接收储运设施等大型石油天然气储备设施，应当接入国家石油天然气干线管网。"},{"i":14,"n":"第十四条","txt":"国家推进石油天然气基础设施互联互通，提高管道网络化水平，提升设施运营安全和供应能力。石油天然气发展规划在编制过程中应当考虑基础设施互联互通，基础设施项目审批、核准的批复文件中应对必要的互联互通方案提出明确要求。互联互通项目可作为单独项目投资建设，也可纳入相互连接的油气基础设施项目。 国务院能源主管部门加强对油气干线管道互联互通及油气基础设施跨境、跨省（自治区、直辖市）联通工作的指导和协调。加强城乡石油天然气基础设施建设统筹，支持城乡石油天然气基础设施互联互通。"},{"i":15,"n":"第十五条","txt":"承担石油天然气干线管道建设运营主体责任的企业及其所属企业不得参与石油天然气勘探开发、进出口、生产销售（不含购买自耗自用和铺底石油天然气）竞争性业务，保障设施公平接入和使用；除确有必要保留的维抢修业务外，不得从事石油天然气管输领域设备制造（定向承担国家重大科技攻关任务除外）、施工建造辅助性业务。从事石油天然气勘探开发、进出口、生产销售等竞争性业务的企业及其所属企业，不得从事石油天然气干线管道投资与运营业务（项目勘查设计施工除外）。"},{"i":16,"n":"第十六条","txt":"各省（自治区、直辖市）人民政府应推进所辖行政区域管网管输和销售分开，管输业务实行财务独立核算，条件成熟时实现产权独立。政府核定管输价格，确保设施第三方准入和使用，支持上游企业和下游城燃、工业等用户间直购直销。积极引导和推进省级管网以市场化方式融入国家管网。"},{"i":17,"n":"第十七条","txt":"石油天然气基础设施运营企业向服务用户提供服务，应与服务用户签订服务合同，按合同约定执行。合同双方不得擅自拒绝、中断、减少或限制设施使用。 服务用户应当根据国家法规政策及合同约定，按时准确向石油天然气输送管网设施运营企业提交年度、月度等需求计划以及日指定计划。石油天然气购销合同主体有义务按照相关合同约定和日指定计划，保障管网等设施进出资源量平衡和设施安全平稳运行。 石油天然气基础设施运营企业应当严格遵守价格主管部门有关价格政策规定，不得违规收取相关费用。 石油天然气输送管网设施使用受限或能力不足，无法满足第三方使用需求的，省级以上人民政府能源主管部门应协调推进基础设施扩容改造或新建工作。"},{"i":18,"n":"第十八条","txt":"石油天然气输送管网设施运营企业依据各自服务合同约定独立自主运营。支持和鼓励石油天然气输送管网设施运营企业依托服务平台开展管网联合运营及调度合作，压缩管输层级，提高运营效率。"},{"i":19,"n":"第十九条","txt":"进出石油天然气基础设施资源量日偏差和累计偏差限值应符合国家政策规定和合同约定。超出偏差限值且基础设施服务用户未主动采取措施或不能自主平衡时，石油天然气基础设施运营企业可采取措施对相关设施进出资源量予以限制，或采取不以盈利为目的的主动平衡措施，保障设施安全运营。 石油天然气基础设施运营企业针对服务合同履约严重失信方，可按合同约定在一定期限内限制其获取服务。"},{"i":20,"n":"第二十条","txt":"建立健全石油天然气质量、计量检测制度和标准。接入石油天然气基础设施的原油、成品油、天然气等应符合国家质量标准和服务合同关于热值、组分等相关约定。石油天然气不符合国家质量标准和服务合同约定的，石油天然气输送管网设施运营企业可以拒绝提供服务。 完善和规范成品油管道入网（上载）和下载标准。加快推进成品油管道顺序输送，扩大管输服务和覆盖用户范围。在规范成品油流通和市场运营秩序、健全油品质量标准和质量控制基础上，逐步推广成品油混合去标签化输送。"},{"i":21,"n":"第二十一条","txt":"提供公共服务的石油天然气基础设施，相关企业应当完善公平开放规则，完善服务用户准入、获得服务的条件和程序等使用机制和规则，按照规定向服务用户公开相关设施情况、服务能力、运行情况等信息或提供相应查询服务，向符合条件的企业等经营主体公平、无歧视开放并提供石油天然气输送等服务。 鼓励石油天然气输送管网设施运营企业集中受理长期及固定时段服务能力申请。按照双方合同约定，基础设施服务用户现有服务合同已预定的能力，可在服务合同到期前申请延续使用。"},{"i":22,"n":"第二十二条","txt":"石油天然气输送管网设施运营企业应当提高基础设施运行安全水平，保障输送管网等基础设施系统运行安全。 在发生管输事故等供应中断应急状况时，按照应急预案和各级人民政府有关要求，优先保障与居民生活密切相关的民生用油用气供应安全可靠。"},{"i":23,"n":"第二十三条","txt":"石油天然气基础设施不符合安全运营标准、环境管理要求或存在其他安全风险隐患的，石油天然气基础设施运营企业应及时整改消除隐患，不得以此为由擅自停止运营。 石油天然气基础设施因维检修、更新改造等原因需要计划性短期停止运营的，石油天然气基础设施运营企业与基础设施服务用户应在服务合同中约定必要的维检修周期和执行机制，协商落实维检修时间窗口。 经石油天然气安全生产、管道保护、特种设备、生态环境等主管部门认定确不具备整改和消除隐患条件的，或被有关部门责令停止运营的，应按其规定和要求执行。"},{"i":24,"n":"第二十四条","txt":"石油天然气基础设施停止运营、封存、报废的，按照国家有关规定处理，石油天然气输送管网设施运营企业应保障全过程符合生态环境管理等要求，应当采取必要的安全防护措施，并依法依规向县级以上人民政府能源主管部门和其他有关部门报备。 石油天然气基础设施需要永久性停止运营的，石油天然气输送管网设施运营企业应提前一年告知设施相关使用方，双方应协商一致；仍有相关服务需求的还应共同落实安全可行、经济合理的替代方案，保障石油天然气产供储销体系平稳运行。发生争议的，可以由省级以上人民政府能源主管部门进行协调。"},{"i":25,"n":"第二十五条","txt":"按照统筹规划、因地制宜、集约布局、多元互补的原则，加快天然气储备设施建设。建立健全天然气储备体系，科学合理确定天然气储备的种类、规模和方式。 储气设施建设运营应与天然气产业发展布局衔接，储气设施注采、接卸、气化、外输等设施应同步规划、同步建设、同步投产，各级地方人民政府能源主管部门和相关企业应为设施接入和使用提供便利。"},{"i":26,"n":"第二十六条","txt":"供气企业应形成不低于其年供气量5%的储气能力。承担国家石油天然气干线管道建设主体责任的企业应形成不低于国内主要供气企业合计年供气量5%的储气能力。县级以上地方人民政府要建立健全燃气应急储备制度，形成不低于保障本行政区域5天日均消费量的储气能力，城镇燃气企业要形成不低于其年用气量5%的储气能力。"},{"i":27,"n":"第二十七条","txt":"建立完善储气调峰市场机制，发挥天然气储备季节性、周期性调节，以及突发等极端情形下尖峰和应急保供作用。各方可通过自建合建租赁储气设施或者购买储气服务等手段履行储气责任。储气服务（储存、注采等）价格、储气设施天然气购进价格和对外销售价格由市场竞争形成，合理传导储气服务成本。 依托储气设施灵活调节能力、市场化供需调节手段、发展可中断用户等方式，有序探索管网气量市场化平衡机制。石油天然气输送管网设施运营企业在参与相关市场建设中不得买卖或变相买卖天然气，未经同意不得动用其受政府委托管理的应急调节能力。 发挥天然气储备的战略保障、宏观调控和应对急需等功能。在出现天然气供应严重短缺、供应中断等应急状态时，天然气储备应服从政府应急保障安排。"},{"i":28,"n":"第二十八条","txt":"省级以上人民政府能源主管部门，加强对有关石油天然气基础设施规划建设、接入使用等工作的监督检查，及时查处违法违规行为。对能源主管部门依法实施的监督检查，被检查单位及其有关人员应当予以配合，不得拒绝、阻碍。"},{"i":29,"n":"第二十九条","txt":"各级能源主管部门、各类经营企业不得限制符合政府规划和安全运行要求的设施接入和使用，不得增加或变相增加前置条件或提出不合理要求。因石油天然气基础设施的接入、使用发生的争议，可以由省级以上人民政府能源主管部门进行协调，协调不成的，当事人可以向人民法院提起诉讼；当事人也可以直接向人民法院提起诉讼。 跨境和跨省（自治区、直辖市）的石油天然气干线管道设施、进口液化天然气接收储运设施、地下储气库接入和使用发生争议的，由国务院能源主管部门负责协调；其余设施接入、使用发生争议的，由省级人民政府能源主管部门协调，必要时国务院能源主管部门予以指导。"},{"i":30,"n":"第三十条","txt":"国务院能源主管部门主管全国油气管网设施公平开放监管工作，建立健全油气管网设施公平开放监管工作机制，健全违反公平开放事项的投诉、举报、受理及处置程序，协调解决油气管网设施公平开放重大问题，组织并指导派出机构开展管网设施公平开放相关监管工作。 县级以上地方人民政府能源主管部门按照职责分工，负责本行政区域内油气管网设施公平开放相关工作。"},{"i":31,"n":"第三十一条","txt":"国家加强石油天然气基础设施建设和保护。任何单位或者个人不得从事危及石油天然气基础设施安全的活动。国务院能源主管部门主管全国石油天然气管道保护工作。"},{"i":32,"n":"第三十二条","txt":"国务院能源主管部门加强全国石油天然气基础设施规划建设与运营数据信息管理和利用。经营企业、行业协会等有关单位应当按照规定向国务院能源主管部门报送相关信息。"},{"i":33,"n":"第三十三条","txt":"各级能源主管部门及其工作人员对监督检查、信息报送等过程中知悉的国家秘密、商业秘密、个人隐私和个人信息依法负有保密义务，加强石油天然气基础设施汇集类信息保密管理。"},{"i":34,"n":"第三十四条","txt":"国务院能源主管部门做好石油天然气基础设施规划建设与运营所涉各类经营主体的信用记录，依法依规实施守信激励和失信约束。"},{"i":35,"n":"第三十五条","txt":"任何单位和个人对违反本办法的行为，有权向县级以上人民政府能源主管部门举报。接到举报的部门应当及时依法处理。"},{"i":36,"n":"第三十六条","txt":"对违反本办法第七条规定，省级规划不服从和落实国家规划的，由国务院能源主管部门责令省级规划有关部门整改，必要时予以约谈。"},{"i":37,"n":"第三十七条","txt":"对违反本办法第十一条规定，石油天然气基础设施项目未依法履行项目审批、核准、备案相关手续的，按照《政府投资条例》《企业投资项目核准和备案管理条例》等有关法律法规处理。"},{"i":38,"n":"第三十八条","txt":"违反本办法第十五条规定，承担石油天然气干线管道建设主体责任的企业违规从事竞争性及辅助性业务的，或利用管存等应急调节能力，或以管网平衡服务为由严重扰乱市场秩序的，由国务院能源主管部门责令改正，情节严重的给予通报批评。涉嫌违法的，由相关部门依职责查处。 违反本办法第十五条规定，从事石油天然气勘探开发、进出口、生产销售等竞争性业务的企业违规从事石油天然气干线管道建设与运营业务的，由省级以上能源主管部门责令改正，情节严重的给予通报批评。涉嫌违法的，由相关部门依职责查处。"},{"i":39,"n":"第三十九条","txt":"违反本办法第十六条规定，各省（自治区、直辖市）所辖行政区域内油气管道未实行管输与销售业务分开，未实行财务独立核算并阻碍上下游用户间直购直销的，由省级以上能源主管部门责令改正，情节严重的给予通报批评。"},{"i":40,"n":"第四十条","txt":"违反本办法第十九条规定，石油天然气基础设施运营企业、服务用户已签订服务合同但拒不履约，引发供应中断或剧烈波动，严重影响市场稳定运行和供应安全的，由县级以上人民政府能源主管部门或者其他有关部门按照职责分工责令改正，依法给予行政处罚；情节严重的，对有关主管人员和直接责任人员依法给予处分。"},{"i":41,"n":"第四十一条","txt":"违反本办法第二十条规定，因原油、成品油、天然气质量不符合国家质量标准和服务合同约定，造成石油天然气基础设施运营企业经营损失的，应按合同约定赔偿；影响石油天然气基础设施安全运营，造成重大事故等严重后果或影响的，由省级以上能源主管部门责令改正，情节严重的给予通报批评。涉嫌违法的，由相关部门依职责查处。"},{"i":42,"n":"第四十二条","txt":"违反本办法第二十一条规定，石油天然气基础设施运营企业未向符合条件的企业等经营主体公平、无歧视开放并提供能源输送服务的，由省级以上人民政府能源主管部门或者其他有关部门按照职责分工责令改正，给予警告或者通报批评；拒不改正的，处相关经营主体经济损失额二倍以下的罚款；情节严重的，对有关主管人员和直接责任人员依法给予处分。"},{"i":43,"n":"第四十三条","txt":"违反本办法第二十二条、第二十三条规定，石油天然气基础设施运营企业无正当理由在运营期内擅自停止石油天然气基础设施运营，可能造成石油天然气供需失衡等严重后果或风险的，由省级以上人民政府能源主管部门按职责责令改正。造成损失的，石油天然气基础设施运营企业依法承担赔偿责任。"},{"i":44,"n":"第四十四条","txt":"县级以上人民政府能源主管部门的工作人员违反本规定，在石油天然气基础设施规划建设与运营管理中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"本办法中下列用语的含义是： （一）石油天然气基础设施：是指提供原油、成品油、天然气（含液化天然气，下同）管输、储存、接卸、气化等服务的管道、储存及其他配套和附属设施，但不包括与陆上和海上石油天然气开发备案项目整体配套的集输管道（井口集输至处理厂、净化厂的内部管道等）、井间管道、海上平台到陆上终端连接管道、石化企业厂区和机场辖区内管道、化工品管道、城镇燃气设施、加油站。其中，油气管网设施是指提供公共服务的原油、成品油、天然气（含液化天然气）管输等服务的设施。 （二）石油天然气管道：是指石油天然气基础设施中，符合《输油管道工程设计规范》（GB 50253），用于输送原油、成品油的管道；以及符合《输气管道工程设计规范》（GB 50251），用于输送天然气的管道。 （三）国家石油天然气干线管网：是指前述第二款中，输送天然气的管道设计最高工作压力大于4兆帕（MPa），输送原油或成品油的管道设计最"},{"i":46,"n":"第四十六条","txt":"本办法由国家发展改革委、国家能源局负责解释。各省（自治区、直辖市）可在本办法规定范围内结合本地实际制定相关实施细则。"},{"i":47,"n":"第四十七条","txt":"本办法自2026年1月1日起实施。《天然气基础设施建设与运营管理办法》（国家发展改革委2014年第8号令）同时废止。"}],"fenmeihuizongheliyongguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为节约资源、保护环境、发展循环经济，深入推进粉煤灰综合利用健康发展，根据《中华人民共和国循环经济促进法》、《中华人民共和国清洁生产促进法》、《中华人民共和国固体废物污染环境防治法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内粉煤灰的产生、储运、综合利用等活动,适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称粉煤灰是指：燃煤电厂以及煤矸石、煤泥资源综合利用电厂(以下称产灰单位)锅炉烟气经除尘器收集后获得的细小飞灰和炉底渣。"},{"i":4,"n":"第四条","txt":"本办法所称粉煤灰综合利用是指：从粉煤灰中进行物质提取，以粉煤灰为原料生产建材、化工、复合材料等产品，粉煤灰直接用于建筑工程、筑路、回填和农业等。"},{"i":5,"n":"第五条","txt":"国家发展改革委负责全国粉煤灰综合利用的组织协调和监督检查工作，国务院有关部门负责各自职责范围内的相关工作。 地方各级资源综合利用主管部门负责本办法的贯彻实施和本行政区域的监督、管理和协调工作，有关部门负责各自职责范围内的相关工作。 相关行业协会、社会团体组织开展粉煤灰综合利用技术培训和交流，加强行业自律。"},{"i":6,"n":"第六条","txt":"粉煤灰综合利用应遵循“谁产生、谁治理，谁利用、谁受益”的原则，减少粉煤灰堆存，不断扩大粉煤灰综合利用规模，提高技术水平和产品附加值。"},{"i":7,"n":"第七条","txt":"国家发展改革委会同国务院有关部门组织编制粉煤灰综合利用实施方案。各省级资源综合利用主管部门会同有关部门编制本行政区域的粉煤灰综合利用实施方案，并纳入地方经济社会发展规划，报国家发展改革委备案。"},{"i":8,"n":"第八条","txt":"国家发展改革委会同科技部、工业和信息化部、财政部、国土资源部、环境保护部、住房城乡建设部、交通运输部、税务总局、质检总局等部门负责制订完善粉煤灰综合利用的相关政策、技术、产品导向目录和标准，组织开展粉煤灰清洁高效利用关键技术、设备的研发与产业化示范，推动粉煤灰在建筑、建材、化工等更多领域的广泛应用。"},{"i":9,"n":"第九条","txt":"产灰单位须按照《中华人民共和国固体废物污染环境防治法》和环境保护部门有关规定申报登记粉煤灰产生、贮存、流向、利用和处置等情况，同时报同级资源综合利用主管部门备案。 地市级环境保护部门、资源综合利用主管部门负责统计和掌握本地区粉煤灰产生、贮存、流向、利用、处置等数据信息。各省(区、市)环境保护部门和资源综合利用主管部门应于每年6月底前，将本地区上年度统计数据报环境保护部和国家发展改革委。"},{"i":10,"n":"第十条","txt":"新建和扩建燃煤电厂,项目可行性研究报告和项目申请报告中须提出粉煤灰综合利用方案，明确粉煤灰综合利用途径和处置方式。 综合利用方案中涉及粉煤灰存储、装运的设施和装备以及产灰单位自行建设粉煤灰综合利用工程的要与主体工程同时设计、同时施工、同时建成。 综合利用方案中涉及为其他单位提供粉煤灰的，用灰单位应符合国家产业政策且具备相应的处理能力。"},{"i":11,"n":"第十一条","txt":"新建电厂应综合考虑周边粉煤灰利用能力，以及节约土地、防止环境污染，避免建设永久性粉煤灰堆场(库)，确需建设的，原则上占地规模按不超过3年储灰量设计，且粉煤灰堆场(库)选址、设计、建设及运行管理应当符合《一般工业固体废物贮存、处置场污染控制标准》(GB18599-2001)等相关要求。"},{"i":12,"n":"第十二条","txt":"产灰单位灰渣处理工艺系统应按照干湿分排、粗细分排、灰渣分排的原则进行分类收集，并配备相应储灰设施。已投运的电厂要改造、完善粉煤灰储、装、运系统，包括加工分选、磨细和灰场综合治理等设施。 产灰单位既有湿排灰堆场(库)，应制订粉煤灰综合利用专项方案和污染防治专项方案，并报所在地市级资源综合利用主管部门和环境保护部门备案。新建电厂应以便于利用为原则，不得湿排粉煤灰。 堆场(库)中的粉煤灰应按环境保护部门有关规定严格管理。"},{"i":13,"n":"第十三条","txt":"在堆场(库)提取粉煤灰，产灰单位应与用灰单位签订取灰安全及环保协议，产灰单位应对用灰单位从指定地点装运未经加工的粉煤灰(包括从湿排灰堆场(库)取灰点、电厂储装运设施中取原灰)提供装载方便，并维护灰场和生产现场的安全。"},{"i":14,"n":"第十四条","txt":"粉煤灰运输须使用专用封闭罐车，并严格遵守环境保护等有关部门规定和要求，避免二次污染。"},{"i":15,"n":"第十五条","txt":"粉煤灰建材产品和利用粉煤灰或制品建造的道路、港口、桥涵、大坝及其他建筑工程，必须符合国家或行业的有关质量标准，质量技术监督部门和工程质量管理部门应依法监督管理。"},{"i":16,"n":"第十六条","txt":"鼓励对粉煤灰进行以下高附加值和大掺量利用： (一)发展高铝粉煤灰提取氧化铝及相关产品; (二)发展技术成熟的大掺量粉煤灰新型墙体材料; (三)利用粉煤灰作为水泥混合材并在生料中替代粘土进行配料; (四)利用粉煤灰作商品混凝土掺合料等。"},{"i":17,"n":"第十七条","txt":"鼓励产灰单位对粉煤灰进行分选加工，生产的符合国家或行业标准的成品粉煤灰，可以适当收取费用，其收费标准根据加工成本和质量，由产、用灰双方商定。 鼓励产灰单位与用灰单位签订长期供应协议。"},{"i":18,"n":"第十八条","txt":"用灰单位可以按照《国家鼓励的资源综合利用认定管理办法》有关要求和程序申报资源综合利用认定。符合条件的用灰单位，可根据国家有关规定，申请享受资源综合利用相关优惠政策。"},{"i":19,"n":"第十九条","txt":"鼓励在具备条件的建筑、筑路等工程中使用符合国家或行业质量标准的粉煤灰及其制品。"},{"i":20,"n":"第二十条","txt":"对粉煤灰大掺量、高附加值关键共性技术的自主创新研究，相关部门应给予一定支持。对获得国家和地方资金支持的粉煤灰综合利用项目，所在地区科技、投资、环保等部门要对项目进展、资金使用、环境影响情况进行监督检查，并进行资源综合利用效果的后评估。"},{"i":21,"n":"第二十一条","txt":"各级资源综合利用主管部门应会同相关部门，根据本地区实际情况制定相应的鼓励和扶持措施。"},{"i":22,"n":"第二十二条","txt":"相关部门、各级地方政府对在粉煤灰综合利用工作中有突出贡献的产灰、用灰、运灰、设计、科研和管理等单位及个人按规定予以表彰和奖励。"},{"i":23,"n":"第二十三条","txt":"新建电厂兴建永久性储灰场违反第十一条规定的，由国土资源等部门监督其限期整改。对环境造成污染的，由环境保护部门依法予以处罚。"},{"i":24,"n":"第二十四条","txt":"任何单位及个人不得在灰场(库)非指定区域擅自取灰，凡擅自取灰影响灰场(库)安全，造成财产损失或引发安全事故的，有关部门要依法追究相关责任。"},{"i":25,"n":"第二十五条","txt":"违反本办法第十四条、第十五条规定的，由环境保护、质量技术监督等部门根据情节轻重及有关规定予以行政处罚，资源综合利用主管部门监督整改。"},{"i":26,"n":"第二十六条","txt":"有关部门依照本办法及相关规定对单位、个人处以罚款和没收财物时，应遵守《中华人民共和国行政处罚法》相关规定，同时必须使用财政部门统一制发的罚没票据。"},{"i":27,"n":"第二十七条","txt":"各省级资源综合利用主管部门应根据本办法，并结合当地实际情况，制定实施细则。"},{"i":28,"n":"第二十八条","txt":"本办法自2013年3月1日起施行。原国家经贸委等六部门联合发布的《粉煤灰综合利用管理办法》(国经贸节〔1994〕14号)同时废止。"}],"fenmeihuizongheliyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为节约资源、保护环境、发展循环经济，深入推进粉煤灰综合利用健康发展，根据《中华人民共和国循环经济促进法》、《中华人民共和国清洁生产促进法》、《中华人民共和国固体废物污染环境防治法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内粉煤灰的产生、储运、综合利用等活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称粉煤灰是指：燃煤电厂以及煤矸石、煤泥资源综合利用电厂（以下称产灰单位）锅炉烟气经除尘器收集后获得的细小飞灰和炉底渣。"},{"i":4,"n":"第四条","txt":"本办法所称粉煤灰综合利用是指：从粉煤灰中进行物质提取，以粉煤灰为原料生产建材、化工、复合材料等产品，粉煤灰直接用于建筑工程、筑路、回填和农业等。"},{"i":5,"n":"第五条","txt":"国家发展改革委负责全国粉煤灰综合利用的组织协调和监督检查工作，国务院有关部门 负责各自职责范围内的相关工作。 地方各级资源综合利用主管部门负责本办法的贯彻实施和本行政区域的监督、管理和协调工作，有关部门负责各自职责范围内的相关工作。 相关行业协会、社会团体组织开展粉煤灰综合利用技术培训和交流，加强行业自律。"},{"i":6,"n":"第六条","txt":"粉煤灰综合利用应遵循 “谁产生、谁治理，谁利用、谁受益”的原则，减少粉煤灰堆存，不断扩大粉煤灰综合利用规模，提高技术水平和产品附加值。"},{"i":7,"n":"第七条","txt":"国家发展改革委会同国务院有关部门组织编制粉煤灰综合利用实施方案。各省级资源综合利用主管部门会同有关部门编制本行政区域的粉煤灰综合利用实施方案，并纳入地方经济社会发展规划，报国家发展改革委备案。"},{"i":8,"n":"第八条","txt":"国家发展改革委会同科技部、工业和信息化部、财政部、国土资源部、环境保护部、住房城乡建设部、交通运输部、税务总局、质检总局等部门负责制订完善粉煤灰综合利用的相关政策、技术、产品导向目录和标准，组织开展粉煤灰清洁高效利用关键技术、设备的研发与产业化示范，推动粉煤灰在建筑、建材、化工等更多领域的广泛应用。"},{"i":9,"n":"第九条","txt":"产灰单位须按照《中华人民共和国固体废物污染环境防治法》和环境保护部门有关规定申报登记粉煤灰产生、贮存、流向、利用和处置等情况，同时报同级资源综合利用主管部门备案。 地市级环境保护部门、资源综合利用主管部门负责统计和掌握本地区粉煤灰产生、贮存、流向、利用、处置等数据信息。各省（区、市）环境保护部门和资源综合利用主管部门应于每年6月底前，将本地区上年度统计数据报环境保护部和国家发展改革委。"},{"i":10,"n":"第十条","txt":"新建和扩建燃煤电厂，项目可行性研究报告和项目申请报告中须提出粉煤灰综合利用方案，明确粉煤灰综合利用途径和处置方式。 综合利用方案中涉及粉煤灰存储、装运的设施和装备以及产灰单位自行建设粉煤灰综合利用工程的要与主体工程同时设计、同时施工、同时建成。 综合利用方案中涉及为其他单位提供粉煤灰的，用灰单位应符合国家产业政策且具备相应的处理能力。"},{"i":11,"n":"第十一条","txt":"新建电厂应综合考虑周边粉煤灰利用能力，以及节约土地、防止环境污染，避免建设永久性粉煤灰堆场（库），确需建设的，原则上占地规模按不超过3年储灰量设计，且粉煤灰堆场（库）选址、设计、建设及运行管理应当符合《一般工业固体废物贮存、处置场污染控制标准》（GB18599-2001）等相关要求。"},{"i":12,"n":"第十二条","txt":"产灰单位灰渣处理工艺系统应按照干湿分排、粗细分排、灰渣分排的原则进行分类收集，并配备相应储灰设施。已投运的电厂要改造、完善粉煤灰储、装、运系统，包括加工分选、磨细和灰场综合治理等设施。 产灰单位既有湿排灰堆场（库），应制订粉煤灰综合利用专项方案和污染防治专项方案，并报所在地市级资源综合利用主管部门和环境保护部门备案。新建电厂应以便于利用为原则，不得湿排粉煤灰。 堆场（库）中的粉煤灰应按环境保护部门有关规定严格管理。"},{"i":13,"n":"第十三条","txt":"在堆场（库）提取粉煤灰，产灰单位应与用灰单位签订取灰安全及环保协议，产灰单位应对用灰单位从指定地点装运未经加工的粉煤灰（包括从湿排灰堆场（库）取灰点、电厂储装运设施中取原灰）提供装载方便，并维护灰场和生产现场的安全。"},{"i":14,"n":"第十四条","txt":"粉煤灰运输须使用专用封闭罐车，并严格遵守环境保护等有关部门规定和要求，避免二次污染。"},{"i":15,"n":"第十五条","txt":"粉煤灰建材产品和利用粉煤灰或制品建造的道路、港口、桥涵、大坝及其他建筑工程，必须符合国家或行业的有关质量标准，质量技术监督部门和工程质量管理部门应依法监督管理。"},{"i":16,"n":"第十六条","txt":"鼓励对粉煤灰进行以下高附加值和大掺量利用： （一）发展高铝粉煤灰提取氧化铝及相关产品； （二）发展技术成熟的大掺量粉煤灰新型墙体材料； （三）利用粉煤灰作为水泥混合材并在生料中替代粘土进行配料； （四）利用粉煤灰作商品混凝土掺合料等。"},{"i":17,"n":"第十七条","txt":"鼓励产灰单位对粉煤灰进行分选加工，生产的符合国家或行业标准的成品粉煤灰，可以适当收取费用，其收费标准根据加工成本和质量，由产、用灰双方商定。 鼓励产灰单位与用灰单位签订长期供应协议。"},{"i":18,"n":"第十八条","txt":"用灰单位可以按照《国家鼓励的资源综合利用认定管理办法》有关要求和程序申报资源综合利用认定。符合条件的用灰单位，可根据国家有关规定，申请享受资源综合利用相关优惠政策。"},{"i":19,"n":"第十九条","txt":"鼓励在具备条件的建筑、筑路等工程中使用符合国家或行业质量标准的粉煤灰及其制品。"},{"i":20,"n":"第二十条","txt":"对粉煤灰大掺量、高附加值关键共性技术的自主创新研究，相关部门应给予一定支持。对获得国家和地方资金支持的粉煤灰综合利用项目，所在地区科技、投资、环保等部门要对项目进展、资金使用、环境影响情况进行监督检查，并进行资源综合利用效果的后评估。"},{"i":21,"n":"第二十一条","txt":"各级资源综合利用主管部门应会同相关部门，根据本地区实际情况制定相应的鼓励和扶持措施。"},{"i":22,"n":"第二十二条","txt":"相关部门、各级地方政府对在粉煤灰综合利用工作中有突出贡献的产灰、用灰、运灰、设计、科研和管理等单位及个人按规定予以表彰和奖励。"},{"i":23,"n":"第二十三条","txt":"新建电厂兴建永久性储灰场违反第十一条规定的，由国土资源等部门监督其限期整改。对环境造成污染的，由环境保护部门依法予以处罚。"},{"i":24,"n":"第二十四条","txt":"任何单位及个人不得在灰场（库）非指定区域擅自取灰，凡擅自取灰影响灰场（库）安全，造成财产损失或引发安全事故的，有关部门要依法追究相关责任。"},{"i":25,"n":"第二十五条","txt":"违反本办法第十四条、第十五条规定的，由环境保护、质量技术监督等部门根据情节轻重及有关规定予以行政处罚，资源综合利用主管部门监督整改。"},{"i":26,"n":"第二十六条","txt":"有关部门依照本办法及相关规定对单位、个人处以罚款和没收财物时，应遵守《中华人民共和国行政处罚法》相关规定，同时必须使用财政部门统一制发的罚没票据。"},{"i":27,"n":"第二十七条","txt":"各省级资源综合利用主管部门应根据本办法，并结合当地实际情况，制定实施细则。"},{"i":28,"n":"第二十八条","txt":"本办法自 2013年3月1日起施行。原国家经贸委等六部门联合发布的《粉煤灰综合利用管理办法》（国经贸节[1994]14号）同时废止。"}],"liangyoucangchuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范粮油仓储单位的粮油仓储活动，维护粮食流通秩序，保障国家粮食安全，根据《粮食流通管理条例》、《中央储备粮管理条例》和相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的粮油仓储单位从事粮油仓储活动，适用本办法。"},{"i":3,"n":"第三条","txt":"粮油仓储单位必须遵守国家法律、法规和相关管理规定，执行国家和地方粮食流通政策和粮食应急预案，贯彻国家和地方制定的仓储管理制度和标准，接受粮食行政管理部门的业务指导，配合粮食行政管理部门依法开展监督检查。"},{"i":4,"n":"第四条","txt":"粮油仓储单位应当建立健全粮油仓储管理制度，积极应用先进适用的粮油储藏技术，延缓粮油品质劣变，降低粮油损失损耗，防止粮油污染，确保库存粮油数量真实、质量良好、储存安全。"},{"i":5,"n":"第五条","txt":"国家粮食行政管理部门负责全国粮油仓储监督管理工作，制定管理制度和标准，组织储粮安全检查工作。县级以上地方人民政府粮食行政管理部门负责本行政区域的粮油仓储监督管理工作。"},{"i":6,"n":"第六条","txt":"粮油仓储单位应当自设立或者开始从事粮油仓储活动之日起30个工作日内，向所在地粮食行政管理部门备案。备案应当包括单位名称、地址、法定代表人、主要仓储业务类型、仓(罐)容规模等内容。具体备案管理办法由省、自治区、直辖市人民政府粮食行政管理部门制定。"},{"i":7,"n":"第七条","txt":"粮油仓储单位应当具备以下条件： (一)拥有固定经营场地，并符合本办法有关污染源、危险源安全距离的规定; (二)拥有与从事粮油仓储活动相适应的设施设备，并符合粮油储藏技术规范的要求; (三)拥有相应的专业技术管理人员。"},{"i":8,"n":"第八条","txt":"未经国家粮食行政管理部门批准，粮油仓储单位名称中不得使用“国家储备粮”和“中央储备粮”字样。"},{"i":9,"n":"第九条","txt":"粮油仓储单位应当按照国家粮油质量标准对入库粮油进行检验，建立粮油质量档案。成品粮油质量档案还应包括生产企业出具的质量检验报告、生产日期、保质期限等内容。"},{"i":10,"n":"第十条","txt":"粮油仓储单位应当及时对入库粮油进行整理，使其达到储存安全的要求，并按照不同品种、性质、生产年份、等级、安全水分、食用和非食用等进行分类存放。粮油入库(仓)应当准确计量，并制作计量凭证。"},{"i":11,"n":"第十一条","txt":"粮油仓储单位应当按货位及时制作“库存粮油货位卡”，准确记录粮油的品种、数量、产地、生产年份、粮权所有人、粮食商品属性、等级、水分、杂质等信息，并将卡片置于货位的明显位置。"},{"i":12,"n":"第十二条","txt":"粮油仓储单位应当在粮油出库前按规定检验出库粮油质量。粮油出库应当准确计量，并制作计量凭证，做好出库记录。"},{"i":13,"n":"第十三条","txt":"出库粮油包装物和运输工具不得对粮油造成污染。未经处理的严重虫粮、危险虫粮不得出库。可能存在发热危险的粮油不得长途运输。"},{"i":14,"n":"第十四条","txt":"粮油仓储单位应当及时清除仓房、工作塔等仓储设施内的粉尘，按规定配置防粉尘设备，防止发生粉尘爆炸事故。禁止人员进入正在作业的烘干塔、立筒仓、浅圆仓等设施。"},{"i":15,"n":"第十五条","txt":"粮油仓储单位负责人对全部库存粮油的数量真实、质量良好、储存安全负责。 粮油保管员、粮油质量检验员应当掌握必要的专业知识和职业技能，具备相应的职业资格。"},{"i":16,"n":"第十六条","txt":"粮油储存区应当保持清洁，并与办公区、生活区进行有效隔离。在粮油储存区内开展的活动和存放的物品不得对粮油造成污染或者对粮油储存安全构成威胁。"},{"i":17,"n":"第十七条","txt":"粮油仓储单位应当对仓房(油罐)编排号码，配备必要的仓储设备，建立健全设备使用、保养、维修、报废等制度。"},{"i":18,"n":"第十八条","txt":"粮油仓储单位应当按照仓房(油罐)的设计容量和要求储存粮油，执行《粮油储藏技术规范》等技术标准，建立粮油仓储管理过程记录文件。"},{"i":19,"n":"第十九条","txt":"粮油仓储单位仓储能力不足时，应当通过代储、租赁等方式，合理利用其他单位的现有粮油仓储设施，扩大仓储能力。粮油仓储单位应当与承储或者出租的单位签订规范的代储或者租赁合同，明确双方的权利义务。 现有仓储设施不足，确有必要露天储存粮油的，应当具备以下条件： (一)打囤做垛应当确保结构安全，规格一致; (二)囤垛应当满足防水、防潮、防火、防风、防虫鼠雀害的要求，并采取测温、通风等必要的仓储措施; (三)用于堆放粮油的地坪和打囤做垛的器材不得对粮油造成污染。"},{"i":20,"n":"第二十条","txt":"在常规储存条件下，粮油正常储存年限一般为小麦5年，稻谷和玉米3年，食用油脂和豆类2年。"},{"i":21,"n":"第二十一条","txt":"粮油仓储单位应当按照本办法有关粮油储存损耗处置方法的规定处置粮油储存损耗。国家对政策性粮油储存损耗的处置方法另有规定的，从其规定。"},{"i":22,"n":"第二十二条","txt":"储存粮油出库数量多于入库数量的溢余，不得冲抵其他货位或批次粮油的损耗和损失。"},{"i":23,"n":"第二十三条","txt":"粮油仓储单位应当设立粮油保管账、统计账、会计账，真实、完整地反映库存粮油和资金占用情况，并按有关规定妥善保管。库存粮油情况发生变化的，粮油仓储单位应当在5个工作日内更新库存粮油货位卡和有关帐目，确保账账相符、账实相符。"},{"i":24,"n":"第二十四条","txt":"粮油仓储单位应当建立安全生产检查制度，定期对生产状况进行检查评估，及时消除安全隐患。"},{"i":25,"n":"第二十五条","txt":"储粮化学药剂应当存放在专用的药品库内，实行双人双锁管理，并对药剂和包装物领用及回收进行登记。 进行熏蒸作业的，应当制订熏蒸方案，并报当地粮食行政管理部门备案。熏蒸作业中，粮油仓储单位应当在作业场地周围设立警示牌和警戒线，禁止无关人员进入熏蒸作业区。"},{"i":26,"n":"第二十六条","txt":"库存粮油发生降等、损失、超耗等储存事故的，粮油仓储单位应当及时进行处置，避免损失扩大。属于较大、重大或者特大储存事故的，应当立即向所在地粮食行政管理部门报告。属于特大储存事故的，所在地粮食行政管理部门应当在接到事故报告24小时内，上报国家粮食行政管理部门。 粮油储存事故按照以下标准划分： (一)一次事故造成10吨以下粮食或2吨以下油脂损失的为一般储存事故; (二)一次事故造成10吨以上100吨以下粮食或2吨以上20吨以下油脂损失的为较大储存事故; (三)一次事故造成100吨以上1000吨以下粮食或20吨以上200吨以下油脂损失的为重大储存事故; (四)一次事故造成1000吨以上粮食或200吨以上油脂损失的为特别重大储存事故。"},{"i":27,"n":"第二十七条","txt":"发生安全生产事故的，粮油仓储单位应当依法及时进行处理，并立即向所在地粮食行政管理部门报告。"},{"i":28,"n":"第二十八条","txt":"粮油仓储单位违反本办法第六条规定，未在规定时间向粮食行政管理部门备案，或者备案内容弄虚作假的，由负责备案管理的粮食行政管理部门责令改正，给予警告;拒不改正的，处1万元以下罚款。"},{"i":29,"n":"第二十九条","txt":"粮油仓储单位不具备本办法第七条规定条件的，由负责备案管理的粮食行政管理部门责令改正，给予警告;拒不改正的，处1万元以上3万元以下罚款。"},{"i":30,"n":"第三十条","txt":"粮油仓储单位的名称不符合本办法第八条规定的，由负责备案管理的粮食行政管理部门责令改正，给予警告。"},{"i":31,"n":"第三十一条","txt":"粮油仓储单位违反本办法有关粮油出入库、储存等管理规定的，由所在地粮食行政管理部门责令改正，给予警告;情节严重的，可以并处3万元以下罚款;造成粮油储存事故或者安全生产事故的，按照有关法律法规和国家有关规定给予处罚。"},{"i":32,"n":"第三十二条","txt":"本办法所称粮油，包括各类粮食、植物油料和油脂。 本办法所称粮油仓储单位，是指仓容规模500吨以上或者罐容规模100吨以上，专门从事粮油仓储活动，或者在粮油收购、销售、运输、加工、进出口等经营活动过程中从事粮油仓储活动的法人和其他组织。 仓容规模500吨以下或者罐容规模100吨以下从事粮油仓储活动的经营者，其管理办法由省、自治区、直辖市人民政府粮食行政管理部门参照本办法制定。"},{"i":33,"n":"第三十三条","txt":"本办法相关条款所称的“以上”包括本数，“以下”不包括本数。"},{"i":34,"n":"第三十四条","txt":"本办法自公布之日起施行。原商业部1987年6月22日颁布的《国家粮油仓库管理办法》((87)商储(粮)字第12号)同时废止。 附件一： 关于污染源、危险源安全距离的规定 粮油仓储单位的固定经营场地至污染源、危险源的距离应当满足以下要求： 一、距有害元素的矿山、炼焦、炼油、煤气、化工(包括有毒化合物的生产)、塑料、橡胶制品及加工、人造纤维、油漆、农药、化肥等排放有毒气体的生产单位，不小于1000米; 二、距屠宰场、集中垃圾堆场、污水处理站等单位，不小于500米; 三、距砖瓦厂、混凝土及石膏制品厂等粉尘污染源，不小于100米。 附件二： 关于粮油储存损耗处置办法的规定 一、粮油储存损耗包括自然损耗和水分杂质减量： (一)自然损耗是指粮油在储存过程中，因正常生命活动消耗的干物质、计量的合理误差、检验化验耗用的样品、轻微的虫鼠雀害以及搬倒中零星抛撒等导致的损耗。 (二)水分杂质减量是指粮油在入"}],"liangshiliutongxingzhengzhifabanfa":[{"i":1,"n":"第一条","txt":"为全面贯彻落实党的二十大精神，深入贯彻落实习近平新时代中国特色社会主义思想，全方位夯实粮食安全根基，规范粮食和物资储备行政管理部门（以下简称“粮食和储备部门”）粮食流通行政执法行为，根据《中华人民共和国行政处罚法》《中华人民共和国行政强制法》《粮食流通管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于粮食和储备部门对粮食收购、储存、运输和政策性粮食购销等活动，以及国家粮食流通统计制度执行情况，依法开展的监督检查活动。"},{"i":3,"n":"第三条","txt":"粮食和储备部门应当与相关部门加强配合，建立粮食流通行政执法工作协调机制。"},{"i":4,"n":"第四条","txt":"粮食流通行政执法应当严格落实《国务院办公厅关于全面推行行政执法公示制度执法全过程记录制度重大执法决定法制审核制度的指导意见》相关制度规定。 粮食流通行政执法实行持证上岗。开展行政执法工作，执法人员不得少于两人，不得干扰粮食经营者的正常经营活动。 粮食和储备部门应当加强粮食流通行政执法制度建设和人员队伍建设，并定期对行政执法人员进行培训考核。"},{"i":5,"n":"第五条","txt":"任何单位和个人有权向粮食和储备部门检举违反粮食流通管理规定的行为。粮食和储备部门应当为检举人保密，并依法及时处理。"},{"i":6,"n":"第六条","txt":"粮食流通行政执法过程中，可以行使以下职权： （一）进入粮食经营者经营场所，查阅有关资料、凭证； （二）检查粮食数量、质量和储存安全情况； （三）检查粮食仓储设施、设备是否符合有关标准和技术规范； （四）向有关单位和人员调查了解相关情况； （五）查封、扣押非法收购或者不符合国家粮食质量安全标准的粮食，用于违法经营或者被污染的工具、设备以及有关账簿资料； （六）查封违法从事粮食经营活动的场所； （七）法律、法规规定的其他职权。"},{"i":7,"n":"第七条","txt":"被检查对象对粮食流通行政执法人员依法履行职责，应当予以配合。任何单位和个人不得拒绝、阻挠、干涉粮食和储备部门粮食流通行政执法人员依法履行行政执法职责。"},{"i":8,"n":"第八条","txt":"粮食和储备部门行政执法实行分级负责制。 国家粮食和物资储备局组织、指导跨省（自治区、直辖市）等重大案件的查办，必要时提级或者指定管辖。省级粮食和储备部门组织、指导跨地（市）等重大案件的查处，必要时提级或者指定管辖。"},{"i":9,"n":"第九条","txt":"粮食和储备部门行政执法涉及政策性粮食的，应当结合粮食权属及性质开展。 国家粮食和物资储备局垂直管理局负责监管辖区内中央政府储备粮管理情况，对中央政府储备粮承储企业开展行政执法，依法对违法违规行为实施行政处罚。 地方粮食和储备部门会同国家粮食和物资储备局垂直管理局，监管辖区内除中央政府储备粮以外的其他中央事权粮食及其相关政策执行情况，开展相关行政执法。 地方粮食和储备部门监管辖区内地方政府储备粮，以及社会粮食流通情况。 国家粮食和物资储备局垂直管理局与省级粮食和储备部门应当建立协同联动工作机制。"},{"i":10,"n":"第十条","txt":"粮食和储备部门实施行政处罚，原则上由违法行为发生地的县级以上粮食和储备部门管辖。两个以上同级部门都有管辖权的，由最先立案的粮食和储备部门管辖；因管辖权发生争议，协商解决不成的，应当报请共同上一级部门指定管辖。 粮食和储备部门发现涉嫌违法违规的行为不属于本部门管辖时，应当及时移送有管辖权的粮食和储备部门。受移送的粮食和储备部门对管辖权有异议的，应当报请共同上一级部门指定管辖；不得擅自移送。"},{"i":11,"n":"第十一条","txt":"粮食和储备部门在行政执法中发现不属于本部门管辖的涉嫌违法违规的行为，应当及时向有管辖权的相关部门移送违法线索。"},{"i":12,"n":"第十二条","txt":"粮食和储备部门对属于本部门管辖的涉嫌违法违规的行为，除可以当场作出行政处罚的外，应当立案调查。"},{"i":13,"n":"第十三条","txt":"粮食经营者存在下列情形之一的，属于第十二条规定的应当立案调查的违法违规行为： （一）粮食收购企业、仓储单位未按照规定备案，或者提供虚假备案信息； （二）粮食收购企业未及时向售粮者支付售粮款，时间三十日以上且涉及金额三千元以上，或者其他粮食收购者未及时向售粮者支付售粮款被举报； （三）粮食收购者违反《粮食流通管理条例》相关规定，代扣、代缴税、费和其他款项； （四）粮食收购者未执行国家粮食质量标准，涉及粮食数量较大； （五）粮食收购者收购粮食，未按照国家有关规定进行质量安全检验，涉及粮食数量较大； （六）粮食收购者收购粮食，对不符合食品安全标准的粮食未作为非食用用途单独储存； （七）粮食储存企业未按照规定进行粮食销售出库质量安全检验，涉及粮食数量五吨以上； （八）粮食收购者、粮食储存企业非法销售不得作为食用用途销售的粮食； （九）从事粮食收购、销售、储存、加工的经营者以及饲料、工业用粮企业"},{"i":14,"n":"第十四条","txt":"粮食经营者在政策性粮食业务中，存在下列情形之一的，属于第十二条规定的应当立案调查的违法违规行为： （一）政策性粮食收购时，未及时向售粮者支付售粮款； （二）承储企业虚报粮食收储数量达十吨以上； （三）承储企业通过以陈顶新、以次充好、低收高转、虚假购销、虚假轮换、违规倒卖等方式，套取粮食价差和财政补贴，或者骗取信贷资金； （四）承储企业挤占、挪用、克扣财政补贴、信贷资金三千元以上； （五）承储企业擅自动用政策性粮食； （六）承储企业以政策性粮食为债务作担保或者清偿债务； （七）承储企业利用政策性粮食进行除政府委托的政策性任务以外的其他商业经营； （八）承储企业在政策性粮食出库时掺杂使假、以次充好、调换标的物，涉及粮食数量五吨以上； （九）承储企业在政策性粮食出库时拒不执行出库指令或者阻挠出库，时间三日以上并且涉及粮食数量五十吨以上； （十）粮食经营者购买国家限定用途的政策性粮食，违规倒卖"},{"i":15,"n":"第十五条","txt":"应当立案调查的，立案决定应于发现涉嫌违法违规行为之日起十五个工作日内，经粮食和储备部门负责人批准后作出。"},{"i":16,"n":"第十六条","txt":"粮食和储备部门对违法违规行为进行调查取证，应当依照相关法律法规及粮食和储备部门有关工作规程等法定程序开展。"},{"i":17,"n":"第十七条","txt":"粮食和储备部门执法人员在调查或者进行检查时，应当主动向当事人或者有关人员出示行政执法证件。当事人或者有关人员有权要求执法人员出示行政执法证件。执法人员不出示行政执法证件的，当事人或者有关人员有权拒绝接受调查或者检查。 当事人或者有关人员应当如实回答询问，并协助调查或者检查，不得拒绝或者阻挠。询问或者检查应当制作笔录。"},{"i":18,"n":"第十八条","txt":"粮食和储备部门在收集证据时，可以抽样取证。 在证据可能灭失或者以后难以取得的情况下，经粮食和储备部门负责人批准，可以先行登记保存，并在七个工作日内作出处理决定。 在调查期间，被调查对象及有关人员不得销毁或者转移证据。"},{"i":19,"n":"第十九条","txt":"粮食和储备部门可委托具有相应资质的鉴定检测机构，对涉嫌违法违规行为有关的粮食、工具等进行鉴定检测。"},{"i":20,"n":"第二十条","txt":"粮食和储备部门应当在立案决定作出之日起三十日内形成案件调查报告，必要时可听取公职律师、法律顾问、专家意见。案情疑难复杂或者委托检验鉴定时间较长的，经粮食和储备部门负责人批准，可以适当延长调查时限。"},{"i":21,"n":"第二十一条","txt":"粮食和储备部门在行政执法过程中，应当依照法定的权限、范围、条件和程序，实施查封、扣押等行政强制措施。采用非强制手段可以达到行政管理目的的，不得实施查封、扣押等行政强制措施。"},{"i":22,"n":"第二十二条","txt":"粮食和储备部门不得查封、扣押与违法行为无关的粮食、工具、设备、账簿资料，不得查封与违法行为无关的场所。粮食经营者的粮食、工具、设备、账簿资料、场所等已被其他国家机关依法查封的，不得重复查封。"},{"i":23,"n":"第二十三条","txt":"粮食和储备部门决定实施查封、扣押的，应当制作并当场交付查封、扣押决定书和清单。"},{"i":24,"n":"第二十四条","txt":"查封、扣押的期限不得超过三十日；情况复杂的，经粮食和储备部门负责人批准，可以延长，但是延长期限不得超过三十日。法律、行政法规另有规定的除外。 延长查封、扣押的决定应当及时书面告知当事人，并说明理由。 对涉案粮食、工具、设备需要进行检测、检验或者技术鉴定的，查封、扣押的期间不包括检测、检验或者技术鉴定的期间。检测、检验或者技术鉴定的期间应当明确，并书面告知当事人。初次检测、检验或者技术鉴定的费用由粮食和储备部门承担。"},{"i":25,"n":"第二十五条","txt":"对查封、扣押的粮食、工具、设备、账簿资料、场所等，粮食和储备部门应当妥善保管，不得使用或者损毁；造成损失的，应当承担赔偿责任。 对查封的粮食、工具、设备、账簿资料、场所等，粮食和储备部门可以委托第三人保管，第三人不得损毁或者擅自转移、处置。因第三人的原因造成的损失，粮食和储备部门先行赔付后，应当及时向第三人追偿。 因查封、扣押发生的保管费用由粮食和储备部门承担。"},{"i":26,"n":"第二十六条","txt":"粮食和储备部门采取查封、扣押措施后，应当及时查清事实，在规定期限内作出处理决定。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，粮食和储备部门应当及时作出解除查封、扣押决定： （一）当事人没有违法行为； （二）查封、扣押的粮食、工具、设备、账簿资料、场所等与违法行为无关； （三）对违法行为已经作出处理决定，不再需要查封、扣押； （四）查封、扣押期限已经届满； （五）其他不再需要采取查封、扣押措施的情形。 解除查封、扣押应当立即退还粮食、工具、设备、账簿资料。"},{"i":28,"n":"第二十八条","txt":"粮食和储备部门查封、扣押的粮食、工具、设备、账簿资料、场所等，依法应当没收、销毁的，依照有关法律法规规定，移送有权部门执行。"},{"i":29,"n":"第二十九条","txt":"违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的行政处罚的，粮食和储备部门及其执法人员可以当场作出行政处罚决定。法律另有规定的，从其规定。"},{"i":30,"n":"第三十条","txt":"执法人员当场作出行政处罚决定的，应当向当事人出示行政执法证件，填写预定格式、编有号码的行政处罚决定书，并当场交付当事人。当事人拒绝签收的，应当在行政处罚决定书上注明。 前款规定的行政处罚决定书应当载明当事人的违法行为，行政处罚的种类和依据、罚款数额、时间、地点，申请行政复议、提起行政诉讼的途径和期限以及行政机关名称，并由执法人员签名或者盖章。 执法人员当场作出的行政处罚决定，应当报所属粮食和储备部门备案。"},{"i":31,"n":"第三十一条","txt":"对当场作出的行政处罚决定，当事人应当依照《中华人民共和国行政处罚法》的规定履行。"},{"i":32,"n":"第三十二条","txt":"除本办法规定的可以当场作出的行政处罚外，粮食和储备部门发现公民、法人或者其他组织有依法应当给予行政处罚的行为的，必须全面、客观、公正地调查，收集有关证据。"},{"i":33,"n":"第三十三条","txt":"调查终结，粮食和储备部门负责人应当对调查结果进行审查，根据不同情况，分别作出如下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关。 对情节复杂或者重大违法行为给予行政处罚，粮食和储备部门负责人应当集体讨论决定。"},{"i":34,"n":"第三十四条","txt":"粮食和储备部门在作出行政处罚决定时，应当遵循公正、公开、过罚相当、处罚与教育相结合的原则，正确行使粮食流通行政处罚裁量权。 省级粮食和储备部门、国家粮食和物资储备局垂直管理局应当参照本办法，结合地区实际制定并公开行政处罚裁量权基准，包括违法行为、法定依据、裁量阶次、适用条件和具体标准等内容。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一，在粮食和储备部门负责人作出行政处罚的决定之前，应当由从事行政处罚决定法制审核的人员按照相关规定进行法制审核；未经法制审核或者审核未通过的，不得作出决定： （一）涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）应当进行法制审核的其他情形。 粮食和储备部门初次从事行政处罚决定法制审核的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":36,"n":"第三十六条","txt":"粮食和储备部门及其执法人员在作出行政处罚决定之前，未依照《中华人民共和国行政处罚法》规定向当事人告知拟作出的行政处罚内容及事实、理由、依据，或者拒绝听取当事人的陈述、申辩，不得作出行政处罚决定；当事人明确放弃陈述或者申辩权利的除外。"},{"i":37,"n":"第三十七条","txt":"粮食和储备部门依照《中华人民共和国行政处罚法》规定给予行政处罚，应当制作行政处罚决定书。行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）违反法律、法规、规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）申请行政复议、提起行政诉讼的途径和期限； （六）作出行政处罚决定的行政机关名称和作出决定的日期。 行政处罚决定书必须盖有作出行政处罚决定的粮食和储备部门的印章。"},{"i":38,"n":"第三十八条","txt":"粮食和储备部门应当自行政处罚案件立案之日起九十日内作出行政处罚决定。法律、法规另有规定的，从其规定。"},{"i":39,"n":"第三十九条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，粮食和储备部门应当在七个工作日内依照《中华人民共和国民事诉讼法》有关规定，将行政处罚决定书送达当事人。 当事人同意并签订确认书的，粮食和储备部门可以采用传真、电子邮件等方式，将行政处罚决定书等送达当事人。"},{"i":40,"n":"第四十条","txt":"粮食和储备部门行政处罚决定信息应当在执法决定作出之日起7个工作日内，通过政府网站及政务新媒体、办事大厅公示栏、服务窗口等平台向社会公开。"},{"i":41,"n":"第四十一条","txt":"粮食流通行政处罚产生的罚没收入，按照《中华人民共和国行政处罚法》和《财政部关于印发〈罚没财物管理办法〉的通知》（财税〔2020〕54号）相关规定处理。"},{"i":42,"n":"第四十二条","txt":"粮食和储备部门拟作出下列行政处罚决定，应当告知当事人有要求听证的权利，当事人要求听证的，粮食和储备部门应当组织听证： （一）较大数额罚款； （二）没收较大数额违法所得； （三）法律、法规、规章规定的其他情形。 前款中所称“较大数额”，省、自治区、直辖市人大常委会或者人民政府有规定的，从其规定；没有规定的，其数额为对公民罚款、没收违法所得三千元以上，对法人或者其他组织罚款、没收违法所得五万元以上。 当事人不承担粮食和储备部门组织听证的费用。"},{"i":43,"n":"第四十三条","txt":"听证应当依照以下程序组织： （一）当事人要求听证的，应当在粮食和储备部门告知后五个工作日内提出； （二）粮食和储备部门应当在举行听证的七个工作日前，通知当事人及有关人员听证的时间、地点； （三）除涉及国家秘密、商业秘密或者个人隐私依法予以保密外，听证公开举行； （四）听证由粮食和储备部门指定的非本案调查人员主持；当事人认为主持人与本案有直接利害关系的，有权申请回避； （五）当事人可以亲自参加听证，也可以委托一至二人代理 （六）当事人及其代理人无正当理由拒不出席听证或者未经许可中途退出听证的，视为放弃听证权利，粮食和储备部门终止听证； （七）举行听证时，调查人员提出当事人违法的事实、证据和行政处罚建议，当事人进行申辩和质证； （八）听证应当制作笔录。笔录应当交当事人或者其代理人核对无误后签字或者盖章。当事人或者其代理人拒绝签字或者盖章的，由听证主持人在笔录中注明。"},{"i":44,"n":"第四十四条","txt":"听证结束后，粮食和储备部门应当根据听证笔录，依照《中华人民共和国行政处罚法》的规定，作出决定。"},{"i":45,"n":"第四十五条","txt":"粮食和储备部门行政执法人员在粮食流通行政执法中，涉嫌违纪违规、违法犯罪的，依照有关规定移送纪检监察机关、司法机关。 有下列行为之一的，除按前款规定处理外，粮食和储备部门应予以通报，并由相关任免部门按照管理权限进行教育、管理、监督或处分： （一）包庇、纵容粮食流通违法违规行为； （二）瞒案不报、压案不查； （三）未按规定核查、处理粮食流通违法违规举报、案件线索； （四）未按法定权限、程序和规定开展粮食流通行政执法，造成不良后果； （五）违反保密规定，泄露举报人或者案情； （六）滥用职权、徇私舞弊； （七）其他违法违规行为。"},{"i":46,"n":"第四十六条","txt":"本办法中，涉及粮食价值的，已达成交易的按交易价计算，其他按库存成本价或最近一次采购成本计算；涉及数量的，“以上”包括基数。"},{"i":47,"n":"第四十七条","txt":"大豆、油料和食用植物油的收购、销售、储存、运输、加工等经营活动，适用本办法的规定。"},{"i":48,"n":"第四十八条","txt":"本办法由国家发展改革委、国家粮食和物资储备局负责解释。"},{"i":49,"n":"第四十九条","txt":"本办法自2023年1月1日起施行。2004年11月16日国家发展和改革委员会、原国家粮食局、财政部、原卫生部、原国家工商行政管理总局、原国家质量监督检验检疫总局印发的《粮食流通监督检查暂行办法》（国粮检〔2004〕230号），以及2005年3月9日原国家粮食局印发的《粮食监督检查行政处罚程序（试行）》（国粮检〔2005〕31号）同时废止。"}],"liangshizhilianganquanjianguanbanfa":[{"i":1,"n":"第一条","txt":"为保护粮食生产者的积极性，维护粮食经营者和消费者的合法权益，加强粮食流通领域质量安全监督管理，保障国家粮食质量安全，根据《粮食流通管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"粮食收购、储存、运输和政策性粮食购销活动的质量安全监管工作，适用本办法。 政府储备粮食质量安全管理的特殊要求按国家粮食和储备行政管理部门制定的相关规定执行。"},{"i":3,"n":"第三条","txt":"县级以上粮食和储备行政管理部门在本级人民政府的统一组织领导下，负责本行政区域粮食收购、储存、运输和政策性粮食购销活动中粮食质量安全的监督管理工作。 国家粮食和物资储备局垂直管理机构负责监管辖区内中央政府储备质量安全管理情况。"},{"i":4,"n":"第四条","txt":"粮食经营者对粮食质量安全承担主体责任。 从事粮食经营活动，应当严格执行有关法律、法规、政策及标准，严格遵守粮食质量安全管理制度，明确质量安全管理责任，认真落实反食品浪费、粮食节约等有关规定和要求，严禁多扣水杂、压级压价、以陈顶新、掺杂使假、以次充好等行为。"},{"i":5,"n":"第五条","txt":"国家鼓励采用并推行科学先进的质量安全管理和检验方法、标准和适用技术，不断提高粮食质量安全管理水平。 县级以上粮食和储备行政管理部门应当建立并完善粮食质量安全数据库；定期对相关人员进行有关法律、法规、政策、标准和技能等培训。"},{"i":6,"n":"第六条","txt":"开展粮食质量安全风险监测、检验等检查活动所需必要合理的费用，按照有关规定列入本级部门预算。"},{"i":7,"n":"第七条","txt":"省级以上粮食和储备行政管理部门应当建立健全粮食收购和储存环节质量安全风险监测制度，包括收购粮食质量安全监测、库存粮食质量安全监测、应急粮食质量安全监测和其他专项粮食质量安全监测。 县级以上地方粮食和储备行政管理部门应当按照国家粮食质量安全风险监测管理规定，结合本行政区域的具体情况，依职责组织开展粮食质量安全风险监测工作。 县级以上地方粮食和储备行政管理部门获知粮食质量安全风险信息后，应当立即组织开展核查，视情况及时调整粮食质量安全风险监测计划，依职责采取风险防控措施，降低粮食质量安全风险和损失。"},{"i":8,"n":"第八条","txt":"开展风险监测工作应当充分利用现有资源和成果，建立各有侧重、上下联动、有效衔接、协同配合、结果共享的监测机制。"},{"i":9,"n":"第九条","txt":"县级以上粮食和储备行政管理部门应当强化粮食质量安全风险监测等全过程信息化管理，统筹利用有关数据和信息资源。"},{"i":10,"n":"第十条","txt":"省级粮食和储备行政管理部门应当及时将本行政区域内粮食质量安全风险监测结果以及对发现问题的处理情况报告本级人民政府，通报同级食品安全委员会办公室及相关部门和单位，抄送国家粮食和储备行政管理部门。"},{"i":11,"n":"第十一条","txt":"县级以上地方粮食和储备行政管理部门应当按照本级人民政府加强粮食污染监控、建立健全被污染粮食处置长效机制等要求，依职责开展有关工作。发现区域性粮食污染情况或者在收购等环节发现有关线索的，应当按照地方人民政府或者有关部门和单位的规定，依职责迅速采取处置措施。"},{"i":12,"n":"第十二条","txt":"粮食收购者、粮食储存企业使用仓储设施设备应当符合粮食储存有关标准和技术规范以及安全生产法律、法规的要求；收购、储存场所应当保持整洁，并按规定与有毒有害场所以及其他污染源保持安全距离。"},{"i":13,"n":"第十三条","txt":"粮食经营者收购粮食，应当严格执行国家粮食质量标准和政策，按质论价，按照国家有关规定进行质量安全检验，并执行下列规定： （一）告知售粮者或者在收购场所醒目位置公示粮食的品种、质量标准、收购价格等内容； （二）按照有关标准、技术规范和政策规定进行入库和平仓环节扦样、检验，把好入库质量关。发现不符合食品安全国家标准的粮食，应当及时向收购地县级粮食和储备行政管理等部门报告，跨省收购的，应当向收购地和粮食收购企业所在地的县级粮食和储备行政管理等部门报告； （三）杂质、水分等质量指标超过标准限量或者政策规定的政策性粮食，应当及时整理达标或者符合相关要求。水分较高时应当合理降水、降温，确保安全储粮。"},{"i":14,"n":"第十四条","txt":"鼓励对不同产地、等级和品质的粮食单收、单储。"},{"i":15,"n":"第十五条","txt":"粮食经营者收购非食用用途的粮食，应当单收、单储、单销，采取在收购码单、包装、库存货位卡上明确标识等措施，强化全流程闭环管理。 粮食经营者对粮食进行单收、单储，应当通过单独仓廒、物理隔断等措施进行，确保符合有关规定。"},{"i":16,"n":"第十六条","txt":"粮食经营者储存粮食应当遵守粮油仓储管理制度规定和相关标准，规范仓储管理业务，合理应用粮油储藏技术。储存过程中发现粮食质量不符合要求的，应当及时按规定进行处置。 粮食不得与可能对粮食产生污染的有毒有害物质混存。 国家鼓励建设高标准粮仓，推广使用绿色储粮技术，有效保障储存安全和粮食品质。"},{"i":17,"n":"第十七条","txt":"粮食经营者储存粮食应当严格执行储粮药剂使用管理制度和相关标准，不得使用国家禁止使用的化学药剂或者超量使用化学药剂。"},{"i":18,"n":"第十八条","txt":"粮食销售出库前，粮食经营者应当严格按照粮食质量安全标准及有关规定进行质量安全检验，出具检验检测数据、结果、报告（以下统称检验报告），作为出库质量安全依据。未经质量安全检验的粮食不得销售出库。 （一）在正常储存年限内的粮食，销售出库前粮食储存企业应当自行检验或者委托粮食质量安全检验机构进行质量安全检验，并出具检验报告； （二）超过正常储存年限的粮食，或者储存期间使用储粮药剂未满安全间隔期的粮食，以及色泽、气味异常的粮食，在出库前应当委托粮食质量安全检验机构进行质量安全检验，并出具检验报告。 销售出库粮食的质量安全状况应当与检验报告相一致。检验报告应当随货同行，有效期为自签发之日起6个月，国家另有规定的，从其规定。有效期满，应当重新检验并出具检验报告。 粮食质量安全检验机构应当按照委托方要求的时间和方式完成扦样、检验并出具检验报告。"},{"i":19,"n":"第十九条","txt":"粮食收购者、粮食储存企业不得将直接拌有农药、混有农药残渣、含有国家禁止使用的储粮药剂或者超量使用化学药剂的粮食作为食用用途销售出库。定向销售用作非食用用途的粮食，应当在包装、销售凭证中明确标识用途。对定向销售作为非食用用途的政策性粮食的质量安全管理另有规定的，从其规定。"},{"i":20,"n":"第二十条","txt":"根据特定区域粮食可能受到有害物质污染、发生霉变等情况，或者根据有关政策规定，省级粮食和储备行政管理部门应当统一或者分地区设定粮食收购和出库质量安全必检项目，并抄送国家粮食和储备行政管理部门。"},{"i":21,"n":"第二十一条","txt":"运输粮食的运输工具、容器应当完好，并保持清洁、干燥、安全卫生。非专用车（船）应当有必要的铺垫物和防潮湿等设备，铺垫物、防潮湿设备等必备物品应当符合国家有关标准和政策要求。 不得使用被污染的运输工具、容器或者包装材料运输粮食，不得与有毒有害物质混装运输。"},{"i":22,"n":"第二十二条","txt":"运输粮食应当严防发生质量安全事故。运输粮食发生污染、结露、虫害、霉变等情况的，有关方面应当积极采取有效措施进行处置。 运输粮食应当符合国家规定，有效减少粮食运输损耗。鼓励采取在途粮食质量安全监测技术等信息化手段，保障运输过程中粮食质量安全。"},{"i":23,"n":"第二十三条","txt":"粮食经营者应当如实记录粮食品种、供货方、粮食产地、收获年度、入库时间、货位及数量、质量等级、品质情况、药剂使用情况、销售去向和出库时间，以及其他有关质量安全信息，形成档案，保存期限自粮食销售出库之日起，不得少于3年。"},{"i":24,"n":"第二十四条","txt":"粮食经营者应当建立库存粮食从入库到出库环节的质量安全追溯制度，实现粮食质量安全可追溯。"},{"i":25,"n":"第二十五条","txt":"按照粮食资源合理化利用、节粮减损等原则，对重金属、真菌毒素、农药残留等污染物质以及其他危害人体健康的物质含量超过食品安全标准限量的粮食，能够进行无害化处理的，鼓励粮食收储企业进行无害化处理，并按规定利用。"},{"i":26,"n":"第二十六条","txt":"粮食质量安全检验机构应当取得检验检测机构资质认定，依法依规开展检验监测工作。 粮食质量安全检验机构应当加强自身质量控制体系、检验能力、人员队伍建设，包括健全的规章制度、必要的粮食检验仪器设备和配套基础设施，质量安全技术基础研究、应用和信息管理能力，相应的管理和技术人才队伍等。 粮食质量安全检验机构应当加强扦样、检验人员业务培训，提升人员素质，使其具备必要的专业知识和所需的职业技能，熟悉粮食相关法律法规和政策规定，满足岗位要求。扦样、检验人员上岗前应当接受所在岗位工作相关技术培训。"},{"i":27,"n":"第二十七条","txt":"国家粮食和储备行政管理部门应当建立健全国家粮食质量安全检验监测体系，根据开展粮食质量检验监测等工作的需要，依托现有粮食检验监测资源，择优选用基础较好的粮食质量安全检验机构，委托承担检验监测任务。 省级以上粮食和储备行政管理部门应当加强对粮食质量安全检验监测业务的管理和指导，通过现场检查、标准物质测量审核、样品比对等方式，提升粮食质量安全检验监测能力，充分发挥粮食质量安全检验机构的作用。 县级以上地方粮食和储备行政管理部门应当按照落实粮食安全责任制的要求，建立健全粮食质量安全检验监测体系，加强能力建设，确保能够履行相应职责。"},{"i":28,"n":"第二十八条","txt":"扦样方法和程序应当符合国家有关规定、标准。扦样机构和扦样人员对扦样合规性、样品真实性与代表性、信息准确性与完整性负责。 扦样人员在扦样过程中应当严格遵守安全生产有关规定，采取有效的安全防护措施。扦样机构和被扦样单位应当提供必要的人身安全保护用品。 出现下列情形的，应当实施现场扦样，不得由利益相关方送样： （一）监督检查中的质量安全检验监测； （二）超过正常储存年限的粮食、储存期间使用储粮药剂未满安全间隔期的粮食以及色泽、气味异常的粮食的出库质量安全检验监测； （三）其他应当实施现场扦样的。"},{"i":29,"n":"第二十九条","txt":"粮食经营者在收购环节进行的粮食质量安全检验以及县级以上粮食和储备行政管理部门依法依规开展的粮食质量安全风险监测和抽查检验，可采用国家粮食和储备行政管理部门认可的快速检测方法。 采用快速检测方法，应当实施有效的质量控制措施，保证检测结果真实可靠。在粮食质量安全抽查检验中，快速检测结果表明可能不符合国家粮食质量标准和政策规定的，应当按照国家标准规定的检验方法进行检验。"},{"i":30,"n":"第三十条","txt":"县级以上粮食和储备行政管理部门在监督检查中需要对粮食质量安全进行检验的，应当委托粮食质量安全检验机构进行扦样和检验，并按规定支付相应费用。扦取的样品应当自监督检查工作结束后保留3个月。"},{"i":31,"n":"第三十一条","txt":"粮食经营者对监督检查检验结果有异议的，可以向监督检查机构申请复检并充分说明理由。监督检查机构认为存在检验程序不规范等需要复检的，可以安排原粮食质量安全检验机构进行复检；必要时，可以安排其他具备条件的省级以上粮食质量安全检验机构进行复检。 复检应当使用备份样品。有充分理由说明备份样品不具备代表性的，可以安排重新扦样。 复检不得采用快速检测方法。"},{"i":32,"n":"第三十二条","txt":"粮食质量安全检验机构应当履行保密义务，除法律法规规定的情形外，未经委托方同意，不得擅自公开或者向他人提供检验报告。对发现存在粮食质量安全重大风险情况的，应当及时报告粮食所在地粮食和储备行政管理部门。"},{"i":33,"n":"第三十三条","txt":"县级以上地方粮食和储备行政管理部门应当结合本地实际建立健全粮食质量安全事故应急预案。对粮食经营者因管理不善等原因，导致粮食出现较为严重的质量安全等问题或者风险的，应当进行应急处置。 县级以上地方粮食和储备行政管理部门应当完善快速反应及应急处置信息发布机制和程序，加强应急处置能力和应急队伍建设，强化应急装备配置和应急物资储备，提升应急处置能力和水平，满足应急需要。"},{"i":34,"n":"第三十四条","txt":"粮食经营者应当具备处置粮食质量安全事故的能力，定期检查各项风险防范措施的落实情况，及时消除事故隐患。 粮食质量安全事故发生后，有关粮食经营者应当立即对事故予以妥善处置，防止损害扩大，并及时向事故发生地县级粮食和储备行政管理部门报告。有上级管理单位的，一并向其上级管理单位报告。"},{"i":35,"n":"第三十五条","txt":"县级以上粮食和储备行政管理部门在日常监督管理中发现粮食质量安全事故，或者接到粮食质量安全事故报告，应当依职责和权限立即调查处理，按规定采取封存、检验、限定用途等措施，防止或者减轻对社会的危害。发生重大粮食质量安全事故的，应当同时报告本级人民政府、上一级粮食和储备行政管理部门，并及时通报同级食品安全委员会办公室及相关部门。 任何单位或者个人不得隐瞒、谎报、缓报粮食质量安全事故，不得毁灭有关证据。"},{"i":36,"n":"第三十六条","txt":"县级以上粮食和储备行政管理部门进行粮食质量安全事故调查，有权向有关单位和个人了解与事故有关的情况，并要求提供相关资料和样品。有关单位和个人应当予以配合，不得拒绝。 任何单位和个人不得阻挠、干涉粮食质量安全事故的调查处理。"},{"i":37,"n":"第三十七条","txt":"县级以上粮食和储备行政管理部门依法依规依职责对粮食经营者进行质量安全监督管理，制定粮食质量安全监督抽查计划，采用普查、随机抽查、巡查、重点检查、交叉检查、提级查办等方式，对本行政区域内收购、储存、运输活动和政策性粮食购销活动中的质量安全状况实施监督抽查。 国家粮食和储备行政管理部门根据质量安全监管需要组织开展监督抽查，原则上每年不少于1次；国家粮食和物资储备局垂直管理机构按照季度巡查等要求，开展质量安全监督抽查。 县级以上地方粮食和储备行政管理部门根据国家粮食和储备行政管理部门年度监督抽查计划，结合实际组织本行政区域监督抽查，原则上每年不少于2次。监督抽查内容主要包括粮食质量安全状况，执行出入库检验制度、质量管理制度情况，对被污染粮食实施定点收购、分类管理、专仓储存、定向处置等闭环管理、全程监控措施的情况等。 根据实际情况，政府储备粮食年度监督抽查比例一般不低于本行政区域内本级政府储备"},{"i":38,"n":"第三十八条","txt":"县级以上粮食和储备行政管理部门在履行粮食质量安全监督管理职责过程中，有权采取下列措施： （一）进入粮食经营者经营场所检查粮食质量安全情况，对检验仪器设备和扦样、检验的规范性进行检查； （二）向有关单位和人员调查、了解相关情况； （三）查阅、复制与粮食经营活动中与质量安全有关的合同、票据、账簿、检验报告以及其他资料、凭证； （四）对粮食经营者经营的粮食进行扦样检验； （五）检查粮食仓储设施、设备是否符合有关标准、技术规范和安全生产要求； （六）查封、扣押非法收购或者不符合国家粮食质量安全标准的粮食，用于违法经营或者被污染的工具、设备以及有关账簿资料； （七）查封违法从事粮食经营活动的场所。 粮食经营者拒绝检查的，粮食和储备行政管理部门应当向本级人民政府、上一级粮食和储备行政管理部门报告。"},{"i":39,"n":"第三十九条","txt":"日常质量安全监督抽查的情况和处理结果应当经监督抽查人员和粮食经营者签字后归档。粮食经营者拒绝签字的，应当如实记录原因，经监督抽查人员2人以上签字后归档。"},{"i":40,"n":"第四十条","txt":"县级以上粮食和储备行政管理部门建立粮食经营者信用档案，应当包含粮食经营者粮食质量安全信用情况，记录日常质量安全监督抽查结果、违规违纪违法行为查处等信息，并根据信用等级实施分类监管，对有不良信用记录的粮食经营者增加抽查频次。"},{"i":41,"n":"第四十一条","txt":"任何组织和个人有权向县级以上粮食和储备行政管理部门提出加强粮食质量安全监督管理工作的意见和建议，举报粮食质量安全违规违纪违法行为。"},{"i":42,"n":"第四十二条","txt":"县级以上粮食和储备行政管理部门接到意见、建议和举报，应当按照职责和程序及时研究、处理。对属于本部门职责的，应当受理，并及时进行答复、核实、处理；对不属于本部门职责的，应当书面通知相对人，按程序移交有权处理的部门处理，或者告知其向有权处理的部门反映。"},{"i":43,"n":"第四十三条","txt":"国家粮食和储备行政管理部门可以依法依规对省级粮食和储备行政管理部门的质量安全监管工作进行年度评估考核，对取得显著成绩的单位和个人进行通报表扬。 县级以上地方粮食和储备行政管理部门落实粮食质量安全监管职责情况依法依规纳入相关考核。"},{"i":44,"n":"第四十四条","txt":"县级以上粮食和储备行政管理部门违反本办法规定，出现下列情形的，责令改正；造成严重后果的，对负有责任的领导人员和直接责任人员依规依纪依法给予处分： （一）未建立并实施粮食质量安全风险监测制度的； （二）发现区域性粮食污染情况，未按规定及时报告或者处置的； （三）未建立健全粮食质量安全事故应急预案及相关机制的； （四）本行政区域内的粮食质量安全违法违规行为由上级粮食和储备行政管理部门在监督抽查中发现的； （五）其他在粮食质量安全监督管理中不依法依规履行职责或者存在滥用职权、玩忽职守、徇私舞弊等情形的。"},{"i":45,"n":"第四十五条","txt":"县级以上粮食和储备行政管理部门所属的粮食质量安全检验机构和检验人员违反本办法规定，出现下列情形的，由县级以上粮食和储备行政管理部门依职责对有关单位和人员进行处分；情节严重的，依法纳入全国信用信息共享平台： （一）违反保密规定，未经委托方同意擅自公开或者向他人提供检验报告的； （二）未按要求实施现场扦样，或者扦样方法、程序等不符合国家有关规定或者标准的； （三）存在其他违反扦样、检验管理规定行为的。 其他粮食质量安全检验机构和检验人员违反保密、扦样、检验管理等规定的，依照有关法律法规进行处理。"},{"i":46,"n":"第四十六条","txt":"粮食经营者在从事粮食收购、储存、销售出库、运输和政策性粮食购销活动中违反质量安全管理有关规定的，依照《粮食流通管理条例》等有关法律法规进行处理。粮食经营者在收购等环节发现不符合食品安全国家标准的粮食，未及时向粮食和储备行政管理等部门报告的，依照有关规定进行处理。"},{"i":47,"n":"第四十七条","txt":"大豆、油料和食用植物油的收购、储存、运输，政策性大豆、油料和食用植物油的购销等经营活动中的质量安全监管，适用本办法规定。"},{"i":48,"n":"第四十八条","txt":"省级粮食和储备行政管理部门可以结合本行政区域实际制定相应的实施细则。"},{"i":49,"n":"第四十九条","txt":"本办法由国家发展和改革委员会、国家粮食和物资储备局负责解释。"},{"i":50,"n":"第五十条","txt":"本办法自2023年10月1日起施行。《粮食质量安全监管办法》（国家发展改革委2016年第42号令）同时废止。"}],"nengyuanxiaolvbiaoshiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强节能管理，推动节能技术进步，提高用能产品能源效率，依据《中华人民共和国节约能源法》、《中华人民共和国产品质量法》、《中华人民共和国进出口商品检验法》及其实施条例、《中华人民共和国认证认可条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称能源效率标识（以下简称能效标识），是指表示用能产品能源效率等级等性能指标的一种信息标识，属于产品符合性标志的范畴。"},{"i":3,"n":"第三条","txt":"国家对节能潜力大、使用面广的用能产品实行能效标识管理。具体产品实行目录管理。 国家发展和改革委员会（以下简称国家发展改革委）、国家质量监督检验检疫总局（以下简称国家质检总局）和国家认证认可监督管理委员会（以下简称国家认监委）负责能效标识管理制度的建立并组织实施。国家发展改革委会同国家质检总局、国家认监委制定并公布《中华人民共和国实行能源效率标识的产品目录》（以下简称《目录》），规定统一适用的产品能效标准、实施规则、能效标识样式和规格。"},{"i":4,"n":"第四条","txt":"地方各级人民政府管理节能工作的部门（以下简称地方节能主管部门）、地方各级质量技术监督部门和出入境检验检疫机构（以下简称地方质检部门），在各自职责范围内对所辖区域内能效标识的使用实施监督管理。"},{"i":5,"n":"第五条","txt":"列入《目录》的用能产品生产者和进口商应当向国家质检总局和国家发展改革委授权的中国标准化研究院 （以下简称授权机构）备案能效标识及相关信息。"},{"i":6,"n":"第六条","txt":"生产者和进口商应当对列入《目录》的用能产品标注能效标识，根据国家统一规定的能效标识样式、规格以及标注规定印制和使用能效标识，并在产品包装物上或者使用说明书中予以说明。 列入《目录》的用能产品通过网络交易的，还应当在产品信息展示主页面醒目位置展示相应的能效标识。 在产品包装物、说明书、网络交易产品信息展示主页面以及广告宣传中使用的能效标识，可按比例放大或者缩小，并清晰可辨。"},{"i":7,"n":"第七条","txt":"能效标识的名称为“中国能效标识”（英文名称为China Energy Label），能效标识应当包括以下基本内容： （一）生产者名称或者简称； （二）产品规格型号； （三）能效等级； （四）能效指标； （五）依据的能源效率强制性国家标准编号； （六）能效信息码。 列入国家能效“领跑者”目录的产品，还应当包括能效“领跑者”相关信息。"},{"i":8,"n":"第八条","txt":"列入《目录》的用能产品生产者和进口商，可以利用自有检测实验室或者委托依法取得资质认定的第三方检验检测机构，对产品进行检测，并依据能源效率强制性国家标准，确定产品能效等级。 企业自有检测实验室应当依据相关产品能源效率强制性国家标准规定的检测方法和要求进行检测，如实出具产品能效检测报告。 第三方检验检测机构接受生产者和进口商的委托，应当依据相关产品能源效率强制性国家标准规定的检测方法和要求进行检测，保证检测结果客观公正、真实准确，保守受检产品和企业的商业秘密，并承担相应法律责任。"},{"i":9,"n":"第九条","txt":"利用自有检测实验室检测确定能效等级的生产者和进口商，应当保证其检测实验室具备按照能源效率强制性国家标准进行检测的能力，并鼓励其取得国家认可机构的认可。 利用自有检测实验室检测确定能效等级的生产者和进口商，对其检测实验室出具的产品能效检测报告负责，并承担相应法律责任。"},{"i":10,"n":"第十条","txt":"列入《目录》的用能产品，生产者应当于出厂前、进口商应当于进口前向授权机构申请备案。能效标识备案应当提交以下材料： （一）生产者营业执照或者登记注册证明复制件；进口商营业执照以及与境外生产者订立的相关合同复制件； （二）产品能效检测报告； （三）能效标识样本； （四）产品基本配置清单等有关材料； （五）利用自有检测实验室进行检测的，应当提供实验室检测能力证明材料（包括实验室人员能力、设备能力和检测管理规范），已经获得国家认可机构认可的，还应当提供相应认可证书复制件；利用第三方检验检测机构进行检测的，应当提供检验检测机构的资质认定证书复制件。 （六）由代理人提交备案材料的，应当有生产者或者进口商的委托代理文件等。 上述材料应当真实、准确、完整。 外文材料应当附有中文译本，并以中文文本为准。"},{"i":11,"n":"第十一条","txt":"进境的列入《目录》的用能产品符合下列情形之一的，可以免于标注能效标识及备案： （一）外国驻华使馆、领事馆或者国际组织驻华机构及其外交人员的自用物品； （二）香港、澳门特别行政区政府驻大陆官方机构及其工作人员的自用物品； （三）入境人员随身从境外带入境内的自用物品； （四）外国政府援助、赠送的物品； （五）为科研、测试所需的产品； （六）为考核技术引进生产线所需的零部件； （七）直接为最终用户维修目的所需的产品； （八）工厂生产线、成套生产线配套所需的设备和部件（不包含办公用品）。"},{"i":12,"n":"第十二条","txt":"能效标识内容发生变化的，应当重新备案。"},{"i":13,"n":"第十三条","txt":"授权机构应当对生产者和进口商使用的能效标识及产品能效检测报告进行核验。"},{"i":14,"n":"第十四条","txt":"授权机构应当自收到完整备案材料之日起10个工作日内完成能效标识的备案工作，并于备案完成之日起5个工作日内公告备案的能效标识样本。 能效标识备案不收取费用。"},{"i":15,"n":"第十五条","txt":"生产者和进口商应当对其标注的能效标识及相关信息的准确性负责。"},{"i":16,"n":"第十六条","txt":"销售者（含网络商品经营者）应当建立并执行进货检查验收制度，验明列入《目录》的用能产品能效标识，不得销售应当标注而未标注能效标识的产品。 第三方交易平台（场所）经营者对通过平台（场所）销售的列入《目录》的用能产品应当建立能效标识检查监控制度，发现违反本办法规定行为的，应当及时采取措施制止。"},{"i":17,"n":"第十七条","txt":"任何单位和个人不得伪造、冒用能效标识或者利用能效标识进行虚假宣传。"},{"i":18,"n":"第十八条","txt":"国家质检总局负责组织实施对能效标识使用的监督检查、专项检查和验证管理。 地方质检部门负责对所辖区域内能效标识的使用实施监督检查、专项检查和验证管理，发现有违反本办法规定行为的，通报同级节能主管部门，并通知授权机构。"},{"i":19,"n":"第十九条","txt":"授权机构应当撤销能效不合格产品生产者或者进口商的相关备案信息并及时公告。"},{"i":20,"n":"第二十条","txt":"列入《目录》的用能产品生产者、进口商、销售者（含网络商品经营者）、第三方交易平台（场所）经营者、企业自有检测实验室和第三方检验检测机构应当接受监督检查、专项检查和验证管理。 企业自有检测实验室、第三方检验检测机构在能效检测中，伪造检验检测结果或者出具虚假能效检测报告的，授权机构自发现之日起一年内不再采信其检验检测结果。"},{"i":21,"n":"第二十一条","txt":"授权机构应当建立规范的工作制度，客观、公正开展备案工作，保守备案产品和企业的商业秘密。"},{"i":22,"n":"第二十二条","txt":"任何单位和个人对违反本办法规定的行为，可以向地方节能主管部门、地方质检部门举报。地方节能主管部门、地方质检部门应当及时调查处理，并为举报人保密，授权机构应当予以配合。"},{"i":23,"n":"第二十三条","txt":"国家发展改革委、国家质检总局和国家认监委对违反本办法规定的行为建立信用记录，并纳入全国统一的信用信息共享交互平台。"},{"i":24,"n":"第二十四条","txt":"地方节能主管部门、地方质检部门依据《中华人民共和国节约能源法》等相关法律法规，在各自的职责范围内对违反本办法规定的行为进行处罚。"},{"i":25,"n":"第二十五条","txt":"生产、进口、销售不符合能源效率强制性国家标准的用能产品，依据《中华人民共和国节约能源法》第七十条予以处罚。"},{"i":26,"n":"第二十六条","txt":"在用能产品中掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的，或者进口属于掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的用能产品的，依据《中华人民共和国产品质量法》第五十条、《中华人民共和国进出口商品检验法》第三十五条的规定予以处罚。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，应当标注能效标识而未标注的，未办理能效标识备案的，使用的能效标识不符合有关样式、规格等标注规定的（包括不符合网络交易产品能效标识展示要求的），伪造、冒用能效标识或者利用能效标识进行虚假宣传的，依据《中华人民共和国节约能源法》第七十三条予以处罚。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，企业自有检测实验室、第三方检验检测机构在能效检测中，伪造检验检测结果或者出具虚假能效检测报告的，依据《中华人民共和国产品质量法》、《检验检测机构资质认定管理办法》予以处罚。"},{"i":29,"n":"第二十九条","txt":"从事能效标识管理的国家工作人员及授权机构工作人员，玩忽职守、滥用职权或者包庇纵容违法行为的，依法予以处分；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"本办法由国家发展改革委、国家质检总局负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2016年6月1日起施行。2004年8月13日国家发展改革委、国家质检总局令第17号发布的《能源效率标识管理办法》同时废止。"}],"nengyuanxiaolvbiaoshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强节能管理，推动节能技术进步，提高用能产品能源效率，依据《中华人民共和国节约能源法》、《中华人民共和国产品质量法》、《中华人民共和国进出口商品检验法》及其实施条例、《中华人民共和国认证认可条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称能源效率标识(以下简称能效标识)，是指表示用能产品能源效率等级等性能指标的一种信息标识，属于产品符合性标志的范畴。"},{"i":3,"n":"第三条","txt":"国家对节能潜力大、使用面广的用能产品实行能效标识管理。具体产品实行目录管理。 国家发展和改革委员会(以下简称国家发展改革委)、国家质量监督检验检疫总局(以下简称国家质检总局)和国家认证认可监督管理委员会(以下简称国家认监委)负责能效标识管理制度的建立并组织实施。国家发展改革委会同国家质检总局、国家认监委制定并公布《中华人民共和国实行能源效率标识的产品目录》(以下简称《目录》)，规定统一适用的产品能效标准、实施规则、能效标识样式和规格。"},{"i":4,"n":"第四条","txt":"地方各级人民政府管理节能工作的部门(以下简称地方节能主管部门)、地方各级质量技术监督部门和出入境检验检疫机构(以下简称地方质检部门)，在各自职责范围内对所辖区域内能效标识的使用实施监督管理。"},{"i":5,"n":"第五条","txt":"列入《目录》的用能产品生产者和进口商应当向国家质检总局和国家发展改革委授权的中国标准化研究院 (以下简称授权机构)备案能效标识及相关信息。"},{"i":6,"n":"第六条","txt":"生产者和进口商应当对列入《目录》的用能产品标注能效标识，根据国家统一规定的能效标识样式、规格以及标注规定印制和使用能效标识，并在产品包装物上或者使用说明书中予以说明。 列入《目录》的用能产品通过网络交易的，还应当在产品信息展示主页面醒目位置展示相应的能效标识。 在产品包装物、说明书、网络交易产品信息展示主页面以及广告宣传中使用的能效标识，可按比例放大或者缩小，并清晰可辨。"},{"i":7,"n":"第七条","txt":"能效标识的名称为“中国能效标识”(英文名称为China Energy Label)，能效标识应当包括以下基本内容： (一)生产者名称或者简称; (二)产品规格型号; (三)能效等级; (四)能效指标; (五)依据的能源效率强制性国家标准编号; (六)能效信息码。 列入国家能效“领跑者”目录的产品，还应当包括能效“领跑者”相关信息。"},{"i":8,"n":"第八条","txt":"列入《目录》的用能产品生产者和进口商，可以利用自有检测实验室或者委托依法取得资质认定的第三方检验检测机构，对产品进行检测，并依据能源效率强制性国家标准，确定产品能效等级。 企业自有检测实验室应当依据相关产品能源效率强制性国家标准规定的检测方法和要求进行检测，如实出具产品能效检测报告。 第三方检验检测机构接受生产者和进口商的委托，应当依据相关产品能源效率强制性国家标准规定的检测方法和要求进行检测，保证检测结果客观公正、真实准确，保守受检产品和企业的商业秘密，并承担相应法律责任。"},{"i":9,"n":"第九条","txt":"利用自有检测实验室检测确定能效等级的生产者和进口商，应当保证其检测实验室具备按照能源效率强制性国家标准进行检测的能力，并鼓励其取得国家认可机构的认可。 利用自有检测实验室检测确定能效等级的生产者和进口商，对其检测实验室出具的产品能效检测报告负责，并承担相应法律责任。"},{"i":10,"n":"第十条","txt":"列入《目录》的用能产品，生产者应当于出厂前、进口商应当于进口前向授权机构申请备案。能效标识备案应当提交以下材料： (一)生产者营业执照或者登记注册证明复制件;进口商营业执照以及与境外生产者订立的相关合同复制件; (二)产品能效检测报告; (三)能效标识样本; (四)产品基本配置清单等有关材料; (五)利用自有检测实验室进行检测的，应当提供实验室检测能力证明材料(包括实验室人员能力、设备能力和检测管理规范)，已经获得国家认可机构认可的，还应当提供相应认可证书复制件;利用第三方检验检测机构进行检测的，应当提供检验检测机构的资质认定证书复制件。 (六)由代理人提交备案材料的，应当有生产者或者进口商的委托代理文件等。 上述材料应当真实、准确、完整。 外文材料应当附有中文译本，并以中文文本为准。"},{"i":11,"n":"第十一条","txt":"进境的列入《目录》的用能产品符合下列情形之一的，可以免于标注能效标识及备案： (一)外国驻华使馆、领事馆或者国际组织驻华机构及其外交人员的自用物品; (二)香港、澳门特别行政区政府驻大陆官方机构及其工作人员的自用物品; (三)入境人员随身从境外带入境内的自用物品; (四)外国政府援助、赠送的物品; (五)为科研、测试所需的产品; (六)为考核技术引进生产线所需的零部件; (七)直接为最终用户维修目的所需的产品; (八)工厂生产线、成套生产线配套所需的设备和部件(不包含办公用品)。"},{"i":12,"n":"第十二条","txt":"能效标识内容发生变化的，应当重新备案。"},{"i":13,"n":"第十三条","txt":"授权机构应当对生产者和进口商使用的能效标识及产品能效检测报告进行核验。"},{"i":14,"n":"第十四条","txt":"授权机构应当自收到完整备案材料之日起10个工作日内完成能效标识的备案工作，并于备案完成之日起5个工作日内公告备案的能效标识样本。 能效标识备案不收取费用。"},{"i":15,"n":"第十五条","txt":"生产者和进口商应当对其标注的能效标识及相关信息的准确性负责。"},{"i":16,"n":"第十六条","txt":"销售者(含网络商品经营者)应当建立并执行进货检查验收制度，验明列入《目录》的用能产品能效标识，不得销售应当标注而未标注能效标识的产品。 第三方交易平台(场所)经营者对通过平台(场所)销售的列入《目录》的用能产品应当建立能效标识检查监控制度，发现违反本办法规定行为的，应当及时采取措施制止。"},{"i":17,"n":"第十七条","txt":"任何单位和个人不得伪造、冒用能效标识或者利用能效标识进行虚假宣传。"},{"i":18,"n":"第十八条","txt":"国家质检总局负责组织实施对能效标识使用的监督检查、专项检查和验证管理。 地方质检部门负责对所辖区域内能效标识的使用实施监督检查、专项检查和验证管理，发现有违反本办法规定行为的，通报同级节能主管部门，并通知授权机构。"},{"i":19,"n":"第十九条","txt":"授权机构应当撤销能效不合格产品生产者或者进口商的相关备案信息并及时公告。"},{"i":20,"n":"第二十条","txt":"列入《目录》的用能产品生产者、进口商、销售者(含网络商品经营者)、第三方交易平台(场所)经营者、企业自有检测实验室和第三方检验检测机构应当接受监督检查、专项检查和验证管理。 企业自有检测实验室、第三方检验检测机构在能效检测中，伪造检验检测结果或者出具虚假能效检测报告的，授权机构自发现之日起一年内不再采信其检验检测结果。"},{"i":21,"n":"第二十一条","txt":"授权机构应当建立规范的工作制度，客观、公正开展备案工作，保守备案产品和企业的商业秘密。"},{"i":22,"n":"第二十二条","txt":"任何单位和个人对违反本办法规定的行为，可以向地方节能主管部门、地方质检部门举报。地方节能主管部门、地方质检部门应当及时调查处理，并为举报人保密，授权机构应当予以配合。"},{"i":23,"n":"第二十三条","txt":"国家发展改革委、国家质检总局和国家认监委对违反本办法规定的行为建立信用记录，并纳入全国统一的信用信息共享交互平台。"},{"i":24,"n":"第二十四条","txt":"地方节能主管部门、地方质检部门依据《中华人民共和国节约能源法》等相关法律法规，在各自的职责范围内对违反本办法规定的行为进行处罚。"},{"i":25,"n":"第二十五条","txt":"生产、进口、销售不符合能源效率强制性国家标准的用能产品，依据《中华人民共和国节约能源法》第七十条予以处罚。"},{"i":26,"n":"第二十六条","txt":"在用能产品中掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的，或者进口属于掺杂、掺假，以假充真、以次充好，以不合格品冒充合格品的用能产品的，依据《中华人民共和国产品质量法》第五十条、《中华人民共和国进出口商品检验法》第三十五条的规定予以处罚。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，应当标注能效标识而未标注的，未办理能效标识备案的，使用的能效标识不符合有关样式、规格等标注规定的(包括不符合网络交易产品能效标识展示要求的)，伪造、冒用能效标识或者利用能效标识进行虚假宣传的，依据《中华人民共和国节约能源法》第七十三条予以处罚。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，企业自有检测实验室、第三方检验检测机构在能效检测中，伪造检验检测结果或者出具虚假能效检测报告的，依据《中华人民共和国产品质量法》、《检验检测机构资质认定管理办法》予以处罚。"},{"i":29,"n":"第二十九条","txt":"从事能效标识管理的国家工作人员及授权机构工作人员，玩忽职守、滥用职权或者包庇纵容违法行为的，依法予以处分;构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"本办法由国家发展改革委、国家质检总局负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2016年6月1日起施行。2004年8月13日国家发展改革委、国家质检总局令第17号发布的《能源效率标识管理办法》同时废止。"}],"ziyoumaoyishiyanquwaishangtouzizhunrutebieguanlicua938e7-2":[],"ziyoumaoyishiyanquwaishangtouzizhunrutebieguanlicua938e7":[],"jienengjianchabanfa":[{"i":1,"n":"第一条","txt":"为规范节能监察行为，提升节能监察效能，提高全社会能源利用效率，依据《中华人民共和国节约能源法》等有关法律、法规，结合节能监察工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称节能监察，是指依法开展节能监察的机构(以下简称节能监察机构)对能源生产、经营、使用单位和其他相关单位(以下简称被监察单位)执行节能法律、法规、规章和强制性节能标准的情况等进行监督检查，对违法违规用能行为予以处理，并提出依法用能、合理用能建议的行为。"},{"i":3,"n":"第三条","txt":"国家发展和改革委员会负责全国节能监察工作的统筹协调和指导。 县级以上地方人民政府管理节能工作的部门负责本行政区域内节能监察工作的统筹协调和指导。"},{"i":4,"n":"第四条","txt":"节能监察应当遵循合法、公开、公平、公正的原则。"},{"i":5,"n":"第五条","txt":"省、市、县三级节能监察机构的节能监察任务分工，由省级人民政府管理节能工作的部门结合本地实际确定。 上一级节能监察机构应当对下一级节能监察机构的业务进行指导。"},{"i":6,"n":"第六条","txt":"节能监察机构应当开展下列工作： (一)监督检查被监察单位执行节能法律、法规、规章和强制性节能标准的情况，督促被监察单位依法用能、合理用能，依法处理违法违规行为; (二)受理对违法违规用能行为的举报和投诉，办理其他行政执法单位依法移送或者政府有关部门交办的违法违规用能案件; (三)协助政府管理节能工作的部门和有关部门开展其他节能监督管理工作; (四)节能法律、法规、规章和规范性文件规定的其他工作。"},{"i":7,"n":"第七条","txt":"节能监察机构应当配备必要的取证仪器和装备，具有从事节能监察所需的现场检测取证和合理用能评估等能力。"},{"i":8,"n":"第八条","txt":"节能监察人员应当取得行政执法证件，并具备开展节能监察工作需要的专业素质和业务能力。 节能监察机构应当定期对节能监察人员进行业务培训。"},{"i":9,"n":"第九条","txt":"实施节能监察不得向被监察单位收取费用。"},{"i":10,"n":"第十条","txt":"节能监察机构应当建立健全相关保密制度，保守被监察单位的技术和商业秘密。"},{"i":11,"n":"第十一条","txt":"节能监察机构依照授权或者委托，具体实施节能监察工作。节能监察应当包括下列内容： (一)建立落实节能目标责任制、节能计划、节能管理和技术措施等情况; (二)落实固定资产投资项目节能评估和审查制度的情况，包括节能评估和审查实施情况、节能审查意见落实情况等; (三)执行用能设备和生产工艺淘汰制度的情况; (四)执行强制性节能标准的情况; (五)执行能源统计、能源利用状况分析和报告制度的情况; (六)执行设立能源管理岗位、聘任能源管理负责人等有关制度的情况; (七)执行用能产品能源效率标识制度的情况; (八)公共机构采购和使用节能产品、设备以及开展能源审计的情况; (九)从事节能咨询、设计、评估、检测、审计、认证等服务的机构贯彻节能要求、提供信息真实性等情况; (十)节能法律、法规、规章规定的其他应当实施节能监察的事项。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府管理节能工作的部门应当会同有关部门结合本地实际，编制节能监察计划并组织节能监察机构实施。 节能监察计划的实施情况应当报本级人民政府管理节能工作的部门。"},{"i":13,"n":"第十三条","txt":"节能监察分为书面监察和现场监察。 实施书面监察，应当将实施监察的依据、内容、时间和要求书面通知被监察单位。 实施现场监察，应当于实施监察的五日前将监察的依据、内容、时间和要求书面通知被监察单位。办理涉嫌违法违规案件、举报投诉和应当以抽查方式实施的节能监察除外。"},{"i":14,"n":"第十四条","txt":"实施书面监察时，被监察单位应当按照书面通知要求如实报送材料。节能监察机构应当在二十个工作日内对被监察单位报送材料的完整性、真实性，以及是否符合节能法律、法规、规章和强制性节能标准等情况进行审查。 被监察单位所报材料信息不完整的，节能监察机构可以要求被监察单位在五个工作日内补充完善，补充完善所用时间不计入审查期限。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，节能监察机构应当实施现场监察： (一)节能监察计划规定应当进行现场监察的; (二)书面监察发现涉嫌违法违规的; (三)需要对被监察单位的能源利用状况进行现场监测的; (四)需要现场确认被监察单位落实限期整改通知书要求的; (五)被监察单位主要耗能设备、生产工艺或者能源利用状况发生重大变化影响节能的; (六)对举报、投诉内容需要现场核实的; (七)应当实施现场节能监察的其他情形。"},{"i":16,"n":"第十六条","txt":"现场监察应当有两名以上节能监察人员在场，并出示有效的行政执法证件，告知被监察单位实施节能监察的依据、内容、要求和方法，并制作现场监察笔录，必要时还应当制作询问笔录。 监察笔录和询问笔录应当如实记录实施节能监察的时间、地点、内容、参加人员、现场监察和询问的实际情况，并由节能监察人员和被监察单位的法定代表人或者其委托人、被询问人确认并签名;拒绝签名的，应当由两名以上节能监察人员在监察笔录或者询问笔录中如实注明，不影响监察结果的认定。"},{"i":17,"n":"第十七条","txt":"实施现场监察可以采取下列措施： (一)进入有关场所进行勘察、采样、拍照、录音、录像、制作笔录等; (二)查阅、复制或者摘录与节能监察事项有关的文件、账目等资料; (三)约见、询问有关人员，要求说明有关事项、提供相关材料; (四)对用能产品、设备和生产工艺的能源利用状况等进行监测和分析评价; (五)责令被监察单位停止明显违法违规用能行为; (六)节能法律、法规、规章规定可以采取的其他措施。"},{"i":18,"n":"第十八条","txt":"被监察单位有违反节能法律、法规、规章和强制性节能标准行为的，节能监察机构应当下达限期整改通知书。 被监察单位有不合理用能行为，但尚未违反节能法律、法规、规章和强制性节能标准的，节能监察机构应当下达节能监察建议书，提出节能建议或者节能措施。 节能监察机构在作出限期整改通知书前，应当充分听取被监察单位的意见，对被监察单位提出的事实、理由和证据应当进行复核。被监察单位提出的事实、理由和证据成立的，节能监察机构应当采纳。 限期整改通知书或者节能监察建议书应当在对本单位的节能监察活动结束后十五日内送达被监察单位。 被监察单位对限期整改通知书有异议的，可依法申请行政复议或者提起行政诉讼。"},{"i":19,"n":"第十九条","txt":"被监察单位应当按照限期整改通知书的要求进行整改。节能监察机构应当进行跟踪检查并督促落实。 被监察单位的整改期限一般不超过六个月。确需延长整改期限的，被监察单位应当在期限届满十五日前以书面形式向节能监察机构提出延期申请，节能监察机构应当在期限届满前作出是否准予延期的决定，延期最长不得超过三个月。节能监察机构未在期限届满前作出决定的，视为同意延期。"},{"i":20,"n":"第二十条","txt":"节能监察机构在同一年度内对被监察单位的同一监察内容不得重复监察。但确认被监察单位整改落实情况、处理举报投诉和由上一级节能监察机构组织的抽查除外。"},{"i":21,"n":"第二十一条","txt":"节能监察人员与被监察单位有利害关系或者其他关系，可能影响公正监察的，应当回避。"},{"i":22,"n":"第二十二条","txt":"建立节能监察情况公布制度。节能监察机构应当向社会公布违反节能法律、法规和标准的企业名单、整改期限、措施要求等节能监察结果。"},{"i":23,"n":"第二十三条","txt":"被监察单位应当配合节能监察人员依法实施节能监察。 被监察单位拒绝依法实施的节能监察的，由有处罚权的节能监察机构或委托开展节能监察的单位给予警告，责令限期改正;拒不改正的，处1万元以上3万元以下罚款。阻碍依法实施节能监察的，移交公安机关按照《治安管理处罚法》相关规定处理，构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"被监察单位在整改期限届满后，整改未达到要求的，由节能监察机构将相关情况向社会公布，并纳入社会信用体系记录。被监察单位仍有违反节能法律、法规、规章和强制性节能标准的用能行为的，由节能监察机构将有关线索转交有处罚权的机关进行处理。"},{"i":25,"n":"第二十五条","txt":"节能监察机构实施节能监察有违法违规行为的，被监察单位有权向本级人民政府管理节能监察机构的机构或者上一级节能监察机构投诉。 节能监察人员滥用职权、玩忽职守、徇私舞弊，有下列情形之一的，由有管理权限的机构依法给予处分;构成犯罪的，依法追究刑事责任： (一)泄露被监察单位的技术秘密和商业秘密的; (二)利用职务之便非法谋取利益的; (三)实施节能监察时向被监察单位收费或者变相收费的; (四)有其他违法违规行为并造成较为严重后果的。"},{"i":26,"n":"第二十六条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":27,"n":"第二十七条","txt":"本办法自2016年3月1日起施行。"}],"xibudiqugulileichanyemulu":[],"pingbiaozhuanjiahepingbiaozhuanjiakuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强评标专家和评标专家库管理，提高评标专家队伍整体素质，促进评标专家资源共享，保证评标活动的公平、公正，提高评标质量，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》等法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于评标专家的选聘、抽取、管理以及评标专家库的组建、使用、共享、监督等活动。"},{"i":3,"n":"第三条","txt":"本办法所称评标专家，是指符合本办法规定的条件，经评标专家库组建单位聘任，以独立身份为招标人提供评标服务的技术、经济等方面的专业人员。 本办法所称评标专家库，是指存储评标专家信息，并具备抽取专家参加评标、辅助评标专家库组建单位管理、向评标专家提供必要服务等功能的电子信息系统。"},{"i":4,"n":"第四条","txt":"国务院发展改革部门指导和协调全国评标专家和评标专家库管理工作。国务院有关招标投标行政监督部门按照职责分工，对评标专家的评标活动和评标专家库的组建、使用、共享实施行政监督。 地方各级人民政府有关部门在各自职责范围内负责评标专家和评标专家库的监督管理工作。"},{"i":5,"n":"第五条","txt":"国家实行统一的评标专家专业分类标准和评标专家库共享技术标准，推动专家资源跨区域、跨行业、跨评标专家库共享，应用数智技术提高评标专家管理水平，推广远程异地评标等评标组织形式。"},{"i":6,"n":"第六条","txt":"入选评标专家库的专业人员，应当具备下列条件： （一）具备良好的职业道德； （二）从事相关专业领域工作满八年并具有高级职称或者同等专业水平； （三）具备参加评标工作所需要的专业知识和实践经验； （四）熟悉有关招标投标的法律法规； （五）熟练掌握电子化评标技能； （六）具备正常履行职责的身体和年龄条件； （七）法律、法规、规章规定的其他条件。 评标专家库组建单位应当根据前款所列条件，制定入选评标专家库的具体标准，并向社会公布。"},{"i":7,"n":"第七条","txt":"存在下列情形之一的，不得入选评标专家库： （一）无民事行为能力或者限制民事行为能力的； （二）被有关行政监督部门取消担任评标委员会成员资格的； （三）被开除公职的； （四）受过刑事处罚的； （五）被列入严重失信主体名单的； （六）法律、法规、规章规定的其他情形。"},{"i":8,"n":"第八条","txt":"评标专家享有下列权利： （一）接受招标人聘请，担任评标委员会成员； （二）依法对投标文件进行独立评审，提出评审意见，不受任何单位或者个人的干预； （三）接受参加评标活动的劳务报酬； （四）法律、法规、规章规定的其他权利。"},{"i":9,"n":"第九条","txt":"评标专家负有下列义务： （一）如实填报并及时更新个人基本信息，配合评标专家库组建单位的管理工作； （二）存在法定回避情形的，主动提出回避； （三）遵守评标工作纪律和评标现场秩序； （四）按照招标文件确定的评标标准和方法客观公正地进行评标； （五）协助、配合招标人处理异议，按规定程序复核、纠正评标报告中的错误； （六）发现违法违规行为主动向招标人、有关行政监督部门反映，协助、配合有关行政监督部门、纪检监察机关、司法机关、审计部门开展监督、检查、调查； （七）法律、法规、规章规定的其他义务。"},{"i":10,"n":"第十条","txt":"评标专家库由法律、行政法规规定的组建单位依法组建。评标专家库的组建活动应当公开，接受公众监督。"},{"i":11,"n":"第十一条","txt":"组建评标专家库，应当具备下列条件： （一）有符合本办法规定条件的评标专家，且专家总人数不得少于2000人； （二）有满足评标需要的专业分类； （三）有满足异地抽取、随机抽取评标专家需要的必要条件； （四）符合网络安全和数据安全管理有关规定； （五）有负责系统运行和维护管理的专门机构和人员。"},{"i":12,"n":"第十二条","txt":"专业人员入选评标专家库，实行个人申请和单位推荐相结合的方式。申请入库的专业人员应当提交下列材料： （一）个人申请书； （二）所在工作单位或者退休前原单位的推荐书； （三）符合本办法第六条规定条件的证明材料； （四）关于入库信息真实性合法性和依法履职的书面承诺； （五）法律、法规、规章规定的其他材料。"},{"i":13,"n":"第十三条","txt":"评标专家库组建单位应当对申请人或者被推荐人进行审核，决定是否聘任入库。审核过程及结果应当全过程记录并存档备查。 评标专家库组建单位应当组织测试或者评估，确认拟入库专家是否符合本办法第六条第一款第三项至第五项规定的条件。"},{"i":14,"n":"第十四条","txt":"评标专家库组建单位应当根据评标专家的入库申请材料和测试、评估情况，确定评标专家参加评标的专业类别。"},{"i":15,"n":"第十五条","txt":"评标专家实行聘期制，聘期届满自动解除聘任关系。评标专家可以在聘期届满前提出续聘申请，评标专家库组建单位应当按照入库标准进行审核，决定是否继续聘任。 评标专家库组建单位结合实际确定聘期，一般为三年至五年。"},{"i":16,"n":"第十六条","txt":"依法必须进行招标项目的评标专家，应当从评标专家库中随机抽取。在一个评标专家库中无法随机抽取到足够数量专家的，应当从其他依法组建的相关评标专家库中随机抽取。"},{"i":17,"n":"第十七条","txt":"技术复杂、专业性强或者国家有特殊要求的依法必须进行招标项目，采取随机抽取方式确定的专家难以胜任评标工作的，招标人可以依法直接确定评标专家，并向有关行政监督部门报告。"},{"i":18,"n":"第十八条","txt":"政府投资项目的评标专家，应当从国务院有关部门组建的评标专家库或者省级综合评标专家库中抽取。"},{"i":19,"n":"第十九条","txt":"评标专家库组建单位、招标投标电子交易系统运行服务机构应当建立健全与远程异地评标相适应的评标专家资源共享和协同管理机制，为评标专家远程异地参加评标提供服务保障，为有关行政监督部门开展监督提供支持。"},{"i":20,"n":"第二十条","txt":"评标专家库组建单位承担评标专家档案记录、教育培训、履职考核、动态调整等日常管理责任，加强评标专家全周期管理。 评标专家库组建单位不得以任何名义非法控制、干预或者影响评标专家的具体评标活动。"},{"i":21,"n":"第二十一条","txt":"评标专家库组建单位应当建立并永久保存评标专家电子档案，详细记录评标专家的基本信息、参加评标的具体情况、参加教育培训和履职考核的情况，并进行动态更新。"},{"i":22,"n":"第二十二条","txt":"评标专家库组建单位应当加强对评标专家的教育培训，每年组织招标投标有关专业知识、法律法规和电子化评标技能等方面培训，并开展廉洁教育。 评标专家库组建单位可以结合教育培训情况开展专项测试。"},{"i":23,"n":"第二十三条","txt":"评标专家库组建单位应当建立评标专家年度履职考核制度，制定考核标准，并向社会公布。考核标准应当包含下列内容： （一）响应抽取参加评标情况； （二）遵守评标工作纪律和评标现场秩序情况； （三）评标客观公正情况； （四）协助、配合招标人处理异议、复核评标结果情况； （五）协助、配合有关行政监督部门、纪检监察机关、司法机关、审计部门开展监督、检查、调查情况； （六）参加教育培训情况； （七）其他能够反映评标专家履职情况的内容。 评标专家库组建单位应当结合评标专家年度履职考核结论、在库年限、参加评标频次等开展履职风险评估，并根据评估情况调整抽取频次、设置抽取间隔期，防范评标专家履职风险。"},{"i":24,"n":"第二十四条","txt":"年度履职考核结论应当通知评标专家。评标专家对考核结论有异议的，有权向评标专家库组建单位申请复核，评标专家库组建单位应当在收到异议后30日内核实有关情况并作出答复。"},{"i":25,"n":"第二十五条","txt":"评标专家年度履职考核不合格的，评标专家库组建单位应当与其解除聘任关系，调整出库，并通报入库推荐单位。"},{"i":26,"n":"第二十六条","txt":"对于入库后不再具备本办法第六条规定的条件，不再符合评标专家库组建单位制定的入库具体标准，或者存在本办法第七条规定情形的评标专家，评标专家库组建单位应当在发现有关情形后30日内与其解除聘任关系，调整出库，并通报入库推荐单位。"},{"i":27,"n":"第二十七条","txt":"评标专家自愿退出评标专家库的，应当向评标专家库组建单位提出书面申请。 评标专家库组建单位收到申请后，应当停止抽取该评标专家参加评标，在10日内与其解除聘任关系，并调整出库。"},{"i":28,"n":"第二十八条","txt":"评标专家库组建单位应当结合经济社会发展水平和评标专家工作价值，制定评标专家劳务报酬标准和支付机制。"},{"i":29,"n":"第二十九条","txt":"评标专家有下列情形之一的，由有关行政监督部门责令改正，没收收受的财物，并依法处以罚款；情节严重的，禁止其在一定期限内参加依法必须进行招标项目的评标；情节特别严重的，取消其担任评标委员会成员的资格，并向社会公布；涉嫌违纪违法犯罪的，及时移送纪检监察机关、司法机关处理。 （一）提供虚假材料入库的； （二）应当回避而不回避的； （三）擅离职守或者扰乱评标现场秩序的； （四）不按照招标文件确定的评标标准和方法进行评标，或者对依法应当否决的投标不提出否决意见的； （五）与招标人、招标代理机构、投标人或者其他利害关系人私下接触或者相互串通的； （六）向招标人征询确定中标人的意向，或者接受任何单位、个人提出的倾向、排斥特定投标人要求的； （七）暗示或者诱导投标人作出澄清、说明，或者接受投标人主动提出的澄清、说明的； （八）对其他评标委员会成员的独立评标施加不当影响的； （九）违法透露对投标文件的评审"},{"i":30,"n":"第三十条","txt":"评标专家对评标行为终身负责，不因退休或者与评标专家库组建单位解除聘任关系等免予追责。 评标专家存在本办法第二十九条第一款所列情形的，除依法给予行政处罚外，评标专家库组建单位应当作进一步核实，依照本办法第二十五条、第二十六条规定调整出库，并将处理结果通报其入库推荐单位；涉嫌违纪违法犯罪的，及时移送纪检监察机关、司法机关处理。 评标专家所在工作单位根据专家职务晋升、职称评审等工作需要，可以查询评标专家参加评标情况并作为参考；涉及国家秘密、商业秘密或者个人隐私的除外。"},{"i":31,"n":"第三十一条","txt":"评标专家不履行本办法第九条规定的义务，给招标人造成损失的，依法承担赔偿责任。"},{"i":32,"n":"第三十二条","txt":"评标专家库组建单位有下列情形之一的，由有关行政监督部门责令改正；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分；涉嫌违纪违法犯罪的，及时移送纪检监察机关、司法机关处理。 （一）组建的评标专家库不符合本办法规定的； （二）未按本办法规定开展评标专家管理的； （三）违法泄露评标委员会成员名单的； （四）以管理为名非法控制、干预或者影响评标专家的评标活动的； （五）利用评标专家库开展其他业务谋取利益的； （六）其他滥用职权、玩忽职守、徇私舞弊等违法违规行为。 法律、法规对前款规定行为的处罚另有规定的，从其规定。"},{"i":33,"n":"第三十三条","txt":"招标投标电子交易系统运行服务机构违法泄露评标委员会成员名单的，依法处以罚款；对负有责任的领导人员和直接责任人员依法给予处分；涉嫌违纪违法犯罪的，及时移送纪检监察机关、司法机关处理。"},{"i":34,"n":"第三十四条","txt":"依法必须进行招标项目的招标人违法组建评标委员会，或者违法确定、更换评标委员会成员的，由有关行政监督部门责令改正，可以处十万元以下的罚款；对负有责任的领导人员和直接责任人员依法给予处分；涉嫌违纪违法犯罪的，及时移送纪检监察机关、司法机关处理。 政府投资项目的招标人不按照本办法规定抽取专家的，由有关行政监督部门责令改正；对负有责任的领导人员和直接责任人员依法给予处分；涉嫌违纪违法犯罪的，及时移送纪检监察机关、司法机关处理。 违法确定或者更换的评标委员会成员作出的评标结论无效。"},{"i":35,"n":"第三十五条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":36,"n":"第三十六条","txt":"本办法自2025年1月1日起实施。原《评标专家和评标专家库管理暂行办法》（国家发展计划委员会令2003年第29号）同时废止。"}],"pingbiaozhuanjiahepingbiaozhuanjiakuguanlizanxingb220adc":[{"i":1,"n":"第一条","txt":"为加强对评标专家的监督管理，健全评标专家库制度，保证评标活动的公平、公正，提高评标质量，根据《中华人民共和国招标投标法》(简称为《招标投标法》)、《中华人民共和国招标投标法实施条例》(简称《招标投标法实施条例》)，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于评标专家的资格认定、入库及评标专家库的组建、使用、管理活动。"},{"i":3,"n":"第三条","txt":"评标专家库由省级(含，下同)以上人民政府有关部门或者依法成立的招标代理机构依照《招标投标法》、《招标投标法实施条例》以及国家统一的评标专家专业分类标准和管理办法的规定自主组建。 评标专家库的组建活动应当公开，接受公众监督。"},{"i":4,"n":"第四条","txt":"省级人民政府、省级以上人民政府有关部门、招标代理机构应当加强对其所建评标专家库及评标专家的管理，但不得以任何名义非法控制、干预或者影响评标专家的具体评标活动。"},{"i":5,"n":"第五条","txt":"政府投资项目的评标专家，必须从政府或者政府有关部门组建的评标专家库中抽取。"},{"i":6,"n":"第六条","txt":"省级人民政府、省级以上人民政府有关部门组建评标专家库，应当有利于打破地区封锁，实现评标专家资源共享。 省级人民政府和国务院有关部门应当组建跨部门、跨地区的综合评标专家库。"},{"i":7,"n":"第七条","txt":"入选评标专家库的专家，必须具备如下条件： (一)从事相关专业领域工作满八年并具有高级职称或同等专业水平; (二)熟悉有关招标投标的法律法规; (三)能够认真、公正、诚实、廉洁地履行职责; (四)身体健康，能够承担评标工作; (五)法规规章规定的其他条件。"},{"i":8,"n":"第八条","txt":"评标专家库应当具备下列条件： (一)具有符合本办法第七条规定条件的评标专家，专家总数不得少于500人; (二)有满足评标需要的专业分类; (三)有满足异地抽取、随机抽取评标专家需要的必要设施和条件; (四)有负责日常维护管理的专门机构和人员。"},{"i":9,"n":"第九条","txt":"专家入选评标专家库，采取个人申请和单位推荐两种方式。采取单位推荐方式的，应事先征得被推荐人同意。 个人申请书或单位推荐书应当存档备查。个人申请书或单位推荐书应当附有符合本办法第七条规定条件的证明材料。"},{"i":10,"n":"第十条","txt":"组建评标专家库的省级人民政府、政府部门或者招标代理机构，应当对申请人或被推荐人进行评审，决定是否接受申请或者推荐，并向符合本办法第七条规定条件的申请人或被推荐人颁发评标专家证书。 评审过程及结果应做成书面记录，并存档备查。 组建评标专家库的政府部门，可以对申请人或者被推荐人进行必要的招标投标业务和法律知识培训。"},{"i":11,"n":"第十一条","txt":"组建评标专家库的省级人民政府、政府部门或者招标代理机构，应当为每位入选专家建立档案，详细记载评标专家评标的具体情况。"},{"i":12,"n":"第十二条","txt":"组建评标专家库的省级人民政府、政府部门或者招标代理机构，应当建立年度考核制度，对每位入选专家进行考核。评标专家因身体健康、业务能力及信誉等原因不能胜任评标工作的，停止担任评标专家，并从评标专家库中除名。"},{"i":13,"n":"第十三条","txt":"评标专家享有下列权利： (一)接受招标人或其招标代理机构聘请，担任评标委员会成员; (二)依法对投标文件进行独立评审，提出评审意见，不受任何单位或者个人的干预; (三)接受参加评标活动的劳务报酬; (四)国家规定的其他权利。"},{"i":14,"n":"第十四条","txt":"评标专家负有下列义务： (一)有《招标投标法》第三十七条、《招标投标法实施条例》第四十六条和《评标委员会和评标方法暂行规定》第十二条规定情形之一的，应当主动提出回避; (二)遵守评标工作纪律，不得私下接触投标人，不得收受投标人或者其他利害关系人的财物或者其他好处，不得透露对投标文件的评审和比较、中标候选人的推荐情况以及与评标有关的其他情况; (三)客观公正地进行评标; (四)协助、配合有关行政监督部门的监督、检查; (五)国家规定的其他义务。"},{"i":15,"n":"第十五条","txt":"评标专家有下列情形之一的，由有关行政监督部门责令改正;情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标;情节特别严重的，取消其担任评标委员会成员的资格： (一)应当回避而不回避; (二)擅离职守; (三)不按照招标文件规定的评标标准和方法评标; (四)私下接触投标人; (五)向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求; (六)对依法应当否决的投标不提出否决意见; (七)暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明; (八)其他不客观、不公正履行职务的行为。 评标委员会成员收受投标人的财物或者其他好处的，评标委员会成员或者与评标活动有关的工作人员向他人透露对投标文件的评审和比较、中标候选人的推荐以及与评标有关的其他情况的，给予警告，没收收受的财物，可以并处三千元以上五万元以下的罚款;对有所列违法行"},{"i":16,"n":"第十六条","txt":"组建评标专家库的政府部门或者招标代理机构有下列情形之一的，由有关行政监督部门给予警告;情节严重的，暂停直至取消招标代理机构相应的招标代理资格： (一)组建的评标专家库不具备本办法规定条件的; (二)未按本办法规定建立评标专家档案或对评标专家档案作虚假记载的; (三)以管理为名，非法干预评标专家的评标活动的。 法律法规对前款规定的行为处罚另有规定的，从其规定。"},{"i":17,"n":"第十七条","txt":"依法必须进行招标的项目的招标人不按照规定组建评标委员会，或者确定、更换评标委员会成员违反《招标投标法》和《招标投标法实施条例》规定的，由有关行政监督部门责令改正，可以处十万元以下的罚款，对单位直接负责的主管人员和其他直接责任人员依法给予处分;违法确定或者更换的评标委员会成员作出的评审结论无效，依法重新进行评审。 政府投资项目的招标人或其委托的招标代理机构不遵守本办法第五条的规定，不从政府或者政府有关部门组建的评标专家库中抽取专家的，评标无效;情节严重的，由政府有关部门依法给予警告。"},{"i":18,"n":"第十八条","txt":"本办法由国家发展改革委负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自二〇〇三年四月一日起实施。"}],"pingbiaoweiyuanhuihepingbiaofangfazanxingguiding-2":[{"i":1,"n":"第一条","txt":"为了规范评标活动，保证评标的公平、公正，维护招标投标活动当事人的合法权益，依照《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于依法必须招标项目的评标活动。"},{"i":3,"n":"第三条","txt":"评标活动遵循公平、公正、科学、择优的原则。"},{"i":4,"n":"第四条","txt":"评标活动依法进行，任何单位和个人不得非法干预或者影响评标过程和结果。"},{"i":5,"n":"第五条","txt":"招标人应当采取必要措施，保证评标活动在严格保密的情况下进行。"},{"i":6,"n":"第六条","txt":"评标活动及其当事人应当接受依法实施的监督。 有关行政监督部门依照国务院或者地方政府的职责分工，对评标活动实施监督，依法查处评标活动中的违法行为。"},{"i":7,"n":"第七条","txt":"评标委员会依法组建，负责评标活动，向招标人推荐中标候选人或者根据招标人的授权直接确定中标人。"},{"i":8,"n":"第八条","txt":"评标委员会由招标人负责组建。 评标委员会成员名单一般应于开标前确定。评标委员会成员名单在中标结果确定前应当保密。"},{"i":9,"n":"第九条","txt":"评标委员会由招标人或其委托的招标代理机构熟悉相关业务的代表，以及有关技术、经济等方面的专家组成，成员人数为五人以上单数，其中技术、经济等方面的专家不得少于成员总数的三分之二。 评标委员会设负责人的，评标委员会负责人由评标委员会成员推举产生或者由招标人确定。评标委员会负责人与评标委员会的其他成员有同等的表决权。"},{"i":10,"n":"第十条","txt":"评标委员会的专家成员应当从依法组建的专家库内的相关专家名单中确定。 按前款规定确定评标专家，可以采取随机抽取或者直接确定的方式。一般项目，可以采取随机抽取的方式;技术复杂、专业性强或者国家有特殊要求的招标项目，采取随机抽取方式确定的专家难以保证胜任的，可以由招标人直接确定。"},{"i":11,"n":"第十一条","txt":"评标专家应符合下列条件： (一)从事相关专业领域工作满八年并具有高级职称或者同等专业水平; (二)熟悉有关招标投标的法律法规，并具有与招标项目相关的实践经验; (三)能够认真、公正、诚实、廉洁地履行职责。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，不得担任评标委员会成员： (一)投标人或者投标人主要负责人的近亲属; (二)项目主管部门或者行政监督部门的人员; (三)与投标人有经济利益关系，可能影响对投标公正评审的; (四)曾因在招标、评标以及其他与招标投标有关活动中从事违法行为而受过行政处罚或刑事处罚的。 评标委员会成员有前款规定情形之一的，应当主动提出回避。"},{"i":13,"n":"第十三条","txt":"评标委员会成员应当客观、公正地履行职责，遵守职业道德，对所提出的评审意见承担个人责任。 评标委员会成员不得与任何投标人或者与招标结果有利害关系的人进行私下接触，不得收受投标人、中介人、其他利害关系人的财物或者其他好处，不得向招标人征询其确定中标人的意向，不得接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求，不得有其他不客观、不公正履行职务的行为。 评标委员会成员不得与任何投标人或者与招标结果有利害关系的人进行私下接触，不得收受投标人、中介人、其他利害关系人的财物或者其他好处。"},{"i":14,"n":"第十四条","txt":"评标委员会成员和与评标活动有关的工作人员不得透露对投标文件的评审和比较、中标候选人的推荐情况以及与评标有关的其他情况。 前款所称与评标活动有关的工作人员，是指评标委员会成员以外的因参与评标监督工作或者事务性工作而知悉有关评标情况的所有人员。"},{"i":15,"n":"第十五条","txt":"评标委员会成员应当编制供评标使用的相应表格，认真研究招标文件，至少应了解和熟悉以下内容： (一)招标的目标; (二)招标项目的范围和性质; (三)招标文件中规定的主要技术要求、标准和商务条款; (四)招标文件规定的评标标准、评标方法和在评标过程中考虑的相关因素。"},{"i":16,"n":"第十六条","txt":"招标人或者其委托的招标代理机构应当向评标委员会提供评标所需的重要信息和数据，但不得带有明示或者暗示倾向或者排斥特定投标人的信息。 招标人设有标底的，标底在开标前应当保密，并在评标时作为参考。"},{"i":17,"n":"第十七条","txt":"评标委员会应当根据招标文件规定的评标标准和方法，对投标文件进行系统地评审和比较。招标文件中没有规定的标准和方法不得作为评标的依据。 招标文件中规定的评标标准和评标方法应当合理，不得含有倾向或者排斥潜在投标人的内容，不得妨碍或者限制投标人之间的竞争。"},{"i":18,"n":"第十八条","txt":"评标委员会应当按照投标报价的高低或者招标文件规定的其他方法对投标文件排序。以多种货币报价的，应当按照中国银行在开标日公布的汇率中间价换算成人民币。 招标文件应当对汇率标准和汇率风险作出规定。未作规定的，汇率风险由投标人承担。"},{"i":19,"n":"第十九条","txt":"评标委员会可以书面方式要求投标人对投标文件中含义不明确、对同类问题表述不一致或者有明显文字和计算错误的内容作必要的澄清、说明或者补正。澄清、说明或者补正应以书面方式进行并不得超出投标文件的范围或者改变投标文件的实质性内容。 投标文件中的大写金额和小写金额不一致的，以大写金额为准;总价金额与单价金额不一致的，以单价金额为准，但单价金额小数点有明显错误的除外;对不同文字文本投标文件的解释发生异议的，以中文文本为准。"},{"i":20,"n":"第二十条","txt":"在评标过程中，评标委员会发现投标人以他人的名义投标、串通投标、以行贿手段谋取中标或者以其他弄虚作假方式投标的，应当否决该投标人的投标。"},{"i":21,"n":"第二十一条","txt":"在评标过程中，评标委员会发现投标人的报价明显低于其他投标报价或者在设有标底时明显低于标底，使得其投标报价可能低于其个别成本的，应当要求该投标人作出书面说明并提供相关证明材料。投标人不能合理说明或者不能提供相关证明材料的，由评标委员会认定该投标人以低于成本报价竞标，应当否决其投标。"},{"i":22,"n":"第二十二条","txt":"投标人资格条件不符合国家有关规定和招标文件要求的，或者拒不按照要求对投标文件进行澄清、说明或者补正的，评标委员会可以否决其投标。"},{"i":23,"n":"第二十三条","txt":"评标委员会应当审查每一投标文件是否对招标文件提出的所有实质性要求和条件作出响应。未能在实质上响应的投标，应当予以否决。"},{"i":24,"n":"第二十四条","txt":"评标委员会应当根据招标文件，审查并逐项列出投标文件的全部投标偏差。 投标偏差分为重大偏差和细微偏差。"},{"i":25,"n":"第二十五条","txt":"下列情况属于重大偏差： (一)没有按照招标文件要求提供投标担保或者所提供的投标担保有瑕疵; (二)投标文件没有投标人授权代表签字和加盖公章; (三)投标文件载明的招标项目完成期限超过招标文件规定的期限; (四)明显不符合技术规格、技术标准的要求; (五)投标文件载明的货物包装方式、检验标准和方法等不符合招标文件的要求; (六)投标文件附有招标人不能接受的条件; (七)不符合招标文件中规定的其他实质性要求。 投标文件有上述情形之一的，为未能对招标文件作出实质性响应，并按本规定第二十三条规定作否决投标处理。招标文件对重大偏差另有规定的，从其规定。"},{"i":26,"n":"第二十六条","txt":"细微偏差是指投标文件在实质上响应招标文件要求，但在个别地方存在漏项或者提供了不完整的技术信息和数据等情况，并且补正这些遗漏或者不完整不会对其他投标人造成不公平的结果。细微偏差不影响投标文件的有效性。 评标委员会应当书面要求存在细微偏差的投标人在评标结束前予以补正。拒不补正的，在详细评审时可以对细微偏差作不利于该投标人的量化，量化标准应当在招标文件中规定。"},{"i":27,"n":"第二十七条","txt":"评标委员会根据本规定第二十条、第二十一条、第二十二条、第二十三条、第二十五条的规定否决不合格投标后，因有效投标不足三个使得投标明显缺乏竞争的，评标委员会可以否决全部投标。 投标人少于三个或者所有投标被否决的，招标人在分析招标失败的原因并采取相应措施后，应当依法重新招标。"},{"i":28,"n":"第二十八条","txt":"经初步评审合格的投标文件，评标委员会应当根据招标文件确定的评标标准和方法，对其技术部分和商务部分作进一步评审、比较。"},{"i":29,"n":"第二十九条","txt":"评标方法包括经评审的最低投标价法、综合评估法或者法律、行政法规允许的其他评标方法。"},{"i":30,"n":"第三十条","txt":"经评审的最低投标价法一般适用于具有通用技术、性能标准或者招标人对其技术、性能没有特殊要求的招标项目。"},{"i":31,"n":"第三十一条","txt":"根据经评审的最低投标价法，能够满足招标文件的实质性要求，并且经评审的最低投标价的投标，应当推荐为中标候选人。"},{"i":32,"n":"第三十二条","txt":"采用经评审的最低投标价法的，评标委员会应当根据招标文件中规定的评标价格调整方法，对所有投标人的投标报价以及投标文件的商务部分作必要的价格调整。 采用经评审的最低投标价法的，中标人的投标应当符合招标文件规定的技术要求和标准，但评标委员会无需对投标文件的技术部分进行价格折算。"},{"i":33,"n":"第三十三条","txt":"根据经评审的最低投标价法完成详细评审后，评标委员会应当拟定一份“标价比较表”，连同书面评标报告提交招标人。“标价比较表”应当载明投标人的投标报价、对商务偏差的价格调整和说明以及经评审的最终投标价。"},{"i":34,"n":"第三十四条","txt":"不宜采用经评审的最低投标价法的招标项目，一般应当采取综合评估法进行评审。"},{"i":35,"n":"第三十五条","txt":"根据综合评估法，最大限度地满足招标文件中规定的各项综合评价标准的投标，应当推荐为中标候选人。 衡量投标文件是否最大限度地满足招标文件中规定的各项评价标准，可以采取折算为货币的方法、打分的方法或者其他方法。需量化的因素及其权重应当在招标文件中明确规定。"},{"i":36,"n":"第三十六条","txt":"评标委员会对各个评审因素进行量化时，应当将量化指标建立在同一基础或者同一标准上，使各投标文件具有可比性。 对技术部分和商务部分进行量化后，评标委员会应当对这两部分的量化结果进行加权，计算出每一投标的综合评估价或者综合评估分。"},{"i":37,"n":"第三十七条","txt":"根据综合评估法完成评标后，评标委员会应当拟定一份“综合评估比较表”，连同书面评标报告提交招标人。“综合评估比较表”应当载明投标人的投标报价、所作的任何修正、对商务偏差的调整、对技术偏差的调整、对各评审因素的评估以及对每一投标的最终评审结果。"},{"i":38,"n":"第三十八条","txt":"根据招标文件的规定，允许投标人投备选标的，评标委员会可以对中标人所投的备选标进行评审，以决定是否采纳备选标。不符合中标条件的投标人的备选标不予考虑。"},{"i":39,"n":"第三十九条","txt":"对于划分有多个单项合同的招标项目，招标文件允许投标人为获得整个项目合同而提出优惠的，评标委员会可以对投标人提出的优惠进行审查，以决定是否将招标项目作为一个整体合同授予中标人。将招标项目作为一个整体合同授予的，整体合同中标人的投标应当最有利于招标人。"},{"i":40,"n":"第四十条","txt":"评标和定标应当在投标有效期内完成。不能在投标有效期内完成评标和定标的，招标人应当通知所有投标人延长投标有效期。拒绝延长投标有效期的投标人有权收回投标保证金。同意延长投标有效期的投标人应当相应延长其投标担保的有效期，但不得修改投标文件的实质性内容。因延长投标有效期造成投标人损失的，招标人应当给予补偿，但因不可抗力需延长投标有效期的除外。 招标文件应当载明投标有效期。投标有效期从提交投标文件截止日起计算。"},{"i":41,"n":"第四十一条","txt":"评标委员会在评标过程中发现的问题，应当及时作出处理或者向招标人提出处理建议，并作书面记录。"},{"i":42,"n":"第四十二条","txt":"评标委员会完成评标后，应当向招标人提出书面评标报告，并抄送有关行政监督部门。评标报告应当如实记载以下内容： (一)基本情况和数据表; (二)评标委员会成员名单; (三)开标记录; (四)符合要求的投标一览表; (五)否决投标的情况说明; (六)评标标准、评标方法或者评标因素一览表; (七)经评审的价格或者评分比较一览表; (八)经评审的投标人排序; (九)推荐的中标候选人名单与签订合同前要处理的事宜; (十)澄清、说明、补正事项纪要。"},{"i":43,"n":"第四十三条","txt":"评标报告由评标委员会全体成员签字。对评标结论持有异议的评标委员会成员可以书面方式阐述其不同意见和理由。评标委员会成员拒绝在评标报告上签字且不陈述其不同意见和理由的，视为同意评标结论。评标委员会应当对此作出书面说明并记录在案。"},{"i":44,"n":"第四十四条","txt":"向招标人提交书面评标报告后，评标委员会应将评标过程中使用的文件、表格以及其他资料应当即时归还招标人。"},{"i":45,"n":"第四十五条","txt":"评标委员会推荐的中标候选人应当限定在一至三人，并标明排列顺序。"},{"i":46,"n":"第四十六条","txt":"中标人的投标应当符合下列条件之一： (一)能够最大限度满足招标文件中规定的各项综合评价标准; (二)能够满足招标文件的实质性要求，并且经评审的投标价格最低;但是投标价格低于成本的除外。"},{"i":47,"n":"第四十七条","txt":"招标人不得与投标人就投标价格、投标方案等实质性内容进行谈判。"},{"i":48,"n":"第四十八条","txt":"国有资金占控股或者主导地位的项目，招标人应当确定排名第一的中标候选人为中标人。排名第一的中标候选人放弃中标、因不可抗力提出不能履行合同，或者招标文件规定应当提交履约保证金而在规定的期限内未能提交，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人。依次确定其他中标候选人与招标人预期差距较大，或者对招标人明显不利的，招标人可以重新招标。 招标人可以授权评标委员会直接确定中标人。 国务院对中标人的确定另有规定的，从其规定。"},{"i":49,"n":"第四十九条","txt":"中标人确定后，招标人应当向中标人发出中标通知书，同时通知未中标人，并与中标人在投标有效期内以及中标通知书发出之日起30日之内签订合同。"},{"i":50,"n":"第五十条","txt":"中标通知书对招标人和中标人具有法律约束力。中标通知书发出后，招标人改变中标结果或者中标人放弃中标的，应当承担法律责任。"},{"i":51,"n":"第五十一条","txt":"招标人应当与中标人按照招标文件和中标人的投标文件订立书面合同。招标人与中标人不得再行订立背离合同实质性内容的其他协议。"},{"i":52,"n":"第五十二条","txt":"招标人与中标人签订合同后5日内，应当向中标人和未中标的投标人退还投标保证金。"},{"i":53,"n":"第五十三条","txt":"评标委员会成员有下列行为之一的，由有关行政监督部门责令改正;情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标;情节特别严重的，取消其担任评标委员会成员的资格： (一)应当回避而不回避; (二)擅离职守; (三)不按照招标文件规定的评标标准和方法评标; (四)私下接触投标人; (五)向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求; (六)对依法应当否决的投标不提出否决意见; (七)暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明; (八)其他不客观、不公正履行职务的行为。"},{"i":54,"n":"第五十四条","txt":"评标委员会成员收受投标人的财物或者其他好处的，评标委员会成员或者与评标活动有关的工作人员向他人透露对投标文件的评审和比较、中标候选人的推荐以及与评标有关的其他情况的，给予警告，没收收受的财物，可以并处三千元以上五万元以下的罚款;对有所列违法行为的评标委员会成员取消担任评标委员会成员的资格，不得再参加任何依法必须进行招标项目的评标;构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"招标人有下列情形之一的，责令改正，可以处中标项目金额千分之十以下的罚款;给他人造成损失的，依法承担赔偿责任;对单位直接负责的主管人员和其他直接责任人员依法给予处分： (一)无正当理由不发出中标通知书; (二)不按照规定确定中标人; (三)中标通知书发出后无正当理由改变中标结果; (四)无正当理由不与中标人订立合同; (五)在订立合同时向中标人提出附加条件。"},{"i":56,"n":"第五十六条","txt":"招标人与中标人不按照招标文件和中标人的投标文件订立合同的，合同的主要条款与招标文件、中标人的投标文件的内容不一致，或者招标人、中标人订立背离合同实质性内容的协议的，由有关行政监督部门责令改正，可以处中标项目金额千分之五以上千分之十以下的罚款。"},{"i":57,"n":"第五十七条","txt":"中标人无正当理由不与招标人订立合同，在签订合同时向招标人提出附加条件，或者不按照招标文件要求提交履约保证金的，取消其中标资格，投标保证金不予退还。对依法必须进行招标的项目的中标人，由有关行政监督部门责令改正，可以处中标项目金额10‰以下的罚款。"},{"i":58,"n":"第五十八条","txt":"依法必须招标项目以外的评标活动，参照本规定执行。"},{"i":59,"n":"第五十九条","txt":"使用国际组织或者外国政府贷款、援助资金的招标项目的评标活动，贷款方、资金提供方对评标委员会与评标方法另有规定的，适用其规定，但违背中华人民共和国的社会公共利益的除外。"},{"i":60,"n":"第六十条","txt":"本规定颁布前有关评标机构和评标方法的规定与本规定不一致的，以本规定为准。法律或者行政法规另有规定的，从其规定。"},{"i":61,"n":"第六十一条","txt":"本规定由国家发展改革委会同有关部门负责解释。"},{"i":62,"n":"第六十二条","txt":"本规定自发布之日起施行。"}],"pingbiaoweiyuanhuihepingbiaofangfazanxingguiding":[{"i":1,"n":"第一条","txt":"为了规范评标活动，保证评标的公平、公正，维护招标投标活动当事人的合法权益，依照《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于依法必须招标项目的评标活动。"},{"i":3,"n":"第三条","txt":"评标活动遵循公平、公正、科学、择优的原则。"},{"i":4,"n":"第四条","txt":"评标活动依法进行，任何单位和个人不得非法干预或者影响评标过程和结果。"},{"i":5,"n":"第五条","txt":"招标人应当采取必要措施，保证评标活动在严格保密的情况下进行。"},{"i":6,"n":"第六条","txt":"评标活动及其当事人应当接受依法实施的监督。 　　有关行政监督部门依照国务院或者地方政府的职责分工，对评标活动实施监督，依法查处评标活动中的违法行为。"},{"i":7,"n":"第七条","txt":"评标委员会依法组建，负责评标活动，向招标人推荐中标候选人或者根据招标人的授权直接确定中标人。"},{"i":8,"n":"第八条","txt":"评标委员会由招标人负责组建。 　　评标委员会成员名单一般应于开标前确定。评标委员会成员名单在中标结果确定前应当保密。"},{"i":9,"n":"第九条","txt":"评标委员会由招标人或其委托的招标代理机构熟悉相关业务的代表，以及有关技术、经济等方面的专家组成，成员人数为五人以上单数，其中技术、经济等方面的专家不得少于成员总数的三分之二。 　　评标委员会设负责人的，评标委员会负责人由评标委员会成员推举产生或者由招标人确定。评标委员会负责人与评标委员会的其他成员有同等的表决权。"},{"i":10,"n":"第十条","txt":"评标委员会的专家成员应当从依法组建的专家库内的相关专家名单中确定。 　　按前款规定确定评标专家，可以采取随机抽取或者直接确定的方式。一般项目，可以采取随机抽取的方式；技术复杂、专业性强或者国家有特殊要求的招标项目，采取随机抽取方式确定的专家难以保证胜任的，可以由招标人直接确定。"},{"i":11,"n":"第十一条","txt":"评标专家应符合下列条件： 　　（一）从事相关专业领域工作满八年并具有高级职称或者同等专业水平； 　　（二）熟悉有关招标投标的法律法规，并具有与招标项目相关的实践经验； 　　（三）能够认真、公正、诚实、廉洁地履行职责。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，不得担任评标委员会成员： 　　（一）投标人或者投标人主要负责人的近亲属； 　　（二）项目主管部门或者行政监督部门的人员； 　　（三）与投标人有经济利益关系，可能影响对投标公正评审的； 　　（四）曾因在招标、评标以及其他与招标投标有关活动中从事违法行为而受过行政处罚或刑事处罚的。 　　评标委员会成员有前款规定情形之一的，应当主动提出回避。"},{"i":13,"n":"第十三条","txt":"评标委员会成员应当客观、公正地履行职责，遵守职业道德，对所提出的评审意见承担个人责任。 　　评标委员会成员不得与任何投标人或者与招标结果有利害关系的人进行私下接触，不得收受投标人、中介人、其他利害关系人的财物或者其他好处，不得向招标人征询其确定中标人的意向，不得接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求，不得有其他不客观、不公正履行职务的行为。"},{"i":14,"n":"第十四条","txt":"评标委员会成员和与评标活动有关的工作人员不得透露对投标文件的评审和比较、中标候选人的推荐情况以及与评标有关的其他情况。 　　前款所称与评标活动有关的工作人员，是指评标委员会成员以外的因参与评标监督工作或者事务性工作而知悉有关评标情况的所有人员。"},{"i":15,"n":"第十五条","txt":"评标委员会成员应当编制供评标使用的相应表格，认真研究招标文件，至少应了解和熟悉以下内容： 　　（一）招标的目标； 　　（二）招标项目的范围和性质； 　　（三）招标文件中规定的主要技术要求、标准和商务条款； 　　（四）招标文件规定的评标标准、评标方法和在评标过程中考虑的相关因素。"},{"i":16,"n":"第十六条","txt":"招标人或者其委托的招标代理机构应当向评标委员会提供评标所需的重要信息和数据，但不得带有明示或者暗示倾向或者排斥特定投标人的信息。 　　招标人设有标底的，标底在开标前应当保密，并在评标时作为参考。"},{"i":17,"n":"第十七条","txt":"评标委员会应当根据招标文件规定的评标标准和方法，对投标文件进行系统地评审和比较。招标文件中没有规定的标准和方法不得作为评标的依据。 　　招标文件中规定的评标标准和评标方法应当合理，不得含有倾向或者排斥潜在投标人的内容，不得妨碍或者限制投标人之间的竞争。"},{"i":18,"n":"第十八条","txt":"评标委员会应当按照投标报价的高低或者招标文件规定的其他方法对投标文件排序。以多种货币报价的，应当按照中国银行在开标日公布的汇率中间价换算成人民币。 　　招标文件应当对汇率标准和汇率风险作出规定。未作规定的，汇率风险由投标人承担。"},{"i":19,"n":"第十九条","txt":"评标委员会可以书面方式要求投标人对投标文件中含义不明确、对同类问题表述不一致或者有明显文字和计算错误的内容作必要的澄清、说明或者补正。澄清、说明或者补正应以书面方式进行并不得超出投标文件的范围或者改变投标文件的实质性内容。 　　投标文件中的大写金额和小写金额不一致的，以大写金额为准；总价金额与单价金额不一致的，以单价金额为准，但单价金额小数点有明显错误的除外；对不同文字文本投标文件的解释发生异议的，以中文文本为准。"},{"i":20,"n":"第二十条","txt":"在评标过程中，评标委员会发现投标人以他人的名义投标、串通投标、以行贿手段谋取中标或者以其他弄虚作假方式投标的，应当否决该投标人的投标。"},{"i":21,"n":"第二十一条","txt":"在评标过程中，评标委员会发现投标人的报价明显低于其他投标报价或者在设有标底时明显低于标底，使得其投标报价可能低于其个别成本的，应当要求该投标人作出书面说明并提供相关证明材料。投标人不能合理说明或者不能提供相关证明材料的，由评标委员会认定该投标人以低于成本报价竞标，应当否决其投标。"},{"i":22,"n":"第二十二条","txt":"投标人资格条件不符合国家有关规定和招标文件要求的，或者拒不按照要求对投标文件进行澄清、说明或者补正的，评标委员会可以否决其投标。"},{"i":23,"n":"第二十三条","txt":"评标委员会应当审查每一投标文件是否对招标文件提出的所有实质性要求和条件作出响应。未能在实质上响应的投标，应当予以否决。"},{"i":24,"n":"第二十四条","txt":"评标委员会应当根据招标文件，审查并逐项列出投标文件的全部投标偏差。 　　投标偏差分为重大偏差和细微偏差。"},{"i":25,"n":"第二十五条","txt":"下列情况属于重大偏差： 　　（一）没有按照招标文件要求提供投标担保或者所提供的投标担保有瑕疵； 　　（二）投标文件没有投标人授权代表签字和加盖公章； 　　（三）投标文件载明的招标项目完成期限超过招标文件规定的期限； 　　（四）明显不符合技术规格、技术标准的要求； 　　（五）投标文件载明的货物包装方式、检验标准和方法等不符合招标文件的要求； 　　（六）投标文件附有招标人不能接受的条件； 　　（七）不符合招标文件中规定的其他实质性要求。 　　投标文件有上述情形之一的，为未能对招标文件作出实质性响应，并按本规定第二十三条规定作否决投标处理。招标文件对重大偏差另有规定的，从其规定。"},{"i":26,"n":"第二十六条","txt":"细微偏差是指投标文件在实质上响应招标文件要求，但在个别地方存在漏项或者提供了不完整的技术信息和数据等情况，并且补正这些遗漏或者不完整不会对其他投标人造成不公平的结果。细微偏差不影响投标文件的有效性。 　　评标委员会应当书面要求存在细微偏差的投标人在评标结束前予以补正。拒不补正的，在详细评审时可以对细微偏差作不利于该投标人的量化，量化标准应当在招标文件中规定。"},{"i":27,"n":"第二十七条","txt":"评标委员会根据本规定第二十条、第二十一条、第二十二条、第二十三条、第二十五条的规定否决不合格投标后，因有效投标不足三个使得投标明显缺乏竞争的，评标委员会可以否决全部投标。 　　投标人少于三个或者所有投标被否决的，招标人在分析招标失败的原因并采取相应措施后，应当依法重新招标。"},{"i":28,"n":"第二十八条","txt":"经初步评审合格的投标文件，评标委员会应当根据招标文件确定的评标标准和方法，对其技术部分和商务部分作进一步评审、比较。"},{"i":29,"n":"第二十九条","txt":"评标方法包括经评审的最低投标价法、综合评估法或者法律、行政法规允许的其他评标方法。"},{"i":30,"n":"第三十条","txt":"经评审的最低投标价法一般适用于具有通用技术、性能标准或者招标人对其技术、性能没有特殊要求的招标项目。"},{"i":31,"n":"第三十一条","txt":"根据经评审的最低投标价法，能够满足招标文件的实质性要求，并且经评审的最低投标价的投标，应当推荐为中标候选人。"},{"i":32,"n":"第三十二条","txt":"采用经评审的最低投标价法的，评标委员会应当根据招标文件中规定的评标价格调整方法，以所有投标人的投标报价以及投标文件的商务部分作必要的价格调整。采用经评审的最低投标价法的，中标人的投标应当符合招标文件规定的技术要求和标准，但评标委员会无需对投标文件的技术部分进行价格折算。"},{"i":33,"n":"第三十三条","txt":"根据经评审的最低投标价法完成详细评审后，评标委员会应当拟定一份“标价比较表”，连同书面评标报告提交招标人。“标价比较表”应当载明投标人的投标报价、对商务偏差的价格调整和说明以及经评审的最终投标价。"},{"i":34,"n":"第三十四条","txt":"不宜采用经评审的最低投标价法的招标项目，一般应当采取综合评估法进行评审。"},{"i":35,"n":"第三十五条","txt":"根据综合评估法，最大限度地满足招标文件中规定的各项综合评价标准的投标，应当推荐为中标候选人。 　　衡量投标文件是否最大限度地满足招标文件中规定的各项评价标准，可以采取折算为货币的方法、打分的方法或者其他方法。需量化的因素及其权重应当在招标文件中明确规定。"},{"i":36,"n":"第三十六条","txt":"评标委员会对各个评审因素进行量化时，应当将量化指标建立在同一基础或者同一标准上，使各投标文件具有可比性。 　　对技术部分和商务部分进行量化后，评标委员会应当对这两部分的量化结果进行加权，计算出每一投标的综合评估价或者综合评估分。"},{"i":37,"n":"第三十七条","txt":"根据综合评估法完成评标后，评标委员会应当拟定一份“综合评估比较表”，连同书面评标报告提交招标人。“综合评估比较表”应当载明投标人的投标报价、所作的任何修正、对商务偏差的调整、对技术偏差的调整、对各评审因素的评估以及对每一投标的最终评审结果。"},{"i":38,"n":"第三十八条","txt":"根据招标文件的规定，允许投标人投备选标的，评标委员会可以对中标人所投的备选标进行评审，以决定是否采纳备选标。不符合中标条件的投标人的备选标不予考虑。"},{"i":39,"n":"第三十九条","txt":"对于划分有多个单项合同的招标项目，招标文件允许投标人为获得整个项目合同而提出优惠的，评标委员会可以对投标人提出的优惠进行审查，以决定是否将招标项目作为一个整体合同授予中标人。将招标项目作为一个整体合同授予的，整体合同中标人的投标应当最有利于招标人。"},{"i":40,"n":"第四十条","txt":"评标和定标应当在投标有效期内完成。不能在投标有效期结束日30个工作日前完成评标和定标的，招标人应当通知所有投标人延长投标有效期。拒绝延长投标有效期的投标人有权收回投标保证金。同意延长投标有效期的投标人应当相应延长其投标担保的有效期，但不得修改投标文件的实质性内容。因延长投标有效期造成投标人损失的，招标人应当给予补偿，但因不可抗力需延长投标有效期的除外。 　　招标文件应当载明投标有效期。投标有效期从提交投标文件截止日起计算。"},{"i":41,"n":"第四十一条","txt":"评标委员会在评标过程中发现的问题，应当及时作出处理或者向招标人提出处理建议，并作书面记录。"},{"i":42,"n":"第四十二条","txt":"评标委员会完成评标后，应当向招标人提出书面评标报告，并抄送有关行政监督部门。评标报告应当如实记载以下内容： 　　（一）基本情况和数据表； 　　（二）评标委员会成员名单； 　　（三）开标记录； 　　（四）符合要求的投标一览表； 　　（五）否决投标的情况说明； 　　（六）评标标准、评标方法或者评标因素一览表； 　　（七）经评审的价格或者评分比较一览表； 　　（八）经评审的投标人排序； 　　（九）推荐的中标候选人名单与签订合同前要处理的事宜； 　　（十）澄清、说明、补正事项纪要。"},{"i":43,"n":"第四十三条","txt":"评标报告由评标委员会全体成员签字。对评标结论持有异议的评标委员会成员可以书面方式阐述其不同意见和理由。评标委员会成员拒绝在评标报告上签字且不陈述其不同意见和理由的，视为同意评标结论。评标委员会应当对此作出书面说明并记录在案。"},{"i":44,"n":"第四十四条","txt":"向招标人提交书面评标报告后，评标委员会应将评标过程中使用的文件、表格以及其他资料应当即时归还招标人。"},{"i":45,"n":"第四十五条","txt":"评标委员会推荐的中标候选人应当限定在一至三人，并标明排列顺序。"},{"i":46,"n":"第四十六条","txt":"中标人的投标应当符合下列条件之一： 　　（一）能够最大限度满足招标文件中规定的各项综合评价标准； 　　（二）能够满足招标文件的实质性要求，并且经评审的投标价格最低；但是投标价格低于成本的除外。"},{"i":47,"n":"第四十七条","txt":"招标人不得与投标人就投标价格、投标方案等实质性内容进行谈判。"},{"i":48,"n":"第四十八条","txt":"国有资金占控股或者主导地位的项目，招标人应当确定排名第一的中标候选人为中标人。排名第一的中标候选人放弃中标、因不可抗力提出不能履行合同，或者招标文件规定应当提交履约保证金而在规定的期限内未能提交，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人。依次确定其他中标候选人与招标人预期差距较大，或者对招标人明显不利的，招标人可以重新招标。 　　招标人可以授权评标委员会直接确定中标人。 　　国务院对中标人的确定另有规定的，从其规定。"},{"i":49,"n":"第四十九条","txt":"中标人确定后，招标人应当向中标人发出中标通知书，同时通知未中标人，并与中标人在投标有效期内以及中标通知书发出之日起30日之内签订合同。"},{"i":50,"n":"第五十条","txt":"中标通知书对招标人和中标人具有法律约束力。中标通知书发出后，招标人改变中标结果或者中标人放弃中标的，应当承担法律责任。"},{"i":51,"n":"第五十一条","txt":"招标人应当与中标人按照招标文件和中标人的投标文件订立书面合同。招标人与中标人不得再行订立背离合同实质性内容的其他协议。"},{"i":52,"n":"第五十二条","txt":"招标人与中标人签订合同后5日内，应当向中标人和未中标的投标人退还投标保证金。"},{"i":53,"n":"第五十三条","txt":"评标委员会成员有下列行为之一的，由有关行政监督部门责令改正；情节严重的，禁止其在一定期限内参加依法必须进行招标的项目的评标；情节特别严重的，取消其担任评标委员会成员的资格： 　　（一）应当回避而不回避； 　　（二）擅离职守； 　　（三）不按照招标文件规定的评标标准和方法评标； 　　（四）私下接触投标人； 　　（五）向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求； 　　（六）对依法应当否决的投标不提出否决意见； 　　（七）暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明； 　　（八）其他不客观、不公正履行职务的行为。"},{"i":54,"n":"第五十四条","txt":"评标委员会成员收受投标人的财物或者其他好处的，评标委员会成员或者与评标活动有关的工作人员向他人透露对投标文件的评审和比较、中标候选人的推荐以及与评标有关的其他情况的，给予警告，没收收受的财物，可以并处三千元以上五万元以下的罚款；对有所列违法行为的评标委员会成员取消担任评标委员会成员的资格，不得再参加任何依法必须进行招标项目的评标；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"招标人有下列情形之一的，责令改正，可以处中标项目金额千分之十以下的罚款；给他人造成损失的，依法承担赔偿责任；对单位直接负责的主管人员和其他直接责任人员依法给予处分： 　　（一）无正当理由不发出中标通知书； 　　（二）不按照规定确定中标人； 　　（三）中标通知书发出后无正当理由改变中标结果； 　　（四）无正当理由不与中标人订立合同； 　　（五）在订立合同时向中标人提出附加条件。"},{"i":56,"n":"第五十六条","txt":"招标人与中标人不按照招标文件和中标人的投标文件订立合同的，合同的主要条款与招标文件、中标人的投标文件的内容不一致，或者招标人、中标人订立背离合同实质性内容的协议的，由有关行政监督部门责令改正，可以处中标项目金额千分之五以上千分之十以下的罚款。"},{"i":57,"n":"第五十七条","txt":"中标人无正当理由不与招标人订立合同，在签订合同时向招标人提出附加条件，或者不按照招标文件要求提交履约保证金的，取消其中标资格，投标保证金不予退还。对依法必须进行招标的项目的中标人，由有关行政监督部门责令改正，可以处中标项目金额10‰以下的罚款。"},{"i":58,"n":"第五十八条","txt":"依法必须招标项目以外的评标活动，参照本规定执行。"},{"i":59,"n":"第五十九条","txt":"使用国际组织或者外国政府贷款、援助资金的招标项目的评标活动，贷款方、资金提供方对评标委员会与评标方法另有规定的，适用其规定，但违背中华人民共和国的社会公共利益的除外。"},{"i":60,"n":"第六十条","txt":"本规定颁布前有关评标机构和评标方法的规定与本规定不一致的，以本规定为准。法律或者行政法规另有规定的，从其规定。"},{"i":61,"n":"第六十一条","txt":"本规定由国家发展改革委会同有关部门负责解释。"},{"i":62,"n":"第六十二条","txt":"本规定自发布之日起施行。"}],"bianxiaochaguojiachubeiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强边销茶国家储备管理，保证边销茶市场稳定供应，制定本办法。"},{"i":2,"n":"第二条","txt":"边销茶储备分为原料储备和成品储备。 边销茶原料储备品种为黑毛茶、老青茶、红茶;边销茶成品储备品种为茯砖、康砖、青砖、金尖、花砖、黑砖和米砖。"},{"i":3,"n":"第三条","txt":"边销茶原料储备由产区定点生产企业代储，边销茶成品储备由销区供销社主营公司代储。"},{"i":4,"n":"第四条","txt":"边销茶国家储备、动销计划由国家计委商财政部、中华全国供销合作总社(以下简称供销总社)后下达到代储企业。 供销总社负责边销茶国家储备计划的组织实施，并将执行情况及时报国家计委、财政部备案。"},{"i":5,"n":"第五条","txt":"国家储备边销茶的收储、动销价格，由国家计委商财政部后，根据市场情况确定。"},{"i":6,"n":"第六条","txt":"根据国家下达的边销茶储备计划，边销茶原料储备由产区代储的定点生产企业在每年生产旺季组织收购、储存。 入储的边销茶成品由代储单位从定点生产企业购进，且须是经国家法定质量监督机构公证检验的合格产品，检验费用按规定标准计入收储成本，具体标准由国家计委商财政部另行制定。"},{"i":7,"n":"第七条","txt":"代储单位要认真做好边销茶国家储备的保管工作，负责推陈储新，及时轮换，保证数量和质量，确保调控市场需要。"},{"i":8,"n":"第八条","txt":"代储单位对边销茶国家储备要严格做到专库、专帐、专人管理，要在每季后10天内将上季度各月分库点购、销、存情况报供销总社审核，供销总社汇总并于季后20天内报国家计委和财政部。"},{"i":9,"n":"第九条","txt":"国家计委、财政部和供销总社每年对边销茶国家储备情况进行检查。"},{"i":10,"n":"第十条","txt":"代储单位保管不善，或未能完成边销茶成品收储(动销)任务的，取消其代储资格，并相应扣减其利息补贴款。"},{"i":11,"n":"第十一条","txt":"国家储备边销茶原料和成品所需贷款利息由中央财政负担。"},{"i":12,"n":"第十二条","txt":"边销茶国家储备所需资金由代储单位向当地开户银行申请贷款解决，各开户银行在贷款安排上应给予支持，保证供应，并区别情况计收利息。代储单位按时支付利息款。 边销茶成品储备贷款执行正常流动资金贷款基准利率;边销茶原料储备贷款执行民贸和民族用品生产贷款利率。"},{"i":13,"n":"第十三条","txt":"代储单位应在第二、四季度后10天内分别将上半年和下半年分月储存贷款利息支出情况经所在开户银行和财政部驻当地财政监察专员办事处审核并签注意见后，于第二、四季度后15天内报供销总社，供销总社审核汇总连同代储单位上报材料一并于季后20天内报财政部。 供销总社根据代储单位储存情况编制上半年和下半年边销茶储备利息补贴申请报告，分别于第三、第四季度开始后的头20天内报财政部。"},{"i":14,"n":"第十四条","txt":"财政部根据代储单位计划内实际储存及其贷款占用、利息开支等情况，在年中和年末分两次将贴息款核拨(或预拨)给供销总社。供销总社在收到财政贴息款的5个工作日内将资金及时转拨给代储单位。"},{"i":15,"n":"第十五条","txt":"供销总社应在年度终了后30天内，编制边销茶国家储备利息补贴清算报告报财政部，财政部按规定进行清算，据实结算。"},{"i":16,"n":"第十六条","txt":"本办法由国家计委会同有关部门负责解释。"},{"i":17,"n":"第十七条","txt":"本办法自发布之日起执行。"}],"bimianzaimianhuacaizhaijiaoshoujiagongguochengzhonde4225-2":[{"i":1,"n":"第一条","txt":"为提高我国棉花质量和棉纺织品出口竞争力，鼓励使用国产棉花，根据《棉花质量监督管理条例》、《棉花收购加工与市场管理暂行办法》等有关行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国境内所有从事棉花生产、经营活动的棉花生产者(含农民和棉花生产企业)、棉花经营者(含棉花收购、加工、销售)、纺织用棉企业。"},{"i":3,"n":"第三条","txt":"异性纤维是指混入棉花中的非棉纤维，如化学纤维、丝、麻、毛发、塑料绳等。"},{"i":4,"n":"第四条","txt":"农民和棉花生产企业在棉花生产过程中应遵守下列规定： (一)采摘、晾晒、交售棉花时，应当戴棉布帽子，穿棉布服装;用棉布口袋盛装棉花;用棉绳、棉线绑扎棉袋口。禁止使用化纤编织袋等非棉布口袋盛装棉花;禁止使用有色的或非棉线绳扎棉袋口。 (二)晾晒籽棉时应当采取必要措施加强防护管理，防止混入异性纤维。"},{"i":5,"n":"第五条","txt":"棉花收购企业应严格按棉花国家标准收购棉花并遵守下列规定： (一)收购籽棉时应当对交售者籽棉盛装物、绑扎物进行检查，发现使用化纤编织袋、有色棉线或非棉线(绳)等物品的，应当拒绝收购。 (二)收购籽棉时发现籽棉中混有异性纤维、色纤维及其他危害性杂物的，应当责成交售者挑拣干净后收购;交售者拒绝挑拣或挑拣不干净的，可以拒绝收购或由收购者挑拣干净后根据异性纤维含量相应降价收购。 (三)已购进的籽棉，应当在上垛前组织人力进行检查，发现异性纤维应当予以排除。 (四)在籽棉收购、运输、存放等环节，应当采取必要措施防止混入异性纤维。 (五)应当为农民免费或以成本价提供盛装籽棉的棉布口袋及其他所需物品。"},{"i":6,"n":"第六条","txt":"棉花加工企业应严格按棉花国家标准加工棉花并遵守下列规定： (一)设立清理异性纤维的工序。加工籽棉前发现混有异性纤维、色纤维及其他危害性杂物的，须组织人力挑拣干净后加工。 (二)加强待加工籽棉的存放管理，采取必要措施防止混入异性纤维。 (三)对批量成包皮棉应当按照国家标准进行异性纤维检验，应当在棉花标识中明示“有、无或未发现”字样，并在检验证书上注明。 棉花加工企业收购籽棉的，同时应当遵守第五条的有关规定。"},{"i":7,"n":"第七条","txt":"纺织用棉企业与供棉企业可以根据棉花中有、无混入异性纤维情况对棉花制定加价、降价、索赔、拒收和退货的规定。有关条款应当在双方签定的棉花购销合同中约定。"},{"i":8,"n":"第八条","txt":"对违反本规定第五条第(一)、(二)、(三)项和第六条第(一)、(三)项的棉花收购、加工企业，按照《棉花质量监督管理条例》的有关规定处罚： (一)棉花收购企业收购棉花，不按照国家标准和技术规范排除异性纤维和其他有害物质的，由棉花质量监督机构责令改正，可以处3万元以下的罚款;情节严重的，由质检机关提交原资格认定机关取消其棉花收购资格。 (二)棉花加工企业加工棉花，不按照国家标准分拣、排除异性纤维和其他有害物质的，由棉花质量监督机构责令改正，并可以根据情节轻重，处10万元以下的罚款;情节严重的，由质检机关提交原资格认定机关取消其棉花加工资格。 (三)棉花加工企业销售皮棉时未将棉花中异性纤维情况在外包装上标识或标识与实物不符的，由棉花质量监督机构责令改正，并可以根据情节轻重，处3万元以下的罚款。"},{"i":9,"n":"第九条","txt":"产棉县、乡人民政府及其农业部门应当采取措施，利用多种方式引导和教育农民、棉花生产企业自觉遵守第四条的规定。"},{"i":10,"n":"第十条","txt":"产棉区市、县、乡人民政府及省、市、县农业、纺织、供销、质量技术监督部门应依据本规定做好排除异性纤维的宣传、组织、引导和监督工作。"},{"i":11,"n":"第十一条","txt":"农业发展银行对违反本规定收购及加工后的棉花中异性纤维含量较多且屡教不改的棉花收购、加工企业，可停止对其提供棉花收购贷款。"},{"i":12,"n":"第十二条","txt":"本规定由国家发展计划委员会商有关部门解释。"},{"i":13,"n":"第十三条","txt":"本规定自2002年10月30日起执行。 避免在棉花采摘、交售、加工过程中混入异性纤维的暂行规定 避免在棉花采摘、交售、加工过程中混入异性纤维的暂行规定 避免在棉花采摘、交售、加工过程中混入异性纤维的暂行规定"}],"bimianzaimianhuacaizhaijiaoshoujiagongguochengzhonde4225":[{"i":1,"n":"第一条","txt":"为提高我国棉花质量和棉纺织品出口竞争力，鼓励使用国产棉花，根据《棉花质量监督管理条例》、《棉花收购加工与市场管理暂行办法》等有关行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国境内所有从事棉花生产、经营活动的棉花生产者（含农民和棉花生产企业）、棉花经营者（含棉花收购、加工、销售）、纺织用棉企业。"},{"i":3,"n":"第三条","txt":"异性纤维是指混入棉花中的非棉纤维，如化学纤维、丝、麻、毛发、塑料绳等。"},{"i":4,"n":"第四条","txt":"农民和棉花生产企业在棉花生产过程中应遵守下列规定： （一）采摘、晾晒、交售棉花时，应当戴棉布帽子，穿棉布服装；用棉布口袋盛装棉花；用棉绳、棉线绑扎棉袋口。禁止使用化纤编织袋等非棉布口袋盛装棉花；禁止使用有色的或非棉线绳扎棉袋口。 （二）晾晒籽棉时应当采取必要措施加强防护管理，防止混入异性纤维。"},{"i":5,"n":"第五条","txt":"棉花收购企业应严格按棉花国家标准收购棉花并遵守下列规定： （一）收购籽棉时应当对交售者籽棉盛装物、绑扎物进行检查，发现使用化纤编织袋、有色棉线或非棉线（绳）等物品的，应当拒绝收购。 （二）收购籽棉时发现籽棉中混有异性纤维、色纤维及其他危害性杂物的，应当责成交售者挑拣干净后收购；交售者拒绝挑拣或挑拣不干净的，可以拒绝收购或由收购者挑拣干净后根据异性纤维含量相应降价收购。 （三）已购进的籽棉，应当在上垛前组织人力进行检查，发现异性纤维应当予以排除。 （四）在籽棉收购、运输、存放等环节，应当采取必要措施防止混入异性纤维。 （五）应当为农民免费或以成本价提供盛装籽棉的棉布口袋及其他所需物品。"},{"i":6,"n":"第六条","txt":"棉花加工企业应严格按棉花国家标准加工棉花并遵守下列规定： （一）设立清理异性纤维的工序。加工籽棉前发现混有异性纤维、色纤维及其他危害性杂物的，须组织人力挑拣干净后加工。 （二）加强待加工籽棉的存放管理，采取必要措施防止混入异性纤维。 （三）对批量成包皮棉应当按照国家标准进行异性纤维检验，应当在棉花标识中明示“有、无或未发现”字样，并在检验证书上注明。 棉花加工企业收购籽棉的，同时应当遵守第五条的有关规定。"},{"i":7,"n":"第七条","txt":"纺织用棉企业与供棉企业可以根据棉花中有、无混入异性纤维情况对棉花制定加价、降价、索赔、拒收和退货的规定。有关条款应当在双方签定的棉花购销合同中约定。"},{"i":8,"n":"第八条","txt":"对违反本规定第五条第（一）、（二）、（三）项和第六条第（一）、（三）项的棉花收购、加工企业，按照《棉花质量监督管理条例》的有关规定处罚： （一）棉花收购企业收购棉花，不按照国家标准和技术规范排除异性纤维和其他有害物质的，由棉花质量监督机构责令改正，可以处3万元以下的罚款；情节严重的，由质检机关提交原资格认定机关取消其棉花收购资格。 （二）棉花加工企业加工棉花，不按照国家标准分拣、排除异性纤维和其他有害物质的，由棉花质量监督机构责令改正，并可以根据情节轻重，处10万元以下的罚款；情节严重的，由质检机关提交原资格认定机关取消其棉花加工资格。 （三）棉花加工企业销售皮棉时未将棉花中异性纤维情况在外包装上标识或标识与实物不符的，由棉花质量监督机构责令改正，并可以根据情节轻重，处3万元以下的罚款。"},{"i":9,"n":"第九条","txt":"产棉县、乡人民政府及其农业部门应当采取措施，利用多种方式引导和教育农民、棉花生产企业自觉遵守第四条的规定。"},{"i":10,"n":"第十条","txt":"产棉区市、县、乡人民政府及省、市、县农业、纺织、供销、质量技术监督部门应依据本规定做好排除异性纤维的宣传、组织、引导和监督工作。"},{"i":11,"n":"第十一条","txt":"农业发展银行对违反本规定收购及加工后的棉花中异性纤维含量较多且屡教不改的棉花收购、加工企业，可停止对其提供棉花收购贷款。"},{"i":12,"n":"第十二条","txt":"本规定由国家发展计划委员会商有关部门解释。"},{"i":13,"n":"第十三条","txt":"本规定自2002年10月30日起执行。"}],"zhongdianyongnengdanweijienengguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强重点用能单位的节能管理，提高能源利用效率，控制能源消费总量，促进生态文明建设，根据《中华人民共和国节约能源法》等有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称重点用能单位是指： （一）年综合能源消费量一万吨标准煤及以上的用能单位； （二）国务院有关部门或者省、自治区、直辖市人民政府管理节能工作的部门指定的年综合能源消费量五千吨及以上不满一万吨标准煤的用能单位。 能源消费的核算单位是法人单位。"},{"i":3,"n":"第三条","txt":"重点用能单位应当贯彻执行国家和地方有关节能的法律、法规、规章、政策和标准，按照合理用能的原则，加强节能管理，降低能源消耗，接受所在地县级以上人民政府管理节能工作的部门的管理。"},{"i":4,"n":"第四条","txt":"国家发展和改革委员会负责全国重点用能单位节能管理工作。国务院有关部门在各自的职责范围内开展重点用能单位节能管理工作。 县级以上地方各级人民政府管理节能工作的部门负责本行政区域内重点用能单位节能管理工作。县级以上地方各级人民政府有关部门在各自的职责范围内开展重点用能单位节能管理工作。 县级以上人民政府管理节能工作的部门，在开展重点用能单位节能管理工作过程中，根据本地区重点用能单位行业情况，充分发挥有关行业主管部门作用，共同推动重点用能单位节能管理工作。"},{"i":5,"n":"第五条","txt":"对重点用能单位实行节能目标责任制和节能考核评价制度。地市级以上人民政府管理节能工作的部门会同有关部门，将能耗总量控制和节能目标分解到重点用能单位，对重点用能单位分级开展节能目标责任评价考核，主要考核重点用能单位能耗总量控制和节能目标完成情况、能源利用效率及节能措施落实情况，逐级报送考核结果，并将考核结果向社会进行公布。"},{"i":6,"n":"第六条","txt":"重点用能单位应当每年制定并实施节能计划和节能措施，确保完成能耗总量控制和节能目标。节能措施应当技术上可行、经济上合理。"},{"i":7,"n":"第七条","txt":"重点用能单位应当建立健全能源管理制度，明确能源管理职责，制定能源利用全过程的管理要求或规范，确立淘汰落后、实施节能技术改造及奖惩等各方面管理机制，加强节能管理，减少能源损失，提高能源利用效率。"},{"i":8,"n":"第八条","txt":"重点用能单位应当建立节能目标责任制，根据政府管理节能工作的部门下达的能耗总量控制和节能目标任务及要求，科学评估节能潜力，合理分解目标，落实到相应层级或岗位，并定期组织内部考核。 重点用能单位应当建立节能奖惩制度，将能耗总量控制和节能目标完成情况与奖惩挂钩，对节能工作中取得突出成绩的集体和个人给予表彰和奖励，对浪费能源的集体和个人给予惩罚。"},{"i":9,"n":"第九条","txt":"重点用能单位应当按照《能源管理体系 要求》等相关标准的要求，建立健全能源管理体系并使之有效运行。 县级以上人民政府管理节能工作的部门负责组织开展能源管理体系建设效果评价工作。鼓励重点用能单位开展能源管理体系认证。"},{"i":10,"n":"第十条","txt":"重点用能单位应当成立节能工作领导小组，负责人由单位主要领导担任。 重点用能单位应当聘任具有节能专业知识、实际经验以及中级以上技术职称的人员担任能源管理负责人。 重点用能单位应当明确能源管理部门，设立能源管理岗位，聘任能够满足节能工作需要的能源管理人员。能源管理人员负责贯彻执行国家有关节约能源工作的法律、法规、规章、政策和标准，加强日常节能管理，组织实施本单位内部能源审计、节能技术改造，开展能源计量和统计分析等。 重点用能单位应当将节能工作领导小组、能源管理负责人、能源管理人员报管理节能工作的部门和有关部门备案，上述信息发生变动的，应当及时将变动情况报管理节能工作的部门和有关部门备案。"},{"i":11,"n":"第十一条","txt":"重点用能单位应当按照《用能单位能源计量器具配备和管理通则》《重点用能单位能源计量审查规范》等有关规定，配备和使用经依法检定或校准的能源计量器具，加强能源计量数据的管理和使用，建立健全能源计量管理制度，完善能源计量体系，并接受质量技术监督部门开展的能源计量审查等监督检查。"},{"i":12,"n":"第十二条","txt":"重点用能单位应当按照国家有关规定设置原始记录、统计台账，建立健全统计资料的审核、签署、交接、归档等管理制度。统计资料的审核、签署人员应当对其审核、签署的统计资料的真实性、准确性和完整性负责。"},{"i":13,"n":"第十三条","txt":"重点用能单位应当由能源管理负责人负责组织能源利用状况报告填报工作，并每年向县级以上人民政府管理节能工作的部门报送上年度的能源利用状况报告。能源利用状况报告应当包括能源消费情况、能源利用效率、能耗总量控制和节能目标完成情况、节能效益分析、节能措施等内容。 县级以上人民政府管理节能工作的部门负责对重点用能单位报送的能源利用状况报告进行审查，逐级报送审查结果，将数据质量存在问题的重点用能单位作为本年度节能监察重点对象。"},{"i":14,"n":"第十四条","txt":"重点用能单位应当按照国家有关规定实施能源审计，分析现状，查找问题，挖掘节能潜力，提出切实可行的节能措施，并向县级以上人民政府管理节能工作的部门报送能源审计报告。 县级以上人民政府管理节能工作的部门对重点用能单位的能源审计报告进行审核，并指导和督促重点用能单位落实节能措施。"},{"i":15,"n":"第十五条","txt":"重点用能单位应当结合现有能源管理信息化平台，加强能源计量基础能力建设，按照政府管理节能工作的部门、质量技术监督部门要求建设能耗在线监测系统，提升能源管理信息化水平。"},{"i":16,"n":"第十六条","txt":"重点用能单位应当优先采用《国家重点节能低碳技术推广目录》以及地方发布的相关目录中的节能技术、生产工艺和用能设备，主动淘汰落后的和国家明令禁止使用的用能产品、设备和生产工艺。 重点用能单位应当每年安排一定数量资金用于节能技术研发、节能技术改造、能源计量器具配备和节能技术培训等。 鼓励重点用能单位开展产学研合作，加强节能技术研发与应用交流合作。鼓励重点用能单位积极运用先进节能技术实施节能改造。 节能改造时涉及高耗能特种设备的，应当保障特种设备的安全性能，有关特种设备安全与节能法律、法规及规章另有规定的，从其规定。"},{"i":17,"n":"第十七条","txt":"重点用能单位应当执行单位产品能耗限额强制性国家标准和能源效率强制性国家标准。鼓励重点用能单位制定严于国家标准、行业标准、地方标准的企业节能标准。 重点用能单位应当积极开展能效对标活动，持续提升能效水平，争当本行业能效“领跑者”。鼓励各行业协会在有关部门的指导下开展本行业内能效对标活动，组织本行业重点用能单位开展能效对标，对重点用能单位能效对标活动进行跟踪指导和评估，并提供技术支持。"},{"i":18,"n":"第十八条","txt":"重点用能单位应当严格落实固定资产投资项目节能审查制度，未进行节能审查，或节能审查未通过的项目，建设单位不得开工建设，已经建成的不得投入生产、使用。"},{"i":19,"n":"第十九条","txt":"省级以上人民政府管理节能工作的部门会同有关部门可结合重点用能单位节能目标责任考核结果，对在节能工作中取得显著成绩的重点用能单位和个人给予表彰和奖励。对节能考核结果为未完成等级的重点用能单位，地市级以上人民政府管理节能工作的部门应当责令其实施能源审计、报送能源审计报告、提出整改措施并限期整改。 国务院国资委将中央企业能耗总量控制和节能目标完成情况纳入企业业绩考核范围，作为企业领导班子和领导干部综合评价考核的重要内容，建立完善问责制度，对成绩突出的单位和个人给予表彰奖励。地方国资委相应加强对重点用能单位中的地方国有企业节能目标责任考核结果运用，落实奖惩机制。"},{"i":20,"n":"第二十条","txt":"省级以上人民政府管理节能工作的部门对因在节能工作中取得显著成绩获得表彰和奖励的重点用能单位和个人，联合有关部门给予守信激励。 国家发展和改革委员会对违反本办法规定的行为建立信用记录，纳入全国信用信息共享平台，在“信用中国”网站向社会公开，对严重失信主体实施联合惩戒措施。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府管理节能工作的部门会同有关部门推动和引导社会有关方面加大对节能的资金投入，支持重点用能单位开展节能技术研究开发、节能技术和产品的示范与推广、节能改造项目实施、能源计量器具配备、节能管理能力建设、节能宣传培训等。 县级以上人民政府管理节能工作的部门会同有关部门利用节能有关专项资金支持重点用能单位实施节能重点工程时，优先支持节能目标责任评价考核成绩突出的重点用能单位。"},{"i":22,"n":"第二十二条","txt":"鼓励银行业金融机构加大对符合条件的节能产品生产、节能技术改造等节能项目的信贷投入。银行业金融机构在开展能效信贷工作中，对符合信贷条件，达到先进能效标准的固定资产和项目、节能目标责任评价考核成绩突出的重点用能单位融资需求优先支持；对达不到能效国家标准的固定资产和项目融资需求，不予支持。 鼓励重点用能单位通过发行绿色债券、上市融资等方式筹措资金，实施能效提升项目。 鼓励和引导创业投资基金等对节能技术研究开发加大资金支持力度，鼓励和引导社会有关方面资金通过成立产业投资基金等方式投资重点用能单位的节能改造。"},{"i":23,"n":"第二十三条","txt":"实行有利于节能的价格政策，鼓励重点用能单位开展电力需求侧管理、合同能源管理、节能自愿承诺等。 对高耗能行业的重点用能单位，结合其能耗指标等情况分别实行差别电价和阶梯电价政策。"},{"i":24,"n":"第二十四条","txt":"各级科技部门、管理节能工作的部门会同有关部门推动新型节能技术装备的研发和产业化，鼓励重点用能单位加大节能技术装备研发、产业化和应用推广力度。 国家发展和改革委员会制定《国家重点节能低碳技术推广目录》，对重点用能单位研发的节能降碳效果显著、技术先进、经济适用、有成功实施案例的技术加大宣传推广力度。地方管理节能工作的部门可结合本地实际，制定节能技术推广目录。"},{"i":25,"n":"第二十五条","txt":"对入围能效“领跑者”名单的重点用能单位，各级管理节能工作的部门会同有关部门优先支持其开展节能技术改造、能源管理信息化建设等能效提升工作，广泛宣传推广先进经验，带动行业能效水平整体提升。"},{"i":26,"n":"第二十六条","txt":"对节能管理制度不健全、节能措施不落实、能源利用效率低的重点用能单位，管理节能工作的部门应当开展现场调查，组织实施用能设备能源效率检测，责令实施能源审计，并提出书面整改要求，限期整改。重点用能单位无正当理由拒不落实整改要求或者整改没有达到要求的，由管理节能工作的部门处十万元以上三十万元以下罚款。 对节能考核结果为未完成等级的重点用能单位，拒不落实管理节能工作的部门要求实施能源审计、报送能源审计报告、提出整改措施并限期整改的，由管理节能工作的部门处一万元以上三万元以下罚款。"},{"i":27,"n":"第二十七条","txt":"重点用能单位未按照本办法规定设立能源管理岗位，指定相应的能源管理负责人并报管理节能工作的部门和有关部门备案的，由管理节能工作的部门责令改正；拒不改正的，处一万元以上三万元以下罚款。"},{"i":28,"n":"第二十八条","txt":"重点用能单位未按规定配备、使用能源计量器具的，按照《中华人民共和国节约能源法》第七十四条有关规定进行处理；拒绝、阻碍能源计量监督检查的，按照《能源计量监督管理办法》相关规定进行处理。"},{"i":29,"n":"第二十九条","txt":"重点用能单位未能按规定设置原始记录、统计台账，提供不真实或者不完整的统计资料的，按照《中华人民共和国统计法》及有关规定予以处理。"},{"i":30,"n":"第三十条","txt":"重点用能单位未按照本办法规定报送能源利用状况报告或者报告内容不实的，由管理节能工作的部门责令限期改正；逾期不改正的，处一万元以上五万元以下罚款。"},{"i":31,"n":"第三十一条","txt":"重点用能单位不按要求开展能耗在线监测系统建设和能耗在线监测工作的，由管理节能工作的部门以书面形式责令限期整改；逾期不整改的或者没有达到整改要求的，由管理节能工作的部门处一万元以上三万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"重点用能单位超过单位产品能耗限额标准用能，限期治理，逾期不治理或者没有达到治理要求的，由管理节能工作的部门提请执行惩罚性电价。"},{"i":33,"n":"第三十三条","txt":"重点用能单位不按期淘汰落后生产工艺、用能设备和产品的，由管理节能工作的部门责令停止使用，没收国家明令淘汰的用能设备，并按照《中华人民共和国循环经济促进法》有关规定处以罚款；情节严重的，由管理节能工作的部门报请本级人民政府按照国务院规定的权限责令停业整顿或者关闭。"},{"i":34,"n":"第三十四条","txt":"重点用能单位建设需经节能审查的固定资产投资项目存在以下情况的，依据《固定资产投资项目节能审查办法》有关规定予以处罚： （一）未按规定进行节能审查，或节能审查未获通过，擅自开工建设或擅自投入生产、使用的； （二）以拆分项目、提供虚假材料等不正当手段通过节能审查的； （三）未落实节能审查意见要求的。"},{"i":35,"n":"第三十五条","txt":"国家工作人员在节能管理工作中有违法违规行为的，重点用能单位有权向本级人民政府管理节能工作的部门或者上一级管理节能工作的部门投诉。 国家工作人员滥用职权、玩忽职守、徇私舞弊，有下列情形之一的，由有管理权限的机构依法给予处分；构成犯罪的，依法追究刑事责任： （一）泄露重点用能单位的技术及商业秘密的； （二）利用职务之便非法谋取利益的； （三）实施节能监察时向被监察单位收费或者变相收费的； （四）有其他违法违规行为并造成较为严重后果的。"},{"i":36,"n":"第三十六条","txt":"本办法由国家发展和改革委员会会同有关部门负责解释。"},{"i":37,"n":"第三十七条","txt":"本办法自2018年5月1日起施行。原国家经贸委1999年3月10日颁布的《重点用能单位节能管理办法》（中华人民共和国国家经济贸易委员会令第7号）同时废止。"}],"zhongdianyongnengdanweijienengguanlibanfa-3":[{"i":1,"n":"第一条","txt":"为加强重点用能单位的节能管理，提高能源利用效率，控制能源消费总量，促进生态文明建设，根据《中华人民共和国节约能源法》等有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称重点用能单位是指： （一）年综合能源消费量一万吨标准煤及以上的用能单位； （二）国务院有关部门或者省、自治区、直辖市人民政府管理节能工作的部门指定的年综合能源消费量五千吨及以上不满一万吨标准煤的用能单位。 能源消费的核算单位是法人单位。"},{"i":3,"n":"第三条","txt":"重点用能单位应当贯彻执行国家和地方有关节能的法律、法规、规章、政策和标准，按照合理用能的原则，加强节能管理，降低能源消耗，接受所在地县级以上人民政府管理节能工作的部门的管理。"},{"i":4,"n":"第四条","txt":"国家发展和改革委员会负责全国重点用能单位节能管理工作。国务院有关部门在各自的职责范围内开展重点用能单位节能管理工作。 县级以上地方各级人民政府管理节能工作的部门负责本行政区域内重点用能单位节能管理工作。县级以上地方各级人民政府有关部门在各自的职责范围内开展重点用能单位节能管理工作。 县级以上人民政府管理节能工作的部门，在开展重点用能单位节能管理工作过程中，根据本地区重点用能单位行业情况，充分发挥有关行业主管部门作用，共同推动重点用能单位节能管理工作。"},{"i":5,"n":"第五条","txt":"对重点用能单位实行节能目标责任制和节能考核评价制度。地市级以上人民政府管理节能工作的部门会同有关部门，将能耗总量控制和节能目标分解到重点用能单位，对重点用能单位分级开展节能目标责任评价考核，主要考核重点用能单位能耗总量控制和节能目标完成情况、能源利用效率及节能措施落实情况，逐级报送考核结果，并将考核结果向社会进行公布。"},{"i":6,"n":"第六条","txt":"重点用能单位应当每年制定并实施节能计划和节能措施，确保完成能耗总量控制和节能目标。节能措施应当技术上可行、经济上合理。"},{"i":7,"n":"第七条","txt":"重点用能单位应当建立健全能源管理制度，明确能源管理职责，制定能源利用全过程的管理要求或规范，确立淘汰落后、实施节能技术改造及奖惩等各方面管理机制，加强节能管理，减少能源损失，提高能源利用效率。"},{"i":8,"n":"第八条","txt":"重点用能单位应当建立节能目标责任制，根据政府管理节能工作的部门下达的能耗总量控制和节能目标任务及要求，科学评估节能潜力，合理分解目标，落实到相应层级或岗位，并定期组织内部考核。 重点用能单位应当建立节能奖惩制度，将能耗总量控制和节能目标完成情况与奖惩挂钩，对节能工作中取得突出成绩的集体和个人给予表彰和奖励，对浪费能源的集体和个人给予惩罚。"},{"i":9,"n":"第九条","txt":"重点用能单位应当按照《能源管理体系要求》等相关标准的要求，建立健全能源管理体系并使之有效运行。 县级以上人民政府管理节能工作的部门负责组织开展能源管理体系建设效果评价工作。鼓励重点用能单位开展能源管理体系认证。"},{"i":10,"n":"第十条","txt":"重点用能单位应当成立节能工作领导小组，负责人由单位主要领导担任。 重点用能单位应当聘任具有节能专业知识、实际经验以及中级以上技术职称的人员担任能源管理负责人。 重点用能单位应当明确能源管理部门，设立能源管理岗位，聘任能够满足节能工作需要的能源管理人员。能源管理人员负责贯彻执行国家有关节约能源工作的法律、法规、规章、政策和标准，加强日常节能管理，组织实施本单位内部能源审计、节能技术改造，开展能源计量和统计分析等。 重点用能单位应当将节能工作领导小组、能源管理负责人、能源管理人员报管理节能工作的部门和有关部门备案，上述信息发生变动的，应当及时将变动情况报管理节能工作的部门和有关部门备案。"},{"i":11,"n":"第十一条","txt":"重点用能单位应当按照《用能单位能源计量器具配备和管理通则》《重点用能单位能源计量审查规范》等有关规定，配备和使用经依法检定或校准的能源计量器具，加强能源计量数据的管理和使用，建立健全能源计量管理制度，完善能源计量体系，并接受质量技术监督部门开展的能源计量审查等监督检查。"},{"i":12,"n":"第十二条","txt":"重点用能单位应当按照国家有关规定设置原始记录、统计台账，建立健全统计资料的审核、签署、交接、归档等管理制度。统计资料的审核、签署人员应当对其审核、签署的统计资料的真实性、准确性和完整性负责。"},{"i":13,"n":"第十三条","txt":"重点用能单位应当由能源管理负责人负责组织能源利用状况报告填报工作，并每年向县级以上人民政府管理节能工作的部门报送上年度的能源利用状况报告。能源利用状况报告应当包括能源消费情况、能源利用效率、能耗总量控制和节能目标完成情况、节能效益分析、节能措施等内容。 县级以上人民政府管理节能工作的部门负责对重点用能单位报送的能源利用状况报告进行审查，逐级报送审查结果，将数据质量存在问题的重点用能单位作为本年度节能监察重点对象。"},{"i":14,"n":"第十四条","txt":"重点用能单位应当按照国家有关规定实施能源审计，分析现状，查找问题，挖掘节能潜力，提出切实可行的节能措施，并向县级以上人民政府管理节能工作的部门报送能源审计报告。 县级以上人民政府管理节能工作的部门对重点用能单位的能源审计报告进行审核，并指导和督促重点用能单位落实节能措施。"},{"i":15,"n":"第十五条","txt":"重点用能单位应当结合现有能源管理信息化平台，加强能源计量基础能力建设，按照政府管理节能工作的部门、质量技术监督部门要求建设能耗在线监测系统，提升能源管理信息化水平。"},{"i":16,"n":"第十六条","txt":"重点用能单位应当优先采用《国家重点节能低碳技术推广目录》以及地方发布的相关目录中的节能技术、生产工艺和用能设备，主动淘汰落后的和国家明令禁止使用的用能产品、设备和生产工艺。 重点用能单位应当每年安排一定数量资金用于节能技术研发、节能技术改造、能源计量器具配备和节能技术培训等。 鼓励重点用能单位开展产学研合作，加强节能技术研发与应用交流合作。 鼓励重点用能单位积极运用先进节能技术实施节能改造。 节能改造时涉及高耗能特种设备的，应当保障特种设备的安全性能，有关特种设备安全与节能法律、法规及规章另有规定的，从其规定。"},{"i":17,"n":"第十七条","txt":"重点用能单位应当执行单位产品能耗限额强制性国家标准和能源效率强制性国家标准。鼓励重点用能单位制定严于国家标准、行业标准、地方标准的企业节能标准。 重点用能单位应当积极开展能效对标活动，持续提升能效水平，争当本行业能效“领跑者”。鼓励各行业协会在有关部门的指导下开展本行业内能效对标活动，组织本行业重点用能单位开展能效对标，对重点用能单位能效对标活动进行跟踪指导和评估，并提供技术支持。"},{"i":18,"n":"第十八条","txt":"重点用能单位应当严格落实固定资产投资项目节能审查制度，未进行节能审查，或节能审查未通过的项目，建设单位不得开工建设，已经建成的不得投入生产、使用。"},{"i":19,"n":"第十九条","txt":"省级以上人民政府管理节能工作的部门会同有关部门可结合重点用能单位节能目标责任考核结果，对在节能工作中取得显著成绩的重点用能单位和个人给予表彰和奖励。对节能考核结果为未完成等级的重点用能单位，地市级以上人民政府管理节能工作的部门应当责令其实施能源审计、报送能源审计报告、提出整改措施并限期整改。 国务院国资委将中央企业能耗总量控制和节能目标完成情况纳入企业业绩考核范围，作为企业领导班子和领导干部综合评价考核的重要内容，建立完善问责制度，对成绩突出的单位和个人给予表彰奖励。地方国资委相应加强对重点用能单位中的地方国有企业节能目标责任考核结果运用，落实奖惩机制。"},{"i":20,"n":"第二十条","txt":"省级以上人民政府管理节能工作的部门对因在节能工作中取得显著成绩获得表彰和奖励的重点用能单位和个人，联合有关部门给予守信激励。 国家发展和改革委员会对违反本办法规定的行为建立信用记录，纳入全国信用信息共享平台，在“信用中国”网站向社会公开，对严重失信主体实施联合惩戒措施。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府管理节能工作的部门会同有关部门推动和引导社会有关方面加大对节能的资金投入，支持重点用能单位开展节能技术研究开发、节能技术和产品的示范与推广、节能改造项目实施、能源计量器具配备、节能管理能力建设、节能宣传培训等。 县级以上人民政府管理节能工作的部门会同有关部门利用节能有关专项资金支持重点用能单位实施节能重点工程时，优先支持节能目标责任评价考核成绩突出的重点用能单位。"},{"i":22,"n":"第二十二条","txt":"鼓励银行业金融机构加大对符合条件的节能产品生产、节能技术改造等节能项目的信贷投入。银行业金融机构在开展能效信贷工作中，对符合信贷条件，达到先进能效标准的固定资产和项目、节能目标责任评价考核成绩突出的重点用能单位融资需求优先支持;对达不到能效国家标准的固定资产和项目融资需求，不予支持。 鼓励重点用能单位通过发行绿色债券、上市融资等方式筹措资金，实施能效提升项目。 鼓励和引导创业投资基金等对节能技术研究开发加大资金支持力度，鼓励和引导社会有关方面资金通过成立产业投资基金等方式投资重点用能单位的节能改造。"},{"i":23,"n":"第二十三条","txt":"实行有利于节能的价格政策，鼓励重点用能单位开展电力需求侧管理、合同能源管理、节能自愿承诺等。 对高耗能行业的重点用能单位，结合其能耗指标等情况分别实行差别电价和阶梯电价政策。"},{"i":24,"n":"第二十四条","txt":"各级科技部门、管理节能工作的部门会同有关部门推动新型节能技术装备的研发和产业化，鼓励重点用能单位加大节能技术装备研发、产业化和应用推广力度。 国家发展和改革委员会制定《国家重点节能低碳技术推广目录》，对重点用能单位研发的节能降碳效果显著、技术先进、经济适用、有成功实施案例的技术加大宣传推广力度。地方管理节能工作的部门可结合本地实际，制定节能技术推广目录。"},{"i":25,"n":"第二十五条","txt":"对入围能效“领跑者”名单的重点用能单位，各级管理节能工作的部门会同有关部门优先支持其开展节能技术改造、能源管理信息化建设等能效提升工作，广泛宣传推广先进经验，带动行业能效水平整体提升。"},{"i":26,"n":"第二十六条","txt":"对节能管理制度不健全、节能措施不落实、能源利用效率低的重点用能单位，管理节能工作的部门应当开展现场调查，组织实施用能设备能源效率检测，责令实施能源审计，并提出书面整改要求，限期整改。重点用能单位无正当理由拒不落实整改要求或者整改没有达到要求的，由管理节能工作的部门处十万元以上三十万元以下罚款。 对节能考核结果为未完成等级的重点用能单位，拒不落实管理节能工作的部门要求实施能源审计、报送能源审计报告、提出整改措施并限期整改的，由管理节能工作的部门处一万元以上三万元以下罚款。"},{"i":27,"n":"第二十七条","txt":"重点用能单位未按照本办法规定设立能源管理岗位，指定相应的能源管理负责人并报管理节能工作的部门和有关部门备案的，由管理节能工作的部门责令改正;拒不改正的，处一万元以上三万元以下罚款。"},{"i":28,"n":"第二十八条","txt":"重点用能单位未按规定配备、使用能源计量器具的，按照《中华人民共和国节约能源法》第七十四条有关规定进行处理;拒绝、阻碍能源计量监督检查的，按照《能源计量监督管理办法》相关规定进行处理。"},{"i":29,"n":"第二十九条","txt":"重点用能单位未能按规定设置原始记录、统计台账，提供不真实或者不完整的统计资料的，按照《中华人民共和国统计法》及有关规定予以处理。"},{"i":30,"n":"第三十条","txt":"重点用能单位未按照本办法规定报送能源利用状况报告或者报告内容不实的，由管理节能工作的部门责令限期改正;逾期不改正的，处一万元以上五万元以下罚款。"},{"i":31,"n":"第三十一条","txt":"重点用能单位不按要求开展能耗在线监测系统建设和能耗在线监测工作的，由管理节能工作的部门以书面形式责令限期整改;逾期不整改的或者没有达到整改要求的，由管理节能工作的部门处一万元以上三万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"重点用能单位超过单位产品能耗限额标准用能，限期治理，逾期不治理或者没有达到治理要求的，由管理节能工作的部门提请执行惩罚性电价。"},{"i":33,"n":"第三十三条","txt":"重点用能单位不按期淘汰落后生产工艺、用能设备和产品的，由管理节能工作的部门责令停止使用，没收国家明令淘汰的用能设备，并按照《中华人民共和国循环经济促进法》有关规定处以罚款;情节严重的，由管理节能工作的部门报请本级人民政府按照国务院规定的权限责令停业整顿或者关闭。"},{"i":34,"n":"第三十四条","txt":"重点用能单位建设需经节能审查的固定资产投资项目存在以下情况的，依据《固定资产投资项目节能审查办法》有关规定予以处罚： （一）未按规定进行节能审查，或节能审查未获通过，擅自开工建设或擅自投入生产、使用的； （二）以拆分项目、提供虚假材料等不正当手段通过节能审查的； （三）未落实节能审查意见要求的。"},{"i":35,"n":"第三十五条","txt":"国家工作人员在节能管理工作中有违法违规行为的，重点用能单位有权向本级人民政府管理节能工作的部门或者上一级管理节能工作的部门投诉。 国家工作人员滥用职权、玩忽职守、徇私舞弊，有下列情形之一的，由有管理权限的机构依法给予处分;构成犯罪的，依法追究刑事责任： （一）泄露重点用能单位的技术及商业秘密的； （二）利用职务之便非法谋取利益的； （三）实施节能监察时向被监察单位收费或者变相收费的； （四）有其他违法违规行为并造成较为严重后果的。"},{"i":36,"n":"第三十六条","txt":"本办法由国家发展和改革委员会会同有关部门负责解释。"},{"i":37,"n":"第三十七条","txt":"本办法自2018年5月1日起施行。原国家经贸委1999年3月10日颁布的《重点用能单位节能管理办法》（中华人民共和国国家经济贸易委员会令第7号）同时废止。"}],"feichangshiqiluoshijiageganyucuoshihejinjicuoshiza6dd461-2":[{"i":1,"n":"第一条","txt":"为在非常时期及时有效地平抑市场价格波动，维护公共利益和社会稳定，依法落实国务院和省、自治区、直辖市人民政府决定实行的价格干预措施或者紧急措施，依据《价格法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在突发公共事件、严重自然灾害、战争、通货膨胀等非常时期，当重要商品和服务价格显著上涨或者有可能显著上涨，影响经济发展和国民经济正常运行时，国务院价格主管部门或者省、自治区、直辖市价格主管部门应当向本级人民政府提出实行价格干预措施的建议;当价格总水平出现剧烈波动等异常状态，影响人民生活安定和社会稳定时，国务院价格主管部门应当向国务院提出实行价格紧急措施的建议。"},{"i":3,"n":"第三条","txt":"依据《价格法》第三十条的规定，价格干预措施包括限定差价率或者利润率、规定限价、实行提价申报制度和调价备案制度。价格干预措施适用于价格显著上涨或者有可能显著上涨的实行市场调节价的商品和服务。 依据《价格法》第三十一条的规定，价格紧急措施包括临时集中定价权限、部分或者全面冻结价格。价格紧急措施适用于实行市场调节价、政府指导价和政府定价的商品和服务。"},{"i":4,"n":"第四条","txt":"实行价格干预措施或者紧急措施应当遵循经济规律，在做好非常时期商品的生产、调运和供应的组织工作的前提下，必要时可以采取价格干预措施或者紧急措施。 落实价格干预措施或者紧急措施时，价格主管部门应当合理确定实施的地区、品种，把握好时机和力度，有利于促进相关商品正常生产、流通和相关服务的正常提供，有利于保持社会稳定。"},{"i":5,"n":"第五条","txt":"国务院或者省、自治区、直辖市人民政府作出实行价格干预措施或者紧急措施的决定后，同级人民政府价格主管部门应当按照国务院或者省、自治区、直辖市人民政府的决定，及时向社会公告实施价格干预措施或者紧急措施的具体范围和有关政策。"},{"i":6,"n":"第六条","txt":"国务院价格主管部门负责全国范围内价格干预措施或者紧急措施的落实。 对符合《价格法》第三十条有关规定的，国务院价格主管部门应当及时指导有关地方价格主管部门落实价格干预措施。 省、自治区、直辖市价格主管部门，负责价格干预措施或者紧急措施在本行政区域范围内的落实。"},{"i":7,"n":"第七条","txt":"价格主管部门对纳入价格干预措施或者紧急措施范围的商品和服务，以及可能波及的相关商品和服务，应当加强市场供求情况和价格监测，建立畅通的信息渠道，及时将市场供求和价格的监测结果上报本级人民政府和上一级价格主管部门;市场价格有可能出现异常波动时，要及时做出预警。"},{"i":8,"n":"第八条","txt":"价格主管部门应当做好价格干预措施、紧急措施的宣传工作，及时向社会公布市场供求、价格信息，引导经营者遵守价格法律、法规和政策。"},{"i":9,"n":"第九条","txt":"价格主管部门在落实价格干预措施或者紧急措施时期，应当依法打击不执行价格干预措施和紧急措施的行为。应当加强价格举报值班工作，认真受理和及时查处群众的投诉举报，依法打击哄抬价格、价格欺诈、价格垄断、变相涨价等行为，确保价格干预措施或者紧急措施的实施。"},{"i":10,"n":"第十条","txt":"地方价格主管部门应当及时向本级人民政府和上一级价格主管部门报告干预措施或者紧急措施的执行情况。"},{"i":11,"n":"第十一条","txt":"经营者不执行价格干预措施、紧急措施的，责令改正，没收违法所得，可以并处违法所得五倍以下的罚款;没有违法所得的，可以处四万元以上四十万元以下的罚款;情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照;构成犯罪的，移交司法机关追究刑事责任。"},{"i":12,"n":"第十二条","txt":"价格主管部门在进行价格监督检查过程中，必要时可以采取责令当事人暂停相关营业、公告价格违法行为、公开曝光典型案件等措施。对拒绝按照规定提供价格监督检查所需资料或者提供虚假资料的，责令改正、予以警告;逾期不改正的，可以处以五万元以下的罚款。"},{"i":13,"n":"第十三条","txt":"地方各级人民政府或者各级人民政府有关部门不执行法定的价格干预措施、紧急措施的，由上级人民政府或者政府价格主管部门责令改正，并可以通报批评;对直接负责的主管人员和其他直接责任人，由政府价格主管部门建议有权部门依法给予行政处分。"},{"i":14,"n":"第十四条","txt":"价格主管部门工作人员在落实价格干预措施或者紧急措施期间失职、渎职的，应当依法追究直接负责的主管人员和其他直接责任人的责任。"},{"i":15,"n":"第十五条","txt":"依据《价格法》第三十二条的规定，引起价格总水平剧烈波动或者商品和服务价格显著上涨的因素消除后，国务院价格主管部门或者省、自治区、直辖市价格主管部门应当按照有关程序和权限，建议本级人民政府及时解除价格干预或者紧急措施，并对社会公告。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市价格主管部门可以根据本办法制定预案。"},{"i":17,"n":"第十七条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自2004年1月1日起实施。"}],"feichangshiqiluoshijiageganyucuoshihejinjicuoshiza6dd461":[{"i":1,"n":"第一条","txt":"为在非常时期及时有效地平抑市场价格波动，维护公共利益和社会稳定，依法落实国务院和省、自治区、直辖市人民政府决定实行的价格干预措施或者紧急措施，依据《价格法》制定本办法。"},{"i":2,"n":"第二条","txt":"在突发公共事件、严重自然灾害、战争、通货膨胀等非常时期，当重要商品和服务价格显著上涨或者有可能显著上涨，影响经济发展和国民经济正常运行时，国务院价格主管部门或者省、自治区、直辖市价格主管部门应当向本级人民政府提出实行价格干预措施的建议；当价格总水平出现剧烈波动等异常状态，影响人民生活安定和社会稳定时，国务院价格主管部门应当向国务院提出实行价格紧急措施的建议。"},{"i":3,"n":"第三条","txt":"依据《价格法》第三十条的规定，价格干预措施包括限定差价率或者利润率、规定限价、实行提价申报制度和调价备案制度。价格干预措施适用于价格显著上涨或者有可能显著上涨的实行市场调节价的商品和服务。 依据《价格法》第三十一条的规定，价格紧急措施包括临时集中定价权限、部分或者全面冻结价格。价格紧急措施适用于实行市场调节价、政府指导价和政府定价的商品和服务。"},{"i":4,"n":"第四条","txt":"实行价格干预措施或者紧急措施应当遵循经济规律，在做好非常时期商品的生产、调运和供应的组织工作的前提下，必要时可以采取价格干预措施或者紧急措施。 落实价格干预措施或者紧急措施时，价格主管部门应当合理确定实施的地区、品种，把握好时机和力度，有利于促进相关商品正常生产、流通和相关服务的正常提供，有利于保持社会稳定。"},{"i":5,"n":"第五条","txt":"国务院或者省、自治区、直辖市人民政府作出实行价格干预措施或者紧急措施的决定后，同级人民政府价格主管部门应当按照国务院或者省、自治区、直辖市人民政府的决定，及时向社会公告实施价格干预措施或者紧急措施的具体范围和有关政策。"},{"i":6,"n":"第六条","txt":"国务院价格主管部门负责全国范围内价格干预措施或者紧急措施的落实。 对符合《价格法》第三十条有关规定的，国务院价格主管部门应当及时指导有关地方价格主管部门落实价格干预措施。 省、自治区、直辖市价格主管部门，负责价格干预措施或者紧急措施在本行政区域范围内的落实。"},{"i":7,"n":"第七条","txt":"价格主管部门对纳入价格干预措施或者紧急措施范围的商品和服务，以及可能波及的相关商品和服务，应当加强市场供求情况和价格监测，建立畅通的信息渠道，及时将市场供求和价格的监测结果上报本级人民政府和上一级价格主管部门；市场价格有可能出现异常波动时，要及时做出预警。"},{"i":8,"n":"第八条","txt":"价格主管部门应当做好价格干预措施、紧急措施的宣传工作，及时向社会公布市场供求、价格信息，引导经营者遵守价格法律、法规和政策。"},{"i":9,"n":"第九条","txt":"价格主管部门在落实价格干预措施或者紧急措施时期，应当依法打击不执行价格干预措施和紧急措施的行为。应当加强价格举报值班工作，认真受理和及时查处群众的投诉举报，依法打击哄抬价格、价格欺诈、价格垄断、变相涨价等行为，确保价格干预措施或者紧急措施的实施。"},{"i":10,"n":"第十条","txt":"地方价格主管部门应当及时向本级人民政府和上一级价格主管部门报告干预措施或者紧急措施的执行情况。"},{"i":11,"n":"第十一条","txt":"经营者不执行价格干预措施、紧急措施的，责令改正，没收违法所得，可以并处违法所得五倍以下的罚款；没有违法所得的，可以处四万元以上四十万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照；构成犯罪的，移交司法机关追究刑事责任。"},{"i":12,"n":"第十二条","txt":"价格主管部门在进行价格监督检查过程中，必要时可以采取责令当事人暂停相关营业、公告价格违法行为、公开曝光典型案件等措施。对拒绝按照规定提供价格监督检查所需资料或者提供虚假资料的，责令改正、予以警告；逾期不改正的，可以处以五万元以下的罚款。"},{"i":13,"n":"第十三条","txt":"地方各级人民政府或者各级人民政府有关部门不执行法定的价格干预措施、紧急措施的，由上级人民政府或者政府价格主管部门责令改正，并可以通报批评；对直接负责的主管人员和其他直接责任人，由政府价格主管部门建议有权部门依法给予行政处分。"},{"i":14,"n":"第十四条","txt":"价格主管部门工作人员在落实价格干预措施或者紧急措施期间失职、渎职的，应当依法追究直接负责的主管人员的责任和其他责任人的责任。"},{"i":15,"n":"第十五条","txt":"依据《价格法》第三十二条的规定，引起价格总水平剧烈波动或者商品和服务价格显著上涨的因素消除后，国务院价格主管部门或者省、自治区、直辖市价格主管部门应当按照有关程序和权限，建议本级人民政府及时解除价格干预或者紧急措施，并对社会公告。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市价格主管部门可以根据本办法制定预案。"},{"i":17,"n":"第十七条","txt":"本办法由国家发展和改革委员会负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自2004年1月1日起实施。"}],"guliwaishangtouzichanyemulu-2":[],"guliwaishangtouzichanyemulu":[]};
